package com.matthewmariner.livelycities;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * The one overlay that draws citizens' overhead text.
 *
 * <p><b>One overlay, and it derives everything from the live entity set every
 * frame.</b> That is the structural fix for two of the predecessor's bug classes
 * at once — text floating with nobody under it, and text drifting off the citizen
 * it belonged to. Both were symptoms of the same thing: a renderer with its own
 * list of what to draw and its own idea of where. There is no such list here.
 * Each frame this walks {@link EntityScene#inScopeEntities()}, skips anything the
 * client does not have registered, asks the entity what it is saying, and projects
 * the position the client is about to draw the model at. An entity that despawned
 * one frame ago is simply not in the loop's output, so its text is gone on the
 * next frame rather than when something remembers to remove it.
 *
 * <p><b>{@code Actor.setOverheadText} is not available and could not be.</b> A
 * {@code RuneLiteObject} is not an {@code Actor} — it has no overhead text, no
 * health bar and no native menu — so screen-space drawing is the only option, and
 * it is what the hub-merged precedents do.
 *
 * <p><b>Projection is allowed to fail, and failing must draw nothing.</b>
 * {@code Perspective.getCanvasTextLocation} returns null for a citizen behind the
 * camera, off the edge of the viewport, or on a world view the client no longer
 * has — all three of which happen constantly and none of which is an error. Every
 * one of them is a {@code continue}. This runs once per frame per talking citizen,
 * so a throw here would be a stack trace sixty times a second <i>and</i> would
 * abandon every citizen after the offender on every one of them, which is the same
 * reasoning behind the containment in {@link EntityScene}.
 *
 * <p><b>The hard off switch is checked here as well as in
 * {@link CitizenChatter}.</b> Not belt-and-braces: the chatter clears its state on
 * its next game tick, up to 600ms away, and a toggle that visibly lags the click
 * reads as a toggle that did not work. Checking it here is what makes unticking the
 * box silence the screen on the same frame.
 *
 * <p><b>Kept minimal, because it runs every frame.</b> No sorting, no allocation
 * per entity beyond the {@code LocalPoint} the client's own API hands back, and no
 * work at all for the common case of a citizen with nothing to say — which is 215
 * of the 269 shipped citizens, and most of the remaining 54 most of the time.
 */
class ChatterOverlay extends Overlay
{
	/**
	 * How far above the citizen's tile the text sits, in local units
	 * ({@link Perspective#LOCAL_TILE_SIZE} = 128 per tile).
	 *
	 * <p>A constant rather than the model's own height. {@code Model} in 1.12.36
	 * exposes {@code getBottomY()} and an {@code AABB}, neither of which is a
	 * documented "how tall is this" and both of which need a live, lit model to mean
	 * anything; {@code Actor.getLogicalHeight()}, which is what RuneLite's own actor
	 * overlays use, does not exist on a {@code RuneLiteObject}. Every citizen in the
	 * dataset is a human-scale single-tile model, so one number that clears a head
	 * is both honest and right. Scenery never talks.
	 */
	static final int TEXT_HEIGHT = 220;

	private final Client client;
	private final EntityScene scene;
	private final LivelyCitiesConfig config;

	@Inject
	ChatterOverlay(LivelyCitiesPlugin plugin, Client client, EntityScene scene, LivelyCitiesConfig config)
	{
		super(plugin);
		this.client = client;
		this.scene = scene;
		this.config = config;

		// ABOVE_SCENE so the text sits over the world but under the interface — the
		// same layer RuneLite's own world-space text overlays use. DYNAMIC because
		// there is no box to drag: the position comes from the citizens.
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);

		// Below everything that is actually telling the user something. This is
		// ambience; it must never end up drawn over a warning.
		setPriority(Overlay.PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.overheadText())
		{
			// The hard off switch, upstream issue #35. Checked first so that "off"
			// costs one field read per frame.
			return null;
		}

		final List<LivelyEntity> entities = scene.inScopeEntities();
		for (int i = 0; i < entities.size(); i++)
		{
			LivelyEntity entity = entities.get(i);

			CitizenRemarks remarks = entity.getRemarks();
			if (remarks == null || !remarks.isTalking())
			{
				continue;
			}

			// Asked of the client, not of local bookkeeping: this is what makes a
			// despawned citizen's text disappear on the next frame rather than on
			// the next tick.
			if (!entity.isActive())
			{
				continue;
			}

			LocalPoint at = entity.getRenderLocation();
			if (at == null)
			{
				continue;
			}

			String text = remarks.text();
			if (text == null)
			{
				// isTalking() and text() are the same field; this is here so the
				// null-check the compiler wants is honest rather than an assertion
				// about ordering.
				continue;
			}

			Point on = textLocation(graphics, at, text);
			if (on == null)
			{
				// Behind the camera, off the viewport, or on a world view that has
				// gone. Not an error; draw nothing.
				continue;
			}

			drawRemark(graphics, on, text);
		}

		return null;
	}

	/**
	 * Projects a citizen's position to the screen.
	 *
	 * <p>Package-private and non-final so a test can stand in for it — the real
	 * implementation reads the live camera through
	 * {@code Perspective.localToCanvas}, and this repo has no mocking framework and
	 * does not use reflection. Everything the tests care about — which citizens are
	 * considered, and what happens when this returns null — is on this side of the
	 * seam.
	 *
	 * @return the canvas point, or {@code null} if the citizen cannot be drawn
	 */
	@Nullable
	Point textLocation(Graphics2D graphics, LocalPoint at, String text)
	{
		return Perspective.getCanvasTextLocation(client, graphics, at, text, TEXT_HEIGHT);
	}

	/**
	 * Draws one remark. Package-private and non-final for the same reason as
	 * {@link #textLocation}.
	 */
	void drawRemark(Graphics2D graphics, Point at, String text)
	{
		// The same colour as the menu targets, so overhead text is one more place
		// that says "this is not a real NPC" — see CitizenLabel.
		OverlayUtil.renderTextLocation(graphics, at, text, CitizenLabel.FAKE_COLOUR);
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Constants;
import net.runelite.api.coords.WorldPoint;

/**
 * Decides who is saying something, and for how long.
 *
 * <p><b>The off switches were built before the feature, on purpose.</b> Overhead
 * text was the predecessor's single loudest complaint — 144 upvotes on "please add
 * an option to shut them up", a mute toggle its author promised and never shipped,
 * and upstream issue #35 still open on release day plus a year. So the dials are
 * not a follow-up to this class; they are its parameters, and every one of them is
 * consulted on every pass:
 *
 * <ul>
 *   <li>{@link LivelyCitiesConfig#overheadText()} — the hard off switch. False
 *       means no rolls at all <i>and</i> every remark already up is cleared, so
 *       turning it off is silence now rather than silence when the last dwell
 *       expires.</li>
 *   <li>{@link CitizenOverrides} — the per-citizen mute, at the granularity people
 *       actually complained at.</li>
 *   <li>{@link LivelyCitiesConfig#remarkIntervalTicks()} and
 *       {@link LivelyCitiesConfig#remarkDwellTicks()} — the cadence.</li>
 *   <li>{@link LivelyCitiesConfig#chatterRadius()} — the distance limit.</li>
 *   <li>{@link LivelyCitiesConfig#maxConcurrentRemarks()} — the cap that stops a
 *       crowd becoming a wall of text.</li>
 * </ul>
 *
 * <p><b>The defaults are the predecessor's timings converted into this plugin's
 * clock</b>, which is the one thing about its chatter that was reported as feeling
 * right: a chance once a minute, only within 15 tiles, a remark readable for a few
 * seconds. Its numbers were <i>not</i> in the same units as ours and the conversion
 * is written out on each constant below — see {@link #DEFAULT_ROLL_INTERVAL_TICKS}
 * and {@link #DEFAULT_DWELL_TICKS}, and {@link #effectiveDwellTicks} for the clamp
 * that makes a saturating combination unreachable however the numbers are edited.
 * What is new is that all four are dials, that there is a cap at all, and that the
 * roll is a per-citizen chance rather than a certainty.
 *
 * <p><b>The pass order is deliberate.</b> Expire, then count, then roll, then
 * admit nearest-first up to the cap. Expiring first means a citizen whose remark
 * ends on the same tick another wants to start does not block it; admitting
 * nearest-first means the cap sheds the far edge of a crowd rather than whichever
 * citizen the region file happened to list last — the same rule
 * {@link EntityScene#updateVisibility} uses for the object cap, for the same
 * reason.
 *
 * <p><b>The clock is the game tick and nothing else.</b> {@link #onGameTick} is
 * called from {@link EntityScene#onGameTick} and from nowhere else;
 * {@link #onSettingsChanged} exists so a settings change can take effect at once
 * <i>without</i> advancing it. RuneLite posts one {@code ConfigChanged} per key, so
 * switching profiles posts one per item this plugin owns — and a chatter clock that
 * advanced on those would run cadence at about thirty times speed for a moment,
 * which is the same bug the walkers already had and which is why
 * {@code onSettingsChanged} exists on the scene at all.
 *
 * <p><b>Client-thread-free.</b> Nothing here touches the client; it reads
 * {@link LivelyEntity#isActive()}, which does, so callers are on the client thread
 * anyway.
 */
@Slf4j
final class CitizenChatter
{
	/**
	 * Milliseconds in one game tick: {@link Constants#GAME_TICK_LENGTH}, 600.
	 *
	 * <p>Named here, and used in the arithmetic below rather than in prose, because
	 * every timing constant in this class is a wall-clock duration expressed in game
	 * ticks and <b>the units are exactly what got this wrong once already</b>. The
	 * client's other clock is the <i>client</i> tick,
	 * {@link Constants#CLIENT_TICK_LENGTH} = 20ms — thirty of them to a game tick —
	 * and reading one figure as the other is a thirtyfold error in a number nobody
	 * looks at twice.
	 */
	static final int TICK_MILLIS = Constants.GAME_TICK_LENGTH;

	/**
	 * Game ticks between a citizen's chances to say something: 100, i.e. one minute.
	 *
	 * <p><b>Converted from the predecessor's cadence, not copied from it.</b> Its
	 * roll interval was 60 <b>wall-clock seconds</b>, which is
	 * {@code 60000 / 600 = 100} of this plugin's game ticks. An earlier revision
	 * shipped the bare figure {@code 60} as game ticks — 36 seconds — which is the
	 * interval half of the unit error described on {@link #DEFAULT_DWELL_TICKS}.
	 */
	static final int DEFAULT_ROLL_INTERVAL_TICKS = 60_000 / TICK_MILLIS;

	/** The tightest cadence worth offering: once every 10 ticks, i.e. 6 seconds. */
	static final int MIN_ROLL_INTERVAL_TICKS = 10;

	/**
	 * The loosest: once every 600 ticks, i.e. six minutes. Past this the feature is
	 * indistinguishable from the hard off switch, which already exists — a dial
	 * whose far end duplicates another control is a dial that misleads.
	 */
	static final int MAX_ROLL_INTERVAL_TICKS = 600;

	/**
	 * How long a remark stays on screen: 8 game ticks, i.e. 4.8 seconds.
	 *
	 * <p><b>This is the constant the unit error landed on.</b> The predecessor's
	 * dwell was 120 <b>client</b> ticks —
	 * {@code 120 * 20ms} = 2.4 seconds — and it shipped here as 120 <b>game</b>
	 * ticks, {@code 120 * 600ms} = 72 seconds: exactly thirty times too long,
	 * because that is the ratio of the two clocks. Worse than long, it was longer
	 * than the roll interval it shipped beside (36 seconds), so a bubble could never
	 * expire before its citizen's next chance to speak and the overhead text
	 * saturated permanently — which is the one complaint this whole feature exists to
	 * answer.
	 *
	 * <p><b>Where 8 comes from.</b> Not from the 2.4-second conversion, which is the
	 * predecessor's number and is too short to read: the longest line in the shipped
	 * dataset is 11 words, which needs about 3.3 seconds at an unhurried 200 words a
	 * minute, and a bubble that appears while the player is looking somewhere else
	 * needs a second or so on top before anybody starts reading it. Call it 4.8
	 * seconds, i.e. {@code 4800 / 600} = 8 game ticks. The median shipped line is 5
	 * words, so the typical remark is up for roughly twice as long as it takes to
	 * read. It is 8% of {@link #DEFAULT_ROLL_INTERVAL_TICKS}, which is what
	 * "comfortably shorter than the interval" means here.
	 */
	static final int DEFAULT_DWELL_TICKS = 4_800 / TICK_MILLIS;

	/**
	 * The shortest dwell worth offering: 5 ticks, 3 seconds. Below this the longest
	 * shipped remark is off the screen before it can be read.
	 */
	static final int MIN_DWELL_TICKS = 5;

	/**
	 * The longest: 30 ticks, 18 seconds.
	 *
	 * <p>A judgement, and a much smaller one than it used to be. 18 seconds is over
	 * five times what the longest shipped line needs, which covers anyone who reads
	 * slowly or wants to screenshot it; past that a bubble stops reading as somebody
	 * saying something and starts reading as a label stuck to their head. The
	 * previous ceiling was 600 ticks — six minutes — which was only ever plausible
	 * while these numbers were being read as client ticks.
	 *
	 * <p>It is deliberately still <i>above</i> {@link #MIN_ROLL_INTERVAL_TICKS}, so
	 * the pair {@code (dwell 30, interval 10)} remains something a user can ask for
	 * and {@link #effectiveDwellTicks} remains a clamp that really fires rather than
	 * unreachable code.
	 */
	static final int MAX_DWELL_TICKS = 30;

	/**
	 * Tiles from the player inside which a citizen may start talking: 15, the
	 * predecessor's figure and comfortably inside the default 25-tile cull radius,
	 * so the citizens that talk are the ones a player is actually standing among.
	 */
	static final int DEFAULT_RADIUS_TILES = 15;

	static final int MIN_RADIUS_TILES = 1;

	/**
	 * Remarks on screen at once: 3.
	 *
	 * <p>This is the number that stops "ambience" being "a wall of text", and it is
	 * the guard that holds whatever the cadence dials are set to. Varrock square
	 * holds 40 citizens inside a 25-tile square; at the tightest cadence the dials
	 * allow — a 10-tick roll and the 9-tick dwell {@link #effectiveDwellTicks} leaves
	 * of it — a {@link #REMARK_CHANCE_PERCENT} chance puts about nine bubbles on
	 * screen at once without a cap, and the saturating combination this class used to
	 * default to put every one of those 40 up and left them there. Three is the
	 * number that makes both of those the same, bounded thing.
	 */
	static final int DEFAULT_MAX_CONCURRENT = 3;

	static final int MIN_MAX_CONCURRENT = 1;

	/** The most bubbles the dial will allow, for anyone who wants a market square. */
	static final int MAX_MAX_CONCURRENT = 12;

	/**
	 * The chance, in percent, that an eligible citizen says something on its due
	 * tick.
	 *
	 * <p>Not a dial: the two things a user actually wants to control are how often
	 * they get a chance ({@code remarkIntervalTicks}) and how many can be on screen
	 * ({@code maxConcurrentRemarks}), and a third multiplier interacting with both
	 * would make neither predictable. A quarter, so a citizen with something to say
	 * speaks roughly once every four intervals — about once every four minutes at the
	 * default one-minute cadence.
	 */
	static final int REMARK_CHANCE_PERCENT = 25;

	private final LivelyCitiesConfig config;
	private final CitizenOverrides overrides;

	/**
	 * Game ticks since this chatter started. Its own counter rather than
	 * {@code client.getTickCount()} so the class stays client-free and so the
	 * cadence restarts cleanly on a scene invalidation instead of inheriting a
	 * phase from before the player logged in.
	 */
	private int tick;

	/**
	 * Reused between passes so the per-tick allocation is one growable list rather
	 * than one per pass. The pass runs every game tick over every entity in scope.
	 */
	private final List<LivelyEntity> candidates = new ArrayList<>();

	CitizenChatter(LivelyCitiesConfig config, CitizenOverrides overrides)
	{
		this.config = config;
		this.overrides = overrides;
	}

	/**
	 * One game tick of chatter.
	 *
	 * @param entities       the entities in scope — the live list, filtered here on
	 *                       {@link LivelyEntity#isActive()} so a citizen that is not
	 *                       on screen cannot be talking
	 * @param playerLocation the local player's tile, never null
	 * @return how many remarks are on screen when this returns
	 */
	int onGameTick(List<LivelyEntity> entities, WorldPoint playerLocation)
	{
		tick++;

		if (!config.overheadText())
		{
			// The hard off switch. Clearing rather than merely not rolling is the
			// difference between "off" and "off in two minutes".
			silence(entities);
			return 0;
		}

		int interval = effectiveIntervalTicks(config.remarkIntervalTicks());
		int dwell = effectiveDwellTicks(config.remarkDwellTicks(), config.remarkIntervalTicks());
		int radius = clamp(config.chatterRadius(), MIN_RADIUS_TILES, RenderPolicy.MAX_CULL_RADIUS);
		int cap = clamp(config.maxConcurrentRemarks(), MIN_MAX_CONCURRENT, MAX_MAX_CONCURRENT);

		Set<UUID> muted = overrides.mutedUuids();

		int talking = 0;
		candidates.clear();

		for (int i = 0; i < entities.size(); i++)
		{
			LivelyEntity entity = entities.get(i);
			CitizenRemarks remarks = entity.getRemarks();
			if (remarks == null)
			{
				continue;
			}

			if (!entity.isActive())
			{
				// Not on screen. despawn() already cleared any remark; this is the
				// belt to that braces, and it costs a field read.
				remarks.clear();
				continue;
			}

			// Expire before counting: a remark ending this tick must not hold a slot
			// against a remark starting this tick.
			remarks.expire(tick);

			if (remarks.isTalking())
			{
				talking++;
				continue;
			}

			if (muted.contains(entity.getDefinition().getUuid()))
			{
				continue;
			}

			if (!remarks.dueAt(tick, interval))
			{
				continue;
			}

			// Measured from the authored tile, the same anchor the cull check uses,
			// so "near enough to talk" and "near enough to render" are the same kind
			// of question. A wandering citizen can be up to
			// RenderPolicy.DATASET_OVERHANG_ALLOWANCE tiles from it; deriving this
			// from the live position instead would make a citizen start and stop
			// being eligible mid-stride.
			if (RenderPolicy.tileDistance(playerLocation, entity.getDefinition().getWorldLocation()) > radius)
			{
				continue;
			}

			// Rolled for every eligible citizen, before the cap — see
			// CitizenRemarks.rolls.
			if (remarks.rolls(REMARK_CHANCE_PERCENT))
			{
				candidates.add(entity);
			}
		}

		if (candidates.isEmpty() || talking >= cap)
		{
			return talking;
		}

		// Nearest first, so the cap sheds the far edge of the crowd.
		candidates.sort(Comparator.comparingInt(
			e -> RenderPolicy.tileDistance(playerLocation, e.getDefinition().getWorldLocation())));

		int started = 0;
		for (int i = 0; i < candidates.size() && talking < cap; i++)
		{
			CitizenRemarks remarks = candidates.get(i).getRemarks();
			if (remarks == null)
			{
				continue;
			}
			remarks.say(tick, dwell);
			talking++;
			started++;
		}

		if (started > 0 && log.isDebugEnabled())
		{
			log.debug("chatter: {} remark(s) started, {} wanted to, {} on screen of at most {}",
				started, candidates.size(), talking, cap);
		}

		return talking;
	}

	/**
	 * Re-applies the hard off switch without advancing the clock.
	 *
	 * <p>Called from {@link EntityScene#onSettingsChanged} so that unticking
	 * "Overhead chatter" clears the bubbles on the click rather than on the next
	 * game tick. It deliberately does nothing else: a settings change is not a
	 * tick, and starting a remark here would let a user produce chatter by dragging
	 * a slider.
	 */
	void onSettingsChanged(List<LivelyEntity> entities)
	{
		if (!config.overheadText())
		{
			silence(entities);
		}
	}

	/**
	 * Forgets the cadence. Called when the scene is invalidated or torn down, so a
	 * fresh login starts a fresh phase rather than inheriting one from the last
	 * world.
	 */
	void reset()
	{
		tick = 0;
		candidates.clear();
	}

	/** @return the chatter clock, for tests and log lines */
	int getTick()
	{
		return tick;
	}

	/**
	 * The roll interval this class will actually use for a configured value.
	 *
	 * @param requested whatever the config holds, from the slider or from a
	 *                  hand-edited profile
	 * @return the value inside {@link #MIN_ROLL_INTERVAL_TICKS} ..
	 * {@link #MAX_ROLL_INTERVAL_TICKS}, so {@link CitizenRemarks#dueAt} can never be
	 * handed a zero to take a modulo of
	 */
	static int effectiveIntervalTicks(int requested)
	{
		return clamp(requested, MIN_ROLL_INTERVAL_TICKS, MAX_ROLL_INTERVAL_TICKS);
	}

	/**
	 * The dwell this class will actually use, which depends on the interval.
	 *
	 * <p><b>A dwell at least as long as the interval saturates the screen, so it is
	 * not merely a bad setting — it is an unreachable one.</b> The pass expires a
	 * remark before it asks whether the citizen is due, so at {@code dwell == interval}
	 * a citizen that keeps rolling successfully is never silent for a single tick, and
	 * above it the bubble is still up when the next roll comes round and the text
	 * never clears at all. That is precisely the state this plugin's headline feature
	 * exists to prevent, and it shipped as the default once already, so the guard
	 * lives here rather than in the range of either slider: both values also arrive
	 * from a hand-edited {@code settings.properties} and from a profile synced off
	 * another install, and neither {@code @Range} can see the other's value.
	 *
	 * <p>One tick of silence is the least it can subtract and still be honest, so
	 * that is what it subtracts; the shipped defaults are nowhere near the clamp
	 * (8 of 100). {@link #MIN_ROLL_INTERVAL_TICKS} is 10, so the clamped value can
	 * never fall below {@link #MIN_DWELL_TICKS} — {@code CitizenChatterTest} asserts
	 * that relationship rather than leaving it as a comment.
	 *
	 * @return a dwell inside {@link #MIN_DWELL_TICKS} .. {@link #MAX_DWELL_TICKS}
	 * that is also strictly less than {@link #effectiveIntervalTicks(int)} of
	 * {@code requestedInterval}
	 */
	static int effectiveDwellTicks(int requestedDwell, int requestedInterval)
	{
		int interval = effectiveIntervalTicks(requestedInterval);
		int dwell = clamp(requestedDwell, MIN_DWELL_TICKS, MAX_DWELL_TICKS);
		return Math.min(dwell, interval - 1);
	}

	private static void silence(List<LivelyEntity> entities)
	{
		for (int i = 0; i < entities.size(); i++)
		{
			CitizenRemarks remarks = entities.get(i).getRemarks();
			if (remarks != null)
			{
				remarks.clear();
			}
		}
	}

	/**
	 * {@code @Range} only constrains the slider. The value also arrives from a
	 * hand-edited {@code settings.properties} and from a profile synced off another
	 * install, so the clamp lives here where every read goes through it — the same
	 * reasoning as {@link RenderPolicy#clampCullRadius(int)}.
	 */
	private static int clamp(int requested, int min, int max)
	{
		return Math.max(min, Math.min(max, requested));
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Who each shipped uuid <i>is</i>, and how many citizens each place holds — the two
 * questions the live scene cannot answer.
 *
 * <p><b>Why it exists.</b> Hiding and muting are stored as bare uuids
 * ({@link CitizenOverrides}), and {@link EntityScene} can only put a name to one while
 * its region is in the loaded scene. So the moment you walk away from somebody you
 * hid, the plugin knows only that <i>a</i> uuid is hidden. The undo that ships in the
 * config screen is "unhide all", which needs no names; a list you can restore one row
 * from does, and the row that reads "Bob the Jagex Mod — Varrock" is the difference
 * between a repair and a wall of hexadecimal.
 *
 * <p><b>Client-free, and that is deliberate rather than incidental.</b> Everything
 * here comes out of the classpath through {@link RegionDataLoader} and
 * {@link CitizenEcho}, neither of which touches the client, so the whole index can be
 * built and asserted without a game running — and so the panel's rows are a fact about
 * the jar rather than about what happens to be on screen.
 *
 * <p><b>Two tiers, and the second is usually never built.</b>
 * <ul>
 *   <li><b>Authored.</b> Parse the 27 shipped region files: 269 citizens, their names,
 *       and the {@link City} each belongs to. This is also where the per-city counts
 *       come from, so a card that says "24 citizens" is counting the dataset rather
 *       than quoting a number somebody typed.</li>
 *   <li><b>Derived.</b> Re-run {@link CitizenEcho#echoesOfRegion} over each region's
 *       roster to learn the echoes' uuids. Echoes exist only at
 *       {@link CrowdDensity#CROWDED} but they are hideable like anybody else, so a
 *       hidden uuid really can be one — and the derivation costs more than the parse
 *       it follows. It is therefore built on the first uuid the authored tier cannot
 *       place and not before, which for the overwhelming majority of profiles is
 *       never.</li>
 * </ul>
 *
 * <p><b>Muted uuids never reach the second tier</b>, and that is structural rather
 * than lucky: {@code CitizenMenu} only offers "Mute" to an entity with remarks, and
 * {@code EntityDefinition.echoOf} gives every echo the empty remarks array. An echo
 * cannot be muted because it has nothing to say.
 *
 * <p><b>Nothing here is cleared on teardown, unlike every cache in
 * {@link EntityScene}.</b> Those hold wrappers, lit models and objects the client has
 * registered — things a teardown exists to let go of. This holds strings and ints
 * decoded from resources inside the running jar, which cannot change while the client
 * is up and which no scene points at. Dropping it would only mean paying the parse
 * again the next time the plugin is enabled.
 */
@Slf4j
@Singleton
class CitizenDirectory
{
	private final RegionDataLoader loader;

	/** Authored citizens by uuid. Null until the first question is asked. */
	@Nullable
	private Map<UUID, Entry> authored;

	/** Citizens per city, from the same pass that fills {@link #authored}. */
	@Nullable
	private Map<City, Integer> counts;

	/**
	 * Echo uuids, built only when {@link #authored} cannot place one — see the class
	 * javadoc. Null means "not built"; an empty map after a build is a legitimate
	 * answer and is why this is not tracked by emptiness.
	 */
	@Nullable
	private Map<UUID, Entry> derived;

	@Inject
	CitizenDirectory(RegionDataLoader loader)
	{
		this.loader = loader;
	}

	/**
	 * @return how many citizens the shipped dataset places in this city — scenery
	 * excluded, echoes excluded. The number on a city card.
	 */
	int citizenCount(City city)
	{
		Integer n = index().get(city);
		return n == null ? 0 : n;
	}

	/**
	 * @return who this uuid is, or {@code null} if no shipped record and no derivable
	 * echo carries it. Null is reachable in practice: a profile can hold a uuid from a
	 * place the dataset used to cover — fifteen were dropped on 2026-08-24 — and the
	 * panel says so rather than inventing a name.
	 */
	@Nullable
	Entry find(UUID uuid)
	{
		Entry entry = authoredIndex().get(uuid);
		if (entry != null)
		{
			// The common case, and the one that must not pay for the tier below: an
			// ordinary profile's overrides are all authored citizens.
			return entry;
		}

		return echoIndex().get(uuid);
	}

	/** @return how many authored citizens are indexed. For the tests. */
	int size()
	{
		return authoredIndex().size();
	}

	/**
	 * @return whether the echo tier has been built. Nothing in the plugin reads this;
	 * it is how {@code CitizenDirectoryTest} asserts that an ordinary profile never
	 * pays for it, which is a claim about cost that no count of results could make.
	 */
	boolean hasBuiltEchoIndex()
	{
		return derived != null;
	}

	private Map<City, Integer> index()
	{
		buildAuthored();
		return counts;
	}

	private Map<UUID, Entry> authoredIndex()
	{
		buildAuthored();
		return authored;
	}

	private void buildAuthored()
	{
		if (authored != null)
		{
			return;
		}

		Map<UUID, Entry> byUuid = new HashMap<>();
		Map<City, Integer> perCity = new EnumMap<>(City.class);

		for (City city : City.values())
		{
			int citizens = 0;
			for (int regionId : city.getRegionIds())
			{
				RegionDefinition region = loader.loadRegion(regionId);
				if (region == null)
				{
					// A city naming a region that ships no file is a red CityTest, not a
					// reason for the panel to fail to open.
					continue;
				}

				for (EntityDefinition definition : region.getEntities())
				{
					if (!definition.getType().isCitizen())
					{
						// Scenery carries no name and cannot be hidden or muted from a
						// menu that is never offered on it.
						continue;
					}

					citizens++;
					byUuid.put(definition.getUuid(), new Entry(nameOf(definition), city));
				}
			}
			perCity.put(city, citizens);
		}

		authored = Collections.unmodifiableMap(byUuid);
		counts = Collections.unmodifiableMap(perCity);
		log.debug("citizen directory: {} authored citizen(s) across {} cities",
			authored.size(), counts.size());
	}

	/**
	 * The echo tier, derived the same way {@link EntityScene#ensureBuilt} derives it —
	 * from the region's <i>whole</i> authored roster, because separation is judged
	 * against everything in the region and deriving one citizen at a time gives
	 * different uuids.
	 */
	private Map<UUID, Entry> echoIndex()
	{
		if (derived != null)
		{
			return derived;
		}

		Map<UUID, Entry> byUuid = new HashMap<>();
		for (City city : City.values())
		{
			for (int regionId : city.getRegionIds())
			{
				RegionDefinition region = loader.loadRegion(regionId);
				if (region == null)
				{
					continue;
				}

				for (EntityDefinition echo : CitizenEcho.echoesOfRegion(region.getEntities()))
				{
					// Its source's city, which is the checkbox that governs it — the same
					// rule EntityScene.allowedByConfig applies, and not the city its own
					// tile happens to fall in.
					City home = City.of(echo.getCityRegionId());
					byUuid.put(echo.getUuid(), new Entry(nameOf(echo), home == null ? city : home));
				}
			}
		}

		derived = Collections.unmodifiableMap(byUuid);
		log.debug("citizen directory: {} derived citizen(s) indexed", derived.size());
		return derived;
	}

	/**
	 * @return every uuid the directory knows, authored tier only. For the tests, which
	 * use it to prove the index really covers the shipped dataset rather than a subset
	 * of it that happened to parse.
	 */
	List<UUID> authoredUuids()
	{
		return new ArrayList<>(authoredIndex().keySet());
	}

	private static String nameOf(EntityDefinition definition)
	{
		String name = definition.getName();
		return name == null || name.trim().isEmpty() ? "Unnamed citizen" : name.trim();
	}

	/** A citizen the directory can place: what it is called, and whose checkbox owns it. */
	static final class Entry
	{
		private final String name;
		private final City city;

		Entry(String name, City city)
		{
			this.name = name;
			this.city = city;
		}

		String getName()
		{
			return name;
		}

		City getCity()
		{
			return city;
		}

		@Override
		public String toString()
		{
			return name + " (" + city.getLabel() + ")";
		}
	}
}

package com.matthewmariner.livelycities;

import java.awt.Color;

/**
 * Every string and the one colour that say "this thing is ours, not the game's".
 *
 * <p><b>This is the plugin's licence to exist, not decoration.</b> The hub
 * disabled the predecessor after a Reddit thread — r/2007scape {@code 1f3yy3k},
 * "Who is this man? Why does he not have any legs?" — in which a player mistook a
 * broken-looking fake NPC for a real one and went to the maintainers about it.
 * Fake being mistakable for real is the failure mode that gets this category of
 * plugin pulled, so the menu row, the examine line and the overhead text all
 * carry the same colour and the plugin's name.
 *
 * <p><b>Why {@link #FAKE_RGB} is a constant and not a config item.</b> It would
 * be cheap to expose — RuneLite supports {@code Color} config items — and it is
 * deliberately not exposed. The colour's whole job is to be a colour the game
 * never uses for a real target, and a user-settable colour can be set to
 * {@code ffff00}, which is exactly what a real NPC's menu target is. Making the
 * one legibility guarantee user-defeatable to save a constant is a bad trade. The
 * client's own target colours, for the record:
 *
 * <ul>
 *   <li>{@code <col=ffff00>} yellow — NPCs</li>
 *   <li>{@code <col=ffffff>} white — players</li>
 *   <li>{@code <col=00ffff>} cyan — scene objects</li>
 *   <li>{@code <col=ff9040>} orange — items, on the ground and in the inventory</li>
 * </ul>
 *
 * <p>{@code ff66ff} is none of those and is not close to any of them at any
 * brightness, which is the property being bought.
 *
 * <p><b>The tag string is written out rather than formatted from the int.</b>
 * {@code String.format("<col=%06x>", FAKE_RGB)} would be the same six characters
 * and one more thing that can go wrong at runtime, in a string the client parses
 * and silently drops on a mismatch. {@code CitizenLabelTest} asserts the two
 * halves agree, so they cannot drift.
 */
final class CitizenLabel
{
	/**
	 * The one colour. Magenta, chosen for not being any colour the client uses
	 * for a real menu target — see the class javadoc.
	 */
	static final int FAKE_RGB = 0xFF66FF;

	/** {@link #FAKE_RGB} as the client's colour tag, for menu targets and chat. */
	static final String COLOUR_TAG = "<col=ff66ff>";

	/** {@link #FAKE_RGB} for the overhead-text overlay, which draws in AWT. */
	static final Color FAKE_COLOUR = new Color(FAKE_RGB);

	/**
	 * The plugin's name, as it appears to a player who is wondering what they are
	 * looking at. This is the string that has to make the answer findable.
	 */
	static final String PLUGIN_NAME = "Lively Cities";

	private CitizenLabel()
	{
	}

	/**
	 * The menu target for one of our entries: the citizen's name and the plugin's,
	 * in the plugin's colour.
	 *
	 * <p>The name of the plugin is inside the coloured span on purpose — a
	 * half-coloured row reads as a real target with a suffix, which is the
	 * impression this is trying to avoid.
	 *
	 * <p>Scenery has no {@code name} in the dataset, so it falls back to the entity
	 * type. Scenery does not currently get menu entries, but the fallback is here
	 * rather than at the call site because "the label is never empty" is a property
	 * of the label, and a row reading {@code Examine  (Lively Cities)} would be the
	 * confusing outcome this class exists to prevent.
	 */
	static String menuTarget(EntityDefinition definition)
	{
		return COLOUR_TAG + who(definition) + " (" + PLUGIN_NAME + ")</col>";
	}

	/**
	 * The Examine line, printed into the local chat buffer and nowhere else.
	 *
	 * <p>It uses the dataset's own {@code examineText} — all 269 shipped citizens
	 * have one — and then says, in as many words, that the thing is this plugin's
	 * and is not a real NPC. That sentence is the direct answer to the thread that
	 * got the predecessor disabled, and it is why this is not simply the authored
	 * examine text on its own.
	 */
	static String examineMessage(EntityDefinition definition)
	{
		String examine = definition.getExamineText();
		StringBuilder out = new StringBuilder();
		out.append(COLOUR_TAG).append(who(definition)).append("</col>: ");

		if (examine != null && !examine.trim().isEmpty())
		{
			out.append(examine.trim());
			if (!endsSentence(examine.trim()))
			{
				out.append('.');
			}
			out.append(' ');
		}

		out.append('(').append(PLUGIN_NAME)
			.append(" — a cosmetic citizen added by the plugin, not a real NPC.)");
		return out.toString();
	}

	/**
	 * Confirmation for "Hide", naming the way back. A right-click action whose undo
	 * lives in a settings panel the user has not opened is an action they will
	 * report as a bug.
	 */
	static String hiddenMessage(EntityDefinition definition, int totalHidden)
	{
		return COLOUR_TAG + who(definition) + "</col> is hidden. Tick \"Unhide all citizens\" in the "
			+ PLUGIN_NAME + " settings to bring "
			+ (totalHidden == 1 ? "them" : "all " + totalHidden + " of them") + " back.";
	}

	/** Confirmation for "Mute", on the same terms as {@link #hiddenMessage}. */
	static String mutedMessage(EntityDefinition definition, int totalMuted)
	{
		return COLOUR_TAG + who(definition) + "</col> will stop talking. Tick \"Unmute all citizens\" in the "
			+ PLUGIN_NAME + " settings to undo "
			+ (totalMuted == 1 ? "it" : "all " + totalMuted + " of them") + ".";
	}

	private static String who(EntityDefinition definition)
	{
		String name = definition.getName();
		return name != null && !name.trim().isEmpty() ? name.trim() : definition.getType().name();
	}

	private static boolean endsSentence(String text)
	{
		char last = text.charAt(text.length() - 1);
		return last == '.' || last == '!' || last == '?';
	}
}

package com.matthewmariner.livelycities;

import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * The right-click menu for a fake citizen: Examine, Hide, Mute — and nothing that
 * could ever reach the server.
 *
 * <p><b>Purely cosmetic and local: this class uses {@code RuneLiteObject}s only,
 * adds RUNELITE-type menu entries only, and sends nothing to the server.</b> That
 * is the hub's own accepted formula, and it is enforced here rather than
 * promised:
 * <ul>
 *   <li>Every entry is created with {@link MenuAction#RUNELITE} and
 *       {@code setDeprioritized(true)}. RUNELITE actions are handled inside the
 *       client's plugin layer and never packed into a packet.</li>
 *   <li>{@link #onMenuOptionClicked} checks the action type <i>and</i> the option
 *       text <i>and</i> the identifier it stamped on its own entry, then calls
 *       {@code consume()} before doing anything, so the click never reaches the
 *       client's own menu dispatch.</li>
 *   <li>The three actions do exactly three things: print a line into the local
 *       chat buffer, and write a uuid into this plugin's own config. Neither is a
 *       game action. {@code Client.menuAction(..)} — the one API on this surface
 *       that <i>does</i> perform a real action — is never called, and
 *       {@code StubClient} throws on it, so a regression that reached for it is a
 *       red test rather than a shipped packet.</li>
 * </ul>
 *
 * <p><b>Never compete with a real NPC for a click</b> — upstream issue #14, 49
 * upvotes, "can't right-click through them" and "misclicks when using an item".
 * Three things, and the first is structural:
 *
 * <ol>
 *   <li><b>The entries only exist inside an opened right-click menu.</b> They are
 *       created in {@link MenuOpened}, which fires after the client has built the
 *       menu for that click, so they are not present when the client resolves a
 *       <i>left</i> click at all. There is nothing to misclick.</li>
 *   <li><b>They go in at index 0, which is the bottom of the menu.</b>
 *       {@code MenuOpened.getFirstEntry()} returns {@code menuEntries[length - 1]}
 *       — verified in the 1.12.36 bytecode — so the array is rendered last-first
 *       and index 0 is the last row. {@code Menu.createMenuEntry(0)} inserts
 *       there; the same bytecode shows a non-negative index is used directly and a
 *       negative one is folded to {@code count + idx + 1}, which is why {@code -1}
 *       (the conventional call) would put us at the <i>top</i>. On top of that
 *       every entry is {@code setDeprioritized(true)}, whose contract is
 *       "sorted in the menu to be below the other menu entries".</li>
 *   <li><b>No clickbox is computed at all while an item or a spell is on the
 *       cursor.</b> {@code Client.isWidgetSelected()} — "is a widget in target
 *       mode?" — is checked before anything else, so mid-"use item on" there is no
 *       hit test, no entries, and nothing of ours in the menu. This is the
 *       specific reported complaint, and the guard is placed so that it also costs
 *       nothing.</li>
 *   <li><b>Nothing is added to an interface's menu either.</b> The clickbox is in
 *       canvas space and the inventory is drawn over the viewport, so a citizen
 *       standing behind it projects underneath it — see {@link #isWorldClick} and
 *       {@link #isOverMinimap}.</li>
 * </ol>
 *
 * <p><b>What {@code setDrawFrontTilesFirst} turned out to be, since the plan
 * flagged it as a possible third lever.</b> It is not one. Its own javadoc in
 * 1.12.36 says it expands the pre-drawn tile rectangle by a full tile in the
 * direction the object faces; the flag is passed to the scene's add-entity call as
 * its last argument, alongside a click tag of {@code -1L} — the client registers
 * our objects for <i>drawing</i> with no click tag at all, which is precisely why
 * this class has to compute a clickbox itself. So the flag is tile draw order and
 * cannot affect click competition. It is left at its default {@code false}: the
 * citizens are single-tile human models at the default radius of 60, which the
 * same javadoc calls the value that "works well for models the size of a single
 * tile", and a wandering citizen changes facing every step, so setting it would
 * churn the pre-drawn tile set once a tick for no visual gain.
 *
 * <p><b>The clickbox is computed on right-click, not per tick.</b> The plan named
 * the per-object per-tick convex hull as the known frame-time cost centre, and the
 * accepted three-part pattern is "clickbox → menu → click". Doing the first part
 * lazily costs nothing per frame and nothing per tick: {@link MenuOpened} fires
 * once per right-click, and at most
 * {@link #CLICKBOX_RADIUS_TILES}-worth of citizens are tested on it. A per-tick
 * clickbox would only be needed to put an entry on a <i>left</i> click, which this
 * plugin deliberately never does.
 *
 * <p><b>Client thread, and no {@code invokeLater}.</b> {@code MenuOpened} and
 * {@code MenuOptionClicked} are both posted from the client's own menu code, and
 * {@code Menu.createMenuEntry} asserts {@code isClientThread()} (also verified in
 * the bytecode). Deferring the {@code MenuOpened} handler through
 * {@link net.runelite.client.callback.ClientThread} would be actively wrong, not
 * merely unnecessary: the entries would be added after the menu had been built and
 * drawn.
 */
@Slf4j
@Singleton
class CitizenMenu
{
	/**
	 * How far from the player a citizen may be and still get a right-click menu:
	 * 15 tiles.
	 *
	 * <p>The figure the performance budget names for clickboxes. It is deliberately
	 * tighter than the default 25-tile render distance — a citizen twenty tiles away
	 * is scenery, and the whole point of the distance gate is that the hit test
	 * never walks the far half of a crowd.
	 */
	static final int CLICKBOX_RADIUS_TILES = 15;

	static final String OPTION_EXAMINE = "Examine";
	static final String OPTION_HIDE = "Hide";
	static final String OPTION_MUTE = "Mute";

	/**
	 * The minimap panel, in each of the three toplevel layouts a desktop client can
	 * be in: fixed (interface 548), resizable-classic (161) and resizable-modern
	 * (164).
	 *
	 * <p><b>Not invented — this is RuneLite's own answer to "where is the minimap".</b>
	 * {@code net.runelite.client.ui.overlay.OverlayOrigin.MINIMAP} in client-1.12.36
	 * resolves exactly these three component ids, in exactly the order
	 * {@link #minimapPanel()} does (verified by disassembling
	 * {@code OverlayOrigin$3.getWidget} and {@code OverlayOrigin.getComponent}). They
	 * are the containers RuneLite positions its own {@code CANVAS_TOP_RIGHT} overlays
	 * against, so they are laid out and drawn whenever the minimap is on screen —
	 * which is what makes {@code getBounds()} on them mean something.
	 *
	 * <p>The container rather than the {@code MINIMAP} child inside it, deliberately:
	 * it covers the compass and the orb column as well as the map itself, and a
	 * citizen projecting under any of those is equally unreachable. A wider rectangle
	 * costs nothing here and is one fewer guess about which child owns the "Walk here"
	 * option.
	 */
	private static final int FIXED_MINIMAP_PANEL = InterfaceID.Toplevel.MAPCONTAINER;
	private static final int RESIZABLE_MINIMAP_PANEL = InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER;
	private static final int RESIZABLE_MODERN_MINIMAP_PANEL = InterfaceID.ToplevelPreEoc.MAP_CONTAINER;

	private final Client client;
	private final EntityScene scene;
	private final CitizenOverrides overrides;

	/**
	 * The citizen the last opened menu was built for.
	 *
	 * <p>A uuid does not fit in {@code MenuEntry.setIdentifier(int)}, and there is
	 * exactly one open menu at a time, so the entity is remembered rather than
	 * encoded. {@link #token} is what makes that safe: it is stamped on the entries
	 * as their identifier and checked on the click, so a stale field can never be
	 * acted on by somebody else's RUNELITE entry.
	 */
	@Nullable
	private LivelyEntity target;

	/**
	 * Stamped on this menu's entries as their identifier, and bumped for every menu.
	 * Starts at 1 so a click carrying the default identifier of 0 can never match.
	 */
	private int token;

	@Inject
	CitizenMenu(Client client, EntityScene scene, CitizenOverrides overrides)
	{
		this.client = client;
		this.scene = scene;
		this.overrides = overrides;
	}

	/**
	 * Adds this plugin's entries, if the right-click landed on one of our citizens.
	 *
	 * <p>Client thread only, and synchronously — see the class javadoc.
	 */
	void onMenuOpened(MenuOpened event)
	{
		// Whatever happens, the previous menu's target is stale from here on.
		target = null;

		if (client.isWidgetSelected())
		{
			// An item or a spell is on the cursor. No hit test, no clickbox, no
			// entries — the misclick complaint from issue #14, and the reason this
			// is the first line rather than a filter further down.
			return;
		}

		if (!isWorldClick(event))
		{
			// The right-click was on an interface, not on the world. Our clickbox is
			// in canvas space and the inventory is drawn on top of the viewport, so a
			// citizen standing behind the inventory really does project underneath
			// it — and without this, right-clicking a rune would offer to examine
			// him. Nothing is computed and nothing is added.
			return;
		}

		final Player local = client.getLocalPlayer();
		final WorldPoint playerLocation = local == null ? null : local.getWorldLocation();
		final WorldView worldView = client.getTopLevelWorldView();
		final Point mouse = client.getMouseCanvasPosition();
		if (playerLocation == null || worldView == null || mouse == null)
		{
			return;
		}

		if (isOverMinimap(mouse))
		{
			// The one interface that also carries a "Walk here", so the check above
			// waved it through — GitHub issue #2. Same rule, answered geometrically
			// because the menu itself cannot answer it. Still before any clickbox.
			return;
		}

		LivelyEntity hit = findUnderMouse(playerLocation, worldView, mouse);
		if (hit == null)
		{
			return;
		}

		target = hit;
		token++;
		addEntries(hit);
	}

	/**
	 * Handles a click on one of our entries, and consumes it.
	 *
	 * <p>Anything that is not ours falls through untouched — in particular a
	 * RUNELITE entry with the same option text belonging to another plugin, which is
	 * what the identifier and target checks are for.
	 */
	void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.RUNELITE)
		{
			return;
		}

		final String option = event.getMenuOption();
		if (!OPTION_EXAMINE.equals(option) && !OPTION_HIDE.equals(option) && !OPTION_MUTE.equals(option))
		{
			return;
		}

		final LivelyEntity entity = target;
		if (entity == null || event.getId() != token)
		{
			return;
		}

		final EntityDefinition definition = entity.getDefinition();
		if (!CitizenLabel.menuTarget(definition).equals(event.getMenuTarget()))
		{
			// Same type, same option text, same identifier, different target: not
			// ours, and acting on it would be acting on somebody else's entry.
			return;
		}

		// Consumed before anything else happens, so there is no path on which the
		// client's own menu dispatch sees this click.
		event.consume();

		switch (option)
		{
			case OPTION_EXAMINE:
				message(CitizenLabel.examineMessage(definition));
				break;

			case OPTION_HIDE:
				if (overrides.hide(definition))
				{
					message(CitizenLabel.hiddenMessage(definition, overrides.hiddenUuids().size()));
				}
				// The citizen is not despawned here. Writing the setting posts a
				// ConfigChanged, the plugin answers that with a visibility pass, and
				// the pass despawns whatever is no longer wanted — the same path a
				// city checkbox takes. One mechanism, already tested.
				target = null;
				break;

			case OPTION_MUTE:
				if (overrides.mute(definition))
				{
					message(CitizenLabel.mutedMessage(definition, overrides.mutedUuids().size()));
				}
				// Unlike Hide, this one does need a nudge: muting does not change
				// whether the citizen is visible, so the visibility pass has nothing
				// to do, and a remark already on screen would otherwise sit there for
				// the rest of its dwell.
				CitizenRemarks remarks = entity.getRemarks();
				if (remarks != null)
				{
					remarks.clear();
				}
				break;

			default:
				// Unreachable: the option was matched above.
				break;
		}
	}

	/**
	 * Drops the remembered target.
	 *
	 * <p>Called on every scene invalidation and on shutdown. A {@link LivelyEntity}
	 * held here after its region has been evicted would be a wrapper the scene has
	 * forgotten, kept alive — with its lit model — by this one field.
	 */
	void forget()
	{
		target = null;
	}

	/** @return the citizen the currently open menu belongs to, for tests */
	@Nullable
	LivelyEntity getTarget()
	{
		return target;
	}

	/**
	 * Whether this menu belongs to a click on the game world rather than on an
	 * interface.
	 *
	 * <p>Decided by looking for a {@link MenuAction#WALK} entry: the client adds
	 * "Walk here" to every viewport right-click — on the ground, on an NPC, on a
	 * scene object alike — and to no interface right-click, where the menu is
	 * "Cancel" plus the widget's own operations. So it is the client's own answer to
	 * "was this a click on the world", read off the menu it built, rather than a
	 * geometric guess about where the inventory happens to be.
	 *
	 * <p><b>It has exactly one exception, and it is handled next door.</b> A minimap
	 * right-click carries a "Walk here" too, so this returns true for one interface —
	 * see {@link #isOverMinimap}, and GitHub issue #2.
	 */
	private static boolean isWorldClick(MenuOpened event)
	{
		MenuEntry[] entries = event.getMenuEntries();
		if (entries == null)
		{
			return false;
		}

		for (MenuEntry entry : entries)
		{
			if (entry != null && entry.getType() == MenuAction.WALK)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * Whether the right-click landed on the minimap panel — the one interface
	 * {@link #isWorldClick} cannot see. GitHub issue #2.
	 *
	 * <p><b>Why this has to be geometry.</b> The obvious fix would be to read it off
	 * the menu, and the menu does not carry it. Disassembling the injected 1.12.36
	 * client, there is exactly one producer of a "Walk here" option — the string lives
	 * in {@code kk.hm} and the only code that reads it builds the entry as
	 * {@code rp.fb("Walk here", "", 23, 0, mouseX - originX, mouseY - originY, 0,
	 * false, worldViewId, ..)}. Opcode 23 is {@link MenuAction#WALK}, the identifier is
	 * a literal {@code 0}, the target is empty, and {@code param0}/{@code param1} are a
	 * mouse position relative to whatever the caller's origin was. Every field is the
	 * same whichever of the three call sites built it, so there is nothing on the entry
	 * that says "this one came from the map". {@code MenuEntry.getWidget()} is not an
	 * answer either: the entry is built by that call, which takes no widget.
	 *
	 * <p><b>Why these ids and this order.</b> Straight out of
	 * {@code net.runelite.client.ui.overlay.OverlayOrigin.MINIMAP} in client-1.12.36 —
	 * RuneLite's own "where is the minimap" — rather than a rule invented here:
	 * {@code isResized()} picks fixed versus resizable, and inside resizable
	 * {@code getTopLevelInterfaceId() == 164} picks the modern layout from the classic
	 * one. {@code Client.getWidget(int)} decodes the packed component id through
	 * {@code WidgetUtil.componentToInterface}/{@code componentToId} (also verified in
	 * the bytecode) and returns {@code null} when that interface is not loaded, so
	 * asking about the wrong layout is a null rather than a wrong rectangle.
	 *
	 * <p><b>It fails open, on purpose.</b> No widget and a hidden widget both mean
	 * "cannot tell", and the answer to "cannot tell" is the previous behaviour — a
	 * spurious Examine option — rather than silently withholding the plugin's own menu
	 * from a chunk of the screen. The entries here are inert and local, so the failure
	 * this trades against is the milder one.
	 *
	 * <p><b>No null or emptiness check on the rectangle</b>, and that is deliberate
	 * rather than an omission. {@code lw.getBounds()} in 1.12.36 is literally
	 * {@code new Rectangle(cz, ca, getWidth(), getHeight())} — a fresh instance, never
	 * null — and {@link Rectangle#contains(int, int)} already answers "no" for any box
	 * with a zero or negative dimension. Either guard would be a branch no test could
	 * tell from an empty statement, which is the kind of code this project treats as
	 * worse than absent.
	 *
	 * <p><b>The case those guards would nominally cover is a panel the client has
	 * loaded and never laid out, and the geometry already answers it.</b> Two earlier
	 * revisions of this paragraph claimed a "phantom rectangle at canvas (0, 0)"
	 * instead; both were wrong, so the bytecode is written out. {@code lw}'s no-arg
	 * constructor initialises the two canvas coordinates {@code cz} and {@code ca} to
	 * <b>{@code -1}</b> ({@code iconst_m1}) and the raw width and height fields
	 * {@code cv} and {@code do} to {@code 0} ({@code iconst_0}). {@code getWidth()}
	 * reads {@code cv}, which is <i>not</i> the interface definition's width — that is a
	 * separate field {@code dd}, exposed separately as {@code getOriginalWidth()}, and
	 * the buffer decoders that fill {@code dd} in never touch {@code cv}. So an
	 * unpositioned panel reports {@code Rectangle(-1, -1, 0, 0)}: empty, and
	 * {@code contains} returns false for every point on the canvas, {@code (0, 0)}
	 * included. There is no window in which this guard suppresses a citizen it should
	 * have offered. The original reasoning — {@code getBounds()} is never null and
	 * {@code contains()} already says no to a degenerate box — was right all along.
	 *
	 * <p><b>What {@code isHidden()} is for, then.</b> Not that case, and it is not a
	 * layout signal at all: disassembling 1.12.36 it is self-hidden (the raw boolean
	 * field {@code cq}, which is the whole of {@code isSelfHidden()}) OR, with no
	 * parent, the widget's own interface not being the current toplevel, OR the parent
	 * being hidden. All three are visibility flags. What it covers is the case that
	 * does happen: a panel the client <i>has</i> laid out, so it owns a real rectangle
	 * over the minimap, and has since marked hidden — the whole toplevel swapped out
	 * from under it, or the panel switched off. Geometry alone would go on suppressing
	 * citizens under a minimap that is not on screen, so the flag earns its place; it
	 * just earns it for a positioned panel rather than an unpositioned one.
	 *
	 * <p><b>What is still not covered:</b> {@code InterfaceID.TOPLEVEL_OSM} (601), the
	 * mobile-style layout, whose minimap sits at a fourth component id.
	 * {@code OverlayOrigin.MINIMAP} does not handle it either, so a plugin's overlays
	 * do not snap to the minimap there and this guard does not fire there. Adding a
	 * fourth branch would be a check nothing could verify — see the class javadoc's
	 * rule about the clickbox seam.
	 */
	private boolean isOverMinimap(Point mouse)
	{
		final Widget panel = minimapPanel();
		if (panel == null || panel.isHidden())
		{
			return false;
		}

		final Rectangle bounds = panel.getBounds();
		return bounds.contains(mouse.getX(), mouse.getY());
	}

	/**
	 * The minimap panel widget for whichever toplevel layout is loaded, or
	 * {@code null} if none of the three resolves.
	 *
	 * <p>Private, unlike {@link #clickbox}, and that is the difference worth noting:
	 * the clickbox needs a test seam because it projects through the live camera, while
	 * this is three ordinary {@code Client} calls a fake can answer. The tests drive it
	 * through {@code FakeClient}'s widget map rather than by overriding it, so what they
	 * exercise is this method and not a stand-in for it.
	 */
	@Nullable
	private Widget minimapPanel()
	{
		if (!client.isResized())
		{
			return client.getWidget(FIXED_MINIMAP_PANEL);
		}

		return client.getTopLevelInterfaceId() == InterfaceID.TOPLEVEL_PRE_EOC
			? client.getWidget(RESIZABLE_MODERN_MINIMAP_PANEL)
			: client.getWidget(RESIZABLE_MINIMAP_PANEL);
	}

	/**
	 * The nearest active citizen whose clickbox contains the mouse.
	 *
	 * <p>Nearest rather than first: citizens overlap on screen in a crowd, and the
	 * one in front is the one the player is pointing at.
	 */
	@Nullable
	private LivelyEntity findUnderMouse(WorldPoint playerLocation, WorldView worldView, Point mouse)
	{
		final List<LivelyEntity> entities = scene.inScopeEntities();

		LivelyEntity best = null;
		int bestDistance = Integer.MAX_VALUE;

		for (int i = 0; i < entities.size(); i++)
		{
			LivelyEntity entity = entities.get(i);
			if (!entity.isActive())
			{
				continue;
			}

			int distance = RenderPolicy.tileDistance(
				playerLocation, entity.getDefinition().getWorldLocation());
			if (distance > CLICKBOX_RADIUS_TILES || distance >= bestDistance)
			{
				// Too far to be clickable, or further than something already hit —
				// either way, do not pay for its clickbox. This is the whole of the
				// distance gate, and it is placed before the projection rather than
				// after it on purpose.
				continue;
			}

			Shape clickbox = clickbox(entity, worldView);
			if (clickbox == null || !clickbox.contains(mouse.getX(), mouse.getY()))
			{
				continue;
			}

			best = entity;
			bestDistance = distance;
		}

		return best;
	}

	/**
	 * The on-screen clickable area of one citizen, or {@code null} if it has no
	 * model yet or is off screen.
	 *
	 * <p>Package-private and non-final so a test can stand in for it. There is no
	 * other way: {@code Perspective.getClickbox} projects through the live camera —
	 * {@code get3dZoom}, {@code getCameraX/Y/Z}, the rasteriser clip fields — and
	 * this repo has no mocking framework and does not use reflection, so the seam is
	 * the override. Everything that decides <i>whether</i> to call this, which is
	 * the part issue #14 is about, is on this side of the seam and is tested.
	 *
	 * <p>{@code Perspective.getClickbox} is marked {@code @ApiStatus.Internal} with
	 * a javadoc that says to use {@code TileObject#getClickbox()} instead. There is
	 * no such method to use: a {@code RuneLiteObject} is neither a {@code TileObject}
	 * nor an {@code Actor}, and the client gives it no click tag (see the class
	 * javadoc), so this is the only projection available and it is the one the
	 * hub-merged precedents use.
	 */
	@Nullable
	Shape clickbox(LivelyEntity entity, WorldView worldView)
	{
		final Model model = entity.getRenderedModel();
		final LocalPoint at = entity.getRenderLocation();
		if (model == null || at == null)
		{
			return null;
		}

		return Perspective.getClickbox(
			client,
			worldView,
			model,
			entity.getRenderOrientation(),
			at.getX(),
			at.getY(),
			entity.getRenderZ());
	}

	/**
	 * Prints one line into the local chat buffer.
	 *
	 * <p>Package-private and non-final for the same reason as
	 * {@link #clickbox}: it is the one client call the click handler makes, and a
	 * test wants to read what was said.
	 */
	void message(String text)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", text, null);
	}

	/**
	 * Three entries, all RUNELITE, all deprioritised, all at the bottom of the menu.
	 *
	 * <p>Inserted Examine, Hide, Mute, which — because each insert goes in at index
	 * 0 and the array renders last-first — puts them on screen in that order with
	 * Mute at the very bottom.
	 *
	 * <p>Mute is only offered to a citizen that has something to say. An entry that
	 * cannot do anything is worse than a missing one: the user who clicks it learns
	 * that the plugin's menu lies.
	 */
	private void addEntries(LivelyEntity entity)
	{
		final EntityDefinition definition = entity.getDefinition();

		entry(OPTION_EXAMINE, definition);
		entry(OPTION_HIDE, definition);

		if (entity.getRemarks() != null)
		{
			entry(OPTION_MUTE, definition);
		}
	}

	/**
	 * One entry.
	 *
	 * <p>{@code client.getMenu().createMenuEntry(int)} and not
	 * {@code Client.createMenuEntry(int)} — the latter is {@code @Deprecated} in
	 * 1.12.36 in favour of exactly this.
	 */
	private void entry(String option, EntityDefinition definition)
	{
		MenuEntry created = client.getMenu().createMenuEntry(0)
			.setOption(option)
			.setTarget(CitizenLabel.menuTarget(definition))
			.setType(MenuAction.RUNELITE)
			.setIdentifier(token)
			.setDeprioritized(true);

		if (log.isDebugEnabled())
		{
			log.debug("added '{}' for {} (identifier {}, deprioritized {})",
				option, definition.label(), created.getIdentifier(), created.isDeprioritized());
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The two per-citizen opt-outs: <b>hide this one</b> and <b>shut this one up</b>.
 *
 * <p>Both are the same mechanism — a set of uuids in a {@code hidden = true}
 * config string, written by a RUNELITE menu entry, cleared by a visible
 * checkbox — so they are one class with two {@link UuidSetting}s rather than two
 * classes that would drift apart. Upstream issue #40 asked for the first; the
 * 144-upvote "please add an option to shut them up" thread is the second, at the
 * granularity people actually complained at: it was never "no citizen anywhere
 * should ever speak", it was "this one, outside the bank, every six seconds".
 *
 * <p><b>Why per-citizen and not just a global mute.</b> A global mute already
 * exists one notch up — {@link LivelyCitiesConfig#overheadText()} is the hard off
 * switch that removes overhead text entirely (issue #35). A second global switch
 * spelled "mute" would be the same setting twice, and a test could not tell them
 * apart, which is exactly the "fixture too uniform to distinguish outcomes" trap.
 * Two genuinely different granularities: one citizen, or the whole feature.
 *
 * <p><b>The uuid is the dataset's, and it is stable.</b> All 311 shipped records
 * carry one. {@link EntityDefinition} generates a random uuid for a record that
 * does not, and an override on such an entity therefore lasts only as long as the
 * session — the honest failure, and the reason the generator logs a warning.
 *
 * <p><b>Nothing here despawns or silences anything itself.</b> Writing the
 * setting posts a {@code ConfigChanged}, the plugin answers that by re-running the
 * visibility pass, and the pass has one rule — what is not wanted is despawned.
 * That is the same path the per-city checkboxes take, and reusing it is why
 * "Hide" needs no code of its own on the render side.
 */
@Slf4j
@Singleton
class CitizenOverrides
{
	/** {@code keyName} of the hidden string holding the hidden-citizen uuids. */
	static final String HIDDEN_KEY = "hiddenCitizens";

	/** {@code keyName} of the hidden string holding the muted-citizen uuids. */
	static final String MUTED_KEY = "mutedCitizens";

	/** {@code keyName} of the visible "Unhide all" checkbox. */
	static final String UNHIDE_ALL_KEY = "unhideAll";

	/** {@code keyName} of the visible "Unmute all" checkbox. */
	static final String UNMUTE_ALL_KEY = "unmuteAll";

	private final UuidSetting hidden;
	private final UuidSetting muted;

	@Inject
	CitizenOverrides(LivelyCitiesConfig config, ConfigWriter writer)
	{
		this.hidden = new UuidSetting(HIDDEN_KEY, config::hiddenCitizens, writer);
		this.muted = new UuidSetting(MUTED_KEY, config::mutedCitizens, writer);
	}

	/**
	 * @return the hidden uuids. Hoist this out of a per-entity loop — see
	 * {@link UuidSetting}.
	 */
	Set<UUID> hiddenUuids()
	{
		return hidden.current();
	}

	/**
	 * @return the muted uuids. Same advice as {@link #hiddenUuids()}.
	 */
	Set<UUID> mutedUuids()
	{
		return muted.current();
	}

	/**
	 * @return true if this call actually hid something new
	 */
	boolean hide(EntityDefinition definition)
	{
		boolean added = hidden.add(definition.getUuid());
		if (added)
		{
			log.debug("hiding {} ({}), {} citizen(s) now hidden",
				definition.label(), definition.getUuid(), hidden.size());
		}
		return added;
	}

	/**
	 * @return true if this call actually muted something new
	 */
	boolean mute(EntityDefinition definition)
	{
		boolean added = muted.add(definition.getUuid());
		if (added)
		{
			log.debug("muting {} ({}), {} citizen(s) now muted",
				definition.label(), definition.getUuid(), muted.size());
		}
		return added;
	}

	/**
	 * Brings one hidden citizen back.
	 *
	 * <p>The counterpart to {@link #hide}, and the half that was missing until
	 * {@link LivelyCitiesPanel} existed: hiding is per citizen and the only undo was
	 * {@link #unhideAll()}, so changing your mind about one figure cost you every other
	 * decision. Nothing here respawns anything — the write posts a
	 * {@code ConfigChanged}, the plugin answers it with a visibility pass, and the pass
	 * has one rule. Exactly the path {@link #hide} takes, in reverse.
	 *
	 * @return true if this call actually unhid something
	 */
	boolean unhide(UUID uuid)
	{
		boolean removed = hidden.remove(uuid);
		if (removed)
		{
			log.debug("unhiding {}, {} citizen(s) still hidden", uuid, hidden.size());
		}
		return removed;
	}

	/**
	 * Lets one muted citizen talk again. Same shape and same reasoning as
	 * {@link #unhide}.
	 *
	 * @return true if this call actually unmuted something
	 */
	boolean unmute(UUID uuid)
	{
		boolean removed = muted.remove(uuid);
		if (removed)
		{
			log.debug("unmuting {}, {} citizen(s) still muted", uuid, muted.size());
		}
		return removed;
	}

	/**
	 * @return how many citizens were unhidden
	 */
	int unhideAll()
	{
		int count = hidden.size();
		if (hidden.clear())
		{
			log.info("Lively Cities: unhid {} citizen(s)", count);
			return count;
		}
		return 0;
	}

	/**
	 * @return how many citizens were unmuted
	 */
	int unmuteAll()
	{
		int count = muted.size();
		if (muted.clear())
		{
			log.info("Lively Cities: unmuted {} citizen(s)", count);
			return count;
		}
		return 0;
	}
}

package com.matthewmariner.livelycities;

import java.util.Random;
import javax.annotation.Nullable;

/**
 * One citizen's authored one-liners, and whichever of them it is saying now.
 *
 * <p>Built and owned by {@link LivelyEntity}, exactly like {@link CitizenWalk}:
 * one per entity that has anything to say, {@code null} for everything else.
 * {@link CitizenChatter} drives it once per game tick and
 * {@code ChatterOverlay} reads it once per frame.
 *
 * <p><b>Why the text lives here and not in the overlay.</b> The predecessor's
 * loudest text bugs were orphaned bubbles and text drifting off its NPC, and both
 * came from the overlay keeping its own list of what to draw and where. This
 * splits the two halves that were conflated:
 * <ul>
 *   <li><b>What is being said</b> has a lifetime in game ticks — a remark stays up
 *       for {@code remarkDwellTicks} — so it is state, and it belongs on the
 *       entity that is saying it. It is cleared by {@link LivelyEntity#despawn()},
 *       which is what makes an orphaned bubble impossible rather than
 *       unlikely: there is no list for a despawned entity to stay in.</li>
 *   <li><b>Where it is drawn</b> is not state at all. The overlay recomputes it
 *       from the object's live position every frame and caches nothing, so text
 *       cannot drift away from the citizen it belongs to — there is nothing for it
 *       to drift from.</li>
 * </ul>
 *
 * <p><b>The randomness is seeded, and not from the clock.</b> Same reasoning as
 * {@link CitizenWalk}: a citizen's remark order is then the same every session, so
 * a street reads as a place rather than as a random generator, and a test can
 * assert something about a thousand ticks. The seed is
 * {@link EntityDefinition#stableHash()} XOR'd with a salt, because the walk
 * already uses the bare hash — two {@link Random}s from one seed would make a
 * citizen's remark rolls line up exactly with its destination rolls forever, which
 * is a correlation nobody asked for and nobody could debug.
 *
 * <p><b>Client-thread-free.</b> Nothing here touches the client.
 */
final class CitizenRemarks
{
	/**
	 * Mixed into the seed so the remark {@link Random} is not the walk
	 * {@link Random} — see the class javadoc. An arbitrary constant; its only
	 * requirement is being non-zero and fixed forever, because changing it changes
	 * every citizen's remark order.
	 */
	private static final long SEED_SALT = 0x5AF31C0FFEEL;

	private final String[] remarks;
	private final Random random;

	/**
	 * The stagger offset, so a crowd does not all roll on the same tick — see
	 * {@link #dueAt(int, int)}. Derived from the identity hash rather than drawn
	 * from {@link #random}, so it does not depend on how many times the citizen has
	 * spoken.
	 */
	private final long spread;

	@Nullable
	private String current;

	/** Only meaningful while {@link #current} is non-null. */
	private int expiresAtTick;

	private CitizenRemarks(EntityDefinition definition, String[] remarks)
	{
		this.remarks = remarks;
		this.random = new Random(definition.stableHash() ^ SEED_SALT);
		this.spread = definition.stableHash();
	}

	/**
	 * @return a remark holder, or {@code null} if this entity has nothing to say —
	 * which is most of the dataset. Of the 269 shipped citizens 54 carry remarks,
	 * 183 carry an empty array and 32 carry no {@code remarks} field at all; scenery
	 * never speaks. {@link EntityDefinition} has already flattened all four cases
	 * into "the array is empty".
	 */
	@Nullable
	static CitizenRemarks forDefinition(EntityDefinition definition)
	{
		String[] remarks = definition.getRemarks();
		return remarks.length == 0 ? null : new CitizenRemarks(definition, remarks);
	}

	/** @return true while a remark is on screen */
	boolean isTalking()
	{
		return current != null;
	}

	/** @return the remark being said, or {@code null} */
	@Nullable
	String text()
	{
		return current;
	}

	/**
	 * Stops talking now. Called by {@link LivelyEntity#despawn()} and by the hard
	 * off switch, and safe to call when there is nothing to stop.
	 */
	void clear()
	{
		current = null;
	}

	/**
	 * Ends a remark that has been up for its dwell.
	 *
	 * @return true if this call ended one
	 */
	boolean expire(int tick)
	{
		if (current != null && tick >= expiresAtTick)
		{
			current = null;
			return true;
		}
		return false;
	}

	/**
	 * Whether this citizen's roll falls on this tick.
	 *
	 * <p>Staggered per citizen rather than synchronised, so a street does not
	 * produce a chorus every {@code interval} ticks and then silence. With the
	 * shipped defaults — a 100-tick (one minute) interval and an 8-tick (4.8 second)
	 * dwell — a synchronised roll would mean every talker in view starting and
	 * stopping in lockstep once a minute, which reads as a script firing rather than
	 * as people talking.
	 *
	 * @param interval the roll interval in game ticks, already through
	 *                 {@link CitizenChatter#effectiveIntervalTicks(int)}, so at least
	 *                 {@link CitizenChatter#MIN_ROLL_INTERVAL_TICKS}
	 */
	boolean dueAt(int tick, int interval)
	{
		return Math.floorMod(tick - spread, interval) == 0;
	}

	/**
	 * Rolls this citizen's own die.
	 *
	 * <p><b>Called for every eligible citizen on its due tick, before the
	 * concurrency cap is applied</b>, so that each citizen consumes exactly one
	 * draw per due tick whatever the crowd around it is doing. Rolling only until
	 * the cap filled would make one citizen's sequence depend on how many other
	 * citizens happened to be nearby, and then no test could pin either.
	 *
	 * @param chancePercent 0..100
	 * @return true if it wants to say something
	 */
	boolean rolls(int chancePercent)
	{
		return random.nextInt(100) < chancePercent;
	}

	/**
	 * Picks a remark and starts its dwell.
	 *
	 * @param tick       the current game tick
	 * @param dwellTicks how long it stays up
	 */
	void say(int tick, int dwellTicks)
	{
		current = remarks[random.nextInt(remarks.length)];
		expiresAtTick = tick + dwellTicks;
	}

	/** @return how many different things this citizen can say */
	int size()
	{
		return remarks.length;
	}
}

package com.matthewmariner.livelycities;

import java.util.Random;
import javax.annotation.Nullable;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * One wandering citizen's walk: where it is going, where it is, and where it
 * should be drawn part-way between two tiles.
 *
 * <p><b>The per-tick / per-frame split lives here, and it is the whole design.</b>
 *
 * <ul>
 *   <li>{@link #tick()} is <b>game-tick work</b>: pick a destination, take one
 *       tile of a step, work out which way that faces. A tile per game tick is
 *       the speed the game itself walks at, and doing it anywhere else would
 *       either make citizens sprint at the frame rate or make their speed depend
 *       on the machine.</li>
 *   <li>{@link #localPoint(WorldView, float)} is <b>frame work</b>: it slides the
 *       drawn position between the tile the citizen left and the tile it is
 *       walking to. There is no walk API on {@code RuneLiteObject} — no
 *       destination, no speed, no path — so this interpolation is the only thing
 *       standing between a smooth walk and a citizen teleporting one tile every
 *       600ms.</li>
 * </ul>
 *
 * <p><b>The other half of "smooth" is the animation, and this class does not own
 * any of it.</b> The mechanism, read out of the 1.12.36 API jar rather than
 * guessed at:
 *
 * <ul>
 *   <li>{@code RuneLiteObject.tick(ticksSinceLastFrame)} is called by the client,
 *       once per frame, for every registered object — the API javadoc says
 *       "Called every frame the RuneLiteObject is registered and in the scene",
 *       and the injected client calls
 *       {@code RuneLiteObjectController.tick(I)} immediately before drawing each
 *       one. It forwards to the {@code AnimationController}, whose {@code tick}
 *       accumulates client ticks (20ms) against the animation's own
 *       {@code getFrameLengths()}. So the <i>frame index</i> already advances
 *       between game ticks, without this plugin doing anything.</li>
 *   <li>Whether the client also <i>interpolates between</i> two frames is decided
 *       by {@code AnimationController.getPackedFrame()}, which is private and read
 *       at draw time. Disassembled, it is:
 *       {@code filter = client.getAnimationInterpolationFilter(); return (filter
 *       != null && filter.test(animation.getId())) ? (Integer.MIN_VALUE |
 *       (elapsedTicks << 16) | frame) : frame;} — the high bit plus the elapsed
 *       ticks is what tells {@code applyTransformations} to blend; the bare frame
 *       index is what tells it not to.</li>
 *   <li>The only thing in RuneLite that installs that filter is the core
 *       <b>Animation Smoothing</b> plugin, and it is
 *       {@code enabledByDefault = false}. With it off the filter is null and
 *       nothing — player, NPC or {@code RuneLiteObject} — is interpolated.</li>
 * </ul>
 *
 * <p><b>So the honest position on smoothing.</b> It is not ours to switch on, and
 * it is not gated on our animation ids: the filter Animation Smoothing installs
 * is a <i>denylist</i> of 23 ids ({@code isAnimationInterpolatable} returns
 * {@code false} for those and {@code true} for everything else), and none of the
 * ids in {@link LivelyAnimation} is on it —
 * {@code LivelyAnimationTest.noShippedAnimationIsOnTheSmoothingDenylist} pins
 * that. Our citizens are therefore smoothed exactly when the user has Animation
 * Smoothing enabled, and stepped frame-by-frame when they do not, on the same
 * terms as every real NPC. There is nothing to work around and no reason to
 * ask for the frame index ourselves.
 *
 * <p>What {@link LivelyEntity} keeping one controller per animation actually buys
 * is unrelated to any of that: {@code AnimationController.setAnimation} calls
 * {@code reset()}, zeroing both {@code frame} and {@code elapsedTicks}, so
 * building a fresh controller — or re-setting an existing one — restarts the walk
 * cycle from its first frame. Holding both controllers means a citizen resumes
 * mid-stride instead of snapping back to frame zero on every idle↔move switch.
 * (An earlier version of this comment claimed the predecessor plugin's smoothing
 * complaint came from animations being reset every game tick. It did not do that;
 * the sentence was an explanation of a symptom nobody had traced.)
 *
 * <p>This class must never call {@code tick()} itself — the client already does,
 * once per frame, and a second caller runs every animation at double speed.
 *
 * <p><b>Scripted citizens are not wandering citizens.</b> The five
 * {@code ScriptedCitizen} records carry a {@code startScript} name and no wander
 * box, so they get no {@code CitizenWalk} and stand exactly where L1 put them.
 * That is on purpose and not an oversight: running authored scripts is a later
 * phase, and a scripted citizen wandering at random would be worse than one
 * standing still. Nothing runs those scripts today and nothing ever has — see
 * {@code ShippedSourceTest.noShippedClassReadsTheStartScriptField}, which is what
 * stops that sentence quietly becoming untrue. (It read "six" until 2026-08-29:
 * there were six until the nine-city cut on 2026-08-24 took "Draug" and region
 * 14936 with it, and this line was not counted again afterwards.)
 *
 * <p><b>Client-thread-free.</b> Nothing here touches the client;
 * {@link #localPoint} only reads the world view's scene rectangle. That is what
 * lets {@code CitizenWalkTest} drive ten thousand ticks without a game running.
 */
final class CitizenWalk
{
	/**
	 * Game ticks a citizen stands still before looking for somewhere new to go.
	 *
	 * <p>Ten, which is the cadence the predecessor used and about six seconds —
	 * long enough that a street reads as people pausing and moving on rather than
	 * as a crowd of pacing sentries.
	 */
	static final int IDLE_TICKS_BEFORE_NEW_DESTINATION = 10;

	/**
	 * Orientation, in RuneLite's 0..2047 turn units, for each of the eight steps a
	 * citizen can take. Indexed {@code [dx + 1][dy + 1]}.
	 *
	 * <p>The convention is the client's own, taken from
	 * {@code Angle.getNearestDirection()}: 0 = south, 1 = west, 2 = north, 3 = east —
	 * i.e. the angle rises as the facing turns clockwise from south, through a full
	 * turn of 2048 units.
	 *
	 * <p><b>The method, disassembled, is three steps and not one.</b> This javadoc
	 * quoted it as {@code (angle >> 9) & 3} — the bucketing without the rounding, which
	 * is the part that makes it a <em>nearest</em>-direction. Out of
	 * {@code runelite-api}, it is:
	 * <pre>
	 *   int d = angle &gt;&gt;&gt; 9;              // unsigned, not &gt;&gt;
	 *   if ((angle &amp; 256) != 0) d++;       // round to the nearer of the two
	 *   switch (d &amp; 3) { 0 SOUTH, 1 WEST, 2 NORTH, 3 EAST }
	 * </pre>
	 * At the four cardinals (0, 512, 1024, 1536) bit 256 is clear, the increment never
	 * fires and the two forms agree — which is why the mapping above was right anyway,
	 * and why nothing here behaves differently. They disagree at exactly the four
	 * diagonals this table ships: 256 is {@code WEST} under the real method and
	 * {@code SOUTH} under the truncating one, and 768, 1280 and 1792 are each off by
	 * one bucket the same way. Nothing in this plugin calls
	 * {@code getNearestDirection}, so the cost of the wrong quotation fell on anybody
	 * checking this table against it — including {@code ../entourage}, which copied
	 * the sentence verbatim before either was corrected.
	 *
	 * <p>A table rather than {@code atan2(-dx, -dy)} because there are only eight
	 * answers, every one of them exact, and a lookup cannot be a rounding bug. What
	 * defends the entries is not this quotation but
	 * {@code CitizenWalkTest.theCardinalOrientationsMatchTheClientsOwnBuckets}, which
	 * derives all eight from the geometry independently.
	 */
	private static final int[][] STEP_ORIENTATION = {
		//        dy = -1 (south)  dy = 0        dy = +1 (north)
		/* dx=-1 */ {256, 512, 768},      // south-west, west, north-west
		/* dx= 0 */ {0, -1, 1024},        // south, (not moving), north
		/* dx=+1 */ {1792, 1536, 1280},   // south-east, east, north-east
	};

	private final EntityDefinition.WanderBox box;
	private final int plane;
	private final int baseOrientation;
	private final Random random;

	/** The tile the citizen is walking to over the current game tick. */
	private int x;
	private int y;

	/** The tile it left at the start of that step; equal to x,y while idle. */
	private int fromX;
	private int fromY;

	/** Where it is heading over the next several ticks. */
	private int destinationX;
	private int destinationY;

	private int idleTicks;
	private boolean moving;
	private int orientation;

	/**
	 * @param definition a definition whose {@link EntityDefinition#getWanderBox()}
	 *                   is not null
	 */
	private CitizenWalk(EntityDefinition definition, EntityDefinition.WanderBox box)
	{
		this.box = box;
		this.plane = box.getPlane();
		this.baseOrientation = definition.getOrientation();
		this.orientation = baseOrientation;

		// Seeded from the entity's identity, not from the clock. A citizen then
		// paces the same route every session, which is what makes
		// CitizenWalkTest able to assert anything at all about ten thousand
		// ticks — and which stops a city's traffic pattern being different every
		// login for no reason the player could ever see as intentional. The
		// mixing is already done by stableHash(), so nearby uuids do not produce
		// neighbouring seeds.
		this.random = new Random(definition.stableHash());

		this.x = definition.getWorldLocation().getX();
		this.y = definition.getWorldLocation().getY();
		this.fromX = x;
		this.fromY = y;
		this.destinationX = x;
		this.destinationY = y;
	}

	/**
	 * @return a walk for this entity, or {@code null} if it does not wander
	 */
	@Nullable
	static CitizenWalk forDefinition(EntityDefinition definition)
	{
		EntityDefinition.WanderBox box = definition.getWanderBox();
		return box == null ? null : new CitizenWalk(definition, box);
	}

	/**
	 * One game tick of walking: either take a step towards the destination, or
	 * count down to choosing a new one.
	 */
	void tick()
	{
		// Whatever happens, the step that was in flight is over: the drawn
		// position has caught up with the tile, and the next interpolation starts
		// from here.
		fromX = x;
		fromY = y;

		if (x == destinationX && y == destinationY)
		{
			moving = false;
			orientation = baseOrientation;

			if (++idleTicks < IDLE_TICKS_BEFORE_NEW_DESTINATION)
			{
				return;
			}

			idleTicks = 0;
			chooseDestination();

			if (x == destinationX && y == destinationY)
			{
				// It rolled the tile it is already standing on. Standing still for
				// another interval is the honest outcome; forcing a re-roll would
				// bias the destination away from the citizen's own tile.
				return;
			}
		}

		int dx = Integer.signum(destinationX - x);
		int dy = Integer.signum(destinationY - y);
		x += dx;
		y += dy;
		moving = true;
		orientation = STEP_ORIENTATION[dx + 1][dy + 1];
	}

	/**
	 * Where to draw the citizen right now.
	 *
	 * @param worldView the view the entity is being placed in
	 * @param fraction  how far through the current game tick this frame is, 0..1
	 * @return the interpolated local position, or {@code null} if the tile it is
	 * walking to is outside the loaded scene — the caller then leaves the object
	 * where it was rather than moving it somewhere meaningless
	 */
	@Nullable
	LocalPoint localPoint(WorldView worldView, float fraction)
	{
		LocalPoint to = LocalPoint.fromWorld(worldView, new WorldPoint(x, y, plane));
		if (to == null)
		{
			return null;
		}

		if (!moving || (fromX == x && fromY == y))
		{
			return to;
		}

		LocalPoint from = LocalPoint.fromWorld(worldView, new WorldPoint(fromX, fromY, plane));
		if (from == null)
		{
			// It stepped in from outside the scene. Snapping to the tile it is
			// walking to is one tile of pop, at the far edge of the render
			// distance, instead of a frame drawn at a stale position.
			return to;
		}

		float clamped = fraction < 0f ? 0f : (fraction > 1f ? 1f : fraction);
		int lx = from.getX() + Math.round((to.getX() - from.getX()) * clamped);
		int ly = from.getY() + Math.round((to.getY() - from.getY()) * clamped);

		// The (int, int, WorldView) constructor rather than passing an id: it is
		// the same one LocalPoint.fromScene uses, so the world view on the point
		// this returns matches the one on the points either side of it. That is
		// load-bearing — RuneLiteObject.setLocation deactivates and reactivates
		// the object whenever the point's world view differs from the object's,
		// so a mismatch here would churn the client's registered-object list
		// once per frame per citizen.
		return new LocalPoint(lx, ly, worldView);
	}

	/** @return the tile the citizen is on, or walking onto */
	WorldPoint currentTile()
	{
		return new WorldPoint(x, y, plane);
	}

	/** @return the tile the current step started from */
	WorldPoint stepStartTile()
	{
		return new WorldPoint(fromX, fromY, plane);
	}

	/** @return true while a step is in progress, i.e. this tick moved the citizen */
	boolean isMoving()
	{
		return moving;
	}

	/**
	 * @return the direction of travel while moving, and the authored
	 * {@code baseOrientation} while idle, both in 0..2047
	 */
	int getOrientation()
	{
		return orientation;
	}

	EntityDefinition.WanderBox getBox()
	{
		return box;
	}

	private void chooseDestination()
	{
		destinationX = box.getMinX() + random.nextInt(box.getWidth());
		destinationY = box.getMinY() + random.nextInt(box.getHeight());
	}
}

package com.matthewmariner.livelycities;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * The places the dataset covers, and the single source of truth for which region
 * ids belong to which of them.
 *
 * <p><b>Why an enum and not a table in the config interface.</b> RuneLite config
 * items are static declarations: {@code @ConfigItem} annotates a method on an
 * interface, so there is no way to generate one checkbox per city at runtime.
 * That forces 9 hand-written methods on {@link LivelyCitiesConfig} — but it does
 * not force the region lists to be written twice. They live here, once; each
 * constant knows which of those 9 methods is its own, through
 * {@link #enabledIn(LivelyCitiesConfig)}. So adding a region to a city is a
 * one-line change in one file, and {@code CityTest} fails if the two halves ever
 * stop lining up.
 *
 * <p><b>Why nine places and not twenty-four.</b> An earlier revision shipped 24,
 * and thirteen of them held one or two figures each — ten held exactly one, and
 * Varrock alone held 97 of the 181 entities. A city with one citizen is not
 * ambient life: it is a checkbox, a region file, a set of cache ids that break on
 * a game update, and a user who ticks "Canifis", sees one person, and concludes
 * the plugin is broken. The rule applied on 2026-08-24 was <b>a real city with at
 * least three figures</b>; fifteen places failed it and were removed outright,
 * dataset and all. Varrock is deliberately the dense flagship. Bringing the
 * thinner survivors up is content work, not a reason to keep shipping the thin
 * ones meanwhile.
 *
 * <p><b>Every id below was checked against a primary source</b> —
 * {@code ((x >> 6) << 8) | (y >> 6)} applied to the {@code {{Map}}} coordinates
 * in the corresponding OSRS Wiki {@code {{Infobox Location}}}, which is the same
 * arithmetic as {@link RenderPolicy#regionIdOf(int, int)}. {@code CityTest}
 * asserts that every shipped {@code RegionData} file maps to exactly one city, so
 * a new region file with no home fails the build instead of quietly becoming
 * untoggleable.
 *
 * <p><b>What that check caught.</b> An earlier revision shipped a "Digsite"
 * checkbox over regions 13109, 13110 and 13622, none of which contains the
 * Digsite: the Digsite's own map centre is (3354, 3420), which is region
 * <b>13365</b>, and the plugin ships no file for it. The same pass found the
 * Ranging Guild (10549) filed under Catherby, roughly 160 tiles away. 13109 is
 * still here, under Varrock, where the arithmetic put it; 13110, 13622 and 10549
 * have since been dropped from the dataset entirely as part of the nine-city cut,
 * so the only trace they leave is their retired {@code keyName}s. The
 * {@code cityDigsite} key stays retired rather than reused — see
 * {@link LivelyCitiesConfig} for why a {@code keyName} is permanent.
 *
 * <p><b>A vague label beats a confident wrong one.</b> Region 13109 has no
 * landmark of its own; it is the strip of road immediately outside Varrock's east
 * gate, and its one entity ("City workman") stands four tiles east of the city
 * wall. It is grouped under Varrock for that reason and not because anything
 * named "Varrock" sits in it.
 *
 * <p><b>An unmapped region stays visible.</b> {@link #isEnabled} answers
 * {@code true} for a region no constant claims. A region file can be added in one
 * commit and its checkbox in the next without the entities vanishing in between;
 * the test is what stops that grace period becoming permanent.
 */
@Slf4j
public enum City
{
	// The order here is the order the checkboxes appear in, so it is alphabetical
	// by display label rather than by region id.
	AL_KHARID("Al Kharid", LivelyCitiesConfig.KEY_AL_KHARID, 13105, 13106, 13361)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityAlKharid();
			}
		},
	ARDOUGNE("Ardougne", LivelyCitiesConfig.KEY_ARDOUGNE, 10290, 10548, 10804)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityArdougne();
			}
		},
	// 11061 and 11317 are the two halves of Catherby. Region 10549 (the Ranging
	// Guild, ~160 tiles west) was once filed in here by mistake; it was moved to a
	// checkbox of its own, and then dropped with the rest of the nine-city cut.
	CATHERBY("Catherby", LivelyCitiesConfig.KEY_CATHERBY, 11061, 11317)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityCatherby();
			}
		},
	DRAYNOR("Draynor", LivelyCitiesConfig.KEY_DRAYNOR, 12338, 12340)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityDraynor();
			}
		},
	EDGEVILLE("Edgeville", LivelyCitiesConfig.KEY_EDGEVILLE, 12342)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityEdgeville();
			}
		},
	FALADOR("Falador", LivelyCitiesConfig.KEY_FALADOR, 11828, 11829, 12083, 11571)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityFalador();
			}
		},
	GRAND_EXCHANGE("Grand Exchange", LivelyCitiesConfig.KEY_GRAND_EXCHANGE, 12598)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityGrandExchange();
			}
		},
	LUMBRIDGE("Lumbridge", LivelyCitiesConfig.KEY_LUMBRIDGE, 12850, 12594, 12595, 12849)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityLumbridge();
			}
		},
	/**
	 * The city's own six regions, plus 13109 — the strip east of the east gate.
	 * 13109 covers x 3264..3327, y 3392..3455, which starts one tile past the
	 * eastern wall (12853 ends at x 3263) and stops short of the Digsite's region
	 * (13365, x 3328..3391). Nothing in it has a name of its own; its single
	 * entity, a "City workman", stands at (3268, 3426), i.e. at the gate. Varrock
	 * is where it belongs for that reason and no stronger one.
	 */
	VARROCK("Varrock", LivelyCitiesConfig.KEY_VARROCK, 12853, 12852, 12854, 12597, 12596, 12697, 13109)
		{
			@Override
			boolean enabledIn(LivelyCitiesConfig config)
			{
				return config.cityVarrock();
			}
		};

	private static final Map<Integer, City> BY_REGION = index();

	private final String label;
	private final String configKey;
	private final int[] regionIds;

	City(String label, String configKey, int... regionIds)
	{
		this.label = label;
		this.configKey = configKey;
		this.regionIds = regionIds;
	}
	/**
	 * Which of the {@code enabledIn} config getters is this city's.
	 *
	 * <p>Abstract rather than a lambda field or a name-based lookup: the compiler
	 * then guarantees every constant answers, and {@code CityTest} composes this
	 * with a config whose 9 getters are individually distinguishable, so a
	 * copy-paste that points two cities at the same checkbox is a red test rather
	 * than a checkbox that quietly does someone else's job.
	 */
	abstract boolean enabledIn(LivelyCitiesConfig config);
	/**
	 * @param regionId a region id
	 * @return the city that claims it, or {@code null} if none does
	 */
	@Nullable
	public static City of(int regionId)
	{
		return BY_REGION.get(regionId);
	}
	/**
	 * Whether entities standing in a region should be shown.
	 *
	 * @return the city's checkbox, or {@code true} for a region no city claims —
	 * see the class javadoc for why an unmapped region fails open
	 */
	public static boolean isEnabled(int regionId, LivelyCitiesConfig config)
	{
		City city = BY_REGION.get(regionId);
		return city == null || city.enabledIn(config);
	}

	public String getLabel()
	{
		return label;
	}

	/**
	 * @return the {@code keyName} of this city's checkbox — the literal string
	 * RuneLite writes into the user's profile.
	 *
	 * <p><b>It is the same constant the {@code @ConfigItem} is annotated with</b>, not
	 * a second copy of it: {@link LivelyCitiesConfig#KEY_VARROCK} and friends are
	 * declared once and referenced from both sides. A {@code keyName} is permanent —
	 * renaming one silently resets that setting for every user who had it — so the
	 * thing to avoid is not a wrong string, it is <i>two</i> strings, one of which can
	 * be changed without the other. There is only one here.
	 *
	 * <p>This exists because {@link LivelyCitiesPanel} writes these checkboxes.
	 * {@link #enabledIn(LivelyCitiesConfig)} answers "is it on?" and cannot answer
	 * "what do I write to turn it off?" — a config getter is a method, and
	 * {@link ConfigWriter} needs the key.
	 */
	public String getConfigKey()
	{
		return configKey;
	}
	/**
	 * @return this city's region ids. A copy: the array is the enum's state, and
	 * handing out the original would let a caller edit the mapping.
	 */
	public int[] getRegionIds()
	{
		return regionIds.clone();
	}

	@Override
	public String toString()
	{
		return label;
	}
	/**
	 * Builds the region lookup.
	 *
	 * <p>Fail-soft on a duplicate — first constant wins, with a loud line —
	 * because the rest of this plugin refuses to lose a city over one bad record
	 * and a static initialiser that throws would lose all of them. The build-time
	 * guard is {@code CityTest}, which walks the constants' own arrays rather than
	 * this map, so it sees the collision this method swallows.
	 */
	private static Map<Integer, City> index()
	{
		Map<Integer, City> byRegion = new HashMap<>();
		for (City city : values())
		{
			for (int regionId : city.regionIds)
			{
				City clash = byRegion.put(regionId, city);
				if (clash != null && clash != city)
				{
					log.error("Lively Cities: region {} is claimed by both {} and {} — keeping {}",
						regionId, clash.label, city.label, clash.label);
					byRegion.put(regionId, clash);
				}
			}
		}
		return Collections.unmodifiableMap(byRegion);
	}
}

package com.matthewmariner.livelycities;

/**
 * How much of the roster to show.
 *
 * <p><b>There is no density field in the dataset</b>, and inventing one would
 * mean editing 27 vendored files. So this is proportional thinning instead: each
 * level keeps a percentage of the entities, and every entity's own identity
 * decides whether it is one of them.
 *
 * <p><b>Why the decision is a hash and not a random number.</b> The choice has to
 * come out the same every time it is asked, for three separate reasons:
 * <ul>
 *   <li>The visibility pass runs every game tick. A coin flip per pass would
 *       make the whole crowd strobe at 1.6 Hz.</li>
 *   <li>Even a per-session draw is wrong: the same street would be populated by
 *       different people after every login, and after every hop and every
 *       region-cache eviction, because the wrappers are rebuilt. The point of
 *       thinning a city is a quieter city, not a different city each time you
 *       walk down the same road.</li>
 *   <li>A hash of a stable id is testable. {@code CrowdDensityTest} can assert
 *       both the proportion and the exact verdict for a known uuid, which a
 *       {@code Random} — even a seeded one — cannot offer without pinning an
 *       implementation detail of the JDK's generator.</li>
 * </ul>
 *
 * <p>The hash is {@link EntityDefinition#stableHash()}, derived from the record's
 * uuid, so it survives restarts, evictions and reorderings of the region files.
 *
 * <p>The levels nest: everything {@link #SPARSE} keeps, {@link #NORMAL} keeps
 * too. That falls out of comparing one bucket against a rising threshold rather
 * than hashing per level, and it means turning the dial up only ever adds people
 * — it never swaps one crowd for another.
 *
 * <p><b>{@link #CROWDED} is the one level that adds rather than subtracts</b>, and
 * it is deliberately not a fourth percentage. Thinning can only ever remove
 * authored citizens, so there is no percentage above 100 to ask for; going the
 * other way needs citizens that are not in the dataset, which is
 * {@link CitizenEcho}'s job. So {@link #getKeepPercent()} is 100 for both
 * {@link #FULL} and {@link #CROWDED} — they keep the same authored roster, which is
 * all of it — and the difference between them is the separate, boolean
 * {@link #includesEchoes()}. Two questions, two accessors: "how much of the roster"
 * and "and the derived ones as well?".
 */
public enum CrowdDensity
{
	/**
	 * Everything {@link #FULL} shows, plus the procedurally-derived echoes. Opt-in, and
	 * the only level that shows an entity the dataset does not contain.
	 *
	 * <p><b>How many more is not a fixed proportion and this javadoc used to say it
	 * was.</b> It read "roughly twice as many citizens", which was the original request
	 * and stopped being true when {@link CitizenEcho}'s flesh and body rules landed; the
	 * user-facing description on {@code LivelyCitiesConfig.crowdDensity} was corrected
	 * and this was not. Only a citizen whose own colours can be re-dealt honestly seeds
	 * anything, so the figure is a property of the dataset rather than of this enum —
	 * {@link CitizenEcho}'s javadoc carries it, and {@code CitizenEchoTest} recomputes
	 * it from the shipped files.
	 *
	 * <p>Listed first so the dropdown reads densest-to-sparsest. It is a strict
	 * superset of {@link #FULL} for the same reason every other level nests: the
	 * authored roster is untouched and the echoes are added on top, so turning the
	 * dial up here cannot make an authored citizen disappear.
	 */
	CROWDED("Crowded", 100, true),

	/** No thinning at all, and no additions: the dial's "off" position. */
	FULL("Full", 100, false),

	/** Roughly two thirds of the roster. */
	NORMAL("Normal", 66, false),

	/** Roughly a third of the roster. */
	SPARSE("Sparse", 33, false);

	/** Buckets the hash is spread over; the percentage is a count of buckets. */
	private static final int BUCKETS = 100;

	private final String label;
	private final int keepPercent;
	private final boolean echoes;

	CrowdDensity(String label, int keepPercent, boolean echoes)
	{
		this.label = label;
		this.keepPercent = keepPercent;
		this.echoes = echoes;
	}

	/**
	 * @return what share of the <b>authored</b> roster this level keeps. Never above
	 * 100 — see the class javadoc for why the extra citizens are not expressed here.
	 */
	public int getKeepPercent()
	{
		return keepPercent;
	}

	/**
	 * @return whether this level also shows {@link CitizenEcho}'s derived citizens.
	 * True for {@link #CROWDED} and nothing else, which is what makes the feature
	 * purely additive and purely opt-in: {@link #FULL} still yields exactly the
	 * authored set and nothing more.
	 */
	public boolean includesEchoes()
	{
		return echoes;
	}

	/**
	 * @param stableHash the entity's {@link EntityDefinition#stableHash()}
	 * @return whether this level keeps that entity
	 */
	public boolean keeps(long stableHash)
	{
		if (keepPercent >= BUCKETS)
		{
			// Not just an optimisation: it guarantees FULL keeps everything
			// regardless of how the buckets are spread.
			return true;
		}

		return Math.floorMod(stableHash, (long) BUCKETS) < keepPercent;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.matthewmariner.livelycities;

import com.matthewmariner.livelycities.data.EntityRecord;
import com.matthewmariner.livelycities.data.MergedObjectRecord;
import com.matthewmariner.livelycities.data.PointRecord;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * A validated, render-ready entity — everything the spawner needs and nothing
 * that still has to be checked.
 *
 * <p>{@link #fromRecord(EntityRecord, int)} is the only gate between the JSON
 * and the scene, and it is deliberately fail-soft in two different ways:
 *
 * <ul>
 *   <li><b>Skip</b> (returns null + warn) only when the record cannot possibly
 *       render: no known type, no location, or neither a usable model nor a
 *       plausible {@code npcAppearanceId}.</li>
 *   <li><b>Degrade</b> (keeps the entity + warn) for everything else: an unknown
 *       animation name becomes a static model, a lopsided recolour pair list is
 *       truncated to the matched pairs, a malformed scale/translate is dropped.</li>
 * </ul>
 *
 * <p>What it never does is reject the whole region. The predecessor gated on
 * {@code version != 0.8f} and returned null for the entire file, so one bumped
 * version number silently emptied a city.
 */
@Slf4j
public final class EntityDefinition
{
	private static final int JAU_FULL_ROTATION = 2048;
	private static final int MAX_PLANE = 3;

	/** Shared, so 257 of the 311 entities do not each allocate an empty array. */
	private static final String[] NO_REMARKS = new String[0];

	private final UUID uuid;
	private final int regionId;
	private final int tileRegionId;
	private final int cityRegionId;
	private final EntityType type;
	private final String name;
	private final String examineText;
	private final String[] remarks;
	private final WorldPoint worldLocation;
	private final int orientation;
	private final int[] modelIds;

	/**
	 * The NPC whose appearance this entity wears, or {@code 0} for one dressed from
	 * {@link #modelIds}.
	 *
	 * <p>Resolved at spawn time rather than here — it needs a {@link net.runelite.api.Client},
	 * and this class is deliberately client-free so the whole dataset can be
	 * validated without a game running. See {@link NpcAppearance}.
	 */
	private final int npcAppearanceId;

	/** See {@link #isCameo()}. */
	private final boolean cameo;

	/** See {@link #isNoEcho()}. */
	private final boolean noEcho;

	private final short[] recolorFind;
	private final short[] recolorReplace;
	private final float[] scale;
	private final float[] translate;
	private final List<MergedObject> mergedObjects;
	private final LivelyAnimation idleAnimation;
	private final LivelyAnimation moveAnimation;
	private final WanderBox wanderBox;

	/**
	 * The uuid of the authored citizen this one was derived from, or {@code null}
	 * for an authored entity — which is what {@link #isEcho()} reads.
	 *
	 * <p>Kept rather than merely used once, because "which citizen is this a copy
	 * of?" is the question a log line and a test both want to ask, and rederiving
	 * it is impossible: the derivation is one-way (see {@link CitizenEcho}).
	 */
	@Nullable
	private final UUID echoSourceUuid;

	/**
	 * For an echo only: whether its tile came from inside its source's authored
	 * wander box, i.e. from ground a human already decided a citizen could pace.
	 *
	 * <p>This is the fallback signal {@link CitizenEcho} falls back <i>to</i> when
	 * the live collision map has no answer. Always {@code false} for an authored
	 * entity, which never consults either.
	 */
	private final boolean echoOnAuthoredGround;

	private EntityDefinition(
		UUID uuid,
		int regionId,
		int tileRegionId,
		int cityRegionId,
		EntityType type,
		@Nullable String name,
		@Nullable String examineText,
		String[] remarks,
		WorldPoint worldLocation,
		int orientation,
		int[] modelIds,
		int npcAppearanceId,
		boolean cameo,
		boolean noEcho,
		short[] recolorFind,
		short[] recolorReplace,
		@Nullable float[] scale,
		@Nullable float[] translate,
		List<MergedObject> mergedObjects,
		@Nullable LivelyAnimation idleAnimation,
		@Nullable LivelyAnimation moveAnimation,
		@Nullable WanderBox wanderBox,
		@Nullable UUID echoSourceUuid,
		boolean echoOnAuthoredGround)
	{
		this.echoSourceUuid = echoSourceUuid;
		this.echoOnAuthoredGround = echoOnAuthoredGround;
		this.uuid = uuid;
		this.regionId = regionId;
		this.tileRegionId = tileRegionId;
		this.cityRegionId = cityRegionId;
		this.type = type;
		this.name = name;
		this.examineText = examineText;
		this.remarks = remarks;
		this.worldLocation = worldLocation;
		this.orientation = orientation;
		this.modelIds = modelIds;
		this.npcAppearanceId = npcAppearanceId;
		this.cameo = cameo;
		this.noEcho = noEcho;
		this.recolorFind = recolorFind;
		this.recolorReplace = recolorReplace;
		this.scale = scale;
		this.translate = translate;
		this.mergedObjects = mergedObjects;
		this.idleAnimation = idleAnimation;
		this.moveAnimation = moveAnimation;
		this.wanderBox = wanderBox;
	}

	/**
	 * Validates one parsed roster entry.
	 *
	 * @param record       the parsed record, may be null
	 * @param fileRegionId the region id the containing file is named after —
	 *                     authoritative for identity, because the file name is
	 *                     what the loader keys on. Where the entity actually
	 *                     stands is a separate question, answered by
	 *                     {@link #getTileRegionId()}
	 * @return a render-ready definition, or {@code null} if the record is
	 * unusable. Never throws.
	 */
	@Nullable
	public static EntityDefinition fromRecord(@Nullable EntityRecord record, int fileRegionId)
	{
		if (record == null)
		{
			log.warn("region {}: null roster entry skipped", fileRegionId);
			return null;
		}

		String label = describe(record, fileRegionId);

		EntityType type = EntityType.fromName(record.entityType);
		if (type == null)
		{
			log.warn("{}: unknown entityType '{}', skipped", label, record.entityType);
			return null;
		}

		WorldPoint location = toWorldPoint(record.worldLocation);
		if (location == null)
		{
			log.warn("{}: missing or invalid worldLocation, skipped", label);
			return null;
		}

		// Two ways of being dressed, and exactly one of them has to work out. The
		// NPC id is only a *claim* here — whether it resolves is a question for a
		// live cache, and LivelyEntity asks it — so what this gate checks is that
		// the record named a plausible one, the same standard the offline audit
		// holds a modelId to.
		int npcAppearanceId = npcAppearanceId(record.npcAppearanceId, label);
		int[] modelIds = usableModelIds(record.modelIds, label);
		if (npcAppearanceId == 0 && modelIds.length == 0)
		{
			log.warn("{}: no usable modelIds and no npcAppearanceId, skipped", label);
			return null;
		}

		if (npcAppearanceId != 0 && modelIds.length > 0)
		{
			// Both. The NPC appearance wins, models and recolours alike — see
			// EntityRecord.npcAppearanceId. Loud rather than silent: carrying both is
			// an authoring mistake, and the half that is ignored is the half a human
			// typed.
			log.warn("{}: carries both npcAppearanceId {} and {} modelIds — the NPC appearance wins, "
					+ "the modelIds and any modelRecolor* are ignored",
				label, npcAppearanceId, modelIds.length);
		}

		if (record.regionId != null && record.regionId != fileRegionId)
		{
			log.warn("{}: record claims regionId {} but lives in {}.json — using {}",
				label, record.regionId, fileRegionId, fileRegionId);
		}

		// The record's own regionId field is a claim; the tile is the fact. The
		// two disagree in the shipped data — "Dark wizard" is filed under 12853
		// and stands in 12852 — and it is the tile that decides whether the
		// client has the region loaded, so the scene keys visibility on this and
		// not on the file name.
		int tileRegionId = RenderPolicy.regionIdOf(location.getX(), location.getY());
		if (tileRegionId != fileRegionId)
		{
			log.warn("{}: tile {},{} is in region {}, not the {} its file is named after — "
					+ "it can only be found while region {} is in the scene too",
				label, location.getX(), location.getY(), tileRegionId, fileRegionId, fileRegionId);
		}

		UUID uuid = parseUuid(record.uuid, label);
		int orientation = orientation(record.baseOrientation, label);

		int pairs = recolorPairCount(record, label);
		short[] find = new short[pairs];
		short[] replace = new short[pairs];
		for (int i = 0; i < pairs; i++)
		{
			find[i] = (short) record.modelRecolorFind[i];
			replace[i] = (short) record.modelRecolorReplace[i];
		}

		LivelyAnimation idle = animation(record.idleAnimation, "idleAnimation", label);
		LivelyAnimation move = animation(record.moveAnimation, "moveAnimation", label);

		return new EntityDefinition(
			uuid,
			fileRegionId,
			tileRegionId,
			// An authored entity answers to the city containing the tile it stands on,
			// and it is the only kind of entity that answers for itself.
			tileRegionId,
			type,
			record.name,
			record.examineText,
			usableRemarks(record.remarks, type, label),
			location,
			orientation,
			modelIds,
			npcAppearanceId,
			cameo(record, type, label),
			record.noEcho != null && record.noEcho,
			find,
			replace,
			vector3(record.scale, "scale", label),
			vector3(record.translate, "translate", label),
			mergedObjects(record.mergedObjects, label),
			idle,
			move,
			wanderBox(record, type, location, label),
			null,
			false);
	}

	/**
	 * Builds one procedurally-derived citizen — an "echo" — from an authored one.
	 *
	 * <p>Every decision behind the arguments is {@link CitizenEcho}'s; this method
	 * only assembles them, so that the one place that may construct an
	 * {@link EntityDefinition} stays this class. What it does add is the three things
	 * that are properties of <i>being</i> a definition rather than of being an echo:
	 * the tile's own region id (recomputed, because an echo can stand a few tiles
	 * over a region border exactly like the shipped "Dark wizard" does), the region
	 * whose city checkbox governs it (its <b>source's</b> — see
	 * {@link #getCityRegionId()}, and it is emphatically not the recomputed one), and
	 * the {@link EntityType#StationaryCitizen} type.
	 *
	 * <p><b>The type is forced rather than inherited</b>, and that is the whole of
	 * "echoes do not wander": {@link CitizenWalk#forDefinition} needs a
	 * {@link WanderBox}, {@code wanderBox} is always {@code null} here, and a
	 * {@code WanderingCitizen} that stands still would be a lie in every log line.
	 *
	 * <p>What is inherited is the body: model ids, merged objects, scale, translate
	 * and the idle animation. What is not: the name, the examine text, the remarks
	 * (an echo is silent — see {@link CitizenEcho}), the move animation (nothing
	 * moves), and the recolour, which is the source's own palette re-dealt.
	 *
	 * @param source               the authored citizen this is derived from
	 * @param uuid                 the echo's own uuid, derived from the source's
	 * @param tile                 the echo's tile, already at least
	 *                             {@link CitizenEcho#MIN_SEPARATION_TILES} from the
	 *                             source and from its siblings
	 * @param orientation          already inside 0..2047
	 * @param recolorFind          the source's find array, as-is
	 * @param recolorReplace       the source's replace array, re-dealt
	 * @param name                 an honestly generic name — never the source's
	 * @param examineText          truthful about what this is — never the source's
	 * @param onAuthoredGround     whether {@code tile} came from inside the source's
	 *                             authored wander box
	 */
	static EntityDefinition echoOf(
		EntityDefinition source,
		UUID uuid,
		WorldPoint tile,
		int orientation,
		short[] recolorFind,
		short[] recolorReplace,
		String name,
		String examineText,
		boolean onAuthoredGround)
	{
		return new EntityDefinition(
			uuid,
			source.regionId,
			RenderPolicy.regionIdOf(tile.getX(), tile.getY()),
			// Its source's city, not its own tile's. See getCityRegionId().
			source.cityRegionId,
			EntityType.StationaryCitizen,
			name,
			examineText,
			NO_REMARKS,
			tile,
			orientation,
			source.modelIds,
			source.npcAppearanceId,
			// Never a cameo, however it was derived. An echo carries none of its
			// source's identity (see CitizenEcho), so it cannot be a likeness of
			// anybody — and inheriting the flag would put an extra body next to a
			// cameo whenever the cameos checkbox happened to be on. The stronger half
			// of the same guarantee is that CitizenEcho refuses to derive anything
			// from a cameo at all, so this line is unreachable for a cameo source;
			// it is written down because "an echo is not a cameo" is a property of
			// being an echo, and a future second derivation path would need it too.
			false,
			// An echo never seeds an echo of its own, so this flag has nothing left to
			// govern by the time it would be read. It is set true rather than false
			// because that is the truthful value — CitizenEcho.echoesOfSource refuses
			// an echo on its first line, and a flag that said "derive from me" while
			// nothing can would be a second, disagreeing statement of the same fact.
			true,
			recolorFind,
			recolorReplace,
			source.scale == null ? null : source.scale.clone(),
			source.translate == null ? null : source.translate.clone(),
			source.mergedObjects,
			source.idleAnimation,
			null,
			null,
			source.uuid,
			onAuthoredGround);
	}

	/**
	 * Validates a wandering citizen's patrol box.
	 *
	 * <p>Degrades to {@code null} — i.e. the citizen spawns and stands still —
	 * rather than skipping the record, for every failure. Same reasoning as the
	 * unknown-animation case: a citizen standing in the right place beats no
	 * citizen.
	 *
	 * <p>The clamp at the end is the only place that enforces
	 * {@link RenderPolicy#DATASET_OVERHANG_ALLOWANCE}. The cull check measures
	 * from {@code base}, so a box that reached much further would let a citizen
	 * wander an unbounded distance from the tile the crowd cap and the render
	 * distance were both computed about. Clamping bounds that disagreement for any
	 * dataset rather than merely for this one. It does <b>not</b> keep the citizen
	 * inside the loaded scene — nothing can, see
	 * {@link RenderPolicy#SUSTAINED_SCENE_RADIUS} — and a step onto unloaded ground
	 * is handled where it happens: {@code LocalPoint.fromWorld} returns null and
	 * {@link CitizenWalk#localPoint} leaves the citizen where it was.
	 *
	 * @return the box, or {@code null} for a non-wanderer or an unusable box
	 */
	@Nullable
	private static WanderBox wanderBox(
		EntityRecord record,
		EntityType type,
		WorldPoint base,
		String label)
	{
		if (type != EntityType.WanderingCitizen)
		{
			// ScriptedCitizens carry a startScript, not a box, and L3 leaves them
			// stationary — see the comment in CitizenWalk.
			return null;
		}

		PointRecord bl = record.wanderBoxBL;
		PointRecord tr = record.wanderBoxTR;
		if (bl == null || tr == null
			|| bl.x == null || bl.y == null || tr.x == null || tr.y == null
			|| bl.x <= 0 || bl.y <= 0 || tr.x <= 0 || tr.y <= 0)
		{
			log.warn("{}: WanderingCitizen with no usable wanderBox — spawning it stationary", label);
			return null;
		}

		if (!samePlane(bl, base) || !samePlane(tr, base))
		{
			// A box on another storey is not a walk, it is a fall.
			log.warn("{}: wanderBox is on plane {}/{} but the citizen stands on {} — spawning it stationary",
				label, bl.plane, tr.plane, base.getPlane());
			return null;
		}

		int minX = Math.min(bl.x, tr.x);
		int maxX = Math.max(bl.x, tr.x);
		int minY = Math.min(bl.y, tr.y);
		int maxY = Math.max(bl.y, tr.y);

		if (base.getX() < minX || base.getX() > maxX || base.getY() < minY || base.getY() > maxY)
		{
			// Growing the box to swallow the start tile would quietly widen the
			// authored patrol, and walking the citizen to the nearest corner first
			// would teleport it. Neither is worth it for a case the shipped data
			// does not contain.
			log.warn("{}: stands outside its own wanderBox {},{}..{},{} — spawning it stationary",
				label, minX, minY, maxX, maxY);
			return null;
		}

		int allowance = RenderPolicy.DATASET_OVERHANG_ALLOWANCE;
		int clampedMinX = Math.max(minX, base.getX() - allowance);
		int clampedMaxX = Math.min(maxX, base.getX() + allowance);
		int clampedMinY = Math.max(minY, base.getY() - allowance);
		int clampedMaxY = Math.min(maxY, base.getY() + allowance);

		if (clampedMinX != minX || clampedMaxX != maxX || clampedMinY != minY || clampedMaxY != maxY)
		{
			log.warn("{}: wanderBox {},{}..{},{} reaches further than {} tiles from the tile its cull "
					+ "check is measured from — clamped to {},{}..{},{} to keep the walk near the tile "
					+ "the render distance was measured about",
				label, minX, minY, maxX, maxY, allowance,
				clampedMinX, clampedMinY, clampedMaxX, clampedMaxY);
		}

		if (clampedMinX == clampedMaxX && clampedMinY == clampedMaxY)
		{
			log.debug("{}: wanderBox is a single tile — spawning it stationary", label);
			return null;
		}

		return new WanderBox(clampedMinX, clampedMinY, clampedMaxX, clampedMaxY, base.getPlane());
	}

	private static boolean samePlane(PointRecord corner, WorldPoint base)
	{
		return corner.plane != null && corner.plane == base.getPlane();
	}

	@Nullable
	private static WorldPoint toWorldPoint(@Nullable PointRecord point)
	{
		if (point == null || point.x == null || point.y == null || point.plane == null)
		{
			return null;
		}

		if (point.x <= 0 || point.y <= 0 || point.plane < 0 || point.plane > MAX_PLANE)
		{
			return null;
		}

		return new WorldPoint(point.x, point.y, point.plane);
	}

	/**
	 * Validates the optional {@code npcAppearanceId}.
	 *
	 * <p>Degrades to {@code 0} ("not set") rather than skipping the record, so a
	 * record carrying both a junk NPC id and a usable {@code modelIds} array still
	 * spawns from its models. A record carrying only the junk id is skipped by the
	 * caller's gate, which is the same outcome as a record with no models.
	 *
	 * <p>Bounded by {@link CacheIdPlausibility}, the same ceiling the offline audit
	 * holds a model id to — and it is a real bound here rather than a formality:
	 * {@code gameval.NpcID}'s highest constant in 1.12.36 is 16346, so a pasted
	 * hashcode in this field is caught before the client is ever asked about it.
	 *
	 * @return the id, or {@code 0} for absent/unusable
	 */
	private static int npcAppearanceId(@Nullable Integer raw, String label)
	{
		if (raw == null)
		{
			return 0;
		}

		if (!CacheIdPlausibility.isPlausible(raw))
		{
			log.warn("{}: npcAppearanceId {} is not a plausible cache id — ignoring it", label, raw);
			return 0;
		}

		return raw;
	}

	/**
	 * Whether this record is a cameo — see {@link EntityRecord#cameo} and
	 * {@link #isCameo()}.
	 *
	 * <p>Refused for scenery, and loudly. The flag's whole job is to keep
	 * player-shaped named likenesses behind an opt-in, and a crate is neither; a
	 * crate carrying it would be a crate a checkbox nobody expects switches off.
	 * Same reasoning, and the same place, as {@link #usableRemarks} silencing a
	 * talking crate.
	 */
	private static boolean cameo(EntityRecord record, EntityType type, String label)
	{
		if (record.cameo == null || !record.cameo)
		{
			return false;
		}

		if (!type.isCitizen())
		{
			log.warn("{}: {} is not a citizen but is flagged as a cameo — ignoring the flag", label, type);
			return false;
		}

		return true;
	}

	private static int[] usableModelIds(@Nullable int[] ids, String label)
	{
		if (ids == null || ids.length == 0)
		{
			return new int[0];
		}

		int[] kept = new int[ids.length];
		int n = 0;
		for (int id : ids)
		{
			if (id <= 0)
			{
				log.warn("{}: dropping non-positive model id {}", label, id);
				continue;
			}
			kept[n++] = id;
		}

		if (n == ids.length)
		{
			return ids;
		}

		int[] trimmed = new int[n];
		System.arraycopy(kept, 0, trimmed, 0, n);
		return trimmed;
	}

	/**
	 * The one-liners this entity may say, with the four ways of having nothing to
	 * say flattened into one empty array.
	 *
	 * <p>All four occur in the shipped data: 54 citizens carry remarks, 183 carry
	 * {@code "remarks": []}, 32 carry no {@code remarks} field at all — 54 + 183 + 32
	 * being the 269 shipped citizens — and all 42 scenery records omit it.
	 * {@link CitizenRemarks#forDefinition} then has one condition to check rather
	 * than four, and {@link CitizenChatter} never has to ask what kind of silence it
	 * is looking at. {@code CitizenRemarksTest} recomputes the partition from the
	 * shipped files, so a split that no longer adds up fails the build.
	 *
	 * <p><b>Scenery is silenced here rather than downstream.</b> A talking crate is
	 * an authoring mistake, and the place to refuse it is the validation gate — the
	 * alternative is every later reader remembering to ask
	 * {@code getType().isCitizen()} first, and one of them eventually not.
	 *
	 * <p>Degrades rather than skipping, like every other soft failure in this class:
	 * a blank or null entry is dropped and the rest are kept, because a citizen with
	 * two of its three lines is a working citizen.
	 */
	private static String[] usableRemarks(@Nullable String[] raw, EntityType type, String label)
	{
		if (raw == null || raw.length == 0)
		{
			return NO_REMARKS;
		}

		if (!type.isCitizen())
		{
			log.debug("{}: {} is not a citizen but carries {} remark(s) — ignoring them",
				label, type, raw.length);
			return NO_REMARKS;
		}

		String[] kept = new String[raw.length];
		int n = 0;
		for (String remark : raw)
		{
			if (remark == null || remark.trim().isEmpty())
			{
				continue;
			}
			kept[n++] = remark.trim();
		}

		if (n == 0)
		{
			log.warn("{}: every one of its {} remark(s) was blank — it will not talk",
				label, raw.length);
			return NO_REMARKS;
		}

		if (n < raw.length)
		{
			log.warn("{}: dropped {} blank remark(s), keeping {}", label, raw.length - n, n);
		}

		if (n == raw.length)
		{
			return kept;
		}

		String[] trimmed = new String[n];
		System.arraycopy(kept, 0, trimmed, 0, n);
		return trimmed;
	}

	private static int recolorPairCount(EntityRecord record, String label)
	{
		int findLen = record.modelRecolorFind == null ? 0 : record.modelRecolorFind.length;
		int replaceLen = record.modelRecolorReplace == null ? 0 : record.modelRecolorReplace.length;

		if (findLen != replaceLen)
		{
			log.warn("{}: recolour arrays are {} find vs {} replace — using the first {} pair(s)",
				label, findLen, replaceLen, Math.min(findLen, replaceLen));
		}

		return Math.min(findLen, replaceLen);
	}

	private static UUID parseUuid(@Nullable String raw, String label)
	{
		if (raw != null && !raw.trim().isEmpty())
		{
			try
			{
				return UUID.fromString(raw.trim());
			}
			catch (IllegalArgumentException e)
			{
				log.warn("{}: uuid '{}' is not a UUID, generating one", label, raw);
			}
		}
		else
		{
			log.warn("{}: no uuid, generating one", label);
		}

		return UUID.randomUUID();
	}

	private static int orientation(@Nullable Integer raw, String label)
	{
		if (raw == null)
		{
			return 0;
		}

		int wrapped = ((raw % JAU_FULL_ROTATION) + JAU_FULL_ROTATION) % JAU_FULL_ROTATION;
		if (wrapped != raw)
		{
			log.warn("{}: baseOrientation {} is outside 0..{}, wrapped to {}",
				label, raw, JAU_FULL_ROTATION - 1, wrapped);
		}

		return wrapped;
	}

	@Nullable
	private static LivelyAnimation animation(@Nullable String raw, String field, String label)
	{
		if (raw == null || raw.trim().isEmpty())
		{
			return null;
		}

		LivelyAnimation resolved = LivelyAnimation.fromName(raw);
		if (resolved == null)
		{
			log.warn("{}: unknown {} '{}' — spawning without it", label, field, raw);
		}

		return resolved;
	}

	@Nullable
	private static float[] vector3(@Nullable float[] raw, String field, String label)
	{
		if (raw == null)
		{
			return null;
		}

		if (raw.length != 3)
		{
			log.warn("{}: {} has {} components, expected 3 — ignoring it", label, field, raw.length);
			return null;
		}

		return new float[]{raw[0], raw[1], raw[2]};
	}

	private static List<MergedObject> mergedObjects(@Nullable List<MergedObjectRecord> raw, String label)
	{
		if (raw == null || raw.isEmpty())
		{
			return Collections.emptyList();
		}

		List<MergedObject> out = new ArrayList<>(raw.size());
		for (MergedObjectRecord entry : raw)
		{
			if (entry == null || entry.objectId == null || entry.objectId <= 0)
			{
				log.warn("{}: dropping mergedObject with no usable objectID", label);
				continue;
			}

			int rotations = entry.count90CCWRotations == null ? 0 : entry.count90CCWRotations;
			if (rotations < 0)
			{
				log.warn("{}: mergedObject {} has {} rotations, treating as 0",
					label, entry.objectId, rotations);
				rotations = 0;
			}

			out.add(new MergedObject(entry.objectId, rotations % 4));
		}

		return Collections.unmodifiableList(out);
	}

