import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;

/**
 * The sidebar: which places are populated, what is on screen right now, and the way
 * back from every "Hide" and "Mute" you have ever clicked.
 *
 * <p>The surface the plugin was missing. Nine identical checkboxes in a settings screen
 * can say whether Falador is on; they cannot say that Falador holds 26 citizens, that
 * eleven of them are in front of you, or that the reason the street looks thin is the
 * density dial two sections up. And they cannot offer the one thing the config screen
 * structurally cannot: a row per citizen you hid, with a way to bring back <em>that</em>
 * one. RuneLite config items are annotations on interface methods, fixed at compile
 * time, so a control keyed on a uuid out of a data file has never been possible there —
 * which is why the only undo the plugin shipped was "unhide all", a button that undoes
 * every decision you ever made in order to undo the one you regret.
 *
 * <h2>It decides nothing</h2>
 *
 * <p>Every number on it comes out of {@link PanelModel}, which is composed on the
 * client thread and is static, offline and under test. Every click leaves through
 * {@link LivelyCitiesPlugin} and lands in {@link ConfigWriter}, so the config remains
 * the source of truth and everything this panel does round-trips through the settings
 * screen. What is left here is layout and mouse handling, which is the part no test can
 * reach without a windowing system, and keeping it to that is deliberate — see
 * {@link SidePanel}.
 *
 * <h2>Two threads meet here and neither wanders</h2>
 *
 * <p>{@link #accept} is called from the client thread and hands straight to Swing.
 * Everything below it runs on the event dispatch thread and touches no client API at
 * all: a {@code Client} read off the client thread throws {@code IllegalStateException}
 * in a shipped client, and the numbers that need one have already been read by the time
 * they arrive here. Clicks go the other way and need no marshalling, because
 * {@code ConfigManager} is thread-safe and is what RuneLite's own settings panel writes
 * through from this very thread.
 *
 * <h2>Why it updates in place</h2>
 *
 * <p>A model arrives once a game tick while the panel is open. Rebuilding every
 * component each time — which is what a search-results panel should do — would rebuild
 * the row under the cursor 100 times a minute, losing its hover state and, on the tick
 * between the press and the release, the click itself. So the nine city cards are built
 * once and repainted from the model, and the override rows are rebuilt only when the
 * set of rows actually changes. {@link #signature} is what decides that.
 */
class LivelyCitiesPanel extends PluginPanel
{
	/**
	 * The colour of a heading, a live figure, and anything that is switched on.
	 *
	 * <p>Aliased rather than used directly so that "this panel has one accent" is a
	 * fact about the file rather than a habit — and so the accent can never drift into
	 * a hardcoded hex, which is the standing rule across this author's projects. Every
	 * colour below is a {@link ColorScheme} constant; there is no {@code new Color} in
	 * this file.
	 */
	private static final Color ACCENT = ColorScheme.BRAND_ORANGE;

	private static final Color BODY = ColorScheme.TEXT_COLOR;
	private static final Color SUBTLE = ColorScheme.LIGHT_GRAY_COLOR;

	/**
	 * The detail line under a heading, and anything greyed because it is off or empty.
	 *
	 * <p>{@code ColorScheme.MEDIUM_GRAY_COLOR} until it was measured: RGB(77,77,77) on
	 * this panel's RGB(30,30,30) card is a contrast ratio under 2:1, against WCAG's 4.5:1
	 * floor for body text — not dim, unreadable. {@code LIGHT_GRAY_COLOR} is the same
	 * value {@link #SUBTLE} already used for a legible secondary tone, which is what
	 * "helper" text actually needs to be to do its job.
	 */
	private static final Color HELPER = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color CARD_HOVER = ColorScheme.DARKER_GRAY_HOVER_COLOR;
	private static final Color BACKDROP = ColorScheme.DARK_GRAY_COLOR;

	private final LivelyCitiesPlugin plugin;

	private final IconTextField search = new IconTextField();

	private final JLabel whereValue = new JLabel();
	private final JLabel activeValue = new JLabel();
	private final JLabel detailValue = new JLabel();

	private final Map<CrowdDensity, JLabel> densityChips = new LinkedHashMap<>();
	private final Map<City, CityCard> cityCards = new LinkedHashMap<>();

	/**
	 * The strut that follows each card, so the filter can take it away with the card.
	 *
	 * <p>A spacer is not laid out by its neighbours — it is a fixed few pixels whatever is
	 * on either side of it — so hiding only the card left its gap behind. Filtering to one
	 * place left eight 4px voids under it.
	 */
	private final Map<City, JPanel> cityGaps = new LinkedHashMap<>();

	private final JPanel cities = new JPanel();
	private final JPanel overrides = new JPanel();
	private final JLabel overridesHeader = new JLabel();
	private final JLabel overridesEmpty = new JLabel();

	/**
	 * The last model handed over, redrawn whenever the filter changes.
	 *
	 * <p>{@code volatile} because {@link #accept} writes it from the client thread and
	 * everything else reads it from Swing's. The model itself is immutable, so a
	 * published reference is a complete, self-consistent reading — which is the whole
	 * reason {@link PanelModel} is a value object rather than a view of the scene.
	 */
	private volatile PanelModel model;

	/**
	 * What {@link #overrides} was last built from — see {@link #signature}.
	 *
	 * <p><b>Null rather than the empty string, and that is a bug fix rather than a
	 * style.</b> The empty string is a legitimate signature: it is what an empty list
	 * produces. Starting there meant the very first draw of a fresh profile — nobody
	 * hidden, nobody muted — compared equal, skipped the rebuild, and left the section
	 * with no components in it at all. Not the empty-state sentence: nothing. Null cannot
	 * be produced by {@link #signature}, so the first draw always builds.
	 */
	@Nullable
	private String overridesSignature;

	private boolean overridesOpen = true;

	/**
	 * Whether this panel is the one currently open in the sidebar.
	 *
	 * <p>{@code volatile} for the same reason as {@link #model}, in the other
	 * direction: it is written from Swing (RuneLite calls {@code onActivate} there) and
	 * read from the client thread, which asks before doing the per-tick work of
	 * composing a model nobody is looking at.
	 */
	private volatile boolean open;

	@Inject
	LivelyCitiesPanel(LivelyCitiesPlugin plugin)
	{
		super(true);
		this.plugin = plugin;
		this.model = null;

		setBackground(BACKDROP);
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setLayout(new BorderLayout());

		final JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setBackground(BACKDROP);

		column.add(title());
		column.add(gap(8));
		column.add(nowCard());
		column.add(gap(8));
		column.add(heading("Crowd density"));
		column.add(gap(4));
		column.add(densityRow());
		column.add(gap(4));
		column.add(helper("Thins the roster the same way every time, so a street looks the "
			+ "same each time you walk down it. Crowded adds derived extras instead."));
		column.add(gap(8));
		column.add(searchField());
		column.add(gap(8));
		column.add(heading("Places"));
		column.add(gap(4));

		cities.setLayout(new BoxLayout(cities, BoxLayout.Y_AXIS));
		cities.setBackground(BACKDROP);
		for (City city : City.values())
		{
			final CityCard card = new CityCard(city);
			card.setAlignmentX(Component.LEFT_ALIGNMENT);
			cityCards.put(city, card);
			cities.add(card);

			final JPanel spacer = gap(4);
			cityGaps.put(city, spacer);
			cities.add(spacer);
		}
		column.add(cities);

		column.add(gap(8));
		column.add(overridesHeaderRow());
		column.add(gap(4));

		overrides.setLayout(new BoxLayout(overrides, BoxLayout.Y_AXIS));
		overrides.setBackground(BACKDROP);
		column.add(overrides);

		overridesEmpty.setFont(FontManager.getRunescapeSmallFont());
		overridesEmpty.setForeground(HELPER);

		for (Component child : column.getComponents())
		{
			// BoxLayout lays a column out by each child's X alignment, and the two
			// defaults disagree: JPanel is centred, JLabel is left. Mixed, the column
			// comes out ragged — cards indented by half their slack, headings not. One
			// loop here rather than a call per component, so a row added later cannot
			// forget.
			((JComponent) child).setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		add(column, BorderLayout.NORTH);
		redraw();
	}

	// --- the two ends of the seam --------------------------------------------

	/**
	 * A fresh reading from the client thread — see {@link SidePanel#refresh}.
	 *
	 * <p>Publishes the model and hops. Never draws on the calling thread: Swing
	 * components may only be touched from the event dispatch thread, and this is called
	 * from the game tick.
	 */
	void accept(PanelModel next)
	{
		model = next;
		SwingUtilities.invokeLater(this::redraw);
	}

	/** @return whether the sidebar is showing this panel — see {@link SidePanel#isOpen} */
	boolean isOpen()
	{
		return open;
	}

	/**
	 * Opened from the toolbar.
	 *
	 * <p>Redraws from whatever the last reading was, so the panel has content
	 * immediately rather than after the next game tick — up to 600ms of "which region
	 * am I in" being one tick stale is nothing; an empty panel for 600ms every time it
	 * is opened is the thing people notice.
	 *
	 * <p><b>And when there is no last reading, one is asked for.</b> The readings arrive
	 * on the game tick, and the client posts no game tick while there is no world — so a
	 * panel opened at the login screen, which is the exact moment somebody opens it to
	 * find out what the plugin does, met {@link #redraw}'s null branch and stayed there
	 * until the player logged in. Asked for rather than composed here: this class reads no
	 * settings and knows no citizens, and {@link LivelyCitiesPlugin#loggedOutModel} touches
	 * no client, so there is nothing to marshal.
	 */
	@Override
	public void onActivate()
	{
		open = true;

		if (model == null)
		{
			model = plugin.loggedOutModel();
		}

		redraw();
	}

	@Override
	public void onDeactivate()
	{
		open = false;
	}

	/**
	 * Called when the button leaves the toolbar, which RuneLite does not necessarily
	 * follow with an {@code onDeactivate}.
	 *
	 * <p>Left true, the plugin would go on composing a model once a game tick for a
	 * panel that is not in the sidebar any more — and after {@code shutDown()} there is
	 * no plugin to compose it. Same shape as the {@code processedGameTick} flag
	 * {@code shutDown} clears for the developer-only reporter, and for the same reason:
	 * a flag that outlives the thing it describes is a slow leak.
	 */
	void closed()
	{
		open = false;
	}

	// --- drawing --------------------------------------------------------------

	private void redraw()
	{
		final PanelModel current = model;
		final String query = search.getText() == null ? "" : search.getText().trim().toLowerCase(Locale.ROOT);

		if (current == null)
		{
			whereValue.setText("Starting up");
			whereValue.setForeground(HELPER);
			activeValue.setText("—");
			detailValue.setText("No reading yet");
			return;
		}

		drawNow(current);
		drawDensity(current);
		drawCities(current, query);
		drawOverrides(current, query);

		revalidate();
		repaint();
	}

	private void drawNow(PanelModel current)
	{
		if (!current.isInWorld())
		{
			whereValue.setText("Not in a world");
			whereValue.setForeground(HELPER);
			activeValue.setText("0");
			activeValue.setForeground(HELPER);
			detailValue.setText("Log in and the numbers here go live");
			return;
		}

		final City here = current.getHere();
		whereValue.setText(here == null ? "Region " + current.getRegionId() : here.getLabel());
		whereValue.setForeground(here == null ? SUBTLE : ACCENT);

		final SceneCensus census = current.getCensus();
		activeValue.setText(String.valueOf(census.getActive()));
		activeValue.setForeground(census.getActive() == 0 ? HELPER : ACCENT);

		if (here == null)
		{
			detailValue.setText("Nowhere this plugin has data for");
		}
		else
		{
			detailValue.setText(census.getWalking() + " walking · " + census.getTalking()
				+ " talking · " + census.getInScope() + " loaded");
		}
	}

	private void drawDensity(PanelModel current)
	{
		for (Map.Entry<CrowdDensity, JLabel> chip : densityChips.entrySet())
		{
			paintChip(chip.getValue(), chip.getKey() == current.getDensity());
		}
	}

	private void drawCities(PanelModel current, String query)
	{
		for (PanelModel.CityRow row : current.getCities())
		{
			final CityCard card = cityCards.get(row.getCity());
			if (card == null)
			{
				continue;
			}
			card.update(row);

			// The card and the strut under it, together. A spacer's height does not come
			// from its neighbours, so a hidden card whose gap stayed behind is 4px of
			// nothing — and filtering to one place left eight of them stacked under it.
			final boolean shown = matches(query, row.getCity().getLabel());
			card.setVisible(shown);

			final JPanel spacer = cityGaps.get(row.getCity());
			if (spacer != null)
			{
				spacer.setVisible(shown);
			}
		}
	}

	/**
	 * The hidden-and-muted list, rebuilt only when it is actually different.
	 *
	 * <p>The signature covers the filter as well as the rows, because a filtered list
	 * is a different list of components even when the model behind it has not moved.
	 *
	 * <p><b>What it does not cover is how many rows the filter threw away</b> — see the
	 * empty-state sentence below, which is therefore chosen on every draw rather than
	 * inside the rebuild.
	 */
	private void drawOverrides(PanelModel current, String query)
	{
		final List<PanelModel.OverrideRow> visible = new ArrayList<>();
		for (PanelModel.OverrideRow row : current.getOverrides())
		{
			if (matches(query, row.getDisplayName())
				|| (row.getCity() != null && matches(query, row.getCity().getLabel())))
			{
				visible.add(row);
			}
		}

		overridesHeader.setText((overridesOpen ? "▾  " : "▸  ")
			+ "Hidden and muted (" + current.getOverrides().size() + ")");

		// Set on every draw, outside the rebuild below, because it answers the same
		// question the header does — is anybody overridden at all? — and that is the
		// *unfiltered* list, which the signature does not describe. Two draws that both
		// filter down to nothing share the signature "" however much moved between them,
		// so a sentence chosen inside the rebuild is a sentence that is never revisited.
		// It went wrong in both directions: type a query nothing matches and then hide
		// somebody, and the header read "Hidden and muted (1)" directly above "Nobody is
		// hidden or muted."; unhide the last citizen with such a query typed and "Nobody
		// here matches that." was left over a list with nothing left to match.
		overridesEmpty.setText(current.getOverrides().isEmpty()
			? "Nobody is hidden or muted."
			: "Nobody here matches that.");

		final String next = signature(visible);
		if (!next.equals(overridesSignature))
		{
			overridesSignature = next;
			overrides.removeAll();

			if (visible.isEmpty())
			{
				stack(overridesEmpty);
				stack(helper("Right-click any citizen for Hide and Mute. Whatever you "
					+ "choose turns up here, one row at a time, with the way back."));
			}
			else
			{
				for (PanelModel.OverrideRow row : visible)
				{
					stack(new OverrideCard(row));
				}
			}
		}

		overrides.setVisible(overridesOpen);
	}

	/** Adds one component to the override list, spaced and aligned like every other. */
	private void stack(JComponent child)
	{
		child.setAlignmentX(Component.LEFT_ALIGNMENT);
		overrides.add(child);
		overrides.add(gap(4));
	}

	/**
	 * What {@link #drawOverrides} compares to decide whether to rebuild.
	 *
	 * <p>Both flags are in it, not just the uuid: a citizen who was hidden and is now
	 * hidden <i>and</i> muted is the same uuid on the same row with a second action on
	 * it, and a signature of uuids alone would leave that action undrawn until something
	 * else changed.
	 *
	 * <p>And the uuid is in it, not just the flags: bringing back the wrong person and
	 * hiding the right one is one row before and one row after, hidden both times — so a
	 * signature of flags alone would leave the restore pointing at somebody who is already
	 * unhidden, and the citizen who is hidden with no way back.
	 */
	private static String signature(List<PanelModel.OverrideRow> rows)
	{
		final StringBuilder out = new StringBuilder();
		for (PanelModel.OverrideRow row : rows)
		{
			out.append(row.getUuid())
				.append(row.isHidden() ? 'h' : '-')
				.append(row.isMuted() ? 'm' : '-')
				.append(';');
		}
		return out.toString();
	}

	private static boolean matches(String query, String text)
	{
		return query.isEmpty() || text.toLowerCase(Locale.ROOT).contains(query);
	}

	// --- construction helpers -------------------------------------------------

	private JPanel title()
	{
		final JPanel panel = row();

		final JLabel name = new JLabel("Lively Cities");
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(ACCENT);
		panel.add(name, BorderLayout.WEST);

		return constrain(panel);
	}

	private JPanel nowCard()
	{
		final JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(CARD);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
			new EmptyBorder(6, 8, 6, 8)));

		final JPanel top = new JPanel(new BorderLayout());
		top.setBackground(CARD);

		whereValue.setFont(FontManager.getRunescapeBoldFont());
		whereValue.setForeground(ACCENT);
		top.add(whereValue, BorderLayout.WEST);

		activeValue.setFont(FontManager.getRunescapeBoldFont());
		activeValue.setForeground(ACCENT);
		top.add(activeValue, BorderLayout.EAST);
		panel.add(top);

		final JPanel bottom = new JPanel(new BorderLayout());
		bottom.setBackground(CARD);

		detailValue.setFont(FontManager.getRunescapeSmallFont());
		detailValue.setForeground(HELPER);
		bottom.add(detailValue, BorderLayout.WEST);

		final JLabel caption = new JLabel("on screen");
		caption.setFont(FontManager.getRunescapeSmallFont());
		caption.setForeground(HELPER);
		bottom.add(caption, BorderLayout.EAST);
		panel.add(bottom);

		return constrain(panel);
	}

	private JPanel densityRow()
	{
		final JPanel panel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		panel.setBackground(BACKDROP);

		for (CrowdDensity density : CrowdDensity.values())
		{
			final JLabel chip = new JLabel(density.toString());
			chip.setFont(FontManager.getRunescapeSmallFont());
			chip.setBorder(new EmptyBorder(3, 7, 3, 7));
			chip.setOpaque(true);
			chip.setCursor(new Cursor(Cursor.HAND_CURSOR));
			chip.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent event)
				{
					plugin.setCrowdDensity(density);
				}
			});
			paintChip(chip, false);
			densityChips.put(density, chip);
			panel.add(chip);
		}

		return constrain(panel);
	}

	private static void paintChip(JLabel chip, boolean selected)
	{
		chip.setBackground(selected ? CARD_HOVER : CARD);
		chip.setForeground(selected ? ACCENT : SUBTLE);
	}

	private IconTextField searchField()
	{
		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 28));
		search.setAlignmentX(Component.LEFT_ALIGNMENT);
		search.setBackground(CARD);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.addClearListener(this::redraw);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent event)
			{
				redraw();
			}

			@Override
			public void removeUpdate(DocumentEvent event)
			{
				redraw();
			}

			@Override
			public void changedUpdate(DocumentEvent event)
			{
				redraw();
			}
		});
		return search;
	}

	private JPanel overridesHeaderRow()
	{
		final JPanel panel = row();
		panel.setCursor(new Cursor(Cursor.HAND_CURSOR));

		// Given its text before the row is measured. The cap below is the row's preferred
		// height, and a label with nothing in it prefers to be nothing tall.
		overridesHeader.setText("▾  Hidden and muted");
		overridesHeader.setFont(FontManager.getRunescapeBoldFont());
		overridesHeader.setForeground(ACCENT);
		panel.add(overridesHeader, BorderLayout.WEST);

		panel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent event)
			{
				overridesOpen = !overridesOpen;
				redraw();
			}
		});

		return constrain(panel);
	}

	private JPanel heading(String text)
	{
		final JPanel panel = row();

		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ACCENT);
		panel.add(label, BorderLayout.WEST);

		return constrain(panel);
	}

	/** A muted grey paragraph. Wrapped as HTML because Swing labels do not wrap. */
	private JLabel helper(String text)
	{
		final JLabel label = new JLabel("<html><body style='width:"
			+ (PluginPanel.PANEL_WIDTH - 40) + "px'>" + text + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(HELPER);
		label.setBorder(new EmptyBorder(0, 0, 0, 0));
		return label;
	}

	/**
	 * An empty full-width strip.
	 *
	 * <p><b>Deliberately not constrained here.</b> {@link #constrain} caps a row at its
	 * <i>preferred</i> height, and a panel with nothing in it prefers to be nothing tall
	 * — so constraining on the way out of this method capped every heading and the title
	 * at zero pixels and made them invisible. Callers constrain after they have added
	 * their labels.
	 */
	private JPanel row()
	{
		final JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(BACKDROP);
		return panel;
	}

	private static JPanel gap(int height)
	{
		final JPanel spacer = new JPanel();
		spacer.setAlignmentX(Component.LEFT_ALIGNMENT);
		spacer.setBackground(BACKDROP);
		spacer.setPreferredSize(new Dimension(1, height));
		spacer.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		spacer.setMinimumSize(new Dimension(1, height));
		return spacer;
	}

	/**
	 * Stops a {@code BoxLayout} row stretching to fill the column.
	 *
	 * <p><b>Only ever called after the row's children are in place.</b> The cap is the
	 * row's preferred height, and an empty row prefers to be nothing tall — so calling
	 * this too early is not a missing constraint, it is a row pinned to zero pixels,
	 * which is a heading that is laid out, visible, painted and 0px high.
	 */
	private static JPanel constrain(JPanel panel)
	{
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	/**
	 * A row and every label on it, so a hover covers the strip rather than its margins.
	 *
	 * <p>Not called {@code paint}. {@link javax.swing.JComponent} already has a
	 * {@code paint(Graphics)}, and a same-named helper called from inside a
	 * {@code JPanel} subclass below resolves against the inherited one — which does not
	 * fail quietly, but does mean the name is taken.
	 */
	private static void repaintStrip(JPanel strip, Color colour)
	{
		strip.setBackground(colour);
		for (Component child : strip.getComponents())
		{
			child.setBackground(colour);
			if (child instanceof JPanel)
			{
				repaintStrip((JPanel) child, colour);
			}
		}
	}

	// --- the two kinds of card ------------------------------------------------

	/**
	 * One place: its name, what the dataset holds, what is on screen, and its checkbox.
	 *
	 * <p>Built once and repainted, never rebuilt — see the class javadoc. Clicking
	 * anywhere on it toggles the city, which is the same write the config screen's
	 * checkbox makes.
	 */
	private final class CityCard extends JPanel
	{
		private final City city;
		private final JLabel name = new JLabel();
		private final JLabel state = new JLabel();
		private final JLabel counts = new JLabel();

		private boolean enabled = true;

		private CityCard(City city)
		{
			super(new BorderLayout());
			this.city = city;

			setBackground(CARD);
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
				new EmptyBorder(5, 8, 5, 8)));
			setCursor(new Cursor(Cursor.HAND_CURSOR));

			name.setFont(FontManager.getRunescapeBoldFont());
			add(name, BorderLayout.WEST);

			state.setFont(FontManager.getRunescapeSmallFont());
			add(state, BorderLayout.EAST);

			counts.setFont(FontManager.getRunescapeSmallFont());
			counts.setForeground(HELPER);
			add(counts, BorderLayout.SOUTH);

			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent event)
				{
					plugin.setCityEnabled(CityCard.this.city, !enabled);
				}

				@Override
				public void mouseEntered(MouseEvent event)
				{
					repaintStrip(CityCard.this, CARD_HOVER);
				}

				@Override
				public void mouseExited(MouseEvent event)
				{
					repaintStrip(CityCard.this, CARD);
				}
			});
		}

		private void update(PanelModel.CityRow row)
		{
			enabled = row.isEnabled();

			name.setText(row.getCity().getLabel());
			name.setForeground(enabled ? ACCENT : HELPER);

			state.setText(enabled ? "on" : "off");
			state.setForeground(enabled ? SUBTLE : HELPER);

			// The live figure is shown whenever there is one, and not only for the city
			// the player is standing in. A loaded scene covers up to nine regions, so
			// standing in Varrock really can mean the Grand Exchange has figures up —
			// and a card that hid that would be hiding the one thing only a panel can
			// show.
			final StringBuilder text = new StringBuilder();
			text.append(row.getCitizens()).append(row.getCitizens() == 1 ? " citizen" : " citizens");
			if (row.getActive() > 0)
			{
				text.append(" · ").append(row.getActive()).append(" on screen");
			}
			if (row.isHere())
			{
				text.append(" · you are here");
			}
			counts.setText(text.toString());
			counts.setForeground(row.isHere() || row.getActive() > 0 ? BODY : HELPER);

			setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
		}
	}

	/**
	 * One citizen you overrode, with the restore for whichever overrides apply.
	 *
	 * <p>Rebuilt rather than repainted, because the set of rows is what changes and a
	 * pool of reusable rows would be a cache keyed on a list that is usually empty.
	 */
	private final class OverrideCard extends JPanel
	{
		private OverrideCard(PanelModel.OverrideRow row)
		{
			super(new BorderLayout());

			setBackground(CARD);
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
				new EmptyBorder(5, 8, 5, 8)));

			final JLabel name = new JLabel(row.getDisplayName());
			name.setFont(FontManager.getRunescapeBoldFont());
			name.setForeground(ACCENT);
			add(name, BorderLayout.WEST);

			final StringBuilder subtitle = new StringBuilder();
			subtitle.append(row.getCity() == null ? "no longer in the dataset" : row.getCity().getLabel());
			subtitle.append(" · ");
			if (row.isHidden() && row.isMuted())
			{
				subtitle.append("hidden and muted");
			}
			else
			{
				subtitle.append(row.isHidden() ? "hidden" : "muted");
			}

			final JLabel where = new JLabel(subtitle.toString());
			where.setFont(FontManager.getRunescapeSmallFont());
			where.setForeground(HELPER);
			add(where, BorderLayout.SOUTH);

			final JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
			actions.setBackground(CARD);
			if (row.isHidden())
			{
				actions.add(action("show", () -> plugin.unhide(row.getUuid())));
			}
			if (row.isMuted())
			{
				actions.add(action("unmute", () -> plugin.unmute(row.getUuid())));
			}
			add(actions, BorderLayout.EAST);

			setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
		}

		private JLabel action(String text, Runnable onClick)
		{
			final JLabel label = new JLabel(text);
			label.setFont(FontManager.getRunescapeSmallFont());
			label.setForeground(SUBTLE);
			label.setBorder(new EmptyBorder(2, 5, 2, 5));
			label.setOpaque(true);
			label.setBackground(CARD_HOVER);
			label.setCursor(new Cursor(Cursor.HAND_CURSOR));
			label.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent event)
				{
					onClick.run();
				}

				@Override
				public void mouseEntered(MouseEvent event)
				{
					label.setForeground(ACCENT);
				}

				@Override
				public void mouseExited(MouseEvent event)
				{
					label.setForeground(SUBTLE);
				}
			});
			return label;
		}
	}

}

package com.matthewmariner.livelycities;

import com.google.inject.Provides;
import java.util.UUID;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

/**
 * Cosmetic townsfolk and scenery, spawned from the vendored region dataset.
 *
 * <p>Lifecycle, and why it is shaped this way:
 *
 * <ul>
 *   <li><b>Work happens on {@link GameTick}, not on {@code LOGGED_IN}.</b>
 *       {@code LOGGED_IN} fires before the world is usable —
 *       {@code getLocalPlayer()} is still null at that point — so the state
 *       handler only invalidates, and the tick handler does the work behind a
 *       null check.</li>
 *   <li><b>The scene is re-checked every tick</b> by comparing the loaded map
 *       region ids. That is an array compare, not a scene scan, and it means a
 *       region border crossing cannot be missed however the game state
 *       transitions happen to be ordered.</li>
 *   <li><b>{@link BeforeRender} is the second clock.</b> It is posted from the
 *       client's own frame loop, once per rendered frame, and it is where the
 *       wanderers' positions are interpolated between tiles. Nothing else
 *       happens per frame: the animations are advanced by the client, which calls
 *       {@code RuneLiteObject.tick(ticksSinceLastFrame)} on every registered
 *       object as it draws it.</li>
 *   <li><b>The two interaction handlers are not deferred.</b>
 *       {@code MenuOpened} and {@code MenuOptionClicked} are posted from the
 *       client's own menu code and have to be answered inside it — see
 *       {@link #onMenuOpened} and {@link CitizenMenu}.</li>
 *   <li><b>Everything reaches {@link EntityScene} on the client thread.</b>
 *       {@code @Subscribe} runs on the posting thread, so the handlers wrap their
 *       calls in {@link ClientThread#invoke} — which runs inline when we are
 *       already on the client thread, and defers when we are not. The frame
 *       handler is the exception: it is already on the client thread by
 *       construction, and queueing a task per frame would be a queue that never
 *       drains.</li>
 * </ul>
 */
@Slf4j
@PluginDescriptor(
	name = "Lively Cities",
	description = "Cosmetic townsfolk and scenery that make cities feel lived-in",
	tags = {"npc", "citizens", "cosmetic", "immersion", "scenery"}
)
public class LivelyCitiesPlugin extends Plugin
{
	/**
	 * Client ticks in one game tick: 600ms / 20ms.
	 *
	 * <p>The denominator for the interpolation fraction. Taken from the client's
	 * own constants rather than written as 30, because both halves are named
	 * there and a divisor that is silently wrong shows up as citizens that finish
	 * their step early and then stand still, which is hard to attribute.
	 */
	private static final int CLIENT_TICKS_PER_GAME_TICK =
		Constants.GAME_TICK_LENGTH / Constants.CLIENT_TICK_LENGTH;

	// Package-private rather than private so the tests in this package can wire
	// their own fakes in. Guice injects a package-private field exactly as it
	// injects a private one, so this costs the runtime nothing — and the
	// alternative is either a mocking framework (none on the classpath) or
	// reflection (banned).
	@Inject
	Client client;

	@Inject
	ClientThread clientThread;

	@Inject
	EntityScene scene;

	/**
	 * The dials, held here for one reason: the side panel draws them.
	 *
	 * <p>Everything else in this class reaches settings through the collaborator that
	 * owns them — {@link EntityScene} for the render dials, {@link CitizenOverrides} for
	 * the two uuid lists — and that is still the arrangement. What has no owner is "what
	 * do the dials currently say?", which is exactly the question a panel showing them
	 * has to ask before it can offer to change one.
	 */
	@Inject
	LivelyCitiesConfig config;

	@Inject
	OverlayRegistry overlayRegistry;

	/**
	 * The sidebar — see {@link SidePanel}, and note that this is the interface rather
	 * than the panel. Nothing here may touch Swing.
	 */
	@Inject
	SidePanel sidePanel;

	/**
	 * Who each uuid is. Only the panel asks, and it asks lazily — see
	 * {@link CitizenDirectory}.
	 */
	@Inject
	CitizenDirectory directory;

	@Inject
	ChatterOverlay chatterOverlay;

	@Inject
	CitizenMenu citizenMenu;

	@Inject
	CitizenOverrides overrides;

	@Inject
	ConfigWriter configWriter;

	/**
	 * The stopwatch, off for every ordinary launch — see {@link FrameTimings}.
	 *
	 * <p><b>Nothing in this class reads it, and that is deliberate.</b> The measuring
	 * happens in {@link EntityScene}, which Guice hands the same {@code @Singleton};
	 * the <i>reporting</i> — the cadence, {@code RuneLite.RUNELITE_DIR} and the
	 * background thread that writes a file — moved to the test source set, because
	 * filesystem I/O in a shipped jar costs the Plugin Hub submission its automated
	 * review. See {@code LivelyCitiesDevReportsPlugin}, which is loaded only by
	 * {@code ./gradlew runWithTimings} and {@code ./gradlew auditCacheIds}.
	 *
	 * <p>This field is how that plugin reaches <i>this</i> stopwatch rather than a
	 * second one. It declares {@code @PluginDependency(LivelyCitiesPlugin.class)}, so
	 * RuneLite builds its injector as a child of this plugin's and binds this instance
	 * into it; it then reads this field. Resolving {@code FrameTimings} from its own
	 * injector instead would work only as long as Guice keeps hoisting the just-in-time
	 * binding to the root injector, and the failure mode if it ever did not is a report
	 * full of zeros rather than an error.
	 */
	@Inject
	FrameTimings frameTimings;

	/**
	 * {@code getGameCycle()} at the last game tick we processed.
	 *
	 * <p>The frame handler needs to know how far through the current game tick it
	 * is. {@code getGameCycle()} increments every 20ms — the client's own clock,
	 * which stops when the client stops — so the difference divided by
	 * {@link #CLIENT_TICKS_PER_GAME_TICK} is that fraction. Wall-clock time would
	 * also work until the first time the client is paused or the machine sleeps.
	 *
	 * <p><b>Written only by {@link #tick()}.</b> It is the interpolation clock's
	 * origin, so anything else that reset it would restart every citizen's step
	 * from wherever it had got to — which is what {@link #onConfigChanged} used to
	 * do.
	 */
	private int cycleAtLastTick;

	/**
	 * Whether the most recent {@link GameTick} was one {@link #tick()} ran a full pass
	 * on, rather than one it returned early from.
	 *
	 * <p><b>Read by the developer-only reporter, and by nothing here.</b>
	 * {@code frameTimings.onGameTick()} used to be the last statement of
	 * {@link #tick()}, after its early exit — so the population the frame report
	 * described was "ticks this plugin processed", which is the population it claims to
	 * describe. Moving the cadence to {@code LivelyCitiesDevReportsPlugin} put it on its
	 * own {@code GameTick} subscriber, where "did the pass happen?" is no longer implied
	 * by "am I running", so the reporter has to ask.
	 *
	 * <p>Cleared in {@link #shutDown()}, which is the case that makes this a flag rather
	 * than an assumption: the reporter is a separate plugin and stays on when this one
	 * is toggled off, and a flag left true would let the 300-tick cadence keep firing —
	 * rewriting the report from samples nothing is adding to any more.
	 *
	 * <p>The reporter can only ever see the current tick's value because it subscribes
	 * at {@code priority = -1f} and therefore runs after this class. At any other
	 * priority it reads the previous tick's, which is what
	 * {@code FrameTimingsTest.theReportIncludesTheTickThatTriggeredIt} exists to catch.
	 */
	private boolean processedGameTick;

	@Override
	protected void startUp()
	{
		log.info("Lively Cities starting (cull {} tiles, max {}, cap {} objects)",
			RenderPolicy.DEFAULT_CULL_RADIUS, RenderPolicy.MAX_CULL_RADIUS, RenderPolicy.MAX_ACTIVE_OBJECTS);

		overlayRegistry.add(chatterOverlay);

		// The button, unconditionally. It is the only affordance this plugin has that
		// announces itself — everything else is a right-click nobody has been told about
		// or a settings screen you have to already be looking for — so there is no
		// setting behind it to disagree with.
		sidePanel.show();

		// Enabling the plugin mid-session is the common case in dev. Nothing to
		// do here beyond letting the next game tick find the scene — but if we
		// are already logged in, do not make the user wait for a state change
		// that will never come.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			// The braces are load-bearing, and this is not a style choice.
			// ClientThread overloads invoke() on Runnable and BooleanSupplier, and the
			// two mean different things: a BooleanSupplier is re-queued every tick
			// until it returns true. When tick() was void, `this::tick` bound to the
			// Runnable overload. Giving it a boolean return — for the reporting
			// cadence, nothing to do with this line — silently rebound it to
			// BooleanSupplier and turned one first pass into a retry loop, with no
			// warning and no character of this call site changed. A block lambda whose
			// body is a bare statement has no value, so only Runnable fits.
			clientThread.invoke(() ->
			{
				tick();
			});
		}
	}

	/**
	 * Undoes {@link #startUp()}, in the order the ordering matters in.
	 *
	 * <p><b>Straight-line, with no {@code try}/{@code finally}, and that is a decision
	 * rather than an omission.</b> A throw from the first statement here would skip the
	 * button removal and the scene teardown — precisely the leak this method exists to
	 * prevent, and one no amount of re-enabling can undo. So the question is whether
	 * anything on this path can throw, and against the 1.12.37 client it cannot:
	 * {@code ClientToolbar.removeNavigation} is one {@code SwingUtilities.invokeLater} call
	 * and nothing else, and {@code OverlayManager.remove} is a {@code synchronized}
	 * collection removal. Neither reaches the client through anything that could change
	 * underneath this class — both go through the two {@code @Provides} lambdas at the
	 * bottom of this same file — and what is left is two field writes and a
	 * {@link ClientThread#invoke}. Nesting {@code finally} blocks around a path with no
	 * reachable thrower would cost this method the readability the teardown contract is
	 * actually kept by, and the contract itself is asserted rather than read:
	 * {@code LivelyCitiesPluginLifecycleTest} checks it against recording registries.
	 *
	 * <p>If a step that can throw is ever added here, this paragraph is what has to be
	 * revisited with it — and the answer then is to keep going rather than to stop, because
	 * an overlay drawing from an emptied scene is a blank frame and a scene left standing
	 * is every lit model and every registered object leaked.
	 */
	@Override
	protected void shutDown()
	{
		// Removed before the scene is torn down, and synchronously: an overlay left
		// in the OverlayManager keeps drawing, and it would be drawing from a scene
		// that is being emptied underneath it.
		overlayRegistry.remove(chatterOverlay);

		// And the sidebar. Same class of leak as an overlay left in the manager: a
		// NavigationButton left in the toolbar is a button that opens a panel whose
		// plugin is gone, and ClientToolbar keys its navigation off the button instance,
		// so a second one built on the way back in would leave the first sitting there
		// for the rest of the session. The panel's "somebody is looking" flag is cleared
		// with it, or the next enable would compose a model for a panel that is not in
		// the sidebar.
		sidePanel.hide();

		// The menu holds a reference to whichever citizen the last right-click was
		// on. Left set, it would keep that wrapper — and its lit model — alive past
		// the teardown whose whole job is to leave nothing behind.
		citizenMenu.forget();

		// The developer-only reporter is a separate plugin and does not stop when this
		// one does. Left true, its 300-tick cadence would go on firing over a scene
		// nobody is measuring any more.
		processedGameTick = false;

		// Not blocking: invoke() runs inline on the client thread and defers
		// otherwise. The count lands in the log either way.
		//
		// A block lambda rather than `scene::shutdown`, for the same reason the braces
		// in startUp() are load-bearing. That method reference binds to the Runnable
		// overload today only because shutdown() returns int, which cannot be a
		// BooleanSupplier's result. Give it a boolean return one day and it silently
		// rebinds — JLS 15.12.2.5 makes the value-returning function type the more
		// specific of the two, so BooleanSupplier wins outright rather than the call
		// becoming ambiguous and failing to compile — and ClientThread re-queues a
		// BooleanSupplier every tick until it returns true. That is a teardown that
		// runs forever, with no warning and no character of this call site changed. A
		// block lambda whose body is a bare statement has no value, so only Runnable
		// ever fits. LivelyCitiesPluginLifecycleTest's InlineClientThread fails the
		// test outright if the BooleanSupplier overload is ever reached from anywhere
		// in this class, so the binding is pinned rather than merely intended.
		clientThread.invoke(() ->
		{
			scene.shutdown();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		switch (state)
		{
			// The scene is being replaced or is gone. Every LocalPoint we hold
			// is about to mean something else, so nothing may stay active.
			case LOADING:
			case HOPPING:
			case LOGGING_IN:
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
			case CONNECTION_LOST:
				// The remembered right-click target is about to be a wrapper the
				// scene has forgotten.
				citizenMenu.forget();

				// Braces again, and not for symmetry. `() -> scene.invalidate(..)` is
				// an expression lambda, and invalidate() returns int — so it is
				// void-compatible only, and only Runnable fits. The day that return
				// type becomes boolean, the same lambda becomes value-compatible too
				// and BooleanSupplier wins the overload, which would re-queue this
				// every tick until it returned true: a scene load that never finishes
				// invalidating. The block form has no value to offer, so it cannot
				// drift.
				clientThread.invoke(() ->
				{
					scene.invalidate(state.name());

					// Logging out empties the scene, and a panel still showing "Varrock,
					// 34 on screen" over an empty world is worse than one showing
					// nothing: it is the last true reading, indistinguishable from a
					// current one.
					refreshPanel();
				});
				break;

			// Deliberately no work on LOGGED_IN: the local player may still be
			// null here. onGameTick picks it up.
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		processedGameTick = tick();

		// The panel's clock. Everything on it either moves every tick (how many figures
		// are on screen, who is talking) or changes on a click, and a click already runs
		// a pass of its own through onConfigChanged — so the game tick is the only
		// cadence it needs, and it is the cadence the numbers are true at.
		refreshPanel();
	}

	/**
	 * Whether the most recent {@link GameTick} reached the scene — see
	 * {@link #processedGameTick}.
	 *
	 * <p>Package-private, and the developer-only reporter in the test source set is its
	 * only caller. It is a plain getter rather than a listener hook on purpose: nothing
	 * in {@code src/main} may hold a sink, a nullable writer or a "reporting enabled"
	 * branch, which is the arrangement the whole move exists to produce.
	 */
	boolean processedGameTick()
	{
		return processedGameTick;
	}

	/**
	 * Runs a <i>visibility</i> pass as soon as a setting changes, rather than
	 * waiting for the next game tick.
	 *
	 * <p>This is what makes unticking a city <i>deactivate</i> its citizens
	 * instead of merely stopping new ones spawning: the pass has one rule — what
	 * is not wanted is despawned — so re-running it with the new settings is the
	 * whole implementation. A tick is only 600ms away, but a toggle that visibly
	 * lags the click reads as a toggle that did not work.
	 *
	 * <p><b>A visibility pass and not a game tick.</b> This used to call
	 * {@link #tick()}, which also steps every walker one tile and restarts the
	 * interpolation clock. RuneLite posts one {@code ConfigChanged} per key, so
	 * switching profiles posts one per item this plugin owns — about two dozen —
	 * and the crowd teleported two dozen tiles for a change the user made to a
	 * checkbox. Movement comes from the game's clock; a setting is not a tick.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!LivelyCitiesConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (handleResetButton(event))
		{
			// The clear wrote another setting, which posts another ConfigChanged, and
			// that one runs the visibility pass. Running it here as well would run it
			// twice for one click.
			return;
		}

		log.debug("config changed ({}), re-running the visibility pass", event.getKey());
		clientThread.invoke(this::refreshVisibility);
	}

	/**
	 * The two "clear the list" checkboxes, which untick themselves.
	 *
	 * <p>1.12.36 has no {@code Button} config type — there is no
	 * {@code net.runelite.client.config.Button} in the client jar — so a control
	 * whose meaning is "do this now" has to be a boolean that is turned back off
	 * once it has been acted on. Unset rather than written false: a key left in the
	 * profile reads as a user override forever, and "the user has no setting here"
	 * is the honest end state for a button.
	 *
	 * <p><b>It terminates.</b> Unsetting posts one more {@code ConfigChanged} for the
	 * same key with a new value of {@code null}, which fails the {@code "true"} test
	 * below and falls through to an ordinary visibility pass. There is no second
	 * write and so no loop.
	 *
	 * @return true if this event was a button press that has now been handled
	 */
	private boolean handleResetButton(ConfigChanged event)
	{
		final String key = event.getKey();
		if (!CitizenOverrides.UNHIDE_ALL_KEY.equals(key) && !CitizenOverrides.UNMUTE_ALL_KEY.equals(key))
		{
			return false;
		}

		if (!"true".equals(event.getNewValue()))
		{
			// The self-unset echo, or somebody unticking a box that was somehow left
			// ticked. Not a press.
			return false;
		}

		int cleared = CitizenOverrides.UNHIDE_ALL_KEY.equals(key)
			? overrides.unhideAll()
			: overrides.unmuteAll();

		log.debug("'{}' pressed, {} citizen(s) restored", key, cleared);

		// Whether or not anything was cleared: the box has to come back up either
		// way, or it stays ticked and can never be pressed again.
		configWriter.write(key, null);
		return true;
	}

	/**
	 * Adds this plugin's right-click entries.
	 *
	 * <p><b>Not wrapped in {@link ClientThread#invoke}, and that is not an
	 * oversight.</b> {@code MenuOpened} is posted from the client's own menu code,
	 * so this is already on the client thread — and {@code Menu.createMenuEntry}
	 * asserts as much. Deferring would be actively wrong rather than merely
	 * unnecessary: the entries would be added after the menu had been built and
	 * drawn, i.e. into the next menu or into none.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		citizenMenu.onMenuOpened(event);
	}

	/**
	 * Handles a click on one of them, locally.
	 *
	 * <p>Same threading as {@link #onMenuOpened}: posted from the client's menu
	 * dispatch, and it has to consume the event before that dispatch continues, so
	 * it cannot be deferred.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		citizenMenu.onMenuOptionClicked(event);
	}

	/**
	 * The per-frame hook. Posted by the client from its draw loop, so this is
	 * already on the client thread.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		final WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		scene.onFrame(worldView, tickFraction());
	}

	/**
	 * The one place that touches the scene per game tick, and the only writer of
	 * {@link #cycleAtLastTick}. Runs on the client thread — GameTick is posted
	 * from it, and {@link #startUp()} routes through {@link ClientThread}.
	 *
	 * @return true if a full pass ran; false if there was no player or no world view
	 * yet and this tick did nothing. {@link #processedGameTick} is the only reader,
	 * and it is why this returns anything at all.
	 */
	private boolean tick()
	{
		final WorldPoint playerLocation = playerLocation();
		final WorldView worldView = client.getTopLevelWorldView();
		if (playerLocation == null || worldView == null)
		{
			return false;
		}

		// Restarting the interpolation clock is a game-tick-only act: the frame
		// handler measures from here, so writing it anywhere else would drop every
		// citizen back to the start of its step.
		cycleAtLastTick = client.getGameCycle();

		scene.syncRegions(worldView);
		scene.onGameTick(playerLocation, worldView);
		return true;
	}

	/**
	 * The settings path: re-decide who is visible, step nobody, and leave the
	 * interpolation clock alone.
	 *
	 * <p>{@code syncRegions} is still called. It is an array compare that returns
	 * immediately when the scene has not moved, and calling it means this entry
	 * point works even when it is the first thing to run after a login — a config
	 * change can arrive before the first {@link GameTick}, and a visibility pass
	 * over an empty scope would silently do nothing.
	 */
	private void refreshVisibility()
	{
		final WorldPoint playerLocation = playerLocation();
		final WorldView worldView = client.getTopLevelWorldView();
		if (playerLocation == null || worldView == null)
		{
			return;
		}

		scene.syncRegions(worldView);
		scene.onSettingsChanged(playerLocation, worldView);
		refreshPanel();
	}

	/**
	 * Takes a reading and hands it to the sidebar.
	 *
	 * <p><b>Behind {@link SidePanel#isOpen()}, and that is a cost decision rather than a
	 * cosmetic one.</b> Composing a model walks every cached wrapper and asks the client
	 * whether each object is still registered — real per-tick work, in a plugin whose
	 * whole performance argument is that it does almost none per frame and very little
	 * per tick. Nobody is looking at a closed panel, so a closed panel costs one boolean
	 * read every 600ms and nothing else.
	 *
	 * <p>Client thread: every caller is already on it, and {@link EntityScene#census()}
	 * reads the client. The hop to Swing happens on the far side of
	 * {@link SidePanel#refresh}, which is the panel's job rather than this one's.
	 */
	private void refreshPanel()
	{
		if (!sidePanel.isOpen())
		{
			return;
		}

		sidePanel.refresh(PanelModel.of(
			playerLocation(),
			scene.census(),
			config,
			overrides.hiddenUuids(),
			overrides.mutedUuids(),
			directory));
	}

	/**
	 * The reading to draw when the panel is opened before anything has been pushed to
	 * it — see {@link PanelModel#loggedOut}.
	 *
	 * <p><b>Why the panel has to ask for one at all.</b> {@link #refreshPanel} is the only
	 * thing that ever hands a model over, and it is driven by {@link GameTick} — which the
	 * client does not post while there is no world. So enabling the plugin at the login
	 * screen, or opening the panel there, left it with the null model it was constructed
	 * with until the player logged in: nine bordered cards with no name, no on/off and no
	 * counts, no density selected, and an overrides section with nothing in it at all.
	 *
	 * <p><b>Client-free, and that is what makes it callable from Swing.</b> The dials, the
	 * two uuid lists and the citizen counts come out of the profile and the classpath;
	 * nothing here reads the client, so there is no thread to hop to and no reading that
	 * could throw off the client thread. The one number that would need a client —
	 * how many figures are on screen — is zero when there is no world, which is
	 * {@link SceneCensus#EMPTY}.
	 *
	 * <p>Package-private, and {@link LivelyCitiesPanel#onActivate} is its only caller.
	 */
	PanelModel loggedOutModel()
	{
		return PanelModel.loggedOut(config, overrides.hiddenUuids(), overrides.mutedUuids(), directory);
	}

	/**
	 * Turns one city's checkbox on or off, from the panel.
	 *
	 * <p><b>Writes the same key the config screen writes</b>, through the same
	 * {@link ConfigWriter} — see {@link City#getConfigKey()}, which is the very constant
	 * the {@code @ConfigItem} is annotated with. So the panel and the settings screen are
	 * two views of one setting rather than two settings, and unticking a city here shows
	 * up unticked there.
	 *
	 * <p><b>A write that would change nothing does not happen.</b> {@code ConfigManager}
	 * posts a {@code ConfigChanged} per {@code setConfiguration}, and this plugin answers
	 * every one of those with a full visibility pass over every entity in scope — so a
	 * no-op write is a no-op pass over a hundred citizens. The same rule
	 * {@link UuidSetting#add} keeps, for the same reason.
	 *
	 * <p>Called from Swing's event dispatch thread and deliberately not marshalled:
	 * nothing here reads the client. {@code ConfigManager} is thread-safe and is what
	 * RuneLite's own settings panel writes through, from that same thread. The work that
	 * <i>does</i> need the client thread — the visibility pass — is already marshalled by
	 * {@link #onConfigChanged}, which is what the write posts.
	 */
	void setCityEnabled(City city, boolean enabled)
	{
		if (city.enabledIn(config) == enabled)
		{
			return;
		}

		configWriter.write(city.getConfigKey(), Boolean.toString(enabled));
	}

	/**
	 * Moves the density dial, from the panel. Same rules as {@link #setCityEnabled}.
	 *
	 * <p>The value is {@link Enum#name()} because that is what {@code ConfigManager}
	 * stores an enum as and what it reads one back with, so this round-trips through the
	 * settings screen's dropdown rather than sitting beside it.
	 */
	void setCrowdDensity(CrowdDensity density)
	{
		if (config.crowdDensity() == density)
		{
			return;
		}

		configWriter.write(LivelyCitiesConfig.KEY_CROWD_DENSITY, density.name());
	}

	/**
	 * Brings one hidden citizen back, from the panel.
	 *
	 * <p>The panel exists for this. Hiding is per citizen; until now the only undo was
	 * a checkbox that unhid everybody, so taking back one decision cost every other one.
	 * {@link CitizenOverrides} does the work and skips a write that would change nothing;
	 * the respawn comes from the {@code ConfigChanged} that write posts, through the same
	 * visibility pass the checkbox uses.
	 */
	void unhide(UUID uuid)
	{
		overrides.unhide(uuid);
	}

	/** Lets one muted citizen talk again. Same shape as {@link #unhide}. */
	void unmute(UUID uuid)
	{
		overrides.unmute(uuid);
	}

	/**
	 * @return the local player's tile, or {@code null} if there is not one yet.
	 * {@code getLocalPlayer()} is null on {@code LOGGED_IN} and its
	 * {@code getWorldLocation()} can be null for a tick after that, which is why
	 * both halves are checked rather than just the first.
	 */
	@Nullable
	private WorldPoint playerLocation()
	{
		final Player local = client.getLocalPlayer();
		return local == null ? null : local.getWorldLocation();
	}

	/**
	 * @return how far through the current game tick this frame is, clamped to
	 * 0..1. Clamped rather than allowed to run past 1 because a dropped or
	 * delayed game tick would otherwise send citizens sliding past the tile they
	 * were walking to, and clamped at 0 because a frame drawn before the tick that
	 * would explain it must not drag one back past the tile it came from.
	 *
	 * <p><b>The subtraction stays in {@code int} on purpose.</b>
	 * {@code getGameCycle()} is an {@code int} counting 20ms ticks, so it wraps
	 * after about 497 days of client uptime — and two's-complement {@code int}
	 * subtraction wraps with it, which makes the elapsed count come out right
	 * across the seam. Promoting either side to {@code long} would turn that one
	 * frame into a huge negative elapsed, trip the {@code <= 0} guard, and freeze
	 * every citizen mid-step until the next game tick.
	 * {@code LivelyCitiesPluginLifecycleTest} pins both.
	 */
	private float tickFraction()
	{
		int elapsed = client.getGameCycle() - cycleAtLastTick;
		if (elapsed <= 0)
		{
			return 0f;
		}
		if (elapsed >= CLIENT_TICKS_PER_GAME_TICK)
		{
			return 1f;
		}
		return elapsed / (float) CLIENT_TICKS_PER_GAME_TICK;
	}

	@Provides
	LivelyCitiesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LivelyCitiesConfig.class);
	}

	/**
	 * The plugin's only overlay registration path — see {@link OverlayRegistry}.
	 */
	@Provides
	OverlayRegistry provideOverlayRegistry(OverlayManager overlayManager)
	{
		return new OverlayRegistry()
		{
			@Override
			public void add(Overlay overlay)
			{
				overlayManager.add(overlay);
			}

			@Override
			public void remove(Overlay overlay)
			{
				overlayManager.remove(overlay);
			}
		};
	}

	/**
	 * The panel's place in the sidebar — see {@link SidePanel}.
	 *
	 * <p><b>The button is built once here and added and removed</b>, rather than rebuilt
	 * on every toggle. {@code ClientToolbar} keys its navigation off the button instance,
	 * so a second one built on the way back in would leave the first behind — a button
	 * that cannot be removed by anything short of a client restart, which is the
	 * navigation-shaped version of the leaked active object this plugin already guards
	 * against.
	 *
	 * <p><b>{@code @Singleton} is what makes "once" structural rather than a property of
	 * there happening to be one injection point today.</b> A {@code @Provides} method with
	 * no scope on it runs once per injection point, so the day something else asks for a
	 * {@link SidePanel} — a second subscriber, a status overlay, anything — Guice builds a
	 * second button around a second panel, {@code startUp} adds whichever one it was given,
	 * and the other is a button nothing will ever remove. That is the leak the paragraph
	 * above is about, arriving by the one door the teardown test cannot see: it asserts
	 * that {@code shutDown} hides the {@link SidePanel} this plugin was handed, and that
	 * assertion goes on passing while a second one sits in the toolbar.
	 */
	@Provides
	@Singleton
	SidePanel provideSidePanel(ClientToolbar clientToolbar, LivelyCitiesPanel panel)
	{
		final NavigationButton button = NavigationButton.builder()
			.tooltip("Lively Cities")
			.icon(ImageUtil.loadImageResource(LivelyCitiesPanel.class, "panel_icon.png"))
			.priority(7)
			.panel(panel)
			.build();

		return new SidePanel()
		{
			@Override
			public void show()
			{
				clientToolbar.addNavigation(button);
			}

			@Override
			public void hide()
			{
				clientToolbar.removeNavigation(button);

				// Removing the navigation does not have to produce an onDeactivate, and
				// a panel that still believes it is open is a panel the game tick keeps
				// composing models for. Told here rather than inferred there.
				panel.closed();
			}

			@Override
			public boolean isOpen()
			{
				return panel.isOpen();
			}

			@Override
			public void refresh(PanelModel model)
			{
				panel.accept(model);
			}
		};
	}

	/**
	 * The plugin's only write path into its own settings.
	 *
	 * <p>This method is the whole reason {@link ConfigWriter} exists — see its
	 * javadoc. {@code ConfigManager}'s constructor is private, so anything that took
	 * one directly could not be constructed by a test; behind this one lambda,
	 * everything that decides <i>what</i> to write is testable against a map.
	 */
	@Provides
	ConfigWriter provideConfigWriter(ConfigManager configManager)
	{
		return (key, value) ->
		{
			if (value == null)
			{
				configManager.unsetConfiguration(LivelyCitiesConfig.GROUP, key);
			}
			else
			{
				configManager.setConfiguration(LivelyCitiesConfig.GROUP, key, value);
			}
		};
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * One {@link EntityDefinition} bound to one {@link RuneLiteObject}.
 *
 * <p><b>Every method here must run on the client thread.</b> All of it reaches
 * into live client state: {@code loadModelData} and {@code mergeModels} read the
 * model cache, {@code light} allocates against it, {@code setActive} adds to and
 * removes from the client's registered-object list, and
 * {@code RuneLiteObject.setLocation(LocalPoint, int)} calls
 * {@code Perspective.getTileHeight(client, ..)}, which reads the scene's tile
 * settings and tile heights to work out {@code z}. That last one is the
 * {@link RuneLiteObject} override, verified by disassembling 1.12.36 — the base
 * {@code RuneLiteObjectController.setLocation} really does nothing but
 * {@code setX}/{@code setY}/{@code setWorldView}/{@code setLevel}, so reading
 * only the base class makes the call look thread-safe when it is not. The client
 * does the {@code z} fix-up for us; we never set it ourselves.
 *
 * <p>The built model is cached for the lifetime of the wrapper, so walking in
 * and out of a region costs an activate/deactivate rather than a rebuild.
 *
 * <p>Two kinds of failure, kept apart on purpose, because caching the wrong one
 * loses an entity for the whole session:
 * <ul>
 *   <li><b>Structural</b> — the client refuses to create an object, the merge
 *       returns nothing, lighting returns nothing, {@code setActive(true)} does
 *       not take, or anything throws. Nothing about the next tick will be
 *       different, so the entity is marked {@link #broken} and never retried.
 *       That is what stops a bad model producing one warning per game tick,
 *       forever.</li>
 *   <li><b>Transient</b> — {@code loadModelData} returned null for some or all
 *       of the parts, the record's {@code npcAppearanceId} would not resolve to an
 *       appearance (see {@link NpcAppearance}), or {@code loadAnimation} returned
 *       null for an animation the record asked for. On a cold cache all three are
 *       routine and say nothing about the id: the field report behind this code had
 *       84 distinct model ids missing right after login and present later, and
 *       animations and NPC compositions come out of the same cache archives. So
 *       none is latched; all are retried, at most
 *       {@link #MAX_MODEL_ATTEMPTS} / {@link #MAX_ANIMATION_ATTEMPTS} times per
 *       scene load ({@link #onScopeEntered()} hands back both budgets) and spaced
 *       by {@link #RETRY_BACKOFF_PASSES}, which lets a warm cache heal the entity
 *       without a per-tick retry storm.</li>
 * </ul>
 *
 * <p>The difference between the two is which way the entity fails while it waits.
 * A missing model means no citizen at all, so the spawn is deferred. A missing
 * animation means a citizen standing in the right place holding still, which is
 * better than an absent one — so it spawns, and the animation is picked up
 * whenever the cache produces it.
 *
 * <p>A partial resolve counts as a failure, not as a model. Spawning the parts
 * that did load is how a citizen ends up with no head or no boots — and since
 * the model is cached, it would have stayed that way for the session.
 *
 * <p><b>Movement is split across two clocks</b>, and which half does what is not
 * an implementation detail:
 * <ul>
 *   <li>{@link #advanceTick()} is called once per game tick. It steps the walk one
 *       tile, faces the citizen the way it is going, and switches between the
 *       idle and move animations. Walking speed therefore comes from the game's
 *       clock, not the frame rate.</li>
 *   <li>{@link #advanceFrame(WorldView, float)} is called once per frame. It slides
 *       the drawn position between the tile the citizen left and the tile it is
 *       heading for. Nothing else per frame — in particular <i>not</i>
 *       {@code RuneLiteObject.tick(..)}, which the client already calls once per
 *       frame for every registered object and which is what advances the
 *       animation.</li>
 * </ul>
 */
@Slf4j
final class LivelyEntity
{
	/**
	 * Lighting used by the source dataset's authoring tool. Changing these
	 * changes the look of all 311 entities, so they stay put.
	 */
	private static final int LIGHT_AMBIENT = 64;
	private static final int LIGHT_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	/**
	 * Model units per tile. The dataset stores scale/translate as tile
	 * fractions.
	 */
	private static final int UNITS_PER_TILE = 128;

	/**
	 * How many times a model-data miss is retried before this entity gives up
	 * until the next scene load. Three, spaced by
	 * {@link #RETRY_BACKOFF_PASSES}, so a genuinely absent model costs three
	 * attempts and three log lines per scene load rather than one per tick.
	 */
	static final int MAX_MODEL_ATTEMPTS = 3;

	/**
	 * Visibility passes between retries. The cache this is waiting on warms up
	 * over seconds, not ticks: three attempts on three consecutive ticks would
	 * spend the whole budget inside two seconds of a cold login and then leave
	 * the entity waiting for a border crossing. At 600ms a tick this spreads the
	 * three attempts over roughly half a minute, which is the timescale the
	 * field report describes.
	 */
	static final int RETRY_BACKOFF_PASSES = 25;

	/**
	 * How many times an animation that would not load is asked for again before
	 * this entity settles for a static model until the next scene load.
	 *
	 * <p>Same shape and the same reasoning as {@link #MAX_MODEL_ATTEMPTS}, because
	 * it is the same failure. {@code client.loadAnimation(id)} — which is what
	 * {@code new AnimationController(client, id)} calls, verified in the 1.12.36
	 * bytecode — returns {@code null} when the sequence it resolves has no frame
	 * lengths and is not a Maya animation, and the sequence comes out of the
	 * client's own cache archive just like a model does. A controller built on a
	 * {@code null} animation is inert forever: {@code tick}, {@code loop} and
	 * {@code getPackedFrame} all return immediately, so the object draws its base
	 * model unanimated. Caching one — which this class used to do unconditionally —
	 * froze the citizen for the rest of the session on a single cold-cache miss.
	 *
	 * <p>Two causes, and the retry is what tells them apart in a log rather than
	 * in a guess: a cold cache (transient, and this fixes it), or an id that has
	 * no frames at all (permanent — {@code LivelyAnimation.BeeIdle} is id 0, which
	 * is a prime suspect). Either way three attempts per scene load, spaced by
	 * {@link #RETRY_BACKOFF_PASSES}, is the difference between one line in the log
	 * and one line per game tick forever.
	 */
	static final int MAX_ANIMATION_ATTEMPTS = 3;

	private final Client client;
	private final EntityDefinition definition;

	/** The walk, for a wandering citizen; {@code null} for everything else. */
	private final CitizenWalk walk;

	/**
	 * What this citizen can say and what it is saying; {@code null} for the 257 of
	 * 311 shipped entities with nothing authored.
	 *
	 * <p>Owned here, on the wrapper, rather than in the overlay — see
	 * {@link CitizenRemarks}. The consequence that matters is one line down in
	 * {@link #despawn()}: a citizen that leaves the screen stops talking as part of
	 * leaving, so there is no list an orphaned bubble could survive in.
	 */
	private final CitizenRemarks remarks;

	private RuneLiteObject object;
	private Model model;
	private boolean broken;

	/**
	 * The NPC appearance this entity wears, once the client has produced it;
	 * {@code null} for an entity dressed from raw {@code modelIds}, and for one that
	 * is still waiting on the composition.
	 *
	 * <p>Cached because it is the entity's <i>body</i> — the model ids and the
	 * recolour pairs both come out of it, and {@link #assemble} runs after
	 * {@link #loadParts()} rather than inside it. Only ever assigned a resolved
	 * appearance, so a miss leaves it null and the next visibility pass asks again
	 * — the same rule as {@link #idleController}, and for the same reason.
	 */
	private NpcAppearance appearance;

	/**
	 * The two animation controllers, built on first use and then kept.
	 *
	 * <p>Kept rather than rebuilt on every switch because an
	 * {@code AnimationController} <i>is</i> the animation's playback position:
	 * constructing one, or calling {@code setAnimation} on one, resets its frame
	 * to zero. Re-creating a controller every game tick is exactly what makes a
	 * walk cycle look like a stutter instead of a walk — the client advances the
	 * frames between game ticks, and then something throws that progress away
	 * 1.6 times a second. Holding both means a citizen also resumes its walk
	 * cycle mid-stride rather than restarting it on every step.
	 *
	 * <p><b>Only ever assigned a controller that actually has an animation.</b>
	 * {@link #looping} returns null on a failed load and these stay null, so the
	 * next call tries again — see {@link #MAX_ANIMATION_ATTEMPTS}. Caching a
	 * controller whose animation is null is caching a permanently inert object,
	 * which is what this class used to do.
	 */
	private AnimationController idleController;
	private AnimationController moveController;

	/** The controller currently handed to the object, for the identity compare. */
	private AnimationController installed;

	/**
	 * True once the object sits at a position that cannot change again before the
	 * next game tick — i.e. the citizen has stopped and the frame pass has already
	 * placed it there.
	 *
	 * <p>Cleared by every spawn, every despawn and every tick, so a citizen is
	 * always placed at least once per game tick and is skipped only while it is
	 * genuinely standing still. That is most citizens most of the time, and
	 * {@code setLocation} is not free — it runs
	 * {@code Perspective.getTileHeight} against the live scene.
	 */
	private boolean positionSettled;

	/** Model-load attempts spent since the last {@link #onScopeEntered()}. */
	private int modelAttempts;

	/** Visibility passes since the last attempt, for the retry spacing. */
	private int passesSinceAttempt;

	/**
	 * Animation loads that came back {@code null} since the last
	 * {@link #onScopeEntered()}. Counts misses only, so resolving the move
	 * animation after the idle one does not spend anything.
	 */
	private int animationMisses;

	/** Visibility passes since the last animation miss, for the retry spacing. */
	private int passesSinceAnimationMiss;

	/**
	 * Set each visibility pass by {@link EntityScene}: whether this entity
	 * should be active right now.
	 */
	private boolean wanted;

	LivelyEntity(Client client, EntityDefinition definition)
	{
		this.client = client;
		this.definition = definition;
		this.walk = CitizenWalk.forDefinition(definition);
		this.remarks = CitizenRemarks.forDefinition(definition);
	}

	EntityDefinition getDefinition()
	{
		return definition;
	}

	/**
	 * @return this entity's walk, or {@code null} if it stands still — which is
	 * every {@code Scenery}, every {@code StationaryCitizen}, every
	 * {@code ScriptedCitizen}, and any {@code WanderingCitizen} whose box did not
	 * validate
	 */
	@Nullable
	CitizenWalk getWalk()
	{
		return walk;
	}

	/**
	 * @return this citizen's remarks, or {@code null} if it has nothing authored to
	 * say — which is every {@code Scenery} record and 215 of the 269 citizens
	 */
	@Nullable
	CitizenRemarks getRemarks()
	{
		return remarks;
	}

	boolean isWanted()
	{
		return wanted;
	}

	void setWanted(boolean wanted)
	{
		this.wanted = wanted;
	}

	boolean isBroken()
	{
		return broken;
	}

	/**
	 * Latches this entity out of every later pass, without a log line — the
	 * caller has more context and does the logging. For {@link EntityScene} to
	 * use when the throw came from outside {@link #spawn} / {@link #despawn}.
	 */
	void markBroken()
	{
		broken = true;
		wanted = false;
		silence();
	}

	/**
	 * Stops this citizen talking, now.
	 *
	 * <p>Called from every path that takes it off the screen. A remark is text
	 * hanging in the air above a model, so the moment the model is not being drawn
	 * the text must not be either — and the only way to guarantee that is for the
	 * thing that removes the model to be the thing that removes the text.
	 */
	private void silence()
	{
		if (remarks != null)
		{
			remarks.clear();
		}
	}

	/**
	 * Hands back the model-load budget. Called when this entity's region enters
	 * scope: a scene load is the right granularity at which to re-test a cold
	 * model cache, and together with {@link #RETRY_BACKOFF_PASSES} it is what
	 * bounds the retries to a handful per border crossing instead of one per
	 * tick.
	 */
	void onScopeEntered()
	{
		modelAttempts = 0;
		passesSinceAttempt = 0;
		animationMisses = 0;
		passesSinceAnimationMiss = 0;
	}

	/**
	 * @return whether the client currently has this object registered. Asks the
	 * client rather than trusting local bookkeeping, so teardown evidence is
	 * real.
	 */
	boolean isActive()
	{
		return object != null && object.isActive();
	}

	/**
	 * Builds (once) and activates the object. Client thread only.
	 *
	 * @param worldView the view whose scene the entity is being placed in
	 * @return true if the object is active when this returns
	 */
	boolean spawn(WorldView worldView)
	{
		try
		{
			return trySpawn(worldView);
		}
		catch (RuntimeException e)
		{
			// The visibility pass runs from an EventBus handler. Letting this
			// out abandons every entity after this one in the pass — including
			// the ones that were supposed to deactivate — and does it again on
			// the next tick, because nothing would have marked the offender.
			// One entity's bad luck costs that entity.
			broken = true;
			wanted = false;
			log.warn("{}: threw while spawning, not retrying", definition.label(), e);
			return false;
		}
	}

	/**
	 * Deactivates the object if it is active. Client thread only.
	 *
	 * @return true if this call actually deactivated something
	 */
	boolean despawn()
	{
		try
		{
			// Unconditionally, and before the isActive() check: this method is called
			// for every unwanted entity on every visibility pass, so "silence
			// anything that is not on screen" costs one null check and holds even for
			// an entity that was never active.
			silence();

			if (!isActive())
			{
				return false;
			}

			object.setActive(false);
			positionSettled = false;
			log.debug("despawned {} (region {})", definition.label(), definition.getRegionId());
			return true;
		}
		catch (RuntimeException e)
		{
			// Same reasoning as spawn(), and the stakes are higher: this runs
			// from teardown loops that must reach every other entity.
			broken = true;
			wanted = false;
			log.warn("{}: threw while despawning", definition.label(), e);
			return false;
		}
	}

	private boolean trySpawn(WorldView worldView)
	{
		if (broken)
		{
			return false;
		}

		if (isActive())
		{
			return true;
		}

		// A wanderer comes back where it left off, not where it was authored: it
		// does not walk while deactivated, so its walk still holds the tile it was
		// standing on when the player walked away from it.
		LocalPoint location = walk == null
			? LocalPoint.fromWorld(worldView, definition.getWorldLocation())
			: walk.localPoint(worldView, 1f);
		if (location == null)
		{
			// Outside the loaded scene, or the view moved plane between the
			// candidate check and here. Not an error.
			return false;
		}

		if (object == null)
		{
			object = client.createRuneLiteObject();
			if (object == null)
			{
				log.warn("{}: client refused to create a RuneLiteObject", definition.label());
				broken = true;
				return false;
			}
		}

		if (model == null)
		{
			List<ModelData> parts = loadParts();
			if (parts == null)
			{
				// Transient: nothing cached, nothing latched, try again later.
				return false;
			}

			model = assemble(parts);
			if (model == null)
			{
				broken = true;
				return false;
			}

			object.setModel(model);
			object.setOrientation(definition.getOrientation());
			select(idleControllerOrNull());
		}

		object.setLocation(location, definition.getPlane());
		object.setActive(true);

		if (!object.isActive())
		{
			// The client took the call and still does not have the object. That
			// is not going to change on the next tick, and leaving it unlatched
			// is a WARN line per entity per tick, forever.
			log.warn("{}: setActive(true) did not take, not retrying", definition.label());
			broken = true;
			wanted = false;
			return false;
		}

		// The frame pass owns the exact position from here on; make sure it takes
		// one look at a citizen that has just come back.
		positionSettled = false;

		log.debug("spawned {} (region {})", definition.label(), definition.getRegionId());
		return true;
	}

	/**
	 * One game tick of walking, for a wandering citizen: take a step, face the way
	 * it is going, and switch between the idle and move animations.
	 *
	 * <p>Client thread only. Does nothing for anything that stands still, and
	 * nothing while deactivated — a citizen the player cannot see does not need to
	 * have been walking, and freezing it means it is still inside its box when the
	 * player comes back.
	 */
	void advanceTick()
	{
		if (walk == null || broken || !isActive())
		{
			return;
		}

		walk.tick();

		// Idle ↔ move. select() compares controllers by identity, so a citizen
		// mid-walk re-selects the one it already has and the object is left
		// alone — which is what keeps the animation's frame counter intact.
		select(walk.isMoving() ? moveControllerOrNull() : idleControllerOrNull());

		// Facing the direction of travel while moving, back to the authored
		// baseOrientation once it stops. CitizenWalk decides which; this only
		// writes it.
		object.setOrientation(walk.getOrientation());

		// This tick may have moved the citizen — including onto the tile it was
		// heading for, which is the case where it stops — so the frame pass has to
		// take at least one look before it is allowed to skip it again.
		positionSettled = false;
	}

	/**
	 * One frame of visual interpolation, for a wandering citizen.
	 *
	 * <p>Client thread only. This is the part that has to happen per frame rather
	 * than per game tick: {@code RuneLiteObject} has no walk API at all, so
	 * without this a citizen jumps a whole tile every 600ms.
	 *
	 * <p>It deliberately does <b>not</b> touch the animation. The client calls
	 * {@code RuneLiteObject.tick(ticksSinceLastFrame)} once per frame for every
	 * registered object, which is what advances the {@code AnimationController};
	 * calling it here as well would run every animation at double speed.
	 *
	 * @param fraction how far through the current game tick this frame is, 0..1
	 */
	void advanceFrame(WorldView worldView, float fraction)
	{
		if (walk == null || broken || !isActive())
		{
			return;
		}

		if (positionSettled)
		{
			// Standing still and already placed. Most citizens, most frames.
			return;
		}

		LocalPoint location = walk.localPoint(worldView, fraction);
		if (location == null)
		{
			// Walked to a tile the client has not loaded. Leaving the object where
			// it is beats moving it somewhere that does not mean anything.
			return;
		}

		object.setLocation(location, definition.getPlane());
		positionSettled = !walk.isMoving();
	}

	/**
	 * @return the animation currently driving the model, or {@code null} for a
	 * static one. Only meaningful once the model has been built.
	 */
	@Nullable
	AnimationController getInstalledController()
	{
		return installed;
	}

	/**
	 * @return the NPC appearance this entity is wearing, or {@code null} if it is
	 * dressed from raw model ids or has not resolved one yet. For the tests: "it used
	 * the NPC's models rather than the record's" and "it is still waiting" are two
	 * outcomes that otherwise look identical from outside.
	 */
	@Nullable
	NpcAppearance getAppearance()
	{
		return appearance;
	}

	// --- What the client is about to draw ------------------------------------
	//
	// Four read-only accessors for the two things that have to project this entity
	// into screen space: CitizenMenu's clickbox and ChatterOverlay's text position.
	// Deliberately four narrow getters rather than handing out the RuneLiteObject:
	// this class is the only writer of the object's state, and a caller that could
	// reach setActive or setLocation would be a second definition of the lifecycle
	// and of how fast a citizen walks.
	//
	// They read the object rather than the definition on purpose. The definition
	// holds the authored tile, which is where a wandering citizen is not; the object
	// holds the position the frame pass last put it at, which is where the client
	// will draw it this frame. Text that used the authored tile would sit still
	// while its citizen walked away from it — one of the two bugs the overlay exists
	// to make impossible.

	/**
	 * @return the lit model, or {@code null} before it has been built (a cold model
	 * cache) or if the build failed
	 */
	@Nullable
	Model getRenderedModel()
	{
		return model;
	}

	/**
	 * @return the local position the object currently holds, or {@code null} if it
	 * has never been placed. {@code RuneLiteObjectController.getLocation()} builds
	 * this from the x/y/worldView it was last given, so it is the frame pass's own
	 * answer rather than a second computation of it.
	 */
	@Nullable
	LocalPoint getRenderLocation()
	{
		return object == null ? null : object.getLocation();
	}

	/**
	 * @return the height the client fixed up when the object was placed. Set by
	 * {@code RuneLiteObject.setLocation}, which runs
	 * {@code Perspective.getTileHeight} — this plugin never writes it.
	 */
	int getRenderZ()
	{
		return object == null ? 0 : object.getZ();
	}

	/**
	 * @return the orientation the object is drawn at, in 0..2047 — the direction of
	 * travel for a walking citizen, the authored {@code baseOrientation} otherwise.
	 * Falls back to the authored value when there is no object yet, so a clickbox
	 * computed a frame too early is wrong by nothing worse than a facing.
	 */
	int getRenderOrientation()
	{
		return object == null ? definition.getOrientation() : object.getOrientation();
	}

	/**
	 * Hands the object a controller, but only when it is not the one it already
	 * has. The identity compare is the whole point — see
	 * {@link #idleController}.
	 */
	private void select(@Nullable AnimationController controller)
	{
		if (controller == installed)
		{
			return;
		}

		installed = controller;
		object.setAnimationController(controller);
	}

	@Nullable
	private AnimationController idleControllerOrNull()
	{
		LivelyAnimation animation = definition.getIdleAnimation();
		if (animation == null)
		{
			// A static model is a legitimate outcome — most scenery has no
			// animation at all, and an unknown animation name degrades to this.
			return null;
		}

		if (idleController == null)
		{
			idleController = looping(animation);
		}
		return idleController;
	}

	@Nullable
	private AnimationController moveControllerOrNull()
	{
		LivelyAnimation animation = definition.getMoveAnimation();
		if (animation == null)
		{
			// Every shipped wanderer has one, but a citizen with an unknown
			// moveAnimation name should keep whatever it idles as while walking
			// rather than freeze into a static model mid-step.
			return idleControllerOrNull();
		}

		if (moveController == null)
		{
			moveController = looping(animation);
		}
		return moveController;
	}

	/**
	 * Builds a looping controller, or returns {@code null} without caching
	 * anything if the client would not give us the animation.
	 *
	 * <p>Not {@code setAnimation(..)}: that is sugar for exactly this, and the
	 * looping half of the old API ({@code setShouldLoop}) is deprecated. An
	 * {@code AnimationController} defaults to {@code AnimationController::loop},
	 * but say so explicitly so a future default change cannot silently make every
	 * citizen freeze on their last frame.
	 *
	 * <p><b>The null check is the whole point.</b> The constructor swallows a
	 * failed load — it calls {@code client.loadAnimation(id)} and hands the result,
	 * null or not, straight to {@code setAnimation} — so the only way to tell is to
	 * ask the controller what animation it ended up with. See
	 * {@link #MAX_ANIMATION_ATTEMPTS} for why that is treated as transient and
	 * bounded rather than as a permanent verdict on the id.
	 */
	@Nullable
	private AnimationController looping(LivelyAnimation animation)
	{
		if (animationMisses >= MAX_ANIMATION_ATTEMPTS)
		{
			return null;
		}

		if (animationMisses > 0 && ++passesSinceAnimationMiss < RETRY_BACKOFF_PASSES)
		{
			return null;
		}

		AnimationController controller = new AnimationController(client, animation.getId());
		if (controller.getAnimation() == null)
		{
			animationMisses++;
			passesSinceAnimationMiss = 0;

			if (animationMisses == 1)
			{
				log.warn("{}: animation {} (id {}) did not load — spawning it static for now; "
						+ "a cold animation cache is the usual cause, so it will be retried up to "
						+ "{} time(s) per scene load. An id with no frames at all never resolves.",
					definition.label(), animation, animation.getId(), MAX_ANIMATION_ATTEMPTS);
			}
			else
			{
				log.debug("{}: animation {} (id {}) still not loading (attempt {} of {})",
					definition.label(), animation, animation.getId(),
					animationMisses, MAX_ANIMATION_ATTEMPTS);
			}

			return null;
		}

		controller.setOnFinished(AnimationController::loop);
		return controller;
	}

	/**
	 * Asks again for an animation that did not load, for an entity that is already
	 * on screen.
	 *
	 * <p>Called once per visibility pass by {@link EntityScene}. A wandering
	 * citizen would get its retry from {@link #advanceTick()} anyway, which
	 * re-selects every game tick; a {@code StationaryCitizen} would not, and there
	 * are plenty of those with idle animations. Without this, "it loaded the model
	 * but not the animation" would be permanent for everything that stands still —
	 * which is the same bug the {@code null} check in {@link #looping} fixes, one
	 * level up.
	 *
	 * <p>Costs a field compare and returns once the animation is installed, which
	 * is the case for every entity that is working. Client thread only.
	 */
	void retryMissingAnimation()
	{
		if (broken || model == null || installed != null || !isActive())
		{
			return;
		}

		if (definition.getIdleAnimation() == null && definition.getMoveAnimation() == null)
		{
			// Static by design: every Scenery record, and any citizen whose
			// animation name this build does not know. Not a cache miss, so not
			// something to retry.
			return;
		}

		select(walk != null && walk.isMoving() ? moveControllerOrNull() : idleControllerOrNull());
	}

	/**
	 * Loads every model this entity is made of.
	 *
	 * @return all of the requested parts, or {@code null} if even one did not
	 * load — never a partial list. Costs at most one of
	 * {@link #MAX_MODEL_ATTEMPTS} and returns {@code null} without touching the
	 * client while a retry is still backing off, or once the budget is gone.
	 */
	@Nullable
	private List<ModelData> loadParts()
	{
		if (modelAttempts >= MAX_MODEL_ATTEMPTS)
		{
			return null;
		}

		if (modelAttempts > 0 && ++passesSinceAttempt < RETRY_BACKOFF_PASSES)
		{
			return null;
		}

		passesSinceAttempt = 0;
		modelAttempts++;

		// Which ids to build is itself a question for the client when the record
		// names an NPC instead of listing models — and it is asked inside the budget,
		// after it has been spent, so a composition that will not resolve costs the
		// same three attempts and three log lines a missing model does rather than
		// one per game tick.
		int[] modelIds = modelIdsToBuild();
		if (modelIds == null)
		{
			return null;
		}

		List<EntityDefinition.MergedObject> merged = definition.getMergedObjects();
		int requested = modelIds.length + merged.size();

		List<ModelData> parts = new ArrayList<>(requested);
		StringBuilder missing = new StringBuilder();

		for (int modelId : modelIds)
		{
			ModelData part = client.loadModelData(modelId);
			if (part == null)
			{
				note(missing, modelId);
				continue;
			}
			parts.add(part);
		}

		for (EntityDefinition.MergedObject entry : merged)
		{
			ModelData part = client.loadModelData(entry.getObjectId());
			if (part == null)
			{
				note(missing, entry.getObjectId());
				continue;
			}

			for (int i = 0; i < entry.getRotations(); i++)
			{
				part.cloneVertices();
				part.rotateY90Ccw();
			}
			parts.add(part);
		}

		if (parts.size() == requested)
		{
			return parts;
		}

		// One line for the entity, not one per id: a cold cache misses whole
		// handfuls at once, and the per-id version was the noise this class
		// exists to avoid.
		if (modelAttempts == 1)
		{
			log.warn("{}: only {} of {} model part(s) loaded, missing id(s) {} — not spawning; "
					+ "a cold model cache is the usual cause, so it will be retried up to {} time(s) per scene load",
				definition.label(), parts.size(), requested, missing, MAX_MODEL_ATTEMPTS);
		}
		else
		{
			log.debug("{}: still only {} of {} model part(s), missing id(s) {} (attempt {} of {})",
				definition.label(), parts.size(), requested, missing, modelAttempts, MAX_MODEL_ATTEMPTS);
		}

		return null;
	}

	/**
	 * The model ids this entity is made of — the record's own, or the ones an NPC
	 * composition supplies.
	 *
	 * <p>Costs one of {@link #MAX_MODEL_ATTEMPTS}, already spent by the caller.
	 *
	 * @return the ids, or {@code null} if the record names an NPC whose appearance
	 * the client would not give us. Never falls back to the record's {@code modelIds}
	 * — see {@link NpcAppearance} for why a different body in the right place is
	 * worse than no body.
	 */
	@Nullable
	private int[] modelIdsToBuild()
	{
		int npcId = definition.getNpcAppearanceId();
		if (npcId == 0)
		{
			return definition.getModelIds();
		}

		if (appearance != null)
		{
			return appearance.getModelIds();
		}

		NpcAppearance resolved = NpcAppearance.resolve(client, npcId, definition.label());
		if (resolved == null)
		{
			// One line for the entity, on the first attempt only — the same shape as
			// the missing-model line below, because it is the same failure from the
			// player's point of view: nothing spawns.
			if (modelAttempts == 1)
			{
				log.warn("{}: npcAppearanceId {} would not resolve to an appearance — not spawning; "
						+ "a cold cache is one cause and a renumbered NPC id is the other, so it will be "
						+ "retried up to {} time(s) per scene load. Run ./gradlew auditCacheIds to tell "
						+ "them apart.",
					definition.label(), npcId, MAX_MODEL_ATTEMPTS);
			}
			else
			{
				log.debug("{}: npcAppearanceId {} still not resolving (attempt {} of {})",
					definition.label(), npcId, modelAttempts, MAX_MODEL_ATTEMPTS);
			}
			return null;
		}

		appearance = resolved;
		log.debug("{}: dressed from NPC {} ('{}') — {} model(s), {} recolour pair(s)",
			definition.label(), npcId, resolved.getNpcName(),
			resolved.getModelIds().length, resolved.getRecolorFind().length);
		return resolved.getModelIds();
	}

	/**
	 * Merges, recolours, transforms and lights a complete set of parts.
	 *
	 * @return the lit model, or {@code null} for a structural failure — the
	 * caller latches those.
	 */
	@Nullable
	private Model assemble(List<ModelData> parts)
	{
		// Always merge, even for a single part: mergeModels returns a fresh
		// ModelData, and recolour/scale below mutate in place. Recolouring a
		// bare loadModelData result would corrupt the client's shared cache
		// entry for every other user of that model.
		ModelData combined = client.mergeModels(parts.toArray(new ModelData[0]), parts.size());
		if (combined == null)
		{
			log.warn("{}: mergeModels returned null for {} part(s), cannot spawn",
				definition.label(), parts.size());
			return null;
		}

		// The NPC's palette when the entity is wearing one, the record's otherwise.
		// The pair has to come from the same place the models did: a find/replace list
		// authored against one model's colours repaints nothing on another's, and
		// would silently leave the citizen in the NPC's own default colours while
		// looking like a recolour that worked.
		short[] find = appearance != null ? appearance.getRecolorFind() : definition.getRecolorFind();
		short[] replace = appearance != null ? appearance.getRecolorReplace() : definition.getRecolorReplace();
		if (find.length > 0)
		{
			// ModelData.recolor's own javadoc says to call cloneColors() first.
			// "mergeModels hands back a fresh instance" is an observation about
			// an obfuscated constructor, not a contract: 21 shipped entities are
			// single-part models carrying recolours, so a single-part fast path
			// that shared faceColors would repaint every instance of that model
			// in the world, through the client's own cache.
			combined.cloneColors();
			for (int i = 0; i < find.length; i++)
			{
				combined.recolor(find[i], replace[i]);
			}
		}

		// Sign convention comes from the dataset's authoring tool: the stored
		// values are negated on the way into model space (model Y is up-negative).
		float[] scale = definition.getScale();
		if (scale != null)
		{
			combined.cloneVertices();
			combined.scale(
				-Math.round(scale[0] * UNITS_PER_TILE),
				-Math.round(scale[1] * UNITS_PER_TILE),
				-Math.round(scale[2] * UNITS_PER_TILE));
		}

		float[] translate = definition.getTranslate();
		if (translate != null)
		{
			combined.cloneVertices();
			combined.translate(
				-Math.round(translate[0] * UNITS_PER_TILE),
				-Math.round(translate[1] * UNITS_PER_TILE),
				-Math.round(translate[2] * UNITS_PER_TILE));
		}

		Model lit = combined.light(LIGHT_AMBIENT, LIGHT_CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
		if (lit == null)
		{
			log.warn("{}: lighting produced no model, cannot spawn", definition.label());
			return null;
		}

		return lit;
	}

	private static void note(StringBuilder missing, int modelId)
	{
		if (missing.length() > 0)
		{
			missing.append(", ");
		}
		missing.append(modelId);
	}
}

package com.matthewmariner.livelycities;

import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;

/**
 * One existing NPC's appearance — its model parts and its recolour pairs — read
 * off the client so a record can wear it instead of listing raw {@code modelIds}.
 *
 * <p><b>Why this is the better mechanism, and why it is not a retrofit.</b> A raw
 * model id is an unnamed number that a game update can renumber underneath the
 * dataset; that is exactly what killed the predecessor plugin (see
 * {@code README.md}). An NPC id is a generated constant in
 * {@code net.runelite.api.gameval.NpcID}, reviewable by anyone with the jar, and
 * one indirection further from the geometry an artist reworks. So new authored
 * content prefers this, and the vendored entities keep their {@code modelIds}
 * unchanged with one exception — "Rufus", whose authored array had no footwear model
 * in it at all (GitHub issue #1), so there was nothing worth keeping.
 * {@code EntityRecord.npcAppearanceId} says which wins when a record carries both.
 *
 * <p><b>The accessors, verified against 1.12.36 rather than guessed.</b>
 * {@code javap net.runelite.api.Client} declares
 * {@code public abstract net.runelite.api.NPCComposition getNpcDefinition(int);}
 * and {@code javap net.runelite.api.NPCComposition} declares exactly three
 * accessors this class needs — {@code public abstract int[] getModels();},
 * {@code public abstract short[] getColorToReplace();} and
 * {@code public abstract short[] getColorToReplaceWith();} (plus
 * {@code getName()}, used only for the log line). In the injected client
 * ({@code injected-client-1.12.36.jar}) the composition is class {@code pl}, and
 * all three of those accessors compile to a bare {@code getfield} + {@code areturn}
 * on {@code cf:[I}, {@code dt:[S} and {@code dr:[S} respectively — <b>so every one
 * of them can be {@code null}</b>, because those fields are only assigned for a
 * composition whose cache entry carried that opcode. Nothing here treats a null as
 * an empty array.
 *
 * <p><b>Two ways of not resolving, and both are handled.</b>
 * {@code client.getNpcDefinition(id)} is {@code client.kz(id)} → {@code oh.ae(id, ..)},
 * which asserts {@code isClientThread()} and then looks the id up in
 * {@code pl.cy} (a cache) or loads it from archive 9. When the archive has no
 * entry, {@code va.bb(..)} returns {@code null} and the {@code pl} constructor is
 * handed a {@code null} buffer — inside a {@code catch (RuntimeException)} that
 * rethrows as the client's own wrapper. So an id that does not resolve
 * <b>throws</b>, rather than returning {@code null}, and a composition that does
 * resolve may still have no models. Both come back from {@link #resolve} as
 * {@code null}, and the caller ({@link LivelyEntity#loadParts()}) treats that
 * exactly like a model-cache miss: the entity does not spawn, one {@code warn} is
 * written, and it is retried on the same bounded, backed-off budget. Never a
 * partial build, never a throw out of here, and never a silent fall back to the
 * record's own {@code modelIds} — a different body in the right place is worse than
 * no body.
 *
 * <p><b>Deliberately not cloned from the composition:</b> {@code getWidthScale()} /
 * {@code getHeightScale()} and {@code getSize()}. The scale pair is a 128-based
 * multiplier in the client's own units and the dataset's {@code scale} field is
 * tile fractions with an inverted sign convention (see
 * {@code LivelyEntity.assemble}); mapping between them is arithmetic this could not
 * verify without a live client, and getting it wrong silently is a citizen at the
 * wrong height. The seven NPCs this currently sources are ordinary human-sized
 * townsfolk, so identity scale is the right answer for them — a future
 * non-human-sized NPC would render at default size, which is a known limitation
 * rather than a surprise. {@code transform()} is likewise not called: it reads live
 * varbit state to pick between a multi-form NPC's shapes, and a multi-form NPC
 * whose base composition has no models simply fails the {@code getModels()} check
 * above and is skipped with a warn naming it.
 *
 * <p><b>Client thread only</b> — {@code getNpcDefinition} asserts it.
 */
@Slf4j
final class NpcAppearance
{
	private final int npcId;
	private final String npcName;
	private final int[] modelIds;
	private final short[] recolorFind;
	private final short[] recolorReplace;

	private NpcAppearance(
		int npcId,
		@Nullable String npcName,
		int[] modelIds,
		short[] recolorFind,
		short[] recolorReplace)
	{
		this.npcId = npcId;
		this.npcName = npcName;
		this.modelIds = modelIds;
		this.recolorFind = recolorFind;
		this.recolorReplace = recolorReplace;
	}

	/**
	 * Reads one NPC's appearance.
	 *
	 * @param client the live client. Client thread only.
	 * @param npcId  the NPC id to clone
	 * @param label  the entity this is for, for the log line
	 * @return the appearance, or {@code null} if the id does not resolve, the
	 * composition has no models, or every model id it lists is unusable. Never
	 * throws. Writes nothing — the caller owns the warn, because only it knows
	 * whether this is the first attempt or a retry.
	 */
	@Nullable
	static NpcAppearance resolve(Client client, int npcId, String label)
	{
		if (npcId <= 0)
		{
			// Not reachable through EntityDefinition, which drops a non-positive id
			// at the validation gate. Here so a future caller cannot ask the client
			// about a sentinel.
			return null;
		}

		NPCComposition composition;
		try
		{
			composition = client.getNpcDefinition(npcId);
		}
		catch (RuntimeException e)
		{
			// The ordinary "this id no longer exists" case — see the class javadoc,
			// the client throws rather than returning null for a missing archive
			// entry. Debug, not warn: the caller decides what to say and how often.
			log.debug("{}: npcAppearanceId {} threw on lookup", label, npcId, e);
			return null;
		}

		if (composition == null)
		{
			log.debug("{}: npcAppearanceId {} resolved to no composition", label, npcId);
			return null;
		}

		int[] models = usableModelIds(composition.getModels(), label, npcId);
		if (models.length == 0)
		{
			log.debug("{}: npcAppearanceId {} ('{}') has no usable models",
				label, npcId, composition.getName());
			return null;
		}

		short[] find = composition.getColorToReplace();
		short[] replace = composition.getColorToReplaceWith();
		int pairs = Math.min(find == null ? 0 : find.length, replace == null ? 0 : replace.length);

		short[] keptFind = new short[pairs];
		short[] keptReplace = new short[pairs];
		for (int i = 0; i < pairs; i++)
		{
			keptFind[i] = find[i];
			keptReplace[i] = replace[i];
		}

		return new NpcAppearance(npcId, composition.getName(), models, keptFind, keptReplace);
	}

	/**
	 * Drops a non-positive model id, exactly as {@code EntityDefinition} does for an
	 * authored {@code modelIds} array — and for the same reason: the client would be
	 * asked about it and would answer null, which the caller would read as a cold
	 * cache and retry three times for nothing.
	 *
	 * <p>A composition with <i>some</i> usable models still resolves. That is not a
	 * partial build: what "partial" means in this plugin is a model part that failed
	 * to <i>load</i> ({@link LivelyEntity#loadParts()} refuses those wholesale), and
	 * a {@code -1} in a composition's model array is the client's own "this slot is
	 * empty" rather than a missing part.
	 */
	private static int[] usableModelIds(@Nullable int[] models, String label, int npcId)
	{
		if (models == null || models.length == 0)
		{
			return new int[0];
		}

		int[] kept = new int[models.length];
		int n = 0;
		for (int id : models)
		{
			if (id <= 0)
			{
				log.debug("{}: npcAppearanceId {} lists an empty model slot ({}), skipping it",
					label, npcId, id);
				continue;
			}
			kept[n++] = id;
		}

		if (n == models.length)
		{
			return models.clone();
		}

		int[] trimmed = new int[n];
		System.arraycopy(kept, 0, trimmed, 0, n);
		return trimmed;
	}

	int getNpcId()
	{
		return npcId;
	}

	/** @return the NPC's own name, for a log line. May be {@code null}. */
	@Nullable
	String getNpcName()
	{
		return npcName;
	}

	/**
	 * @return the model parts to build, never empty. The array itself, not a copy —
	 * the same call {@code EntityDefinition.getModelIds()} already makes, and its
	 * only reader iterates it.
	 */
	int[] getModelIds()
	{
		return modelIds;
	}

	/** @return the NPC's {@code getColorToReplace()}, truncated to matched pairs. */
	short[] getRecolorFind()
	{
		return recolorFind;
	}

	/** @return the NPC's {@code getColorToReplaceWith()}, truncated to matched pairs. */
	short[] getRecolorReplace()
	{
		return recolorReplace;
	}

	@Override
	public String toString()
	{
		return "NpcAppearance{" + npcId + " '" + npcName + "', "
			+ modelIds.length + " model(s), " + recolorFind.length + " recolour pair(s)}";
	}
}

package com.matthewmariner.livelycities;

import net.runelite.client.ui.overlay.Overlay;

/**
 * Where an overlay is registered and unregistered.
 *
 * <p><b>Why an interface and not {@code OverlayManager} itself.</b> The same
 * reason as {@link ConfigWriter}: its only constructor is <i>private</i> —
 * verified with {@code javap -p} against the 1.12.36 client jar, where it takes
 * seven collaborators — so it can be neither constructed nor subclassed, and
 * there is no mocking framework on this classpath.
 *
 * <p>That is not a theoretical problem here. "An overlay left in the manager keeps
 * drawing after shutdown" is the same class of leak as "a {@code RuneLiteObject}
 * left active renders forever", which this plugin already guards with a
 * mutation-verified test, and this repo has already been caught once shipping a
 * plugin class nothing had ever constructed. Two methods behind an interface is
 * what makes {@code startUp} adding and {@code shutDown} removing an assertion
 * instead of a reading of the source.
 */
interface OverlayRegistry
{
	void add(Overlay overlay);

	void remove(Overlay overlay);
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.UUID;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

/**
 * Everything {@link LivelyCitiesPanel} draws, worked out where the client can be read
 * and handed over finished.
 *
 * <p><b>Why the answer is pushed rather than pulled.</b> Swing's event dispatch thread
 * is not the client thread, and the two numbers this panel exists to show —
 * how many figures are on screen, and which of them belong to which city — come from
 * asking the client whether each {@code RuneLiteObject} is registered. That is a client
 * read, and a client read off the client thread throws {@code IllegalStateException} in
 * a shipped client. So the panel gets a value object and does layout, and the deciding
 * happens in {@link #of}, which is static, client-free and under test.
 *
 * <p><b>Immutable, and every list already sorted.</b> A model is composed once a game
 * tick while the panel is open; if the row order came out of a {@code HashSet} the
 * panel would reshuffle under the cursor every 600ms and be unusable for the one thing
 * it is for, which is clicking a specific row. {@link #getOverrides()} is therefore
 * ordered by city, then name, then uuid — three keys, the last of which is unique, so
 * the order is total and cannot depend on iteration order.
 *
 * <p><b>What it deliberately does not hold.</b> No {@link LivelyEntity}, no
 * {@link EntityDefinition}, no live view of anything. A wrapper reaching Swing would
 * be a lit model kept alive by a panel — the same class of leak the teardown contract
 * spends its time on, arriving through the one door that is not on the client thread.
 * Rows carry a uuid, which is what {@link CitizenOverrides} keys on anyway.
 */
final class PanelModel
{
	/**
	 * What the panel shows before the first game tick.
	 *
	 * <p>Not "no cities": the nine cards are a fact about the plugin rather than about
	 * the session, and a panel that emptied itself at the login screen would look
	 * broken at the exact moment somebody opens it to find out what the plugin does.
	 * The live numbers are the part that goes to zero.
	 *
	 * <p><b>The overrides are not, which is why they are passed in rather than emptied
	 * here.</b> Hiding and muting live in the profile, so the list of them is exactly as
	 * true at the login screen as it is in Varrock square. Emptied, the section would
	 * read "Hidden and muted (0)" over "Nobody is hidden or muted." for somebody who has
	 * hidden twelve citizens — a worse answer than the blank this method exists to
	 * replace, because it is a confident one. Same reason
	 * {@link LivelyCitiesPlugin#onGameStateChanged} composes an ordinary model on the way
	 * out of a world instead of calling this: leaving a world does not un-hide anybody.
	 *
	 * @param hidden {@link CitizenOverrides#hiddenUuids()}, as for {@link #of}
	 * @param muted  {@link CitizenOverrides#mutedUuids()}, as for {@link #of}
	 */
	static PanelModel loggedOut(
		LivelyCitiesConfig config, Set<UUID> hidden, Set<UUID> muted, CitizenDirectory directory)
	{
		return of(null, SceneCensus.EMPTY, config, hidden, muted, directory);
	}

	private final boolean inWorld;
	private final int regionId;

	@Nullable
	private final City here;

	private final SceneCensus census;
	private final CrowdDensity density;
	private final List<CityRow> cities;
	private final List<OverrideRow> overrides;

	private PanelModel(
		boolean inWorld,
		int regionId,
		@Nullable City here,
		SceneCensus census,
		CrowdDensity density,
		List<CityRow> cities,
		List<OverrideRow> overrides)
	{
		this.inWorld = inWorld;
		this.regionId = regionId;
		this.here = here;
		this.census = census;
		this.density = density;
		this.cities = Collections.unmodifiableList(cities);
		this.overrides = Collections.unmodifiableList(overrides);
	}

	/**
	 * Composes one reading.
	 *
	 * @param playerLocation where the player is standing, or {@code null} when there is
	 *                       no world — which is a state the panel has to be able to
	 *                       draw, because a plugin panel can be opened at the login
	 *                       screen
	 * @param census         {@link EntityScene#census()}, already taken
	 * @param config         the dials, read once here rather than once per row
	 * @param hidden         {@link CitizenOverrides#hiddenUuids()}
	 * @param muted          {@link CitizenOverrides#mutedUuids()}
	 * @param directory      what puts a name to a uuid — see {@link CitizenDirectory}
	 */
	static PanelModel of(
		@Nullable WorldPoint playerLocation,
		SceneCensus census,
		LivelyCitiesConfig config,
		Set<UUID> hidden,
		Set<UUID> muted,
		CitizenDirectory directory)
	{
		final int regionId = playerLocation == null
			? 0
			: RenderPolicy.regionIdOf(playerLocation.getX(), playerLocation.getY());
		final City here = playerLocation == null ? null : City.of(regionId);

		// A profile carrying a value this build does not know about deserialises to
		// null rather than throwing — the same case EntityScene.runVisibilityPass
		// handles, and the same answer, because a panel that showed no density selected
		// would be a panel with no way to select one.
		CrowdDensity density = config.crowdDensity();
		if (density == null)
		{
			density = CrowdDensity.FULL;
		}

		List<CityRow> cities = new ArrayList<>(City.values().length);
		for (City city : City.values())
		{
			cities.add(new CityRow(
				city,
				// The city's own getter, not City.isEnabled(regionId, config). The two
				// agree for a region the city claims, but isEnabled fails open for a
				// region no city claims — a deliberate grace period for a region file
				// that lands before its checkbox — and a card asking about its own
				// checkbox has no such question to ask. enabledIn is the checkbox.
				city.enabledIn(config),
				directory.citizenCount(city),
				census.activeIn(city),
				city == here));
		}

		return new PanelModel(playerLocation != null, regionId, here, census, density,
			cities, overrideRows(hidden, muted, directory));
	}

	/**
	 * One row per citizen the user has overridden, whether they hid it, muted it or
	 * both.
	 *
	 * <p><b>One row and not two lists</b>, because the two overrides are decisions
	 * about the same person and a citizen who is both hidden and muted would otherwise
	 * appear twice with no indication that the two rows are one figure. The row carries
	 * both flags and the panel offers whichever restores apply.
	 *
	 * <p>The union is walked through a {@link TreeSet} keyed on the uuid string so this
	 * method's own iteration order cannot depend on the two incoming sets' — they are
	 * {@code LinkedHashSet}s in insertion order today, which is an order the user's
	 * click history decides. The final sort is what the panel sees; this one only makes
	 * the intermediate deterministic so a failing test says the same thing twice.
	 */
	private static List<OverrideRow> overrideRows(
		Set<UUID> hidden, Set<UUID> muted, CitizenDirectory directory)
	{
		Set<UUID> all = new TreeSet<>(Comparator.comparing(UUID::toString));
		all.addAll(hidden);
		all.addAll(muted);

		List<OverrideRow> rows = new ArrayList<>(all.size());
		for (UUID uuid : all)
		{
			CitizenDirectory.Entry entry = directory.find(uuid);
			rows.add(new OverrideRow(
				uuid,
				entry == null ? null : entry.getName(),
				entry == null ? null : entry.getCity(),
				hidden.contains(uuid),
				muted.contains(uuid)));
		}

		// City, then name, then uuid. The last key is unique, so the order is total:
		// two citizens sharing a name in the same city — the dataset has several — still
		// come out in the same order on every tick, and a row cannot move under the
		// cursor between the reading and the click.
		rows.sort(Comparator
			.comparing((OverrideRow row) -> row.getCity() == null ? "￿" : row.getCity().getLabel())
			.thenComparing(OverrideRow::getDisplayName)
			.thenComparing(row -> row.getUuid().toString()));
		return rows;
	}

	/** @return whether there is a player in a world to describe at all */
	boolean isInWorld()
	{
		return inWorld;
	}

	/** @return the region the player is standing in, or {@code 0} when out of world */
	int getRegionId()
	{
		return regionId;
	}

	/**
	 * @return the city the player is standing in, or {@code null} — which is the
	 * ordinary case, because the dataset covers 27 of the game's regions and the player
	 * is usually in one of the others
	 */
	@Nullable
	City getHere()
	{
		return here;
	}

	SceneCensus getCensus()
	{
		return census;
	}

	CrowdDensity getDensity()
	{
		return density;
	}

	/** @return one row per city, in {@link City} declaration order, never empty */
	List<CityRow> getCities()
	{
		return cities;
	}

	/** @return one row per overridden citizen, sorted; empty for a fresh profile */
	List<OverrideRow> getOverrides()
	{
		return overrides;
	}

	/** One city card: its checkbox, what the dataset holds, and what is on screen. */
	static final class CityRow
	{
		private final City city;
		private final boolean enabled;
		private final int citizens;
		private final int active;
		private final boolean here;

		CityRow(City city, boolean enabled, int citizens, int active, boolean here)
		{
			this.city = city;
			this.enabled = enabled;
			this.citizens = citizens;
			this.active = active;
			this.here = here;
		}

		City getCity()
		{
			return city;
		}

		boolean isEnabled()
		{
			return enabled;
		}

		/** @return how many citizens the dataset places here, whatever is on screen */
		int getCitizens()
		{
			return citizens;
		}

		/**
		 * @return how many of this city's figures the client currently has registered.
		 * Zero everywhere but the place the player is standing in, and often lower than
		 * {@link #getCitizens()} even there — the render distance, the density dial and
		 * the object cap all cut it down, which is exactly what a player looking at
		 * "24 citizens · 11 here" is entitled to see.
		 */
		int getActive()
		{
			return active;
		}

		/** @return whether the player is standing in this city right now */
		boolean isHere()
		{
			return here;
		}
	}

	/**
	 * One citizen the user hid, muted, or both.
	 *
	 * <p>{@code name} and {@code city} are nullable together: a uuid the directory
	 * cannot place is one from a place the dataset no longer covers — fifteen were
	 * dropped on 2026-08-24 — and the row says so rather than inventing somebody.
	 */
	static final class OverrideRow
	{
		private final UUID uuid;

		@Nullable
		private final String name;

		@Nullable
		private final City city;

		private final boolean hidden;
		private final boolean muted;

		OverrideRow(UUID uuid, @Nullable String name, @Nullable City city, boolean hidden, boolean muted)
		{
			this.uuid = uuid;
			this.name = name;
			this.city = city;
			this.hidden = hidden;
			this.muted = muted;
		}

		UUID getUuid()
		{
			return uuid;
		}

		/** @return the citizen's name, or {@code null} if the directory could not place it */
		@Nullable
		String getName()
		{
			return name;
		}

		/**
		 * @return what to put on the row: the name when there is one, and otherwise the
		 * uuid's first block. Never null, so the panel has nothing to branch on and a
		 * sort key that always exists.
		 */
		String getDisplayName()
		{
			if (name != null)
			{
				return name;
			}

			String text = uuid.toString();
			return "Citizen " + text.substring(0, text.indexOf('-'));
		}

		@Nullable
		City getCity()
		{
			return city;
		}

		boolean isHidden()
		{
			return hidden;
		}

		boolean isMuted()
		{
			return muted;
		}
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.matthewmariner.livelycities.data.EntityRecord;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Reads {@code RegionData/<regionId>.json} off the classpath and turns it into
 * validated {@link EntityDefinition}s.
 *
 * <p>Parsing is per-record on purpose. Binding the whole roster to a DTO array
 * in one call means a single bad element aborts the file, which is how the
 * predecessor managed to lose entire cities; here each roster entry gets its own
 * try/catch, so a malformed record costs exactly that record.
 *
 * <p>The {@code Gson} comes in through Guice — RuneLite provides a configured
 * one, and {@code new Gson()} is on the Plugin Hub's disallowed-API list.
 */
@Slf4j
@Singleton
public class RegionDataLoader
{
	/**
	 * The schema version every shipped file carries. A mismatch is reported and
	 * then ignored: the point is to notice a format change, not to blank a city
	 * because a number moved.
	 */
	static final float EXPECTED_VERSION = 0.8f;

	static final String DEFAULT_RESOURCE_PREFIX = "RegionData/";

	private final Gson gson;
	private final String resourcePrefix;

	@Inject
	RegionDataLoader(Gson gson)
	{
		this(gson, DEFAULT_RESOURCE_PREFIX);
	}

	RegionDataLoader(Gson gson, String resourcePrefix)
	{
		this.gson = gson;
		this.resourcePrefix = resourcePrefix;
	}

	/**
	 * @param regionId the region id, which is also the file name
	 * @return the parsed region, or {@code null} when there is no file for this
	 * region or the file is not parseable JSON at all. Never throws.
	 */
	@Nullable
	public RegionDefinition loadRegion(int regionId)
	{
		String resource = resourcePrefix + regionId + ".json";
		InputStream in = RegionDataLoader.class.getClassLoader().getResourceAsStream(resource);
		if (in == null)
		{
			// Most regions simply have no citizens. Not an error.
			log.trace("no region data for {}", regionId);
			return null;
		}

		try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			return parse(reader, regionId);
		}
		catch (IOException e)
		{
			log.warn("region {}: could not read {}", regionId, resource, e);
			return null;
		}
	}

	/**
	 * Parses region JSON from an already-open reader. Split out from
	 * {@link #loadRegion(int)} and left package-visible so the parser can be
	 * driven from a string rather than the classpath.
	 *
	 * @return the parsed region, or {@code null} if the document is not a JSON
	 * object.
	 */
	@Nullable
	RegionDefinition parse(Reader reader, int regionId)
	{
		JsonObject root;
		try
		{
			JsonElement parsed = gson.fromJson(reader, JsonElement.class);
			if (parsed == null || !parsed.isJsonObject())
			{
				log.warn("region {}: data is not a JSON object, skipped", regionId);
				return null;
			}
			root = parsed.getAsJsonObject();
		}
		catch (JsonParseException e)
		{
			log.warn("region {}: malformed JSON, skipped ({})", regionId, e.getMessage());
			return null;
		}

		float version = readVersion(root, regionId);
		checkDeclaredRegionId(root, regionId);

		List<EntityDefinition> entities = new ArrayList<>();
		Set<UUID> seen = new HashSet<>();
		int skipped = 0;

		skipped += readRoster(root, "citizenRoster", regionId, entities, seen);
		skipped += readRoster(root, "sceneryRoster", regionId, entities, seen);

		RegionDefinition region = new RegionDefinition(regionId, version, entities, skipped);
		if (skipped > 0)
		{
			log.warn("region {}: {} record(s) skipped, {} loaded", regionId, skipped, entities.size());
		}

		return region;
	}

	private float readVersion(JsonObject root, int regionId)
	{
		JsonElement el = root.get("version");
		if (el == null || !el.isJsonPrimitive())
		{
			log.warn("region {}: no version field, assuming {}", regionId, EXPECTED_VERSION);
			return EXPECTED_VERSION;
		}

		float version;
		try
		{
			version = el.getAsFloat();
		}
		catch (NumberFormatException | UnsupportedOperationException e)
		{
			log.warn("region {}: version '{}' is not a number, loading anyway", regionId, el);
			return 0f;
		}

		if (version != EXPECTED_VERSION)
		{
			// Deliberately not a bail-out. See the class javadoc.
			log.warn("region {}: schema version {} differs from the expected {} — loading anyway",
				regionId, version, EXPECTED_VERSION);
		}

		return version;
	}

	private void checkDeclaredRegionId(JsonObject root, int regionId)
	{
		JsonElement el = root.get("regionId");
		if (el == null || !el.isJsonPrimitive())
		{
			return;
		}

		try
		{
			int declared = el.getAsInt();
			if (declared != regionId)
			{
				log.warn("region {}: file declares regionId {} — the file name wins", regionId, declared);
			}
		}
		catch (NumberFormatException | UnsupportedOperationException e)
		{
			log.warn("region {}: regionId field '{}' is not a number", regionId, el);
		}
	}

	/**
	 * @return the number of records skipped in this roster
	 */
	private int readRoster(
		JsonObject root,
		String key,
		int regionId,
		List<EntityDefinition> out,
		Set<UUID> seen)
	{
		JsonElement el = root.get(key);
		if (el == null || el.isJsonNull())
		{
			return 0;
		}

		if (!el.isJsonArray())
		{
			log.warn("region {}: {} is not an array, ignored", regionId, key);
			return 0;
		}

		JsonArray array = el.getAsJsonArray();
		int skipped = 0;

		for (JsonElement element : array)
		{
			EntityRecord record;
			try
			{
				record = gson.fromJson(element, EntityRecord.class);
			}
			catch (JsonParseException e)
			{
				log.warn("region {}: unparseable {} entry skipped ({})", regionId, key, e.getMessage());
				skipped++;
				continue;
			}

			EntityDefinition definition = EntityDefinition.fromRecord(record, regionId);
			if (definition == null)
			{
				skipped++;
				continue;
			}

			if (!seen.add(definition.getUuid()))
			{
				log.warn("region {}: duplicate uuid {} on {} — keeping both",
					regionId, definition.getUuid(), definition.label());
			}

			out.add(definition);
		}

		return skipped;
	}
}

package com.matthewmariner.livelycities;

import java.util.Collections;
import java.util.List;

/**
 * One parsed {@code RegionData/<regionId>.json}: what loaded, and what did not.
 *
 * <p>{@link #getSkippedRecords()} exists so the "fail soft" promise is
 * observable rather than a claim — the log line at load time reports it, and the
 * unit tests assert on it.
 */
public final class RegionDefinition
{
	private final int regionId;
	private final float version;
	private final List<EntityDefinition> entities;
	private final int skippedRecords;

	RegionDefinition(int regionId, float version, List<EntityDefinition> entities, int skippedRecords)
	{
		this.regionId = regionId;
		this.version = version;
		this.entities = Collections.unmodifiableList(entities);
		this.skippedRecords = skippedRecords;
	}

	public int getRegionId()
	{
		return regionId;
	}

	public float getVersion()
	{
		return version;
	}

	public List<EntityDefinition> getEntities()
	{
		return entities;
	}

	public int getSkippedRecords()
	{
		return skippedRecords;
	}

	public int getEntityCount()
	{
		return entities.size();
	}

	public int getCitizenCount()
	{
		int n = 0;
		for (EntityDefinition e : entities)
		{
			if (e.getType().isCitizen())
			{
				n++;
			}
		}
		return n;
	}

	public int getSceneryCount()
	{
		return entities.size() - getCitizenCount();
	}

	@Override
	public String toString()
	{
		return "RegionDefinition{" + regionId
			+ ", v" + version
			+ ", " + getCitizenCount() + " citizens"
			+ ", " + getSceneryCount() + " scenery"
			+ ", " + skippedRecords + " skipped}";
	}
}

package com.matthewmariner.livelycities;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;

/**
 * One reading of what the scene is actually doing, taken on the client thread and
 * safe to look at from anywhere afterwards.
 *
 * <p><b>Why a snapshot and not five getters.</b> {@link EntityScene} already answers
 * every one of these questions individually, and the side panel wants all of them at
 * once, once a game tick. Asking five times means five walks of the wrapper cache and
 * five rounds of {@code RuneLiteObject.isActive()} calls into the client — for one
 * screenful of numbers that have to agree with each other. Worse, they would be five
 * readings taken at five moments: a panel that said "34 active" beside a per-city
 * breakdown adding to 33 is a panel nobody trusts again.
 *
 * <p><b>Why it is immutable and client-free.</b> It crosses a thread boundary. The
 * numbers are read where the client can be read and drawn on Swing's event dispatch
 * thread, so anything the panel could still dereference has to be a value rather than
 * a live view — the opposite decision from {@link EntityScene#inScopeEntities()},
 * which is deliberately a live view because its readers are already on the client
 * thread and need to see the set as it is <i>now</i>.
 *
 * <p>{@link #getActiveByCity()} holds only cities with at least one active figure, so
 * a reader has to treat a missing key as zero — see {@link #activeIn(City)}, which is
 * the accessor to use.
 */
final class SceneCensus
{
	/** What a caller with no scene at all should show: zeroes, not nulls. */
	static final SceneCensus EMPTY = new SceneCensus(0, 0, 0, 0, new EnumMap<>(City.class));

	private final int active;
	private final int inScope;
	private final int walking;
	private final int talking;
	private final Map<City, Integer> activeByCity;

	SceneCensus(int active, int inScope, int walking, int talking, EnumMap<City, Integer> activeByCity)
	{
		this.active = active;
		this.inScope = inScope;
		this.walking = walking;
		this.talking = talking;
		this.activeByCity = Collections.unmodifiableMap(activeByCity);
	}

	/**
	 * @return how many objects the client currently has registered for this plugin —
	 * the figure a player can count on screen, near enough
	 */
	int getActive()
	{
		return active;
	}

	/** @return how many definitions sit in a region the loaded scene covers */
	int getInScope()
	{
		return inScope;
	}

	/** @return how many active citizens the per-frame pass is interpolating */
	int getWalking()
	{
		return walking;
	}

	/** @return how many citizens have a remark on screen right now */
	int getTalking()
	{
		return talking;
	}

	/**
	 * @return the per-city breakdown, unmodifiable, holding only the cities with at
	 * least one active figure
	 */
	Map<City, Integer> getActiveByCity()
	{
		return activeByCity;
	}

	/** @return how many of {@link #getActive()} belong to one city, zero if none do */
	int activeIn(City city)
	{
		Integer n = activeByCity.get(city);
		return n == null ? 0 : n;
	}

	@Override
	public String toString()
	{
		return "SceneCensus{" + active + " active, " + inScope + " in scope, "
			+ walking + " walking, " + talking + " talking, " + activeByCity + '}';
	}
}

package com.matthewmariner.livelycities;

import javax.annotation.Nullable;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * "Could an ordinary person be standing on this tile?", answered from the
 * client's own collision map.
 *
 * <p>This exists for {@link CitizenEcho}. An authored citizen's tile was placed
 * by a human who could see the ground; a procedurally-derived one's was placed by
 * arithmetic, and arithmetic cannot see that the tile two east is the inside of a
 * bank counter. So every echo tile is checked here before it is allowed to spawn,
 * and an echo that fails is <b>skipped, never nudged</b> — a citizen standing in
 * the River Lum is worse than no citizen, and a "find somewhere nearby that works"
 * fallback is how a deterministic placement stops being deterministic.
 *
 * <p><b>The accessor, read out of the 1.12.36 jars rather than guessed.</b>
 * {@code javap net.runelite.api.WorldView} declares
 * {@code public abstract net.runelite.api.CollisionData[] getCollisionMaps();}
 * and {@code javap net.runelite.api.CollisionData} declares exactly one method,
 * {@code public abstract int[][] getFlags();}. In the injected client
 * ({@code injected-client-1.12.36.jar}) the world view is class {@code dz} and the
 * collision map is class {@code gc}:
 * <ul>
 *   <li>{@code dz.getCollisionMaps()} returns the field {@code ab:[Lgc;}, which
 *       the constructor allocates as {@code anewarray gc} of length
 *       {@code iconst_4} — <b>one map per plane</b>, indexed by plane — and then
 *       fills all four slots in a loop <i>before it returns</i>. The array is
 *       assigned once, in that constructor, and so is every element of it. An
 *       earlier version of this javadoc said the elements "are filled in as the
 *       scene loads, so an element can be {@code null}"; two independent
 *       disassemblies, of 1.12.36 and of 1.12.38, say the opposite. See
 *       <b>What the null checks are for</b> below.</li>
 *   <li>{@code gc.getFlags()} returns the field {@code bb:[[I}, allocated in
 *       {@code gc.<init>(int,int,boolean)} as
 *       {@code multianewarray "[[I"} over the two size fields — first dimension
 *       from the constructor's first {@code int}, second from its second. The
 *       world view passes {@code getSizeX()} and {@code getSizeY()} in that
 *       order (both are stored from the same two constructor arguments:
 *       {@code getSizeX()} returns field {@code as}, {@code getSizeY()} returns
 *       field {@code ax}). So it is <b>{@code getFlags()[sceneX][sceneY]}</b>.
 *       Every writer in {@code gc} agrees — e.g. {@code gc.cv(int,int)} is
 *       {@code bb[x - originX][y - originY] |= 2097152} — and so does RuneLite's
 *       own {@code DevToolsOverlay}, which indexes
 *       {@code getFlags()[tile.getSceneLocation().getX()][..getY()]}.</li>
 * </ul>
 *
 * <p><b>Why {@link WorldView#isTopLevel()} is a precondition and not a
 * formality.</b> {@code gc}'s constructor has two shapes, chosen by its
 * {@code boolean}: origin {@code (0,0)} and size {@code (sizeX, sizeY)}, or
 * origin {@code (-1,-1)} and size {@code (sizeX + 6, sizeY + 6)}. The world view
 * passes {@code (getId() != 0)} for that boolean, and
 * {@code WorldView.TOPLEVEL == 0} with {@code dz.isTopLevel()} compiled to
 * {@code getId() == 0}. So on a <i>non</i>-top-level view (a
 * {@code WorldEntity}'s) the flags array is origin-shifted by one tile and scene
 * coordinates would read the wrong tile's flags — silently, and off by one, which
 * is exactly the kind of wrong that puts a citizen half inside a wall. This plugin
 * only ever passes {@code client.getTopLevelWorldView()}, so the check costs
 * nothing; it is here so that a future caller cannot make the mistake.
 *
 * <p><b>What the flags mean.</b> {@code CollisionDataFlag} splits into three
 * kinds, and only one of them answers this question:
 * <ul>
 *   <li>{@code BLOCK_MOVEMENT_OBJECT} (256), {@code BLOCK_MOVEMENT_FLOOR_DECORATION}
 *       (262144) and {@code BLOCK_MOVEMENT_FLOOR} (2097152) say the tile itself
 *       cannot be occupied — a wall or counter fills it, a floor decoration fills
 *       it, or there is no walkable floor there at all (water, void, the inside of
 *       a building's footprint). {@code BLOCK_MOVEMENT_FULL} is exactly those
 *       three OR'd together: {@code 2359552 == 256 | 262144 | 2097152}, which
 *       {@code StandableGroundTest} pins.</li>
 *   <li>The eight directional bits ({@code BLOCK_MOVEMENT_NORTH} and friends) say
 *       a <i>step across one edge</i> of the tile is blocked. A tile with a wall
 *       along its north side is still a tile a person stands on — most of the
 *       pavement in Varrock carries one of these — so they are deliberately
 *       <b>not</b> consulted.</li>
 *   <li>The line-of-sight bits are about projectiles and sight, not standing, and
 *       are not consulted either.</li>
 * </ul>
 *
 * <p><b>What the null checks are for.</b> Not for a client state anybody has
 * observed. On the injected client {@code getCollisionMaps()} never returns
 * {@code null} and no element of what it returns is ever {@code null}, because both
 * the array and its four entries are assigned in the world view's own constructor
 * before it returns. The checks guard the {@link WorldView} <i>interface</i>, which
 * promises none of that: this plugin does not construct the implementation and does
 * not get to make claims about one it was handed. A branch that costs a comparison
 * and turns an unowned {@code NullPointerException} into {@link Verdict#UNKNOWN} is
 * worth keeping even against a client that cannot take it — this method runs from a
 * per-game-tick visibility pass, where a throw abandons every entity after the
 * offending one, including the ones that were about to be deactivated. What is not
 * worth keeping is the claim that it happens, which is what this paragraph replaced.
 *
 * <p><b>{@link Verdict#UNKNOWN} is not "probably fine".</b> Every way of failing
 * to get an answer — no maps at all, no map for that plane, the tile outside the
 * loaded scene, a view whose flags array is origin-shifted — comes back as
 * {@code UNKNOWN}, and the caller decides. {@link CitizenEcho} treats
 * {@code UNKNOWN} as "only if a human already vouched for this ground", i.e. only
 * inside an authored wander box. Nothing here ever guesses.
 *
 * <p><b>Client-thread only</b>, like everything that reads live scene state.
 * Nothing here allocates.
 */
final class StandableGround
{
	/**
	 * The mask that decides it: {@code CollisionDataFlag.BLOCK_MOVEMENT_FULL}.
	 *
	 * <p>Named through the API constant rather than written as {@code 0x240100} so
	 * a client-side change to the aggregate travels here, and so the one number
	 * this class turns on is traceable to its declaration.
	 */
	static final int BLOCKS_STANDING = CollisionDataFlag.BLOCK_MOVEMENT_FULL;

	enum Verdict
	{
		/** The collision map says an ordinary person could be standing here. */
		STANDABLE,

		/** The collision map says the tile is filled, decorated, or floorless. */
		BLOCKED,

		/** No answer available — see the class javadoc. Never treated as a yes. */
		UNKNOWN
	}

	private StandableGround()
	{
	}

	/**
	 * @param worldView the view whose scene the tile is being judged in — must be
	 *                  the top-level view, or the answer is {@link Verdict#UNKNOWN}
	 * @param tile      the world tile, whose {@code plane} selects the collision map
	 * @return whether an ordinary person could stand there. Never throws, never
	 * allocates.
	 */
	static Verdict verdict(@Nullable WorldView worldView, @Nullable WorldPoint tile)
	{
		if (worldView == null || tile == null)
		{
			return Verdict.UNKNOWN;
		}

		if (!worldView.isTopLevel())
		{
			// Origin-shifted flags array — see the class javadoc. Reading it with
			// scene coordinates would answer about the tile one to the south-west.
			return Verdict.UNKNOWN;
		}

		CollisionData[] maps = worldView.getCollisionMaps();
		if (maps == null)
		{
			return Verdict.UNKNOWN;
		}

		int plane = tile.getPlane();
		if (plane < 0 || plane >= maps.length)
		{
			return Verdict.UNKNOWN;
		}

		CollisionData map = maps[plane];
		if (map == null)
		{
			// Not a state the injected client produces: the world view's constructor
			// allocates the four-slot array and fills every slot before it returns.
			// This guards the WorldView interface, which promises nothing of the sort
			// — see "What the null checks are for" in the class javadoc.
			return Verdict.UNKNOWN;
		}

		int[][] flags = map.getFlags();
		if (flags == null)
		{
			return Verdict.UNKNOWN;
		}

		// The same subtraction LocalPoint.fromWorld does, without the <<7 / >>7
		// round trip and without LocalPoint's plane coupling: fromWorld returns
		// null whenever the view's current plane differs from the point's, which
		// is a question about what the player is looking at rather than about what
		// the ground is like.
		int sceneX = tile.getX() - worldView.getBaseX();
		int sceneY = tile.getY() - worldView.getBaseY();

		if (sceneX < 0 || sceneX >= flags.length)
		{
			return Verdict.UNKNOWN;
		}

		int[] column = flags[sceneX];
		if (column == null || sceneY < 0 || sceneY >= column.length)
		{
			return Verdict.UNKNOWN;
		}

		return (column[sceneY] & BLOCKS_STANDING) == 0 ? Verdict.STANDABLE : Verdict.BLOCKED;
	}
}

package com.matthewmariner.livelycities;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.UUID;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * A set of entity uuids kept in one hidden config string.
 *
 * <p><b>Why a string and not a list of checkboxes.</b> RuneLite config items are
 * {@code @ConfigItem} annotations on interface methods — static declarations,
 * fixed at compile time. There is no dynamic checkbox list, and there could not
 * be one keyed on 269 uuids that ship in a data file. The established shape is
 * therefore a {@code hidden = true} string item plus a RUNELITE menu entry that
 * appends to it, and a visible "clear the list" item for the way back. This
 * class is that string, parsed.
 *
 * <p><b>The parse is cached on the raw string, and that is load-bearing rather
 * than an optimisation.</b> {@link EntityScene#updateVisibility} consults this
 * for every definition in scope on every game tick — 76 of them in Varrock — and
 * a config read is a proxy call into {@code ConfigManager}. Reading the raw value
 * once per pass and re-parsing only when the bytes actually changed is what keeps
 * "is this one hidden?" a hash lookup. The same reasoning as the
 * "read the dials once per pass, not once per entity" comment in that method.
 *
 * <p><b>Fail-soft, like everything else that reads authored or persisted
 * data.</b> A profile can be hand-edited, synced from another install, or written
 * by a future version of this plugin. Junk between the commas is dropped with one
 * log line per distinct string rather than throwing: the alternative is that one
 * bad character makes every hide the user ever set disappear, or worse, makes the
 * visibility pass throw once per tick.
 *
 * <p><b>Nothing here touches the client</b>, so it needs no client thread. The
 * write does reach {@code ConfigManager} through {@link ConfigWriter}, which is
 * thread-safe in the client and is called from the menu-click handler, i.e. from
 * the client thread anyway.
 */
@Slf4j
final class UuidSetting
{
	/** The separator in the stored string. Never appears in a UUID's toString. */
	private static final char SEPARATOR = ',';

	private final String key;
	private final Supplier<String> reader;
	private final ConfigWriter writer;

	/**
	 * The raw string {@link #cache} was built from, so a re-parse happens exactly
	 * when the value changed. {@code null} is a legitimate raw value (no setting
	 * at all), so "not parsed yet" is tracked separately rather than by
	 * {@code parsedFrom == null}.
	 */
	@Nullable
	private String parsedFrom;

	private boolean parsed;

	private Set<UUID> cache = Collections.emptySet();

	/**
	 * @param key    the {@code keyName} of the hidden {@code @ConfigItem} holding
	 *               this set
	 * @param reader the config getter for that item — a method reference, so the
	 *               interface stays the single declaration of the key's default
	 * @param writer how to persist a change
	 */
	UuidSetting(String key, Supplier<String> reader, ConfigWriter writer)
	{
		this.key = key;
		this.reader = reader;
		this.writer = writer;
	}

	/**
	 * @return the current set, unmodifiable. Cheap to call repeatedly: it re-reads
	 * the config value (one proxy call) and only re-parses when that value has
	 * changed. Callers that ask per entity should still hoist it out of the loop —
	 * see the class javadoc.
	 */
	Set<UUID> current()
	{
		String raw = reader.get();
		if (parsed && equalRaw(raw, parsedFrom))
		{
			return cache;
		}

		cache = parse(raw);
		parsedFrom = raw;
		parsed = true;
		return cache;
	}

	boolean contains(UUID uuid)
	{
		return current().contains(uuid);
	}

	/**
	 * Adds a uuid and persists the whole set.
	 *
	 * @return true if it was not already there — i.e. if anything was written. A
	 * write that would produce the same string is skipped: {@code ConfigManager}
	 * posts a {@code ConfigChanged} per {@code setConfiguration} call, and this
	 * plugin answers that by re-running the visibility pass, so a no-op write is a
	 * no-op pass for every entity in scope.
	 */
	boolean add(UUID uuid)
	{
		Set<UUID> existing = current();
		if (existing.contains(uuid))
		{
			return false;
		}

		Set<UUID> next = new LinkedHashSet<>(existing);
		next.add(uuid);
		store(next);
		return true;
	}

	/**
	 * Takes one uuid back out and persists the rest.
	 *
	 * <p>The single-citizen counterpart to {@link #clear()}, and the reason it exists
	 * is that {@code clear()} was the <i>only</i> way back. A user hides or mutes one
	 * citizen from its right-click menu, one at a time, and the only undo the plugin
	 * shipped was a checkbox that undid all of them at once — so restoring the one you
	 * changed your mind about meant losing every other decision you had made. See
	 * {@link LivelyCitiesPanel}, which is the surface that can offer a row per citizen.
	 *
	 * <p>Same skipped-write rule as {@link #add}, for the same reason and in the other
	 * direction: removing a uuid that is not in the set would write a string identical
	 * to the one already stored, and {@code ConfigManager} posts a
	 * {@code ConfigChanged} per write which this plugin answers with a full visibility
	 * pass over every entity in scope.
	 *
	 * @return true if it was there — i.e. if anything was written
	 */
	boolean remove(UUID uuid)
	{
		Set<UUID> existing = current();
		if (!existing.contains(uuid))
		{
			return false;
		}

		Set<UUID> next = new LinkedHashSet<>(existing);
		next.remove(uuid);
		store(next);
		return true;
	}

	/**
	 * Empties the set.
	 *
	 * @return true if there was anything to empty
	 */
	boolean clear()
	{
		if (current().isEmpty())
		{
			return false;
		}

		store(Collections.emptySet());
		return true;
	}

	int size()
	{
		return current().size();
	}

	String getKey()
	{
		return key;
	}

	/**
	 * Writes the set out and primes the cache with it.
	 *
	 * <p>Priming matters: the write is followed — synchronously, on this thread —
	 * by a {@code ConfigChanged} that makes the plugin re-run the visibility pass,
	 * and that pass has to see the new set. Waiting for the next {@link #current()}
	 * to re-read the config would also work, but only because
	 * {@code ConfigManager.setConfiguration} updates its in-memory properties
	 * before it posts; priming here means this class does not depend on that
	 * ordering.
	 */
	private void store(Set<UUID> uuids)
	{
		String serialised = serialise(uuids);
		cache = Collections.unmodifiableSet(uuids);
		parsedFrom = serialised;
		parsed = true;

		// An empty set is stored as "no setting", not as the empty string: see
		// ConfigWriter.write.
		writer.write(key, serialised.isEmpty() ? null : serialised);
	}

	private static String serialise(Set<UUID> uuids)
	{
		StringBuilder out = new StringBuilder();
		for (UUID uuid : uuids)
		{
			if (out.length() > 0)
			{
				out.append(SEPARATOR);
			}
			out.append(uuid);
		}
		return out.toString();
	}

	/**
	 * @return the uuids in {@code raw}, in the order they appear, ignoring blanks
	 * and anything that is not a uuid
	 */
	private Set<UUID> parse(@Nullable String raw)
	{
		if (raw == null || raw.trim().isEmpty())
		{
			return Collections.emptySet();
		}

		Set<UUID> out = new LinkedHashSet<>();
		int rejected = 0;
		for (String piece : raw.split(String.valueOf(SEPARATOR), -1))
		{
			String trimmed = piece.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}

			try
			{
				out.add(UUID.fromString(trimmed));
			}
			catch (IllegalArgumentException e)
			{
				rejected++;
			}
		}

		if (rejected > 0)
		{
			// One line per distinct stored value, not one per entry and not one per
			// pass: the cache means this runs again only when the string changes.
			log.warn("Lively Cities: {} entr{} in the '{}' setting {} not a uuid and {} ignored; "
					+ "{} usable uuid(s) kept",
				rejected, rejected == 1 ? "y" : "ies", key,
				rejected == 1 ? "is" : "are", rejected == 1 ? "was" : "were", out.size());
		}

		return Collections.unmodifiableSet(out);
	}

	private static boolean equalRaw(@Nullable String a, @Nullable String b)
	{
		return a == null ? b == null : a.equals(b);
	}
}

package com.matthewmariner.livelycities.data;

import java.util.List;

/**
 * Wire shape of one entry in {@code citizenRoster} or {@code sceneryRoster}.
 *
 * <p>One class covers both rosters: a scenery record is simply a citizen record
 * with the name/examine/remarks/animation fields absent, so a second DTO would
 * only duplicate the validation. Every field is nullable — validation happens
 * once, in {@code EntityDefinition.fromRecord}, so there is a single place that
 * decides what "unusable" means.
 *
 * <p>Fields for later milestones ({@code wanderBox*}, {@code moveAnimation},
 * {@code startScript}, {@code remarks}) are parsed but unused by the render
 * core, so enabling L2/L3 does not mean revisiting the schema.
 */
public class EntityRecord
{
	// Identity
	public String uuid;
	public Integer regionId;
	public String entityType;

	// Presentation (citizens only)
	public String name;
	public String examineText;
	public String[] remarks;

	// Placement
	public PointRecord worldLocation;
	public Integer baseOrientation;

	// Model
	public int[] modelIds;
	public int[] modelRecolorFind;
	public int[] modelRecolorReplace;

	/**
	 * Clone an existing NPC's appearance instead of listing raw {@code modelIds}.
	 *
	 * <p>Optional, and <b>it wins when it is present</b>: the models and the
	 * recolour arrays both come from {@code Client.getNpcDefinition(id)}, and this
	 * record's own {@code modelIds} / {@code modelRecolor*} are ignored (with a warn
	 * at validation time, because carrying both is an authoring mistake rather than
	 * a fallback — a recolour pair list authored against one model's palette means
	 * nothing against another's). See {@code NpcAppearance}.
	 *
	 * <p><b>Why it exists.</b> A raw model id is the fragility that killed the
	 * predecessor plugin: an August 2024 update renumbered player-model ids and its
	 * citizens broke visually. An NPC id is a named, generated constant in
	 * {@code net.runelite.api.gameval.NpcID}, is what a game update renumbers last,
	 * and — unlike a model id — can be looked up by anyone with the jar. The vendored
	 * entities keep their {@code modelIds} except where the authored array was itself
	 * the bug ("Rufus", GitHub issue #1, whose twelve ids contained no footwear);
	 * anything authored here should prefer this.
	 */
	public Integer npcAppearanceId;
	public float[] scale;
	public float[] translate;
	public List<MergedObjectRecord> mergedObjects;

	// Animation, by symbolic name
	public String idleAnimation;
	public String moveAnimation;

	// L3 — wandering
	public PointRecord wanderBoxBL;
	public PointRecord wanderBoxTR;

	// L3 — scripted
	public String startScript;

	/**
	 * Whether this record is a <b>cameo</b>: a named, player-shaped likeness of a
	 * real person, which the {@code cameos} config item switches on and which is
	 * <b>off by default</b>.
	 *
	 * <p>A separate field rather than "anything with an {@link #npcAppearanceId}",
	 * deliberately. The two are unrelated questions — the appearance mechanism is
	 * meant to be the preferred way to dress <i>any</i> future entity, and a market
	 * stall owner sourced from an NPC id must not silently become opt-in content —
	 * so the gate is stated rather than inferred. {@code EntityScene} refuses a
	 * cameo unless both {@code cameos} and its city's checkbox are on, and
	 * {@code CitizenEcho} refuses to derive anything from one.
	 *
	 * <p>Absent (or false) for all 305 other entities — the 145 vendored ones, the 33
	 * ordinary townsfolk authored for the five thin cities on 2026-08-29 and the 127
	 * liveried townsfolk authored on 2026-09-01.
	 */
	public Boolean cameo;

	/**
	 * Whether {@code CitizenEcho} may derive a "Passer-by" from this record.
	 * Absent (or false) means it may, which is what every record predating
	 * 2026-09-01 relies on.
	 *
	 * <p><b>Why it exists, and why it did not before.</b> {@code CitizenEcho}'s
	 * javadoc proposed exactly this field, refused it — "it should be added when
	 * there is a record that needs it, not before" — and named the condition: a
	 * record no derivable rule can refuse, whose palette an echo must not re-deal.
	 * The 127 liveried townsfolk added on 2026-09-01 are that record, 127 times.
	 *
	 * <p>An echo's whole mechanism is <i>the source's own palette, re-dealt</i> —
	 * the tunic colour is deliberately moved to where the hair colour was. That is
	 * a sound way to vary a citizen whose colours are arbitrary, and it is precisely
	 * wrong for one whose colours are not: a liveried citizen wears Varrock's gold
	 * on the torso slot and Varrock's near-black on the legs slot <i>because those
	 * are the slots that make the colours read as a city's</i>. Re-deal it and the
	 * gold lands on the boots, a donor's own colour lands on the chest, and the
	 * figure stops saying the one thing it was authored to say.
	 *
	 * <p>No rule already in {@code CitizenEcho} can see that. The body rules ask what
	 * the figure is doing, the palette rules ask whether a colour would cross the
	 * flesh boundary, and a liveried record passes both — it is a person standing
	 * still in colours that are nowhere near skin. The fact the derivation needs is
	 * about <i>authorial intent</i>, and intent is not derivable from the numbers.
	 * So it is stated.
	 *
	 * <p>Defaulting to {@code false} matters and is the shape {@link #cameo} already
	 * has: a record that says nothing keeps the behaviour it had, so this field can
	 * never silently switch off a derivation somebody was relying on.
	 */
	public Boolean noEcho;

	// Authoring metadata, not used at render time
	public Integer baseNpcId;
	public Integer removedObject;
}

package com.matthewmariner.livelycities.data;

import com.google.gson.annotations.SerializedName;

/**
 * Wire shape of an entry in {@code mergedObjects} — an extra model merged into
 * the entity's own, optionally pre-rotated in 90 degree counter-clockwise steps.
 */
public class MergedObjectRecord
{
	@SerializedName("objectID")
	public Integer objectId;

	public Integer count90CCWRotations;
}

package com.matthewmariner.livelycities.data;

/**
 * Wire shape of {@code {"x":3238,"y":3425,"plane":0}}.
 *
 * <p>Boxed on purpose: a missing field must be distinguishable from a genuine
 * zero so the loader can reject the record instead of silently placing an
 * entity at the world origin. Deliberately NOT
 * {@link net.runelite.api.coords.WorldPoint} — that class is immutable with no
 * no-arg constructor, and asking Gson to fabricate one is exactly the kind of
 * implicit behaviour that breaks quietly on a library bump.
 */
public class PointRecord
{
	public Integer x;
	public Integer y;
	public Integer plane;
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A citizen may not walk on a different skeleton from the one it stands on.
 *
 * <h2>The defect this exists for</h2>
 *
 * <p>A human playing the plugin and recording video found citizens whose
 * {@code idleAnimation} and {@code moveAnimation} had been taken from different
 * creatures: goblins that stood like goblins and walked like men, a penguin with a
 * human gait, four dwarves the same, a bee swarm on {@code HumanWalk}, a cat on
 * {@code HumanWalk} — and, in the other direction, a man at a furnace who walked
 * like a stray dog. That is ten. An offline sweep against the 1.12.36 cache found
 * three more nobody had reported: another man on {@code DogWalk} and two women on
 * {@code DrunkenDwarfWalk}.
 *
 * <p>There was a fifth dwarf, "Draug" in the Motherlode Mine, which made it fourteen
 * rather than thirteen; region 14936 left the dataset in the nine-city cut on
 * 2026-08-24, so both the citizen and its correction are gone and every count in this
 * file is one lower than it was.
 *
 * <p>Twelve of the thirteen never move — only "Bees!" in Varrock carries a wander
 * box — so in all but one case the wrong gait was latent rather than visible. That is
 * precisely why it needs a test and not just a fix: the
 * dataset's whole claim on anyone's attention is that it is trustworthy, and a
 * latent wrong is only ever one wander box away from a visible one.
 *
 * <h2>Two rules, and why the second one had to be added</h2>
 *
 * <p>The first rule here is the one the dataset can ask about itself: the two
 * animations on one record must drive the same skeleton as each other. Every one of
 * the thirteen fails that, and no correct record does — a figure with one body cannot
 * have two rigs.
 *
 * <p>It has a blind spot exactly one record wide, and it is not hypothetical.
 * {@code if (idle == null || move == null) continue;} skips every figure carrying only
 * an idle — which is all six cameos, deliberately, because they are posed statues. So
 * the guard built to catch wrong-skeleton animations was skipping precisely the figures
 * whose poses had been hand-picked, and three records were on the wrong rig behind it:
 * "Sludgellama" posed on the Braindeath Island skeleton while wearing a Rogue's body,
 * and "Child" and "Liam" playing human emotes on gnome-rigged child models.
 *
 * <p>The second rule closes it by asking the question a reviewer actually wants
 * answered — "does this animation belong to this body?" — which needs one fact per
 * appearance rather than per record. {@link ModelSkeletons} carries them: which
 * framemap each shipped model id and each {@code npcAppearanceId} was seen rigged to.
 * That is an inference off NPC compositions rather than something readable out of a
 * model file, and its limits are written down there.
 *
 * <p>The skeleton numbers on both sides come from tables transcribed from the cache
 * rather than read at test time; see {@link AnimationSkeletons} for why.
 */
public class AnimationSkeletonTest
{
	/**
	 * Citizens carrying <b>both</b> an idle and a move animation, i.e. the population
	 * this rule can say anything about.
	 *
	 * <p>Pinned, and load-bearing. The comparison below skips a record with only one
	 * animation, so a bug that made {@link EntityDefinition} drop move animations
	 * entirely would empty the sample and turn every assertion green. This is the
	 * number that stops that: 233 of the 269 shipped citizens have both.
	 *
	 * <p>It was 73 of 109 before the top-up pass on 2026-08-29 added 33 citizens to the
	 * five thin cities, and 106 of 142 before the livery pass on 2026-09-01 added 127
	 * more. Every one of those 160 carries an idle <i>and</i> a move, because each one
	 * reuses a shipped citizen's whole {@code modelIds} array and is animated on that
	 * body's own framemap — so the sample this rule can speak about grew by exactly the
	 * number of records added, twice.
	 */
	private static final int CITIZENS_WITH_BOTH_ANIMATIONS = 233;

	/**
	 * The one that would have caught all thirteen.
	 */
	@Test
	public void noCitizenWalksOnADifferentSkeletonFromTheOneItStandsOn()
	{
		List<String> violations = new ArrayList<>();
		int checked = 0;

		for (EntityDefinition citizen : shippedCitizens())
		{
			LivelyAnimation idle = citizen.getIdleAnimation();
			LivelyAnimation move = citizen.getMoveAnimation();
			if (idle == null || move == null)
			{
				continue;
			}

			checked++;

			Integer idleSkeleton = AnimationSkeletons.framemapOf(idle);
			Integer moveSkeleton = AnimationSkeletons.framemapOf(move);
			assertNotNull(idle + " has no framemap in the table", idleSkeleton);
			assertNotNull(move + " has no framemap in the table", moveSkeleton);

			if (!idleSkeleton.equals(moveSkeleton))
			{
				violations.add(citizen.label() + " in " + citizen.getRegionId() + ".json stands on "
					+ idle + " (framemap " + idleSkeleton + ") and walks on "
					+ move + " (framemap " + moveSkeleton + ")");
			}
		}

		assertEquals("citizens carrying both an idle and a move animation — if this drops, the "
				+ "sample shrank and the assertion below stopped being asked",
			CITIZENS_WITH_BOTH_ANIMATIONS, checked);

		assertTrue("citizen(s) whose two animations come from different creatures: " + violations,
			violations.isEmpty());
	}

	/**
	 * Shipped records whose appearance the cache can put a rig on, i.e. the population
	 * the rule below can say anything about.
	 *
	 * <p>Pinned for the same reason {@link #CITIZENS_WITH_BOTH_ANIMATIONS} is: the loop
	 * skips a record whose models nothing in the cache is built out of, so a bug that
	 * emptied {@link ModelSkeletons} would turn every assertion green.
	 *
	 * <p>The arithmetic: 311 shipped records, 14 of them carrying no animation at all,
	 * leaves 297 this rule could apply to. 272 of those have a body the cache can put a
	 * rig on and 25 do not — see {@link #RECORDS_WITH_NO_RIG_EVIDENCE}.
	 *
	 * <p>It read 112 of 137 before the top-up pass on 2026-08-29 and 145 of 170 before
	 * the livery pass on 2026-09-01. Every one of the 160 citizens those two passes
	 * added wears a body already in this table, so all 160 landed in the traceable
	 * bucket and the other side of the split did not move at all.
	 */
	private static final int RECORDS_WITH_A_TRACEABLE_RIG = 272;

	/**
	 * The other side of that split, pinned so it cannot quietly grow.
	 *
	 * <p>These are records whose {@code modelIds} appear in no NPC composition anywhere
	 * in the cache — braziers, market stalls, planters, a wheat field. They are object
	 * geometry, nothing rigs them, and the rule below has nothing to say about them. It
	 * is a counted, named outcome rather than a silent {@code continue}: a citizen
	 * landing in this bucket would mean somebody had authored a person out of scenery
	 * models, and that should be visible.
	 */
	private static final int RECORDS_WITH_NO_RIG_EVIDENCE = 25;

	/**
	 * An animation has to drive the skeleton the record's own body is rigged to.
	 *
	 * <p>The rule that reaches the six cameos. Each of them carries an
	 * {@code npcAppearanceId} and no move animation, so the pair rule above skips all
	 * six; this one compares the single pose against the framemap of the NPC body it is
	 * worn on, and it is the check that would have caught {@code LectorIdle} (framemap
	 * 1304) posed on a Rogue (framemap 0) on the day it was written.
	 *
	 * <p>Scenery is in scope, not just citizens. A scenery record can carry an
	 * {@code idleAnimation} and {@link LivelyEntity} installs a controller for it exactly
	 * as it does for a citizen — and one did: an "Inactive spirit pool" model, rigged to
	 * framemap 1944, playing {@code HUMAN_READY}.
	 */
	@Test
	public void noRecordPlaysAnAnimationOnASkeletonItsOwnBodyIsNotRiggedTo()
	{
		List<String> violations = new ArrayList<>();
		List<String> noEvidence = new ArrayList<>();
		int checked = 0;

		for (EntityDefinition entity : shippedEntities())
		{
			List<LivelyAnimation> animations = new ArrayList<>();
			if (entity.getIdleAnimation() != null)
			{
				animations.add(entity.getIdleAnimation());
			}
			if (entity.getMoveAnimation() != null)
			{
				animations.add(entity.getMoveAnimation());
			}

			if (animations.isEmpty())
			{
				continue;
			}

			Set<Integer> rig = ModelSkeletons.impliedRig(entity);
			if (rig.isEmpty())
			{
				noEvidence.add(entity.label() + " in " + entity.getRegionId() + ".json");
				continue;
			}

			checked++;

			for (LivelyAnimation animation : animations)
			{
				Integer framemap = AnimationSkeletons.framemapOf(animation);
				assertNotNull(animation + " has no framemap in the table", framemap);

				if (!rig.contains(framemap))
				{
					violations.add(entity.label() + " in " + entity.getRegionId() + ".json plays "
						+ animation + " (framemap " + framemap + ") on a body rigged to " + rig);
				}
			}
		}

		// The rule first, then the two guards on the sample. That order is deliberate:
		// a record joining the sample and being wrong should fail with what is wrong
		// with it, not with a count that moved.
		assertTrue("record(s) whose animation drives a skeleton their own body does not have: "
			+ violations, violations.isEmpty());

		assertEquals("records carrying an animation and a body the cache can put a rig on — "
				+ "if this drops, the sample shrank and the rule above stopped being asked",
			RECORDS_WITH_A_TRACEABLE_RIG, checked);
		assertEquals("records animated on models no NPC is built out of, so nothing can be "
				+ "inferred: " + noEvidence, RECORDS_WITH_NO_RIG_EVIDENCE, noEvidence.size());
	}

	/**
	 * The body table has to actually distinguish the bodies, or the rule above is
	 * satisfied by a table of zeroes.
	 *
	 * <p>The mirror of {@link #theFramemapTableTellsTheCreaturesApart}, and it is not
	 * hypothetical for the same reason: 255 of the 340 covered model ids really are on
	 * framemap 0, so a table that rounded the rest off to human would look almost right
	 * and pass every record in the dataset. The counts and the four spot-checks below
	 * are what stops that.
	 *
	 * <p>These four counts are properties of the <b>table</b>, which the nine-city cut
	 * did not touch — see {@link ModelSkeletons} for why its rows outlive the dataset.
	 * The matching claim about the <b>dataset</b> is
	 * {@link #everyShippedModelIdIsEitherRiggedOrExplicitlyUnriggable}.
	 */
	@Test
	public void theModelSkeletonTableTellsTheBodiesApart()
	{
		Set<Integer> framemaps = new TreeSet<>();
		for (Set<Integer> rigs : ModelSkeletons.all().values())
		{
			framemaps.addAll(rigs);
		}

		assertEquals("distinct framemaps across the model table", 28, framemaps.size());
		assertEquals("shipped model ids with a rig recorded", 340, ModelSkeletons.all().size());
		assertEquals("shipped model ids no NPC is built out of, so no rig can be inferred",
			36, ModelSkeletons.NO_NPC_EVIDENCE.size());
		assertEquals("npcAppearanceId bodies", 7, ModelSkeletons.bodies().size());

		// One per record that was actually found wrong by this table, so a flattening
		// fails with the name of the thing it would have stopped catching.
		assertEquals("the Rogue body Sludgellama wears",
			(Integer) AnimationSkeletons.HUMAN, ModelSkeletons.framemapOfBody(526));
		assertEquals("model 12735 is a Street urchin part, on the small-humanoid rig",
			Collections.singleton(2402), ModelSkeletons.framemapsOf(12735));
		assertEquals("model 56138 is a Henja/Boy part, on the same one",
			Collections.singleton(2402), ModelSkeletons.framemapsOf(56138));
		assertEquals("model 41886 is the Inactive spirit pool, which is on neither",
			Collections.singleton(1944), ModelSkeletons.framemapsOf(41886));
		assertEquals("and a brazier is on nothing at all — it is object geometry",
			Collections.<Integer>emptySet(), ModelSkeletons.framemapsOf(2260));
	}

	/**
	 * Every model id the dataset actually ships is classified one way or the other:
	 * it has a rig recorded, or it is named as having no NPC to infer one from.
	 *
	 * <p>This is the guard that used to be implicit. {@link ModelSkeletons} held
	 * exactly as many rows as the dataset had distinct model ids — 340 rigged plus 36
	 * unriggable, against 376 shipped — so a shipped id nobody had looked up showed as
	 * a size mismatch in {@link #theModelSkeletonTableTellsTheBodiesApart}. The
	 * nine-city cut took the dataset to 324 without touching the table (see
	 * {@link ModelSkeletons} for why the extra rows were kept), so the two are no
	 * longer the same set and that coincidence stopped doing any work.
	 *
	 * <p>Stated directly it is a better check than the coincidence was: it fails with
	 * the id that has no row, rather than with two numbers that disagree. An
	 * unclassified id is not cosmetic — {@link ModelSkeletons#impliedRig} would return
	 * an empty set for a record built only out of such ids, and
	 * {@link #noRecordPlaysAnAnimationOnASkeletonItsOwnBodyIsNotRiggedTo} skips a
	 * record with no rig evidence, so the animation rule would silently stop being
	 * asked of it.
	 */
	@Test
	public void everyShippedModelIdIsEitherRiggedOrExplicitlyUnriggable()
	{
		Set<Integer> unclassified = new TreeSet<>();
		int rigged = 0;
		int unriggable = 0;

		for (int modelId : ShippedModelIds.distinct())
		{
			boolean hasRig = !ModelSkeletons.framemapsOf(modelId).isEmpty();
			boolean named = ModelSkeletons.NO_NPC_EVIDENCE.contains(modelId);

			if (hasRig && named)
			{
				unclassified.add(modelId);
				continue;
			}

			if (hasRig)
			{
				rigged++;
			}
			else if (named)
			{
				unriggable++;
			}
			else
			{
				unclassified.add(modelId);
			}
		}

		assertTrue("shipped model id(s) with no row in ModelSkeletons and no place on its "
				+ "NO_NPC_EVIDENCE list — look them up in the cache and add them, or the "
				+ "animation rule quietly stops being asked of whatever wears them: "
				+ unclassified, unclassified.isEmpty());

		// Both buckets pinned, so a table that classified everything as unriggable —
		// which would empty impliedRig() and turn the animation rule green everywhere —
		// fails here rather than passing.
		assertEquals("shipped model ids with a rig recorded", 290, rigged);
		assertEquals("shipped model ids no NPC is built out of", 34, unriggable);
		assertEquals("and the two buckets have to account for the whole dataset",
			ShippedModelIds.distinct().size(), rigged + unriggable);
	}

	/**
	 * Every animation in the enum is classified.
	 *
	 * <p>Both directions, because both failures are silent. An enum constant with no
	 * table entry would make the comparison above throw rather than skip — which is
	 * why {@link AnimationSkeletons#framemapOf} returns null instead of a default — but
	 * only if some record happens to use it, and most of the table is unused by the
	 * shipped data. A table entry with no enum constant behind it would not compile,
	 * so the interesting direction is the first one: adding an animation without
	 * looking up its framemap must fail here, immediately, rather than years later when
	 * somebody first pairs it with a walk.
	 */
	@Test
	public void everyAnimationConstantHasAFramemap()
	{
		Set<LivelyAnimation> missing = EnumSet.noneOf(LivelyAnimation.class);
		for (LivelyAnimation animation : LivelyAnimation.values())
		{
			if (AnimationSkeletons.framemapOf(animation) == null)
			{
				missing.add(animation);
			}
		}

		assertTrue("animation(s) with no framemap recorded — look the id up in the cache and add "
			+ "a row to AnimationSkeletons: " + missing, missing.isEmpty());

		assertEquals("the table has to cover the whole enum and nothing else",
			LivelyAnimation.values().length, AnimationSkeletons.all().size());
	}

	/**
	 * The table has to actually distinguish the creatures, or the rule above is
	 * satisfied by a table of zeroes.
	 *
	 * <p>This is the fake-test guard, and it is not hypothetical: a table that mapped
	 * every animation to {@link AnimationSkeletons#HUMAN} would pass the comparison for
	 * all 106 records including the thirteen broken ones, because every pair would agree
	 * on 0. So the six skeletons the thirteen fixes actually turned on are named here
	 * individually, asserted distinct from the human one and from each other, and the
	 * distinct-framemap count across the whole table is pinned on top.
	 */
	@Test
	public void theFramemapTableTellsTheCreaturesApart()
	{
		assertEquals("HumanWalk is the player skeleton",
			(Integer) AnimationSkeletons.HUMAN, AnimationSkeletons.framemapOf(LivelyAnimation.HumanWalk));
		assertEquals("HumanIdle is the same skeleton as HumanWalk",
			(Integer) AnimationSkeletons.HUMAN, AnimationSkeletons.framemapOf(LivelyAnimation.HumanIdle));

		assertEquals((Integer) AnimationSkeletons.DWARF, AnimationSkeletons.framemapOf(LivelyAnimation.DwarfWalk));
		assertEquals((Integer) AnimationSkeletons.GOBLIN, AnimationSkeletons.framemapOf(LivelyAnimation.GoblinWalk));
		assertEquals((Integer) AnimationSkeletons.PENGUIN, AnimationSkeletons.framemapOf(LivelyAnimation.PenguinWalk));
		assertEquals((Integer) AnimationSkeletons.CAT, AnimationSkeletons.framemapOf(LivelyAnimation.KittenWalk));
		assertEquals((Integer) AnimationSkeletons.SWARM, AnimationSkeletons.framemapOf(LivelyAnimation.BeeIdle));
		assertEquals((Integer) AnimationSkeletons.DOG, AnimationSkeletons.framemapOf(LivelyAnimation.DogWalk));

		Set<Integer> named = new TreeSet<>();
		named.add(AnimationSkeletons.HUMAN);
		named.add(AnimationSkeletons.DWARF);
		named.add(AnimationSkeletons.GOBLIN);
		named.add(AnimationSkeletons.PENGUIN);
		named.add(AnimationSkeletons.CAT);
		named.add(AnimationSkeletons.SWARM);
		named.add(AnimationSkeletons.DOG);
		assertEquals("the seven named skeletons must be seven different numbers", 7, named.size());

		// And the whole table, so a wholesale flattening cannot hide behind the seven
		// spot-checks above.
		assertEquals("distinct framemaps across the animation table",
			33, new TreeSet<>(AnimationSkeletons.all().values()).size());
	}

	/**
	 * The corrected pairs, named one by one.
	 *
	 * <p>The sweep above says "no citizen disagrees with itself", which stays true if
	 * somebody fixes a mismatch by making the citizen stationary or by copying the
	 * wrong animation onto both fields. This says what each of the thirteen was
	 * actually given, so a regression that re-broke one of them fails with that
	 * citizen's name in the message rather than as an anonymous list entry.
	 *
	 * <p><b>"Its own species' gait" is eight of the thirteen, not thirteen.</b> The
	 * method is named for the skeleton, not the animation, because that is all the
	 * thirteen have in common. Eight got the exact {@code walk} of the NPC whose model
	 * list the record copies. Grimefang and Sludgenose got {@code GoblinWalk} (6202)
	 * where NPC 3028 "Goblin" — which owns their exact models — walks on 6180; both are
	 * framemap 1415, so the rig is right and the animation is a different goblin walk.
	 * Forester, Thalindra and the Dark wizard have no NPC owning their exact models at
	 * all, so {@code HumanWalk} was a judgement made on the rig: every NPC sharing any
	 * of Forester's or the Dark wizard's models is on framemap 0, and Thalindra is 671
	 * of 672. {@code NOTICE} carries the same three-way split, because a licensee reads
	 * that and not this.
	 */
	@Test
	public void theThirteenCorrectedCitizensCarryAGaitFromTheirOwnSkeleton()
	{
		assertGait(12594, "Grimefang", LivelyAnimation.GoblinChill, LivelyAnimation.GoblinWalk);
		assertGait(12594, "Sludgenose", LivelyAnimation.GoblinIdle3, LivelyAnimation.GoblinWalk);
		assertGait(12596, "Skipper", LivelyAnimation.PenguinIdle, LivelyAnimation.PenguinWalk);
		assertGait(12853, "Bees!", LivelyAnimation.BeeIdle, LivelyAnimation.BeeIdle);
		assertGait(12853, "Nightfire", LivelyAnimation.CatSit, LivelyAnimation.KittenWalk);
		assertGait(12853, "Dofur", LivelyAnimation.DwarfSit, LivelyAnimation.DwarfWalk);
		assertGait(12853, "Simon", LivelyAnimation.DwarfSit, LivelyAnimation.DwarfWalk);
		assertGait(12853, "Rifur", LivelyAnimation.DwarfSmith, LivelyAnimation.DwarfWalk);
		assertGait(12853, "Dorgud", LivelyAnimation.DwarfIdle, LivelyAnimation.DwarfWalk);
		assertGait(12850, "Zack", LivelyAnimation.FurnaceSmelt, LivelyAnimation.HumanWalk);
		assertGait(11061, "Forester", LivelyAnimation.Woodcutting, LivelyAnimation.HumanWalk);
		assertGait(12850, "Thalindra", LivelyAnimation.Sitting, LivelyAnimation.HumanWalk);
		assertGait(12850, "Dark wizard", LivelyAnimation.Sitting, LivelyAnimation.HumanWalk);
	}

	/**
	 * A printed roster of every animation pairing the dataset uses, backed by an
	 * assertion so it cannot drift from what was checked.
	 */
	@Test
	public void printsTheAnimationPairingsForHumanReview()
	{
		TreeMap<String, Integer> pairings = new TreeMap<>();

		for (EntityDefinition citizen : shippedCitizens())
		{
			LivelyAnimation idle = citizen.getIdleAnimation();
			LivelyAnimation move = citizen.getMoveAnimation();
			if (idle == null || move == null)
			{
				continue;
			}
			String key = String.format("%-22s %-22s framemap %d",
				idle.name(), move.name(), AnimationSkeletons.framemapOf(idle));
			pairings.merge(key, 1, Integer::sum);
		}

		System.out.println("Lively Cities animation pairings — idle, move, shared framemap, citizens");
		int total = 0;
		for (java.util.Map.Entry<String, Integer> row : pairings.entrySet())
		{
			System.out.println(row.getKey() + "   " + row.getValue());
			total += row.getValue();
		}

		assertEquals("the printed rows have to account for every checked citizen",
			CITIZENS_WITH_BOTH_ANIMATIONS, total);
	}

	// --- fixtures ------------------------------------------------------------

	private static void assertGait(int regionId, String name, LivelyAnimation idle, LivelyAnimation move)
	{
		EntityDefinition citizen = null;
		for (EntityDefinition candidate : shippedCitizens())
		{
			if (candidate.getRegionId() == regionId && name.equals(candidate.getName()))
			{
				assertNull("two citizens named " + name + " in " + regionId
					+ ".json would make this assertion ambiguous", citizen);
				citizen = candidate;
			}
		}

		assertNotNull(name + " is no longer in " + regionId + ".json", citizen);
		assertEquals(name + " idle animation", idle, citizen.getIdleAnimation());
		assertEquals(name + " move animation", move, citizen.getMoveAnimation());
		assertEquals(name + " must stand and walk on one skeleton",
			AnimationSkeletons.framemapOf(idle), AnimationSkeletons.framemapOf(move));
	}

	private static List<EntityDefinition> shippedCitizens()
	{
		List<EntityDefinition> out = new ArrayList<>();
		for (EntityDefinition entity : shippedEntities())
		{
			if (entity.getType() != null && entity.getType().isCitizen())
			{
				out.add(entity);
			}
		}
		return out;
	}

	/** Every shipped record, scenery included — see the body-rig rule for why. */
	private static List<EntityDefinition> shippedEntities()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			out.addAll(region.getEntities());
		}

		return out;
	}
}

