package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Which records in the vendored dataset are ours, what they are made of, and the fact
 * that {@code NOTICE} says both correctly.
 *
 * <h2>Why this is a test and not a paragraph</h2>
 *
 * <p>{@code src/main/resources/RegionData/} is somebody else's work, redistributed
 * under BSD-2. Adding records to it is a modification, and the licence's whole point
 * is that a reader can tell what was changed. {@code NOTICE} item 8 makes claims a
 * reader has no way to check for themselves: that exactly thirty-three records were
 * authored by this project in the 2026-08-29 top-up, that they are the ones whose
 * {@code uuid} begins {@value #MARKER}, and that every one of them wears a
 * {@code modelIds} array copied whole out of a record already in the dataset with
 * that record's palette re-dealt.
 *
 * <p>All of those rot the moment somebody adds a thirty-fourth citizen, and none of
 * them would fail anything. So this reads the table out of {@code NOTICE} itself and
 * checks it against the shipped files: the region ids, the counts, the names, and —
 * record by record — the kit. A disclosure that has drifted from the data is a red
 * build rather than a quiet inaccuracy in a licence file.
 *
 * <h2>Why the uuid and not a field</h2>
 *
 * <p>The cameos are marked with {@code "cameo": true}, but that flag means "opt-in
 * content behind a checkbox" — {@code EntityScene} and {@link CitizenEcho} both read
 * it — so putting it on an ordinary townsperson who is on by default would be a lie
 * with behaviour attached. A new field would change the wire format for the sake of
 * bookkeeping. The uuid is already required, already unique, and is the one thing
 * about a record that never changes ({@code EntityDefinition.stableHash}), so a
 * reserved prefix costs nothing and is greppable from outside the build.
 *
 * <h2>Both rosters, not just the citizen one</h2>
 *
 * <p>This class reads the region files itself rather than going through
 * {@link ShippedCitizens}, which is deliberately citizens-only (see its javadoc).
 * Every count here is a claim about <i>records this project authored</i>, and a
 * marked record parked in {@code sceneryRoster} would be invisible to a
 * citizens-only reader — including to the "exactly thirty-three" count that is the
 * headline of the disclosure. It is read from both rosters and the scenery half is
 * then asserted empty, so "there are none" is a measured fact rather than a
 * consequence of not having looked.
 *
 * <h2>Requires a fresh test run</h2>
 *
 * <p>{@code NOTICE} is declared an input of the {@code test} task in
 * {@code build.gradle} for this class's sake. Without that declaration, editing
 * {@code NOTICE} and running {@code ./gradlew test} reports nothing and exits 0 —
 * the task is up to date, because none of its inputs appeared to change, and the
 * disclosure check never runs. If that declaration is ever removed, this class is
 * only honest under {@code ./gradlew clean test} or {@code --rerun-tasks}.
 */
public class AuthoredRecordsTest
{
	/** The uuid prefix every record this project authored in the top-up carries. */
	private static final String MARKER = "add1";

	/** What {@code NOTICE} item 8 claims, and what the region files have to show. */
	private static final int AUTHORED = 33;

	/**
	 * The uuid prefix every record this project authored in the <b>livery</b> pass
	 * carries, and what {@code NOTICE} item 12 claims about them.
	 *
	 * <p>A second marker rather than more of the first, because the two passes make
	 * different claims about the same kind of record. Item 8's thirty-three wear their
	 * donor's palette <i>rotated</i>; item 12's hundred and twenty-seven wear one that
	 * was <i>authored</i>, so that the colours land on the slots that make them read as
	 * a city's. A single marker would put both under whichever rule this class checked,
	 * and the rule that survived would be the one nothing contradicted.
	 */
	private static final String LIVERY_MARKER = "add2";

	/** @see #LIVERY_MARKER */
	private static final int LIVERIED = 127;

	/**
	 * The disclosure's own table, parsed back out of {@code NOTICE}.
	 *
	 * <p>Lines look like {@code 10290   2   Ardougne monastery      Anselm, Brother
	 * Edwy} — region id, count, a place label, then the names. The label is prose and
	 * is not checked; the other three are. Every row is one line, which is why the
	 * Draynor row runs long rather than wrapping: a continuation line is one more thing
	 * for this pattern to get subtly wrong, and getting it wrong here means silently
	 * checking twelve rows instead of thirteen.
	 */
	private static final Pattern ROW = Pattern.compile(
		"^ {7}(\\d{5}) {3}(\\d+) {3}\\S.*?(?: {2,})([A-Z][^\\n]*)$",
		Pattern.MULTILINE);

	@Test
	public void everyRecordThisProjectAuthoredIsIdentifiableFromTheDataAlone()
	{
		TreeMap<Integer, List<String>> ours = ourRecordsByRegion();

		int authored = 0;
		for (List<String> names : ours.values())
		{
			authored += names.size();
		}

		assertEquals("records carrying the '" + MARKER + "' uuid marker", AUTHORED, authored);
		assertEquals("region files they were added to", 13, ours.size());

		int upstream = 0;
		int liveried = 0;
		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (citizen.uuid.startsWith(MARKER))
			{
				continue;
			}
			if (citizen.uuid.startsWith(LIVERY_MARKER))
			{
				liveried++;
			}
			else
			{
				upstream++;
			}
		}

		// The other half of the claim, and the half that would rot silently: a marker
		// is only a marker if nothing else wears it. 109 is the roster as it stood
		// before either pass, cameos included, and it must not move again — a third
		// pass that reached for "add1" or "add2" would show up here as this number
		// falling rather than as a marker quietly meaning two things.
		assertEquals("citizens that predate both passes and must carry neither marker",
			109, upstream);
		assertEquals("citizens carrying the '" + LIVERY_MARKER + "' marker", LIVERIED, liveried);
		assertEquals("and the three parts are the whole roster",
			269, authored + liveried + upstream);
	}

	/**
	 * Nothing this project authored hides in {@code sceneryRoster}.
	 *
	 * <p>Not a hypothetical tidiness rule. Every other assertion in this class, and
	 * the {@code grep} {@code NOTICE} hands the reader, is about citizens; a marked
	 * record in the other roster would be authored content this project ships and
	 * discloses nowhere, and it would leave "exactly thirty-three" true of the
	 * citizen roster while being false of the dataset. It would also be silent
	 * behaviourally — scenery has no name, no examine text and no remarks, and
	 * {@link CitizenEcho} refuses to derive from it — so nothing else would notice.
	 */
	@Test
	public void everyAuthoredRecordIsACitizenAndNotAPieceOfScenery()
	{
		List<String> inTheWrongRoster = new ArrayList<>();
		int marked = 0;

		for (Record record : shippedRecords())
		{
			if (!record.isOurs())
			{
				continue;
			}

			marked++;
			if (!"citizenRoster".equals(record.rosterKey))
			{
				inTheWrongRoster.add(record.describe());
			}
		}

		assertTrue("records this project authored that ship in sceneryRoster: "
			+ inTheWrongRoster, inTheWrongRoster.isEmpty());

		// Counted over both rosters, so a record moved from one to the other changes
		// this number even though it changes neither roster's own total by itself.
		assertEquals("marked records across the whole dataset, both rosters",
			AUTHORED, marked);
	}

	/**
	 * An authored townsperson must not be flagged as a cameo.
	 *
	 * <p>{@code "cameo": true} is a behavioural flag — it gates a record behind the
	 * {@code cameos} checkbox and stops {@link CitizenEcho} deriving from it — and
	 * {@code NOTICE} tells a reader it is what identifies the six likenesses. Putting
	 * it on one of these thirty-three would both hide an ordinary citizen behind a
	 * checkbox nobody expects and make that sentence in the licence file wrong.
	 */
	@Test
	public void noAuthoredTownspersonIsFlaggedAsACameoOrDressedFromAnNpc()
	{
		List<String> offenders = new ArrayList<>();

		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (!citizen.uuid.startsWith(MARKER))
			{
				continue;
			}

			if (citizen.cameo)
			{
				offenders.add(citizen.name + " is flagged as a cameo");
			}

			// Not a rule about what is possible, but about what this pass did: every
			// one of the thirty-three wears raw modelIds copied from a shipped record,
			// which is what NOTICE item 8 claims and what keeps the distinct-model-id
			// figure at 324.
			if (citizen.npcAppearanceId != 0)
			{
				offenders.add(citizen.name + " is dressed from NPC "
					+ citizen.npcAppearanceId + " rather than from copied modelIds");
			}
		}

		assertTrue("authored townsfolk must be ordinary citizens: " + offenders,
			offenders.isEmpty());
	}

	/**
	 * <b>The rule the whole top-up rests on, enforced rather than trusted.</b>
	 *
	 * <p>{@code NOTICE} item 8 says it in one sentence: every one of the thirty-three
	 * reuses a {@code modelIds} array copied whole out of a record already in this
	 * dataset, with that record's own {@code modelRecolorFind} kept as-is and its
	 * {@code modelRecolorReplace} rotated so the copy is not simply its donor standing
	 * somewhere else. That is what keeps the distinct-model-id figure at 324 — the
	 * number that decides how much of this plugin a cache renumbering can break — and
	 * it is what stops the dataset acquiring twins.
	 *
	 * <p>Until this test it was held by nothing but the discipline of whoever wrote
	 * the records. A review on 2026-08-29 made three edits to prove it, and <b>all
	 * three survived the whole suite</b>:
	 *
	 * <ol>
	 *   <li>setting one new record's {@code modelRecolorReplace} to its donor's exact
	 *       array, making it a pixel-for-pixel twin of a shipped citizen;</li>
	 *   <li>reversing one new record's {@code modelIds} order — a hand-assembled kit
	 *       that appears nowhere in the dataset, with the distinct-id count unmoved
	 *       because reversing an array changes no member of it;</li>
	 *   <li>swapping one model id for another already in the dataset, producing a
	 *       combination that exists in no record and is therefore a body nobody has
	 *       ever seen rendered.</li>
	 * </ol>
	 *
	 * <p>The three assertions below are one per mutation, in that order.
	 *
	 * <p><b>Why "a rotation" and not "some other palette".</b> The re-deal is not a
	 * loose "make it look different" — it is {@link CitizenEcho#redeal}, the exact
	 * operation the {@code Crowded} derivation uses on the same arrays, and the
	 * rotation has to be one {@link CitizenEcho#distinctDeals} would offer, which is
	 * how a rotation that comes out as the identity (a palette of one repeated colour)
	 * is excluded. Stating the rule in the code's own vocabulary rather than
	 * re-implementing it means this test cannot drift from what the plugin does, and
	 * it means the authored records and the derived ones are provably the same kind of
	 * thing: an existing citizen's wardrobe, dealt round.
	 */
	@Test
	public void everyAuthoredKitIsAWholeCopyOfAShippedKitWithThePaletteReDealt()
	{
		List<Record> all = shippedRecords();

		List<String> noDonor = new ArrayList<>();
		List<String> notReDealt = new ArrayList<>();
		List<String> donorIsNotACitizen = new ArrayList<>();
		TreeSet<String> repaletted = new TreeSet<>();
		TreeSet<String> legsLifted = new TreeSet<>();
		int checked = 0;

		for (Record ours : all)
		{
			if (!ours.isOurs())
			{
				continue;
			}

			checked++;

			List<Record> donors = new ArrayList<>();
			for (Record candidate : all)
			{
				if (candidate.isOurs() || candidate.isLiveried())
				{
					// A record this project authored is not evidence that a kit predates
					// it — and that is true of the later pass as well as this one. The
					// livery pass copies the same donor kits these records copy, so every
					// one of its 127 records would otherwise turn up here as a candidate
					// donor for a record that predates it by three days.
					continue;
				}

				if (Arrays.equals(candidate.modelIds, ours.modelIds)
					&& Arrays.equals(candidate.recolorFind, ours.recolorFind))
				{
					donors.add(candidate);
				}
			}

			if (donors.isEmpty())
			{
				noDonor.add(ours.describe() + " wears modelIds/modelRecolorFind that appear "
					+ "in no record predating the top-up: " + Arrays.toString(ours.modelIds));
				continue;
			}

			Record reDealtFrom = null;
			Lift lifted = null;
			for (Record donor : donors)
			{
				Lift slots = reDealOf(
					ours.recolorReplace, donor.recolorReplace, ours.recolorFind);
				if (slots != null)
				{
					reDealtFrom = donor;
					lifted = slots;
					if (slots.total() == 0)
					{
						break;
					}
				}
			}

			if (lifted != null && lifted.face > 0)
			{
				repaletted.add(ours.name);
			}
			if (lifted != null && lifted.legs > 0)
			{
				legsLifted.add(ours.name);
			}

			if (reDealtFrom == null)
			{
				List<String> tried = new ArrayList<>();
				for (Record donor : donors)
				{
					tried.add(donor.describe() + " "
						+ Arrays.toString(shorts(donor.recolorReplace)));
				}
				notReDealt.add(ours.describe() + " carries "
					+ Arrays.toString(shorts(ours.recolorReplace))
					+ ", which is not a distinct re-deal of any donor's palette: " + tried);
				continue;
			}

			// True of every donor this pass actually used, and worth pinning: scenery
			// carries no name, no examine text and no remarks, so a citizen wearing a
			// market stall's kit would be a body the dataset has no other example of.
			if (!"citizenRoster".equals(reDealtFrom.rosterKey))
			{
				donorIsNotACitizen.add(ours.describe() + " copies " + reDealtFrom.describe());
			}
		}

		assertTrue("authored kits that are not a whole copy of an existing kit — a "
			+ "hand-assembled modelIds array is a body nobody has seen rendered, and a "
			+ "new combination is new cache-breakage surface: " + noDonor, noDonor.isEmpty());
		assertTrue("authored kits whose palette is their donor's, not a re-deal of it — "
			+ "which is a pixel-for-pixel twin of a shipped citizen: " + notReDealt,
			notReDealt.isEmpty());
		assertTrue("authored kits copied from scenery: " + donorIsNotACitizen,
			donorIsNotACitizen.isEmpty());

		// The exception is bounded and named, because an unbounded one would let the
		// rule above be satisfied by any palette at all: "a re-deal with some slots
		// changed" is not a claim. These are the six the 2026-08-30 repalette lifted the
		// face colour off; every other authored record is a rotation and nothing else.
		assertEquals("authored records whose donor's palette had to be repaletted "
				+ "because no rotation of it could hold the face colour: " + repaletted,
			new TreeSet<>(Arrays.asList(
				"Aldous", "Brother Edwy", "Hesper", "Marta", "Sela", "Wynn")),
			repaletted);

		// The second exception, added 2026-08-31 and bounded the same way: one slot, the
		// legs slot, moved off a colour BodySlotLintTest now refuses there. See
		// everyLegsLiftIsOneSlotMovedOffTheFleshGamutAndNothingElse for its shape and for
		// why a whole-wardrobe re-rotation was not taken instead.
		assertEquals("authored records whose legs slot had to be lifted off the flesh "
				+ "gamut the rotation dealt onto it: " + legsLifted,
			new TreeSet<>(Arrays.asList(
				"Berta", "Brother Edwy", "Marlow", "Nessa", "Osric", "Tarik", "Tobias")),
			legsLifted);

		// The sample guard this file's siblings all carry: the three rules above are
		// inside the loop, so a scan that found no marked records would pass having
		// asked nothing at all.
		assertEquals("every authored record has to have been put through the rule",
			AUTHORED, checked);
	}

	/**
	 * <b>The six records a rotation could not produce, and why no rotation could.</b>
	 *
	 * <p>The rule above allows one exception, and this test is the evidence for it: for
	 * each of the six, <i>every</i> rotation of the donor's palette lands
	 * {@link CitizenEcho#PLAYER_SKIN_BASE} — the colour the client paints a player's
	 * face — on a {@code find} slot the donor did not aim at skin. That is not a
	 * property of which rotation was picked; it is a property of the donor. Each of
	 * these six donors carries the face colour on a slot aimed at an arm, a hand or a
	 * head, and <b>none of them has a {@code find = 4550} slot at all</b>, so there is
	 * nowhere in the array for the face colour to stay. Rotating such a palette moves
	 * the face somewhere by construction.
	 *
	 * <p>Asserting this is what stops the exception being a licence to hand-author a
	 * palette: if somebody later repalettes a record whose donor <i>could</i> have been
	 * rotated safely, this goes red.
	 */
	@Test
	public void noRotationOfThoseSixDonorsCouldHaveHeldTheFaceColourInPlace()
	{
		List<Record> all = shippedRecords();
		int checked = 0;

		for (Record ours : all)
		{
			if (!ours.isOurs())
			{
				continue;
			}

			for (Record donor : all)
			{
				if (donor.isOurs()
					|| !Arrays.equals(donor.modelIds, ours.modelIds)
					|| !Arrays.equals(donor.recolorFind, ours.recolorFind))
				{
					continue;
				}

				Lift lift = reDealOf(ours.recolorReplace, donor.recolorReplace,
					ours.recolorFind);
				if (lift == null || lift.face == 0)
				{
					// A legs lift is a different exception with a different justification
					// — see everyLegsLiftIsOneSlotMovedOffTheFleshGamutAndNothingElse. It
					// is deliberately not claimed to be forced, so it must not be counted
					// here: doing so would make this test assert an impossibility that is
					// not true and quietly widen what "forced" means.
					continue;
				}

				checked++;
				short[] theirs = shorts(donor.recolorReplace);
				for (int deal = 1; deal < theirs.length; deal++)
				{
					short[] dealt = CitizenEcho.redeal(theirs, deal);
					if (Arrays.equals(dealt, theirs))
					{
						continue;
					}

					assertTrue(ours.describe() + " could have been rotation " + deal
							+ " of " + donor.describe() + " without touching a colour, so "
							+ "repaletting it was not forced: " + Arrays.toString(dealt),
						landsTheFaceColourOnANonSkinSlot(dealt, ours.recolorFind));
				}
			}
		}

		assertEquals("repaletted records the impossibility was proved for", 6, checked);
	}

	/**
	 * <b>The seven legs lifts, and the honest reason each one is a lift rather than a
	 * different rotation.</b>
	 *
	 * <p>{@link BodySlotLintTest#noLegsSlotIsPaintedAColourFromTheFleshGamut} refuses any
	 * legs slot painted a colour inside {@link CitizenEcho#isFlesh}'s gamut. Seven of the
	 * thirty-three authored records inherited such a colour from their donor's rotation,
	 * so seven had to move — and the question this test answers is <b>what "move" was
	 * allowed to mean</b>.
	 *
	 * <h2>What a lift is allowed to be</h2>
	 *
	 * <p>Exactly one slot, it has to be the {@link BodySlots#LEGS_BASE} slot, the colour
	 * the rotation would have dealt there has to be inside the gamut, and the colour put
	 * there has to be outside it. Nothing else about the palette may move. That is
	 * asserted below record by record, which is what stops "a re-deal with a slot lifted"
	 * becoming a licence to hand-author a wardrobe.
	 *
	 * <h2>Why not simply pick a rotation that needed no lift</h2>
	 *
	 * <p>{@link #noRotationOfThoseSixDonorsCouldHaveHeldTheFaceColourInPlace} makes
	 * exactly that demand of the face-colour exception, and it is a fair demand to make
	 * of this one too. The answer is that it was available six times out of seven and was
	 * taken none of them, for two different reasons, both counted below rather than
	 * asserted away:
	 *
	 * <ul>
	 *   <li><b>"Brother Edwy" had no clean rotation at all.</b> His donor, the "Assistant
	 *       Apothecary", carries {@link CitizenEcho#PLAYER_SKIN_BASE} on its cuff slot and
	 *       has no {@code find = 4550} slot to hold it, so every rotation moves the face
	 *       somewhere it may not go — and four of the five also deal a tan onto the legs.
	 *       He is forced twice over, which is why he is the one record in both sets.</li>
	 *   <li><b>"Tobias", "Marlow" and "Tarik" had one clean rotation each and it was
	 *       already taken.</b> The gardener palette admits exactly one, and Tobias and
	 *       Marlow are both built from it, so giving it to both would make them
	 *       pixel-identical. The Ali palette likewise admits exactly one, and "Fahd" is
	 *       already wearing it — in Al Kharid, the same city as Tarik, which is a twin
	 *       standing where somebody can see both halves. Trading a bare leg for a
	 *       duplicate is not a repair.</li>
	 *   <li><b>"Osric", "Berta" and "Nessa" had a clean rotation and it was not taken.</b>
	 *       No twin would have resulted. The reason is scope and nothing grander: a
	 *       rotation repaints every slot in the record — the face, the hair, the tunic —
	 *       to fix the trousers, and these three ship today with faces and hair somebody
	 *       looked at. A lift changes the one slot that is wrong. This is the pass's
	 *       judgement rather than a rule, so it is written down as one.</li>
	 * </ul>
	 */
	@Test
	public void everyLegsLiftIsOneSlotMovedOffTheFleshGamutAndNothingElse()
	{
		List<Record> all = shippedRecords();
		TreeSet<String> lifted = new TreeSet<>();
		TreeSet<String> hadACleanRotationAvailable = new TreeSet<>();

		for (Record ours : all)
		{
			if (!ours.isOurs())
			{
				continue;
			}

			for (Record donor : all)
			{
				if (donor.isOurs()
					|| !Arrays.equals(donor.modelIds, ours.modelIds)
					|| !Arrays.equals(donor.recolorFind, ours.recolorFind))
				{
					continue;
				}

				Lift lift = reDealOf(ours.recolorReplace, donor.recolorReplace, ours.recolorFind);
				if (lift == null || lift.legs == 0)
				{
					continue;
				}

				lifted.add(ours.name);
				assertEquals(ours.describe() + " lifts more than the one slot the legs rule "
					+ "forces, which is hand-authoring rather than a re-deal", 1, lift.legs);

				if (cleanRotationsOf(donor.recolorReplace, ours.recolorFind) > 0)
				{
					hadACleanRotationAvailable.add(ours.name);
				}

				// The shape of the lift itself: the slot has to be the legs slot, and the
				// move has to be out of the gamut rather than merely to a different colour.
				short[] mine = shorts(ours.recolorReplace);
				short[] theirs = shorts(donor.recolorReplace);
				int rotationsThatWouldHaveDealtFleshOntoTheLegs = 0;
				for (int deal = 1; deal < theirs.length; deal++)
				{
					short[] dealt = CitizenEcho.redeal(theirs, deal);
					for (int i = 0; i < dealt.length; i++)
					{
						if (dealt[i] == mine[i]
							|| (ours.recolorFind[i] & 0xFFFF) != BodySlots.LEGS_BASE
							|| !CitizenEcho.isFlesh(dealt[i]))
						{
							continue;
						}

						rotationsThatWouldHaveDealtFleshOntoTheLegs++;
						assertFalse(ours.describe() + " lifts its legs slot onto " + mine[i]
								+ ", which is inside the gamut it was lifted out of",
							CitizenEcho.isFlesh(mine[i]));
					}
				}
				assertTrue(ours.describe() + " is marked as a legs lift but no rotation of "
						+ donor.describe() + " deals a flesh colour onto its legs slot",
					rotationsThatWouldHaveDealtFleshOntoTheLegs > 0);
			}
		}

		assertEquals("authored records carrying a legs lift", new TreeSet<>(Arrays.asList(
			"Berta", "Brother Edwy", "Marlow", "Nessa", "Osric", "Tarik", "Tobias")), lifted);

		// The count that keeps the javadoc above honest. Six of the seven could have been
		// re-rotated instead; the one that could not is the one that is also a face lift.
		assertEquals("legs lifts that had an untouched rotation available instead",
			new TreeSet<>(Arrays.asList("Berta", "Marlow", "Nessa", "Osric", "Tarik", "Tobias")),
			hadACleanRotationAvailable);
	}

	/**
	 * The licence file's table has to be the dataset's table.
	 *
	 * <p>Region by region, count by count, name by name. This is the assertion the
	 * whole class exists for: {@code NOTICE} is the document a licensee reads, and
	 * nothing else in this build would notice it going stale.
	 *
	 * <p><b>A row's count is checked against more than its own name list.</b> It used
	 * to be checked against that alone, which left a hole one duplicate wide: a row
	 * reading {@code 10290   3   Ardougne monastery   Anselm, Brother Edwy, Brother
	 * Edwy} has a count of three and three names, so it passed, and the name
	 * comparison below is between sets, so the duplicate collapsed and matched the two
	 * records that actually ship. The disclosure would have overstated what this
	 * project added and nothing would have said so. Names within a row are now
	 * asserted distinct, and the row counts are asserted to sum to the thirty-three
	 * the prose above the table claims.
	 */
	@Test
	public void theNoticeTableMatchesWhatWasActuallyAdded() throws IOException
	{
		String notice = new String(
			Files.readAllBytes(new File("NOTICE").toPath()), StandardCharsets.UTF_8);

		assertTrue("NOTICE has to state the marker, or a reader cannot find these records",
			notice.contains("beginning \"" + MARKER + "\""));

		TreeMap<Integer, List<String>> declared = new TreeMap<>();
		int declaredTotal = 0;
		Matcher matcher = ROW.matcher(noticeItem(notice, "\n  8. ", "\n  9. "));
		while (matcher.find())
		{
			int region = Integer.parseInt(matcher.group(1));
			int count = Integer.parseInt(matcher.group(2));
			List<String> names = new ArrayList<>();
			for (String name : matcher.group(3).split(","))
			{
				String trimmed = name.trim().replaceAll("\\s+", " ");
				if (!trimmed.isEmpty())
				{
					names.add(trimmed);
				}
			}

			assertEquals("NOTICE row for region " + region + " names " + names.size()
				+ " citizen(s) but claims " + count, count, names.size());
			assertEquals("NOTICE row for region " + region + " lists a name twice, which "
					+ "makes its count larger than the number of records it names: " + names,
				names.size(), new TreeSet<>(names).size());
			assertFalse("region " + region + " is listed twice in NOTICE",
				declared.containsKey(region));
			declared.put(region, names);
			declaredTotal += count;
		}

		assertEquals("the parser has to find the whole table — a regex that matched "
				+ "nothing would pass while checking nothing", 13, declared.size());
		assertEquals("the row counts have to sum to the total NOTICE claims in prose",
			AUTHORED, declaredTotal);

		TreeMap<Integer, List<String>> actual = ourRecordsByRegion();
		assertEquals("the regions NOTICE lists have to be the regions that changed",
			actual.keySet(), declared.keySet());

		for (Integer region : actual.keySet())
		{
			assertEquals("citizens NOTICE lists for " + region,
				new TreeSet<>(declared.get(region)), new TreeSet<>(actual.get(region)));
		}
	}

	/**
	 * {@code NOTICE} item 12's table, checked the same way item 8's is.
	 *
	 * <p>Parsed out of the item's own slice of the file rather than out of the whole
	 * file, because {@link #ROW} matches both tables and a whole-file parse would put
	 * 34 rows in one map and check neither disclosure against anything.
	 */
	@Test
	public void theLiveryNoticeTableMatchesWhatWasActuallyAdded() throws IOException
	{
		String notice = new String(
			Files.readAllBytes(new File("NOTICE").toPath()), StandardCharsets.UTF_8);

		assertTrue("NOTICE has to state the livery marker, or a reader cannot find "
			+ "these records", notice.contains("beginning \"" + LIVERY_MARKER + "\""));

		TreeMap<Integer, List<String>> declared = new TreeMap<>();
		int declaredTotal = 0;
		Matcher matcher = ROW.matcher(noticeItem(notice, "\n 12. ", "\nBSD-2 permits"));
		while (matcher.find())
		{
			int region = Integer.parseInt(matcher.group(1));
			int count = Integer.parseInt(matcher.group(2));
			List<String> names = new ArrayList<>();
			for (String name : matcher.group(3).split(","))
			{
				String trimmed = name.trim().replaceAll("\\s+", " ");
				if (!trimmed.isEmpty())
				{
					names.add(trimmed);
				}
			}

			assertEquals("NOTICE row for region " + region + " names " + names.size()
				+ " citizen(s) but claims " + count, count, names.size());
			assertEquals("NOTICE row for region " + region + " lists a name twice",
				names.size(), new TreeSet<>(names).size());
			assertFalse("region " + region + " is listed twice in NOTICE item 12",
				declared.containsKey(region));
			declared.put(region, names);
			declaredTotal += count;
		}

		assertEquals("the parser has to find the whole table — a regex that matched "
			+ "nothing would pass while checking nothing", 21, declared.size());
		assertEquals("the row counts have to sum to the total NOTICE claims in prose",
			LIVERIED, declaredTotal);

		TreeMap<Integer, List<String>> actual = liveriedRecordsByRegion();
		assertEquals("the regions NOTICE lists have to be the regions that changed",
			actual.keySet(), declared.keySet());

		for (Integer region : actual.keySet())
		{
			assertEquals("citizens NOTICE lists for " + region,
				new TreeSet<>(declared.get(region)), new TreeSet<>(actual.get(region)));
		}
	}

	/**
	 * <b>The rule the livery pass rests on</b>, and it is not item 8's rule.
	 *
	 * <p>Each of the 127 wears a {@code modelIds} array and a {@code modelRecolorFind}
	 * array copied whole out of a record that predates it — that is what keeps the
	 * distinct-model-id figure at 324, and it is shared with item 8. What is different
	 * is the third array: item 8 rotates the donor's, and these author one. So the
	 * check that {@code everyAuthoredKitIsAWholeCopyOfAShippedKitWithThePaletteReDealt}
	 * makes about the palette cannot be made here, and the two claims that can be are
	 * made instead:
	 *
	 * <ul>
	 *   <li>the kit is somebody else's, whole — no hand-assembled arrays, no new ids;
	 *   <li>the palette is <i>not</i> the donor's, so the figure is not its donor
	 *       standing somewhere else.
	 * </ul>
	 */
	@Test
	public void everyLiveriedRecordWearsAShippedKitAndAPaletteOfItsOwn()
	{
		List<Record> all = shippedRecords();
		List<String> noDonor = new ArrayList<>();
		List<String> notRepainted = new ArrayList<>();
		int checked = 0;

		for (Record ours : all)
		{
			if (!ours.isLiveried())
			{
				continue;
			}

			checked++;
			boolean donorFound = false;
			boolean repainted = true;

			for (Record candidate : all)
			{
				if (candidate.isLiveried()
					|| !Arrays.equals(candidate.modelIds, ours.modelIds)
					|| !Arrays.equals(candidate.recolorFind, ours.recolorFind))
				{
					continue;
				}

				donorFound = true;
				if (Arrays.equals(candidate.recolorReplace, ours.recolorReplace))
				{
					repainted = false;
				}
			}

			if (!donorFound)
			{
				noDonor.add(ours.describe() + " wears modelIds/modelRecolorFind that "
					+ "appear in no record predating the livery pass");
			}
			else if (!repainted)
			{
				notRepainted.add(ours.describe() + " wears its donor's palette unchanged, "
					+ "so it is its donor standing somewhere else");
			}
		}

		assertTrue("liveried record(s) with no donor: " + noDonor, noDonor.isEmpty());
		assertTrue("liveried record(s) that were never repainted: " + notRepainted,
			notRepainted.isEmpty());
		assertEquals("liveried records the rule was asked about", LIVERIED, checked);
	}

	/**
	 * Every liveried record refuses the derivation, and nothing else does.
	 *
	 * <p>The flag is the reason the {@code Crowded} density did not move when the
	 * roster nearly doubled — see {@code EntityRecord.noEcho}. It is asserted from both
	 * ends because either alone is satisfiable by accident: a record that forgot the
	 * flag would seed "Passer-by" figures wearing a city's colours dealt onto the wrong
	 * slots, and a record that acquired it by a stray paste would silently stop seeding
	 * ones a reviewer had already looked at.
	 */
	@Test
	public void theLiveriedRecordsAreExactlyTheOnesThatRefuseToSeedAnEcho()
	{
		TreeSet<String> refuse = new TreeSet<>();
		TreeSet<String> liveried = new TreeSet<>();

		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> entities = new ArrayList<>();
		for (int regionId : ShippedRegions.ids())
		{
			entities.addAll(loader.loadRegion(regionId).getEntities());
		}
		assertEquals("the whole shipped roster", 311, entities.size());

		for (EntityDefinition entity : entities)
		{
			String label = entity.label() + " in " + entity.getRegionId() + ".json";
			if (entity.isNoEcho())
			{
				refuse.add(label);
			}
			if (entity.getUuid().toString().startsWith(LIVERY_MARKER))
			{
				liveried.add(label);
			}
		}

		assertEquals("records carrying \"noEcho\": true", LIVERIED, refuse.size());
		assertEquals("and they are exactly the liveried ones", liveried, refuse);
	}

	/**
	 * @param startsWith the first characters of the NOTICE item wanted
	 * @param endsWith   the first characters of whatever follows it
	 * @return that item's own text, so a table parse cannot wander into a neighbour's
	 */
	private static String noticeItem(String notice, String startsWith, String endsWith)
	{
		int from = notice.indexOf(startsWith);
		assertTrue("NOTICE has no item starting " + startsWith.trim(), from >= 0);
		int to = notice.indexOf(endsWith, from + startsWith.length());
		assertTrue("NOTICE item starting " + startsWith.trim() + " is not followed by "
			+ endsWith.trim(), to > from);
		return notice.substring(from, to);
	}

	private static TreeMap<Integer, List<String>> liveriedRecordsByRegion()
	{
		TreeMap<Integer, List<String>> ours = new TreeMap<>();
		for (Record record : shippedRecords())
		{
			if (record.isLiveried())
			{
				ours.computeIfAbsent(record.fileRegionId, k -> new ArrayList<>())
					.add(record.name);
			}
		}
		return ours;
	}

	/**
	 * @return whether {@code candidate} is {@code donor}'s palette dealt round by a
	 * rotation that actually changes it — which excludes the identity, and excludes a
	 * rotation that lands back on the palette it started from because every colour in
	 * it is the same
	 *
	 * <p><b>This used to ask {@link CitizenEcho#distinctDeals} for the rotations, and
	 * it deliberately does not any more.</b> Sharing that method made the authoring
	 * rule and the derivation rule the same rule by construction, which read as a
	 * strength right up until the derivation acquired a rule the authoring does not
	 * have: {@code distinctDeals} now refuses any rotation that would move a colour
	 * across the flesh boundary (see
	 * {@link CitizenEcho#keepsEachColourOnItsOwnSideOfTheSkin}), and 33 of the
	 * authored top-up records were hand-rotated by exactly such a rotation, so every
	 * one of them failed this test the moment the flesh rule landed.
	 *
	 * <p>They are not twins of their donors, which is the only thing this test claims,
	 * so the answer is to state the claim in its own terms rather than to borrow one
	 * that has grown a second meaning. The rotation is still {@link CitizenEcho#redeal}
	 * — the same operation, on the same arrays — and "distinct" is still the same
	 * exclusion. What is dropped is the flesh rule, which is a rule about <b>what this
	 * plugin may derive</b> and not about what a human may author: a Demon Butler with
	 * a red face and a shrouded figure with a white one are content decisions, and no
	 * test gets a vote on them.
	 *
	 * <p><b>That said, this is a finding and not a formality.</b> The hand-rotated
	 * palettes cross the boundary for the same reason a derived one would, and some of
	 * them therefore land a garment colour on a face, or a skin tone on a garment, on a
	 * citizen who ships at every density rather than only at {@code CROWDED}.
	 * <b>24 of the 33</b> are rotations the flesh rule would refuse — not all 33, which
	 * is what this paragraph claimed until the 2026-08-30 pass. The other nine happen to
	 * be class-preserving rotations and would have passed the coupled form unchanged,
	 * which matters because <b>"Wynn" in Catherby was one of the nine</b> and was the
	 * worst record in the set: he wore {@link CitizenEcho#PLAYER_SKIN_BASE} on
	 * {@code find = 25238}, the legs base, so his trousers were painted the exact colour
	 * the game paints faces. Neither form of this assertion could ever have caught him,
	 * because both ask whether a palette <i>is</i> a rotation and he is one.
	 *
	 * <p>The photographs the top-up shipped are worth naming rather than summarising.
	 * The Varrock "Gardener" is authored {@code [3507, 16026, 37394, 5572]} against the
	 * {@code find} slots {@code [4550, 8741, 25238, 123]} — a tan face, a dark
	 * yellow-green tunic, dark blue legs. "Tobias" in Falador is that palette rotated by
	 * two: a <b>very dark blue face</b>, and mid tan on <i>both</i> the torso and the
	 * legs. "Marlow" in Draynor is rotated by one: a <b>dark yellow-green face</b>, a
	 * dark blue torso and mid tan legs. So it is not only that one wears the green on
	 * his face and the other the blue — each of them also wears a complexion where a
	 * garment goes, which is the half of the fault the reader is actually looking at in
	 * the photograph.
	 *
	 * <p>Six records were worse still and were repaletted on 2026-08-30 — see
	 * {@link BodySlotLintTest} for the rule that now holds them and
	 * {@link #noRotationOfThoseSixDonorsCouldHaveHeldTheFaceColourInPlace} for why a
	 * different rotation was not available.
	 *
	 * <p><b>Tobias and Marlow were left out of that pass and should not have been.</b>
	 * The reasoning written here was that they wear flesh-<i>class</i> tans rather than
	 * the face colour itself, so no categorical rule reached them and repaletting them
	 * would be a taste judgement. That was defensible in the abstract and was falsified
	 * by observation on 2026-08-31: the owner, playing at {@code FULL}, reported figures
	 * that still looked like they had no trousers. Marlow's {@code 5572} decodes to
	 * hue 5, saturation 3, lightness 68 against the skin base's hue 4, saturation 3,
	 * lightness 70 — one hue rung and two lightness rungs from the colour the client
	 * paints a face. It is not a tan near skin; on a pair of legs it is skin.
	 *
	 * <p>The categorical rule that does reach them exists and is
	 * {@link BodySlotLintTest#noLegsSlotIsPaintedAColourFromTheFleshGamut}: a legs slot
	 * may not be painted a flesh-gamut colour at all. Both are now legs lifts — see
	 * {@link #everyLegsLiftIsOneSlotMovedOffTheFleshGamutAndNothingElse} — and their
	 * faces, which this paragraph describes correctly and which nothing in this pass
	 * touched, are still what they were.
	 */
	private static boolean isADistinctReDealOf(int[] candidate, int[] donor)
	{
		if (candidate.length != donor.length || donor.length < 2)
		{
			return false;
		}

		short[] mine = shorts(candidate);
		short[] theirs = shorts(donor);
		for (int deal = 1; deal < theirs.length; deal++)
		{
			short[] dealt = CitizenEcho.redeal(theirs, deal);
			if (!Arrays.equals(dealt, theirs) && Arrays.equals(dealt, mine))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * How much of {@code candidate} is not simply {@code donor}'s palette dealt round.
	 *
	 * @return {@code null} if {@code candidate} is not a distinct rotation of
	 * {@code donor} at all; otherwise the rotation with the fewest lifted slots, counted
	 * by <i>which</i> of the two permitted exceptions each one is
	 *
	 * <p><b>Two exceptions, both deliberately narrow, and counted apart.</b> A slot may
	 * not differ from the rotation for any reason a reader has to take on trust — only
	 * for one of these, and only ever <i>away</i> from the thing that is refused:
	 *
	 * <ul>
	 *   <li><b>A face lift.</b> The rotation would land
	 *       {@link CitizenEcho#PLAYER_SKIN_BASE} on a {@code find} the donor did not aim
	 *       at skin, and the candidate paints something that is not the face colour. Six
	 *       records, 2026-08-30, and
	 *       {@link #noRotationOfThoseSixDonorsCouldHaveHeldTheFaceColourInPlace} proves
	 *       each was forced.</li>
	 *   <li><b>A legs lift.</b> The rotation would land a colour inside
	 *       {@link CitizenEcho#isFlesh}'s gamut on the {@link BodySlots#LEGS_BASE} slot,
	 *       and the candidate paints something outside it. Seven records, 2026-08-31, and
	 *       {@link #everyLegsLiftIsOneSlotMovedOffTheFleshGamutAndNothingElse} pins its
	 *       shape.</li>
	 * </ul>
	 *
	 * <p>Counted apart because the two claims are not the same strength. A face lift is
	 * <i>forced</i> — no rotation of those donors could have avoided it. A legs lift is
	 * forced only once in its seven cases, and saying so is the whole point of keeping
	 * the two numbers separate rather than adding them up.
	 */
	private static Lift reDealOf(int[] candidate, int[] donor, int[] find)
	{
		if (candidate.length != donor.length || donor.length < 2 || find.length != donor.length)
		{
			return null;
		}

		short[] mine = shorts(candidate);
		short[] theirs = shorts(donor);
		Lift best = null;

		for (int deal = 1; deal < theirs.length; deal++)
		{
			short[] dealt = CitizenEcho.redeal(theirs, deal);
			if (Arrays.equals(dealt, theirs) || Arrays.equals(mine, theirs))
			{
				// The identity rotation, or a candidate that is its donor's twin.
				continue;
			}

			int face = 0;
			int legs = 0;
			boolean usable = true;
			for (int i = 0; i < dealt.length; i++)
			{
				if (dealt[i] == mine[i])
				{
					continue;
				}

				if ((dealt[i] & 0xFFFF) == CitizenEcho.PLAYER_SKIN_BASE
					&& (find[i] & 0xFFFF) != CitizenEcho.PLAYER_SKIN_BASE
					&& (mine[i] & 0xFFFF) != CitizenEcho.PLAYER_SKIN_BASE)
				{
					face++;
				}
				else if ((find[i] & 0xFFFF) == BodySlots.LEGS_BASE
					&& CitizenEcho.isFlesh(dealt[i])
					&& !CitizenEcho.isFlesh(mine[i]))
				{
					legs++;
				}
				else
				{
					usable = false;
					break;
				}
			}

			if (usable && (best == null || face + legs < best.total()))
			{
				best = new Lift(face, legs);
			}
		}

		return best;
	}

	/**
	 * How many distinct rotations of {@code donor} land nothing where it may not go —
	 * no {@link CitizenEcho#PLAYER_SKIN_BASE} on a {@code find} aimed at anything but
	 * skin, and nothing inside {@link CitizenEcho#isFlesh}'s gamut on the
	 * {@link BodySlots#LEGS_BASE} slot.
	 *
	 * <p>Used only to record, rather than to require, whether a record that took a legs
	 * lift had an untouched rotation available to it instead.
	 */
	private static int cleanRotationsOf(int[] donor, int[] find)
	{
		short[] theirs = shorts(donor);
		TreeSet<String> seen = new TreeSet<>();
		int clean = 0;

		for (int deal = 1; deal < theirs.length; deal++)
		{
			short[] dealt = CitizenEcho.redeal(theirs, deal);
			if (Arrays.equals(dealt, theirs) || !seen.add(Arrays.toString(dealt)))
			{
				continue;
			}

			boolean ok = true;
			for (int i = 0; i < dealt.length && ok; i++)
			{
				ok = !((dealt[i] & 0xFFFF) == CitizenEcho.PLAYER_SKIN_BASE
						&& (find[i] & 0xFFFF) != CitizenEcho.PLAYER_SKIN_BASE)
					&& !((find[i] & 0xFFFF) == BodySlots.LEGS_BASE && CitizenEcho.isFlesh(dealt[i]));
			}

			if (ok)
			{
				clean++;
			}
		}

		return clean;
	}

	/** The two kinds of lifted slot a re-deal may carry, counted apart. @see #reDealOf */
	private static final class Lift
	{
		private final int face;
		private final int legs;

		Lift(int face, int legs)
		{
			this.face = face;
			this.legs = legs;
		}

		int total()
		{
			return face + legs;
		}
	}

	/**
	 * @return whether this dealt palette puts the game's own face colour on a
	 * {@code find} slot the author did not aim at skin
	 */
	private static boolean landsTheFaceColourOnANonSkinSlot(short[] dealt, int[] find)
	{
		for (int i = 0; i < dealt.length; i++)
		{
			if ((dealt[i] & 0xFFFF) == CitizenEcho.PLAYER_SKIN_BASE
				&& (find[i] & 0xFFFF) != CitizenEcho.PLAYER_SKIN_BASE)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The recolour values as the render path sees them.
	 *
	 * <p>{@code EntityDefinition} narrows these to {@code short} because that is what
	 * {@code ModelData#recolor} takes, and several shipped palettes hold values above
	 * {@code Short.MAX_VALUE}. The narrowing is one-to-one over the range the dataset
	 * uses (every value is below 65536), so comparing after it neither merges two
	 * distinct colours nor splits one — and it is the comparison that matches what
	 * actually renders.
	 */
	private static short[] shorts(int[] values)
	{
		short[] out = new short[values.length];
		for (int i = 0; i < values.length; i++)
		{
			out[i] = (short) values[i];
		}
		return out;
	}

	/**
	 * @return every marked record, grouped by the file it ships in, read straight
	 * from the JSON rather than from a validated {@link EntityDefinition} — the
	 * disclosure is about what is written in the files, not about what survived
	 * validation
	 */
	private static TreeMap<Integer, List<String>> ourRecordsByRegion()
	{
		TreeMap<Integer, List<String>> ours = new TreeMap<>();
		for (Record record : shippedRecords())
		{
			if (record.isOurs())
			{
				ours.computeIfAbsent(record.fileRegionId, k -> new ArrayList<>())
					.add(record.name);
			}
		}
		return ours;
	}

	/**
	 * Every record in every shipped region file, both rosters, exactly as authored.
	 *
	 * <p>Read here rather than through {@link ShippedCitizens} or
	 * {@link ShippedModelIds} because this class needs three things neither of them
	 * carries together: the uuid (which roster a record is in is decided by the
	 * marker), the raw {@code modelIds}, and both recolour arrays.
	 */
	private static List<Record> shippedRecords()
	{
		List<Record> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			String resource = RegionDataLoader.DEFAULT_RESOURCE_PREFIX + regionId + ".json";
			InputStream in = AuthoredRecordsTest.class.getClassLoader()
				.getResourceAsStream(resource);
			if (in == null)
			{
				throw new IllegalStateException("missing " + resource);
			}

			try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				JsonObject root = TestGson.injected().fromJson(reader, JsonObject.class);
				collect(root, "citizenRoster", regionId, out);
				collect(root, "sceneryRoster", regionId, out);
			}
			catch (IOException e)
			{
				throw new IllegalStateException("could not read " + resource, e);
			}
		}

		if (out.isEmpty())
		{
			throw new IllegalStateException("no records found in the shipped dataset");
		}

		return out;
	}

	private static void collect(JsonObject root, String rosterKey, int regionId, List<Record> into)
	{
		JsonElement roster = root.get(rosterKey);
		if (roster == null || !roster.isJsonArray())
		{
			return;
		}

		for (JsonElement element : roster.getAsJsonArray())
		{
			if (!element.isJsonObject())
			{
				continue;
			}

			JsonObject record = element.getAsJsonObject();
			into.add(new Record(
				regionId,
				rosterKey,
				string(record, "uuid"),
				string(record, "name"),
				ints(record, "modelIds"),
				ints(record, "modelRecolorFind"),
				ints(record, "modelRecolorReplace")));
		}
	}

	private static String string(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : null;
	}

	private static int[] ints(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		if (value == null || !value.isJsonArray())
		{
			return new int[0];
		}

		JsonArray array = value.getAsJsonArray();
		int[] out = new int[array.size()];
		for (int i = 0; i < array.size(); i++)
		{
			out[i] = array.get(i).getAsInt();
		}
		return out;
	}

	/** One roster record, from either roster, exactly as it is written in the file. */
	private static final class Record
	{
		final int fileRegionId;
		final String rosterKey;
		final String uuid;
		final String name;
		final int[] modelIds;
		final int[] recolorFind;
		final int[] recolorReplace;

		Record(
			int fileRegionId,
			String rosterKey,
			String uuid,
			String name,
			int[] modelIds,
			int[] recolorFind,
			int[] recolorReplace)
		{
			this.fileRegionId = fileRegionId;
			this.rosterKey = rosterKey;
			this.uuid = uuid;
			this.name = name;
			this.modelIds = modelIds;
			this.recolorFind = recolorFind;
			this.recolorReplace = recolorReplace;
		}

		boolean isOurs()
		{
			return uuid != null && uuid.startsWith(MARKER);
		}

		boolean isLiveried()
		{
			return uuid != null && uuid.startsWith(LIVERY_MARKER);
		}

		String describe()
		{
			return "'" + (name == null ? rosterKey : name) + "' in " + fileRegionId + ".json";
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import net.runelite.api.Client;

/**
 * The cache-backed half of the durability tooling: walks every distinct cache id
 * the shipped dataset references — model ids, merged-object ids,
 * {@code npcAppearanceId}s and animation ids — and asks a live {@link Client}
 * whether each one still resolves.
 *
 * <p><b>Why this cannot be a normal test.</b> {@code client.loadModelData(id)},
 * {@code client.getNpcDefinition(id)} and {@code client.loadAnimation(id)} are the
 * only ground truth for whether an id is still valid, and all require a real,
 * cache-loaded client — there is no
 * offline substitute (see {@link CacheIdPlausibility}, which is as far as pure
 * data invariants can go). The only caller of {@link #run} is
 * {@code LivelyCitiesDevReportsPlugin}, which lives in the test source set and is
 * loaded only by {@code ./gradlew auditCacheIds} — and even there only when
 * {@code developerMode} is on <b>and</b> the {@code livelycities.validateCacheIds}
 * system property is set, which {@code ./gradlew test} never does. So this class is
 * never exercised by the normal build, and never reachable at all in a shipped client.
 *
 * <p><b>This class lives in the test source set, with the plugin that calls it.</b>
 * It moved for the second half of the same argument that moved {@link ReportWriter}:
 * the first half was that filesystem I/O in {@code src/main} costs the submission its
 * automated review (riktenx, plugin-hub#12366 and #13208), which taking the file away
 * settled. What it did not settle is that the audit then shipped with no reachable
 * caller at all — three classes of a hub user's jar, counting {@link DatasetIds} and
 * {@link Report}, for a capability nothing in {@code src/main} invokes. "The jar was
 * paying for capabilities its users cannot invoke" is the whole argument, and it
 * applies here whether or not a file is involved.
 *
 * <p><b>{@link FrameTimings} deliberately did not come with it.</b> That one is
 * measured into by {@code EntityScene} on the hot path, so it has a real shipped
 * caller; only its <i>reporting</i> left. This has none — the cache walk is started by
 * {@code LivelyCitiesDevReportsPlugin} and by {@code CacheIdAuditTest}, and by nothing
 * else — which is what makes moving it free rather than a hole in the render path.
 *
 * <p>{@link Report#toReportText()} still produces a {@code String} and stops there;
 * writing it is {@code LivelyCitiesDevReportsPlugin}'s and {@link ReportWriter}'s.
 *
 * <p><b>Everything else here is plain data-in/data-out</b>, and is exercised by
 * {@code CacheIdAuditTest} against {@code FakeClient} — the algorithm that
 * decides what counts as broken is exactly the kind of thing that must not be
 * the untested half.
 */
final class CacheIdAudit
{
	/**
	 * {@code LivelyAnimation.BeeIdle}'s id. {@code client.loadAnimation(0)}
	 * returns null by design in every cache state — the real
	 * {@code loadAnimation} returns null for a sequence with no frame lengths
	 * that is also not a Maya animation, and id 0 is exactly that — not because
	 * of a broken or renumbered cache entry. Reported in its own bucket so a
	 * real regression is never lost inside an expected, permanent null.
	 */
	static final int KNOWN_PERMANENT_NULL_ANIMATION_ID = LivelyAnimation.BeeIdle.getId();

	private CacheIdAudit()
	{
	}

	/**
	 * Walks every region {@link City} claims — which {@code CityTest} keeps
	 * exactly equal to the 27 shipped region files — loading each through
	 * {@code loader} and collecting the ids the render core would actually ask
	 * the client to resolve.
	 *
	 * <p>Deliberately not a classpath directory listing (the way the test-only
	 * {@code ShippedRegions} works): that relies on the resource being an
	 * exploded directory on disk, which is true for a test run but not
	 * guaranteed once the plugin's resources are packed inside a shipped jar.
	 * {@link City} is main-source, already required to name exactly the shipped
	 * regions, and works the same way whether the classpath entry is a directory
	 * or a jar.
	 */
	static DatasetIds collect(RegionDataLoader loader)
	{
		TreeSet<Integer> modelIds = new TreeSet<>();
		TreeSet<Integer> mergedObjectIds = new TreeSet<>();
		TreeSet<Integer> npcAppearanceIds = new TreeSet<>();
		TreeMap<String, Integer> animationIdsByName = new TreeMap<>();
		List<String> regionSummaries = new ArrayList<>();
		int regionsLoaded = 0;

		for (int regionId : shippedRegionIds())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			if (region == null)
			{
				regionSummaries.add("region " + regionId + ": failed to load");
				continue;
			}

			regionsLoaded++;
			TreeSet<Integer> regionModelIds = new TreeSet<>();

			for (EntityDefinition entity : region.getEntities())
			{
				for (int id : entity.getModelIds())
				{
					modelIds.add(id);
					regionModelIds.add(id);
				}

				for (EntityDefinition.MergedObject mergedObject : entity.getMergedObjects())
				{
					mergedObjectIds.add(mergedObject.getObjectId());
				}

				// The whole point of preferring an NPC id to raw model ids is that it
				// is still auditable. An entity dressed this way contributes no model
				// ids at all, so without this line it would be the one part of the
				// dataset the durability tooling could not see.
				if (entity.getNpcAppearanceId() != 0)
				{
					npcAppearanceIds.add(entity.getNpcAppearanceId());
				}

				addIfPresent(entity.getIdleAnimation(), animationIdsByName);
				addIfPresent(entity.getMoveAnimation(), animationIdsByName);
			}

			regionSummaries.add(String.format(
				"region %d: %d entities (%d citizens, %d scenery), %d distinct model id(s)",
				regionId, region.getEntityCount(), region.getCitizenCount(),
				region.getSceneryCount(), regionModelIds.size()));
		}

		return new DatasetIds(modelIds, mergedObjectIds, npcAppearanceIds,
			animationIdsByName, regionSummaries, regionsLoaded);
	}

	private static void addIfPresent(LivelyAnimation animation, Map<String, Integer> into)
	{
		if (animation != null)
		{
			into.put(animation.name(), animation.getId());
		}
	}

	/**
	 * @return every region id any {@link City} claims — the same 27 the dataset
	 * ships, per {@code CityTest.everyShippedRegionBelongsToExactlyOneCity}
	 */
	static Set<Integer> shippedRegionIds()
	{
		TreeSet<Integer> ids = new TreeSet<>();
		for (City city : City.values())
		{
			for (int id : city.getRegionIds())
			{
				ids.add(id);
			}
		}
		return ids;
	}

	/**
	 * Asks {@code client} about every id in {@code dataset} and buckets the
	 * results. Never throws: a client call that blows up is recorded as a
	 * failure for that one id rather than aborting the rest of the walk — the
	 * same fail-soft principle {@link EntityDefinition} applies to parsing
	 * applies here to validation, and for the same reason: one bad id must not
	 * hide the report on every other one.
	 */
	static Report run(Client client, DatasetIds dataset)
	{
		List<Integer> failingModelIds = new ArrayList<>();
		for (int id : dataset.modelIds)
		{
			if (!resolvesAsModel(client, id))
			{
				failingModelIds.add(id);
			}
		}

		List<Integer> failingMergedObjectIds = new ArrayList<>();
		for (int id : dataset.mergedObjectIds)
		{
			if (!resolvesAsModel(client, id))
			{
				failingMergedObjectIds.add(id);
			}
		}

		List<Integer> failingNpcAppearanceIds = new ArrayList<>();
		for (int id : dataset.npcAppearanceIds)
		{
			if (!resolvesAsNpcAppearance(client, id))
			{
				failingNpcAppearanceIds.add(id);
			}
		}

		List<String> failingAnimations = new ArrayList<>();
		List<String> knownPermanentNullAnimations = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : dataset.animationIdsByName.entrySet())
		{
			if (!resolvesAsAnimation(client, entry.getValue()))
			{
				String label = entry.getKey() + "=" + entry.getValue();
				if (entry.getValue() == KNOWN_PERMANENT_NULL_ANIMATION_ID)
				{
					knownPermanentNullAnimations.add(label);
				}
				else
				{
					failingAnimations.add(label);
				}
			}
		}

		return new Report(dataset, failingModelIds, failingMergedObjectIds, failingNpcAppearanceIds,
			failingAnimations, knownPermanentNullAnimations);
	}

	private static boolean resolvesAsModel(Client client, int id)
	{
		try
		{
			return client.loadModelData(id) != null;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/**
	 * Asks the same question {@link NpcAppearance#resolve} asks, through the same
	 * class, so the audit and the render core can never disagree about what "this
	 * NPC id still works" means.
	 *
	 * <p>Going through {@code resolve} rather than calling {@code getNpcDefinition}
	 * here is the point: an id that resolves to a composition with <i>no models</i>
	 * renders nothing, so an audit that only checked the lookup would report a green
	 * id for an invisible citizen. The label is the audit's own, not an entity's —
	 * the same NPC id can be shared by several records.
	 */
	private static boolean resolvesAsNpcAppearance(Client client, int id)
	{
		try
		{
			return NpcAppearance.resolve(client, id, "cache id audit") != null;
		}
		catch (RuntimeException e)
		{
			// resolve() already contains its own throws; this is the backstop for
			// anything thrown on the way in, on the same terms as the two above.
			return false;
		}
	}

	private static boolean resolvesAsAnimation(Client client, int id)
	{
		try
		{
			return client.loadAnimation(id) != null;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/** Every cache id the dataset references, gathered without touching a client. */
	static final class DatasetIds
	{
		final Set<Integer> modelIds;
		final Set<Integer> mergedObjectIds;

		/**
		 * Every distinct {@code npcAppearanceId} the dataset references — the ids
		 * whose compositions supply a body instead of a {@code modelIds} array.
		 */
		final Set<Integer> npcAppearanceIds;

		final Map<String, Integer> animationIdsByName;
		final List<String> regionSummaries;
		final int regionsLoaded;

		DatasetIds(
			Set<Integer> modelIds,
			Set<Integer> mergedObjectIds,
			Set<Integer> npcAppearanceIds,
			Map<String, Integer> animationIdsByName,
			List<String> regionSummaries,
			int regionsLoaded)
		{
			this.modelIds = Collections.unmodifiableSet(modelIds);
			this.mergedObjectIds = Collections.unmodifiableSet(mergedObjectIds);
			this.npcAppearanceIds = Collections.unmodifiableSet(npcAppearanceIds);
			this.animationIdsByName = Collections.unmodifiableMap(animationIdsByName);
			this.regionSummaries = Collections.unmodifiableList(regionSummaries);
			this.regionsLoaded = regionsLoaded;
		}
	}

	/** The result of one validation pass, and the diffable text form of it. */
	static final class Report
	{
		final DatasetIds dataset;
		final List<Integer> failingModelIds;
		final List<Integer> failingMergedObjectIds;
		final List<Integer> failingNpcAppearanceIds;
		final List<String> failingAnimations;
		final List<String> knownPermanentNullAnimations;

		Report(
			DatasetIds dataset,
			List<Integer> failingModelIds,
			List<Integer> failingMergedObjectIds,
			List<Integer> failingNpcAppearanceIds,
			List<String> failingAnimations,
			List<String> knownPermanentNullAnimations)
		{
			this.dataset = dataset;
			this.failingModelIds = Collections.unmodifiableList(failingModelIds);
			this.failingMergedObjectIds = Collections.unmodifiableList(failingMergedObjectIds);
			this.failingNpcAppearanceIds = Collections.unmodifiableList(failingNpcAppearanceIds);
			this.failingAnimations = Collections.unmodifiableList(failingAnimations);
			this.knownPermanentNullAnimations = Collections.unmodifiableList(knownPermanentNullAnimations);
		}

		boolean hasUnexpectedFailures()
		{
			return !failingModelIds.isEmpty()
				|| !failingMergedObjectIds.isEmpty()
				|| !failingNpcAppearanceIds.isEmpty()
				|| !failingAnimations.isEmpty();
		}

		/**
		 * A stable, sorted, plain-text report — every list here is already sorted
		 * by its collection type ({@link TreeSet}/{@link TreeMap}), so two runs
		 * against the same dataset produce byte-identical text and a real
		 * regression shows up as a small, reviewable diff rather than a reordered
		 * wall of ids.
		 */
		String toReportText()
		{
			StringBuilder sb = new StringBuilder();
			sb.append("# Lively Cities cache id audit\n");
			sb.append("# model ids checked: ").append(dataset.modelIds.size()).append('\n');
			sb.append("# model ids failing: ").append(failingModelIds.size()).append('\n');
			for (int id : failingModelIds)
			{
				sb.append(id).append('\n');
			}
			sb.append('\n');

			sb.append("# merged-object ids checked: ").append(dataset.mergedObjectIds.size()).append('\n');
			sb.append("# merged-object ids failing: ").append(failingMergedObjectIds.size()).append('\n');
			for (int id : failingMergedObjectIds)
			{
				sb.append(id).append('\n');
			}
			sb.append('\n');

			sb.append("# npc appearance ids checked: ").append(dataset.npcAppearanceIds.size()).append('\n');
			sb.append("# npc appearance ids failing: ").append(failingNpcAppearanceIds.size()).append('\n');
			for (int id : failingNpcAppearanceIds)
			{
				sb.append(id).append('\n');
			}
			sb.append('\n');

			sb.append("# animation ids checked: ").append(dataset.animationIdsByName.size()).append('\n');
			sb.append("# animation ids failing: ").append(failingAnimations.size()).append('\n');
			for (String failure : failingAnimations)
			{
				sb.append(failure).append('\n');
			}
			sb.append('\n');

			sb.append("# known-permanent-null (expected, not a failure): ")
				.append(knownPermanentNullAnimations.size()).append('\n');
			for (String known : knownPermanentNullAnimations)
			{
				sb.append(known).append('\n');
			}
			sb.append('\n');

			sb.append("# regions loaded: ").append(dataset.regionsLoaded).append('\n');
			for (String summary : dataset.regionSummaries)
			{
				sb.append("# ").append(summary).append('\n');
			}

			return sb.toString();
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The part of the durability tooling that can be tested without a real client:
 * given a client's answers, does {@link CacheIdAudit} bucket them correctly?
 * {@link FakeClient} stands in for the client — {@code setUnloadable} /
 * {@code setThrowing} / {@code setUnloadableAnimations} are exactly the
 * fixtures {@code LivelyEntityTest} already uses for the same client contract,
 * reused here rather than re-invented.
 *
 * <p>What this file does <b>not</b> claim: that any of these ids resolve against
 * the <i>real</i> game cache. That question belongs to
 * {@code ./gradlew auditCacheIds} against a live client, which is exactly why
 * {@link CacheIdAudit} takes a {@code Client} rather than owning one.
 */
public class CacheIdAuditTest
{
	// --- collect(): the no-client half, against the real shipped dataset -----

	/**
	 * Cross-checks {@link CacheIdAudit#collect} against
	 * {@link ShippedModelIds#distinct()} — two independent readings of the same
	 * dataset, one through {@link EntityDefinition} (validated, what the render
	 * core actually uses) and one straight off the raw JSON
	 * ({@link ModelIdAuditTest} pins the raw one at 324). They have to agree,
	 * because the shipped dataset has zero skipped records and zero non-positive
	 * ids — if they ever disagree, either a record started being skipped or a
	 * non-positive id crept into the corpus, and this is what would notice
	 * either one.
	 */
	@Test
	public void collectsExactlyTheDistinctModelIdsTheOfflineAuditSees()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CacheIdAudit.DatasetIds dataset = CacheIdAudit.collect(loader);

		assertEquals("every City-claimed region has to load", 27, dataset.regionsLoaded);
		assertEquals("collect() must see exactly the raw dataset's distinct model ids",
			ShippedModelIds.distinct(), dataset.modelIds);
		assertEquals(324, dataset.modelIds.size());
	}

	/**
	 * The one merged object in the shipped dataset (object id 7719, see
	 * {@code RegionDataLoaderTest}'s fixture for the equivalent test-data shape)
	 * has to turn up as a distinct id of its own, not folded into the model ids.
	 */
	@Test
	public void collectsMergedObjectIdsSeparatelyFromModelIds()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CacheIdAudit.DatasetIds dataset = CacheIdAudit.collect(loader);

		assertFalse("the shipped dataset has at least one mergedObjects entry",
			dataset.mergedObjectIds.isEmpty());
		// Disjoint, not !containsAll — see the npcAppearanceId assertion below for why.
		// With one merged-object id in the dataset the two spellings happen to agree
		// today; with two they would not, and the message would be the thing that lied.
		assertTrue("a merged-object id must not also be counted as a model id; overlapping: "
				+ overlap(dataset.modelIds, dataset.mergedObjectIds),
			Collections.disjoint(dataset.modelIds, dataset.mergedObjectIds));
	}

	/**
	 * The other half of the appearance surface: the {@code npcAppearanceId}s.
	 *
	 * <p>This is the whole justification for preferring an NPC id to a raw model id.
	 * An entity dressed from a composition contributes <b>no</b> model ids at all, so
	 * without this bucket the seven entities dressed that way would be the one part of
	 * the dataset the durability tooling could not see — and "we chose the more
	 * auditable mechanism" would be a claim rather than a fact.
	 *
	 * <p>Cross-checked against {@link ShippedModelIds#distinctNpcAppearanceIds()},
	 * which reads the raw JSON, exactly as the model ids are.
	 */
	@Test
	public void collectsEveryNpcAppearanceIdTheDatasetReferences()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CacheIdAudit.DatasetIds dataset = CacheIdAudit.collect(loader);

		assertEquals("collect() must see exactly the raw dataset's npcAppearanceIds",
			ShippedModelIds.distinctNpcAppearanceIds(), dataset.npcAppearanceIds);
		assertEquals("the six cameos' NPC ids plus the one \"Rufus\" wears", 7,
			dataset.npcAppearanceIds.size());
		// Collections.disjoint, not containsAll: the message claims a property of every
		// element, and containsAll() only says "not all of them" — one stray id landing
		// in modelIds would have gone on passing as long as a second one did not.
		assertTrue("an NPC id is not a model id and must not be counted as one; overlapping: "
				+ overlap(dataset.modelIds, dataset.npcAppearanceIds),
			Collections.disjoint(dataset.modelIds, dataset.npcAppearanceIds));
	}

	/**
	 * Every idle/move animation the render core resolves has to appear here by
	 * name, matching {@code LivelyAnimationTest}'s independently-pinned count of
	 * 72 distinct names.
	 */
	@Test
	public void collectsEveryResolvedAnimationNameUsedByTheDataset()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CacheIdAudit.DatasetIds dataset = CacheIdAudit.collect(loader);

		assertEquals(72, dataset.animationIdsByName.size());
		assertTrue("BeeIdle is used by the dataset and must be one of the collected names",
			dataset.animationIdsByName.containsKey("BeeIdle"));
		assertEquals(0, (int) dataset.animationIdsByName.get("BeeIdle"));
	}

	// --- run(): bucketing a client's answers ----------------------------------

	@Test
	public void everyIdThatResolvesProducesNoFailures()
	{
		FakeClient client = new FakeClient();
		CacheIdAudit.DatasetIds dataset = dataset(
			ids(100, 200, 300),
			ids(7719),
			animations("HumanIdle", 808, "HumanWalk", 819));

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertTrue(report.failingModelIds.isEmpty());
		assertTrue(report.failingMergedObjectIds.isEmpty());
		assertTrue(report.failingAnimations.isEmpty());
		assertTrue(report.knownPermanentNullAnimations.isEmpty());
		assertFalse(report.hasUnexpectedFailures());
	}

	@Test
	public void modelIdsThatDoNotResolveAreReportedAsFailing()
	{
		FakeClient client = new FakeClient();
		client.setUnloadable(200, 400);

		CacheIdAudit.DatasetIds dataset = dataset(
			ids(100, 200, 300, 400),
			ids(),
			animations());

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertEquals(Arrays.asList(200, 400), report.failingModelIds);
		assertTrue(report.hasUnexpectedFailures());
	}

	/**
	 * Merged-object ids go through {@code loadModelData} too (see
	 * {@code LivelyEntity.loadParts}), so a failure there must land in its own
	 * bucket rather than being silently merged into — or lost among — the plain
	 * model id failures.
	 */
	@Test
	public void mergedObjectIdsThatDoNotResolveAreReportedInTheirOwnBucket()
	{
		FakeClient client = new FakeClient();
		client.setUnloadable(7719);

		CacheIdAudit.DatasetIds dataset = dataset(
			ids(100),
			ids(7719),
			animations());

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertTrue("a merged-object failure must not appear as a model id failure",
			report.failingModelIds.isEmpty());
		assertEquals(Collections.singletonList(7719), report.failingMergedObjectIds);
	}

	/**
	 * {@code LivelyAnimation.BeeIdle} is id 0, and {@code client.loadAnimation(0)}
	 * returns null by design, always — a real regression on another animation
	 * must not be swallowed by that expected null, and the expected null must not
	 * be reported as though it were one.
	 */
	@Test
	public void theKnownPermanentNullAnimationIsSeparatedFromRealFailures()
	{
		FakeClient client = new FakeClient();
		client.setUnloadableAnimations(0, 6539); // BeeIdle, and WerewolfIdle failing for real

		CacheIdAudit.DatasetIds dataset = dataset(
			ids(),
			ids(),
			animations("BeeIdle", 0, "WerewolfIdle", 6539, "HumanIdle", 808));

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertEquals(Collections.singletonList("WerewolfIdle=6539"), report.failingAnimations);
		assertEquals(Collections.singletonList("BeeIdle=0"), report.knownPermanentNullAnimations);
		assertTrue("a permanent, expected null alone must not count as an unexpected failure — "
				+ "only WerewolfIdle should trip this",
			report.hasUnexpectedFailures());
	}

	/**
	 * Isolates the claim above from
	 * {@link #theKnownPermanentNullAnimationIsSeparatedFromRealFailures}: with
	 * <b>only</b> the known-permanent-null id failing, the report must not read
	 * as a failure at all.
	 */
	@Test
	public void onlyTheKnownPermanentNullFailingIsNotAnUnexpectedFailure()
	{
		FakeClient client = new FakeClient();
		client.setUnloadableAnimations(0);

		CacheIdAudit.DatasetIds dataset = dataset(ids(), ids(), animations("BeeIdle", 0));

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertTrue(report.failingAnimations.isEmpty());
		assertEquals(Collections.singletonList("BeeIdle=0"), report.knownPermanentNullAnimations);
		assertFalse("only the expected null failed, so this must not read as a real problem",
			report.hasUnexpectedFailures());
	}

	/**
	 * A client call that throws — a real possibility; {@code FakeClient} models
	 * it because {@code LivelyEntityTest} needs it too — must count as that one
	 * id failing, not abort the walk. Proven by checking every other id was still
	 * asked about.
	 */
	@Test
	public void aClientCallThatThrowsIsTreatedAsFailingWithoutAbortingTheWalk()
	{
		FakeClient client = new FakeClient();
		client.setThrowing(200);

		CacheIdAudit.DatasetIds dataset = dataset(ids(100, 200, 300), ids(), animations());

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertEquals(Collections.singletonList(200), report.failingModelIds);
		assertEquals("the throw on 200 must not have stopped 300 from being asked about",
			3, client.loadModelDataCalls());
	}

	/**
	 * An NPC id whose composition is gone lands in its own bucket, and counts as a
	 * real failure — that is what makes a renumbered NPC id after a game update
	 * visible in the report instead of as six invisible citizens.
	 */
	@Test
	public void npcAppearanceIdsThatDoNotResolveAreReportedInTheirOwnBucket()
	{
		FakeClient client = new FakeClient();
		// 1798 resolves; 4214 is not registered, so FakeClient throws for it exactly
		// as the real client does for a missing archive entry.
		client.withNpc(1798, FakeNpcComposition.of("White Knight", 217, 305));

		CacheIdAudit.DatasetIds dataset = dataset(
			ids(100), ids(), ids(1798, 4214), animations());

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		assertEquals(Collections.singletonList(4214), report.failingNpcAppearanceIds);
		assertTrue("an NPC id failure must not appear as a model id failure",
			report.failingModelIds.isEmpty());
		assertTrue(report.hasUnexpectedFailures());
	}

	/**
	 * An NPC id that resolves to a composition with <b>no models</b> is a failure
	 * too, and this is the case a naive audit would miss: the lookup succeeded, so
	 * "does {@code getNpcDefinition} return something?" is green while the citizen is
	 * invisible. Going through {@link NpcAppearance} is what makes the audit ask the
	 * same question the renderer asks.
	 */
	@Test
	public void anNpcIdThatResolvesToNothingDrawableCountsAsFailing()
	{
		FakeClient client = new FakeClient();
		client.withNpc(1798, FakeNpcComposition.withoutModels("Bodyless", new int[0]));

		CacheIdAudit.Report report = CacheIdAudit.run(
			client, dataset(ids(), ids(), ids(1798), animations()));

		assertEquals("a lookup that works but draws nothing is still broken",
			Collections.singletonList(1798), report.failingNpcAppearanceIds);
		assertTrue(report.hasUnexpectedFailures());
	}

	/** Nothing failing anywhere, with all four buckets populated. */
	@Test
	public void everyKindOfIdResolvingProducesACleanReport()
	{
		FakeClient client = new FakeClient();
		client.withNpc(1798, FakeNpcComposition.of("White Knight", 217));

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset(
			ids(100, 200), ids(7719), ids(1798), animations("HumanIdle", 808)));

		assertTrue(report.failingModelIds.isEmpty());
		assertTrue(report.failingMergedObjectIds.isEmpty());
		assertTrue(report.failingNpcAppearanceIds.isEmpty());
		assertTrue(report.failingAnimations.isEmpty());
		assertFalse(report.hasUnexpectedFailures());
	}

	// --- the report text ------------------------------------------------------

	@Test
	public void theReportTextIsSortedAndCarriesTheCounts()
	{
		FakeClient client = new FakeClient();
		client.setUnloadable(500, 100);
		client.setUnloadableAnimations(0);

		CacheIdAudit.DatasetIds dataset = dataset(
			ids(100, 500, 900),
			ids(),
			animations("BeeIdle", 0, "HumanIdle", 808));

		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);
		String text = report.toReportText();

		assertTrue(text.contains("model ids checked: 3"));
		assertTrue(text.contains("model ids failing: 2"));
		// Sorted ascending — a TreeSet under the hood — not authoring order (500
		// before 100) and not call order.
		assertTrue("expected ascending order 100 then 500, got:\n" + text,
			text.indexOf("\n100\n") < text.indexOf("\n500\n"));
		assertTrue(text.contains("known-permanent-null (expected, not a failure): 1"));
		assertTrue(text.contains("BeeIdle=0"));
	}

	/**
	 * The NPC appearance section has to be in the text, or a failing id would be
	 * counted by {@code hasUnexpectedFailures()} and then invisible in the file a
	 * human actually reads.
	 */
	@Test
	public void theReportTextCarriesTheNpcAppearanceSection()
	{
		FakeClient client = new FakeClient();
		client.withNpc(1798, FakeNpcComposition.of("White Knight", 217));

		CacheIdAudit.Report report = CacheIdAudit.run(
			client, dataset(ids(), ids(), ids(512, 1798), animations()));
		String text = report.toReportText();

		assertTrue(text, text.contains("npc appearance ids checked: 2"));
		assertTrue(text, text.contains("npc appearance ids failing: 1"));
		assertTrue("the failing id itself has to be listed", text.contains("\n512\n"));
	}

	@Test
	public void runningTheSameDatasetAndAnswersTwiceProducesByteIdenticalText()
	{
		FakeClient client = new FakeClient();
		client.setUnloadable(500, 100, 900);

		CacheIdAudit.DatasetIds dataset = dataset(ids(100, 500, 900), ids(), animations());

		String first = CacheIdAudit.run(client, dataset).toReportText();
		String second = CacheIdAudit.run(client, dataset).toReportText();

		assertEquals("a diffable report has to be stable across identical runs, or a real "
				+ "regression would be indistinguishable from run-to-run noise",
			first, second);
	}

	// --- fixtures --------------------------------------------------------------

	private static Set<Integer> ids(int... values)
	{
		Set<Integer> set = new LinkedHashSet<>();
		for (int v : values)
		{
			set.add(v);
		}
		return set;
	}

	private static TreeMap<String, Integer> animations(Object... namesThenIds)
	{
		TreeMap<String, Integer> map = new TreeMap<>();
		for (int i = 0; i < namesThenIds.length; i += 2)
		{
			map.put((String) namesThenIds[i], (Integer) namesThenIds[i + 1]);
		}
		return map;
	}

	/** What the two sets have in common, so a failure names the ids rather than the sets. */
	private static Set<Integer> overlap(Set<Integer> left, Set<Integer> right)
	{
		Set<Integer> both = new TreeSet<>(left);
		both.retainAll(right);
		return both;
	}

	private static CacheIdAudit.DatasetIds dataset(
		Set<Integer> modelIds, Set<Integer> mergedObjectIds, TreeMap<String, Integer> animationIdsByName)
	{
		return dataset(modelIds, mergedObjectIds, ids(), animationIdsByName);
	}

	private static CacheIdAudit.DatasetIds dataset(
		Set<Integer> modelIds,
		Set<Integer> mergedObjectIds,
		Set<Integer> npcAppearanceIds,
		TreeMap<String, Integer> animationIdsByName)
	{
		List<String> summaries = Collections.emptyList();
		return new CacheIdAudit.DatasetIds(
			new TreeSet<>(modelIds), new TreeSet<>(mergedObjectIds), new TreeSet<>(npcAppearanceIds),
			animationIdsByName, summaries, 0);
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The six cameos as authored content: who they are, where they stand, what they
 * wear, which way they face, and the promises the record text makes.
 *
 * <h2>Why any of this is a test rather than a comment</h2>
 *
 * <p>These six are the only player-shaped named humans in the dataset, they stand
 * in the most player-dense location in the game, and the predecessor plugin's own
 * content rule — adopted verbatim into this project's — is <i>"we do not add 'fake
 * players'"</i>. Every property this file pins is one that, if it drifted, would
 * turn six affectionate in-jokes into exactly the thing that rule forbids: the
 * opt-in default, the theme that confines them to one city, the honesty of the
 * examine text, and the fact that nothing derives more of them.
 *
 * <h2>The tiles, and how confident this is about them</h2>
 *
 * <p><b>Not very, and the code is arranged so that it does not have to be.</b> The
 * six tiles were chosen off the Grand Exchange's wiki map (centre {@code (3165,
 * 3490)}), north-west of that centre and out of the trade lane, in an arc. Nobody
 * has stood on them in game. Authored entities get no collision validation in this
 * plugin — only echoes do — so the mitigation is twofold and both halves are
 * deliberate:
 *
 * <ol>
 *   <li>{@code EntityScene.groundIsUsable} makes a cameo's tile pass
 *       {@link StandableGround} before it may spawn, on stricter terms than an echo:
 *       {@code UNKNOWN} is refused, because unlike an echo a cameo has no authored
 *       wander box to fall back to. A cameo on a bank booth therefore does not
 *       render at all, rather than rendering inside the booth.</li>
 *   <li>The arc sits in the same region and within a handful of tiles of the three
 *       vendored entities that were placed by hand and are known to work —
 *       "Richard" at {@code (3169, 3489)} and the brazier at {@code (3169, 3488)}
 *       — so it is at least inside the same courtyard rather than somewhere derived
 *       from arithmetic alone.</li>
 * </ol>
 *
 * <p><b>They still need an in-game eyeball.</b> If any of the six turns out to be
 * standing in a wall, the collision gate will have hidden it and the fix is a tile
 * edit in {@code 12598.json} plus the matching constant in this file. That is the
 * honest state of it: this test pins what was intended, not that the intention was
 * right about the floor.
 */
public class CameoPlacementTest
{
	/** The Grand Exchange, per {@code City.GRAND_EXCHANGE}. */
	private static final int GRAND_EXCHANGE_REGION = 12598;

	/** The GE's wiki map centre — what "north-west side" is measured from. */
	private static final WorldPoint GE_CENTRE = new WorldPoint(3165, 3490, 0);

	/**
	 * The closest two cameos may stand: two tiles, Chebyshev — the same figure
	 * {@link CitizenEcho#MIN_SEPARATION_TILES} uses, and for the same reason. Citizen
	 * models are roughly a tile wide, so two on adjacent tiles interpenetrate and
	 * read as one clipped body. A group posing together has to read as six people.
	 *
	 * <p>Note this is a rule about <i>these six</i> and not about authored content in
	 * general: 42 pairs of vendored entities are closer than this to each other and
	 * that is fine, because a human put them there on purpose. Nobody has looked at
	 * these, so they get held to the derived-content standard.
	 */
	private static final int MIN_SEPARATION_TILES = 2;

	/**
	 * The six, exactly as they should appear in {@code 12598.json}.
	 *
	 * <p>Written out here rather than read from the file and compared to itself: a
	 * test that derived its expectations from the data would pass for any data. The
	 * NPC ids are the load-bearing half — every one was confirmed against
	 * {@code javap -p -constants net.runelite.api.gameval.NpcID} on the 1.12.36 jar,
	 * and the name in the comment is the constant's own.
	 *
	 * <h2>The pose rule, learned the hard way</h2>
	 *
	 * <p>These figures never move, so every one of them gets a <b>pose</b> and never an
	 * <b>action</b>. An action animation was authored around the item it uses:
	 * {@code Alching} assumes a staff, {@code Fishing} assumes a rod. Give it to a
	 * figure whose composition has no such model and it plays as a mime — bent double
	 * at the waist with the hands working at nothing, which is exactly how two of these
