	// --- Identity ------------------------------------------------------------

	/**
	 * The dataset holds exactly these six cameos, with exactly these bodies, poses
	 * and facings.
	 */
	@Test
	public void theSixCameosAreAuthoredExactlyAsIntended()
	{
		List<EntityDefinition> cameos = shippedCameos();
		assertEquals("the number of cameos in the dataset", EXPECTED.length, cameos.size());

		for (Cameo expected : EXPECTED)
		{
			EntityDefinition actual = byName(cameos, expected.name);
			assertNotNull("no cameo named " + expected.name, actual);

			assertEquals(expected.name + " uuid", expected.uuid, actual.getUuid().toString());
			assertEquals(expected.name + " x", expected.x, actual.getWorldLocation().getX());
			assertEquals(expected.name + " y", expected.y, actual.getWorldLocation().getY());
			assertEquals(expected.name + " plane", 0, actual.getWorldLocation().getPlane());
			assertEquals(expected.name + " npcAppearanceId", expected.npcId, actual.getNpcAppearanceId());
			assertEquals(expected.name + " orientation", expected.orientation, actual.getOrientation());
			assertNotNull(expected.name + " idle animation", actual.getIdleAnimation());
			assertEquals(expected.name + " idle animation",
				expected.animation, actual.getIdleAnimation().name());

			assertEquals(expected.name + " is a StationaryCitizen",
				EntityType.StationaryCitizen, actual.getType());
			assertNull(expected.name + " must have no wander box — they are posing, not pacing",
				actual.getWanderBox());
			assertNull(expected.name + " must not have a move animation", actual.getMoveAnimation());
			assertEquals(expected.name + " is dressed from an NPC, so it carries no raw model ids",
				0, actual.getModelIds().length);
			assertTrue(expected.name + " must be flagged as a cameo", actual.isCameo());
			assertFalse(expected.name + " is authored, not derived", actual.isEcho());
		}
	}

	/**
	 * Six distinct people wearing six distinct bodies.
	 *
	 * <p>A copy-paste that gave two cameos the same NPC id would produce visual twins
	 * standing two tiles apart — the single most recognisable "this is a plugin, and a
	 * lazy one" tell, and the thing {@link CitizenEcho}'s whole palette re-deal exists
	 * to avoid for derived citizens.
	 */
	@Test
	public void everyCameoHasItsOwnNameUuidBodyAndFacing()
	{
		Set<String> names = new HashSet<>();
		Set<String> uuids = new HashSet<>();
		Set<Integer> npcIds = new HashSet<>();
		Set<Integer> orientations = new HashSet<>();

		for (EntityDefinition cameo : shippedCameos())
		{
			assertTrue("duplicate cameo name: " + cameo.getName(), names.add(cameo.getName()));
			assertTrue("duplicate cameo uuid: " + cameo.getUuid(), uuids.add(cameo.getUuid().toString()));
			assertTrue("two cameos share NPC body " + cameo.getNpcAppearanceId()
				+ " — they would be visual twins", npcIds.add(cameo.getNpcAppearanceId()));
			assertTrue("two cameos share orientation " + cameo.getOrientation()
				+ " — a posed group is not a rank", orientations.add(cameo.getOrientation()));
		}

		assertEquals(EXPECTED.length, names.size());
	}

	/**
	 * Every pose these six may stand in, and nothing else.
	 *
	 * <p>An allowlist rather than a denylist of actions, because the failure being
	 * guarded against is somebody reaching for whichever animation sounds most like
	 * the character — which is how Cazh got a high-alchemy cast and Gunnar got a rod
	 * cast. Adding a row here means adding the matching row to {@link #POSE_EVIDENCE},
	 * which is where the checking now has to be written down rather than asserted.
	 */
	private static final Set<LivelyAnimation> VERIFIED_POSES = EnumSet.of(
		LivelyAnimation.HumanIdle,
		LivelyAnimation.HumanLeanReady,
		LivelyAnimation.NervousIdle,
		LivelyAnimation.MageReady,
		LivelyAnimation.ArmsCrossedReady,
		LivelyAnimation.HumanSmugIdle
	);

	/**
	 * Why each row above was admitted, transcribed from the 1.12.36 cache.
	 *
	 * <p>The project's admission rule is "the gameval name ends in {@code _READY} or
	 * {@code _IDLE}, <b>or</b> the game itself installs the id as some NPC's standing
	 * animation". Both halves are cache facts, so the rule can be executed rather than
	 * recited — and it is, below. That turns "adding a row means having checked it" from
	 * an instruction in a comment into a row somebody has to write and a build that goes
	 * red if the row does not carry the property.
	 *
	 * <p>Only the two halves of the rule are recorded, not a general opinion: the count
	 * is how many NPC definitions in the cache name this id as their {@code stand}, and
	 * the name is the {@code gameval.AnimationID} constant.
	 */
	private static final Map<LivelyAnimation, PoseEvidence> POSE_EVIDENCE = poseEvidence();

	private static Map<LivelyAnimation, PoseEvidence> poseEvidence()
	{
		Map<LivelyAnimation, PoseEvidence> evidence = new EnumMap<>(LivelyAnimation.class);

		// Every ordinary human in the game, 5072 of them, starting with NpcID 13 "Piles".
		evidence.put(LivelyAnimation.HumanIdle, new PoseEvidence(808, "HUMAN_READY", 5072));

		// NpcID 14209 "Antos" and 14215 "Injured boy".
		evidence.put(LivelyAnimation.HumanLeanReady, new PoseEvidence(916, "HUMAN_LEAN_READY", 2));

		// NpcID 12667 "Bandit".
		evidence.put(LivelyAnimation.NervousIdle, new PoseEvidence(10680, "NERVOUS_IDLE", 1));

		// NpcID 3592 "'Transmute' The Alchemist", 3594 "'Currency' The Alchemist", 6157,
		// 6158. The name is the reason this row needs the second half of the rule: it
		// ends in "01", not in "_READY".
		evidence.put(LivelyAnimation.MageReady, new PoseEvidence(5823, "TOL_MAGE_READY01", 4));

		// NpcID 4680 "Lady Table", 4685 "Miss Cheevers", 4931 "Savant", 7377 "Captain
		// Kalt" and 7987 "Lord Marshal Brogan" — which is Peter's own body.
		evidence.put(LivelyAnimation.ArmsCrossedReady,
			new PoseEvidence(2256, "RD_KNIGHT_CROSSED_ARMS", 5));

		// No NPC stands on this one; it is admitted on its name alone.
		evidence.put(LivelyAnimation.HumanSmugIdle, new PoseEvidence(14000, "HUMAN_SMUG_IDLE", 0));

		return Collections.unmodifiableMap(evidence);
	}

	/**
	 * A posed figure gets a pose, never an action.
	 *
	 * <p>Three things, and they are different mistakes. First, every cameo's animation
	 * is on the verified list. Second, every entry on that list carries its evidence and
	 * that evidence satisfies the admission rule — so the list cannot be widened by
	 * adding a name, only by writing down a claim about the cache that is checkable.
	 * Third, the rule itself still rejects the animation that started all this.
	 *
	 * <p><b>And one thing it honestly does not do.</b> The second half of the admission
	 * rule would let {@code Fishing} back in: {@code HUMAN_FISHING_CASTING} really is the
	 * {@code stand} of NpcID 11225 "D3ad1i F15her", a joke NPC posed permanently
	 * mid-cast — with a rod in its composition. That is the whole point and the whole
	 * limit at once: the animation was never the defect, the missing rod was, and no
	 * offline check can ask a composition whether it holds one. What keeps it out is the
	 * allowlist, which is why the allowlist is the primary rule and not a formality.
	 */
	@Test
	public void everyCameoIsPosedRatherThanMidAction()
	{
		for (EntityDefinition cameo : shippedCameos())
		{
			LivelyAnimation pose = cameo.getIdleAnimation();
			assertNotNull(cameo.getName() + " has no animation at all", pose);
			assertTrue(cameo.getName() + " is posed with " + pose + ", which is not on the verified "
					+ "pose list — an action animation without the item it was authored around "
					+ "plays as a mime",
				VERIFIED_POSES.contains(pose));
		}

		assertEquals("every verified pose needs its evidence row and nothing else may have one",
			VERIFIED_POSES, POSE_EVIDENCE.keySet());

		for (LivelyAnimation pose : VERIFIED_POSES)
		{
			PoseEvidence evidence = POSE_EVIDENCE.get(pose);
			assertEquals(pose + "'s recorded id has to be the id the enum actually carries",
				pose.getId(), evidence.animationId);
			assertTrue(pose + " is on the verified list but its evidence does not admit it: "
					+ evidence, evidence.isAPose());
		}

		assertFalse("the rule has to still reject the animation it was written after: Alching is "
				+ "HUMAN_CASTHIGHLVLALCHEMY, it is a cast that assumes a staff, and no NPC in the "
				+ "cache stands on it",
			new PoseEvidence(713, "HUMAN_CASTHIGHLVLALCHEMY", 0).isAPose());

		assertTrue("and the rule's known limit, stated rather than papered over: Fishing is "
				+ "admissible by the letter of it, and only the allowlist keeps it out",
			new PoseEvidence(622, "HUMAN_FISHING_CASTING", 1).isAPose());
	}

	/**
	 * A pose has to drive the skeleton of the body it is worn on.
	 *
	 * <p>This is the assertion that was missing, and its absence is not theoretical:
	 * "Sludgellama" stood at the Grand Exchange on {@code LectorIdle}, framemap 1304,
	 * wearing NpcID 526 "Rogue", framemap 0. It survived because {@code AnimationSkeletonTest}
	 * compares a citizen's idle against its move, and all six cameos have no move —
	 * they are posed statues, asserted as such a few methods up. Giving Rob the dwarf's
	 * standing pose used to leave the whole suite green; now it fails here and in
	 * {@code AnimationSkeletonTest}, twice over.
	 *
	 * <p>Both directions are checked, because they fail differently. Every animation on
	 * the verified list has to be on the human framemap — that is the rule for the
	 * <i>list</i>, and it is what stops a dwarf or goblin pose being admitted at all.
	 * And each cameo's own pose has to match the framemap of the NPC body <i>it</i>
	 * wears — that is the rule for the <i>record</i>, and it would still catch a
	 * non-human cameo body being paired with a human pose.
	 */
	@Test
	public void everyCameoPoseDrivesTheSkeletonOfTheBodyItIsWornOn()
	{
		for (LivelyAnimation pose : VERIFIED_POSES)
		{
			assertEquals(pose + " is on the cameo pose list, so it has to be on the human "
					+ "skeleton — every cameo body in the dataset is",
				(Integer) AnimationSkeletons.HUMAN, AnimationSkeletons.framemapOf(pose));
		}

		List<String> violations = new ArrayList<>();

		for (EntityDefinition cameo : shippedCameos())
		{
			assertEquals(cameo.getName() + " is dressed from an NPC, so its rig is that NPC's",
				0, cameo.getModelIds().length);

			Integer body = ModelSkeletons.framemapOfBody(cameo.getNpcAppearanceId());
			assertNotNull(cameo.getName() + " wears NpcID " + cameo.getNpcAppearanceId()
				+ ", which has no framemap recorded — look it up and add a row to "
				+ "ModelSkeletons", body);

			Integer pose = AnimationSkeletons.framemapOf(cameo.getIdleAnimation());
			assertNotNull(cameo.getIdleAnimation() + " has no framemap in the table", pose);

			if (!body.equals(pose))
			{
				violations.add(cameo.getName() + " wears NpcID " + cameo.getNpcAppearanceId()
					+ " (framemap " + body + ") and is posed " + cameo.getIdleAnimation()
					+ " (framemap " + pose + ")");
			}
		}

		assertTrue("cameo(s) posed on a skeleton their body does not have: " + violations,
			violations.isEmpty());
	}

	/**
	 * Nobody at the Grand Exchange is wearing skin as a costume.
	 *
	 * <p>{@code NpcID.BARBARIAN} is bare-chested in red shorts. It was chosen for
	 * being the most muscular human body in the named constants, which it may well be,
	 * and on video it reads as a naked man standing in the busiest bank in the game.
	 * There is no offline way to ask a composition whether it is dressed — models are
	 * raw geometry — so what is checkable is the narrower thing: the id that was wrong
	 * is not back, and the id that replaced it is the armoured one it was replaced
	 * with, compared against gameval rather than against a copy of itself.
	 */
	@Test
	public void peterIsDressed()
	{
		EntityDefinition peter = byName(shippedCameos(), "Peter");
		assertNotNull("the cameo this test is about is no longer in the dataset", peter);

		assertEquals("Peter wears Lord Marshal Brogan's Shayzien plate",
			NpcID.CORSCURS_LORD_MARSHAL, peter.getNpcAppearanceId());
		assertNotEquals("NpcID.BARBARIAN is bare-chested and cannot come back",
			NpcID.BARBARIAN, peter.getNpcAppearanceId());
	}

	// --- Placement -----------------------------------------------------------

	/**
	 * All six stand in the Grand Exchange's own region, north-west of its centre, and
	 * close enough to it to be inside the compound rather than out on the Varrock
	 * road.
	 */
	@Test
	public void everyCameoStandsNorthWestOfTheGrandExchangeCentre()
	{
		List<String> violations = new ArrayList<>();

		for (EntityDefinition cameo : shippedCameos())
		{
			WorldPoint tile = cameo.getWorldLocation();

			if (cameo.getTileRegionId() != GRAND_EXCHANGE_REGION)
			{
				violations.add(cameo.getName() + " stands in region " + cameo.getTileRegionId());
			}

			if (tile.getX() > GE_CENTRE.getX() || tile.getY() < GE_CENTRE.getY())
			{
				violations.add(cameo.getName() + " at " + tile.getX() + "," + tile.getY()
					+ " is not north-west of the GE centre");
			}

			int distance = RenderPolicy.tileDistance(GE_CENTRE, tile);
			if (distance > 10)
			{
				violations.add(cameo.getName() + " is " + distance
					+ " tiles from the GE centre, which is outside the compound");
			}
		}

		assertTrue("cameo placement violation(s): " + violations, violations.isEmpty());
	}

	/**
	 * The GE checkbox really is the one that governs them.
	 *
	 * <p>Not a restatement of the region assertion above: {@code City} owns the
	 * region-to-checkbox mapping and fails <i>open</i> for a region no city claims, so
	 * "they are in 12598" and "unticking Grand Exchange switches them off" are two
	 * different facts and only the second one matters to a user.
	 */
	@Test
	public void theGrandExchangeCheckboxIsTheOneThatGovernsThem()
	{
		FakeConfig config = new FakeConfig();

		for (EntityDefinition cameo : shippedCameos())
		{
			assertEquals("the city claiming " + cameo.getName() + "'s tile",
				City.GRAND_EXCHANGE, City.of(cameo.getCityRegionId()));

			config.enable(City.GRAND_EXCHANGE);
			assertTrue(City.isEnabled(cameo.getCityRegionId(), config));

			config.disableOnly(City.GRAND_EXCHANGE);
			assertFalse(cameo.getName() + " must go away with the Grand Exchange checkbox",
				City.isEnabled(cameo.getCityRegionId(), config));
		}
	}

	/**
	 * No two of them interpenetrate, and none of them stands on top of one of the
	 * three vendored entities already in the file.
	 */
	@Test
	public void theGroupIsSpacedFarEnoughApartToReadAsSixPeople()
	{
		List<EntityDefinition> cameos = shippedCameos();
		List<String> violations = new ArrayList<>();

		for (int i = 0; i < cameos.size(); i++)
		{
			for (int j = i + 1; j < cameos.size(); j++)
			{
				EntityDefinition a = cameos.get(i);
				EntityDefinition b = cameos.get(j);
				int distance = RenderPolicy.tileDistance(a.getWorldLocation(), b.getWorldLocation());
				if (distance < MIN_SEPARATION_TILES)
				{
					violations.add(a.getName() + " and " + b.getName() + " are " + distance
						+ " tile(s) apart and would clip through each other");
				}
			}
		}

		for (EntityDefinition cameo : cameos)
		{
			for (EntityDefinition other : shippedRegion())
			{
				if (other.isCameo())
				{
					continue;
				}
				int distance = RenderPolicy.tileDistance(
					cameo.getWorldLocation(), other.getWorldLocation());
				if (distance < MIN_SEPARATION_TILES)
				{
					violations.add(cameo.getName() + " is " + distance + " tile(s) from the vendored "
						+ other.label());
				}
			}
		}

		assertTrue("cameo spacing violation(s): " + violations, violations.isEmpty());
	}

	/**
	 * They face the courtyard, not each other's backs and not all north.
	 *
	 * <p>Measured rather than eyeballed. The client's orientation convention is
	 * {@code 0 = south, 512 = west, 1024 = north, 1536 = east} (read off
	 * {@code CitizenWalk.STEP_ORIENTATION}, which maps a step of {@code dx=0, dy=-1}
	 * to 0 and {@code dx=+1, dy=0} to 1536), so an orientation's facing vector is
	 * {@code (-sin θ, -cos θ)} with {@code θ = 2π · o / 2048}. The dot product of
	 * that with the unit vector towards the GE centre has to be strongly positive:
	 * 0.9 is a cone of about 26 degrees, so a cameo that faced north — which is what
	 * an unset {@code baseOrientation} would mean — comes out at roughly -1 and fails
	 * hard.
	 */
	@Test
	public void everyCameoFacesTheCourtyardRatherThanAwayFromTheViewer()
	{
		List<String> violations = new ArrayList<>();

		for (EntityDefinition cameo : shippedCameos())
		{
			WorldPoint tile = cameo.getWorldLocation();
			double toCentreX = GE_CENTRE.getX() - tile.getX();
			double toCentreY = GE_CENTRE.getY() - tile.getY();
			double length = Math.hypot(toCentreX, toCentreY);
			assertTrue("a cameo standing on the GE centre has no direction to face", length > 0);

			double theta = 2 * Math.PI * cameo.getOrientation() / 2048.0;
			double facingX = -Math.sin(theta);
			double facingY = -Math.cos(theta);

			double alignment = (facingX * toCentreX + facingY * toCentreY) / length;
			if (alignment < 0.9)
			{
				violations.add(String.format("%s faces %d, which is %.2f aligned with the courtyard "
						+ "(needs 0.90)", cameo.getName(), cameo.getOrientation(), alignment));
			}
		}

		assertTrue("cameo facing violation(s): " + violations, violations.isEmpty());
	}

	// --- Honesty -------------------------------------------------------------

	/**
	 * The record text has to be affectionate without claiming to be the person.
	 *
	 * <p>Three requirements, and each has a failure mode with a name. Every cameo
	 * needs an {@code examineText}, or {@code CitizenLabel.examineMessage} prints the
	 * plugin's disclaimer and nothing else and the player learns nothing. That text
	 * has to say outright that it is a likeness and not a player, because "Rob" over
	 * a White Knight model at the Grand Exchange is otherwise indistinguishable from
	 * an account name. And nothing may claim the person is <i>present</i> — the
	 * difference between a tribute and an impersonation.
	 */
	@Test
	public void everyCameoExamineTextSaysItIsALikenessAndNotAPlayer()
	{
		List<String> violations = new ArrayList<>();

		// Phrasings that would turn a tribute into a claim about a real account.
		List<String> forbidden = Arrays.asList(
			"is here", "is online", "logged in", "my account", "his account", "her account",
			"real player", "an actual player");

		for (EntityDefinition cameo : shippedCameos())
		{
			String examine = cameo.getExamineText();
			if (examine == null || examine.trim().isEmpty())
			{
				violations.add(cameo.getName() + " has no examine text");
				continue;
			}

			String lower = examine.toLowerCase();

			if (!lower.contains("likeness") && !lower.contains("cameo"))
			{
				violations.add(cameo.getName() + " does not say what it is: '" + examine + "'");
			}

			if (!lower.contains("not a player"))
			{
				violations.add(cameo.getName() + " does not disclaim being a player: '" + examine + "'");
			}

			for (String phrase : forbidden)
			{
				if (lower.contains(phrase))
				{
					violations.add(cameo.getName() + " implies the person is present ('" + phrase
						+ "'): '" + examine + "'");
				}
			}

			// The plugin's own disclaimer still has to be the last word, whatever the
			// authored text says.
			String message = CitizenLabel.examineMessage(cameo);
			if (!message.contains("not a real NPC"))
			{
				violations.add(cameo.getName() + " loses the plugin disclaimer: " + message);
			}
			if (!message.contains(cameo.getName()))
			{
				violations.add(cameo.getName() + " is not named in its own examine line: " + message);
			}
		}

		assertTrue("cameo text violation(s): " + violations, violations.isEmpty());
	}

	/**
	 * Each has one short line, in character.
	 *
	 * <p>Cameos are the one part of the dataset where every citizen talks, so the cap
	 * matters: six characters shouting at once in the busiest room in the game is the
	 * overhead-text spam that was the predecessor's loudest complaint. One line each
	 * keeps them inside the same cadence and the same
	 * {@code maxConcurrentRemarks} cap as everybody else.
	 */
	@Test
	public void everyCameoHasExactlyOneShortRemark()
	{
		List<String> violations = new ArrayList<>();

		for (EntityDefinition cameo : shippedCameos())
		{
			String[] remarks = cameo.getRemarks();
			if (remarks.length != 1)
			{
				violations.add(cameo.getName() + " has " + remarks.length + " remark(s), expected 1");
				continue;
			}

			if (remarks[0].length() > 40)
			{
				violations.add(cameo.getName() + "'s remark is " + remarks[0].length()
					+ " characters — overhead text, not dialogue: '" + remarks[0] + "'");
			}

			assertNotNull("a cameo with a remark must have something to mute",
				CitizenRemarks.forDefinition(cameo));
		}

		assertTrue("cameo remark violation(s): " + violations, violations.isEmpty());
	}

	// --- The opt-in ----------------------------------------------------------

	/**
	 * The default, and it is the whole reason the feature is allowed to exist.
	 *
	 * <p>Asserted on the interface's own {@code default} method rather than on a
	 * fake, because that method <i>is</i> the shipped default: a fresh install and a
	 * hub reviewer both read exactly this value.
	 */
	@Test
	public void theCameosSettingIsOffByDefault()
	{
		LivelyCitiesConfig shipped = new LivelyCitiesConfig()
		{
		};

		assertFalse("cameos must be opt-in — player-shaped content at the Grand Exchange is "
				+ "exactly what got the predecessor plugin disabled",
			shipped.cameos());

		assertFalse("and the test fake must inherit that default rather than opting in for "
				+ "convenience", new FakeConfig().cameos());
	}

	/**
	 * The setting has to explain itself where the user reads it.
	 *
	 * <p>A checkbox whose description said only "adds six cameos" would leave a
	 * reviewer to work out that this is the player-shaped content their own rules are
	 * about. The description is therefore load-bearing text, and this is what stops it
	 * being trimmed to a label.
	 */
	@Test
	public void theCameosSettingDescriptionSaysWhatItAddsAndWhyItIsOff()
	{
		String lower = LivelyCitiesConfig.CAMEOS_DESCRIPTION.toLowerCase();

		assertTrue("it must say where they are", lower.contains("grand exchange"));
		assertTrue("it must say how many", lower.contains("six"));
		assertTrue("it must say what they look like", lower.contains("player-shaped"));
		assertTrue("it must say being off is the deliberate default",
			lower.contains("switched off by default"));
		assertTrue("it must say whose likenesses they are", lower.contains("friend"));
		assertTrue("it must say the city checkbox applies too", lower.contains("grand exchange checkbox"));

		// Long enough to have said all of that, and buried in nothing: this is the
		// text the user reads on the checkbox itself.
		assertTrue("the description must not be trimmed to a tooltip",
			LivelyCitiesConfig.CAMEOS_DESCRIPTION.length() > 300);

		assertTrue("the label itself must not bury it — it is one row in a list of checkboxes",
			LivelyCitiesConfig.CAMEOS_NAME.toLowerCase().contains("cameo"));
		assertTrue("and the label should say it is off, because a reviewer reads labels first",
			LivelyCitiesConfig.CAMEOS_NAME.toLowerCase().contains("off by default"));
	}

	/**
	 * What the description says they are dressed as has to be what they are dressed as.
	 *
	 * <p>The check above pins the phrases that make the text honest about the
	 * <i>feature</i>, and it went on passing for a description that said "a barbarian"
	 * after Peter had stopped being one — because it never looked at the costume list.
	 * That list is the concrete half of the promise: the abstract half ("player-shaped",
	 * "off by default") is what a reviewer skims, and the costume list is what a user
	 * checks against what they can see standing at the bank.
	 *
	 * <p>Derived from the roster rather than restated. {@link #COSTUMES} maps an NPC
	 * body to the word the description uses for it, including bodies that are no longer
	 * worn — so a retired costume is asserted <i>absent</i> by the same table that
	 * asserts the current ones present, and "barbarian" cannot come back into the string
	 * any more than {@code NpcID.BARBARIAN} can come back into the data.
	 */
	@Test
	public void theCameosSettingDescriptionNamesTheCostumesTheCameosActuallyWear()
	{
		String lower = LivelyCitiesConfig.CAMEOS_DESCRIPTION.toLowerCase();

		Set<Integer> worn = new HashSet<>();
		for (EntityDefinition cameo : shippedCameos())
		{
			worn.add(cameo.getNpcAppearanceId());
		}
		assertEquals("one body per cameo", EXPECTED.length, worn.size());

		List<String> violations = new ArrayList<>();

		for (Map.Entry<Integer, String> costume : COSTUMES.entrySet())
		{
			boolean mentioned = lower.contains(costume.getValue());
			if (worn.contains(costume.getKey()) && !mentioned)
			{
				violations.add("a cameo wears NpcID " + costume.getKey()
					+ " but the description never says \"" + costume.getValue() + "\"");
			}
			if (!worn.contains(costume.getKey()) && mentioned)
			{
				violations.add("the description still says \"" + costume.getValue()
					+ "\", but no cameo wears NpcID " + costume.getKey() + " any more");
			}
		}

		for (int body : worn)
		{
			if (!COSTUMES.containsKey(body))
			{
				violations.add("NpcID " + body + " is worn by a cameo and has no word in the "
					+ "costume table — add one, and put it in the description");
			}
		}

		assertTrue("cameo costume violation(s): " + violations, violations.isEmpty());
	}

	/**
	 * The word the settings description uses for each cameo body, and for the one it
	 * used to use.
	 *
	 * <p>Retired entries stay. {@code NpcID.BARBARIAN} is here precisely because it is
	 * not worn: the assertion above reads this table in both directions, so leaving a
	 * dead costume in the string fails as loudly as leaving a live one out.
	 */
	private static final Map<Integer, String> COSTUMES = costumes();

	private static Map<Integer, String> costumes()
	{
		Map<Integer, String> words = new TreeMap<>();
		words.put(NpcID.YOUNG_DARK_WIZARD, "wizard");        // Cazh
		words.put(NpcID.MISC_SAILOR, "sailor");              // Gunnar
		words.put(NpcID.CORSCURS_LORD_MARSHAL, "soldier");   // Peter
		words.put(NpcID.ROGUE, "rogue");                     // Sludgellama
		words.put(NpcID.HOBBES_THE_BUTLER, "butler");        // MrCream
		words.put(NpcID.WHITE_KNIGHT, "white knight");       // Rob
		words.put(NpcID.BARBARIAN, "barbarian");             // retired — see the javadoc
		return Collections.unmodifiableMap(words);
	}

	// --- The lint ------------------------------------------------------------

	/**
	 * Every cameo in the data is tagged {@link Theme#CAMEO} in {@link EntityTheme},
	 * and nothing else is.
	 *
	 * <p>This is the join between the dataset and the placement lint, and without it
	 * the lint would be honest about six citizens and blind to a seventh. Both
	 * directions are checked: an untagged cameo would be {@link Theme#GENERIC}, which
	 * is compatible with every region, so it could be copied into Varrock square
	 * unnoticed — and a tagged non-cameo would be a citizen that mysteriously may only
	 * stand at the Grand Exchange.
	 */
	@Test
	public void theCameoThemeTableAndTheDatasetsOwnFlagAgreeExactly()
	{
		Set<String> flaggedInData = new TreeSet<>();
		Set<String> taggedAsCameo = new TreeSet<>();

		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (citizen.cameo)
			{
				flaggedInData.add(citizen.uuid);
			}
			if (EntityTheme.themeOf(citizen.uuid) == Theme.CAMEO)
			{
				taggedAsCameo.add(citizen.uuid);
			}
		}

		assertEquals("the dataset's cameo count", EXPECTED.length, flaggedInData.size());
		assertEquals("every cameo has to be themed CAMEO and nothing else may be",
			flaggedInData, taggedAsCameo);
	}

	/**
	 * The poison property {@link Theme#CAMEO} depends on: it is mapped to exactly one
	 * city.
	 *
	 * <p>Mapped to none and it would behave like {@link Theme#UNIQUE_BOSS} — flagged
	 * everywhere, including at home, and the shipped dataset would fail its own lint.
	 * Mapped to two or more and a cameo becomes copy-pasteable into a second city,
	 * which is how six in-jokes become the "fake players" the content rules forbid.
	 * The mirror of {@code PlacementLintTest.noCityIsEverMappedToTheUniqueBossTheme}.
	 */
	@Test
	public void theCameoThemeMapsToExactlyOneCityAndItIsTheGrandExchange()
	{
		List<String> cities = new ArrayList<>();
		for (City city : City.values())
		{
			if (CityTheme.of(city) == Theme.CAMEO)
			{
				cities.add(city.getLabel());
			}
		}

		assertEquals("Theme.CAMEO must be compatible with exactly one city: " + cities,
			1, cities.size());
		assertEquals(City.GRAND_EXCHANGE.getLabel(), cities.get(0));

		// And the rule it buys, stated directly rather than left to the lint.
		assertTrue("a cameo belongs at the Grand Exchange",
			PlacementCompatibility.isCompatible(Theme.CAMEO, CityTheme.of(City.GRAND_EXCHANGE)));
		assertFalse("a cameo does not belong in Varrock square",
			PlacementCompatibility.isCompatible(Theme.CAMEO, CityTheme.of(City.VARROCK)));
		assertTrue("and an ordinary townsperson is still welcome at the Grand Exchange — "
				+ "Richard the cook is GENERIC and lives in the same file",
			PlacementCompatibility.isCompatible(Theme.GENERIC, CityTheme.of(City.GRAND_EXCHANGE)));
	}

	/**
	 * A human-readable roll call, printed for review, backed by an assertion so it
	 * cannot drift from what the tests above checked.
	 */
	@Test
	public void printsTheCameoRosterForHumanReview()
	{
		TreeMap<String, String> rows = new TreeMap<>();

		System.out.println("Lively Cities cameos — region " + GRAND_EXCHANGE_REGION
			+ " (Grand Exchange), behind the `cameos` setting, default off");
		System.out.println("name          tile          npc    facing  animation        remark");

		for (EntityDefinition cameo : shippedCameos())
		{
			String row = String.format("%-13s %d,%-8d %-6d %-7d %-16s %s",
				cameo.getName(),
				cameo.getWorldLocation().getX(),
				cameo.getWorldLocation().getY(),
				cameo.getNpcAppearanceId(),
				cameo.getOrientation(),
				cameo.getIdleAnimation() == null ? "-" : cameo.getIdleAnimation().name(),
				cameo.getRemarks().length == 0 ? "-" : cameo.getRemarks()[0]);
			rows.put(cameo.getName(), row);
		}

		for (String row : rows.values())
		{
			System.out.println(row);
		}

		assertEquals("every cameo needs a row", EXPECTED.length, rows.size());
	}

	// --- fixtures ------------------------------------------------------------

	private static List<EntityDefinition> shippedRegion()
	{
		RegionDefinition region = new RegionDataLoader(TestGson.injected())
			.loadRegion(GRAND_EXCHANGE_REGION);
		assertNotNull("region " + GRAND_EXCHANGE_REGION + " failed to load", region);
		return region.getEntities();
	}

	/**
	 * The cameos, read out of the whole shipped dataset rather than out of the one
	 * file they are expected to be in — so a cameo that got copied into another region
	 * turns up here and fails the placement assertions, instead of being invisible to
	 * this file.
	 */
	private static List<EntityDefinition> shippedCameos()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			for (EntityDefinition entity : region.getEntities())
			{
				if (entity.isCameo())
				{
					out.add(entity);
				}
			}
		}

		return out;
	}

	private static EntityDefinition byName(List<EntityDefinition> entities, String name)
	{
		for (EntityDefinition entity : entities)
		{
			if (name.equals(entity.getName()))
			{
				return entity;
			}
		}
		return null;
	}

	/**
	 * The two cache facts the pose admission rule is written in terms of.
	 *
	 * <p>{@link #standOfNpcCount} is how many NPC definitions in the 1.12.36 cache name
	 * {@link #animationId} as their {@code stand}. Zero is a legitimate value and is not
	 * a failure on its own — {@code HUMAN_SMUG_IDLE} is admitted on its name.
	 */
	private static final class PoseEvidence
	{
		final int animationId;
		final String gamevalName;
		final int standOfNpcCount;

		PoseEvidence(int animationId, String gamevalName, int standOfNpcCount)
		{
			this.animationId = animationId;
			this.gamevalName = gamevalName;
			this.standOfNpcCount = standOfNpcCount;
		}

		/** The admission rule itself, executable. */
		boolean isAPose()
		{
			return gamevalName.endsWith("_READY")
				|| gamevalName.endsWith("_IDLE")
				|| standOfNpcCount > 0;
		}

		@Override
		public String toString()
		{
			return gamevalName + " (" + animationId + "), stand of " + standOfNpcCount + " NPC(s)";
		}
	}

	/** One expected cameo, written out by hand. */
	private static final class Cameo
	{
		final String name;
		final String uuid;
		final int x;
		final int y;
		final int npcId;
		final int orientation;
		final String animation;

		Cameo(String name, String uuid, int x, int y, int npcId, int orientation, String animation)
		{
			this.name = name;
			this.uuid = uuid;
			this.x = x;
			this.y = y;
			this.npcId = npcId;
			this.orientation = orientation;
			this.animation = animation;
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What the {@code cameos} checkbox actually does to the scene, and what still has
 * to keep working when it is on.
 *
 * <p>Driven through the real {@link EntityScene} against {@link FakeClient}, so
 * "it is not rendered" means the client genuinely has nothing registered rather
 * than a flag being false somewhere.
 *
 * <p><b>Every fixture here puts a cameo and an ordinary citizen in the same
 * scene.</b> That is not padding: a scene made only of cameos could not tell "the
 * checkbox switched the cameos off" from "the checkbox switched everything off",
 * which is the exact shape of fixture uniformity that made {@link EntitySceneTest}
 * necessary in the first place.
 */
public class CameoSceneTest
{
	/** The Grand Exchange, x 3136-3199, y 3456-3519. */
	private static final int GRAND_EXCHANGE = 12598;

	/** Region 12852 — Varrock south. A second city, so the two toggles can differ. */
	private static final int VARROCK_SOUTH = 12852;

	/** Inside the GE, within the cull radius of the fixtures below. */
	private static final WorldPoint PLAYER = new WorldPoint(3165, 3490, 0);

	/** NpcID.WHITE_KNIGHT, and it does not matter here beyond being a real body. */
	private static final int WHITE_KNIGHT = 1798;

	/**
	 * NpcID.CORSCURS_LORD_MARSHAL — Peter's body, and the second one these fixtures
	 * need so two cameos can be told apart.
	 *
	 * <p>It used to be {@code NpcID.BARBARIAN} (3256), at Peter's exact tile. Nothing
	 * here depends on which body it is, but a retired costume sitting in a fixture is
	 * how a retired costume gets read as current — {@code CameoPlacementTest.peterIsDressed}
	 * exists because that id put a bare-chested man in the busiest bank in the game, and
	 * the settings description went on saying "a barbarian" long after he stopped being
	 * one.
	 */
	private static final int LORD_MARSHAL = 7987;

	private FakeClient client;
	private FakeRegions regions;
	private FakeConfig config;
	private EntityScene scene;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.recoloured(
			"White Knight", new int[]{217, 305}, new short[]{10, 20}, new short[]{11, 21}));
		client.withNpc(LORD_MARSHAL, FakeNpcComposition.of("Lord Marshal Brogan", 400));

		regions = new FakeRegions();
		config = new FakeConfig();
		scene = new EntityScene(client, regions, config, config.overrides());
	}

	/** One cameo and one ordinary citizen, both in the GE and both in range. */
	private void oneCameoAndOneCitizen()
	{
		List<EntityDefinition> roster = new ArrayList<>();
		roster.add(regions.cameo(GRAND_EXCHANGE, 3160, 3495, WHITE_KNIGHT));
		roster.add(regions.citizen(GRAND_EXCHANGE, 3169, 3489, 0, 217));
		regions.file(GRAND_EXCHANGE, roster);
	}

	private FakeWorldView pass()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, GRAND_EXCHANGE);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		return view;
	}

	// --- The two toggles, and their four combinations ------------------------

	/**
	 * The default. A fresh install renders the townsperson and not the cameo.
	 */
	@Test
	public void withTheCameosSettingOffOnlyTheOrdinaryCitizenRenders()
	{
		oneCameoAndOneCitizen();

		pass();

		assertEquals("the ordinary citizen must still be there", 1, client.registeredCount());
		assertFalse("nothing may have asked the client for a cameo's body",
			client.npcDefinitionsRequested().contains(WHITE_KNIGHT));
	}

	@Test
	public void tickingTheCameosSettingBringsThemIn()
	{
		oneCameoAndOneCitizen();
		config.setCameos(true);

		pass();

		assertEquals("both the cameo and the citizen", 2, client.registeredCount());
		assertTrue("the cameo's body has to have come from its NPC id",
			client.npcDefinitionsRequested().contains(WHITE_KNIGHT));
	}

	/**
	 * The interaction, and it is an AND rather than an OR: unticking the Grand
	 * Exchange takes the cameos with it even though their own checkbox is on.
	 */
	@Test
	public void aCameoNeedsItsCityCheckboxTooNotJustItsOwn()
	{
		oneCameoAndOneCitizen();
		config.setCameos(true).disableOnly(City.GRAND_EXCHANGE);

		pass();

		assertEquals("unticking the city switches off the cameo and the citizen alike",
			0, client.registeredCount());
	}

	/**
	 * And the other way round, which is the half that matters for a reviewer: the
	 * Grand Exchange being on is not consent to player-shaped content.
	 */
	@Test
	public void theCityCheckboxBeingOnIsNotEnoughOnItsOwn()
	{
		oneCameoAndOneCitizen();
		config.setCameos(false).enable(City.GRAND_EXCHANGE);

		pass();

		assertEquals("the city is on, so its ordinary citizen renders", 1, client.registeredCount());

		LivelyEntity cameo = wrapperForCameo();
		assertNotNull(cameo);
		assertFalse("but the cameo does not", cameo.isActive());
	}

	/**
	 * Unticking the box takes them off the screen on the click, through the same
	 * "what is not wanted is despawned" rule the city checkboxes use — not on the
	 * next region crossing.
	 */
	@Test
	public void unticikingTheSettingDespawnsThemImmediately()
	{
		oneCameoAndOneCitizen();
		config.setCameos(true);

		FakeWorldView view = pass();
		assertEquals(2, client.registeredCount());

		config.setCameos(false);
		scene.onSettingsChanged(PLAYER, view);

		assertEquals("only the ordinary citizen is left", 1, client.registeredCount());

		// And back again, without a rebuild: the wrapper kept its model.
		client.resetCounters();
		config.setCameos(true);
		scene.onSettingsChanged(PLAYER, view);
		assertEquals(2, client.registeredCount());
		assertEquals("coming back is an activate, not a rebuild", 0, client.mergeCalls());
	}

	// --- The ground gate ------------------------------------------------------

	/**
	 * A cameo standing on ground the collision map calls blocked does not render.
	 *
	 * <p>The mitigation for the fact that nobody has stood on these six tiles in game
	 * — see {@code CameoPlacementTest}'s class javadoc. The ordinary citizen two
	 * tiles away is the control: authored non-cameo content is <b>not</b> collision
	 * gated, and this is what says the gate is about cameos rather than about the
	 * whole scene.
	 */
	@Test
	public void aCameoOnBlockedGroundIsSkippedWhileAnOrdinaryCitizenIsNot()
	{
		WorldPoint cameoTile = new WorldPoint(3160, 3495, 0);
		WorldPoint citizenTile = new WorldPoint(3169, 3489, 0);

		regions.file(GRAND_EXCHANGE, Arrays.asList(
			regions.cameo(GRAND_EXCHANGE, cameoTile.getX(), cameoTile.getY(), WHITE_KNIGHT),
			regions.citizen(GRAND_EXCHANGE, citizenTile.getX(), citizenTile.getY(), 0, 217)));
		config.setCameos(true);

		FakeWorldView view = FakeWorldView.around(PLAYER, GRAND_EXCHANGE);
		view.block(cameoTile);
		view.block(citizenTile);

		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);

		assertEquals("the bank booth keeps the cameo out; the vendored citizen is trusted",
			1, client.registeredCount());

		LivelyEntity cameo = wrapperForCameo();
		assertNotNull(cameo);
		assertFalse(cameo.isActive());
		assertFalse("a refused tile is not a broken entity — the scene may reload", cameo.isBroken());
	}

	/**
	 * The other side of the same coin, and the reason the test above is not green for
	 * the wrong reason: on open ground the cameo does render.
	 *
	 * <p>{@link FakeWorldView} defaults every tile to walkable, so without this pair
	 * a gate that refused every cameo unconditionally would look identical to a gate
	 * that worked.
	 */
	@Test
	public void aCameoOnOpenGroundRenders()
	{
		oneCameoAndOneCitizen();
		config.setCameos(true);

		pass();

		LivelyEntity cameo = wrapperForCameo();
		assertNotNull(cameo);
		assertTrue(cameo.isActive());
	}

	/**
	 * A collision map that has no answer is not a yes.
	 *
	 * <p>An echo may be admitted on {@code UNKNOWN} if its tile came from inside its
	 * source's authored wander box — a human vouched for that ground. A cameo has no
	 * wander box and nothing has vouched for its tile, so it waits. In practice it
	 * waits until the scene finishes building, which is one tick.
	 */
	@Test
	public void aCameoIsNotRenderedWhileTheCollisionMapHasNoAnswer()
	{
		oneCameoAndOneCitizen();
		config.setCameos(true);

		FakeWorldView view = FakeWorldView.around(PLAYER, GRAND_EXCHANGE).withoutCollisionData();
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);

		assertEquals("only the ordinary citizen, which needs no vouching", 1, client.registeredCount());

		// The scene finishes loading. Same wrapper, same tile, now admitted.
		FakeWorldView loaded = FakeWorldView.around(PLAYER, GRAND_EXCHANGE);
		scene.syncRegions(loaded);
		scene.updateVisibility(PLAYER, loaded);
		assertEquals(2, client.registeredCount());
	}

	// --- Hide and mute --------------------------------------------------------

	/**
	 * Hide works on a cameo like any citizen, and hides only that one.
	 */
	@Test
	public void hidingACameoHidesThatCameoAndNothingElse()
	{
		List<EntityDefinition> roster = Arrays.asList(
			regions.cameo(GRAND_EXCHANGE, 3160, 3495, WHITE_KNIGHT),
			regions.cameo(GRAND_EXCHANGE, 3164, 3495, LORD_MARSHAL),
			regions.citizen(GRAND_EXCHANGE, 3169, 3489, 0, 217));
		regions.file(GRAND_EXCHANGE, roster);
		config.setCameos(true);

		FakeWorldView view = pass();
		assertEquals(3, client.registeredCount());

		assertTrue(config.overrides().hide(roster.get(0)));
		scene.onSettingsChanged(PLAYER, view);

		assertEquals("one cameo hidden, the other cameo and the citizen untouched",
			2, client.registeredCount());
		assertFalse(scene.wrapperForUuid(roster.get(0).getUuid()).isActive());
		assertTrue(scene.wrapperForUuid(roster.get(1).getUuid()).isActive());
	}

	/**
	 * Mute works on a cameo, which means a cameo has to have something to mute — all
	 * six shipped ones carry a remark, and {@link CitizenMenu} only offers Mute to a
	 * citizen with remarks.
	 */
	@Test
	public void aCameoCanBeMutedBecauseItHasSomethingToSay()
	{
		List<EntityDefinition> roster = Arrays.asList(
			regions.cameo(GRAND_EXCHANGE, 3160, 3495, WHITE_KNIGHT),
			regions.citizen(GRAND_EXCHANGE, 3169, 3489, 0, 217));
		regions.file(GRAND_EXCHANGE, roster);
		config.setCameos(true);

		pass();

		LivelyEntity cameo = scene.wrapperForUuid(roster.get(0).getUuid());
		assertNotNull(cameo);
		assertNotNull("a cameo has remarks, so CitizenMenu offers it Mute", cameo.getRemarks());

		assertTrue(config.overrides().mute(roster.get(0)));
		assertTrue(config.overrides().mutedUuids().contains(roster.get(0).getUuid()));

		// The control: the ordinary citizen in this fixture has none, so "cameos can
		// be muted" is a fact about cameos rather than about every wrapper.
		assertNull(scene.wrapperForUuid(roster.get(1).getUuid()).getRemarks());
	}

	// --- Interaction with the crowd dial -------------------------------------

	/**
	 * Turning the density up to Crowded must not add anybody near a cameo.
	 *
	 * <p>An echo is gated on the crowd density and on its source's city, and on
	 * nothing else — so an echo of a cameo would be an extra human body in the Grand
	 * Exchange for any Crowded user regardless of the {@code cameos} checkbox, which
	 * is the exact leak that checkbox exists to close. It would also be a seventh
	 * person in a posed group photo.
	 *
	 * <p><b>The cameo in this fixture is deliberately the kind that would otherwise
	 * seed two echoes</b> — {@link FakeRegions#cameoWithModelIds} carries raw model ids
	 * and a three-pair palette — so being a cameo is the only reason it seeds none.
	 * A cameo dressed from an NPC id would have been refused by two other rules first,
	 * and this test would have been green for the wrong reason. The ordinary
	 * {@code recoloured} citizen beside it is the control: it does seed echoes, so a
	 * derivation that had stopped working altogether would also show up.
	 */
	@Test
	public void aCameoSeedsNoEchoesEvenAtCrowdedDensity()
	{
		EntityDefinition cameo = regions.cameoWithModelIds(GRAND_EXCHANGE, 3160, 3495);
		EntityDefinition ordinary = regions.recoloured(GRAND_EXCHANGE, 3170, 3480, 3);

		List<EntityDefinition> echoes = CitizenEcho.echoesOfRegion(Arrays.asList(cameo, ordinary));

		assertFalse("the fixture has to produce echoes at all, or this proves nothing",
			echoes.isEmpty());

		for (EntityDefinition echo : echoes)
		{
			assertEquals("every echo here must come from the ordinary citizen",
				ordinary.getUuid(), echo.getEchoSourceUuid());
			assertFalse("an echo is never a cameo", echo.isCameo());
		}
	}

	/**
	 * An NPC-dressed source seeds no echoes either, and for a different reason: its
	 * colours come from the composition, so a re-dealt palette would produce a
	 * pixel-for-pixel twin standing two tiles away.
	 *
	 * <p>Separate from the cameo rule because the two are separate record fields and
	 * separate branches. Nothing in the shipped data is NPC-dressed without also being
	 * a cameo, so this is the only place the rule is exercised at all — which is
	 * exactly why it is here.
	 */
	@Test
	public void anNpcDressedSourceSeedsNoEchoesBecauseAReDealWouldChangeNothing()
	{
		EntityDefinition dressed = regions.npcDressed(GRAND_EXCHANGE, 3160, 3495, WHITE_KNIGHT);
		EntityDefinition ordinary = regions.recoloured(GRAND_EXCHANGE, 3170, 3480, 3);

		assertEquals("the fixture must have a palette rich enough to seed two, or this "
				+ "test cannot tell the rule from the palette check",
			3, dressed.getRecolorFind().length);

		List<EntityDefinition> echoes = CitizenEcho.echoesOfRegion(Arrays.asList(dressed, ordinary));

		assertFalse(echoes.isEmpty());
		for (EntityDefinition echo : echoes)
		{
			assertEquals("an NPC-dressed citizen must seed nothing",
				ordinary.getUuid(), echo.getEchoSourceUuid());
		}
	}

	/**
	 * The same claim through the scene, because {@code echoesOfRegion} being pure is
	 * only half of it: the scene is what builds the wrappers and applies the dial.
	 */
	@Test
	public void crowdedWithTheCameosSettingOffAddsNothingToTheGrandExchange()
	{
		regions.file(GRAND_EXCHANGE, Arrays.asList(
			regions.cameoWithModelIds(GRAND_EXCHANGE, 3160, 3495),
			regions.citizen(GRAND_EXCHANGE, 3169, 3489, 0, 217)));
		config.setCameos(false).setCrowdDensity(CrowdDensity.CROWDED);

		pass();

		assertEquals("no cameo, and nothing derived from one", 1, client.registeredCount());
		assertEquals(0, scene.countActiveEchoes());
		assertEquals("the cameo must not even have seeded a wrapper", 0, scene.getEchoInScopeCount());
	}

	// --- The flag is not the appearance mechanism ----------------------------

	/**
	 * An entity dressed from an NPC id but <b>not</b> flagged as a cameo is ordinary
	 * content, and the {@code cameos} checkbox has no opinion about it.
	 *
	 * <p>This is why the two are separate record fields. The appearance mechanism is
	 * meant to be the preferred way to dress any future entity — a market stall owner
	 * sourced from an NPC id must not silently become opt-in content that most users
	 * never see.
	 */
	@Test
	public void anNpcDressedCitizenThatIsNotACameoIgnoresTheCameosSetting()
	{
		regions.file(GRAND_EXCHANGE, Arrays.asList(
			regions.npcDressed(GRAND_EXCHANGE, 3160, 3495, WHITE_KNIGHT),
			regions.cameo(GRAND_EXCHANGE, 3164, 3495, LORD_MARSHAL)));
		config.setCameos(false);

		pass();

		assertEquals("the NPC-dressed citizen renders; the cameo does not", 1, client.registeredCount());
		assertTrue("and it really did source its body from the NPC id",
			client.npcDefinitionsRequested().contains(WHITE_KNIGHT));
	}

	/**
	 * A cameo in another city obeys <i>that</i> city's checkbox.
	 *
	 * <p>Nothing in the shipped data does this — the placement lint refuses it, see
	 * {@code CameoPlacementTest} — but the scene's gate must not be a special case
	 * about one region either, or the lint would be the only thing holding the rule
	 * and a hand-edited profile could not be reasoned about.
	 */
	@Test
	public void theCameoGateIsNotSpecialCasedToTheGrandExchange()
	{
		WorldPoint varrock = new WorldPoint(3225, 3360, 0);
		regions.file(VARROCK_SOUTH, Arrays.asList(
			regions.cameo(VARROCK_SOUTH, 3225, 3358, WHITE_KNIGHT),
			regions.citizen(VARROCK_SOUTH, 3227, 3358, 0, 217)));
		config.setCameos(true);

		FakeWorldView view = FakeWorldView.around(varrock, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(varrock, view);
		assertEquals(2, client.registeredCount());

		config.disableOnly(City.VARROCK);
		scene.onSettingsChanged(varrock, view);
		assertEquals("Varrock's checkbox governs a cameo standing in Varrock",
			0, client.registeredCount());
	}

	private LivelyEntity wrapperForCameo()
	{
		for (LivelyEntity entity : scene.inScopeEntities())
		{
			if (entity.getDefinition().isCameo())
			{
				return entity;
			}
		}
		return null;
	}
}

package com.matthewmariner.livelycities;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The one overlay that draws overhead text, and the two bug classes it is shaped
 * to make impossible.
 *
 * <p>The predecessor's text bugs were orphaned bubbles and text drifting off its
 * NPC. Both came from a renderer with its own list of what to draw and its own
 * idea of where, so both are tested here as claims about the loop: it walks the
 * live entity set, it asks the client whether each entity is still registered, and
 * it re-projects the object's own position every frame.
 *
 * <p><b>The projection is a seam, and it has to be.</b>
 * {@code Perspective.getCanvasTextLocation} reads the live camera —
 * {@code get3dZoom}, {@code getCameraX/Y/Z}, the rasteriser clip fields — and this
 * repo has no mocking framework and does not use reflection. So
 * {@link RecordingOverlay} overrides it. The one test that does <i>not</i> override
 * it is {@link #aProjectionThatFailsDrawsNothingRatherThanThrowing()}, which runs
 * the real {@code Perspective} call against {@link FakeClient} — whose
 * {@code getWorldView(int)} returns null, exactly as the real client's does for a
 * view that has gone — and so exercises the real null path rather than a
 * simulation of it.
 */
public class ChatterOverlayTest
{
	private static final int VARROCK_NORTH = 12853;
	private static final WorldPoint PLAYER = new WorldPoint(3220, 3420, 0);

	private FakeClient client;
	private FakeRegions regions;
	private FakeConfig config;
	private EntityScene scene;
	private FakeWorldView view;
	private Graphics2D graphics;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		regions = new FakeRegions();
		config = new FakeConfig();
		scene = new EntityScene(client, regions, config, config.overrides());
		view = FakeWorldView.around(PLAYER, VARROCK_NORTH);

		// A real Graphics2D, off a 1x1 image: getFontMetrics() has to work for the
		// real Perspective call in the projection test, and a stub Graphics2D would
		// be four hundred throwing methods for no gain.
		graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	@Test
	public void oneLineIsDrawnForEachTalkingCitizenAndNoneForTheSilentOnes()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		EntityDefinition alsoTalker = regions.talker(VARROCK_NORTH, 3221, 3421, "Lovely weather.");
		EntityDefinition silent = regions.citizen(VARROCK_NORTH, 3222, 3421, 0);
		spawn(talker, alsoTalker, silent);

		RecordingOverlay overlay = new RecordingOverlay();

		// Nobody is talking yet: the overlay must draw nothing rather than draw a
		// blank line per citizen.
		overlay.render(graphics);
		assertTrue("a scene where nobody is talking draws nothing", overlay.drawn.isEmpty());

		say(talker, "Busy today.");
		say(alsoTalker, "Lovely weather.");
		overlay.render(graphics);

		assertEquals("one line per talking citizen and no more", 2, overlay.drawn.size());
		assertTrue(overlay.drawn.contains("Busy today."));
		assertTrue(overlay.drawn.contains("Lovely weather."));
	}

	/**
	 * The hard off switch, upstream issue #35, on the frame path.
	 *
	 * <p>Checked here as well as in {@link CitizenChatter} so that unticking the box
	 * empties the screen on the same frame rather than on the next game tick.
	 */
	@Test
	public void theHardOffSwitchStopsTheOverlayDrawingAnything()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);
		say(talker, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);
		assertEquals("the fixture has to draw something first", 1, overlay.drawn.size());

		config.setOverheadText(false);
		overlay.drawn.clear();
		overlay.projections = 0;
		overlay.render(graphics);

		assertTrue("nothing may be drawn with overhead chatter off", overlay.drawn.isEmpty());
		assertEquals("and nothing may even be projected — the check is the first line",
			0, overlay.projections);
	}

	/**
	 * A citizen the client no longer has registered contributes nothing, on the very
	 * next frame.
	 *
	 * <p>The remark is deliberately left set on the wrapper here. In the running
	 * plugin {@code despawn()} clears it, and {@code CitizenChatterTest} pins that;
	 * this test unregisters the object <i>behind</i> the wrapper's back so that the
	 * only thing standing between a stale remark and a bubble drawn over empty
	 * ground is the overlay's own {@code isActive()} check. Without it, "the text
	 * vanishes" would be true only because something else remembered to clear it.
	 */
	@Test
	public void aDespawnedCitizensTextVanishesOnTheNextFrame()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);
		say(talker, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);
		assertEquals(1, overlay.drawn.size());

		// The visibility pass takes it off the screen — through the config, which is
		// the real path — and then the remark is put back by hand.
		config.disable(City.VARROCK);
		scene.updateVisibility(PLAYER, view);
		assertEquals("the fixture has to actually despawn it", 0, scene.countActive());
		say(talker, "Busy today.");

		overlay.drawn.clear();
		overlay.render(graphics);

		assertTrue("text must never be drawn for a citizen the client is not rendering",
			overlay.drawn.isEmpty());
	}

	/**
	 * The position comes from the object, per frame, not from the authored tile.
	 *
	 * <p>This is the drifting-text half. A wandering citizen's authored tile is
	 * where it started, not where it is; projecting from the definition would leave
	 * the text standing still while its citizen walked away from it.
	 */
	@Test
	public void theTextFollowsTheObjectRatherThanTheAuthoredTile()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);
		say(talker, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertEquals(1, overlay.projectedAt.size());
		LocalPoint expected = scene.wrapperFor(talker).getRenderLocation();
		assertNotNull("the fixture has to be placed", expected);
		assertEquals("the overlay must project the object's own live position",
			expected.getX(), overlay.projectedAt.get(0).getX());
		assertEquals(expected.getY(), overlay.projectedAt.get(0).getY());
	}

	/**
	 * A projection that fails draws nothing and does not throw — using the real
	 * {@code Perspective} call, not a stand-in for it.
	 *
	 * <p>Behind the camera, off the edge of the viewport, or on a world view the
	 * client no longer has: all three happen constantly and none is an error. This
	 * runs sixty times a second per talking citizen, so a throw here would be sixty
	 * stack traces a second <i>and</i> would abandon every citizen after the
	 * offender on every one of them.
	 */
	@Test
	public void aProjectionThatFailsDrawsNothingRatherThanThrowing()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);
		say(talker, "Busy today.");

		// No override of textLocation: this really does call
		// Perspective.getCanvasTextLocation, which asks the client for the world
		// view by id and returns null when there is none.
		DrawRecordingOverlay overlay = new DrawRecordingOverlay();

		assertNull("the real projection has to fail for this fixture, or the test proves nothing",
			overlay.textLocation(graphics, scene.wrapperFor(talker).getRenderLocation(), "Busy today."));

		overlay.render(graphics);

		assertTrue("a failed projection draws nothing", overlay.drawn.isEmpty());
	}

	/**
	 * A citizen with no model yet — a cold model cache — has no position to project,
	 * and that must not be a null dereference on the frame path.
	 */
	@Test
	public void aCitizenWithNoObjectYetIsSkipped()
	{
		client.setCacheCold(true);
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		regions.file(VARROCK_NORTH, talker);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		assertEquals("a cold cache must not have spawned anything", 0, scene.countActive());

		say(talker, "Busy today.");

		RecordingOverlay overlay = new RecordingOverlay();
		overlay.render(graphics);

		assertTrue(overlay.drawn.isEmpty());
	}

	// --- helpers ------------------------------------------------------------

	private void spawn(EntityDefinition... entities)
	{
		regions.file(VARROCK_NORTH, entities);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		assertTrue("the fixture has to actually spawn", scene.countActive() > 0);
	}

	/**
	 * Puts a specific remark on a specific citizen.
	 *
	 * <p>Set directly rather than by running the chatter until it happens: these
	 * tests are about the frame path, and driving them through the cadence would make
	 * every one of them also a test of the cadence.
	 */
	private void say(EntityDefinition definition, String expected)
	{
		CitizenRemarks remarks = scene.wrapperFor(definition).getRemarks();
		assertNotNull(remarks);
		remarks.say(0, Integer.MAX_VALUE);
		assertEquals("the fixture's citizen has exactly one thing to say, so this is deterministic",
			expected, remarks.text());
	}

	/**
	 * The overlay with both seams recorded and the projection replaced by a fixed
	 * point, so the loop's decisions are observable without a camera.
	 */
	private final class RecordingOverlay extends ChatterOverlay
	{
		private final List<String> drawn = new ArrayList<>();
		private final List<LocalPoint> projectedAt = new ArrayList<>();
		private int projections;

		private RecordingOverlay()
		{
			super(null, client, scene, config);
		}

		@Override
		@Nullable
		Point textLocation(Graphics2D graphics, LocalPoint at, String text)
		{
			projections++;
			projectedAt.add(at);
			return new Point(100, 200);
		}

		@Override
		void drawRemark(Graphics2D graphics, Point at, String text)
		{
			drawn.add(text);
		}
	}

	/**
	 * Only the draw is recorded; the projection is the real one. Used by the single
	 * test that wants {@code Perspective} to actually run.
	 */
	private final class DrawRecordingOverlay extends ChatterOverlay
	{
		private final List<String> drawn = new ArrayList<>();

		private DrawRecordingOverlay()
		{
			super(null, client, scene, config);
		}

		@Override
		void drawRemark(Graphics2D graphics, Point at, String text)
		{
			drawn.add(text);
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Constants;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The off switches, first — because that is the order they were built in and the
 * reason they were built in it.
 *
 * <p>Overhead-text spam was the predecessor's single loudest complaint: 144
 * upvotes on "please add an option to shut them up", a mute toggle its author
 * promised and never shipped, and upstream issue #35 open from release day. So
 * every dial gets a test that fails if the dial stops working, and the two
 * granularities — the whole feature off, and this one citizen muted — are proven
 * to be different things rather than the same setting spelled twice.
 *
 * <p><b>The fixtures are deliberately not uniform.</b> Every scene here mixes
 * citizens that can talk with citizens that cannot, and puts them at different
 * distances, because 98 of the 142 shipped citizens have nothing authored and
 * because the radius and the cap are read off the tiles. A crowd where everybody
 * is identical could not tell "the chatter skipped the silent ones" from "the
 * chatter iterated everybody", nor "the cap bound" from "only three were
 * eligible".
 */
public class CitizenChatterTest
{
	private static final int VARROCK_NORTH = 12853;

	/** In 12853, and the tile every distance below is measured from. */
	private static final WorldPoint PLAYER = new WorldPoint(3220, 3420, 0);

	private FakeClient client;
	private FakeRegions regions;
	private FakeConfig config;
	private EntityScene scene;
	private FakeWorldView view;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		regions = new FakeRegions();
		config = new FakeConfig();
		scene = new EntityScene(client, regions, config, config.overrides());
		view = FakeWorldView.around(PLAYER, VARROCK_NORTH);
	}

	// --- the hard off switch (issue #35) -------------------------------------

	@Test
	public void theHardOffSwitchMeansNobodyEverStartsTalking()
	{
		spawn(regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 12));
		config.setOverheadText(false);

		runTicks(400);

		assertEquals("with overhead chatter off, nothing may start", 0, scene.countTalking());
	}

	/**
	 * Switching it off mid-conversation empties the screen, and does so through the
	 * settings path rather than waiting for a game tick — a toggle that visibly lags
	 * the click reads as a toggle that did not work.
	 */
	@Test
	public void switchingItOffClearsWhatIsAlreadyOnScreenWithoutAdvancingTheClock()
	{
		spawn(regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 12));

		runTicks(400);
		assertTrue("the fixture has to get somebody talking first", scene.countTalking() > 0);

		int clockBefore = scene.getChatterTick();
		config.setOverheadText(false);
		scene.onSettingsChanged(PLAYER, view);

		assertEquals("the screen is empty on the click", 0, scene.countTalking());
		assertEquals("and a settings change is not a game tick",
			clockBefore, scene.getChatterTick());
	}

	// --- the per-citizen mute -----------------------------------------------

	/**
	 * The second granularity, and the one people actually complained at: it was
	 * never "no citizen anywhere should speak", it was "this one, outside the bank,
	 * every six seconds".
	 */
	@Test
	public void aMutedCitizenNeverStartsARemarkAndNobodyElseIsAffected()
	{
		List<EntityDefinition> crowd = regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 12);
		spawn(crowd);

		EntityDefinition silenced = crowd.get(0);
		config.overrides().mute(silenced);

		// Generous cap, so "it never talked" cannot be the cap's doing.
		config.setMaxConcurrentRemarks(CitizenChatter.MAX_MAX_CONCURRENT);

		boolean somebodyElseTalked = false;
		for (int tick = 0; tick < 600; tick++)
		{
			scene.onGameTick(PLAYER, view);
			assertFalse("a muted citizen must never start a remark",
				talking(silenced));
			somebodyElseTalked |= scene.countTalking() > 0;
		}

		assertTrue("and the mute must not have silenced the street", somebodyElseTalked);
	}

	/**
	 * Muting somebody who is already mid-remark has to be different from muting
	 * somebody who is silent, or the "Mute" menu entry would appear to do nothing
	 * for up to the whole dwell.
	 */
	@Test
	public void mutingIsOnlyHalfTheJobIfSomebodyIsAlreadyTalking()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);

		CitizenRemarks remarks = remarksOf(talker);
		runUntilTalking(remarks);

		config.overrides().mute(talker);
		scene.onGameTick(PLAYER, view);

		assertTrue("the mute alone does not cut a remark short — the dwell is still running, "
				+ "which is why CitizenMenu clears it on the click as well",
			remarks.isTalking());
	}

	// --- cadence ------------------------------------------------------------

	/**
	 * The interval is a real dial: a longer one produces strictly fewer remarks
	 * over the same number of ticks.
	 */
	@Test
	public void alongerIntervalMeansFewerRemarks()
	{
		int chatty = remarksStartedOver(2000, CitizenChatter.MIN_ROLL_INTERVAL_TICKS);
		int quiet = remarksStartedOver(2000, 300);

		assertTrue("a 10-tick interval has to be chattier than a 300-tick one, got "
			+ chatty + " vs " + quiet, chatty > quiet);
		assertTrue("and the chatty end has to actually produce something", chatty > 0);
	}

	/**
	 * The dwell is a real dial too, and it is the one that decides how long a
	 * bubble is on screen — the half of the cadence complaint that is not "how
	 * often".
	 */
	@Test
	public void theDwellDecidesHowLongARemarkStaysUp()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);
		config.setRemarkDwellTicks(7);

		CitizenRemarks remarks = remarksOf(talker);
		int startedAt = runUntilTalking(remarks);

		int upFor = 0;
		while (remarks.isTalking())
		{
			scene.onGameTick(PLAYER, view);
			upFor++;
			assertTrue("a 7-tick dwell must not survive 20 ticks (started at " + startedAt + ")",
				upFor <= 20);
		}

		assertEquals("the remark comes down on the tick the dwell expires", 7, upFor);
	}

	// --- the units, and the saturation guard ---------------------------------
	//
	// Every constant in CitizenChatter is a wall-clock duration written in game
	// ticks, and this plugin once shipped two of them in the wrong unit: a dwell of
	// 120 that was the predecessor's *client* ticks (2.4 seconds) became 72 seconds,
	// and an interval of 60 that was the predecessor's *seconds* became 36. Dwell
	// exceeded interval, so a bubble could never expire before its citizen's next
	// chance to speak and the overhead text saturated permanently — the one
	// complaint the whole feature exists to answer, shipped as the default. The
	// three tests below are the guard: the arithmetic, the whole configurable range,
	// and the street actually going quiet again.

	/**
	 * The defaults, in milliseconds, checked against the client's own clock rather
	 * than against a number in a comment.
	 *
	 * <p>{@link Constants} is the primary source for both tick lengths, so a build
	 * against a client whose game tick was not 600ms would fail here rather than
	 * quietly running the cadence at a different speed.
	 */
	@Test
	public void theDefaultCadenceIsAMinuteApartAndAFewSecondsLong()
	{
		assertEquals("a game tick, which is the unit every constant in CitizenChatter is in",
			600, Constants.GAME_TICK_LENGTH);
		assertEquals("a client tick — thirty to a game tick, and the ratio the dwell was "
				+ "once wrong by", 20, Constants.CLIENT_TICK_LENGTH);
		assertEquals("which is exactly the factor that turned 2.4 seconds into 72",
			30, Constants.GAME_TICK_LENGTH / Constants.CLIENT_TICK_LENGTH);

		int intervalMillis = CitizenChatter.DEFAULT_ROLL_INTERVAL_TICKS * Constants.GAME_TICK_LENGTH;
		assertEquals("a chance to speak once a minute, which is the predecessor's cadence "
				+ "converted rather than copied", 60_000, intervalMillis);

		int dwellMillis = CitizenChatter.DEFAULT_DWELL_TICKS * Constants.GAME_TICK_LENGTH;
		assertTrue("a remark has to stay up long enough to read the longest shipped line "
				+ "(11 words, about 3.3 seconds) and not much longer, was " + dwellMillis + "ms",
			dwellMillis >= 3_000 && dwellMillis <= 10_000);

		assertTrue("and it has to be comfortably shorter than the interval, not merely shorter: "
				+ dwellMillis + "ms of every " + intervalMillis + "ms",
			dwellMillis * 4 <= intervalMillis);

		int maxDwellMillis = CitizenChatter.MAX_DWELL_TICKS * Constants.GAME_TICK_LENGTH;
		assertTrue("even the far end of the dwell dial has to read as somebody saying something "
				+ "rather than as a label stuck to their head — it was 600 ticks, six minutes, "
				+ "while these numbers were being read as client ticks. Now " + maxDwellMillis + "ms",
			maxDwellMillis <= 20_000);
		assertTrue("and it has to stay above the tightest interval, so that asking for a "
				+ "saturating pair is still something a user can do and the clamp that refuses "
				+ "it is still live code",
			CitizenChatter.MAX_DWELL_TICKS > CitizenChatter.MIN_ROLL_INTERVAL_TICKS);

		assertTrue("the same has to hold at the ends of both sliders, or the ranges disagree "
				+ "with the defaults they bracket",
			CitizenChatter.MIN_DWELL_TICKS <= CitizenChatter.DEFAULT_DWELL_TICKS
				&& CitizenChatter.DEFAULT_DWELL_TICKS <= CitizenChatter.MAX_DWELL_TICKS
				&& CitizenChatter.MIN_ROLL_INTERVAL_TICKS <= CitizenChatter.DEFAULT_ROLL_INTERVAL_TICKS
				&& CitizenChatter.DEFAULT_ROLL_INTERVAL_TICKS <= CitizenChatter.MAX_ROLL_INTERVAL_TICKS);
	}

	/**
	 * <b>No pair of values the config can hold — from the sliders, from a hand-edited
	 * {@code settings.properties}, or from a profile synced off another install — can
	 * leave a remark up when its citizen's next roll comes round.</b>
	 *
	 * <p>Every combination, one tick past both ends of both ranges, because that is
	 * the only way to state "no combination can saturate" as a test rather than as an
	 * intention. Two {@code @Range} annotations cannot express this between them:
	 * neither one can see the other's value.
	 */
	@Test
	public void noCadenceTheConfigCanHoldLetsARemarkOutliveItsCitizensNextRoll()
	{
		assertTrue("the clamp must never have to push the dwell below its own minimum, "
				+ "which needs the tightest interval to leave room for it",
			CitizenChatter.MIN_ROLL_INTERVAL_TICKS - 1 >= CitizenChatter.MIN_DWELL_TICKS);

		int clamped = 0;
		for (int interval = CitizenChatter.MIN_ROLL_INTERVAL_TICKS - 5;
			 interval <= CitizenChatter.MAX_ROLL_INTERVAL_TICKS + 5; interval++)
		{
			int effectiveInterval = CitizenChatter.effectiveIntervalTicks(interval);
			assertTrue("interval " + interval + " clamped to " + effectiveInterval,
				effectiveInterval >= CitizenChatter.MIN_ROLL_INTERVAL_TICKS
					&& effectiveInterval <= CitizenChatter.MAX_ROLL_INTERVAL_TICKS);

			for (int dwell = CitizenChatter.MIN_DWELL_TICKS - 5;
				 dwell <= CitizenChatter.MAX_DWELL_TICKS + 5; dwell++)
			{
				int effectiveDwell = CitizenChatter.effectiveDwellTicks(dwell, interval);

				assertTrue("dwell " + dwell + " with interval " + interval + " came out as "
						+ effectiveDwell + " against an interval of " + effectiveInterval
						+ " — a remark that outlives its citizen's next roll is the saturation bug",
					effectiveDwell < effectiveInterval);
				assertTrue("dwell " + dwell + " came out as " + effectiveDwell
						+ ", outside its own range", effectiveDwell >= CitizenChatter.MIN_DWELL_TICKS
					&& effectiveDwell <= CitizenChatter.MAX_DWELL_TICKS);

				if (effectiveDwell != Math.max(CitizenChatter.MIN_DWELL_TICKS,
					Math.min(CitizenChatter.MAX_DWELL_TICKS, dwell)))
				{
					clamped++;
				}
			}
		}

		assertTrue("the interval clamp has to actually bind somewhere, or this test is "
				+ "asserting about unreachable code", clamped > 0);

		assertEquals("the tightest interval a user can ask for, with the longest dwell: one "
				+ "tick of silence between the bubble going and the next roll",
			CitizenChatter.MIN_ROLL_INTERVAL_TICKS - 1,
			CitizenChatter.effectiveDwellTicks(
				CitizenChatter.MAX_DWELL_TICKS, CitizenChatter.MIN_ROLL_INTERVAL_TICKS));

		assertEquals("and the shipped defaults are nowhere near it, so the clamp never "
				+ "silently changes what the user asked for",
			CitizenChatter.DEFAULT_DWELL_TICKS,
			CitizenChatter.effectiveDwellTicks(
				CitizenChatter.DEFAULT_DWELL_TICKS, CitizenChatter.DEFAULT_ROLL_INTERVAL_TICKS));
	}

	/**
	 * The regression, at the level a player would have seen it: with the defaults and
	 * a dozen talkative citizens standing next to you, the street is quiet far more
	 * often than not.
	 *
	 * <p>With the saturating defaults this shipped with, {@code silentTicks} was zero
	 * — every citizen that ever spoke was still speaking, forever. It takes a
	 * thousand-tick run to see that, which is why manual QA did not: the off switches
	 * all worked, and you had to stand and watch text accumulate for a minute.
	 */
	@Test
	public void atTheDefaultsTheOverheadTextClearsInsteadOfPilingUp()
	{
		spawn(regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 12));

		int silentTicks = 0;
		int peak = 0;
		for (int tick = 0; tick < 3000; tick++)
		{
			scene.onGameTick(PLAYER, view);
			int talking = scene.countTalking();
			peak = Math.max(peak, talking);
			if (talking == 0)
			{
				silentTicks++;
			}
		}

		assertTrue("twelve citizens with something to say have to say it sometime, or this "
			+ "test proves nothing", peak > 0);
		assertTrue("a " + CitizenChatter.DEFAULT_DWELL_TICKS + "-tick dwell inside a "
				+ CitizenChatter.DEFAULT_ROLL_INTERVAL_TICKS + "-tick interval has to leave the "
				+ "screen empty most of the time — it was empty on " + silentTicks + " of 3000 ticks",
			silentTicks > 1500);
	}

	/**
	 * And when a user asks for the saturating combination outright — the longest dwell
	 * on the tightest cadence — the bubble still comes down.
	 *
	 * <p>Driven through the scene rather than through
	 * {@link CitizenChatter#effectiveDwellTicks} so that the clamp is proved to be on
	 * the path a config value actually travels, not merely available on a static
	 * method nobody calls.
	 */
	@Test
	public void theSaturatingCombinationIsClampedOnThePathTheConfigTravels()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);
		config.setRemarkIntervalTicks(CitizenChatter.MIN_ROLL_INTERVAL_TICKS)
			.setRemarkDwellTicks(CitizenChatter.MAX_DWELL_TICKS);

		CitizenRemarks remarks = remarksOf(talker);
		int startedAt = runUntilTalking(remarks);

		int upFor = 0;
		while (remarks.isTalking())
		{
			scene.onGameTick(PLAYER, view);
			upFor++;
			assertTrue("a dwell of " + CitizenChatter.MAX_DWELL_TICKS + " on an interval of "
					+ CitizenChatter.MIN_ROLL_INTERVAL_TICKS + " has to be clamped, not honoured "
					+ "(started at " + startedAt + ")",
				upFor < CitizenChatter.MIN_ROLL_INTERVAL_TICKS);
		}

		assertEquals("the remark comes down one tick before the next roll",
			CitizenChatter.MIN_ROLL_INTERVAL_TICKS - 1, upFor);
	}

	/**
	 * A value the slider could never produce — a hand-edited profile, or one synced
	 * from another install — must not turn the cadence off or make it divide by
	 * zero.
	 */
	@Test
	public void anImpossibleCadenceIsClampedRatherThanTrusted()
	{
		spawn(regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 8));
		config.setRemarkIntervalTicks(0).setRemarkDwellTicks(-5).setChatterRadius(-1)
			.setMaxConcurrentRemarks(0);

		// The interesting assertion is that this does not throw: an interval of 0
		// reaches Math.floorMod(tick, 0), and a cap of 0 would mean the feature is
		// silently off.
		runTicks(100);

		assertTrue("a cap of 0 clamps to at least one, so the feature is not silently off",
			scene.countTalking() >= 0);
		assertEquals("and the clock still ran", 100, scene.getChatterTick());
	}

	// --- the distance limit -------------------------------------------------

	/**
	 * Only citizens within the chatter radius start talking, and the radius is
	 * measured from the authored tile — the same anchor the cull check uses.
	 */
	@Test
	public void onlyCitizensInsideTheChatterRadiusEverTalk()
	{
		config.setChatterRadius(5);

		// Inside, on the boundary, and outside. Three distances, so "the radius is
		// respected" cannot be satisfied by a fixture where everybody is near.
		EntityDefinition near = regions.talker(VARROCK_NORTH, 3222, 3420, "Near.");
		EntityDefinition boundary = regions.talker(VARROCK_NORTH, 3225, 3420, "On the line.");
		EntityDefinition far = regions.talker(VARROCK_NORTH, 3232, 3420, "Far away.");
		spawn(near, boundary, far);

		assertTrue("all three have to be spawned, or this proves nothing",
			scene.countActive() >= 3);

		boolean nearTalked = false;
		boolean boundaryTalked = false;
		for (int tick = 0; tick < 1200; tick++)
		{
			scene.onGameTick(PLAYER, view);
			nearTalked |= talking(near);
			boundaryTalked |= talking(boundary);
			assertFalse("a citizen 12 tiles away with a 5-tile chatter radius must never talk",
				talking(far));
		}

		assertTrue("the near one has to talk, or the radius is not what stopped the far one",
			nearTalked);
		assertTrue("and the radius is inclusive at its own value", boundaryTalked);
	}

	// --- the concurrency cap ------------------------------------------------

	/**
	 * A crowd cannot produce a wall of text.
	 *
	 * <p>Twenty-four talkers packed inside the chatter radius on the tightest
	 * cadence is well past what the cap allows — without one, roughly twenty would
	 * be on screen at once, which is the complaint restated rather than answered.
	 */
	@Test
	public void theConcurrencyCapBoundsTheNumberOfBubbles()
	{
		spawn(regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 24));
		config.setRemarkIntervalTicks(CitizenChatter.MIN_ROLL_INTERVAL_TICKS)
			.setRemarkDwellTicks(CitizenChatter.MAX_DWELL_TICKS)
			.setMaxConcurrentRemarks(3);

		int peak = 0;
		for (int tick = 0; tick < 1000; tick++)
		{
			scene.onGameTick(PLAYER, view);
			peak = Math.max(peak, scene.countTalking());
			assertTrue("the cap is 3 and " + scene.countTalking() + " were talking on tick " + tick,
				scene.countTalking() <= 3);
		}

		assertEquals("and the cap has to actually bind, or this test proves nothing", 3, peak);
	}

	/**
	 * Raising the cap raises the ceiling. Without this, a cap that was accidentally
	 * hard-coded to 3 would pass the test above.
	 */
	@Test
	public void raisingTheCapRaisesTheCeiling()
	{
		spawn(regions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 24));
		config.setRemarkIntervalTicks(CitizenChatter.MIN_ROLL_INTERVAL_TICKS)
			.setRemarkDwellTicks(CitizenChatter.MAX_DWELL_TICKS)
			.setMaxConcurrentRemarks(8);

		int peak = 0;
		for (int tick = 0; tick < 1000; tick++)
		{
			scene.onGameTick(PLAYER, view);
			peak = Math.max(peak, scene.countTalking());
		}

		assertEquals(8, peak);
	}

	// --- who is eligible at all ---------------------------------------------

	/**
	 * A citizen with nothing authored never talks, however long the scene runs —
	 * and it is in the same scene as citizens that do, so this is a claim about the
	 * filter rather than about an empty scene.
	 */
	@Test
	public void aCitizenWithNothingAuthoredNeverTalks()
	{
		EntityDefinition silent = regions.citizen(VARROCK_NORTH, 3221, 3420, 0);
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3222, 3420, "Busy today.");
		spawn(silent, talker);

		assertNull("the silent one must not even have a remark holder",
			scene.wrapperFor(silent).getRemarks());

		boolean talkerTalked = false;
		for (int tick = 0; tick < 1200; tick++)
		{
			scene.onGameTick(PLAYER, view);
			talkerTalked |= talking(talker);
		}

		assertTrue("the fixture's talker has to talk, or the scene never ran", talkerTalked);
	}

	/**
	 * A citizen the visibility pass has deactivated stops talking as part of being
	 * deactivated.
	 *
	 * <p>This is the structural half of the orphaned-text fix, and the assertion is
	 * deliberately made <b>without</b> running a chatter tick: only
	 * {@code updateVisibility} is called, so the only thing that can have silenced
	 * the citizen is {@code despawn()} itself. Running a game tick instead would also
	 * pass with the silencing removed, because the chatter clears inactive citizens
	 * too — and a test that cannot tell the two apart is a test that pins neither.
	 */
	@Test
	public void aCitizenThatLeavesTheScreenStopsTalkingAsPartOfLeaving()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);

		CitizenRemarks remarks = remarksOf(talker);
		runUntilTalking(remarks);

		// Untick its city. The visibility pass despawns it, and the despawn silences
		// it — one mechanism, not two.
		config.disable(City.VARROCK);
		scene.updateVisibility(PLAYER, view);

		assertEquals("the fixture has to actually despawn it", 0, scene.countActive());
		assertFalse("despawning is what has to stop the remark, on its own",
			remarks.isTalking());
	}

	/**
	 * And the chatter clears a remark on a citizen the client has dropped anyway.
	 *
	 * <p>A second guard for the same outcome, and the only way to reach it is to run
	 * the chatter on its own — through the scene, {@code updateVisibility} always goes
	 * first and its despawn has already done the job. So this drives a
	 * {@link CitizenChatter} directly, which is also the only test here that proves
	 * the class works without a scene wrapped around it. In the running plugin this
	 * branch should never fire; it is here because "text hanging over empty ground"
	 * is the bug the whole design is aimed at, and one guard for it is not enough.
	 */
	@Test
	public void theChatterAlsoClearsARemarkOnACitizenTheClientHasDropped()
	{
		EntityDefinition talker = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(talker);

		CitizenRemarks remarks = remarksOf(talker);
		runUntilTalking(remarks);

		// Off the screen, then the remark put back by hand: nothing in the despawn
		// path can be what clears it this time.
		config.disable(City.VARROCK);
		scene.updateVisibility(PLAYER, view);
		remarks.say(0, Integer.MAX_VALUE);
		assertTrue(remarks.isTalking());

		List<LivelyEntity> justThatOne = new ArrayList<>();
		justThatOne.add(scene.wrapperFor(talker));
		new CitizenChatter(config, config.overrides()).onGameTick(justThatOne, PLAYER);

		assertFalse("a remark on an unregistered citizen must not survive a chatter pass",
			remarks.isTalking());
	}

	// --- helpers ------------------------------------------------------------

	private void spawn(EntityDefinition... entities)
	{
		spawn(new ArrayList<>(java.util.Arrays.asList(entities)));
	}

	private void spawn(List<EntityDefinition> entities)
	{
		regions.file(VARROCK_NORTH, entities);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		assertTrue("the fixture has to actually spawn", scene.countActive() > 0);
	}

	private void runTicks(int ticks)
	{
		for (int i = 0; i < ticks; i++)
		{
			scene.onGameTick(PLAYER, view);
		}
	}

	/**
	 * Runs the scene until a given citizen is talking.
	 *
	 * @return the tick it started on
	 */
	private int runUntilTalking(CitizenRemarks remarks)
	{
		for (int tick = 0; tick < 5000; tick++)
		{
			scene.onGameTick(PLAYER, view);
			if (remarks.isTalking())
			{
				return tick;
			}
		}
		throw new AssertionError("nobody talked in 5000 ticks — the fixture is wrong, not the code");
	}

	/**
	 * How many remarks started over a run at a given interval.
	 *
	 * <p>Counted by watching the text change rather than by asking the chatter,
	 * because "how often does a citizen speak" is a fact about the screen.
	 */
	private int remarksStartedOver(int ticks, int interval)
	{
		FakeClient freshClient = new FakeClient();
		FakeRegions freshRegions = new FakeRegions();
		FakeConfig freshConfig = new FakeConfig();
		freshConfig.setRemarkIntervalTicks(interval).setRemarkDwellTicks(CitizenChatter.MIN_DWELL_TICKS);
		EntityScene freshScene = new EntityScene(
			freshClient, freshRegions, freshConfig, freshConfig.overrides());

		List<EntityDefinition> crowd = freshRegions.talkingCrowd(VARROCK_NORTH, 3218, 3418, 6);
		freshRegions.file(VARROCK_NORTH, crowd);
		freshScene.syncRegions(view);
		freshScene.updateVisibility(PLAYER, view);

		List<CitizenRemarks> holders = new ArrayList<>();
		for (EntityDefinition definition : crowd)
		{
			CitizenRemarks remarks = freshScene.wrapperFor(definition).getRemarks();
			assertNotNull(remarks);
			holders.add(remarks);
		}

		boolean[] wasTalking = new boolean[holders.size()];
		int started = 0;
		for (int tick = 0; tick < ticks; tick++)
		{
			freshScene.onGameTick(PLAYER, view);
			for (int i = 0; i < holders.size(); i++)
			{
				boolean now = holders.get(i).isTalking();
				if (now && !wasTalking[i])
				{
					started++;
				}
				wasTalking[i] = now;
			}
		}
		return started;
	}

	private boolean talking(EntityDefinition definition)
	{
		CitizenRemarks remarks = scene.wrapperFor(definition).getRemarks();
		return remarks != null && remarks.isTalking();
	}

	private CitizenRemarks remarksOf(EntityDefinition definition)
	{
		CitizenRemarks remarks = scene.wrapperFor(definition).getRemarks();
		assertNotNull("the fixture has to have something to say", remarks);
		return remarks;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The index that puts a name to a stored uuid, and a citizen count on a city card.
 *
 * <p>Both are things the live scene cannot answer. {@link EntityScene} only knows about
 * regions the loaded scene covers, and the whole point of the panel's hidden-and-muted
 * list is that you are usually a city away from the person you changed your mind about.
 */
public class CitizenDirectoryTest
{
	/**
	 * The card counts are the dataset's, city by city.
	 *
	 * <p>The same nine numbers {@code RegionDataLoaderTest.everyCityHoldsTheNumberOf
	 * CitizensItIsSupposedTo} pins, reached by a different path, and written out rather
	 * than recomputed here on purpose: computing the expectation the same way the code
	 * under test computes it is how you get a test that cannot fail. These are the
	 * numbers a user reads off a card, so they are worth stating twice.
	 *
	 * <p>All nine rather than a sample, because a card that quietly showed the wrong
	 * city's roster is exactly the copy-paste this shape of loop invites — and only a
	 * table where the numbers differ can see it. They do differ: Varrock is 71 and
	 * Edgeville is 22.
	 */
	@Test
	public void everyCardsCitizenCountIsWhatTheDatasetHolds()
	{
		Map<City, Integer> expected = new EnumMap<>(City.class);
		expected.put(City.AL_KHARID, 24);
		expected.put(City.ARDOUGNE, 24);
		expected.put(City.CATHERBY, 24);
		expected.put(City.DRAYNOR, 24);
		expected.put(City.EDGEVILLE, 22);
		expected.put(City.FALADOR, 26);
		expected.put(City.GRAND_EXCHANGE, 24);
		expected.put(City.LUMBRIDGE, 30);
		expected.put(City.VARROCK, 71);
		assertEquals("every city has to be listed, or one could empty out unnoticed",
			City.values().length, expected.size());

		CitizenDirectory directory = shipped();

		int total = 0;
		for (City city : City.values())
		{
			assertEquals("the card for " + city.getLabel(),
				(int) expected.get(city), directory.citizenCount(city));
			total += directory.citizenCount(city);
		}

		assertEquals("and the nine cards between them account for every shipped citizen",
			269, total);
		assertEquals("which is also how many the index holds", 269, directory.size());
	}

	/**
	 * Every shipped citizen can be named, and every one is filed under the city whose
	 * checkbox governs it.
	 *
	 * <p>Walks the dataset rather than sampling it: an index built from a loop over
	 * {@code City.values()} can miss a whole region — a city naming a file that does not
	 * parse is skipped rather than fatal, deliberately — and 268 of 269 is a defect no
	 * total would show, because the total is what the same loop produced.
	 */
	@Test
	public void everyShippedCitizenIsInTheIndexUnderItsOwnCity()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CitizenDirectory directory = new CitizenDirectory(loader);

		int checked = 0;
		for (City city : City.values())
		{
			for (int regionId : city.getRegionIds())
			{
				RegionDefinition region = loader.loadRegion(regionId);
				assertNotNull("region " + regionId + " failed to load", region);

				for (EntityDefinition definition : region.getEntities())
				{
					if (!definition.getType().isCitizen())
					{
						continue;
					}

					CitizenDirectory.Entry entry = directory.find(definition.getUuid());
					assertNotNull(definition.label() + " is in " + regionId
						+ ".json and the directory cannot place it", entry);
					assertEquals(definition.label() + " belongs to the city whose file ships it",
						city, entry.getCity());
					assertEquals(definition.getName(), entry.getName());
					checked++;
				}
			}
		}

		assertEquals("a walk that checked nothing would pass", 269, checked);
	}

	/**
	 * Scenery is not in the index, and that is not an omission.
	 *
	 * <p>A {@code sceneryRoster} record carries no name — {@code EntityRecord} says so —
	 * and {@code CitizenMenu} offers neither Hide nor Mute on one, so a crate can never
	 * turn up in the panel's list. Indexing 42 nameless props would only mean 42 rows
	 * reading "Unnamed citizen" if it ever did.
	 */
	@Test
	public void sceneryIsNotIndexed()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CitizenDirectory directory = new CitizenDirectory(loader);

		int scenery = 0;
		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull(region);
			for (EntityDefinition definition : region.getEntities())
			{
				if (definition.getType().isCitizen())
				{
					continue;
				}

				assertNull("scenery has no name to show and no menu to be hidden from: "
					+ definition.label(), directory.find(definition.getUuid()));
				scenery++;
			}
		}

		assertEquals("the dataset's 42 props, or this checked nothing", 42, scenery);
	}

	// --- the second tier -------------------------------------------------------

	/**
	 * <b>An ordinary profile never pays for the echo derivation.</b>
	 *
	 * <p>The second tier re-runs {@link CitizenEcho#echoesOfRegion} over all 27 region
	 * files, which is materially more work than the parse it follows — and it is only
	 * ever needed for a uuid the authored tier cannot place. So the claim is about cost,
	 * and no count of results could make it: the index would answer exactly the same
	 * questions with the tier built eagerly. {@link CitizenDirectory#hasBuiltEchoIndex()}
	 * exists so this can be asserted rather than reasoned about.
	 */
	@Test
	public void namingAnAuthoredCitizenDoesNotBuildTheEchoIndex()
	{
		CitizenDirectory directory = shipped();

		for (UUID uuid : directory.authoredUuids())
		{
			assertNotNull(directory.find(uuid));
		}
		assertEquals("the fixture has to have asked about something", 269,
			directory.authoredUuids().size());

		assertFalse("269 authored lookups must not have derived a single echo",
			directory.hasBuiltEchoIndex());
	}

	/**
	 * A hidden echo is named, through the tier that exists for it.
	 *
	 * <p>Echoes are hideable like anybody else — the config item for the density dial
	 * says as much, "hiding one does not hide the citizen it came from" — so a stored
	 * uuid really can be one, and a panel that could not place it would show a row of
	 * hexadecimal for the one figure whose whole identity is that it is anonymous.
	 *
	 * <p>The uuid is derived here the same way {@link EntityScene#ensureBuilt} derives
	 * it: from the region's <b>whole</b> roster. Deriving one citizen at a time produces
	 * different tiles and different uuids, so a fixture that took a shortcut would be
	 * asking about an echo the plugin never builds.
	 */
	@Test
	public void aHiddenEchoIsNamedThroughTheSecondTier()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		CitizenDirectory directory = new CitizenDirectory(loader);

		RegionDefinition varrock = loader.loadRegion(12852);
		assertNotNull(varrock);
		List<EntityDefinition> echoes = CitizenEcho.echoesOfRegion(varrock.getEntities());
		assertFalse("region 12852 has to seed at least one echo for this to mean anything",
			echoes.isEmpty());

		EntityDefinition echo = echoes.get(0);
		assertTrue(echo.isEcho());

		CitizenDirectory.Entry entry = directory.find(echo.getUuid());
		assertNotNull("a derived citizen has to be nameable too", entry);
		assertEquals(CitizenEcho.ECHO_NAME, entry.getName());
		assertEquals("and filed under the city whose checkbox governs it, which is its "
				+ "source's rather than its own tile's",
			City.of(echo.getCityRegionId()), entry.getCity());

		assertTrue("asking about an echo is what builds the tier", directory.hasBuiltEchoIndex());
	}

	/**
	 * A uuid nothing in the jar carries is answered with {@code null}, and only after
	 * both tiers have been asked.
	 *
	 * <p>Reachable rather than hypothetical: fifteen places left the dataset on
	 * 2026-08-24, taking their citizens with them, and a profile that hid one of them
	 * still holds the uuid. The panel's job there is to say so and offer to clear it,
	 * which it can only do if this returns null instead of guessing.
	 */
	@Test
	public void aUuidFromAPlaceTheDatasetNoLongerCoversIsSimplyNotFound()
	{
		CitizenDirectory directory = shipped();

		assertNull(directory.find(UUID.fromString("deadbeef-0000-4000-8000-000000000001")));
		assertTrue("and it had to look in both tiers before answering",
			directory.hasBuiltEchoIndex());
	}

	// --- the index is a fact about the jar, not about the loader ---------------

	/**
	 * The index is built once and reused.
	 *
	 * <p>The panel composes a model once a game tick while it is open, and every model
	 * asks the directory nine times for card counts plus once per override row. A
	 * directory that reparsed 376KB of JSON on each of those would be per-tick file
	 * work in a plugin whose performance argument is that it does almost none.
	 *
	 * <p>Counted through {@link FakeRegions#loadCalls()}, which records every
	 * {@code loadRegion} — so this measures the parse actually happening rather than a
	 * flag saying it did not.
	 */
	@Test
	public void theDatasetIsReadOnceHoweverManyTimesTheIndexIsAsked()
	{
		FakeRegions regions = new FakeRegions();
		regions.file(12852, regions.citizen(12852, 3225, 3360, 0));
		CitizenDirectory directory = new CitizenDirectory(regions);

		assertEquals(1, directory.citizenCount(City.VARROCK));
		int afterFirst = regions.loadCalls().size();
		assertEquals("the first question has to read every region a city claims",
			totalRegions(), afterFirst);

		for (int i = 0; i < 50; i++)
		{
			directory.citizenCount(City.VARROCK);
			directory.citizenCount(City.FALADOR);
			directory.find(UUID.randomUUID());
		}

		// The echo tier is built by the first unplaceable uuid above and then cached too,
		// so the total is two passes over the region list and not fifty-one.
		assertEquals("and nothing after that may read them again",
			2 * totalRegions(), regions.loadCalls().size());
	}

	/**
	 * A city naming a region with no file behind it costs that city's count and nothing
	 * else.
	 *
	 * <p>{@code CityTest} already fails the build for a phantom region id, so this is
	 * the behaviour on the way to that red test rather than a supported state — but the
	 * panel is a surface a user opens, and "the sidebar throws" is a worse way to learn
	 * about a bad region id than "Falador says 0".
	 */
	@Test
	public void aCityWithNoFilesCountsZeroRatherThanFailing()
	{
		FakeRegions regions = new FakeRegions();
		regions.file(12852, regions.citizen(12852, 3225, 3360, 0));
		CitizenDirectory directory = new CitizenDirectory(regions);

		assertEquals(1, directory.citizenCount(City.VARROCK));
		for (City city : City.values())
		{
			if (city != City.VARROCK)
			{
				assertEquals(city + " has no file in this fixture", 0, directory.citizenCount(city));
			}
		}
	}

	/** No uuid may be claimed by two cities, or a row could name the wrong place. */
	@Test
	public void noUuidIsIndexedTwice()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		Set<UUID> seen = new HashSet<>();
		List<String> duplicates = new ArrayList<>();

		for (City city : City.values())
		{
			for (int regionId : city.getRegionIds())
			{
				RegionDefinition region = loader.loadRegion(regionId);
				assertNotNull(region);
				for (EntityDefinition definition : region.getEntities())
				{
					if (definition.getType().isCitizen() && !seen.add(definition.getUuid()))
					{
						duplicates.add(definition.label() + " (" + definition.getUuid() + ")");
					}
				}
			}
		}

		assertEquals("a uuid in two files is a row that names whichever city won: "
			+ duplicates, 0, duplicates.size());
		assertEquals(269, seen.size());
	}

	private static CitizenDirectory shipped()
	{
		return new CitizenDirectory(new RegionDataLoader(TestGson.injected()));
	}

	private static int totalRegions()
	{
		int n = 0;
		for (City city : City.values())
		{
			n += city.getRegionIds().length;
		}
		return n;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.UUID;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The derivation: who seeds an echo, how many, where it stands, what it looks
 * like, and what it is called.
 *
 * <p>Everything here is offline — {@link CitizenEcho#echoesOfRegion} touches nothing
 * but its argument — so these run against the real shipped dataset as well as
 * against hand-built fixtures. The shipped-data tests are the ones that keep the
 * feature's headline claim honest: they recompute the echo count from the 27 shipped
 * region files rather than trusting the number written in a comment, and they are the
 * only tests that can see a citizen colliding with somebody else's echo — a fixture
 * holding one citizen has no other lineage to collide with.
 */
public class CitizenEchoTest
{
	private static final int VARROCK_SOUTH = 12852;

	// --- Who seeds an echo ----------------------------------------------------

	@Test
	public void aCitizenWithNoRecolourPaletteSeedsNothing()
	{
		FakeRegions regions = new FakeRegions();

		assertTrue("nothing to re-deal means no honest way to make it look different",
			echoesOf(regions.citizen(VARROCK_SOUTH, 3225, 3355, 0)).isEmpty());
	}

	@Test
	public void aCitizenWithASinglePairSeedsNothing()
	{
		FakeRegions regions = new FakeRegions();

		assertTrue("one slot cannot be re-dealt into a different slot",
			echoesOf(regions.recoloured(VARROCK_SOUTH, 3225, 3355, 1)).isEmpty());
	}

	@Test
	public void twoPairsSeedOneEchoAndThreeOrMoreSeedTwo()
	{
		FakeRegions regions = new FakeRegions();

		assertEquals("two pairs admit exactly one distinct re-deal",
			1, echoesOf(regions.recoloured(VARROCK_SOUTH, 3225, 3355, 2)).size());
		assertEquals(CitizenEcho.MAX_ECHOES_PER_CITIZEN,
			echoesOf(regions.recoloured(VARROCK_SOUTH, 3230, 3355, 3)).size());
		assertEquals("and the cap holds however rich the palette gets",
			CitizenEcho.MAX_ECHOES_PER_CITIZEN,
			echoesOf(regions.recoloured(VARROCK_SOUTH, 3235, 3355, 11)).size());
	}

	/**
	 * A palette whose {@code replace} values are all the same colour.
	 *
	 * <p>Three shipped citizens are like this ("Brother Keptic", "Dark wizard",
	 * "Ambatu"; a fourth, "Sister Palus", went with region 13622 in the nine-city
	 * cut). Every rotation of {@code [red, red]} is
	 * {@code [red, red]}, so an echo would be a pixel-for-pixel copy of its source
	 * standing two tiles away — which is the twins failure. Counting pairs alone
	 * would have let them through.
	 */
	@Test
	public void aPaletteThatCannotActuallyBeReDealtSeedsNothing()
	{
		assertEquals(0, CitizenEcho.distinctDeals(new short[]{4769, 4769}).length);
		assertEquals(0, CitizenEcho.distinctDeals(new short[]{10508, 10508, 10508}).length);

		// And a palette that repeats in a pattern offers fewer deals than rotations:
		// [a,b,a,b] has three rotations and one distinct result.
		assertEquals(1, CitizenEcho.distinctDeals(new short[]{7, 9, 7, 9}).length);
	}

	// --- The body rule --------------------------------------------------------

	/**
	 * <b>An echo's name says "nobody in particular". Its body has to agree.</b>
	 *
	 * <p>{@link EntityDefinition#echoOf} replaces five things and inherits five
	 * others, and until this rule only the sixth ({@code npcAppearanceId}) was checked
	 * at all. So a gardener's watering can, a butler's chair, a smith's anvil pose and
	 * a citizen with a bench welded into his model all walked into a figure called
	 * {@link CitizenEcho#ECHO_NAME}. The gardener is a photograph.
	 *
	 * <p>Three fixtures for the three ways a body can be doing something, plus the
	 * control that says a plain standing citizen with the same palette still seeds.
	 * The control is the assertion that keeps the other three honest: without it a
	 * gate that refused everything would pass all three.
	 */
	@Test
	public void aCitizenWhoseBodyIsDoingSomethingSeedsNothing()
	{
		FakeRegions regions = new FakeRegions();

		assertFalse("the control: an ordinary standing citizen with this palette seeds",
			echoesOf(regions.recolouredButBusy(
				VARROCK_SOUTH, 3225, 3355, LivelyAnimation.HumanIdle, null, null, 0)).isEmpty());

		assertTrue("sitting on a chair that will not come with it",
			echoesOf(regions.recolouredButBusy(
				VARROCK_SOUTH, 3235, 3355, LivelyAnimation.Sitting, null, null, 0)).isEmpty());
		assertTrue("miming a tool it was authored holding",
			echoesOf(regions.recolouredButBusy(
				VARROCK_SOUTH, 3245, 3355, LivelyAnimation.AnvilBang, null, null, 0)).isEmpty());
		assertTrue("a pose that is about a prop",
			echoesOf(regions.recolouredButBusy(
				VARROCK_SOUTH, 3255, 3355, LivelyAnimation.StandingWithBook, null, null, 0)).isEmpty());

		assertTrue("scenery welded into the body",
			echoesOf(regions.recolouredButBusy(
				VARROCK_SOUTH, 3265, 3355, LivelyAnimation.HumanIdle, null, null, 7719)).isEmpty());
		assertTrue("scaled to fit one piece of the world",
			echoesOf(regions.recolouredButBusy(VARROCK_SOUTH, 3275, 3355,
				LivelyAnimation.HumanIdle, new float[]{-0.5f, -0.5f, -0.5f}, null, 0)).isEmpty());
		assertTrue("nudged off its tile to line up with one piece of the world",
			echoesOf(regions.recolouredButBusy(VARROCK_SOUTH, 3285, 3355,
				LivelyAnimation.HumanIdle, null, new float[]{0f, 0f, -1f}, 0)).isEmpty());

		// A translate of {0,0,0} moves nothing, so it is not "doing something" and a
		// record may carry one. A scale has no such identity — see
		// isAnOrdinaryStandingBody — so there is deliberately no equivalent case for it.
		assertFalse("a translate that does not translate is not 'doing something'",
			echoesOf(regions.recolouredButBusy(VARROCK_SOUTH, 3295, 3355,
				LivelyAnimation.HumanIdle, null, new float[]{0f, 0f, 0f}, 0)).isEmpty());
		assertTrue("but any authored scale is, because {0,0,0} would collapse the figure "
				+ "to a point rather than leave it alone",
			echoesOf(regions.recolouredButBusy(VARROCK_SOUTH, 3305, 3355,
				LivelyAnimation.HumanIdle, new float[]{0f, 0f, 0f}, null, 0)).isEmpty());
	}

	/**
	 * The same rule over the shipped dataset: <b>no echo that ships inherits a body
	 * doing anything</b>.
	 *
	 * <p>Checked against the source rather than against the echo, because the echo is
	 * where the inheritance has already happened — asking the echo would be asking the
	 * code under test to mark its own work. Both are asked anyway, since
	 * {@code echoOf} is what actually copies the fields and a version of it that
	 * dropped the idle animation would satisfy the source check and change what
	 * renders.
	 */
	@Test
	public void noShippedEchoInheritsABodyThatIsDoingSomething()
	{
		Map<UUID, EntityDefinition> sources = new HashMap<>();
		for (EntityDefinition entity : shippedEntities())
		{
			sources.put(entity.getUuid(), entity);
		}

		List<String> violations = new ArrayList<>();
		int checked = 0;

		for (EntityDefinition echo : shippedEchoes())
		{
			EntityDefinition source = sources.get(echo.getEchoSourceUuid());
			assertNotNull(source);
			checked++;

			if (!CitizenEcho.isAnOrdinaryStandingBody(source))
			{
				violations.add(describe(echo) + " came from " + source.label()
					+ ", whose body is doing something");
			}

			if (!CitizenEcho.isAnOrdinaryStandingBody(echo))
			{
				violations.add(describe(echo) + " is itself doing something, idle="
					+ echo.getIdleAnimation());
			}
		}

		assertTrue("echo(es) with a body an anonymous passer-by cannot have: " + violations,
			violations.isEmpty());
		assertEquals("the whole shipped echo roster has to have been asked", 51, checked);
	}

	/**
	 * <b>And the rule bites on the figures that were photographed.</b>
	 *
	 * <p>A gate that refused nothing would satisfy the two tests above. Each name below
	 * is a shipped citizen that seeded echoes before this rule and seeds none now, and
	 * each is named for the clause that refuses it — a fisherman miming a rod, a smith
	 * swinging at an anvil, a woodcutter with an axe, a butler sitting on a chair, a
	 * dwarf nudged off his tile to stand at a workbench, and a chicken carrying a scale
	 * vector so that it is not rendered at human size.
	 *
	 * <p><b>{@code mergedObjects} has no name here, and that is a fact about the
	 * dataset rather than a gap.</b> The two shipped records that carry one — "Morten"
	 * and "Jofridr", each with a bench welded in — are also posed {@code Sitting}, so no
	 * shipped citizen is refused by the merged-object clause <i>alone</i> and this test
	 * cannot witness it. {@code aCitizenWhoseBodyIsDoingSomethingSeedsNothing} covers it
	 * on a fixture built for the purpose, which is what a fixture is for.
	 */
	@Test
	public void theBodyRuleRefusesTheFiguresItWasWrittenFor()
	{
		Set<String> refused = new TreeSet<>();
		for (EntityDefinition citizen : shippedEntities())
		{
			if (citizen.getType().isCitizen() && !CitizenEcho.isAnOrdinaryStandingBody(citizen))
			{
				refused.add(citizen.getName());
			}
		}

		for (String who : Arrays.asList(
			"Fisherman", "Smithing apprentice", "Benny", "Butler Jarvis", "Stonehand", "Chicken"))
		{
			assertTrue(who + " has to be refused for its body", refused.contains(who));
			assertTrue(who + " has to seed nothing", echoesOfShipped(who).isEmpty());
		}

		// Counted as well as named, so that widening the rule until it refuses
		// everything is a failure rather than a stronger pass.
		int citizens = 0;
		int refusedCount = 0;
		for (EntityDefinition citizen : shippedEntities())
		{
			if (!citizen.getType().isCitizen())
			{
				continue;
			}
			citizens++;
			if (!CitizenEcho.isAnOrdinaryStandingBody(citizen))
			{
				refusedCount++;
			}
		}

		assertEquals("the citizen roster", 269, citizens);
		assertEquals("citizens whose body is doing something", 48, refusedCount);
	}

	// --- The flesh rule -------------------------------------------------------

	/**
	 * <b>The guarantee, stated with no threshold in it: no deal this class issues
	 * ever moves a colour across the flesh boundary.</b>
	 *
	 * <p>This is what {@link CitizenEcho#keepsEachColourOnItsOwnSideOfTheSkin} is
	 * for and it is the whole of the "passers-by with no trousers" fix. {@code find}
	 * is handed to an echo verbatim and only {@code replace} is rotated, so slot
	 * {@code i} of an echo still recolours the body region its author aimed it at —
	 * and the only thing that can go wrong is the <i>kind</i> of colour that lands
	 * there. A skin tone dealt onto the legs slot is bare legs. A tunic colour dealt
	 * onto the skin slot is a blue face.
	 *
	 * <p><b>Deliberately not a count of anything.</b> "How many echoes look wrong"
	 * depends on a threshold for how wrong, on which faces a {@code find} value
	 * actually paints, and therefore on a model decoder — three things nobody has to
	 * agree about for this assertion to be checkable. Either a surviving deal moves a
	 * colour across the boundary or it does not.
	 *
	 * <p>Asserted twice over: once about every deal {@code distinctDeals} would issue
	 * for every shipped palette, and once about the 51 echoes actually derived, which
	 * is the population that ships. The second is not implied by the first — it also
	 * covers {@code echoesOfSource} handing {@code redeal} the deal it said it would.
	 */
	@Test
	public void noSurvivingDealEverMovesAColourAcrossTheFleshBoundary()
	{
		List<String> violations = new ArrayList<>();
		int dealsChecked = 0;

		for (EntityDefinition citizen : shippedEntities())
		{
			short[] replace = citizen.getRecolorReplace();
			if (replace.length < 2)
			{
				continue;
			}

			for (int deal : CitizenEcho.distinctDeals(replace))
			{
				short[] dealt = CitizenEcho.redeal(replace, deal);
				dealsChecked++;
				for (int slot = 0; slot < replace.length; slot++)
				{
					if (CitizenEcho.isFlesh(dealt[slot]) != CitizenEcho.isFlesh(replace[slot]))
					{
						violations.add(citizen.label() + " deal " + deal + " puts " + dealt[slot]
							+ " where " + replace[slot] + " was, slot " + slot);
					}
				}
			}
		}

		Map<UUID, EntityDefinition> sources = new HashMap<>();
		for (EntityDefinition entity : shippedEntities())
		{
			sources.put(entity.getUuid(), entity);
		}

		int echoesChecked = 0;
		for (EntityDefinition echo : shippedEchoes())
		{
			EntityDefinition source = sources.get(echo.getEchoSourceUuid());
			assertNotNull(source);

			short[] was = source.getRecolorReplace();
			short[] now = echo.getRecolorReplace();
			assertEquals("an echo wears its source's palette, so the arrays are the same length",
				was.length, now.length);

			echoesChecked++;
			for (int slot = 0; slot < was.length; slot++)
			{
				if (CitizenEcho.isFlesh(now[slot]) != CitizenEcho.isFlesh(was[slot]))
				{
					violations.add(describe(echo) + " wears " + now[slot] + " in the slot "
						+ source.label() + " painted " + was[slot]);
				}
			}
		}

		assertTrue("colour(s) dealt across the flesh boundary: " + violations, violations.isEmpty());

		// The sample guards. Both loops are "look for a counterexample", so an empty
		// dataset would satisfy them having asked nothing.
		assertTrue("the shipped palettes have to offer some deals to check: " + dealsChecked,
			dealsChecked > 50);
		assertEquals("and the whole shipped echo roster has to have been asked",
			51, echoesChecked);
	}

	/**
	 * <b>And the rule actually bites</b> — on the dataset that was photographed, in
	 * the way the photograph shows.
	 *
	 * <p>A rule that refused nothing would satisfy the test above perfectly. So the
	 * refusals are counted, and one of them is worked through by hand.
	 *
	 * <p>"Mary" (region 12852, a Varrock file) is the worked example, because she is not
	 * a hypothetical and not even a near miss: <b>until 2026-08-30 her echo shipped, and
	 * it wore the game's own face colour on its legs.</b> Her {@code find} names the
	 * torso base ({@code 8741}), the legs base ({@code 25238}), the hair base
	 * ({@code 6798}) and {@code 43072}, which is the base the kit's arm and hand models
	 * carry on their cuffs. Her {@code replace} answers them with a grey, a dark brown,
	 * a red-brown and {@link CitizenEcho#PLAYER_SKIN_BASE} — and that last one is on the
	 * <i>arm</i> slot, where it means a bare forearm and is right.
	 *
	 * <p>Rotating by two moves it onto {@code 25238}, and that is still what this test
	 * pins. What has changed is <b>which rule refuses it</b>, and the change is worth
	 * writing down rather than quietly absorbing.
	 *
	 * <p>Her dark brown used to be {@code 5532} — hue 5, saturation 3, lightness 28 — and
	 * that is inside {@link CitizenEcho#isFlesh}'s gamut, so two of her four colours were
	 * flesh-class and they were the two that swapped places. The flesh-or-not rule saw a
	 * class-preserving rotation and allowed it; only the third class, the face colour as
	 * its own kind, refused it. On 2026-08-31 {@code 5532} was repainted {@code 8472},
	 * because a dark brown inside the flesh gamut on a legs slot is exactly what
	 * {@link BodySlotLintTest#noLegsSlotIsPaintedAColourFromTheFleshGamut} now refuses in
	 * the data. With one flesh colour left instead of two, <b>both</b> rules refuse the
	 * rotation, so she no longer separates them — and
	 * {@link #theThirdClassIsKeptEvenThoughTheDataNoLongerNeedsIt} measures that the
	 * shipped data has no other record that does either.
	 *
	 * <p>("Marta" in Falador used to stand here for the same purpose. She was repaletted
	 * on 2026-08-30, because unlike Mary she was <i>ours</i>: the top-up authored her by
	 * hand-rotating an upstream palette, which put {@code 4550} on her hair base at the
	 * default density rather than only at {@code CROWDED}. Her wardrobe is now four
	 * garment colours and she seeds echoes again, which is the right outcome and the
	 * reason she is no longer an example of this rule.)
	 */
	@Test
	public void theFleshRuleRefusesTheDealsThatProducedThePhotographs()
	{
		int refused = 0;
		int citizensLeftWithNothing = 0;
		EntityDefinition mary = null;

		for (EntityDefinition citizen : shippedEntities())
		{
			if (!citizen.getType().isCitizen())
			{
				// Scenery never seeds an echo, so its rotations are not a cost.
				continue;
			}

			short[] replace = citizen.getRecolorReplace();
			if (replace.length < 2)
			{
				continue;
			}

			if ("Mary".equals(citizen.getName()))
			{
				mary = citizen;
			}

			int distinctRotations = distinctRotationCount(replace);
			int allowed = CitizenEcho.distinctDeals(replace).length;
			refused += distinctRotations - allowed;
			if (distinctRotations > 0 && allowed == 0)
			{
				citizensLeftWithNothing++;
			}
		}

		assertEquals("distinct re-deals the palette rule refuses across the dataset — "
				+ "448 of the 847 the shipped citizen palettes admit",
			448, refused);
		assertEquals("citizens whose whole wardrobe is refused by it",
			105, citizensLeftWithNothing);

		assertNotNull("the worked example has to still be in the dataset", mary);
		assertArray("Mary's authored find slots",
			new short[]{8741, 25238, 6798, (short) 43072}, mary.getRecolorFind());
		assertArray("and the palette she answers them with, her legs repainted 2026-08-31",
			new short[]{322, 8472, 8099, 4550}, mary.getRecolorReplace());
		assertTrue("4550 is the game's base skin tone and has to read as flesh",
			CitizenEcho.isFlesh((short) 4550));
		assertTrue("the dark brown she used to wear on her legs was flesh-class too, which "
			+ "is why the flesh-or-not rule let this rotation through before the repaint",
			CitizenEcho.isFlesh((short) 5532));
		assertFalse("and the one she wears there now is not, which is the repaint",
			CitizenEcho.isFlesh((short) 8472));

		// The rotation that shipped: 4550 off the arm slot and onto the legs base.
		short[] wasShipped = CitizenEcho.redeal(mary.getRecolorReplace(), 2);
		assertArray("the deal that produced the photograph",
			new short[]{8099, 4550, 322, 8472}, wasShipped);
		assertEquals("which paints the legs base", 25238, mary.getRecolorFind()[1] & 0xFFFF);

		assertEquals("so no rotation of her palette survives, and she seeds nothing",
			0, CitizenEcho.distinctDeals(mary.getRecolorReplace()).length);
		assertTrue("and she seeds nothing", echoesOf(mary).isEmpty());
	}

	/**
	 * <b>And the derived half of the trousers rule: no echo wears a complexion on its
	 * legs either.</b>
	 *
	 * <p>{@link BodySlotLintTest#noLegsSlotIsPaintedAColourFromTheFleshGamut} holds the
	 * authored records. This holds the ones the plugin makes up, and it is a separate
	 * assertion because the two are held by different machinery: the authored half is a
	 * fact about the files, and the derived half is a <b>consequence</b> of that fact
	 * plus {@link CitizenEcho#keepsEachColourOnItsOwnSideOfTheSkin}.
	 *
	 * <p>The argument is worth stating, because it is short and because it is the thing
	 * that would break silently. A surviving deal has {@code isFlesh(dealt[i])} equal to
	 * {@code isFlesh(replace[i])} at every slot — that is what the rule enforces. So if
	 * the authored {@code replace} at a legs slot is not flesh, no deal can make it
	 * flesh. <b>The derivation is safe because the data is clean, not independently of
	 * it.</b> Repaint one legs slot back inside the gamut and this test goes red along
	 * with the lint, which is the correct pair of failures rather than one.
	 *
	 * <p>Asserted over both populations for the same reason the boundary test above is:
	 * every deal {@link CitizenEcho#distinctDeals} would issue, and every echo actually
	 * derived, because the second also covers {@code echoesOfSource} handing
	 * {@code redeal} the deal it said it would.
	 */
	@Test
	public void noSurvivingDealEverPutsAFleshColourOnALegsSlot()
	{
		List<String> violations = new ArrayList<>();
		int dealsChecked = 0;
		int legsSlotsChecked = 0;

		for (EntityDefinition citizen : shippedEntities())
		{
			short[] find = citizen.getRecolorFind();
			short[] replace = citizen.getRecolorReplace();
			if (replace.length < 2)
			{
				continue;
			}

			for (int deal : CitizenEcho.distinctDeals(replace))
			{
				short[] dealt = CitizenEcho.redeal(replace, deal);
				dealsChecked++;
				for (int slot = 0; slot < dealt.length; slot++)
				{
					if ((find[slot] & 0xFFFF) != BodySlots.LEGS_BASE)
					{
						continue;
					}

					legsSlotsChecked++;
					if (CitizenEcho.isFlesh(dealt[slot]))
					{
						violations.add(citizen.label() + " deal " + deal + " paints its legs "
							+ (dealt[slot] & 0xFFFF));
					}
				}
			}
		}

		int echoesChecked = 0;
		for (EntityDefinition echo : shippedEchoes())
		{
			short[] find = echo.getRecolorFind();
			short[] replace = echo.getRecolorReplace();
			echoesChecked++;

			for (int slot = 0; slot < find.length; slot++)
			{
				if ((find[slot] & 0xFFFF) == BodySlots.LEGS_BASE
					&& CitizenEcho.isFlesh(replace[slot]))
				{
					violations.add(describe(echo) + " wears " + (replace[slot] & 0xFFFF)
						+ " where its trousers go");
				}
			}
		}

		assertTrue("echo(es) whose trousers are painted a complexion: " + violations,
			violations.isEmpty());

		// The sample guards. Both loops look for a counterexample, so a dataset with no
		// legs slots left in it would satisfy them having asked nothing.
		assertTrue("deals to check: " + dealsChecked, dealsChecked > 50);
		assertEquals("legs slots across every surviving deal", 350, legsSlotsChecked);
		assertEquals("and the whole shipped echo roster has to have been asked",
			51, echoesChecked);
	}

	/**
	 * The third class in {@link CitizenEcho}'s re-deal rule now costs nothing, and that
	 * is measured rather than assumed.
	 *
	 * <p>{@link CitizenEcho#keepsEachColourOnItsOwnSideOfTheSkin} sorts a colour into
	 * three kinds — the game's own face colour, some other flesh tone, cloth — where it
	 * used to sort into two. The third kind was added on 2026-08-30 because "Mary"'s
	 * echo slipped past the two-kind version. The 2026-08-31 legs repaint took her second
	 * flesh colour away, and with it the only shipped rotation the two rules disagreed
	 * about.
	 *
	 * <p><b>Zero is the honest number and it is asserted, not written in prose.</b> A rule
	 * that costs nothing today is not a rule that can be deleted — the next authored
	 * record is what it is for — but "we kept it because the data needs it" would be false
	 * now, and a claim nobody checks is how a false one survives. If a future record makes
	 * the two rules disagree again, this goes red and somebody reads the paragraph.
	 */
	@Test
	public void theThirdClassIsKeptEvenThoughTheDataNoLongerNeedsIt()
	{
		int disagreements = 0;
		int rotationsChecked = 0;

		for (EntityDefinition entity : shippedEntities())
		{
			short[] replace = entity.getRecolorReplace();
			if (replace.length < 2)
			{
				continue;
			}

			for (int deal = 1; deal < replace.length; deal++)
			{
				short[] dealt = CitizenEcho.redeal(replace, deal);
				if (Arrays.equals(dealt, replace))
				{
					continue;
				}

				rotationsChecked++;
				boolean twoClassesAllowIt = true;
				boolean threeClassesAllowIt = true;
				for (int slot = 0; slot < replace.length; slot++)
				{
					twoClassesAllowIt &= CitizenEcho.isFlesh(dealt[slot])
						== CitizenEcho.isFlesh(replace[slot]);
					threeClassesAllowIt &=
						((dealt[slot] & 0xFFFF) == CitizenEcho.PLAYER_SKIN_BASE)
							== ((replace[slot] & 0xFFFF) == CitizenEcho.PLAYER_SKIN_BASE);
				}

				if (twoClassesAllowIt && !threeClassesAllowIt)
				{
					disagreements++;
				}
			}
		}

		assertTrue("rotations to check: " + rotationsChecked, rotationsChecked > 100);
		assertEquals("shipped rotations the two-class rule allows and the three-class rule "
			+ "refuses — see this test's javadoc before changing it", 0, disagreements);
	}

	/**
	 * The gamut itself, checked against the five colours it was derived from.
	 *
	 * <p>{@link CitizenEcho#isFlesh} says how the wedge was measured — 3,319
	 * {@code find = 4550} recolours decoded out of the 1.12.36 cache. What can be
	 * asserted inside this repository is the part of that reasoning the dataset
	 * carries with it: the five base colours of the game's own player kit, which are
	 * the {@code find} values the shipped records are authored against.
	 */
	@Test
	public void theFleshGamutSeparatesTheGamesOwnSkinBaseFromItsGarmentBases()
	{
		assertTrue("4550, the skin base, is the colour the wedge is centred on",
			CitizenEcho.isFlesh((short) 4550));
		assertFalse("8741, the torso base, is the hue a tunic is dyed in",
			CitizenEcho.isFlesh((short) 8741));
		assertFalse("25238, the legs base, is green and nowhere near",
			CitizenEcho.isFlesh((short) 25238));

		// Two the palette cannot separate, both of which fall the safe way — see
		// isFlesh. 4626 is the boots base and a dark leather boot really is the hue of
		// a dark complexion; 6798 is the hair base and dark brown hair likewise. Both
		// are therefore held still rather than dealt around. Neither costs anything in
		// the shipped data — 4626 is a replace value four times and 6798 never — but
		// the classification is what it is and is written down rather than special-cased.
		assertTrue("the boots base falls inside the wedge", CitizenEcho.isFlesh((short) 4626));
		assertTrue("and so does the hair base", CitizenEcho.isFlesh((short) 6798));

		// The two excluded saturation rungs, at the wedge's own hue.
		assertFalse("saturation 0 at hue 4 is grey, not tan",
			CitizenEcho.isFlesh((short) ((4 << 10) | (0 << 7) | 70)));
		assertFalse("saturation 7 at hue 4 is a costume orange",
			CitizenEcho.isFlesh((short) ((4 << 10) | (7 << 7) | 70)));
		assertTrue("but everything between them is in, at any lightness",
			CitizenEcho.isFlesh((short) ((4 << 10) | (1 << 7) | 0))
				&& CitizenEcho.isFlesh((short) ((4 << 10) | (6 << 7) | 127)));

		// The hue edges.
		assertFalse("hue 1 is red", CitizenEcho.isFlesh((short) ((1 << 10) | (3 << 7) | 70)));
		assertTrue(CitizenEcho.isFlesh((short) ((2 << 10) | (3 << 7) | 70)));
		assertTrue(CitizenEcho.isFlesh((short) ((7 << 10) | (3 << 7) | 70)));
		assertFalse("hue 8 is where the torso base lives",
			CitizenEcho.isFlesh((short) ((8 << 10) | (3 << 7) | 70)));
	}

	@Test
	public void sceneryNeverSeedsAnEcho()
	{
		FakeRegions regions = new FakeRegions();

		assertTrue("a second market stall two tiles from the first is not a livelier city",
			echoesOf(regions.scenery(VARROCK_SOUTH, 3225, 3355)).isEmpty());
	}

	@Test
	public void anEchoNeverSeedsAnEchoOfItsOwn()
	{
		FakeRegions regions = new FakeRegions();
		List<EntityDefinition> echoes =
			echoesOf(regions.recoloured(VARROCK_SOUTH, 3225, 3355, 6));
		assertFalse(echoes.isEmpty());

		for (EntityDefinition echo : echoes)
		{
			assertTrue("a re-deal of a re-deal drifts away from the authored palette",
				echoesOf(echo).isEmpty());
		}
	}

	// --- Determinism ----------------------------------------------------------

	/**
	 * Two derivations from the same source have to agree on every field.
	 *
	 * <p>Field by field rather than "the lists are the same size": the region cache
	 * is rebuilt on every border crossing and every eviction, so this runs many
	 * times per session, and an echo that moved a tile or changed colour when its
	 * region was rebuilt would flicker exactly where a player is looking.
	 */
	@Test
	public void theSameSourceDerivesTheSameEchoesEveryTime()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition source = regions.recoloured(VARROCK_SOUTH, 3225, 3355, 5);

		List<EntityDefinition> first = echoesOf(source);
		List<EntityDefinition> second = echoesOf(source);

		assertEquals(first.size(), second.size());
		assertFalse("the fixture has to actually produce echoes", first.isEmpty());

		for (int i = 0; i < first.size(); i++)
		{
			EntityDefinition a = first.get(i);
			EntityDefinition b = second.get(i);

			assertEquals("uuid", a.getUuid(), b.getUuid());
			assertEquals("tile", a.getWorldLocation(), b.getWorldLocation());
			assertEquals("facing", a.getOrientation(), b.getOrientation());
			assertEquals("name", a.getName(), b.getName());
			assertEquals("examine", a.getExamineText(), b.getExamineText());
			assertEquals("source", a.getEchoSourceUuid(), b.getEchoSourceUuid());
			assertEquals("region", a.getTileRegionId(), b.getTileRegionId());
			assertTrue("recolour find", Arrays.equals(a.getRecolorFind(), b.getRecolorFind()));
			assertTrue("recolour replace", Arrays.equals(a.getRecolorReplace(), b.getRecolorReplace()));
			assertEquals("stable hash", a.stableHash(), b.stableHash());
		}
	}

	/**
	 * <b>The same roster in a different order derives the same crowd.</b>
	 *
	 * <p>Once separation is judged across a whole region, two citizens can want the
	 * same tile and only the first one asked can have it — so whatever decides who is
	 * asked first decides where somebody stands. If that were the region file's own
	 * listing order, then re-exporting the dataset, or a loader that read the scenery
	 * roster before the citizen roster, would silently move people around. Sources are
	 * walked in uuid order instead, and this is what says so: the same nine citizens,
	 * listed forwards, backwards and rotated, produce the same echoes on the same tiles
	 * in the same order.
	 *
	 * <p>The fixture is the tight three-by-three block again, because in a crowd with
	 * room to spare every order gives the same answer and the test would pass on a
	 * coincidence.
	 */
	@Test
	public void theDerivationDoesNotDependOnTheOrderTheRosterIsListedIn()
	{
		FakeRegions regions = new FakeRegions();
		List<EntityDefinition> roster = new ArrayList<>();
		for (int i = 0; i < 9; i++)
		{
			roster.add(regions.recoloured(VARROCK_SOUTH, 3220 + (i % 3) * 3, 3350 + (i / 3) * 3, 6));
		}

		List<String> asListed = placements(CitizenEcho.echoesOfRegion(roster));

		List<EntityDefinition> backwards = new ArrayList<>(roster);
		Collections.reverse(backwards);

		List<EntityDefinition> rotated = new ArrayList<>(roster);
		Collections.rotate(rotated, 4);

		assertFalse("the fixture has to produce echoes", asListed.isEmpty());
		assertEquals("listing the roster backwards must not move anybody",
			asListed, placements(CitizenEcho.echoesOfRegion(backwards)));
		assertEquals("nor must rotating it",
			asListed, placements(CitizenEcho.echoesOfRegion(rotated)));
	}

	/**
	 * An anchor value for the uuid derivation, so it cannot change by accident.
	 *
	 * <p>Same job as {@code CrowdDensityTest.theHashIsPinned..}: the uuid is what
	 * {@link CitizenOverrides} writes into the user's profile when they hide an echo,
	 * so a "harmless" tweak to the derivation silently discards every hide anybody
	 * had set on an echo, and swaps which stranger is hidden. Changing this number
	 * deliberately is fine; changing it without noticing is what this catches.
	 */
	@Test
	public void theEchoUuidDerivationIsPinned()
	{
		UUID source = UUID.fromString("44444444-4444-4444-8444-444444444444");

		assertEquals(UUID.fromString("663c3dc2-2e38-d721-b7b9-44c9f279864d"),
			CitizenEcho.echoUuid(source, 0));
		assertEquals(UUID.fromString("5d01ffe4-1f40-7d93-9091-4d172f2dd35c"),
			CitizenEcho.echoUuid(source, 1));
	}

	@Test
	public void everyEchoIndexGetsItsOwnUuid()
	{
		UUID source = UUID.fromString("44444444-4444-4444-8444-444444444444");

		assertNotEquals(CitizenEcho.echoUuid(source, 0), CitizenEcho.echoUuid(source, 1));
		assertNotEquals("and neither may be the source's own",
			source, CitizenEcho.echoUuid(source, 0));
		assertNotEquals(source, CitizenEcho.echoUuid(source, 1));
	}

	// --- Not twins ------------------------------------------------------------

	@Test
	public void anEchoIsNeverWithinTheMinimumDistanceOfItsSourceOrOfItsSibling()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition source = regions.recoloured(VARROCK_SOUTH, 3225, 3355, 6);
		List<EntityDefinition> echoes = echoesOf(source);
		assertEquals(2, echoes.size());

		for (EntityDefinition echo : echoes)
		{
			assertTrue("echo at " + echo.getWorldLocation() + " is too close to its source",
				RenderPolicy.tileDistance(source.getWorldLocation(), echo.getWorldLocation())
					>= CitizenEcho.MIN_SEPARATION_TILES);
		}

		assertTrue("two echoes of one citizen must not stand on top of each other",
			RenderPolicy.tileDistance(
				echoes.get(0).getWorldLocation(), echoes.get(1).getWorldLocation())
				>= CitizenEcho.MIN_SEPARATION_TILES);
	}

	/**
	 * <b>And never within the minimum distance of anybody else's citizen, or anybody
	 * else's echo.</b>
	 *
	 * <p>The test above is the old rule: an echo against its own source and its own
	 * sibling. This is the rule as it is actually written down — an echo against
	 * everything the plugin renders in its region — and the fixture is deliberately
	 * tight enough to tell them apart. A three-by-three block of citizens three tiles
	 * apart leaves no tile in its interior more than one tile from somebody, so every
	 * candidate ring runs straight through a neighbour: a derivation that could only
	 * see one lineage would put echoes on top of strangers here, exactly as it did
	 * across the shipped files, where it produced 41 such pairs.
	 *
	 * <p>The shortfall is asserted too. A crowd this tight cannot house two echoes per
	 * citizen, and if it could, the fixture would not be exercising contention at all
	 * — it would be nine separate one-citizen fixtures standing near each other.
	 */
	@Test
	public void anEchoKeepsItsDistanceFromTheWholeRegionAndNotJustItsOwnLineage()
	{
		FakeRegions regions = new FakeRegions();
		List<EntityDefinition> roster = new ArrayList<>();
		for (int i = 0; i < 9; i++)
		{
			roster.add(regions.recoloured(VARROCK_SOUTH, 3220 + (i % 3) * 3, 3350 + (i / 3) * 3, 6));
		}

		List<EntityDefinition> echoes = CitizenEcho.echoesOfRegion(roster);
		assertFalse("the fixture has to produce echoes", echoes.isEmpty());

		List<EntityDefinition> rendered = new ArrayList<>(roster);
		rendered.addAll(echoes);

		for (int i = 0; i < rendered.size(); i++)
		{
			for (int j = i + 1; j < rendered.size(); j++)
			{
				EntityDefinition a = rendered.get(i);
				EntityDefinition b = rendered.get(j);
				if (!a.isEcho() && !b.isEcho())
				{
					// Authored against authored is the fixture's own business.
					continue;
				}

				assertTrue(describe(a) + " at " + a.getWorldLocation() + " and " + describe(b)
						+ " at " + b.getWorldLocation() + " are too close",
					RenderPolicy.tileDistance(a.getWorldLocation(), b.getWorldLocation())
						>= CitizenEcho.MIN_SEPARATION_TILES);
			}
		}

		assertTrue("a row this tight has to cost somebody an echo, or the fixture is not "
				+ "exercising contention: got " + echoes.size() + " of "
				+ roster.size() * CitizenEcho.MAX_ECHOES_PER_CITIZEN,
			echoes.size() < roster.size() * CitizenEcho.MAX_ECHOES_PER_CITIZEN);
	}

	/**
	 * <b>A floor is not a gap, but a floor between two people is.</b> The claimed-tile
	 * set is keyed on the plane as well as the coordinates, so a crowd upstairs cannot
	 * take the tiles a crowd downstairs needs.
	 *
	 * <p>{@link RenderPolicy#tileDistance} ignores the plane — it is the render
	 * distance metric, where a citizen one storey up is still a citizen a few tiles
	 * away — so this is the one place the plane has to be put back. The fixture stacks
	 * two identical nine-citizen blocks one storey apart, both tight enough to be
	 * fighting over tiles within their own storey; if the storeys were pooled they
	 * would be fighting over the same ones and the total would drop.
	 */
	@Test
	public void aCrowdUpstairsDoesNotTakeTheTilesTheCrowdDownstairsNeeds()
	{
		FakeRegions regions = new FakeRegions();
		List<EntityDefinition> groundFloor = new ArrayList<>();
		List<EntityDefinition> upstairs = new ArrayList<>();
		for (int i = 0; i < 9; i++)
		{
			int x = 3220 + (i % 3) * 3;
			int y = 3350 + (i / 3) * 3;
			groundFloor.add(regions.recoloured(VARROCK_SOUTH, x, y, 0, 6));
			upstairs.add(regions.recoloured(VARROCK_SOUTH, x, y, 1, 6));
		}

		List<EntityDefinition> groundAlone = CitizenEcho.echoesOfRegion(groundFloor);
		List<EntityDefinition> upstairsAlone = CitizenEcho.echoesOfRegion(upstairs);
		assertFalse("the fixture has to produce echoes", groundAlone.isEmpty());
		assertTrue("and each storey has to be crowded enough to be short of tiles on its own, "
				+ "or pooling the two would cost nothing and this would pass either way",
			groundAlone.size() < groundFloor.size() * CitizenEcho.MAX_ECHOES_PER_CITIZEN
				&& upstairsAlone.size() < upstairs.size() * CitizenEcho.MAX_ECHOES_PER_CITIZEN);

		List<EntityDefinition> both = new ArrayList<>(groundFloor);
		both.addAll(upstairs);
		List<EntityDefinition> stacked = CitizenEcho.echoesOfRegion(both);

		assertEquals("the ground floor's echoes must be exactly where they were when it was "
				+ "the only storey in the region",
			placements(groundAlone), placements(onPlane(stacked, 0)));
		assertEquals("and so must the first floor's",
			placements(upstairsAlone), placements(onPlane(stacked, 1)));
		assertEquals("with nobody else anywhere",
			groundAlone.size() + upstairsAlone.size(), stacked.size());
	}

	/**
	 * Each echo as {@code uuid@tile facing n}, in the order it was derived — so a
	 * comparison of two derivations names the field that moved rather than saying
	 * "not equal".
	 */
	private static List<String> placements(List<EntityDefinition> echoes)
	{
		List<String> out = new ArrayList<>(echoes.size());
		for (EntityDefinition echo : echoes)
		{
			out.add(echo.getUuid() + "@" + echo.getWorldLocation() + " facing " + echo.getOrientation());
		}
		return out;
	}

	private static List<EntityDefinition> onPlane(List<EntityDefinition> entities, int plane)
	{
		List<EntityDefinition> out = new ArrayList<>();
		for (EntityDefinition entity : entities)
		{
			if (entity.getPlane() == plane)
			{
				out.add(entity);
			}
		}
		return out;
	}

	/**
	 * The recolour is the source's own palette, re-dealt — not a new palette and not
	 * the same one.
	 *
	 * <p>Three separate claims, and each is a different way of getting it wrong: the
	 * {@code find} slots have to be untouched (a different find array would recolour
	 * parts of the model the author never meant to touch), the {@code replace} values
	 * have to be exactly the source's own multiset (anything else is an invented
	 * colour), and the mapping has to actually differ (or it is a twin).
	 */
	@Test
	public void anEchoWearsItsSourcesOwnColoursInADifferentOrder()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition source = regions.recoloured(VARROCK_SOUTH, 3225, 3355, 4);
		List<EntityDefinition> echoes = echoesOf(source);
		assertEquals(2, echoes.size());

		short[] sourceFind = source.getRecolorFind();
		short[] sourceReplace = source.getRecolorReplace();

		for (EntityDefinition echo : echoes)
		{
			assertTrue("the slots being recoloured must be the source's own",
				Arrays.equals(sourceFind, echo.getRecolorFind()));

			short[] sorted = echo.getRecolorReplace().clone();
			short[] sourceSorted = sourceReplace.clone();
			Arrays.sort(sorted);
			Arrays.sort(sourceSorted);
			assertTrue("every colour must be one the source already wore",
				Arrays.equals(sourceSorted, sorted));

			assertFalse("but not in the same order, or it is the source standing next to itself",
				Arrays.equals(sourceReplace, echo.getRecolorReplace()));
		}

		assertFalse("and two echoes of one citizen must differ from each other too",
			Arrays.equals(echoes.get(0).getRecolorReplace(), echoes.get(1).getRecolorReplace()));
	}

	@Test
	public void reDealingRotatesThePaletteAndLeavesTheOriginalAlone()
	{
		short[] palette = {10, 20, 30};

		assertArray(new short[]{20, 30, 10}, CitizenEcho.redeal(palette, 1));
		assertArray(new short[]{30, 10, 20}, CitizenEcho.redeal(palette, 2));
		assertArray("the source's own array must not be touched", new short[]{10, 20, 30}, palette);
	}

	/**
	 * Two echoes of one citizen must not stand shoulder to shoulder facing the same
	 * way — the "twins" tell that survives a recolour. The facing comes from each
	 * echo's own uuid rather than from the source's, which is what makes them differ.
	 */
	@Test
	public void anEchoFacesOneOfTheEightCardinalDirections()
	{
		FakeRegions regions = new FakeRegions();
		Set<Integer> facings = new HashSet<>();

		for (int i = 0; i < 30; i++)
		{
			for (EntityDefinition echo :
				echoesOf(regions.recoloured(VARROCK_SOUTH, 3210 + i * 3, 3340, 6)))
			{
				int facing = echo.getOrientation();
				assertEquals("a facing off the eight looks like a rendering fault, not a person",
					0, facing % 256);
				assertTrue("orientation must be inside 0..2047", facing >= 0 && facing < 2048);
				facings.add(facing);
			}
		}

		assertTrue("the derivation has to actually spread across the eight, not pick one: " + facings,
			facings.size() >= 6);
	}

