	// --- The shipped dataset --------------------------------------------------

	/**
	 * The headline claim, recomputed from the shipped files.
	 *
	 * <p>142 authored citizens and 46 echoes, i.e. 188 in total, 1.32×.
	 *
	 * <p><b>This test used to assert a ratio in the band {@code [1.8, 2.4]}</b>, and
	 * that band was the wrong shape of claim in two ways at once. It was a floor under
	 * a number nobody should want a floor under — "at least 1.8× as many people as a
	 * human placed" is a target the derivation can only hit by relaxing whatever is
	 * stopping it — and it was global, so a city could be four-fifths made-up people
	 * as long as the whole dataset averaged out. The flesh rule
	 * ({@link CitizenEcho#isFlesh}) took the real figure to 1.51× and the band went
	 * red, which is the band doing the only useful thing it ever did.
	 *
	 * <p>What replaces it is a <b>ceiling, per city</b>: no city's rendered crowd may
	 * be more than half derived. That is a claim about what a player standing in
	 * Draynor actually sees, it cannot be satisfied by deriving more, and it is the
	 * one the photographs were evidence against — "Draynor full of near-identical
	 * figures doing nothing" is a statement about Draynor's own mix, not about a
	 * dataset-wide average. Draynor, which is the city that was photographed, is also
	 * the worst in the shipped data: 7 echoes against 10 authored, i.e. 41%. Two cities
	 * — Ardougne and Lumbridge — are now 0%, which is worth knowing when the
	 * keep-or-retire question about {@code CROWDED} is next argued.
	 *
	 * <p>The floor that is kept is the honest one: {@code CROWDED} has to add
	 * <i>something</i>, or it is a setting that does nothing.
	 *
	 * <p><b>Why 44 and not fewer.</b> Every echo the 24 seeds ask for finds somewhere
	 * legal to stand. That was not true before the flesh rule — the "Mysterious Old
	 * Man" in Varrock got one echo instead of two, because every tile near him was
	 * within {@link CitizenEcho#MIN_SEPARATION_TILES} of somebody — and it is true now
	 * for the dullest of reasons: there are fewer echoes competing for the same
	 * ground. The placement rule is untouched.
	 *
	 * <p><b>Why the seed count is one short of the citizens that reach the palette
	 * check with a usable wardrobe.</b> "Rufus" in Varrock square used to seed two
	 * echoes and now seeds none: he is dressed from an {@code npcAppearanceId} (GitHub
	 * issue #1 — his authored {@code modelIds} carried no footwear), and a source whose
	 * colours come from a composition rather than from its own record has no palette to
	 * re-deal, so {@code CitizenEcho} refuses it. That is the price of the fix: two
	 * ambient bodies at {@code CROWDED}, against a citizen who is no longer barefoot.
	 */
	@Test
	public void theShippedRosterIsHalfAgainAsBigUnderCrowded()
	{
		int citizens = 0;
		Map<City, Integer> authoredPerCity = new EnumMap<>(City.class);
		for (EntityDefinition entity : shippedEntities())
		{
			if (entity.getType().isCitizen())
			{
				citizens++;
				authoredPerCity.merge(City.of(entity.getCityRegionId()), 1, Integer::sum);
			}
		}

		int echoes = 0;
		int fromBoxes = 0;
		Set<UUID> seeds = new HashSet<>();
		Map<City, Integer> echoesPerCity = new EnumMap<>(City.class);
		for (EntityDefinition echo : shippedEchoes())
		{
			echoes++;
			if (echo.isEchoOnAuthoredGround())
			{
				fromBoxes++;
			}
			seeds.add(echo.getEchoSourceUuid());
			echoesPerCity.merge(City.of(echo.getCityRegionId()), 1, Integer::sum);
		}

		assertEquals("the authored citizen roster", 269, citizens);
		assertEquals("citizens that seeded at least one echo", 28, seeds.size());
		assertEquals("echoes derived from them", 51, echoes);
		assertEquals("of which this many stand inside an authored wander box", 29, fromBoxes);
		assertEquals("the rest stand on a derived offset the collision map has to vouch for",
			22, echoes - fromBoxes);

		// The floor, stated as the two rosters rather than as `echoes >= 0`, which is
		// what this line used to say: `echoes` is a counter that is only ever
		// incremented, so the old form could not go red whatever the derivation did.
		int atFull = citizens;
		int atCrowded = citizens + echoes;
		assertTrue("CROWDED must never yield fewer citizens than FULL: " + atCrowded
				+ " against " + atFull,
			atCrowded > atFull);

		// The ceiling, per city, which is the claim that means something at 1.32×.
		// Grouped by the region whose checkbox governs the entity — an echo answers to
		// its source's city, not to the tile it stands on — so this is the mix a player
		// who has that one city ticked would be standing in.
		// A city for every entity counted, asserted where it can actually fail. This
		// used to be `echoesPerCity.containsKey(null)`, which is dead twice over: an
		// EnumMap returns false for a null key unconditionally, and `merge(null, ...)`
		// thirty lines above would have thrown a NullPointerException before this line
		// was reached. Counted in the same passes as the maps instead.
		int cityless = 0;
		for (EntityDefinition entity : shippedEntities())
		{
			if (entity.getType().isCitizen() && City.of(entity.getCityRegionId()) == null)
			{
				cityless++;
			}
		}
		for (EntityDefinition echo : shippedEchoes())
		{
			if (City.of(echo.getCityRegionId()) == null)
			{
				cityless++;
			}
		}
		assertEquals("every entity the mix is measured over has to belong to a city, or "
			+ "the shares below are measured against nothing", 0, cityless);

		String worst = "";
		double worstShare = 0;
		for (Map.Entry<City, Integer> city : echoesPerCity.entrySet())
		{
			int authored = authoredPerCity.getOrDefault(city.getKey(), 0);
			int derived = city.getValue();
			double share = derived / (double) (authored + derived);
			if (share > worstShare)
			{
				worstShare = share;
				worst = city.getKey() + ": " + derived + " derived against "
					+ authored + " authored";
			}
		}

		assertTrue("no city may be more than half made-up people; worst was " + worst
				+ " = " + String.format("%.1f%%", worstShare * 100),
			worstShare <= 0.5);

		// Pinned as well as bounded, so that a data change which moved it says so
		// instead of drifting quietly upwards inside the ceiling.
		assertEquals("the worst city's derived share", 0.2727, worstShare, 0.0001);

		// There used to be a `total/authored` assertion here pinning the ratio to four
		// decimal places. It could not fail: `citizens` and `echoes` are both pinned
		// literals a few lines up, so the ratio was arithmetic on two numbers this test
		// had already asserted, and the only way to move it was to break one of them
		// first. The ratio is prose — it belongs in CitizenEcho's javadoc, where it is —
		// and a test that restates a figure it has just pinned is a test that looks like
		// two guards and is one.
	}

	/**
	 * Why the other 114 citizens seed nothing, gate by gate, and the fact that the
	 * gates partition the roster.
	 *
	 * <p>{@link #theShippedRosterIsHalfAgainAsBigUnderCrowded()} pins the ones that do
	 * seed; every other citizen in the roster lands at exactly one of the gates below.
	 * The counts for them are written into {@link CitizenEcho}'s javadoc and into the
	 * comment beside each {@code return NONE} — "22 of the 87 shipped citizens that
	 * reach this line land here" and its siblings — and nothing was checking them, so
	 * they went on saying 49 of 128 after the dataset was cut to 109 citizens. Numbers
	 * that have to sum to a total is the cheapest possible guard, and this is it.
	 *
	 * <p>The number in the first line is the one the last assertion in this method
	 * makes, and it is written that way because the previous version was not: it said
	 * "the other 46" while the code below asserted 118, and survived a review because a
	 * figure in a sentence has nothing holding it.
	 *
	 * <p><b>The last {@code return NONE} covers two different facts and they are split
	 * here.</b> {@code distinctDeals} returns nothing both for a palette that replaces
	 * every slot with the same colour (1 citizen that reaches it — every rotation is the
	 * identity) and for one whose every rotation would carry a colour across the flesh
	 * boundary (36).
	 * Rolled into one number those would hide each other: the flesh rule could stop
	 * working entirely and the total would still add up as long as the identity cases
	 * absorbed the difference.
	 *
	 * <p>The order below is {@code echoesOfSource}'s own order, because the counts
	 * are only meaningful in it: a cameo is refused before its palette is ever
	 * looked at, so "citizens with fewer than two recolour pairs" and "citizens that
	 * reach the palette check with fewer than two" are different numbers.
	 */
	@Test
	public void everyCitizenTheDerivationRefusesIsRefusedAtExactlyOneGate()
	{
		int cameos = 0;
		int dressedFromAnNpc = 0;
		int refusedByTheirOwnRecord = 0;
		int bodyIsDoingSomething = 0;
		int reachThePaletteCheck = 0;
		int tooFewPairs = 0;
		int everyRedealIsTheSame = 0;
		int everyRedealCrossesTheSkin = 0;
		int seeds = 0;

		for (EntityDefinition citizen : shippedEntities())
		{
			if (!citizen.getType().isCitizen())
			{
				continue;
			}

			if (citizen.isCameo())
			{
				cameos++;
				continue;
			}

			if (citizen.isNoEcho())
			{
				refusedByTheirOwnRecord++;
				continue;
			}

			if (citizen.getNpcAppearanceId() != 0)
			{
				dressedFromAnNpc++;
				continue;
			}

			if (!CitizenEcho.isAnOrdinaryStandingBody(citizen))
			{
				bodyIsDoingSomething++;
				continue;
			}

			reachThePaletteCheck++;

			if (citizen.getRecolorFind().length < 2 || citizen.getRecolorReplace().length < 2)
			{
				tooFewPairs++;
				continue;
			}

			if (CitizenEcho.distinctDeals(citizen.getRecolorReplace()).length == 0)
			{
				if (everyRotationIsTheIdentity(citizen.getRecolorReplace()))
				{
					everyRedealIsTheSame++;
				}
				else
				{
					everyRedealCrossesTheSkin++;
				}
				continue;
			}

			seeds++;
		}

		assertEquals("cameos, refused before anything else is asked", 6, cameos);
		assertEquals("dressed from a composition, so there is no palette to re-deal",
			1, dressedFromAnNpc);
		assertEquals("records that refuse the derivation outright, which is the 127 "
				+ "liveried townsfolk of 2026-09-01 and nothing else — see "
				+ "EntityRecord.noEcho", 127, refusedByTheirOwnRecord);
		assertEquals("sitting on something, miming a tool, welded to a bench, scaled or "
				+ "nudged — a body an anonymous passer-by cannot have", 48, bodyIsDoingSomething);
		assertEquals("citizens that get as far as the palette check", 87, reachThePaletteCheck);
		assertEquals("of those, the ones with no second slot to deal into", 22, tooFewPairs);
		assertEquals("and the ones whose every re-deal is the deal it started with",
			1, everyRedealIsTheSame);
		assertEquals("and the ones whose every re-deal would move a colour across the "
				+ "flesh boundary", 36, everyRedealCrossesTheSkin);
		assertEquals("leaving the seeds", 28, seeds);

		assertEquals("the palette check sees everything the three gates above it let through",
			reachThePaletteCheck,
			tooFewPairs + everyRedealIsTheSame + everyRedealCrossesTheSkin + seeds);
		assertEquals("and the gates between them account for every citizen in the dataset "
				+ "exactly once — a set of counts that does not add up is the drift this "
				+ "test exists to catch",
			269, cameos + dressedFromAnNpc + refusedByTheirOwnRecord + bodyIsDoingSomething
				+ reachThePaletteCheck);
		assertEquals("citizens that seed nothing", 22 + 1 + 36 + 48 + 6 + 1 + 127, 269 - seeds);
	}

	/**
	 * The two populations the ring of fallback tiles serves, counted from the shipped
	 * files.
	 *
	 * <p>{@code appendRingCandidates}'s javadoc names both — the citizens with no
	 * authored box at all, and the wanderers whose box cannot supply every echo they
	 * ask for — and both were stale. The second one cannot be counted from the record
	 * alone: whether a box can hold two well-separated echoes depends on who else is
	 * already standing in the region, so it is read back off the placement itself
	 * through {@link EntityDefinition#isEchoOnAuthoredGround()}.
	 */
	@Test
	public void theRingServesTheCitizensWithNoBoxAndTheWanderersWhoseBoxIsNotEnough()
	{
		int citizens = 0;
		int withNoBox = 0;
		for (EntityDefinition entity : shippedEntities())
		{
			if (!entity.getType().isCitizen())
			{
				continue;
			}

			citizens++;
			if (entity.getWanderBox() == null)
			{
				withNoBox++;
			}
		}

		assertEquals("the authored citizen roster", 269, citizens);
		assertEquals("citizens with no authored box, for whom the ring is the only source "
				+ "of candidate ground", 206, withNoBox);
		assertEquals("the rest carry one", 63, citizens - withNoBox);

		int toppedUpFromTheRing = 0;
		int echoesPushedOffABox = 0;
		List<String> where = new ArrayList<>();
		for (Map.Entry<Integer, List<EntityDefinition>> region : shippedRosters().entrySet())
		{
			List<EntityDefinition> roster = region.getValue();

			Map<UUID, EntityDefinition> byUuid = new HashMap<>();
			for (EntityDefinition entity : roster)
			{
				byUuid.put(entity.getUuid(), entity);
			}

			Map<UUID, Integer> fromTheBox = new HashMap<>();
			for (EntityDefinition echo : CitizenEcho.echoesOfRegion(roster))
			{
				if (echo.isEchoOnAuthoredGround())
				{
					fromTheBox.merge(echo.getEchoSourceUuid(), 1, Integer::sum);
					continue;
				}

				EntityDefinition source = byUuid.get(echo.getEchoSourceUuid());
				if (source != null && source.getWanderBox() != null)
				{
					echoesPushedOffABox++;
				}
			}

			for (EntityDefinition source : roster)
			{
				if (source.getWanderBox() == null || source.isCameo()
					|| source.isNoEcho()
					|| source.getNpcAppearanceId() != 0
					|| !CitizenEcho.isAnOrdinaryStandingBody(source)
					|| source.getRecolorFind().length < 2
					|| source.getRecolorReplace().length < 2)
				{
					continue;
				}

				int[] deals = CitizenEcho.distinctDeals(source.getRecolorReplace());
				if (deals.length == 0)
				{
					continue;
				}

				int wanted = Math.min(deals.length, CitizenEcho.MAX_ECHOES_PER_CITIZEN);
				if (fromTheBox.getOrDefault(source.getUuid(), 0) < wanted)
				{
					toppedUpFromTheRing++;
					where.add(source.label() + " in " + region.getKey() + ".json");
				}
			}
		}

		assertEquals("wanderers whose own box could not supply every echo they asked for: "
				+ where, 2, toppedUpFromTheRing);

		// The same fact counted in echoes rather than in sources, because CitizenEcho's
		// "What that costs" paragraph quotes it in echoes and said "four" for as long as
		// nothing checked it. A wanderer that gets neither of its two echoes out of its
		// own box contributes two to this and one to the count above.
		assertEquals("echoes whose source carries a box but which stand on a ring offset "
				+ "instead, because no box tile was far enough from everything else",
			3, echoesPushedOffABox);
	}

	/**
	 * Every uuid in play — 142 authored citizens, 42 scenery records and 51 echoes —
	 * has to be distinct.
	 *
	 * <p>A collision would mean two entities the user cannot tell apart in the
	 * hidden/muted settings: hiding one would hide the other, permanently, and the
	 * derivation would be the reason. Asserted over the whole roster rather than
	 * argued from the mixer's properties.
	 */
	@Test
	public void everyDerivedUuidIsDistinctFromEveryOtherUuidInTheDataset()
	{
		Set<UUID> seen = new HashSet<>();
		List<String> clashes = new ArrayList<>();

		for (EntityDefinition entity : shippedEntities())
		{
			if (!seen.add(entity.getUuid()))
			{
				clashes.add("authored " + entity.label() + " " + entity.getUuid());
			}
		}

		for (EntityDefinition echo : shippedEchoes())
		{
			if (!seen.add(echo.getUuid()))
			{
				clashes.add("echo of " + echo.getEchoSourceUuid() + " " + echo.getUuid());
			}
		}

		assertTrue("uuid collision(s): " + clashes, clashes.isEmpty());
		assertEquals("311 authored entities plus 51 echoes", 362, seen.size());
	}

	/**
	 * <b>Nobody stands inside anybody.</b> Every pair of entities the plugin would
	 * render out of the shipped dataset, at the same storey, at least
	 * {@link CitizenEcho#MIN_SEPARATION_TILES} apart — authored citizens, scenery and
	 * echoes, all in one pot.
	 *
	 * <p>This is the widened form of a test that used to compare each echo against
	 * its own source and its own sibling and nothing else. That is not what the rule
	 * says, and the dataset proved it: judged one lineage at a time, the shipped files
	 * produced <b>41 pairs</b> closer than the minimum — 57 counted once per echo
	 * rather than once per pair — of which three were exact same-tile collisions and
	 * two of those were echo on echo. Twins standing in each other, produced by the
	 * rule against twins standing in each other. The fixture tests above cannot catch
	 * that class of fault at all, because a fixture with one citizen in it has no
	 * other lineage to collide with; only the real dataset does.
	 *
	 * <p><b>It walks the whole dataset rather than one region at a time</b>, so it is
	 * a wider net than {@link CitizenEcho#echoesOfRegion} casts: that method can only
	 * separate an echo from the region file it was derived with, and two entities
	 * either side of a region border are outside its reach. The shipped files have no
	 * such pair (they had none before this change either), so the net is empty rather
	 * than slack — and if a future region file ever creates one, this goes red and
	 * somebody has to decide what to do about it, which is the right outcome for a
	 * problem the derivation cannot see.
	 *
	 * <p><b>Authored against authored is excluded, and counted instead.</b> 42 pairs
	 * of hand-placed entities are closer than the minimum and eight of those share a
	 * tile exactly — a stall and its owner, two guards on a gate. A human chose those
	 * and this feature has no vote on them; what it must not do is add to them. The
	 * count is pinned so that "excluded" cannot quietly grow to cover a derived
	 * offender.
	 */
	@Test
	public void noTwoShippedRenderedEntitiesStandCloserThanTheMinimum()
	{
		List<EntityDefinition> rendered = new ArrayList<>(shippedEntities());
		int authoredCount = rendered.size();
		rendered.addAll(shippedEchoes());

		List<String> violations = new ArrayList<>();
		int authoredPairs = 0;
		int authoredCollisions = 0;

		for (int i = 0; i < rendered.size(); i++)
		{
			for (int j = i + 1; j < rendered.size(); j++)
			{
				EntityDefinition a = rendered.get(i);
				EntityDefinition b = rendered.get(j);

				if (a.getPlane() != b.getPlane())
				{
					// A different storey is not the same tile.
					continue;
				}

				int distance = RenderPolicy.tileDistance(a.getWorldLocation(), b.getWorldLocation());
				if (distance >= CitizenEcho.MIN_SEPARATION_TILES)
				{
					continue;
				}

				if (!a.isEcho() && !b.isEcho())
				{
					authoredPairs++;
					if (distance == 0)
					{
						authoredCollisions++;
					}
					continue;
				}

				violations.add(describe(a) + " and " + describe(b) + " are " + distance
					+ " tile(s) apart at " + a.getWorldLocation() + " / " + b.getWorldLocation());
			}
		}

		assertEquals("the fixture has to be the whole authored roster", 311, authoredCount);
		assertTrue("separation violation(s) involving a derived citizen: " + violations,
			violations.isEmpty());
		assertEquals("hand-placed entities closer than the minimum to each other, which is "
				+ "authored content and none of this feature's business", 42, authoredPairs);
		assertEquals("of which this many share a tile exactly", 8, authoredCollisions);
	}

	/**
	 * Every shipped echo wears its source's own colours, re-dealt.
	 *
	 * <p>The same three claims as the fixture test, over the 44 real echoes. What
	 * this adds is coverage of the dataset's awkward palettes — repeated colours,
	 * eleven-pair wardrobes — where a rotation can quietly come out as the identity.
	 */
	@Test
	public void everyShippedEchoWearsAReDealOfItsSourcesOwnPalette()
	{
		Map<UUID, EntityDefinition> sources = new HashMap<>();
		for (EntityDefinition entity : shippedEntities())
		{
			sources.put(entity.getUuid(), entity);
		}

		List<String> violations = new ArrayList<>();
		Map<UUID, List<short[]>> palettesBySource = new HashMap<>();

		for (EntityDefinition echo : shippedEchoes())
		{
			EntityDefinition source = sources.get(echo.getEchoSourceUuid());
			assertNotNull("every echo has to name a source in the same dataset", source);

			short[] sourceReplace = source.getRecolorReplace();
			short[] sourceSorted = sourceReplace.clone();
			Arrays.sort(sourceSorted);

			if (!Arrays.equals(source.getRecolorFind(), echo.getRecolorFind()))
			{
				violations.add(describe(echo) + " recolours different slots from " + source.label());
			}

			short[] sorted = echo.getRecolorReplace().clone();
			Arrays.sort(sorted);
			if (!Arrays.equals(sourceSorted, sorted))
			{
				violations.add(describe(echo) + " wears a colour " + source.label() + " never wore");
			}

			if (Arrays.equals(sourceReplace, echo.getRecolorReplace()))
			{
				violations.add(describe(echo) + " is dressed identically to " + source.label());
			}

			List<short[]> siblings =
				palettesBySource.computeIfAbsent(echo.getEchoSourceUuid(), k -> new ArrayList<>());
			for (short[] sibling : siblings)
			{
				if (Arrays.equals(sibling, echo.getRecolorReplace()))
				{
					violations.add(describe(echo) + " is dressed identically to its own sibling");
				}
			}
			siblings.add(echo.getRecolorReplace());
		}

		assertTrue("appearance violation(s): " + violations, violations.isEmpty());
	}

	/**
	 * <b>Which checkbox switches an echo off is a question about its source, not about
	 * the tile it happens to stand on</b> — and the shipped dataset is what makes the
	 * difference visible.
	 *
	 * <p>{@link City#isEnabled} fails open for a region no city claims, on purpose, so
	 * that a region file can ship one commit before its checkbox does
	 * ({@code CityTest.aRegionNoCityClaimsIsStillShown}). Four shipped echoes used to
	 * stand a few tiles over a border in a region nobody claimed — three derived from
	 * Piscatoris citizens, one from a Camelot citizen — so judging an echo by its own
	 * tile sent all four through that door: unticking Piscatoris or Camelot left them
	 * standing in an empty village. Asked of the source's region instead, they answer
	 * to the checkbox that governs the citizen they are copies of.
	 *
	 * <p><b>Those four are gone, and the shipped data has no replacement for them.</b>
	 * The nine-city cut on 2026-08-24 removed both Piscatoris and Camelot, and all 44
	 * echoes the surviving 27 regions seed now stand in a region their own source's
	 * city claims. So the stray count below is asserted at zero and is no longer the
	 * interesting assertion in this method. The 33 citizens added on 2026-08-29 did not
	 * reintroduce the case: every one of them stands well inside its own region, so
	 * their echoes cannot reach a border.
	 *
	 * <p>What is still asserted over the real files, and is the claim that actually
	 * matters, is the rule itself: <b>every one of the 51 echoes takes its governing
	 * region from its source's tile, not from its own.</b> That is checked echo by
	 * echo below and cannot go green by there being nothing to check. The two
	 * behavioural halves the strays used to demonstrate are checked directly instead —
	 * that the fail-open door is still open for an unclaimed region, and that unticking
	 * a real city really does switch off an echo derived from it — so no claim was
	 * dropped, only the geometry that used to make them vivid.
	 * {@code CrowdedSceneTest.untickingACityAlsoRemovesTheEchoesStandingInARegionNoCityClaims}
	 * keeps the stray case alive on a hand-built fixture.
	 */
	@Test
	public void everyShippedEchoIsGovernedByItsSourcesCityRatherThanByTheTileItStandsOn()
	{
		Map<UUID, EntityDefinition> sources = new HashMap<>();
		for (EntityDefinition entity : shippedEntities())
		{
			sources.put(entity.getUuid(), entity);
		}

		List<EntityDefinition> strays = new ArrayList<>();
		Map<String, Integer> strayRegions = new TreeMap<>();
		int checked = 0;

		for (EntityDefinition echo : shippedEchoes())
		{
			EntityDefinition source = sources.get(echo.getEchoSourceUuid());
			assertNotNull(source);

			assertEquals("an echo answers to whatever governs the citizen it came from",
				source.getTileRegionId(), echo.getCityRegionId());
			checked++;

			if (City.of(echo.getTileRegionId()) != City.of(source.getTileRegionId()))
			{
				strays.add(echo);
				strayRegions.merge(
					echo.getTileRegionId() + " from " + City.of(echo.getCityRegionId()), 1, Integer::sum);
			}
		}

		// The sample guard, in the same spirit as the rest of this file: the rule above
		// is inside the loop, so an empty roster would pass it having asked nothing.
		assertEquals("the whole shipped echo roster has to have been asked", 51, checked);

		assertEquals("echoes standing in a region their source's city does not claim — the "
				+ "shipped data no longer contains this case at all: " + strayRegions,
			0, strays.size());

		// The two halves the four strays used to demonstrate, asserted directly so that
		// removing them cost no coverage. 13110 is the Lumber Yard's square: it ships no
		// file and no city claims it, because the same cut deleted it.
		int unclaimed = 13110;
		assertNull("the fixture has to be genuinely unclaimed", City.of(unclaimed));
		assertTrue("an unclaimed region still fails open, for the authored entities the "
				+ "rule exists for",
			City.isEnabled(unclaimed, new FakeConfig().disable(City.values())));

		EntityDefinition anyEcho = shippedEchoes().get(0);
		City owner = City.of(anyEcho.getCityRegionId());
		assertNotNull("an echo's source still has a city, or this proves nothing", owner);
		assertFalse("unticking " + owner + " has to switch off an echo derived from it",
			City.isEnabled(anyEcho.getCityRegionId(), new FakeConfig().disableOnly(owner)));
		assertTrue("and leaving it ticked has to leave the echo alone",
			City.isEnabled(anyEcho.getCityRegionId(), new FakeConfig()));
	}

	/** An echo never changes storey, and never leaves the file its source was filed under. */
	@Test
	public void everyShippedEchoStaysOnItsSourcesStoreyAndInItsSourcesFile()
	{
		Map<UUID, EntityDefinition> sources = new HashMap<>();
		for (EntityDefinition entity : shippedEntities())
		{
			sources.put(entity.getUuid(), entity);
		}

		int checked = 0;
		for (EntityDefinition echo : shippedEchoes())
		{
			EntityDefinition source = sources.get(echo.getEchoSourceUuid());
			assertNotNull(source);
			assertEquals("an echo never changes storey", source.getPlane(), echo.getPlane());
			assertEquals("nor the file it is discovered through",
				source.getRegionId(), echo.getRegionId());
			checked++;
		}

		assertEquals("the shipped echo roster", 51, checked);
	}

	private static String describe(EntityDefinition entity)
	{
		return (entity.isEcho() ? "echo of " + entity.getEchoSourceUuid() + " " : "authored ")
			+ entity.label();
	}

	/**
	 * Every echo the named shipped citizen seeds, derived with its whole region file
	 * around it — which is the only way the answer means anything, since placement is
	 * judged against everybody else in the file.
	 */
	private static List<EntityDefinition> echoesOfShipped(String name)
	{
		List<EntityDefinition> out = new ArrayList<>();
		boolean found = false;

		for (List<EntityDefinition> roster : shippedRosters().values())
		{
			UUID uuid = null;
			for (EntityDefinition entity : roster)
			{
				if (name.equals(entity.getName()))
				{
					uuid = entity.getUuid();
					found = true;
				}
			}

			if (uuid == null)
			{
				continue;
			}

			for (EntityDefinition echo : CitizenEcho.echoesOfRegion(roster))
			{
				if (uuid.equals(echo.getEchoSourceUuid()))
				{
					out.add(echo);
				}
			}
		}

		assertTrue("'" + name + "' has to still be in the dataset, or this proves nothing",
			found);
		return out;
	}

	/**
	 * How many <i>distinct</i> non-identity rotations a palette has, ignoring the
	 * flesh rule entirely.
	 *
	 * <p>Written out here rather than asked of {@link CitizenEcho} on purpose: it is
	 * the "before" figure the flesh rule is measured against, so computing it with the
	 * code under test would make the difference between the two numbers unfalsifiable.
	 * The arithmetic is small enough to state twice.
	 */
	private static int distinctRotationCount(short[] replace)
	{
		Set<List<Short>> seen = new HashSet<>();
		seen.add(boxed(replace));

		int distinct = 0;
		for (int k = 1; k < replace.length; k++)
		{
			if (seen.add(boxed(CitizenEcho.redeal(replace, k))))
			{
				distinct++;
			}
		}
		return distinct;
	}

	/** @return true if every rotation of this palette comes out as the palette itself */
	private static boolean everyRotationIsTheIdentity(short[] replace)
	{
		return distinctRotationCount(replace) == 0;
	}

	private static List<Short> boxed(short[] palette)
	{
		List<Short> out = new ArrayList<>(palette.length);
		for (short colour : palette)
		{
			out.add(colour);
		}
		return out;
	}

	private static void assertArray(short[] expected, short[] actual)
	{
		assertArray("", expected, actual);
	}

	private static void assertArray(String message, short[] expected, short[] actual)
	{
		assertTrue(message + " expected " + Arrays.toString(expected)
			+ " but was " + Arrays.toString(actual), Arrays.equals(expected, actual));
	}

	/**
	 * One citizen's echoes, derived as if it were the only thing in its region.
	 *
	 * <p>{@link CitizenEcho#echoesOfRegion} takes a whole region file, because
	 * separation is a claim about a tile and everything standing near it. A fixture
	 * with one citizen in it is a region with one citizen in it, and that is exactly
	 * what most of the tests above want: the derivation with nothing else in the way.
	 * The dataset tests below hand it real rosters instead.
	 */
	private static List<EntityDefinition> echoesOf(EntityDefinition source)
	{
		return CitizenEcho.echoesOfRegion(Collections.singletonList(source));
	}

	/**
	 * Every entity in the shipped dataset, through the real
	 * {@link EntityDefinition#fromRecord} — so wander boxes are the validated,
	 * clamped ones the game would use, which is what {@link CitizenEcho} places
	 * echoes inside.
	 */
	private static List<EntityDefinition> shippedEntities()
	{
		List<EntityDefinition> out = new ArrayList<>();
		for (List<EntityDefinition> roster : shippedRosters().values())
		{
			out.addAll(roster);
		}

		assertEquals("the whole shipped roster", 311, out.size());
		return out;
	}

	/**
	 * Every echo the shipped dataset seeds, derived the way the scene derives them:
	 * one whole region file at a time.
	 */
	private static List<EntityDefinition> shippedEchoes()
	{
		List<EntityDefinition> out = new ArrayList<>();
		for (List<EntityDefinition> roster : shippedRosters().values())
		{
			out.addAll(CitizenEcho.echoesOfRegion(roster));
		}
		return out;
	}

	/** The shipped rosters, keyed by region file, in ascending region order. */
	private static Map<Integer, List<EntityDefinition>> shippedRosters()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		Map<Integer, List<EntityDefinition>> out = new LinkedHashMap<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			out.put(regionId, region.getEntities());
		}

		return out;
	}
}

package com.matthewmariner.livelycities;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The strings and the colour that make a fake citizen legibly fake.
 *
 * <p>This is not string-formatting trivia. The hub disabled the predecessor over
 * a thread in which a player mistook a broken-looking fake NPC for a real one, so
 * "the menu row says whose it is, in a colour the game never uses" is the
 * plugin's licence to exist. Every assertion here is one half of that sentence.
 */
public class CitizenLabelTest
{
	private final FakeRegions regions = new FakeRegions();

	/**
	 * The two spellings of the colour cannot drift.
	 *
	 * <p>{@link CitizenLabel#COLOUR_TAG} is written out as a literal rather than
	 * formatted from {@link CitizenLabel#FAKE_RGB}, so this is the guard that they
	 * are the same colour — and it is the whole reason writing it out is acceptable.
	 */
	@Test
	public void theColourTagAndTheColourAreTheSameColour()
	{
		assertEquals("<col=" + String.format("%06x", CitizenLabel.FAKE_RGB) + ">",
			CitizenLabel.COLOUR_TAG);
		assertEquals(CitizenLabel.FAKE_RGB, CitizenLabel.FAKE_COLOUR.getRGB() & 0xFFFFFF);
	}

	/**
	 * The colour must not be one the client already uses for a real menu target.
	 *
	 * <p>Yellow is an NPC, white is a player, cyan is a scene object, orange is an
	 * item. A colour that collided with any of them would defeat the entire feature
	 * while looking like it worked.
	 */
	@Test
	public void theColourIsNotAColourTheGameUsesForRealTargets()
	{
		int[] realTargetColours = {0xFFFF00, 0xFFFFFF, 0x00FFFF, 0xFF9040};
		for (int colour : realTargetColours)
		{
			assertFalse("the fake colour must not be " + String.format("%06x", colour),
				CitizenLabel.FAKE_RGB == colour);
		}
	}

	@Test
	public void theMenuTargetIsColouredAndNamesThePlugin()
	{
		EntityDefinition citizen = regions.citizen(12853, 3220, 3420, 0);
		String target = CitizenLabel.menuTarget(citizen);

		assertTrue("the target has to open with the colour tag, or the client shows it plain: " + target,
			target.startsWith(CitizenLabel.COLOUR_TAG));
		assertTrue("and close the span, or it bleeds into the rest of the row: " + target,
			target.endsWith("</col>"));
		assertTrue("it has to name the citizen: " + target,
			target.contains(citizen.getName()));
		assertTrue("and it has to name the plugin, inside the coloured span: " + target,
			target.contains(CitizenLabel.PLUGIN_NAME));

		// The plugin's name being inside the span is the point: a half-coloured row
		// reads as a real target with something appended.
		int pluginAt = target.indexOf(CitizenLabel.PLUGIN_NAME);
		int closeAt = target.indexOf("</col>");
		assertTrue("the plugin name must be inside the coloured span: " + target,
			pluginAt < closeAt);
	}

	/**
	 * A record with no {@code name} — every scenery record — still gets a label.
	 * A row reading {@code Examine  (Lively Cities)} would be the confusing outcome
	 * the whole class exists to prevent.
	 */
	@Test
	public void anUnnamedEntityStillGetsALabel()
	{
		EntityDefinition scenery = regions.scenery(12853, 3220, 3420);
		String target = CitizenLabel.menuTarget(scenery);

		assertTrue("an unnamed entity falls back to its type: " + target,
			target.contains(EntityType.Scenery.name()));
		assertFalse("and never produces an empty name: " + target,
			target.contains(CitizenLabel.COLOUR_TAG + " "));
	}

	/**
	 * The Examine line has to carry both halves: the dataset's own authored text,
	 * and the sentence that answers "who is this man?".
	 */
	@Test
	public void theExamineLineUsesTheAuthoredTextAndSaysWhoseCitizenItIs()
	{
		EntityDefinition talker = regions.talker(12853, 3220, 3420, "Busy today.");
		String message = CitizenLabel.examineMessage(talker);

		assertNotNull(talker.getExamineText());
		assertTrue("the authored examine text has to survive: " + message,
			message.contains(talker.getExamineText()));
		assertTrue("and the plugin has to be named: " + message,
			message.contains(CitizenLabel.PLUGIN_NAME));
		assertTrue("in as many words: " + message,
			message.contains("not a real NPC"));
		assertTrue("the name is coloured here too: " + message,
			message.contains(CitizenLabel.COLOUR_TAG + talker.getName() + "</col>"));
	}

	/**
	 * A citizen with no authored examine text still gets the sentence that matters.
	 * The shipped data has one for all 142, but a future record or a hand-written
	 * contribution need not.
	 */
	@Test
	public void anExamineLineWithNoAuthoredTextStillSaysWhoseItIs()
	{
		EntityDefinition plain = regions.citizen(12853, 3220, 3420, 0);
		assertNull("the fixture is only interesting without examine text", plain.getExamineText());

		String message = CitizenLabel.examineMessage(plain);
		assertTrue(message.contains(CitizenLabel.PLUGIN_NAME));
		assertTrue(message.contains("not a real NPC"));
		assertTrue("the citizen is still named: " + message,
			message.contains(plain.getName()));
		assertFalse("and the missing text must not leave a double space: " + message,
			message.contains("  "));
	}

	/**
	 * Authored examine text that is already a sentence must not gain a second full
	 * stop, and text that is not one must gain its first. All 142 shipped records
	 * end in a full stop; a hand-written contribution will not.
	 */
	@Test
	public void theExamineLinePunctuatesTheAuthoredTextExactlyOnce()
	{
		EntityDefinition citizen = regions.talker(12853, 3220, 3420, "Busy today.");
		assertEquals("the fixture's authored text is already a sentence",
			"A talkative citizen.", citizen.getExamineText());
		assertFalse("no doubled full stop: " + CitizenLabel.examineMessage(citizen),
			CitizenLabel.examineMessage(citizen).contains(".."));
	}

	/**
	 * Both confirmations have to name the way back. A right-click action whose undo
	 * lives in a settings panel the user has never opened is an action they report
	 * as a bug.
	 */
	@Test
	public void theHideAndMuteConfirmationsNameTheirUndo()
	{
		EntityDefinition talker = regions.talker(12853, 3220, 3420, "Busy today.");

		String hidden = CitizenLabel.hiddenMessage(talker, 1);
		assertTrue(hidden + " must name the config item that undoes it",
			hidden.contains("Unhide all citizens"));
		assertTrue(hidden.contains(CitizenLabel.PLUGIN_NAME));

		String muted = CitizenLabel.mutedMessage(talker, 1);
		assertTrue(muted + " must name the config item that undoes it",
			muted.contains("Unmute all citizens"));

		// The plural is not cosmetic: "bring them back" after hiding five people is
		// a message that undersells what the button does.
		assertTrue(CitizenLabel.hiddenMessage(talker, 5).contains("all 5 of them"));
	}
}

package com.matthewmariner.livelycities;

import java.awt.Rectangle;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The right-click menu: never competing for a click, unmistakably ours, and
 * sending nothing.
 *
 * <p>These three are, collectively, the plugin's licence to exist. The hub
 * disabled the predecessor after a Reddit thread in which a player mistook a
 * broken-looking fake NPC for a real one, and upstream issue #14 — 49 upvotes —
 * is "can't right-click through them" plus "misclicks when using an item". Both
 * are answered here or not at all.
 *
 * <p><b>How "sends nothing to the server" is asserted rather than asserted-to.</b>
 * {@link FakeClient} extends {@link StubClient}, in which every method this plugin
 * has never needed throws — including {@code Client.menuAction(..)}, the one call
 * on this surface that performs a real game action. {@link FakeMenuEntry} extends
 * {@link StubMenuEntry} on the same terms, so {@code onClick}, {@code setItemId}
 * and {@code setForceLeftClick} throw too. A handler that reached for any of them
 * would fail here, loudly, rather than ship.
 *
 * <p><b>The clickbox is a seam, and it has to be.</b>
 * {@code Perspective.getClickbox} projects a model through the live camera, so
 * {@link TestMenu} overrides it with a rectangle and, more importantly, counts how
 * many times it was asked. "No clickbox at all while an item is on the cursor" is a
 * claim about that count, not about the resulting menu.
 */
public class CitizenMenuTest
{
	private static final int VARROCK_NORTH = 12853;
	private static final WorldPoint PLAYER = new WorldPoint(3220, 3420, 0);

	/** Where the mouse is in every test that wants a hit. */
	private static final Point MOUSE = new Point(400, 300);

	private FakeClient client;
	private FakeRegions regions;
	private FakeConfig config;
	private EntityScene scene;
	private FakeWorldView view;
	private TestMenu menu;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		regions = new FakeRegions();
		config = new FakeConfig();
		scene = new EntityScene(client, regions, config, config.overrides());
		view = FakeWorldView.around(PLAYER, VARROCK_NORTH);
		menu = new TestMenu();

		client.setLocalPlayer(new FakePlayer(PLAYER));
		client.setTopLevelWorldView(view);
		client.setMouseCanvasPosition(MOUSE);

		// The menu the client itself would have built for a right-click on the world:
		// array order is bottom row first, so this renders as Talk-to / Walk here /
		// Cancel from the top.
		client.menu().seedWorldClick();
	}

	// --- never compete for a click (issue #14) --------------------------------

	@Test
	public void everyEntryIsRuneLiteTypedAndDeprioritised()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);

		menu.onMenuOpened(client.menuOpened());

		List<MenuEntry> created = client.menu().created();
		assertEquals("Examine, Hide and Mute", 3, created.size());
		for (MenuEntry entry : created)
		{
			assertEquals(entry + " must be a RUNELITE action — anything else can reach the server",
				MenuAction.RUNELITE, entry.getType());
			assertTrue(entry + " must be deprioritised, so it sorts below every real option",
				entry.isDeprioritized());
		}
	}

	/**
	 * The entries go in at index 0, which is the bottom row of the rendered menu.
	 *
	 * <p>The array is rendered last-first — {@code MenuOpened.getFirstEntry()}
	 * returns {@code menuEntries[length - 1]}, verified in the 1.12.36 bytecode — so
	 * the last array element is the top row <i>and</i> the left-click action. Our
	 * entries must be at the other end.
	 */
	@Test
	public void entriesAreInsertedBelowEveryRealOption()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);

		menu.onMenuOpened(client.menuOpened());

		List<MenuEntry> entries = client.menu().entries();
		assertEquals(6, entries.size());

		// The three ours, at the bottom of the menu, in the order they read on
		// screen: Examine highest of the three, Mute at the very bottom.
		assertEquals(CitizenMenu.OPTION_MUTE, entries.get(0).getOption());
		assertEquals(CitizenMenu.OPTION_HIDE, entries.get(1).getOption());
		assertEquals(CitizenMenu.OPTION_EXAMINE, entries.get(2).getOption());

		// And the real ones untouched above them, with the left-click action — the
		// last element — still the game's.
		assertEquals("Cancel", entries.get(3).getOption());
		assertEquals("Talk-to", entries.get(entries.size() - 1).getOption());
	}

	/**
	 * No clickbox at all while an item or a spell is on the cursor.
	 *
	 * <p>The specific reported complaint: a misclick while using an item on
	 * something. The assertion is on the projection <i>count</i> rather than on the
	 * menu, because "we computed a clickbox and then decided not to use it" would
	 * pass a menu-shaped test while still paying the cost and still being one
	 * refactor away from the bug.
	 */
	@Test
	public void noClickboxIsComputedWhileAnItemOrSpellIsOnTheCursor()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);

		client.setWidgetSelected(true);
		menu.onMenuOpened(client.menuOpened());

		assertEquals("not one clickbox may be computed in target mode", 0, menu.clickboxCalls);
		assertTrue("and not one entry may be added", client.menu().created().isEmpty());
		assertNull("nor may a target be remembered for a later click", menu.getTarget());

		// And it is only the target mode that stopped it.
		client.setWidgetSelected(false);
		menu.onMenuOpened(client.menuOpened());
		assertTrue(menu.clickboxCalls > 0);
		assertEquals(3, client.menu().created().size());
	}

	/**
	 * The clickbox is only computed for citizens close enough to be clickable.
	 *
	 * <p>The plan names the per-object convex hull as the known frame-time cost
	 * centre and the performance budget names 15 tiles. Nine citizens are spawned,
	 * three of them outside the radius; the count is what proves the far ones were
	 * never projected.
	 */
	@Test
	public void clickboxesAreOnlyComputedInsideTheClickboxRadius()
	{
		List<EntityDefinition> near = new ArrayList<>();
		for (int i = 0; i < 6; i++)
		{
			near.add(regions.talker(VARROCK_NORTH, 3221 + i, 3420, "Close by."));
		}
		// 16, 18 and 20 tiles east — inside the default 25-tile cull radius, so they
		// really are spawned, and outside the 15-tile clickbox radius.
		List<EntityDefinition> far = new ArrayList<>();
		for (int distance : new int[]{16, 18, 20})
		{
			far.add(regions.talker(VARROCK_NORTH, 3220 + distance, 3420, "Miles away."));
		}

		List<EntityDefinition> all = new ArrayList<>(near);
		all.addAll(far);
		spawn(all.toArray(new EntityDefinition[0]));
		assertEquals("all nine have to be on screen, or the radius is not what excluded them",
			9, scene.countActive());

		// Nothing is under the mouse, so every candidate gets projected.
		menu.hit = false;
		menu.onMenuOpened(client.menuOpened());

		assertEquals("only the six inside 15 tiles may be projected", 6, menu.clickboxCalls);
	}

	/**
	 * Nothing is added to an interface's right-click menu.
	 *
	 * <p>The clickbox is in canvas space and the inventory is drawn over the
	 * viewport, so a citizen standing behind it really does project underneath it —
	 * and without the guard, right-clicking a rune would offer to examine him. The
	 * two seeds differ only in whether the client put a "Walk here" in the menu,
	 * which is exactly the signal the guard reads.
	 */
	@Test
	public void nothingIsAddedToAnInterfacesRightClickMenu()
	{
		FakeClient interfaceClient = new FakeClient();
		interfaceClient.setLocalPlayer(new FakePlayer(PLAYER));
		interfaceClient.setTopLevelWorldView(view);
		interfaceClient.setMouseCanvasPosition(MOUSE);
		interfaceClient.menu().seedInterfaceClick();

		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		regions.file(VARROCK_NORTH, citizen);
		EntityScene interfaceScene = new EntityScene(
			interfaceClient, regions, config, config.overrides());
		interfaceScene.syncRegions(view);
		interfaceScene.updateVisibility(PLAYER, view);
		assertTrue("the citizen has to be on screen, or the guard is not what stopped this",
			interfaceScene.countActive() > 0);

		TestMenu interfaceMenu = new TestMenu(interfaceClient, interfaceScene);
		interfaceMenu.onMenuOpened(interfaceClient.menuOpened());

		assertEquals("an interface menu has no tile under it, so no clickbox may be computed",
			0, interfaceMenu.clickboxCalls);
		assertTrue("and nothing of ours may be in it",
			interfaceClient.menu().created().isEmpty());
	}

	// --- the minimap hole (issue #2) ------------------------------------------
	//
	// The "Walk here" test above is the client's own answer to "was this the world?",
	// and it is wrong for exactly one interface. These eight pin the premise, the three
	// toplevel layouts the guard has to work in, and the four ways it deliberately
	// declines to fire. Every one of them uses the same seeded menu and the same mouse
	// position, so the only thing that varies is what the interface layout says is
	// under the cursor.

	/**
	 * The premise, pinned before the fix that depends on it.
	 *
	 * <p>A minimap right-click carries a {@code MenuAction.WALK} like any ground
	 * click, so {@code isWorldClick} passes it — and with nothing else to go on, the
	 * plugin offers its entries. This is the bug from issue #2 reproduced, and it is
	 * <i>also</i> the documented fail-open behaviour: when the guard cannot find a
	 * minimap widget to measure against, it leaves the old behaviour alone rather than
	 * withholding the plugin's menu from a region of the screen it is guessing about.
	 */
	@Test
	public void aMinimapMenuLooksExactlyLikeAWorldMenuSoTheGuardHasToBeGeometric()
	{
		FakeClient bare = new FakeClient();
		TestMenu bareMenu = menuUnderTheMinimapFixture(bare, FakeMenu::seedMinimapClick);

		bareMenu.onMenuOpened(bare.menuOpened());

		assertEquals("nothing on a minimap menu distinguishes it from a ground menu, so with "
				+ "no widget to measure against the entries go in — the hole itself",
			3, bare.menu().created().size());
	}

	@Test
	public void nothingIsAddedToAMinimapRightClickInFixedMode()
	{
		assertNothingIsOfferedUnderTheMinimap(new FakeClient()
			.withWidget(InterfaceID.Toplevel.MAPCONTAINER, minimapPanelUnderTheMouse()));
	}

	@Test
	public void nothingIsAddedToAMinimapRightClickInTheClassicResizableLayout()
	{
		assertNothingIsOfferedUnderTheMinimap(new FakeClient()
			.resizedWith(InterfaceID.TOPLEVEL_OSRS_STRETCH)
			.withWidget(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER, minimapPanelUnderTheMouse()));
	}

	@Test
	public void nothingIsAddedToAMinimapRightClickInTheModernResizableLayout()
	{
		assertNothingIsOfferedUnderTheMinimap(new FakeClient()
			.resizedWith(InterfaceID.TOPLEVEL_PRE_EOC)
			.withWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER, minimapPanelUnderTheMouse()));
	}

	/**
	 * Each layout asks about its own component id and only its own.
	 *
	 * <p>Three ids, one of which is right at any moment, and the wrong one resolving to
	 * {@code null} is what {@code Client.getWidget(int)} really does for an interface
	 * that is not loaded. Without this, a version that asked about all three — or about
	 * the wrong one — would pass every test above.
	 */
	@Test
	public void eachLayoutAsksAboutItsOwnMinimapIdAndNotTheOthers()
	{
		// Fixed mode, with both resizable panels registered under the mouse.
		assertTheCitizenIsStillOffered(new FakeClient()
			.withWidget(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER, minimapPanelUnderTheMouse())
			.withWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER, minimapPanelUnderTheMouse()));

		// Modern resizable, with the classic panel registered.
		assertTheCitizenIsStillOffered(new FakeClient()
			.resizedWith(InterfaceID.TOPLEVEL_PRE_EOC)
			.withWidget(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER, minimapPanelUnderTheMouse())
			.withWidget(InterfaceID.Toplevel.MAPCONTAINER, minimapPanelUnderTheMouse()));

		// Classic resizable, with the modern panel registered.
		assertTheCitizenIsStillOffered(new FakeClient()
			.resizedWith(InterfaceID.TOPLEVEL_OSRS_STRETCH)
			.withWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER, minimapPanelUnderTheMouse())
			.withWidget(InterfaceID.Toplevel.MAPCONTAINER, minimapPanelUnderTheMouse()));
	}

	/**
	 * A minimap the client is not drawing suppresses nothing.
	 *
	 * <p>This is not tidiness, and it is the case {@code isHidden()} actually exists for
	 * — see {@code CitizenMenu.isOverMinimap}'s javadoc. The panel here is a
	 * <i>positioned</i> one: the client laid it out, so it owns a real rectangle over
	 * the minimap and the mouse is inside it, and it has since been marked hidden. On
	 * geometry alone the guard would fire and the citizen would be withheld under a
	 * minimap that is not on screen; the flag is what stops that. Delete the
	 * {@code isHidden()} branch and this test is the one that goes red.
	 */
	@Test
	public void aMinimapTheClientIsNotDrawingSuppressesNothing()
	{
		assertTheCitizenIsStillOffered(new FakeClient()
			.withWidget(InterfaceID.Toplevel.MAPCONTAINER, minimapPanelUnderTheMouse().hidden()));
	}

	/**
	 * A right-click beside the panel is still a world click — the rectangle has to be
	 * measured rather than merely found.
	 *
	 * <p>A real 157x157 panel in the fixed layout's top-left corner, laid out and drawn.
	 * The mouse is nowhere near it, and the citizen is offered — so a version of the
	 * guard that fired on merely <i>finding</i> a panel, without measuring it, fails
	 * here.
	 */
	@Test
	public void aRightClickBesideTheMinimapPanelIsStillAWorldClick()
	{
		assertTheCitizenIsStillOffered(new FakeClient()
			.withWidget(InterfaceID.Toplevel.MAPCONTAINER, FakeWidget.at(570, 4, 157, 157)));
	}

	/**
	 * A panel the client has never laid out suppresses nothing either — and it needs no
	 * emptiness check to get there.
	 *
	 * <p><b>These are the numbers the real widget produces, not a fixture invented to
	 * make a point.</b> Disassembling {@code lw} in injected-client-1.12.36: the no-arg
	 * constructor sets the two canvas coordinates {@code cz} and {@code ca} to
	 * {@code -1} and the raw width and height fields {@code cv} and {@code do} to
	 * {@code 0}, and {@code getBounds()} is {@code new Rectangle(cz, ca, getWidth(),
	 * getHeight())}. So an unpositioned panel's bounds is {@code Rectangle(-1, -1, 0,
	 * 0)}, {@code Rectangle.contains} says no to every point in it, and this is a world
	 * click.
	 *
	 * <p>Which is why {@code isOverMinimap} carries no null or emptiness check on the
	 * rectangle: {@code getBounds()} never returns null, and {@code contains()} already
	 * answers the degenerate case. An earlier revision of that javadoc claimed the
	 * unpositioned panel reported a rectangle at canvas <i>(0, 0)</i> — the coordinates
	 * are {@code -1}, the width comes off {@code cv} rather than the interface
	 * definition's {@code dd}, and the test that pinned the invented behaviour used
	 * {@code FakeWidget.at(0, 0, 500, 400)}, a box no client would produce. This
	 * replaces it with what the client really produces.
	 */
	@Test
	public void aPanelTheClientHasNeverLaidOutSuppressesNothing()
	{
		assertTheCitizenIsStillOffered(new FakeClient()
			.withWidget(InterfaceID.Toplevel.MAPCONTAINER, FakeWidget.neverLaidOut()));
	}

	@Test
	public void nothingIsAddedWhenTheMouseIsNotOverACitizen()
	{
		spawn(regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today."));

		menu.hit = false;
		menu.onMenuOpened(client.menuOpened());

		assertTrue("a clickbox that does not contain the mouse is not a hit",
			client.menu().created().isEmpty());
		assertNull(menu.getTarget());
	}

	/**
	 * A citizen with nothing to say gets no Mute entry. An entry that cannot do
	 * anything is worse than a missing one: the user who clicks it learns that the
	 * plugin's menu lies.
	 */
	@Test
	public void aCitizenWithNothingToSayIsNotOfferedMute()
	{
		spawn(regions.citizen(VARROCK_NORTH, 3220, 3421, 0));

		menu.onMenuOpened(client.menuOpened());

		List<MenuEntry> created = client.menu().created();
		assertEquals("Examine and Hide, but not Mute", 2, created.size());
		for (MenuEntry entry : created)
		{
			assertFalse(CitizenMenu.OPTION_MUTE.equals(entry.getOption()));
		}
	}

	// --- fake is unmistakable from real ---------------------------------------

	@Test
	public void theMenuTargetCarriesTheColourAndThePluginsName()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);

		menu.onMenuOpened(client.menuOpened());

		for (MenuEntry entry : client.menu().created())
		{
			assertTrue(entry.getTarget() + " must open with the plugin's colour tag",
				entry.getTarget().startsWith(CitizenLabel.COLOUR_TAG));
			assertTrue(entry.getTarget() + " must name the plugin",
				entry.getTarget().contains(CitizenLabel.PLUGIN_NAME));
			assertTrue(entry.getTarget() + " must name the citizen",
				entry.getTarget().contains(citizen.getName()));
		}
	}

	/**
	 * Examine prints the dataset's own text plus the sentence that says whose
	 * citizen it is, and it does so into the local chat buffer — which is the whole
	 * of what it does.
	 */
	@Test
	public void examinePrintsLocallyAndSaysWhoseCitizenItIs()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);
		menu.onMenuOpened(client.menuOpened());

		MenuOptionClicked event = click(CitizenMenu.OPTION_EXAMINE, citizen);
		menu.onMenuOptionClicked(event);

		assertTrue("the click has to be consumed", event.isConsumed());
		assertEquals(1, client.chatMessages().size());
		String message = client.chatMessages().get(0);
		assertTrue(message, message.contains(citizen.getExamineText()));
		assertTrue(message, message.contains(CitizenLabel.PLUGIN_NAME));
		assertTrue(message, message.contains("not a real NPC"));
	}

	// --- sends nothing to the server -----------------------------------------

	/**
	 * A click is consumed and reaches nothing but the chat buffer and this plugin's
	 * own config.
	 *
	 * <p>The negative half is structural rather than counted: every other route into
	 * the client — {@code menuAction} above all — throws on {@link StubClient}, and
	 * every setter on {@link StubMenuEntry} that could change what a click does
	 * throws too. Reaching one is a test error, not a silent pass. This test walks
	 * all three options through so that every branch of the handler is on that
	 * hook.
	 */
	@Test
	public void everyClickIsConsumedAndSendsNothingToTheServer()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);

		for (String option : new String[]{
			CitizenMenu.OPTION_EXAMINE, CitizenMenu.OPTION_MUTE, CitizenMenu.OPTION_HIDE})
		{
			menu.onMenuOpened(client.menuOpened());
			MenuOptionClicked event = click(option, citizen);
			menu.onMenuOptionClicked(event);
			assertTrue(option + " must be consumed", event.isConsumed());
		}

		assertEquals("three clicks, three local lines and nothing else",
			3, client.chatMessages().size());
	}

	/**
	 * A RUNELITE entry with the same option text that is not ours must fall through
	 * untouched — not be consumed, and not act.
	 *
	 * <p>"Examine" is a common option, and consuming somebody else's would break
	 * their plugin invisibly.
	 */
	@Test
	public void anotherPluginsRuneLiteEntryIsLeftAlone()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);
		menu.onMenuOpened(client.menuOpened());

		// Right type, right text, wrong target and wrong identifier.
		MenuOptionClicked foreign = new MenuOptionClicked(new FakeMenuEntry()
			.setOption(CitizenMenu.OPTION_EXAMINE)
			.setTarget("<col=ffff00>Man")
			.setType(MenuAction.RUNELITE)
			.setIdentifier(9999));

		menu.onMenuOptionClicked(foreign);

		assertFalse("another plugin's entry must not be consumed", foreign.isConsumed());
		assertTrue("and must not have done anything", client.chatMessages().isEmpty());
	}

	/**
	 * The target check, isolated: same type, same option text, and — by coincidence —
	 * the same identifier as ours.
	 *
	 * <p>Identifiers are small integers and every plugin picks its own, so a
	 * collision is a matter of time. This is the case the target comparison exists
	 * for, and without a test where the identifier matches, the comparison is
	 * unreachable and a mutation removing it stays green.
	 */
	@Test
	public void anotherPluginsEntryWithTheSameIdentifierIsStillLeftAlone()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);
		menu.onMenuOpened(client.menuOpened());

		MenuOptionClicked collision = new MenuOptionClicked(new FakeMenuEntry()
			.setOption(CitizenMenu.OPTION_HIDE)
			.setTarget("<col=ffff00>Man")
			.setType(MenuAction.RUNELITE)
			.setIdentifier(currentToken()));

		menu.onMenuOptionClicked(collision);

		assertFalse("an identifier collision must not be enough to act on", collision.isConsumed());
		assertTrue("and nothing may have been hidden",
			config.overrides().hiddenUuids().isEmpty());
	}

	/**
	 * The identifier check, isolated: our own target, from a menu that has since been
	 * replaced.
	 *
	 * <p>A second right-click bumps the token, so a click event still carrying the
	 * first one is stale — the user right-clicked somebody else in between. Acting on
	 * it would examine or hide the wrong citizen. Without a test where the target
	 * matches, the identifier comparison is unreachable.
	 */
	@Test
	public void aStaleClickFromAnEarlierMenuIsIgnored()
	{
		EntityDefinition first = regions.talker(VARROCK_NORTH, 3220, 3421, "One.");
		EntityDefinition second = regions.talker(VARROCK_NORTH, 3222, 3421, "Two.");
		spawn(first, second);

		menu.onMenuOpened(client.menuOpened());
		MenuOptionClicked stale = click(CitizenMenu.OPTION_HIDE, menu.getTarget().getDefinition());

		// A second right-click, which bumps the token.
		menu.onMenuOpened(client.menuOpened());
		assertNotEquals("the second menu has to have a different token",
			stale.getId(), currentToken());

		menu.onMenuOptionClicked(stale);

		assertFalse("a click from a menu that has been replaced must not act",
			stale.isConsumed());
		assertTrue(config.overrides().hiddenUuids().isEmpty());
	}

	/**
	 * A non-RUNELITE click is never touched, whatever it says. This is the type
	 * check, and without it the handler would consume real game actions.
	 */
	@Test
	public void aRealGameActionIsNeverTouched()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);
		menu.onMenuOpened(client.menuOpened());

		MenuOptionClicked real = new MenuOptionClicked(new FakeMenuEntry()
			.setOption(CitizenMenu.OPTION_EXAMINE)
			.setTarget(CitizenLabel.menuTarget(citizen))
			.setType(MenuAction.EXAMINE_NPC)
			.setIdentifier(1));

		menu.onMenuOptionClicked(real);

		assertFalse("a real EXAMINE_NPC must reach the client untouched", real.isConsumed());
		assertTrue(client.chatMessages().isEmpty());
	}

	/**
	 * A click arriving with no open menu behind it — a stale event, or one for a
	 * menu that was invalidated by a scene change — does nothing rather than acting
	 * on whoever was last right-clicked.
	 */
	@Test
	public void aClickWithNoRememberedTargetDoesNothing()
	{
		EntityDefinition citizen = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(citizen);
		menu.onMenuOpened(client.menuOpened());

		MenuOptionClicked event = click(CitizenMenu.OPTION_EXAMINE, citizen);
		menu.forget();
		menu.onMenuOptionClicked(event);

		assertFalse(event.isConsumed());
		assertTrue(client.chatMessages().isEmpty());
	}

	// --- hide one citizen (issue #40) -----------------------------------------

	/**
	 * Hide writes the uuid, and the visibility pass takes the citizen off the
	 * screen. Nothing in {@link CitizenMenu} despawns anything: the write posts a
	 * {@code ConfigChanged} and the pass has one rule — what is not wanted is
	 * despawned.
	 */
	@Test
	public void hidingACitizenWritesItsUuidAndTakesItOffTheScreen()
	{
		EntityDefinition hide = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		EntityDefinition keep = regions.talker(VARROCK_NORTH, 3221, 3421, "Still here.");
		spawn(hide, keep);
		assertEquals(2, scene.countActive());

		menu.onMenuOpened(client.menuOpened());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_HIDE, hide));

		assertEquals("the uuid is what is persisted, in canonical form",
			hide.getUuid().toString(), config.stored(CitizenOverrides.HIDDEN_KEY));

		scene.updateVisibility(PLAYER, view);
		assertEquals("only the hidden one goes", 1, scene.countActive());
		assertFalse("and it is the right one", scene.wrapperFor(hide).isActive());
		assertTrue(scene.wrapperFor(keep).isActive());
	}

	/**
	 * A hidden citizen stays hidden across a scene change, and after its wrapper has
	 * been evicted and rebuilt from the region file.
	 *
	 * <p>This is the test that the hide lives in the config rather than on the
	 * wrapper. An implementation that latched a flag on {@link LivelyEntity} would
	 * pass the previous test and fail this one: eviction drops the wrapper, and the
	 * rebuilt one would come back visible.
	 */
	@Test
	public void aHiddenCitizenStaysHiddenAcrossASceneChange()
	{
		EntityDefinition hide = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(hide);

		menu.onMenuOpened(client.menuOpened());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_HIDE, hide));
		scene.updateVisibility(PLAYER, view);
		assertEquals(0, scene.countActive());

		// Walk far enough away that the region leaves the scene and its wrappers are
		// evicted, then come back.
		WorldPoint elsewhere = new WorldPoint(3600, 3200, 0);
		FakeWorldView away = FakeWorldView.around(elsewhere, RenderPolicy.regionIdOf(3600, 3200));
		for (int i = 0; i <= EntityScene.EVICTION_GRACE_SCOPE_CHANGES + 1; i++)
		{
			away.setMapRegions(RenderPolicy.regionIdOf(3600, 3200) + i);
			scene.syncRegions(away);
		}
		assertEquals("the region has to have been evicted for this test to mean anything",
			0, scene.getCachedRegionCount());

		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);

		assertEquals("a rebuilt wrapper for a hidden uuid must still be hidden",
			0, scene.countActive());
	}

	/**
	 * The hide survives a round trip through the raw config string — which is what
	 * a restart is.
	 */
	@Test
	public void aHiddenCitizenSurvivesAConfigRoundTrip()
	{
		EntityDefinition hide = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(hide);
		menu.onMenuOpened(client.menuOpened());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_HIDE, hide));

		String persisted = config.stored(CitizenOverrides.HIDDEN_KEY);
		assertNotNull(persisted);

		// A new session: new config object, new overrides, new scene — everything the
		// second one knows came out of that string.
		FakeConfig reloaded = new FakeConfig();
		reloaded.writer().write(CitizenOverrides.HIDDEN_KEY, persisted);
		FakeClient freshClient = new FakeClient();
		EntityScene freshScene = new EntityScene(
			freshClient, regions, reloaded, reloaded.overrides());

		freshScene.syncRegions(view);
		freshScene.updateVisibility(PLAYER, view);

		assertEquals("the hide has to survive a restart", 0, freshScene.countActive());
	}

	@Test
	public void unhideAllBringsEveryHiddenCitizenBack()
	{
		EntityDefinition first = regions.talker(VARROCK_NORTH, 3220, 3421, "One.");
		EntityDefinition second = regions.talker(VARROCK_NORTH, 3221, 3421, "Two.");
		spawn(first, second);

		// Hidden one at a time, with a visibility pass between, because the menu
		// targets whichever citizen is nearest and still on screen — which is exactly
		// how a user would do it, two right-clicks apart.
		menu.onMenuOpened(client.menuOpened());
		assertEquals(first, menu.getTarget().getDefinition());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_HIDE, first));
		scene.updateVisibility(PLAYER, view);

		menu.onMenuOpened(client.menuOpened());
		assertEquals("with the first one gone, the menu targets the second",
			second, menu.getTarget().getDefinition());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_HIDE, second));
		scene.updateVisibility(PLAYER, view);

		assertEquals(0, scene.countActive());
		assertEquals(2, config.overrides().hiddenUuids().size());

		assertEquals("both come back", 2, config.overrides().unhideAll());

		scene.updateVisibility(PLAYER, view);
		assertEquals(2, scene.countActive());
		assertNull("and the key is unset rather than left holding an empty string",
			config.stored(CitizenOverrides.HIDDEN_KEY));
	}

	// --- mute one citizen -----------------------------------------------------

	/**
	 * Mute writes the uuid and stops that citizen's current remark on the click.
	 *
	 * <p>Both halves matter: the write is what makes it last, and clearing the
	 * remark is what makes the click look like it worked — a mute that took up to
	 * the whole dwell to become visible is a mute users report as broken.
	 */
	@Test
	public void mutingACitizenPersistsAndShutsItUpOnTheClick()
	{
		EntityDefinition mute = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		EntityDefinition keep = regions.talker(VARROCK_NORTH, 3221, 3421, "Still talking.");
		spawn(mute, keep);

		CitizenRemarks muted = scene.wrapperFor(mute).getRemarks();
		CitizenRemarks other = scene.wrapperFor(keep).getRemarks();
		assertNotNull(muted);
		assertNotNull(other);
		muted.say(0, Integer.MAX_VALUE);
		other.say(0, Integer.MAX_VALUE);

		menu.onMenuOpened(client.menuOpened());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_MUTE, mute));

		assertEquals(mute.getUuid().toString(), config.stored(CitizenOverrides.MUTED_KEY));
		assertFalse("the muted citizen stops mid-remark", muted.isTalking());
		assertTrue("and nobody else does", other.isTalking());
		assertTrue("the citizen stays visible — mute is not hide",
			scene.wrapperFor(mute).isActive());
	}

	@Test
	public void unmuteAllLetsEveryMutedCitizenTalkAgain()
	{
		EntityDefinition mute = regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today.");
		spawn(mute);
		menu.onMenuOpened(client.menuOpened());
		menu.onMenuOptionClicked(click(CitizenMenu.OPTION_MUTE, mute));
		assertEquals(1, config.overrides().mutedUuids().size());

		assertEquals(1, config.overrides().unmuteAll());
		assertTrue(config.overrides().mutedUuids().isEmpty());
		assertNull(config.stored(CitizenOverrides.MUTED_KEY));
	}

	// --- helpers ------------------------------------------------------------

	/**
	 * A minimap panel whose rectangle contains {@link #MOUSE}.
	 *
	 * <p>A method rather than a constant: {@link FakeWidget#hidden()} mutates, and one
	 * shared instance would let a test that hid it hide it for every other test in the
	 * class.
	 */
	private static FakeWidget minimapPanelUnderTheMouse()
	{
		return FakeWidget.at(MOUSE.getX() - 100, MOUSE.getY() - 100, 250, 200);
	}

	/**
	 * A citizen on screen, a menu the client would have built for a right-click that
	 * carries "Walk here", and a {@link TestMenu} wired to the given client.
	 *
	 * <p>Everything except the interface layout is held constant across the minimap
	 * tests, so the only thing any of them varies is what is under the cursor.
	 */
	private TestMenu menuUnderTheMinimapFixture(
		FakeClient other, java.util.function.Consumer<FakeMenu> seed)
	{
		other.setLocalPlayer(new FakePlayer(PLAYER));
		other.setTopLevelWorldView(view);
		other.setMouseCanvasPosition(MOUSE);
		seed.accept(other.menu());

		regions.file(VARROCK_NORTH, regions.talker(VARROCK_NORTH, 3220, 3421, "Busy today."));
		EntityScene otherScene = new EntityScene(other, regions, config, config.overrides());
		otherScene.syncRegions(view);
		otherScene.updateVisibility(PLAYER, view);
		assertTrue("the citizen has to be on screen, or the layout is not what stopped this",
			otherScene.countActive() > 0);

		return new TestMenu(other, otherScene);
	}

	private void assertNothingIsOfferedUnderTheMinimap(FakeClient other)
	{
		TestMenu otherMenu = menuUnderTheMinimapFixture(other, FakeMenu::seedMinimapClick);

		otherMenu.onMenuOpened(other.menuOpened());

		assertEquals("a right-click on the minimap panel must not cost a projection",
			0, otherMenu.clickboxCalls);
		assertTrue("and must add nothing", other.menu().created().isEmpty());
		assertNull("nor leave a target behind for a later click", otherMenu.getTarget());
	}

	private void assertTheCitizenIsStillOffered(FakeClient other)
	{
		TestMenu otherMenu = menuUnderTheMinimapFixture(other, FakeMenu::seedMinimapClick);

		otherMenu.onMenuOpened(other.menuOpened());

		assertEquals("the minimap guard must not fire here", 3, other.menu().created().size());
		assertNotNull(otherMenu.getTarget());
	}

	private void spawn(EntityDefinition... entities)
	{
		regions.file(VARROCK_NORTH, entities);
		scene.syncRegions(view);

		// Passes, plural: RenderPolicy.MAX_MODEL_BUILDS_PER_PASS means a fixture of nine
		// arrives over three game ticks. Nothing here is about when they arrive, only
		// about what the menu does once they have.
		VisibilityPasses.settle(scene, PLAYER, view);
		assertTrue("the fixture has to actually spawn", scene.countActive() > 0);
	}

	/**
	 * The click event the client would post for one of our entries: our type, our
	 * option, our target, and the identifier the open menu stamped.
	 */
	private MenuOptionClicked click(String option, EntityDefinition definition)
	{
		return new MenuOptionClicked(new FakeMenuEntry()
			.setOption(option)
			.setTarget(CitizenLabel.menuTarget(definition))
			.setType(MenuAction.RUNELITE)
			.setIdentifier(currentToken()));
	}

	/**
	 * The identifier the open menu stamped on its entries.
	 *
	 * <p>Read back off the entries the plugin created rather than tracked here: the
	 * token is the plugin's, and a test that kept its own copy would pass even if
	 * the plugin stopped stamping one.
	 */
	private int currentToken()
	{
		List<MenuEntry> created = client.menu().created();
		assertFalse("there has to be an open menu to click on", created.isEmpty());
		return created.get(created.size() - 1).getIdentifier();
	}

	/**
	 * {@link CitizenMenu} with the camera taken out.
	 *
	 * <p>{@link #hit} decides whether the fake clickbox contains the mouse, and
	 * {@link #clickboxCalls} counts how many were computed — which is the assertion
	 * for both halves of issue #14 that are not about the entry's own fields.
	 */
	private final class TestMenu extends CitizenMenu
	{
		private int clickboxCalls;
		private boolean hit = true;

		private TestMenu()
		{
			this(client, scene);
		}

		private TestMenu(FakeClient client, EntityScene scene)
		{
			super(client, scene, config.overrides());
		}

		@Override
		@Nullable
		Shape clickbox(LivelyEntity entity, WorldView worldView)
		{
			clickboxCalls++;
			assertNotNull("a clickbox must never be computed for an unplaced entity",
				entity.getRenderLocation());

			// A box around the mouse, or one nowhere near it — so "the mouse is
			// inside" is a real branch rather than always true.
			return hit
				? new Rectangle(MOUSE.getX() - 10, MOUSE.getY() - 10, 20, 20)
				: new Rectangle(-500, -500, 20, 20);
		}
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * One citizen's remarks: the four ways of having nothing to say, the dwell, and
 * the seeded randomness.
 *
 * <p>{@link CitizenChatter} is the class that decides <i>who</i> talks; this is
 * the state it drives. They are tested apart because the interesting failures are
 * different: here it is "silence is silence however it was spelled in the JSON",
 * there it is the cadence and the cap.
 */
public class CitizenRemarksTest
{
	private final FakeRegions regions = new FakeRegions();

	/**
	 * All four spellings of silence, side by side.
	 *
	 * <p>All four are in the shipped data — 54 citizens carry remarks, 183 carry
	 * {@code "remarks": []}, 32 carry no field at all, and all 42 scenery records
	 * omit it — so this is a fixture matching reality rather than an invented edge
	 * case. Flattening them at the validation gate is what lets every later reader
	 * ask one question. {@link #theShippedRemarksPartitionAddsUpToTheRoster()} is
	 * what keeps those four numbers honest.
	 */
	@Test
	public void everyKindOfSilenceProducesNoRemarksAtAll()
	{
		assertNull("a citizen with no remarks field",
			CitizenRemarks.forDefinition(regions.citizen(12853, 3220, 3420, 0)));
		assertNull("a citizen with an empty remarks array",
			CitizenRemarks.forDefinition(regions.talker(12853, 3220, 3421)));
		assertNull("a citizen whose only remark is blank",
			CitizenRemarks.forDefinition(regions.talker(12853, 3220, 3422, "   ")));
		assertNull("scenery, which must never talk however the record is authored",
			CitizenRemarks.forDefinition(regions.scenery(12853, 3220, 3423, "I am a crate.")));

		assertNotNull("and a citizen with something to say does get one",
			CitizenRemarks.forDefinition(regions.talker(12853, 3220, 3424, "Busy today.")));
	}

	@Test
	public void blankRemarksAreDroppedAndTheRestKept()
	{
		EntityDefinition mixed = regions.talker(12853, 3220, 3420, "First.", "  ", null, "Second.");

		assertEquals(2, mixed.getRemarks().length);
		assertEquals("First.", mixed.getRemarks()[0]);
		assertEquals("Second.", mixed.getRemarks()[1]);
	}

	@Test
	public void aRemarkStaysUpForItsDwellAndThenGoesAway()
	{
		CitizenRemarks remarks = remarksFor("Busy today.");

		assertFalse("silent to start with", remarks.isTalking());

		remarks.say(100, 20);
		assertTrue(remarks.isTalking());
		assertEquals("Busy today.", remarks.text());

		assertFalse("one tick before the dwell is up, it is still there", remarks.expire(119));
		assertTrue(remarks.isTalking());

		assertTrue("and on the tick the dwell expires, it goes", remarks.expire(120));
		assertFalse(remarks.isTalking());
		assertNull(remarks.text());

		assertFalse("expiring nothing is not an event", remarks.expire(200));
	}

	@Test
	public void clearingStopsARemarkMidDwell()
	{
		CitizenRemarks remarks = remarksFor("Busy today.");
		remarks.say(100, 500);
		assertTrue(remarks.isTalking());

		remarks.clear();
		assertFalse("this is the path despawn() and the hard off switch take",
			remarks.isTalking());
	}

	/**
	 * The same citizen says the same things in the same order every session.
	 *
	 * <p>Seeded from the entity's identity, not the clock — the same rule
	 * {@link CitizenWalk} follows, and for the same reason: a street should read as
	 * a place rather than as a random generator, and a test cannot assert anything
	 * about a thousand ticks otherwise.
	 */
	@Test
	public void theRemarkOrderIsTheSameEverySession()
	{
		EntityDefinition definition = regions.talker(12853, 3220, 3420, "A", "B", "C", "D");

		StringBuilder first = new StringBuilder();
		StringBuilder second = new StringBuilder();
		transcribe(definition, first);
		transcribe(definition, second);

		assertEquals("two sessions, same citizen, same lines", first.toString(), second.toString());
		assertTrue("and it does use more than one of them: " + first,
			first.toString().chars().distinct().count() > 1);
	}

	/**
	 * Two citizens do not share a sequence, and neither shares the walk's.
	 *
	 * <p>The second half is why the seed is salted: {@link CitizenWalk} already
	 * seeds a {@link java.util.Random} from the bare {@code stableHash()}, so
	 * without the salt a citizen's remark rolls would line up with its destination
	 * rolls forever — a correlation nobody asked for and nobody could debug.
	 */
	@Test
	public void differentCitizensRollDifferently()
	{
		Set<String> transcripts = new HashSet<>();
		for (int i = 0; i < 8; i++)
		{
			StringBuilder out = new StringBuilder();
			transcribe(regions.talker(12853, 3220 + i, 3420, "A", "B", "C", "D"), out);
			transcripts.add(out.toString());
		}

		assertTrue("eight citizens should not all say the same sequence, got " + transcripts,
			transcripts.size() > 1);
	}

	/**
	 * The rolls are staggered per citizen, so a crowd does not produce a chorus
	 * every interval and then silence.
	 */
	@Test
	public void theDueTickIsStaggeredAcrossCitizens()
	{
		Set<Integer> dueTicks = new HashSet<>();
		for (int i = 0; i < 30; i++)
		{
			CitizenRemarks remarks = remarksFor(regions.talker(12853, 3220 + i, 3420, "A"));
			for (int tick = 1; tick <= 60; tick++)
			{
				if (remarks.dueAt(tick, 60))
				{
					dueTicks.add(tick);
					break;
				}
			}
		}

		assertTrue("thirty citizens on a 60-tick interval should not all be due on the same tick, got "
			+ dueTicks, dueTicks.size() > 1);
	}

	/**
	 * Whatever the interval, a citizen is due exactly once per interval — never
	 * never, and never twice.
	 */
	@Test
	public void aCitizenIsDueExactlyOncePerInterval()
	{
		CitizenRemarks remarks = remarksFor("Busy today.");

		for (int interval : new int[]{1, 7, 60, 120, 600})
		{
			int due = 0;
			for (int tick = 1; tick <= interval * 4; tick++)
			{
				if (remarks.dueAt(tick, interval))
				{
					due++;
				}
			}
			assertEquals("interval " + interval, 4, due);
		}
	}

	private CitizenRemarks remarksFor(String... remarks)
	{
		return remarksFor(regions.talker(12853, 3220, 3420, remarks));
	}

	/**
	 * The four-way split above, recomputed from the shipped files — and made to add
	 * up.
	 *
	 * <p><b>Why a test and not a javadoc sentence.</b> The split was written down in
	 * two places and drifted in both, and the drift was invisible because nothing
	 * added the parts together: one version of it claimed 39 + 54 + 24 remark
	 * spellings across the 109-citizen roster of the day, which is 117 citizens and
	 * therefore could not have been true of any dataset. (The roster is 142 now. The
	 * example is left in the numbers it happened in, because what it demonstrates is a
	 * split that does not sum, and rescaling it to today's roster would turn a real
	 * defect into an invented one.) A partition is the cheapest kind of
	 * claim to guard — the parts have to be the whole — so this asserts both the
	 * parts and the sum, and the totals it checks them against are counted rather
	 * than typed.
	 *
	 * <p>Read through {@link ShippedCitizens} rather than {@link EntityDefinition},
	 * because the four spellings are exactly what the validation gate flattens: ask
	 * a definition and all four look identical.
	 */
	@Test
	public void theShippedRemarksPartitionAddsUpToTheRoster()
	{
		int carryRemarks = 0;
		int carryAnEmptyArray = 0;
		int carryNoField = 0;

		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (citizen.authoredRemarks == null)
			{
				carryNoField++;
			}
			else if (citizen.authoredRemarks == 0)
			{
				carryAnEmptyArray++;
			}
			else
			{
				carryRemarks++;
			}
		}

		int citizens = 0;
		int scenery = 0;
		int sceneryWithARemarksField = 0;
		int silent = 0;
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> entities = new ArrayList<>();
		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			entities.addAll(region.getEntities());
		}

		for (EntityDefinition entity : entities)
		{
			if (entity.getType().isCitizen())
			{
				citizens++;
			}
			else
			{
				scenery++;
			}

			if (CitizenRemarks.forDefinition(entity) == null)
			{
				silent++;
			}
		}

		for (int regionId : ShippedRegions.ids())
		{
			sceneryWithARemarksField += sceneryRecordsCarryingRemarks(regionId);
		}

		assertEquals("citizens carrying at least one remark", 54, carryRemarks);
		assertEquals("citizens carrying \"remarks\": []", 183, carryAnEmptyArray);
		assertEquals("citizens carrying no remarks field at all", 32, carryNoField);
		assertEquals("scenery records, none of which carry the field", 42, scenery);
		assertEquals("and none of them carry it", 0, sceneryWithARemarksField);

		assertEquals("the three citizen spellings have to be the whole roster and nothing "
				+ "more — a split that does not add up is the failure this test exists for",
			citizens, carryRemarks + carryAnEmptyArray + carryNoField);
		assertEquals("and the roster is the shipped one", 269, citizens);

		assertEquals("every spelling of silence ends up as one empty array, which is what "
				+ "EntityDefinition.NO_REMARKS is shared across",
			carryAnEmptyArray + carryNoField + scenery, silent);
		assertEquals("and that shared array covers this many of the shipped entities — the "
				+ "figure EntityDefinition.NO_REMARKS and LivelyEntity.remarks both quote",
			257, silent);
		assertEquals("311 shipped entities, and the ones with nothing to say",
			311, silent + carryRemarks);
	}

	/**
	 * @return how many {@code sceneryRoster} records in one region file carry a
	 * {@code remarks} field — the fourth spelling of silence, which
	 * {@link ShippedCitizens} does not cover because it reads the citizen roster
	 */
	private static int sceneryRecordsCarryingRemarks(int regionId)
	{
		String resource = RegionDataLoader.DEFAULT_RESOURCE_PREFIX + regionId + ".json";
		InputStream in = CitizenRemarksTest.class.getClassLoader().getResourceAsStream(resource);
		assertNotNull("missing " + resource, in);

		JsonObject root;
		try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			root = TestGson.injected().fromJson(reader, JsonObject.class);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("could not read " + resource, e);
		}

		JsonElement roster = root.get("sceneryRoster");
		if (roster == null || !roster.isJsonArray())
		{
			return 0;
		}

		int carrying = 0;
		for (JsonElement element : roster.getAsJsonArray())
		{
			if (element.isJsonObject() && element.getAsJsonObject().has("remarks"))
			{
				carrying++;
			}
		}
		return carrying;
	}

	private CitizenRemarks remarksFor(EntityDefinition definition)
	{
		CitizenRemarks remarks = CitizenRemarks.forDefinition(definition);
		assertNotNull("the fixture has to have something to say", remarks);
		return remarks;
	}

	/**
	 * Drives a fresh holder for the same definition through twenty remarks and
	 * writes down what it said. A fresh holder each time is the point: it is what a
	 * new session is.
	 */
	private void transcribe(EntityDefinition definition, StringBuilder out)
	{
		CitizenRemarks remarks = remarksFor(definition);
		int tick = 0;
		while (out.length() < 20)
		{
			tick += 10;
			if (!remarks.rolls(100))
			{
				continue;
			}
			remarks.say(tick, 1);
			out.append(remarks.text());
			remarks.expire(tick + 1);
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The walk itself, driven without a client.
 *
 * <p>{@link EntitySceneTest} exercises the same code through the scene; this file
 * asserts on one citizen so a failure names the rule that broke.
 *
 * <p>The fixture's {@code baseOrientation} is deliberately 500 — a real value
 * from region 12338 and not a multiple of 256, so it can never be confused with
 * any of the eight travel orientations. A fixture using 0 could not tell "went
 * back to the orientation it was authored with" from "never set one".
 */
public class CitizenWalkTest
{
	private static final int REGION = 12852;
	private static final int BASE_ORIENTATION = 500;

	/** Roughly a minute and a half of game ticks. */
	private static final int MANY_TICKS = 2500;

	private FakeRegions regions;

	@Before
	public void setUp()
	{
		regions = new FakeRegions();
	}

	private CitizenWalk walk(int baseX, int baseY, int blX, int blY, int trX, int trY)
	{
		EntityDefinition definition = regions.wanderer(
			REGION,
			new WorldPoint(baseX, baseY, 0),
			new WorldPoint(blX, blY, 0),
			new WorldPoint(trX, trY, 0),
			BASE_ORIENTATION);
		CitizenWalk walk = CitizenWalk.forDefinition(definition);
		assertNotNull(walk);
		return walk;
	}

	@Test
	public void aWandererNeverLeavesItsBoxHoweverLongItWalks()
	{
		CitizenWalk walk = walk(3225, 3355, 3220, 3350, 3230, 3360);
		EntityDefinition.WanderBox box = walk.getBox();

		Set<WorldPoint> visited = new HashSet<>();
		for (int tick = 0; tick < MANY_TICKS; tick++)
		{
			walk.tick();
			WorldPoint tile = walk.currentTile();
			assertTrue("stepped outside " + box + " onto " + tile,
				box.contains(tile.getX(), tile.getY()));
			visited.add(tile);
		}

		// Otherwise a tick() that did nothing at all would pass the assertion
		// above with room to spare.
		assertTrue("the citizen has to actually walk: only visited " + visited.size() + " tile(s)",
			visited.size() > 10);
		assertTrue("and it should get most of the way round an 11x11 box",
			visited.size() >= 40);
	}

	@Test
	public void aBoxOnTheEdgeOfItsRegionIsStillNeverLeft()
	{
		// The shipped shape: a box straddling the 12852/12853 border, with the
		// citizen starting on the northern side of it.
		CitizenWalk walk = walk(3261, 3392, 3258, 3382, 3261, 3395);
		EntityDefinition.WanderBox box = walk.getBox();

		Set<Integer> regionsVisited = new HashSet<>();
		for (int tick = 0; tick < MANY_TICKS; tick++)
		{
			walk.tick();
			WorldPoint tile = walk.currentTile();
			assertTrue("stepped outside " + box + " onto " + tile,
				box.contains(tile.getX(), tile.getY()));
			regionsVisited.add(RenderPolicy.regionIdOf(tile.getX(), tile.getY()));
		}

		assertEquals("the fixture has to straddle the border to prove anything",
			2, regionsVisited.size());
		assertTrue(regionsVisited.contains(12852));
		assertTrue(regionsVisited.contains(12853));
	}

	/**
	 * A tile per game tick, which is the speed the game walks at. Faster and the
	 * citizens skate; slower and they never get anywhere within an idle interval.
	 */
	@Test
	public void aStepIsNeverMoreThanOneTile()
	{
		CitizenWalk walk = walk(3225, 3355, 3218, 3348, 3232, 3362);

		int steps = 0;
		for (int tick = 0; tick < MANY_TICKS; tick++)
		{
			WorldPoint before = walk.currentTile();
			walk.tick();
			WorldPoint after = walk.currentTile();

			int moved = RenderPolicy.tileDistance(before, after);
			assertTrue("moved " + moved + " tiles in one game tick", moved <= 1);
			assertEquals("the step the frame pass interpolates must start where the citizen was",
				before, walk.stepStartTile());

			if (moved == 1)
			{
				steps++;
				assertTrue("a tick that moved must report itself as moving", walk.isMoving());
			}
			else
			{
				assertFalse("a tick that did not move must not report itself as moving",
					walk.isMoving());
			}
		}

		assertTrue("the citizen has to take some steps", steps > 100);
		assertTrue("but it must also stand still sometimes", steps < MANY_TICKS);
	}

	/**
	 * The cadence: a citizen that has arrived waits an interval before looking for
	 * somewhere new. Its first destination is the tile it is already on, so the
	 * wait is observable from the very first tick.
	 */
	@Test
	public void aNewDestinationIsOnlyLookedForOnceAnIntervalHasPassed()
	{
		CitizenWalk walk = walk(3225, 3355, 3220, 3350, 3230, 3360);
		WorldPoint start = walk.currentTile();

		for (int tick = 1; tick < CitizenWalk.IDLE_TICKS_BEFORE_NEW_DESTINATION; tick++)
		{
			walk.tick();
			assertEquals("tick " + tick + " of the idle interval must not move the citizen",
				start, walk.currentTile());
			assertFalse(walk.isMoving());
			assertEquals("nor turn it", BASE_ORIENTATION, walk.getOrientation());
		}

		// From here it is allowed to move. Give it a couple of intervals, because
		// it can legitimately roll the tile it is already standing on.
		boolean moved = false;
		for (int tick = 0; tick < CitizenWalk.IDLE_TICKS_BEFORE_NEW_DESTINATION * 4 && !moved; tick++)
		{
			walk.tick();
			moved = !walk.currentTile().equals(start);
		}
		assertTrue("the citizen must eventually go somewhere", moved);
	}

	/**
	 * Orientation while moving is the direction of travel, and it goes back to the
	 * authored value when the citizen stops. The expected value is recomputed from
	 * the step rather than compared against a table, so this checks the mapping
	 * and not a copy of it.
	 */
	@Test
	public void orientationTracksTheDirectionOfTravelAndResetsWhenIdle()
	{
		CitizenWalk walk = walk(3225, 3355, 3218, 3348, 3232, 3362);

		Set<Integer> facings = new HashSet<>();
		int idleTicks = 0;

		for (int tick = 0; tick < MANY_TICKS; tick++)
		{
			WorldPoint before = walk.currentTile();
			walk.tick();
			WorldPoint after = walk.currentTile();

			if (!walk.isMoving())
			{
				idleTicks++;
				assertEquals("an idle citizen faces the way it was authored facing",
					BASE_ORIENTATION, walk.getOrientation());
				continue;
			}

			int dx = after.getX() - before.getX();
			int dy = after.getY() - before.getY();
			assertEquals("facing for step " + dx + "," + dy,
				expectedOrientation(dx, dy), walk.getOrientation());
			facings.add(walk.getOrientation());
		}

		assertTrue("the citizen has to stand still at some point", idleTicks > 0);
		assertTrue("and it has to walk in more than one direction: saw " + facings,
			facings.size() >= 4);
		assertFalse("the base orientation is not a travel orientation, so it must never "
			+ "show up while moving", facings.contains(BASE_ORIENTATION));
	}

	/**
	 * The client's convention, spelled out independently of the implementation:
	 * 0 is south and the angle rises as the facing turns clockwise, which is the
	 * 0/1/2/3 to south/west/north/east that {@code Angle.getNearestDirection()} ends
	 * in.
	 *
	 * <p>This javadoc used to quote that method as {@code (angle >> 9) & 3}, which is
	 * the bucketing with the rounding term dropped — see
	 * {@code CitizenWalk.STEP_ORIENTATION} for the disassembly and for the four
	 * diagonals the two forms disagree on. The quotation is not what this helper rests
	 * on: it derives all eight answers from {@code atan2} and the test below pins them
	 * against the literal values, so the table is checked against the geometry and never
	 * against a sentence.
	 */
	private static int expectedOrientation(int dx, int dy)
	{
		// atan2 measured from south, clockwise, over 2048 units of turn.
		double radians = Math.atan2(-dx, -dy);
		int jau = (int) Math.round(radians * 2048.0 / (2.0 * Math.PI));
		return ((jau % 2048) + 2048) % 2048;
	}

	@Test
	public void theCardinalOrientationsMatchTheClientsOwnBuckets()
	{
		// Cross-check of the helper above against the client's decoder, so the
		// test's own expectation is not the thing being trusted.
		assertEquals(0, expectedOrientation(0, -1));       // south
		assertEquals(512, expectedOrientation(-1, 0));     // west
		assertEquals(1024, expectedOrientation(0, 1));     // north
		assertEquals(1536, expectedOrientation(1, 0));     // east
		assertEquals(256, expectedOrientation(-1, -1));    // south-west
		assertEquals(768, expectedOrientation(-1, 1));     // north-west
		assertEquals(1280, expectedOrientation(1, 1));     // north-east
		assertEquals(1792, expectedOrientation(1, -1));    // south-east
	}

	/**
	 * The same citizen walks the same route every session. That is what makes a
	 * thinned or repopulated street look like the same street, and it is why the
	 * walk is seeded from the entity's identity rather than the clock.
	 */
	@Test
	public void theSameCitizenAlwaysWalksTheSameRoute()
	{
		EntityDefinition definition = regions.wanderer(
			REGION,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3220, 3350, 0),
			new WorldPoint(3230, 3360, 0),
			BASE_ORIENTATION);

		CitizenWalk first = CitizenWalk.forDefinition(definition);
		CitizenWalk second = CitizenWalk.forDefinition(definition);
		assertNotNull(first);
		assertNotNull(second);

		StringBuilder firstRoute = new StringBuilder();
		StringBuilder secondRoute = new StringBuilder();
		for (int tick = 0; tick < 500; tick++)
		{
			first.tick();
			second.tick();
			firstRoute.append(first.currentTile()).append(';');
			secondRoute.append(second.currentTile()).append(';');
		}

		assertEquals("two walks of the same citizen must be identical",
			firstRoute.toString(), secondRoute.toString());

		// And a different citizen in the same box must not shadow it, or a whole
		// street would move in lockstep.
		EntityDefinition other = regions.wanderer(
			REGION,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3220, 3350, 0),
			new WorldPoint(3230, 3360, 0),
			BASE_ORIENTATION);
		CitizenWalk third = CitizenWalk.forDefinition(other);
		assertNotNull(third);

		StringBuilder thirdRoute = new StringBuilder();
		for (int tick = 0; tick < 500; tick++)
		{
			third.tick();
			thirdRoute.append(third.currentTile()).append(';');
		}
		assertFalse("two citizens in the same box must not walk in lockstep",
			firstRoute.toString().equals(thirdRoute.toString()));
	}

	/**
	 * The interpolation itself: at the start of a tick the citizen is drawn on the
	 * tile it left, at the end on the tile it walked to, and half way through it is
	 * half way between them.
	 */
	@Test
	public void theDrawnPositionSlidesBetweenTheTwoTilesAcrossOneTick()
	{
		CitizenWalk walk = walk(3225, 3355, 3220, 3350, 3230, 3360);
		FakeWorldView view = FakeWorldView.around(new WorldPoint(3225, 3355, 0), REGION);

		// Walk until a step is actually in progress.
		for (int tick = 0; tick < 200 && !walk.isMoving(); tick++)
		{
			walk.tick();
		}
		assertTrue(walk.isMoving());

		LocalPoint from = LocalPoint.fromWorld(view, walk.stepStartTile());
		LocalPoint to = LocalPoint.fromWorld(view, walk.currentTile());
		assertNotNull(from);
		assertNotNull(to);

		LocalPoint atStart = walk.localPoint(view, 0f);
		LocalPoint atEnd = walk.localPoint(view, 1f);
		LocalPoint halfway = walk.localPoint(view, 0.5f);
		assertNotNull(atStart);
		assertNotNull(atEnd);
		assertNotNull(halfway);

		assertEquals("at fraction 0 it is still on the tile it left", from.getX(), atStart.getX());
		assertEquals(from.getY(), atStart.getY());
		assertEquals("at fraction 1 it has arrived", to.getX(), atEnd.getX());
		assertEquals(to.getY(), atEnd.getY());
		assertEquals("half way through the tick it is half way across the tile",
			(from.getX() + to.getX()) / 2, halfway.getX());
		assertEquals((from.getY() + to.getY()) / 2, halfway.getY());

		// Out-of-range fractions are clamped, not extrapolated: a late game tick
		// must not send the citizen sliding past the tile it was walking to.
		assertEquals(to.getX(), walk.localPoint(view, 4f).getX());
		assertEquals(from.getX(), walk.localPoint(view, -2f).getX());
	}

	@Test
	public void anIdleCitizenIsDrawnOnItsTileWhateverTheFraction()
	{
		CitizenWalk walk = walk(3225, 3355, 3220, 3350, 3230, 3360);
		FakeWorldView view = FakeWorldView.around(new WorldPoint(3225, 3355, 0), REGION);

		assertFalse("it starts idle", walk.isMoving());
		LocalPoint tile = LocalPoint.fromWorld(view, walk.currentTile());
		assertNotNull(tile);

		for (float fraction = 0f; fraction <= 1f; fraction += 0.25f)
		{
			LocalPoint drawn = walk.localPoint(view, fraction);
			assertNotNull(drawn);
			assertEquals(tile.getX(), drawn.getX());
			assertEquals(tile.getY(), drawn.getY());
		}
	}

	@Test
	public void aTileOutsideTheLoadedSceneHasNoDrawnPosition()
	{
		// 200 tiles north of the view's centre: inside the region, outside the
		// 104-tile scene.
		CitizenWalk walk = walk(3225, 3560, 3220, 3555, 3230, 3565);
		FakeWorldView view = FakeWorldView.around(new WorldPoint(3225, 3355, 0), REGION);

		assertEquals("nothing to draw, and nothing to fall over on",
			null, walk.localPoint(view, 0.5f));
	}

	/**
	 * Everything that does not wander gets no walk at all, so the per-frame pass
	 * never sees it. Scripted citizens are in that list on purpose — running their
	 * scripts is a later phase, and a scripted citizen wandering at random would
	 * be worse than one standing still.
	 */
	@Test
	public void onlyWanderingCitizensGetAWalk()
	{
		assertEquals(null, CitizenWalk.forDefinition(
			regions.citizen(REGION, 3225, 3355, 0)));

		EntityDefinition wanderer = regions.wanderer(
			REGION,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3220, 3350, 0),
			new WorldPoint(3230, 3360, 0),
			BASE_ORIENTATION);
		assertNotNull(CitizenWalk.forDefinition(wanderer));
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Checks {@code docs/CITY-LIVERY-CHECK.md} against the 127 records it describes.
 *
 * <p><b>Why a document needs a test.</b> This file is the only artefact of the
 * 2026-09-01 livery pass a human can act on: none of its 127 tiles has been stood
 * on, and the walk is the thing that will settle them. A checklist whose tile is
 * one square off the record's is worse than no checklist, because somebody walks
 * to the wrong square, sees nothing wrong, and ticks the box. The same argument
 * {@code CityTopUpCheckTest} makes about the 33, and this is deliberately its
 * sibling rather than an extension of it — the two passes have different rules,
 * different markers and different documents, and a single test over both would
 * have to be written in whichever way was weaker.
 *
 * <p>{@code docs/CITY-LIVERY-CHECK.md} is declared an input of the {@code test}
 * task in {@code build.gradle}. Without that declaration Gradle would consider the
 * task up to date after a documentation-only edit and this class would never run.
 */
public class CityLiveryCheckTest
{
	private static final String DOC = "docs/CITY-LIVERY-CHECK.md";

	/** The disclosure that publishes the same colours in prose; {@code AuthoredRecordsTest} owns it. */
	private static final String NOTICE = "NOTICE";

	/** The uuid prefix the livery pass's records carry; {@link AuthoredRecordsTest} owns it. */
	private static final String MARKER = "add2";

	private static final int FIGURES = 127;
	private static final int NEW_BOXES = 12;

	/** Ground Markers' own colour strings, as the block spells them. */
	private static final String YELLOW = "#FFFFFF00";
	private static final String CYAN = "#FF00FFFF";

	private static final Pattern ENTRY = Pattern.compile(
		"^- \\[ \\] \\*\\*(.+?)\\*\\* — (.*?)(?=^- \\[ \\]|^#|^---)",
		Pattern.MULTILINE | Pattern.DOTALL);

	private static final Pattern TILE = Pattern.compile("^`(\\d+), (\\d+), (\\d+)`");
	private static final Pattern FACING = Pattern.compile("facing (north|south|east|west)");
	private static final Pattern BOX = Pattern.compile(
		"\\*\\*wanders\\*\\* `(\\d+),(\\d+) \\.\\. (\\d+),(\\d+)`");
	private static final Pattern EXAMINE = Pattern.compile("Examine: \"(.*?)\"", Pattern.DOTALL);
	private static final Pattern KIT = Pattern.compile("Kit: \"(.+?)\" \\((\\d+)\\) · `(\\w+)`");
	private static final Pattern MARKERS = Pattern.compile(
		"```json\\n(\\[.*?\\])\\n```", Pattern.DOTALL);

	/**
	 * The livery line, in both of the forms the document writes it.
	 *
	 * <p>Group 1 is the city and 2 the cut for a liveried figure; both are absent for an
	 * Edgeville figure, whose line says {@code none} instead. Groups 3 and 4 are the
	 * torso and legs words, group 5 the boots word where there is one.
	 */
	private static final Pattern LIVERY = Pattern.compile(
		"Livery: (?:(\\w[\\w ]*?) cut (\\d) — torso `(\\d+)`, legs `(\\d+)`"
			+ "|none — donor's own colours, darkened)(?:; |, )?(?:boots `(\\d+)`)?");

	private static final Pattern PLACED_NEAR = Pattern.compile(
		"Placed near: ([^,\\n(]+?)( \\(unwalked\\))?, (\\d+) tiles?");

	/** Group 1 is the row number, 2 the figure, 3 its city, 4 the distance, 5 the anchor. */
	private static final Pattern REACH_ROW = Pattern.compile(
		"^\\| (\\d+) \\| \\*\\*(\\w+)\\*\\* \\| ([\\w' ]+?) \\| (\\d+) \\| ([\\w' ]+) \\|$",
		Pattern.MULTILINE);

	/**
	 * A row of the document's own livery table: city, torso, legs, trim.
	 *
	 * <p>This is the palette section of the document — the eight measured colours per
	 * city, written once at the top — and it is deliberately <b>not</b> the per-record
	 * {@code Livery:} lines. See
	 * {@link #theLiveryIsOneSetPerCityAndNoTwoCitiesShareOne} for why the difference is
	 * the whole point.
	 */
	private static final Pattern PALETTE_ROW = Pattern.compile(
		"^\\| ([\\w' ]+?) \\| `(\\d+)` [\\w/]+ \\| `(\\d+)` [\\w/]+ \\| `(\\d+)` [\\w/]+ ?†? \\|$",
		Pattern.MULTILINE);

	/**
	 * A {@code Rows N to M …} sentence from the prose above the reach table, to the end
	 * of its paragraph. Group 1 and 2 are the row numbers, 3 the rest of the paragraph.
	 */
	private static final Pattern ROWS_CLAIM = Pattern.compile(
		"^Rows (\\d+) to (\\d+)\\b(.*?)(?=\\n\\n)", Pattern.MULTILINE | Pattern.DOTALL);

	/** A bold run in that prose, which may hold several comma-separated names. */
	private static final Pattern BOLD_NAMES = Pattern.compile("\\*\\*([\\w'][\\w' ,]*?)\\*\\*");

	/** The number words those sentences count in. */
	private static final TreeMap<String, Integer> NUMBERS = numbers();

	/** The dataset's orientation units, as the document spells them in words. */
	private static final TreeMap<String, Integer> ORIENTATIONS = orientations();

	/** The kit bases this pass repaints. {@link BodySlots} owns the measurement. */
	private static final int TORSO_BASE = BodySlots.TORSO_BASE;
	private static final int LEGS_BASE = BodySlots.LEGS_BASE;
	private static final int BOOT_BASE = BodySlots.BOOT_BASE;

	/**
	 * The one colour the document's livery table publishes that no record wears.
	 *
	 * <p>Varrock's eight figures use three cuts, and a city's trim only ever lands on the
	 * fourth, so {@code 10050} is measured, published and unworn. The document carries a
	 * footnote saying so; this constant is the other half of that sentence, and
	 * {@link #everyPublishedLiveryColourIsWornExceptTheOneNamedHere} is what stops the
	 * list of exceptions growing without anybody deciding to grow it.
	 */
	private static final int VARROCKS_UNWORN_TRIM = 10050;

	/** How far from a proven tile earns a row in the document's reach table. */
	private static final int PROVEN_REACH_THRESHOLD = 9;

	@Test
	public void theChecklistNamesEveryLiveriedFigureExactlyOnce() throws IOException
	{
		TreeSet<String> listed = new TreeSet<>();
		for (Entry entry : entries())
		{
			assertTrue("the checklist lists " + entry.name + " twice", listed.add(entry.name));
		}

		assertEquals("the checklist and the liveried records have to be the same set",
			ours().keySet(), listed);
		assertEquals("and there have to be " + FIGURES + " of them", FIGURES, listed.size());
	}

	/**
	 * Every entry's tile, facing and wander box are the record's own.
	 *
	 * <p>The facing is checked as well as the tile because it is the half a walker
	 * cannot verify from the marker: a yellow square says where to stand, and only this
	 * line says which way the figure should be looking when you get there.
	 */
	@Test
	public void everyFigureStandsWhereItsEntrySaysAndFacesTheWayItSays() throws IOException
	{
		TreeMap<String, EntityDefinition> ours = ours();
		int checked = 0;
		int boxes = 0;

		for (Entry entry : entries())
		{
			EntityDefinition record = ours.get(entry.name);
			assertNotNull(entry.name + " is in the checklist and not in the data", record);
			checked++;

			Matcher tile = TILE.matcher(entry.body);
			assertTrue(entry.name + " has no tile in its entry", tile.find());
			WorldPoint at = record.getWorldLocation();
			assertEquals(entry.name + " x", at.getX(), Integer.parseInt(tile.group(1)));
			assertEquals(entry.name + " y", at.getY(), Integer.parseInt(tile.group(2)));
			assertEquals(entry.name + " plane", at.getPlane(), Integer.parseInt(tile.group(3)));

			Matcher facing = FACING.matcher(entry.body);
			assertTrue(entry.name + " does not say which way it faces", facing.find());
			assertEquals(entry.name + " facing",
				(int) ORIENTATIONS.get(facing.group(1)), record.getOrientation());

			Matcher box = BOX.matcher(entry.body);
			EntityDefinition.WanderBox authored = record.getWanderBox();
			if (box.find())
			{
				boxes++;
				assertNotNull(entry.name + " is listed as a wanderer and carries no box",
					authored);
				assertEquals(entry.name + " box minX", authored.getMinX(),
					Integer.parseInt(box.group(1)));
				assertEquals(entry.name + " box minY", authored.getMinY(),
					Integer.parseInt(box.group(2)));
				assertEquals(entry.name + " box maxX", authored.getMaxX(),
					Integer.parseInt(box.group(3)));
				assertEquals(entry.name + " box maxY", authored.getMaxY(),
					Integer.parseInt(box.group(4)));
			}
			else
			{
				assertEquals(entry.name + " carries a wander box the checklist does not "
					+ "mention, so its rectangle would never be walked", null, authored);
			}
		}

		assertEquals("every figure has to have been checked", FIGURES, checked);
		assertEquals("and the new wander boxes have to be the ones listed", NEW_BOXES, boxes);
	}

	/**
	 * Every entry quotes its record's examine text exactly.
	 *
	 * <p>Not tidiness. The examine line is how a walker knows the figure in front of
	 * them is the one the entry is about — two liveried townsfolk in one city wear the
	 * same colours by design, so the text is the only thing in the entry that tells
