	/**
	 * <b>Falador stays white-first, Lumbridge stays blue-first, and the four records that
	 * are neither are exactly the four.</b>
	 *
	 * <p>{@code NOTICE} item 12 and this document both used to say the split was
	 * "enforced by construction". It is not. Cut 3 promotes a city's trim to the whole
	 * legs slot, so Falador's cut 3 is a white torso over royal-blue legs and Lumbridge's
	 * is a blue torso over white legs — four records, mirror images of each other, 50/50
	 * rather than dominant-plus-accent. The claim was corrected rather than the data,
	 * because cut 3 does the same thing in all eight liveried cities and each of the four
	 * still wears its own city's colour on the torso; but a false safety argument with
	 * nothing checking it is how the data gets to drift underneath it.
	 *
	 * <p>So what is pinned is what is true: <b>the torso rule holds in every cut</b>, the
	 * mirror is these four records and no others, and the two blues stay far enough apart
	 * to be two colours. Three hue rungs of sixty-four is 16.9°, which is what the
	 * documents now say — they said nineteen degrees, and nothing measured it.
	 *
	 * <p><b>Two things were wrong with this method until 2026-08-31.</b> It never opened
	 * either document, so reverting {@code docs/CITY-LIVERY-CHECK.md} to "nineteen degrees
	 * apart" left the suite green — a test named for a claim in a document that never read
	 * the document. And its four colours were decimal literals, so the three assertions
	 * about them were constant-folded arithmetic: lifted into a standalone class and run
	 * with {@code RegionData/} emptied of all 27 files, they still passed. The constants
	 * are now read out of the document's livery table, which makes them measurements, and
	 * the hue gap is measured the short way round the wheel — a raw subtraction is correct
	 * at h42 against h39 and silently reports 61 for any future pair straddling 63→0.
	 */
	@Test
	public void theFaladorAndLumbridgeBluesStayApartAndTheMirrorIsExactlyFourRecords()
		throws IOException
	{
		TreeMap<String, Palette> published = published();
		final int faladorWhite = published.get(City.FALADOR.getLabel()).torso;
		final int faladorBlue = published.get(City.FALADOR.getLabel()).trim;
		final int lumbridgeBlue = published.get(City.LUMBRIDGE.getLabel()).torso;
		final int lumbridgeWhite = published.get(City.LUMBRIDGE.getLabel()).trim;

		TreeSet<String> mirrored = new TreeSet<>();
		int faladorTorsos = 0;
		int lumbridgeTorsos = 0;

		for (EntityDefinition record : ours().values())
		{
			City city = City.of(record.getCityRegionId());
			int torso = painted(record, TORSO_BASE);
			int legs = painted(record, LEGS_BASE);

			if (city == City.FALADOR)
			{
				faladorTorsos++;
				assertEquals(record.label() + " is a Falador figure whose torso is not "
					+ "white, so Falador has stopped being a white city", 0, hue(torso));
				assertEquals("and its saturation, which is what makes it white rather "
					+ "than merely pale", 0, saturation(torso));
				if (legs == faladorBlue)
				{
					mirrored.add(record.getName());
				}
			}
			else if (city == City.LUMBRIDGE)
			{
				lumbridgeTorsos++;
				assertEquals(record.label() + " is a Lumbridge figure whose torso is not "
					+ "Lumbridge blue", hue(lumbridgeBlue), hue(torso));
				if (legs == lumbridgeWhite)
				{
					mirrored.add(record.getName());
				}
			}
		}

		assertEquals("Falador's liveried figures", 16, faladorTorsos);
		assertEquals("Lumbridge's", 14, lumbridgeTorsos);
		assertEquals("the cut-3 records whose trim is half the outfit",
			new TreeSet<>(Arrays.asList(
				"Berengar", "Editha", "Lisbeth", "Peveril")), mirrored);

		assertEquals("Falador's white is the grey rung", 0, saturation(faladorWhite));
		assertEquals("and Lumbridge's trim is the same rung", 0, saturation(lumbridgeWhite));
		assertEquals("the two blues are three hue rungs of sixty-four apart — 16.9°, and "
				+ "both documents said nineteen degrees until 2026-08-30",
			3, hueGap(faladorBlue, lumbridgeBlue));

		// And the documents have to carry the measured figure. 3/64 of 360° is 16.875,
		// which rounds to 16.9 whichever way round the wheel it is read. Without this
		// the method was named for a claim it never checked: putting "nineteen degrees
		// apart" back into the document left the whole suite green.
		assertTrue("docs/CITY-LIVERY-CHECK.md has to carry the measured separation",
			read().contains("16.9°"));
		assertTrue("and so does NOTICE item 12, which makes the same claim in prose",
			notice().contains("16.9 degrees"));
	}

	/**
	 * <b>Every Edgeville figure is its donor's own colours, darkened.</b>
	 *
	 * <p>Edgeville has no livery, and what stands in for one is a rule: take the donor
	 * kit's colours and push them towards the dark end by a per-figure amount. Nothing
	 * checked that either, and the rule is the only thing that makes "deliberately
	 * unbranded" different from "eighteen arbitrary palettes".
	 *
	 * <p><b>The rule is "no lighter", not "darker", and the difference is two records.</b>
	 * "Bregg" and "Sten" copy donors already sitting at lightness 6, so their legs cannot
	 * go down and do not move; 17 of the 18 torsos are strictly darker than their donor's.
	 * The single exception in the other direction is Sten's boot, four rungs lighter than
	 * its donor's and black either way. All of it is asserted rather than described,
	 * because a reader of the section would otherwise take "each by a different amount"
	 * to mean every slot moved.
	 *
	 * <p>The donor is the record the entry's own {@code Kit:} line names, which
	 * {@link #everyEntryNamesADonorThatShipsAndAPoseTheRecordActuallyPlays} has already
	 * proved ships.
	 */
	@Test
	public void everyEdgevilleFigureIsItsDonorsColoursDarkened() throws IOException
	{
		TreeMap<String, EntityDefinition> ours = ours();
		TreeMap<String, EntityDefinition> donors = donorsByName();

		int figures = 0;
		int strictlyDarkerTorsos = 0;
		TreeSet<String> unmoved = new TreeSet<>();
		TreeSet<String> lighter = new TreeSet<>();

		for (Entry entry : entries())
		{
			EntityDefinition record = ours.get(entry.name);
			if (City.of(record.getCityRegionId()) != City.EDGEVILLE)
			{
				continue;
			}
			figures++;

			Matcher kit = KIT.matcher(entry.body);
			assertTrue(entry.name, kit.find());
			EntityDefinition donor = donors.get(kit.group(1) + "@" + kit.group(2));
			assertNotNull(entry.name + " names a donor that does not ship", donor);

			for (int base : new int[]{TORSO_BASE, LEGS_BASE, BOOT_BASE})
			{
				Integer mine = painted(record, base);
				Integer theirs = painted(donor, base);
				if (mine == null || theirs == null)
				{
					continue;
				}
				if (lightness(mine) > lightness(theirs))
				{
					lighter.add(entry.name + " " + base);
				}
				else if (lightness(mine) == lightness(theirs))
				{
					unmoved.add(entry.name + " " + base);
				}
				else if (base == TORSO_BASE)
				{
					strictlyDarkerTorsos++;
				}
			}
		}

		assertEquals("Edgeville's figures", 18, figures);
		assertEquals("torsos strictly darker than their donor's", 17, strictlyDarkerTorsos);
		assertEquals("slots that could not move because the donor was already at the "
				+ "floor", new TreeSet<>(Arrays.asList(
				"Bregg " + LEGS_BASE, "Bregg " + BOOT_BASE,
				"Sten " + TORSO_BASE, "Sten " + LEGS_BASE)), unmoved);
		assertEquals("the one slot in Edgeville that is lighter than its donor's, four "
				+ "rungs and black either way",
			new TreeSet<>(Collections.singletonList("Sten " + BOOT_BASE)), lighter);
	}

	/**
	 * <b>Every {@code Placed near} line names a record that ships, at the distance it
	 * claims, and says whether that record has been walked.</b>
	 *
	 * <h2>What was wrong with it</h2>
	 *
	 * <p>The document's own summary said each of the 127 "sits within a few tiles of a
	 * figure whose own tile is proven — somebody stood on it in game". <b>55 of the 127
	 * named one of the 33 citizens added on 2026-08-29</b>, which the same document says
	 * are unwalked. An unwalked figure two tiles away is a second guess resting on the
	 * first, and the line read exactly like the other 72.
	 *
	 * <p>Eight of the stated distances were also wrong. Seven overstated harmlessly; one
	 * — "Gorden", stated 6 tiles from "Ilsa", actually 8 — understated, which is the
	 * direction that matters, because the number is the reader's only offline measure of
	 * how much to trust the tile.
	 *
	 * <h2>What it asserts</h2>
	 *
	 * <p>The anchor ships; the distance is the Chebyshev distance to it, which is what
	 * "tiles away" means when you walk it; the {@code (unwalked)} tag is present exactly
	 * when the anchor is one of the 2026-08-29 records; and the two counts are what the
	 * document says they are. Nothing here can be satisfied by editing prose alone.
	 */
	@Test
	public void everyPlacedNearLineNamesARecordThatShipsAtTheDistanceItClaims()
		throws IOException
	{
		TreeMap<String, EntityDefinition> ours = ours();
		TreeMap<String, List<EntityDefinition>> byName = new TreeMap<>();
		for (EntityDefinition entity : shipped())
		{
			if (entity.getName() != null)
			{
				byName.computeIfAbsent(entity.getName(), k -> new ArrayList<>()).add(entity);
			}
		}

		int proven = 0;
		int unwalked = 0;

		for (Entry entry : entries())
		{
			EntityDefinition record = ours.get(entry.name);
			Matcher near = PLACED_NEAR.matcher(entry.body);
			assertTrue(entry.name + " does not say what its tile was reasoned from",
				near.find());

			String anchorName = near.group(1);
			List<EntityDefinition> candidates = byName.get(anchorName);
			assertNotNull(entry.name + " is placed near \"" + anchorName + "\", which is "
				+ "not in the dataset", candidates);

			WorldPoint at = record.getWorldLocation();
			EntityDefinition anchor = null;
			int distance = Integer.MAX_VALUE;
			for (EntityDefinition candidate : candidates)
			{
				WorldPoint there = candidate.getWorldLocation();
				if (there.getPlane() != at.getPlane())
				{
					continue;
				}
				int chebyshev = Math.max(Math.abs(there.getX() - at.getX()),
					Math.abs(there.getY() - at.getY()));
				if (chebyshev < distance)
				{
					distance = chebyshev;
					anchor = candidate;
				}
			}
			assertNotNull(entry.name + "'s anchor is on another plane", anchor);
			assertEquals(entry.name + " says it is " + near.group(3) + " tiles from "
					+ anchorName + " and it is " + distance,
				distance, Integer.parseInt(near.group(3)));

			// An anchor is unwalked if it is one of the 2026-08-29 records — or one of
			// this pass's own, which nothing currently is, but a new entry anchored to
			// a sibling would otherwise score as proven and then be forbidden from
			// carrying the (unwalked) tag it deserves.
			String anchorUuid = anchor.getUuid().toString();
			boolean anchorIsUnwalked =
				anchorUuid.startsWith("add1") || anchorUuid.startsWith(MARKER);
			if (anchorIsUnwalked)
			{
				unwalked++;
				assertNotNull(entry.name + " is anchored to " + anchorName + ", which has "
					+ "never been walked, and the line does not say so", near.group(2));
			}
			else
			{
				proven++;
				assertEquals(entry.name + " marks " + anchorName + " unwalked and it is "
					+ "one of the tiles somebody stood on", null, near.group(2));
			}
		}

		assertEquals("entries anchored to a tile upstream authored", 72, proven);
		assertEquals("entries anchored to a record that has never been walked either",
			55, unwalked);
	}

	/**
	 * <b>The reach table is every figure nine tiles or more from a proven tile, and the
	 * distances in it are measured.</b>
	 *
	 * <p>"Proven" has one meaning here and the table is built from it: the authored tile
	 * of a citizen that came from upstream's dataset, on the same plane. Those are the
	 * only tiles in this repository somebody is known to have stood on — a 2026-08-29 or
	 * 2026-09-01 record is a placement this project guessed, and upstream scenery is an
	 * object rather than a tile anybody walked to.
	 *
	 * <p>The document published <b>seven</b>. Measured this way it is 21, because the
	 * seven were the entries whose <i>anchor</i> was far away rather than the entries far
	 * from anything proven — and 55 of the anchors are themselves unwalked. Fourteen
	 * figures were therefore missing from the list a walker works down, seven of them
	 * (Ferrand at 15, Gorse 13, Gorden 11, Editha 11, Rashid 10, Basma 10, Isabeau 10)
	 * further out than two of the three the document did name.
	 *
	 * <p><b>The table's last column is checked too, and until 2026-08-31 it was not.</b>
	 * {@code REACH_ROW} captured "That tile" and the loop never read the group, so
	 * rewriting {@code | 6 | Gorse | Draynor | 13 | Sailor |} to name "Hans" passed. That
	 * column is the one thing in the row a walker acts on — it says which proven figure to
	 * start from — so it is asserted against the tile the measurement actually won on. It
	 * is asserted as membership of the set of proven figures at that exact distance rather
	 * than as one name, because a tie between two equally near tiles is a real thing that
	 * would otherwise turn on the iteration order of the region files. There are no ties
	 * today: all 21 rows have a single nearest proven figure.
	 */
	@Test
	public void theReachTableIsEveryFigureNineOrMoreTilesFromAProvenTile() throws IOException
	{
		List<EntityDefinition> proven = new ArrayList<>();
		for (EntityDefinition entity : shipped())
		{
			String uuid = entity.getUuid().toString();
			if (entity.getType().isCitizen()
				&& !uuid.startsWith("add1") && !uuid.startsWith(MARKER))
			{
				proven.add(entity);
			}
		}
		assertTrue("there have to be upstream citizens to measure against", proven.size() > 100);

		TreeMap<String, Integer> measured = new TreeMap<>();
		TreeMap<String, TreeSet<String>> nearestNames = new TreeMap<>();
		for (EntityDefinition record : ours().values())
		{
			WorldPoint at = record.getWorldLocation();
			int nearest = Integer.MAX_VALUE;
			for (EntityDefinition tile : proven)
			{
				WorldPoint there = tile.getWorldLocation();
				if (there.getPlane() != at.getPlane())
				{
					continue;
				}
				nearest = Math.min(nearest, Math.max(Math.abs(there.getX() - at.getX()),
					Math.abs(there.getY() - at.getY())));
			}
			if (nearest < PROVEN_REACH_THRESHOLD)
			{
				continue;
			}
			measured.put(record.getName(), nearest);

			// Which proven figures are at that distance — the answer the table's last
			// column has to give, and a set rather than one name so a tie between two
			// equally near tiles does not depend on the order the regions load in.
			TreeSet<String> tied = new TreeSet<>();
			for (EntityDefinition tile : proven)
			{
				WorldPoint there = tile.getWorldLocation();
				if (there.getPlane() == at.getPlane()
					&& Math.max(Math.abs(there.getX() - at.getX()),
						Math.abs(there.getY() - at.getY())) == nearest)
				{
					tied.add(tile.getName());
				}
			}
			nearestNames.put(record.getName(), tied);
		}

		TreeMap<String, Integer> declared = new TreeMap<>();
		Matcher row = REACH_ROW.matcher(read());
		int rows = 0;
		int previous = Integer.MAX_VALUE;
		while (row.find())
		{
			rows++;
			String name = row.group(2);
			assertEquals("the reach table is numbered in one run, and row " + rows
				+ " is written as " + row.group(1), rows, Integer.parseInt(row.group(1)));

			int tiles = Integer.parseInt(row.group(4));
			assertTrue("the reach table is the QA order, so it has to be sorted by "
				+ "distance — " + name + " breaks it", tiles <= previous);
			previous = tiles;
			assertEquals("the table lists " + name + " twice", null,
				declared.put(name, tiles));

			EntityDefinition record = ours().get(name);
			assertNotNull(name + " is in the reach table and not in the data", record);
			assertEquals(name + "'s city", City.of(record.getCityRegionId()).getLabel(),
				row.group(3));

			TreeSet<String> tied = nearestNames.get(name);
			assertNotNull(name + " is in the reach table and is not nine tiles or more "
				+ "from anything proven", tied);
			assertTrue(name + "'s row says to measure from \"" + row.group(5) + "\", and "
					+ "the proven figure at " + tiles + " tiles is " + tied,
				tied.contains(row.group(5)));
		}

		assertEquals("the reach table has to have a row per far figure", measured.size(), rows);
		assertEquals("the reach table and the measurement have to be the same set and the "
			+ "same distances", measured, declared);
		assertEquals("and there have to be 21 of them, not the seven this document "
			+ "published until 2026-08-30", 21, measured.size());
	}

	/**
	 * <b>The prose above the reach table names figures from the rows it claims.</b>
	 *
	 * <p>Three sentences in that section read {@code Rows N to M …} and then name figures
	 * out of that band. Nothing checked them — the reach guard parses the table and stops
	 * — and one of them was wrong from the day it was written: "Rows 15 to 21 are at
	 * exactly nine. Three of them — <b>Thomasin</b>, Thackeray and Rushen …", where
	 * Thomasin is row 13, at ten tiles. A walker reading down the QA order is told which
	 * of the rows in front of them are the softer sort of far away; a name from a
	 * different band makes that advice point at the wrong figure.
	 *
	 * <p>What is asserted is the part a sentence cannot wriggle out of: the bands cover
	 * the table exactly once and in order, every figure named inside a band sits in it,
	 * the count word matches how many were named, and a band that claims a distance is at
	 * that distance in every one of its rows.
	 */
	@Test
	public void theProseAboveTheReachTableNamesFiguresFromTheRowsItClaims() throws IOException
	{
		String text = read();

		TreeMap<String, Integer> rank = new TreeMap<>();
		TreeMap<Integer, Integer> tilesByRow = new TreeMap<>();
		Matcher row = REACH_ROW.matcher(text);
		while (row.find())
		{
			rank.put(row.group(2), Integer.parseInt(row.group(1)));
			tilesByRow.put(Integer.parseInt(row.group(1)), Integer.parseInt(row.group(4)));
		}
		assertEquals("the reach table has to have been found", 21, rank.size());

		int bands = 0;
		int expectedFirstRow = 1;
		Matcher claim = ROWS_CLAIM.matcher(text);
		while (claim.find())
		{
			bands++;
			int from = Integer.parseInt(claim.group(1));
			int to = Integer.parseInt(claim.group(2));
			String prose = claim.group(3);

			assertEquals("the bands have to tile the table in order, and this one starts "
				+ "at row " + from, expectedFirstRow, from);
			expectedFirstRow = to + 1;
			assertTrue("a band cannot run backwards", to >= from);
			assertTrue("row " + to + " is past the end of the table", tilesByRow.containsKey(to));

			// "… are the ten …" has to be the size of the band.
			Matcher size = Pattern.compile("\\bare the ([a-z]+)\\b").matcher(prose);
			if (size.find() && NUMBERS.containsKey(size.group(1)))
			{
				assertEquals("rows " + from + " to " + to + " are called \"the "
						+ size.group(1) + "\"", to - from + 1,
					(int) NUMBERS.get(size.group(1)));
			}

			// "… are at exactly nine." has to hold for every row in the band.
			Matcher exactly = Pattern.compile("\\bat exactly ([a-z]+)\\b").matcher(prose);
			if (exactly.find() && NUMBERS.containsKey(exactly.group(1)))
			{
				for (int n = from; n <= to; n++)
				{
					assertEquals("rows " + from + " to " + to + " are said to be at exactly "
							+ exactly.group(1) + ", and row " + n + " is not",
						(int) NUMBERS.get(exactly.group(1)), (int) tilesByRow.get(n));
				}
			}

			List<String> named = new ArrayList<>();
			Matcher bold = BOLD_NAMES.matcher(prose);
			while (bold.find())
			{
				for (String name : bold.group(1).split(",\\s*|\\s+and\\s+"))
				{
					named.add(name.trim());
				}
			}

			for (String name : named)
			{
				Integer at = rank.get(name);
				assertNotNull("the prose for rows " + from + " to " + to + " names \""
					+ name + "\", which is not in the reach table at all", at);
				assertTrue(name + " is named in the sentence about rows " + from + " to "
						+ to + " and is row " + at + ", at " + tilesByRow.get(at) + " tiles",
					at >= from && at <= to);
			}

			// "Seven of them (**…**)" has to be as many names as it lists. The count
			// word is only the one that introduces the bold run — "if any of them is
			// standing in a pew" is prose, not a tally.
			Matcher howMany = Pattern.compile("\\b([A-Za-z]+) of them\\b(?=[^*]{0,8}\\*\\*)")
				.matcher(prose);
			if (named.isEmpty())
			{
				assertTrue("rows " + from + " to " + to + " name nobody and still count "
					+ "them", !howMany.find());
			}
			else
			{
				assertTrue("the sentence about rows " + from + " to " + to + " names "
					+ named + " and does not say how many of the band that is",
					howMany.find());
				String word = howMany.group(1).toLowerCase();
				assertTrue("\"" + howMany.group(1) + " of them\" is not a number this test "
					+ "knows", NUMBERS.containsKey(word));
				assertEquals("the sentence about rows " + from + " to " + to + " says \""
						+ howMany.group(1) + " of them\" and names " + named,
					(int) NUMBERS.get(word), named.size());
			}
		}

		assertEquals("the bands have to cover the whole table", 22, expectedFirstRow);
		assertEquals("and there have to be three of them", 3, bands);
	}

	/**
	 * The document's own claim about what this pass did not do, checked.
	 *
	 * <p>Three sentences in the "deliberately did not do" section are the ones a reader
	 * would rely on and nothing else here would notice going stale: that the pass added
	 * no model id, no animation name, and nothing to Varrock's three central regions.
	 */
	@Test
	public void theClaimsAboutWhatWasNotDoneAreTrue() throws IOException
	{
		String text = read();
		assertTrue("the document has to state the model-id figure",
			text.contains("**324** distinct"));
		assertEquals("and it has to be the figure that ships",
			324, ShippedModelIds.distinct().size());

		assertTrue("the document has to state the animation figure",
			text.contains("**72** distinct animation"));
		assertEquals("and it has to be the figure that ships",
			72, ShippedAnimationNames.all().size());

		TreeSet<String> inVarrocksCentre = new TreeSet<>();
		for (EntityDefinition entity : shipped())
		{
			int region = entity.getRegionId();
			if ((region == 12852 || region == 12853 || region == 12597)
				&& entity.getUuid().toString().startsWith(MARKER))
			{
				inVarrocksCentre.add(entity.label());
			}
		}
		assertTrue("the document says regions 12852, 12853 and 12597 gained nothing, and "
			+ "they gained: " + inVarrocksCentre, inVarrocksCentre.isEmpty());
	}

	/**
	 * @return the colour this record paints the slot it aimed at {@code base}, or
	 * {@code null} if it aimed at no such slot
	 *
	 * <p>A {@code find} slot is the author's statement of which body part they meant,
	 * which is the property {@link BodySlots#SKIN_BASE}'s javadoc sets out and the reason
	 * "what colour are this citizen's trousers" is answerable from the record alone.
	 */
	private static Integer painted(EntityDefinition record, int base)
	{
		short[] find = record.getRecolorFind();
		short[] replace = record.getRecolorReplace();
		for (int i = 0; i < find.length; i++)
		{
			if ((find[i] & 0xFFFF) == base)
			{
				return replace[i] & 0xFFFF;
			}
		}
		return null;
	}

	/**
	 * The eight rows of the document's livery table, keyed by the city label.
	 *
	 * <p>This is the palette section at the top of the document — measured once per city
	 * and written once — and it is the source
	 * {@link #theLiveryIsOneSetPerCityAndNoTwoCitiesShareOne} measures records against.
	 * It is deliberately a different part of the file from the {@code Livery:} lines: an
	 * entry cannot edit its way into agreeing with it.
	 */
	private static TreeMap<String, Palette> published() throws IOException
	{
		TreeMap<String, Palette> out = new TreeMap<>();
		Matcher row = PALETTE_ROW.matcher(read());
		while (row.find())
		{
			assertEquals("the livery table lists " + row.group(1) + " twice", null,
				out.put(row.group(1), new Palette(
					Integer.parseInt(row.group(2)),
					Integer.parseInt(row.group(3)),
					Integer.parseInt(row.group(4)))));
		}

		assertEquals("the livery table has to have a row per liveried city — a pattern "
			+ "that matched nothing would make every colour assertion in this file "
			+ "vacuous", 8, out.size());
		return out;
	}

	/**
	 * @return whether two packed colours are the same shade at different lightnesses,
	 * which is the only thing a cut is allowed to change
	 */
	private static boolean sameShade(int a, int b)
	{
		return hue(a) == hue(b) && saturation(a) == saturation(b);
	}

	/** @return a packed colour written the way the document's livery table writes it */
	private static String describe(int packed)
	{
		return packed + " (h" + hue(packed) + "/s" + saturation(packed)
			+ "/l" + lightness(packed) + ")";
	}

	/** @return the six hue bits of a packed game colour */
	private static int hue(int packed)
	{
		return (packed & 0xFFFF) >>> 10;
	}

	/**
	 * @return how many rungs apart two hues are, measured the short way round
	 *
	 * <p>Hue is a wheel of sixty-four, so a plain subtraction is only right while both
	 * values sit on the same side of the 63→0 seam. It is right for Falador against
	 * Lumbridge and would report 61 for a pair three rungs apart across the seam, which
	 * is how a separation claim goes quietly wrong rather than red.
	 */
	private static int hueGap(int a, int b)
	{
		int gap = Math.abs(hue(a) - hue(b)) % 64;
		return Math.min(gap, 64 - gap);
	}

	/** @return the three saturation bits */
	private static int saturation(int packed)
	{
		return ((packed & 0xFFFF) >>> 7) & 0x07;
	}

	/** @return the seven lightness bits */
	private static int lightness(int packed)
	{
		return packed & 0x7F;
	}

	/**
	 * Every record a {@code Kit:} line could be naming, keyed the way that line names it.
	 *
	 * <p>Name alone is not a key — the dataset has two "Charlie"s — so the key is the
	 * name and the region, which is exactly the pair the document prints.
	 */
	private static TreeMap<String, EntityDefinition> donorsByName()
	{
		TreeMap<String, EntityDefinition> out = new TreeMap<>();
		for (EntityDefinition entity : shipped())
		{
			if (entity.getName() != null && !entity.getUuid().toString().startsWith(MARKER))
			{
				out.put(entity.getName() + "@" + entity.getRegionId(), entity);
			}
		}
		return out;
	}

	private static TreeMap<String, EntityDefinition> ours()
	{
		TreeMap<String, EntityDefinition> byName = new TreeMap<>();
		for (EntityDefinition entity : shipped())
		{
			if (entity.getUuid().toString().startsWith(MARKER))
			{
				assertEquals("two liveried records named " + entity.getName(), null,
					byName.put(entity.getName(), entity));
			}
		}

		assertEquals("liveried records in the shipped data", FIGURES, byName.size());
		return byName;
	}

	private static List<EntityDefinition> shipped()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> out = new ArrayList<>();
		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			if (region != null)
			{
				out.addAll(region.getEntities());
			}
		}
		return out;
	}

	private static List<Entry> entries() throws IOException
	{
		List<Entry> out = new ArrayList<>();
		Matcher matcher = ENTRY.matcher(read());
		while (matcher.find())
		{
			out.add(new Entry(matcher.group(1), matcher.group(2)));
		}

		assertEquals("the checklist parser has to find every entry — a pattern that "
			+ "matched nothing would pass every assertion in this file while reading no "
			+ "part of the document at all", FIGURES, out.size());
		return out;
	}

	private static String read() throws IOException
	{
		File file = new File(DOC);
		assertTrue(file.getAbsolutePath() + " is missing, and it is the walk these 127 "
			+ "records are waiting on", file.isFile());
		return new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
	}

	/**
	 * {@code NOTICE}, which item 12 uses to make the same colour claims in prose.
	 *
	 * <p>Declared an input of the {@code test} task in {@code build.gradle} alongside the
	 * checklist, for the same reason: without that, editing it and running
	 * {@code ./gradlew test} reports nothing and exits 0.
	 */
	private static String notice() throws IOException
	{
		File file = new File(NOTICE);
		assertTrue(file.getAbsolutePath() + " is missing, and it is the disclosure this "
			+ "pass's colours are published in", file.isFile());
		return new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
	}

	private static TreeMap<String, Integer> orientations()
	{
		TreeMap<String, Integer> out = new TreeMap<>();
		out.put("north", 0);
		out.put("east", 512);
		out.put("south", 1024);
		out.put("west", 1536);
		return out;
	}

	/** The number words the prose above the reach table counts in. */
	private static TreeMap<String, Integer> numbers()
	{
		TreeMap<String, Integer> out = new TreeMap<>();
		String[] words = {
			"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
			"nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
			"sixteen", "seventeen", "eighteen", "nineteen", "twenty",
		};
		for (int i = 0; i < words.length; i++)
		{
			out.put(words[i], i);
		}
		out.put("twenty-one", 21);
		return out;
	}

	/** One city's row of the document's livery table. */
	private static final class Palette
	{
		final int torso;
		final int legs;
		final int trim;

		Palette(int torso, int legs, int trim)
		{
			this.torso = torso;
			this.legs = legs;
			this.trim = trim;
		}
	}

	private static final class Entry
	{
		final String name;
		final String body;

		Entry(String name, String body)
		{
			this.name = name;
			this.body = body;
		}
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The consistency guard on the city mapping.
 *
 * <p>Two tables have to line up and neither one can be derived from the other:
 * the region ids live in {@link City}, the 9 checkboxes live in
 * {@link LivelyCitiesConfig}, and RuneLite's config annotations make generating
 * one from the other impossible. So this file's whole job is to make a mismatch a
 * red build rather than a checkbox that quietly does nothing, or does someone
 * else's job, or a whole city with no checkbox at all.
 */
public class CityTest
{
	/**
	 * The requirement, stated as a test: every region the plugin ships data for
	 * has exactly one home.
	 *
	 * <p>Both directions matter and both have failed in other people's plugins. A
	 * region with no city cannot be switched off. A region in two cities means one
	 * of the two checkboxes does nothing, which nobody notices until someone asks
	 * why unticking Falador left half of it standing there.
	 *
	 * <p>It walks the constants' own arrays rather than {@link City#of(int)}, on
	 * purpose: the lookup map is fail-soft about collisions, so asking it would be
	 * asking the thing under test to grade itself.
	 */
	@Test
	public void everyShippedRegionBelongsToExactlyOneCity()
	{
		Map<Integer, List<City>> claims = new HashMap<>();
		for (City city : City.values())
		{
			for (int regionId : city.getRegionIds())
			{
				claims.computeIfAbsent(regionId, k -> new ArrayList<>()).add(city);
			}
		}

		List<Integer> shipped = ShippedRegions.ids();
		assertFalse("the dataset has to be on the classpath for this to mean anything",
			shipped.isEmpty());

		List<String> homeless = new ArrayList<>();
		List<String> contested = new ArrayList<>();

		for (int regionId : shipped)
		{
			List<City> claimants = claims.get(regionId);
			if (claimants == null)
			{
				homeless.add(String.valueOf(regionId));
				continue;
			}
			if (claimants.size() > 1)
			{
				contested.add(regionId + " claimed by " + claimants);
			}
		}

		assertEquals("region file(s) with no city, so nothing can switch them off: " + homeless,
			0, homeless.size());
		assertEquals("region(s) claimed by more than one city: " + contested,
			0, contested.size());

		// The other direction: a city naming a region that does not ship is a
		// checkbox for nothing, and usually a typo in an id.
		List<String> phantom = new ArrayList<>();
		for (Map.Entry<Integer, List<City>> entry : claims.entrySet())
		{
			if (!shipped.contains(entry.getKey()))
			{
				phantom.add(entry.getKey() + " (" + entry.getValue() + ")");
			}
		}
		assertEquals("city region id(s) with no region file: " + phantom, 0, phantom.size());

		assertEquals("every shipped region is mapped exactly once",
			shipped.size(), claims.size());
	}

	/**
	 * The enum→checkbox half of the mapping, checked one city at a time.
	 *
	 * <p>{@link FakeConfig} wires each of the 9 getters to its own {@link City},
	 * so switching off exactly one city and finding exactly one city switched off
	 * is the composition of the two mappings coming out as the identity. A
	 * copy-paste in either file — {@code VARROCK.enabledIn} calling
	 * {@code cityLumbridge()}, or two constants sharing a getter — shows up here
	 * as two cities off, or the wrong one.
	 */
	@Test
	public void everyCityCheckboxSwitchesOffExactlyItsOwnCity()
	{
		for (City target : City.values())
		{
			FakeConfig config = new FakeConfig().disableOnly(target);

			for (City other : City.values())
			{
				int regionId = other.getRegionIds()[0];
				boolean enabled = City.isEnabled(regionId, config);

				if (other == target)
				{
					assertFalse("unticking " + target + " should switch it off "
						+ "(region " + regionId + ")", enabled);
				}
				else
				{
					assertTrue("unticking " + target + " must not switch off " + other
						+ " (region " + regionId + ")", enabled);
				}
			}
		}
	}

	@Test
	public void everyRegionOfACityFollowsTheSameCheckbox()
	{
		for (City city : City.values())
		{
			FakeConfig config = new FakeConfig().disableOnly(city);
			for (int regionId : city.getRegionIds())
			{
				assertEquals("region " + regionId + " should resolve to " + city,
					city, City.of(regionId));
				assertFalse("region " + regionId + " should follow " + city + "'s checkbox",
					City.isEnabled(regionId, config));
			}
		}
	}

	/**
	 * A region no city claims is shown, not hidden. That is what lets a region
	 * file land in one commit and its checkbox in the next; the test above is what
	 * stops the grace period becoming permanent.
	 */
	@Test
	public void aRegionNoCityClaimsIsStillShown()
	{
		// 11422 is Keldagrim. There is no region file for it and no city constant.
		int unmapped = 11422;
		assertNull("the fixture has to be genuinely unmapped", City.of(unmapped));

		FakeConfig everythingOff = new FakeConfig().disable(City.values());
		assertTrue("an unmapped region must fail open",
			City.isEnabled(unmapped, everythingOff));
	}

	@Test
	public void labelsAreUniqueAndNoCityIsEmpty()
	{
		TreeSet<String> labels = new TreeSet<>();
		for (City city : City.values())
		{
			assertNotNull(city.getLabel());
			assertFalse(city + " has a blank label", city.getLabel().trim().isEmpty());
			assertTrue("two cities share the label '" + city.getLabel() + "'",
				labels.add(city.getLabel()));
			assertTrue(city + " claims no regions", city.getRegionIds().length > 0);
		}

		assertEquals("9 checkboxes, one per city", 9, City.values().length);
	}

	/**
	 * The declaration order is the order the checkboxes are numbered in, so the
	 * comment at the top of {@link City} claims it is alphabetical by label. Cheap
	 * to check, and it is the kind of claim that quietly stops being true the first
	 * time a constant is appended at the bottom instead of slotted in.
	 */
	@Test
	public void theDeclarationOrderIsAlphabeticalByLabel()
	{
		City[] cities = City.values();
		for (int i = 1; i < cities.length; i++)
		{
			String previous = cities[i - 1].getLabel();
			String current = cities[i].getLabel();
			assertTrue("'" + previous + "' is declared before '" + current
					+ "', which puts the checkboxes out of alphabetical order",
				previous.compareTo(current) < 0);
		}
	}

	/**
	 * The four regions a wrong "Digsite" checkbox used to own, pinned to the place
	 * each of them is actually in.
	 *
	 * <p>Every number here came out of an OSRS Wiki {@code {{Infobox Location}}}
	 * map coordinate put through {@link RenderPolicy#regionIdOf(int, int)}:
	 *
	 * <ul>
	 *   <li>Digsite, map centre (3354, 3420) — region <b>13365</b>, which this
	 *       plugin ships no data for. That is the whole reason the checkbox was
	 *       wrong: it named a place none of its regions contained.</li>
	 *   <li>Lumber Yard, map polygon x 3293..3326 / y 3492..3518 — every corner
	 *       is region <b>13110</b>.</li>
	 *   <li>Paterdomus Temple, map centre (3416, 3487) — region <b>13622</b>.</li>
	 *   <li>Ranging Guild, map polygon x 2651..2686 / y 3411..3446 — every corner
	 *       is region <b>10549</b>. Catherby's own centre (2810, 3440) is region
	 *       11061.</li>
	 * </ul>
	 *
	 * <p>The assertions run the arithmetic rather than quoting the answers, so a
	 * transposed digit in a region id shows up here rather than as a checkbox that
	 * switches off the wrong street.
	 *
	 * <p><b>What this test lost in the nine-city cut, stated plainly.</b> Three of
	 * the four regions — 13110, 13622 and 10549 — no longer ship, so the
	 * "…and it is filed under the checkbox that describes it" half of each pair is
	 * gone with them; {@link City#of} now answers {@code null} for all three, which
	 * is asserted below but is a weaker claim than naming the right city was. The
	 * arithmetic half survives intact and is the half that catches a transposed
	 * digit. The one pairing still checked end to end is 13109 → Varrock, and the
	 * Ranging-Guild-is-not-Catherby point survives as the distance between the two
	 * map points — 159 tiles, which is a claim that can fail, unlike the
	 * {@code 10549 != 11061} it replaced.
	 */
	@Test
	public void theRegionsTheDigsiteCheckboxClaimedBelongToTheirRealPlaces()
	{
		// The Digsite itself. No file ships for it, so no city may claim it, and
		// nothing else may pretend to be it.
		int digsite = RenderPolicy.regionIdOf(3354, 3420);
		assertEquals(13365, digsite);
		assertNull("no city may claim the Digsite while no region file ships for it",
			City.of(digsite));

		// The Lumber Yard's polygon, corner by corner.
		int lumberYard = RenderPolicy.regionIdOf(3293, 3492);
		assertEquals(13110, lumberYard);
		assertEquals(13110, RenderPolicy.regionIdOf(3326, 3518));

		// Paterdomus Temple.
		int paterdomus = RenderPolicy.regionIdOf(3416, 3487);
		assertEquals(13622, paterdomus);

		// The Ranging Guild's polygon, and Catherby, which is not it. What made
		// filing the Guild under Catherby's checkbox a mistake rather than a
		// judgement call is how far apart the two map points are, so the distance is
		// what is asserted. This line used to read `assertFalse(rangingGuild ==
		// 11061)`, which could not fail: `rangingGuild` is asserted to be 10549 two
		// lines above, so the comparison was already decided and the assertion was a
		// sentence rather than a check.
		int rangingGuild = RenderPolicy.regionIdOf(2651, 3411);
		assertEquals(10549, rangingGuild);
		assertEquals(10549, RenderPolicy.regionIdOf(2686, 3446));
		assertEquals(11061, RenderPolicy.regionIdOf(2810, 3440));
		assertEquals(City.CATHERBY, City.of(11061));
		assertEquals("the Ranging Guild's map point is 159 tiles west of Catherby's — "
				+ "a transposed digit in either pair would land them next door to each "
				+ "other and this is what would notice",
			159,
			RenderPolicy.tileDistance(
				new WorldPoint(2651, 3411, 0), new WorldPoint(2810, 3440, 0)));

		// All three are out of the dataset now, and none of them may be claimed by a
		// city while no region file ships for it — the same rule the Digsite is held
		// to above, applied to the three that used to have checkboxes of their own.
		assertNull("13110 ships no file, so no city may claim it", City.of(lumberYard));
		assertNull("13622 ships no file, so no city may claim it", City.of(paterdomus));
		assertNull("10549 ships no file, so no city may claim it", City.of(rangingGuild));

		// The strip outside Varrock's east gate: no landmark of its own, so it is
		// grouped with the city whose wall it starts at. 12853 ends at x 3263. This
		// is the one pairing of the four that still ships, so it is the one that can
		// still be checked all the way through to a checkbox.
		int outsideTheEastGate = RenderPolicy.regionIdOf(3268, 3426);
		assertEquals(13109, outsideTheEastGate);
		assertEquals(City.VARROCK, City.of(outsideTheEastGate));
		assertEquals("Varrock's own centre and its east-gate road share a checkbox",
			City.of(RenderPolicy.regionIdOf(3210, 3448)), City.of(outsideTheEastGate));
	}

	/**
	 * The region id arrays are the enum's state, so handing out the original would
	 * let any caller edit the mapping for the rest of the session.
	 */
	/**
	 * <b>Each city's {@code configKey} is the key on the checkbox its own
	 * {@code enabledIn} reads.</b>
	 *
	 * <p>This is the guard the side panel needs and nothing else does. Rendering only
	 * ever asks "is this city on?", which {@link City#enabledIn} answers; the panel has
	 * to <i>write</i> the checkbox, which needs the key, and a key paired with the wrong
	 * getter is a card that reads "Varrock: on" and unticks Lumbridge. On a live plugin
	 * that is a setting silently changed under a user who did not ask.
	 *
	 * <p><b>Composed rather than compared, because comparing is what a copy-paste
	 * survives.</b> The chain checked here is: the enum's key → the {@code @ConfigItem}
	 * in the source that declares that key → the getter that annotation sits on → the
	 * getter {@code enabledIn} actually calls. {@link KeyedConfig} closes the last link
	 * by answering {@code true} from exactly one getter, named by its own method name, so
	 * a constant pointing at another city's key produces a city that thinks it is off.
	 *
	 * <p>The source is read rather than reflected on, for the reason
	 * {@code RegionDataLoaderTest.visibleConfigKeys} gives: reflection is banned in this
	 * project, shipped or not, and the annotation's argument is a constant whose name is
	 * only visible in the text.
	 */
	@Test
	public void everyCityCheckboxKeySitsOnTheGetterThatCityReads() throws IOException
	{
		Map<String, String> gettersByKey = cityGettersByKey();
		assertEquals("one city @ConfigItem per city", City.values().length, gettersByKey.size());

		Set<String> keys = new TreeSet<>();
		for (City city : City.values())
		{
			String key = city.getConfigKey();
			assertTrue(city + " reuses the key '" + key + "'", keys.add(key));

			String getter = gettersByKey.get(key);
			assertNotNull(city + " names key '" + key + "', which no @ConfigItem in "
				+ "LivelyCitiesConfig declares", getter);

			// The getter that annotation sits on is the one this city reads — and every
			// other city reads a different one.
			assertTrue(city + "'s key is declared on " + getter + "(), which is not the "
					+ "getter " + city + ".enabledIn calls",
				city.enabledIn(new KeyedConfig(getter)));

			for (City other : City.values())
			{
				if (other != city)
				{
					assertFalse(other + " must not read " + city + "'s checkbox",
						other.enabledIn(new KeyedConfig(getter)));
				}
			}
		}

		assertEquals("nine distinct keys", City.values().length, keys.size());
	}

	/**
	 * The nine {@code city*} {@code @ConfigItem}s in the config source, as
	 * key → the getter the annotation is attached to.
	 *
	 * <p>The scan walks parentheses rather than matching a regex across the file, for the
	 * reason {@code RegionDataLoaderTest} gives: an annotation argument list contains
	 * commas, quotes and nested calls, and a lazy {@code .*?} stopping at the first
	 * {@code )} reads half of one.
	 */
	private static Map<String, String> cityGettersByKey() throws IOException
	{
		String source = new String(Files.readAllBytes(
			new File("src/main/java/com/matthewmariner/livelycities/LivelyCitiesConfig.java")
				.toPath()), StandardCharsets.UTF_8);

		// The interface's own key constants, read out of the source rather than off the
		// interface, so a constant whose declared value stopped matching City's would be
		// caught here rather than agreeing with itself.
		Map<String, String> constants = new HashMap<>();
		Matcher declaration = Pattern
			.compile("String\\s+(KEY_\\w+)\\s*=\\s*\"([^\"]+)\"\\s*;")
			.matcher(source);
		while (declaration.find())
		{
			constants.put(declaration.group(1), declaration.group(2));
		}
		assertTrue("no KEY_ constants found, so this scan is checking nothing",
			constants.size() >= City.values().length);

		Map<String, String> out = new TreeMap<>();
		Pattern keyName = Pattern.compile("keyName\\s*=\\s*(?:\"([^\"]+)\"|([\\w.]+))");
		Pattern getter = Pattern.compile("\\A\\s*default\\s+boolean\\s+(\\w+)\\s*\\(");
		final String marker = "@ConfigItem(";

		for (int at = source.indexOf(marker); at >= 0; at = source.indexOf(marker, at + 1))
		{
			int open = at + marker.length();
			int depth = 1;
			int end = open;
			while (depth > 0)
			{
				assertTrue("unbalanced @ConfigItem at offset " + at, end < source.length());
				char c = source.charAt(end++);
				if (c == '(')
				{
					depth++;
				}
				else if (c == ')')
				{
					depth--;
				}
			}

			Matcher match = keyName.matcher(source.substring(open, end - 1));
			assertTrue("every @ConfigItem must name a key", match.find());

			String key = match.group(1) != null ? match.group(1) : constants.get(match.group(2));
			if (key == null || !key.startsWith("city"))
			{
				continue;
			}

			Matcher declared = getter.matcher(source.substring(end));
			assertTrue("the @ConfigItem for '" + key + "' has to be attached to a boolean "
				+ "getter", declared.find());
			assertNull("two @ConfigItems declare '" + key + "'", out.put(key, declared.group(1)));
		}

		return out;
	}

	/**
	 * A config where exactly one city getter answers {@code true}, chosen by its own
	 * method name.
	 *
	 * <p>{@link FakeConfig} cannot do this job: it wires each getter to a {@link City},
	 * which is the mapping under test, so asking it would be asking the thing under test
	 * to grade itself. Here the only thing a getter knows is what it is called.
	 */
	private static final class KeyedConfig implements LivelyCitiesConfig
	{
		private final String getter;

		private KeyedConfig(String getter)
		{
			this.getter = getter;
		}

		private boolean is(String name)
		{
			return getter.equals(name);
		}

		@Override
		public boolean cityAlKharid()
		{
			return is("cityAlKharid");
		}

		@Override
		public boolean cityArdougne()
		{
			return is("cityArdougne");
		}

		@Override
		public boolean cityCatherby()
		{
			return is("cityCatherby");
		}

		@Override
		public boolean cityDraynor()
		{
			return is("cityDraynor");
		}

		@Override
		public boolean cityEdgeville()
		{
			return is("cityEdgeville");
		}

		@Override
		public boolean cityFalador()
		{
			return is("cityFalador");
		}

		@Override
		public boolean cityGrandExchange()
		{
			return is("cityGrandExchange");
		}

		@Override
		public boolean cityLumbridge()
		{
			return is("cityLumbridge");
		}

		@Override
		public boolean cityVarrock()
		{
			return is("cityVarrock");
		}
	}

	@Test
	public void theRegionIdsCannotBeEditedThroughTheGetter()
	{
		int[] first = City.VARROCK.getRegionIds();
		int original = first[0];
		first[0] = 999999;

		assertEquals("getRegionIds() must hand back a copy",
			original, City.VARROCK.getRegionIds()[0]);
		assertEquals(City.VARROCK, City.of(original));
	}
}

package com.matthewmariner.livelycities;

import java.util.EnumMap;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * Which {@link Theme} each {@link City} is expected to hold.
 *
 * <p>Built directly on {@link City} rather than a second region list — the
 * class javadoc on {@code City} is explicit that it is the single source of
 * truth for region grouping, and {@code CityTest} is what keeps every shipped
 * region mapped to exactly one city. Duplicating region ids here would give
 * this lint its own, second chance to disagree with that mapping. This class
 * only ever asks "which theme does this already-resolved city expect", so a
 * region can only be misfiled once, in {@link City}.
 *
 * <p>Only the cities with a real, defensible identity are listed; every other
 * city defaults to {@link Theme#GENERIC} — see {@link Theme} for why the set
 * stops here rather than reaching for Fremennik/snow, elven, or dwarven.
 */
final class CityTheme
{
	private static final Map<City, Theme> BY_CITY = build();

	private CityTheme()
	{
	}

	/**
	 * @param city a city, or {@code null} for a region no city claims
	 * @return the theme entities in this city are expected to match; a city
	 * with no explicit entry (and a {@code null} city — see {@code City}'s own
	 * fail-open rule for an unmapped region) both answer {@link Theme#GENERIC}
	 */
	static Theme of(@Nullable City city)
	{
		if (city == null)
		{
			return Theme.GENERIC;
		}

		return BY_CITY.getOrDefault(city, Theme.GENERIC);
	}

	private static Map<City, Theme> build()
	{
		Map<City, Theme> byCity = new EnumMap<>(City.class);

		// Al Kharid: the shipped dataset's one desert city.
		byCity.put(City.AL_KHARID, Theme.DESERT);

		// Musa Point (Karamja) and Canifis/the Barrows (Morytania) used to be
		// here, carrying Theme.KARAMJA_JUNGLE and Theme.MORYTANIA_UNDEAD. All
		// three places left the dataset in the nine-city cut, so both themes lost
		// their only anchor and were removed from Theme along with these rows —
		// see Theme's javadoc for the rule, which is the same one that keeps
		// FREMENNIK_SNOW and an elven theme out.

		// The Grand Exchange, and the only city that may hold a cameo. Note what
		// this does *not* do: Theme.GENERIC is compatible with every region, so
		// tagging the GE this way does not stop an ordinary townsperson standing
		// there — Richard the cook and the squirrel in 12598.json are both GENERIC
		// and both still pass. What it does is make Theme.CAMEO compatible with
		// here and nowhere else. See Theme.CAMEO.
		byCity.put(City.GRAND_EXCHANGE, Theme.CAMEO);

		return byCity;
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * {@code docs/CITY-TOP-UP-CHECK.md} against the records it describes.
 *
 * <h2>Why a document gets a test</h2>
 *
 * <p>That file is not prose about the plugin. It is the <b>work order</b> for the one
 * thing this dataset still needs and that no command can do: a human walking to 33
 * tiles and looking at what is standing on them. Its Ground Markers block is pasted
 * straight into the client, and its entries are what the walker compares against what
 * they see. A tile in it that is not the tile in the JSON sends somebody to the wrong
 * square and gets a figure ticked that nobody looked at.
 *
 * <p>An independent review on 2026-08-29 read it against the data and found five
 * defects, four of them numeric and one of them a whole missing line — "Hollis" was
 * the only talking figure in the pass whose remark the entry did not print. None of
 * them would have failed anything, because nothing was reading this file. This is the
 * thing that reads it.
 *
 * <h2>What is checked, and what deliberately is not</h2>
 *
 * <p>Everything a walker acts on: which figures exist, where each one stands, which
 * way it faces, what its box is, what its Examine line says, what it says out loud,
 * and every one of the 57 Ground Markers. Not checked: the prose. Judgements like
 * "the likeliest of the six to be inside a wall" are exactly the human reasoning the
 * file exists to record, and a test that tried to verify them would be inventing a
 * rule rather than enforcing one.
 *
 * <p><b>This is a check on the file's shape as well as its content</b>, and that is
 * intended. If a future edit reformats an entry so the patterns below stop matching,
 * this goes red rather than quietly checking 32 figures instead of 33 — every parse
 * here is followed by a count. A document whose format is a contract with a person
 * holding a mouse is allowed to have a format.
 */
public class CityTopUpCheckTest
{
	private static final String DOC = "docs/CITY-TOP-UP-CHECK.md";

	/** The uuid prefix the top-up's records carry; {@link AuthoredRecordsTest} owns it. */
	private static final String MARKER = "add1";

	private static final int FIGURES = 33;
	private static final int NEW_BOXES = 12;

	/** Ground Markers' own colour strings, as the block spells them. */
	private static final String YELLOW = "#FFFFFF00";
	private static final String CYAN = "#FF00FFFF";

	/**
	 * One checklist entry: everything from {@code - [ ] **Name** — } up to the next
	 * entry, the next heading, or the next rule.
	 */
	private static final Pattern ENTRY = Pattern.compile(
		"^- \\[ \\] \\*\\*(.+?)\\*\\* — (.*?)(?=^- \\[ \\]|^#|^---)",
		Pattern.MULTILINE | Pattern.DOTALL);

	private static final Pattern TILE = Pattern.compile("^`(\\d+), (\\d+), (\\d+)`");
	private static final Pattern FACING = Pattern.compile("facing (north|south|east|west)");
	private static final Pattern BOX = Pattern.compile(
		"\\*\\*wanders\\*\\* `(\\d+),(\\d+) \\.\\. (\\d+),(\\d+)`");
	private static final Pattern EXAMINE = Pattern.compile(
		"Examine: \"(.*?)\"", Pattern.DOTALL);

	/**
	 * The {@code Says:} line and any continuation of it.
	 *
	 * <p>A continuation is a following line indented to the entry's own six spaces and
	 * <i>not</i> starting a bolded note, which is how the wrapped three-remark entry
	 * ("Nadir") is read whole while the {@code **Box note:**} beneath it is not swept
	 * in. Entries with nothing to say carry no {@code Says:} line at all, and that is a
	 * claim as much as the text is — see
	 * {@link #everyFiguresRemarksArePrintedInItsEntry()}.
	 */
	private static final Pattern SAYS = Pattern.compile(
		"Says: ((?:[^\\n]*)(?:\\n {6}(?!\\*)[^\\n]*)*)");

	private static final Pattern QUOTED = Pattern.compile("\"(.*?)\"", Pattern.DOTALL);

	private static final Pattern MARKERS = Pattern.compile(
		"```json\\n(\\[.*?\\])\\n```", Pattern.DOTALL);

	@Test
	public void theChecklistNamesEveryAuthoredFigureExactlyOnce() throws IOException
	{
		TreeSet<String> listed = new TreeSet<>();
		for (Entry entry : entries())
		{
			assertTrue("the checklist names '" + entry.name + "' twice",
				listed.add(entry.name));
		}

		TreeSet<String> authored = new TreeSet<>();
		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (citizen.uuid.startsWith(MARKER))
			{
				authored.add(citizen.name);
			}
		}

		// Both directions in one comparison: a figure in the data with no entry is a
		// tile nobody is sent to, and an entry with no figure is a walk to an empty
		// square. Both have happened to this file — the pass shipped a "Brother Alfric"
		// entry that outlived the record for as long as nothing compared the two.
		assertEquals("the checklist and the authored records have to be the same set",
			authored, listed);
		assertEquals("and there have to be 33 of them", FIGURES, listed.size());
	}

	/**
	 * Tile, facing and wander box, entry by entry.
	 *
	 * <p>The facing words are checked because a walker uses them to decide whether
	 * what they are looking at is the figure the entry describes. The mapping is the
	 * game's own JAU convention — 0 south, 512 west, 1024 north, 1536 east — and it is
	 * spelled out here rather than derived, because a table that derived it from the
	 * same constant the record uses would agree with itself whatever either said.
	 */
	@Test
	public void everyFigureStandsWhereItsEntrySaysAndFacesTheWayItSays() throws IOException
	{
		List<String> wrong = new ArrayList<>();
		int checked = 0;
		int boxes = 0;

		for (Entry entry : entries())
		{
			EntityDefinition record = record(entry.name);
			checked++;

			Matcher tile = TILE.matcher(entry.body);
			if (!tile.find())
			{
				wrong.add(entry.name + " has no `x, y, plane` tile");
				continue;
			}

			int x = Integer.parseInt(tile.group(1));
			int y = Integer.parseInt(tile.group(2));
			int plane = Integer.parseInt(tile.group(3));
			if (record.getWorldLocation().getX() != x
				|| record.getWorldLocation().getY() != y
				|| record.getWorldLocation().getPlane() != plane)
			{
				wrong.add(entry.name + " is listed at " + x + "," + y + "," + plane
					+ " and stands at " + record.getWorldLocation());
			}

			Matcher facing = FACING.matcher(entry.body);
			if (!facing.find())
			{
				wrong.add(entry.name + " does not say which way it faces");
			}
			else if (!facing.group(1).equals(compass(record.getOrientation())))
			{
				wrong.add(entry.name + " is listed facing " + facing.group(1)
					+ " and is oriented " + record.getOrientation() + " ("
					+ compass(record.getOrientation()) + ")");
			}

			Matcher box = BOX.matcher(entry.body);
			EntityDefinition.WanderBox authored = record.getWanderBox();
			if (box.find())
			{
				boxes++;
				if (authored == null)
				{
					wrong.add(entry.name + " is listed as a wanderer and carries no box");
				}
				else if (authored.getMinX() != Integer.parseInt(box.group(1))
					|| authored.getMinY() != Integer.parseInt(box.group(2))
					|| authored.getMaxX() != Integer.parseInt(box.group(3))
					|| authored.getMaxY() != Integer.parseInt(box.group(4)))
				{
					wrong.add(entry.name + " is listed pacing " + box.group(1) + ","
						+ box.group(2) + " .. " + box.group(3) + "," + box.group(4)
						+ " and paces " + authored.getMinX() + "," + authored.getMinY()
						+ " .. " + authored.getMaxX() + "," + authored.getMaxY());
				}
			}
			else if (authored != null)
			{
				wrong.add(entry.name + " carries a wander box the entry does not mention, "
					+ "so its cyan corner markers are missing from the import block");
			}
		}

		assertTrue("checklist entries that disagree with the shipped record: " + wrong,
			wrong.isEmpty());
		assertEquals("every figure has to have been checked", FIGURES, checked);
		assertEquals("and the twelve new wander boxes have to be the twelve listed",
			NEW_BOXES, boxes);
	}

	@Test
	public void everyFiguresExamineTextIsQuotedExactly() throws IOException
	{
		List<String> wrong = new ArrayList<>();
		int checked = 0;

		for (Entry entry : entries())
		{
			Matcher examine = EXAMINE.matcher(entry.body);
			if (!examine.find())
			{
				wrong.add(entry.name + " has no Examine line");
				continue;
			}

			checked++;
			String quoted = unwrap(examine.group(1));
			String actual = record(entry.name).getExamineText();
			if (!quoted.equals(actual))
			{
				wrong.add(entry.name + " is quoted as \"" + quoted + "\" and reads \""
					+ actual + "\"");
			}
		}

		assertTrue("Examine lines that are not what the record says: " + wrong,
			wrong.isEmpty());
		assertEquals("every figure has to have been checked", FIGURES, checked);
	}

	/**
	 * The {@code Says:} lines, including the entries that must not have one.
	 *
	 * <p>The absence is the half that failed. "Hollis" carries
	 * {@code "remarks": ["They are not all mine."]} and his entry printed no
	 * {@code Says:} line — the only talking figure in the pass whose line was left
	 * out, and invisible precisely because a missing line looks like a silent figure.
	 * So this asserts both directions: every remark appears, in order, and an entry
	 * with a {@code Says:} line has a record with remarks to justify it.
	 */
	@Test
	public void everyFiguresRemarksArePrintedInItsEntry() throws IOException
	{
		List<String> wrong = new ArrayList<>();
		int withRemarks = 0;
		int checked = 0;

		for (Entry entry : entries())
		{
			checked++;
			List<String> printed = new ArrayList<>();
			Matcher says = SAYS.matcher(entry.body);
			if (says.find())
			{
				Matcher quoted = QUOTED.matcher(says.group(1));
				while (quoted.find())
				{
					printed.add(unwrap(quoted.group(1)));
				}
			}

			List<String> authored = Arrays.asList(record(entry.name).getRemarks());
			if (!authored.isEmpty())
			{
				withRemarks++;
			}

			if (!printed.equals(authored))
			{
				wrong.add(entry.name + " prints " + printed + " and says " + authored);
			}
		}

		assertTrue("entries whose Says: lines are not the record's remarks: " + wrong,
			wrong.isEmpty());
		assertEquals("every figure has to have been checked", FIGURES, checked);

		// A sample guard with teeth: if every one of the 33 were silent, the loop above
		// would compare 33 empty lists to 33 empty lists and prove nothing at all.
		assertEquals("figures in this pass that have something to say", 10, withRemarks);
	}

	/**
	 * The Ground Markers block — the part of this file that is executable.
	 *
	 * <p>It is pasted into the client and it is what puts a square on the ground. A
	 * marker whose coordinates have drifted from the record does not look wrong; it
	 * looks like a figure that failed to spawn, which is the single most confusing
	 * outcome this walk can produce.
	 *
	 * <p>Region coordinates rather than world ones, because that is the format Ground
	 * Markers imports: region id {@code ((x >> 6) << 8) | (y >> 6)}, and the offsets
	 * inside it are the low six bits of each.
	 */
	@Test
	public void everyGroundMarkerLandsOnTheTileItIsLabelledWith() throws IOException
	{
		Matcher block = MARKERS.matcher(read());
		assertTrue("the Ground Markers import block is gone, and it is the reason this "
			+ "file is usable at all", block.find());

		JsonArray markers = TestGson.injected().fromJson(block.group(1), JsonArray.class);

		TreeMap<String, int[]> figures = new TreeMap<>();
		TreeMap<String, int[]> corners = new TreeMap<>();
		for (JsonElement element : markers)
		{
			JsonObject marker = element.getAsJsonObject();
			String label = marker.get("label").getAsString();
			int[] at = new int[]{
				marker.get("regionId").getAsInt(),
				marker.get("regionX").getAsInt(),
				marker.get("regionY").getAsInt(),
				marker.get("z").getAsInt()};

			if (YELLOW.equals(marker.get("color").getAsString()))
			{
				assertEquals("two yellow markers labelled " + label, null,
					figures.put(label, at));
			}
			else
			{
				assertEquals("expected only yellow and cyan markers", CYAN,
					marker.get("color").getAsString());
				assertEquals("two cyan markers labelled " + label, null,
					corners.put(label, at));
			}
		}

		assertEquals("one yellow marker per figure", FIGURES, figures.size());
		assertEquals("two cyan corners per new wander box", NEW_BOXES * 2, corners.size());
		assertEquals("and 57 markers in total, which is what the block's caption promises",
			FIGURES + NEW_BOXES * 2, markers.size());

		List<String> wrong = new ArrayList<>();
		for (Entry entry : entries())
		{
			EntityDefinition record = record(entry.name);
			int[] marker = figures.get(entry.name);
			if (marker == null)
			{
				wrong.add(entry.name + " has no yellow marker");
			}
			else
			{
				expect(wrong, entry.name, marker,
					record.getWorldLocation().getX(),
					record.getWorldLocation().getY(),
					record.getWorldLocation().getPlane());
			}

			EntityDefinition.WanderBox box = record.getWanderBox();
			if (box == null)
			{
				continue;
			}

			int[] sw = corners.get(entry.name + " box SW");
			int[] ne = corners.get(entry.name + " box NE");
			if (sw == null || ne == null)
			{
				wrong.add(entry.name + " is a wanderer with no cyan box corners");
				continue;
			}

			int plane = record.getWorldLocation().getPlane();
			expect(wrong, entry.name + " box SW", sw, box.getMinX(), box.getMinY(), plane);
			expect(wrong, entry.name + " box NE", ne, box.getMaxX(), box.getMaxY(), plane);
		}

		assertTrue("markers that do not land on the tile they name: " + wrong,
			wrong.isEmpty());
	}

	private static void expect(List<String> wrong, String label, int[] marker,
		int x, int y, int plane)
	{
		int regionId = ((x >> 6) << 8) | (y >> 6);
		int regionX = x & 63;
		int regionY = y & 63;

		if (marker[0] != regionId || marker[1] != regionX || marker[2] != regionY
			|| marker[3] != plane)
		{
			wrong.add(label + " marks " + Arrays.toString(marker) + " and should mark ["
				+ regionId + ", " + regionX + ", " + regionY + ", " + plane + "] for tile "
				+ x + "," + y + "," + plane);
		}
	}

	/** @return the compass word this file uses for a JAU orientation */
	private static String compass(int orientation)
	{
		switch (orientation)
		{
			case 0:
				return "south";
			case 512:
				return "west";
			case 1024:
				return "north";
			case 1536:
				return "east";
			default:
				return "orientation " + orientation;
		}
	}

	/** @return quoted text with its line wrapping collapsed back to single spaces */
	private static String unwrap(String quoted)
	{
		return quoted.replaceAll("\\s+", " ").trim();
	}

	private static EntityDefinition record(String name) throws IOException
	{
		EntityDefinition found = byName().get(name);
		if (found == null)
		{
			throw new IOException("no shipped record named '" + name + "'");
		}
		return found;
	}

	private static TreeMap<String, EntityDefinition> byName()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		TreeMap<String, EntityDefinition> byName = new TreeMap<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			if (region == null)
			{
				continue;
			}

			for (EntityDefinition entity : region.getEntities())
			{
				if (entity.getUuid().toString().startsWith(MARKER))
				{
					byName.put(entity.getName(), entity);
				}
			}
		}

		return byName;
	}

	private static List<Entry> entries() throws IOException
	{
		List<Entry> out = new ArrayList<>();
		Matcher matcher = ENTRY.matcher(read());
		while (matcher.find())
		{
			out.add(new Entry(matcher.group(1), matcher.group(2)));
		}

		assertEquals("the checklist parser has to find every entry — a pattern that "
			+ "matched nothing would pass every assertion in this file while reading no "
			+ "part of the document at all", FIGURES, out.size());
		return out;
	}

	private static String read() throws IOException
	{
		File file = new File(DOC);
		assertTrue(file.getAbsolutePath() + " is missing, and it is the walk this "
			+ "dataset is waiting on", file.isFile());
		return new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
	}

	private static final class Entry
	{
		final String name;
		final String body;

		Entry(String name, String body)
		{
			this.name = name;
			this.body = body;
		}
	}
}

package com.matthewmariner.livelycities;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

/**
 * Every label a user is meant to read clears a real contrast ratio against whatever is
 * actually painted behind it.
 *
 * <p><b>Why this exists.</b> This panel had exactly one raw {@code MEDIUM_GRAY_COLOR} —
 * RGB(77,77,77) — behind its {@code HELPER} alias, and that one line coloured every
 * detail line, greyed-out city name, "off" state and empty-state paragraph on the panel.
 * Against this panel's card background, RGB(30,30,30), that is a contrast ratio under
 * 2:1 — WCAG's floor for body text is 4.5:1. Every test in
 * {@code LivelyCitiesPanelTest} that asserted a label's text passed the whole time,
 * because an unreadable label still returns its string from {@code getText()}. This repo
 * ships {@code noRowOnThePanelIsPinnedToZeroHeight} for the exact same shape of gap —
 * existence is not visibility, and visibility is not legibility.
 *
 * <p><b>Computed, not hardcoded.</b> The ratio comes out of the two {@code Color}s a
 * label actually holds when this walks the tree — its own foreground, and the background
 * of the nearest ancestor that actually paints one — via the WCAG 2 relative-luminance
 * formula, so a future colour swap that reintroduces the bug fails on the numbers.
 *
 * <p><b>Two bars, structurally chosen.</b> Ordinary body text is held to WCAG SC 1.4.3's
 * 4.5:1. The two labels that are themselves opaque, self-painted chips — a density chip
 * and an override row's "show"/"unmute" action — are held to SC 1.4.11's 3:1 instead:
 * a chip's state is carried twice, in the fill as well as the glyph, which is the
 * redundancy 1.4.11 exists for. Which bar applies is read off {@link JLabel#isOpaque()}
 * rather than off which label this happens to be.
 */
public class ContrastGuardTest
{
	private static final WorldPoint IN_VARROCK = new WorldPoint(3225, 3360, 0);

	/** WCAG 2 SC 1.4.3 (text contrast, AA): the bar for a plain label on its panel. */
	private static final double TEXT_MIN_CONTRAST = 4.5;

	/**
	 * WCAG 2 SC 1.4.11 (non-text/UI-component contrast, AA): the bar for a label that
	 * paints its own background — a density chip or an override row's action label.
	 * Its selected/rest state is already carried by the fill, so the glyph itself is
	 * held to the UI-component bar rather than the paragraph one.
	 */
	private static final double CHIP_MIN_CONTRAST = 3.0;

	private final FakeConfig config = new FakeConfig();
	private final CitizenDirectory directory =
		new CitizenDirectory(new RegionDataLoader(TestGson.injected()));

	/**
	 * Before any game tick has ever posted — the panel's very first paint, with
	 * {@code model} still null. This is the "Starting up" / "No reading yet" branch, and
	 * the density chips and headings that are built once in the constructor rather than
	 * from a model.
	 */
	@Test
	public void noLabelBeforeTheFirstReadingIsTooCloseToItsBackground()
	{
		assertReadable(new LivelyCitiesPanel(plugin(config)));
	}

	/**
	 * The login-screen reading: nine real city cards, on and off, an empty
	 * overrides section, and both helper paragraphs.
	 */
	@Test
	public void noLabelOnALoggedOutPanelIsTooCloseToItsBackground()
	{
		config.disableOnly(City.FALADOR);
		LivelyCitiesPanel panel = new LivelyCitiesPanel(plugin(config));

		panel.onActivate();
		drain();

		assertReadable(panel);
	}

	/**
	 * A live, in-world reading with somebody hidden and somebody else muted, so the
	 * override cards' subtitle and both restore actions are on screen alongside the
	 * "on screen" figures the now-card reports.
	 */
	@Test
	public void noLabelWithLiveDataAndOverridesIsTooCloseToItsBackground()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition hidden = regions.citizen(12852, 3225, 3360, 0);
		EntityDefinition mutedAndHidden = regions.talker(12852, 3226, 3360, "Busy today.");

		config.overrides().hide(hidden);
		config.overrides().hide(mutedAndHidden);
		config.overrides().mute(mutedAndHidden);

		LivelyCitiesPanel panel = new LivelyCitiesPanel(plugin(config));

		java.util.EnumMap<City, Integer> active = new java.util.EnumMap<>(City.class);
		active.put(City.VARROCK, 5);

		panel.accept(PanelModel.of(IN_VARROCK, new SceneCensus(5, 12, 3, 1, active), config,
			uuids(hidden, mutedAndHidden), uuids(mutedAndHidden),
			new CitizenDirectory(regions)));
		drain();

		assertReadable(panel);
	}

	// --- the guard itself --------------------------------------------------------

	private static void assertReadable(Container root)
	{
		List<String> failures = new ArrayList<>();

		for (Component component : all(root))
		{
			if (!(component instanceof JLabel) || !component.isVisible())
			{
				continue;
			}

			JLabel label = (JLabel) component;
			String text = label.getText();
			if (text == null || text.isEmpty())
			{
				continue;
			}

			Color background = effectiveBackground(label);
			double ratio = contrast(label.getForeground(), background);
			double minimum = label.isOpaque() ? CHIP_MIN_CONTRAST : TEXT_MIN_CONTRAST;

			if (ratio < minimum)
			{
				failures.add(String.format(
					"\"%s\" reads %.2f:1 (needs %.1f:1) — foreground %s on background %s",
					text, ratio, minimum, label.getForeground(), background));
			}
		}

		assertTrue("label(s) too close to their background:\n" + String.join("\n", failures),
			failures.isEmpty());
	}

	/**
	 * @return the colour actually painted behind {@code component} — its own, if it is
	 * opaque and paints one itself, otherwise the nearest ancestor's. A plain
	 * {@code JLabel} is not opaque by default and paints nothing, so what a user sees
	 * behind it is whichever {@code JPanel} it sits on, and every panel in this file sets
	 * its own background explicitly.
	 */
	private static Color effectiveBackground(Component component)
	{
		for (Component at = component; at != null; at = at.getParent())
		{
			if (at instanceof JComponent && ((JComponent) at).isOpaque())
			{
				return at.getBackground();
			}
		}

		throw new AssertionError("no opaque ancestor carries a background for " + component);
	}

	private static double contrast(Color foreground, Color background)
	{
		double lighter = Math.max(relativeLuminance(foreground), relativeLuminance(background));
		double darker = Math.min(relativeLuminance(foreground), relativeLuminance(background));
		return (lighter + 0.05) / (darker + 0.05);
	}

	/** The WCAG 2 relative-luminance formula, straight off the spec. */
	private static double relativeLuminance(Color colour)
	{
		return 0.2126 * channel(colour.getRed())
			+ 0.7152 * channel(colour.getGreen())
			+ 0.0722 * channel(colour.getBlue());
	}

	private static double channel(int value)
	{
		double normalised = value / 255.0;
		return normalised <= 0.03928
			? normalised / 12.92
			: Math.pow((normalised + 0.055) / 1.055, 2.4);
	}

	// --- walking and driving the panel, trimmed from LivelyCitiesPanelTest -----------

	private LivelyCitiesPlugin plugin(FakeConfig config)
	{
		LivelyCitiesPlugin plugin = new LivelyCitiesPlugin();
		plugin.config = config;
		plugin.configWriter = config.writer();
		plugin.overrides = config.overrides();
		plugin.directory = directory;
		return plugin;
	}

	private static Set<UUID> uuids(EntityDefinition... definitions)
	{
		Set<UUID> out = new java.util.LinkedHashSet<>();
		for (EntityDefinition definition : definitions)
		{
			out.add(definition.getUuid());
		}
		return out;
	}

	private static void collect(Container root, List<Component> into)
	{
		for (Component child : root.getComponents())
		{
			into.add(child);
			if (child instanceof Container)
			{
				collect((Container) child, into);
			}
		}
	}

	private static List<Component> all(Container root)
	{
		List<Component> found = new ArrayList<>();
		collect(root, found);
		return found;
	}

	/** {@link LivelyCitiesPanel#accept} hops to Swing; this waits for that hop to land. */
	private static void drain()
	{
		try
		{
			SwingUtilities.invokeAndWait(() ->
			{
			});
		}
		catch (Exception e)
		{
			throw new AssertionError("the Swing queue never drained", e);
		}
	}
}

package com.matthewmariner.livelycities;

import com.matthewmariner.livelycities.data.EntityRecord;
import com.matthewmariner.livelycities.data.PointRecord;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Thinning has to be proportional, deterministic, and nested. Each of those is a
 * separate way for it to be quietly wrong.
 */
public class CrowdDensityTest
{
	private static final int REGION = 12853;

	/**
	 * The bucket arithmetic, pinned directly on the hash rather than through a
	 * uuid, so the boundaries are exact.
	 *
	 * <p>The negative cases are the point. Half of all 64-bit hashes are negative,
	 * and {@code hash % 100 < keepPercent} is true for <i>every</i> negative hash
	 * — which would keep half the roster whatever the dial said, and would look
	 * plausible in a proportion test tuned to a 66% level.
	 */
	@Test
	public void theBucketIsAFloorModSoNegativeHashesAreNotAllKept()
	{
		assertTrue("bucket 0", CrowdDensity.SPARSE.keeps(0L));
		assertTrue("bucket 32 is the last SPARSE keeps", CrowdDensity.SPARSE.keeps(32L));
		assertFalse("bucket 33 is the first it drops", CrowdDensity.SPARSE.keeps(33L));
		assertTrue("bucket 65 is the last NORMAL keeps", CrowdDensity.NORMAL.keeps(65L));
		assertFalse("bucket 66 is the first it drops", CrowdDensity.NORMAL.keeps(66L));

		// floorMod(-1, 100) is 99; the remainder operator would give -1.
		assertFalse("a hash of -1 lands in bucket 99, not bucket -1",
			CrowdDensity.SPARSE.keeps(-1L));
		assertFalse(CrowdDensity.NORMAL.keeps(-1L));
		assertFalse(CrowdDensity.SPARSE.keeps(-101L));
		assertFalse(CrowdDensity.SPARSE.keeps(Long.MIN_VALUE + 91L));
		// And a negative hash in a low bucket is still kept.
		assertTrue("floorMod(-200, 100) is 0", CrowdDensity.SPARSE.keeps(-200L));
	}

	@Test
	public void fullKeepsEveryoneWhateverTheHash()
	{
		assertTrue(CrowdDensity.FULL.keeps(0L));
		assertTrue(CrowdDensity.FULL.keeps(99L));
		assertTrue(CrowdDensity.FULL.keeps(-1L));
		assertTrue(CrowdDensity.FULL.keeps(Long.MIN_VALUE));
		assertTrue(CrowdDensity.FULL.keeps(Long.MAX_VALUE));
		assertEquals(100, CrowdDensity.FULL.getKeepPercent());
	}

	/**
	 * {@link CrowdDensity#CROWDED} keeps the whole authored roster too, and is the
	 * only level that admits {@link CitizenEcho}'s derived citizens.
	 *
	 * <p>Both halves matter and they are different claims. "Keeps everyone" is what
	 * makes the level purely additive: it is {@link CrowdDensity#FULL} plus something,
	 * never a different crowd. "Only one" is what makes the feature opt-in — a second
	 * level that admitted echoes would mean a user who had chosen SPARSE for a quieter
	 * city could be handed extra people.
	 */
	@Test
	public void crowdedKeepsEveryoneAndIsTheOnlyLevelThatAdmitsEchoes()
	{
		assertTrue(CrowdDensity.CROWDED.keeps(0L));
		assertTrue(CrowdDensity.CROWDED.keeps(99L));
		assertTrue(CrowdDensity.CROWDED.keeps(-1L));
		assertTrue(CrowdDensity.CROWDED.keeps(Long.MIN_VALUE));
		assertTrue(CrowdDensity.CROWDED.keeps(Long.MAX_VALUE));
		assertEquals("the thinning percentage is 100 — the extra people are not a percentage",
			100, CrowdDensity.CROWDED.getKeepPercent());

		assertTrue(CrowdDensity.CROWDED.includesEchoes());
		for (CrowdDensity density : CrowdDensity.values())
		{
			if (density != CrowdDensity.CROWDED)
			{
				assertFalse(density + " must not admit derived citizens", density.includesEchoes());
			}
		}
	}

	/**
	 * The default is unchanged, and that is the opt-in.
	 *
	 * <p>A new level at the top of the enum is one {@code @ConfigItem} default away
	 * from being on for everybody who has never touched the dial — including the
	 * users who never asked for extra citizens. RuneLite serialises an enum config
	 * value by name, so a profile with no {@code crowdDensity} key falls through to
	 * this method.
	 */
	@Test
	public void theDefaultIsStillFullSoTheExtraCitizensAreOptIn()
	{
		assertEquals(CrowdDensity.FULL, new FakeConfig().crowdDensity());
		assertFalse(new FakeConfig().crowdDensity().includesEchoes());
	}

	/**
	 * Turning the dial up must only ever add people. It falls out of comparing one
	 * bucket against a rising threshold — but a version that hashed the uuid
	 * together with the level would pass a proportion test and swap the whole
	 * crowd for a different one on every change.
	 */
	@Test
	public void turningTheDialUpOnlyEverAddsPeople()
	{
		List<UUID> uuids = shippedUuids();

		Set<UUID> sparse = kept(CrowdDensity.SPARSE, uuids);
		Set<UUID> normal = kept(CrowdDensity.NORMAL, uuids);
		Set<UUID> full = kept(CrowdDensity.FULL, uuids);
		Set<UUID> crowded = kept(CrowdDensity.CROWDED, uuids);

		assertTrue("everyone sparse keeps, normal keeps too", normal.containsAll(sparse));
		assertTrue("and everyone normal keeps, full keeps too", full.containsAll(normal));
		assertTrue("and everyone full keeps, crowded keeps too", crowded.containsAll(full));
		assertEquals(uuids.size(), full.size());
		assertEquals("crowded adds people, it never swaps them", uuids.size(), crowded.size());
		assertTrue("the levels have to actually differ", sparse.size() < normal.size());
	}

	/**
	 * The same uuid always gets the same answer, and the answer comes from the
	 * uuid's <i>value</i> rather than from the object.
	 *
	 * <p>Parsing the string twice is what makes this a real test: identity hashing
	 * or a per-instance {@code Random} would give two freshly-parsed UUIDs
	 * different verdicts, and that is exactly the bug — a crowd that changes
	 * membership every time the wrapper cache is rebuilt.
	 */
	@Test
	public void theVerdictComesFromTheUuidsValueNotTheObject()
	{
		String raw = "44444444-4444-4444-8444-444444444444";
		long first = definitionWithUuid(raw).stableHash();
		long second = definitionWithUuid(raw).stableHash();

		assertEquals("two definitions built from the same uuid must hash the same",
			first, second);
		assertNotEquals("and a different uuid must hash differently",
			first, definitionWithUuid("55555555-5555-4555-8555-555555555555").stableHash());

		for (CrowdDensity density : CrowdDensity.values())
		{
			assertEquals(density + " must agree with itself across instances",
				density.keeps(first), density.keeps(second));
		}
	}

	/**
	 * An anchor value, so the hash cannot be changed by accident.
	 *
	 * <p>Not a test of the arithmetic — the test above covers that — but of its
	 * <i>stability</i>. The whole promise of this feature is that the same people
	 * are kept across sessions, and a "harmless" tweak to the mixing function
	 * reshuffles every thinned city on everyone's install. Changing this number on
	 * purpose is fine; changing it without noticing is what this catches.
	 */
	@Test
	public void theHashIsPinnedSoAThinnedCityStaysTheSameCityAcrossVersions()
	{
		assertEquals(-6027941731549618587L,
			definitionWithUuid("44444444-4444-4444-8444-444444444444").stableHash());
		assertEquals(7473597206274394059L,
			definitionWithUuid("55555555-5555-4555-8555-555555555555").stableHash());
	}

	/**
	 * The proportion, on enough samples that the sampling noise is smaller than any
	 * bug worth having.
	 *
	 * <p>Ten thousand uuids: for a 33% level the standard deviation of the kept
	 * share is under half a percentage point, so a ±3 point band is six sigma. A
	 * filter that keeps everyone, keeps nobody, or ignores the level cannot fit
	 * inside it.
	 */
	@Test
	public void thinningKeepsRoughlyTheAdvertisedShareOfALargeRoster()
	{
		// A fixed seed, so this is the same ten thousand uuids on every run. The
		// determinism the feature promises is asserted above; this is about spread.
		Random random = new Random(20260823L);
		List<UUID> uuids = new ArrayList<>(10_000);
		for (int i = 0; i < 10_000; i++)
		{
			uuids.add(new UUID(random.nextLong(), random.nextLong()));
		}

		for (CrowdDensity density : CrowdDensity.values())
		{
			double share = 100.0 * kept(density, uuids).size() / uuids.size();
			assertTrue(density + " kept " + String.format("%.1f", share) + "% of "
					+ uuids.size() + ", expected about " + density.getKeepPercent() + "%",
				Math.abs(share - density.getKeepPercent()) <= 3.0);
		}
	}

	/**
	 * And the same thing on the roster that actually ships, where 184 samples make
	 * the band much wider — one standard deviation is already ~3.5 points at the
	 * sparse level. Loose on purpose: what this catches is the dataset's uuids
	 * clustering pathologically, not a small deviation.
	 */
	@Test
	public void thinningIsNotPathologicalOnTheShippedRoster()
	{
		List<UUID> uuids = shippedUuids();
		assertEquals("the whole shipped roster", 311, uuids.size());

		for (CrowdDensity density : CrowdDensity.values())
		{
			double share = 100.0 * kept(density, uuids).size() / uuids.size();
			assertTrue(density + " kept " + String.format("%.1f", share) + "% of the shipped "
					+ uuids.size() + ", expected about " + density.getKeepPercent() + "%",
				Math.abs(share - density.getKeepPercent()) <= 12.0);
		}
	}

	@Test
	public void theLabelsAreWhatTheConfigPanelWillShow()
	{
		assertEquals("Crowded", CrowdDensity.CROWDED.toString());
		assertEquals("Full", CrowdDensity.FULL.toString());
		assertEquals("Normal", CrowdDensity.NORMAL.toString());
		assertEquals("Sparse", CrowdDensity.SPARSE.toString());

		// Declaration order is dropdown order, densest first.
		assertEquals(0, CrowdDensity.CROWDED.ordinal());
		assertEquals(CrowdDensity.values().length - 1, CrowdDensity.SPARSE.ordinal());
	}

	private static Set<UUID> kept(CrowdDensity density, List<UUID> uuids)
	{
		Set<UUID> out = new HashSet<>();
		for (UUID uuid : uuids)
		{
			if (density.keeps(hash(uuid)))
			{
				out.add(uuid);
			}
		}
		return out;
	}

	/**
	 * The same value {@link EntityDefinition#stableHash()} produces, reached
	 * through a definition rather than reimplemented — a local copy of the mixer
	 * here would agree with a broken one there.
	 */
	private static long hash(UUID uuid)
	{
		return definitionWithUuid(uuid.toString()).stableHash();
	}

	private static List<UUID> shippedUuids()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<UUID> uuids = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			for (EntityDefinition entity : region.getEntities())
			{
				uuids.add(entity.getUuid());
			}
		}

		return uuids;
	}

	private static EntityDefinition definitionWithUuid(String uuid)
	{
		EntityRecord record = new EntityRecord();
		record.entityType = "StationaryCitizen";
		record.uuid = uuid;
		record.modelIds = new int[]{217};

		PointRecord point = new PointRecord();
		point.x = 3238;
		point.y = 3425;
		point.plane = 0;
		record.worldLocation = point;

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		return definition;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * {@link CrowdDensity#CROWDED} through the scene: what the dial actually does to
 * the client's registered-object list.
 *
 * <p>{@link CitizenEchoTest} covers the derivation offline. This covers the five
 * things that can only go wrong once the wrappers exist — the opt-in, the placement
 * gate, the object cap, the per-citizen hide, and teardown — because every one of
 * them is a claim about {@code EntityScene}'s passes rather than about
 * {@code CitizenEcho}'s arithmetic.
 *
 * <p>Regions 12852 and 12853 again, for the reason {@code EntitySceneTest} gives:
 * they are Varrock, and they are where the shipped dataset is densest.
 */
public class CrowdedSceneTest
{
	private static final int VARROCK_SOUTH = 12852;
	private static final int VARROCK_NORTH = 12853;

	/**
	 * Varrock's east-gate road: 13109, x 3264..3327, y 3392..3455. The northern
	 * edge of a region a city really does claim.
	 */
	private static final int VARROCK_EAST_GATE_ROAD = 13109;

	/**
	 * The region immediately north of it, y 3456..3519 — the Lumber Yard's square.
	 * No city claims it and no region file ships for it, which is exactly why
	 * echoes can hide there.
	 *
	 * <p>It is unclaimed for a reason worth knowing: it shipped as its own
	 * "Lumber Yard" checkbox over one citizen until the nine-city cut on
	 * 2026-08-24 removed it. So this is not a hypothetical square picked off a
	 * map — it is a real hole the cut opened directly against a surviving city.
	 */
	private static final int UNCLAIMED_NORTH_OF_THE_EAST_GATE = 13110;

	private static final WorldPoint PLAYER = new WorldPoint(3225, 3360, 0);

	private FakeClient client;
	private FakeRegions regions;
	private FakeConfig config;
	private EntityScene scene;

	@Before
	public void setUp()
	{
		// A warm NPC archive: two of the tests below spawn the real dataset, which
		// includes one citizen dressed from an npcAppearanceId. An unregistered id
		// throws, exactly as the real client does, so without this that citizen
		// silently fails to spawn and every crowd count here comes out one short.
		client = new FakeClient().withShippedNpcAppearances();
		regions = new FakeRegions();
		config = new FakeConfig();
		scene = new EntityScene(client, regions, config, config.overrides());
	}

	// --- The opt-in -----------------------------------------------------------

	/**
	 * The whole promise of "purely additive and opt-in": {@link CrowdDensity#FULL}
	 * has to still be exactly the authored set.
	 *
	 * <p>The echo wrappers exist at FULL — {@code EntityScene} builds them whatever
	 * the dial says, so that they inherit eviction and teardown for free — so this
	 * asserts on what the client is holding, not on what is in scope. Those are the
	 * two halves that a "gate it at build time instead" version would conflate.
	 */
	@Test
	public void fullShowsEveryAuthoredCitizenAndNotOneEcho()
	{
		regions.file(VARROCK_SOUTH, regions.recolouredCrowd(VARROCK_SOUTH, 3218, 3350, 6, 6));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);

		assertEquals("every authored citizen", 6, scene.countActiveAuthored());
		assertEquals("and nothing else at all", 0, scene.countActiveEchoes());
		assertEquals(6, client.registeredCount());

		assertEquals("the echoes are built and in scope, they are simply not wanted",
			12, scene.getEchoInScopeCount());
	}

	@Test
	public void crowdedKeepsEveryAuthoredCitizenAndAddsTheEchoesOnTop()
	{
		regions.file(VARROCK_SOUTH, regions.recolouredCrowd(VARROCK_SOUTH, 3218, 3350, 6, 6));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		int authoredAtFull = client.registeredCount();

		config.setCrowdDensity(CrowdDensity.CROWDED);
		VisibilityPasses.settle(scene, PLAYER, view);

		assertEquals("not one authored citizen may be lost on the way up",
			authoredAtFull, scene.countActiveAuthored());
		assertEquals(12, scene.countActiveEchoes());
		assertEquals(18, client.registeredCount());
	}

	/**
	 * Turning the dial back down has to deactivate the echoes on the click, not
	 * merely stop new ones appearing — the same requirement the city checkboxes have,
	 * answered by the same "what is not wanted is despawned" rule.
	 */
	@Test
	public void turningTheDialBackDownDeactivatesTheEchoesAndLeavesTheCitizens()
	{
		regions.file(VARROCK_SOUTH, regions.recolouredCrowd(VARROCK_SOUTH, 3218, 3350, 4, 3));
		config.setCrowdDensity(CrowdDensity.CROWDED);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals(8, scene.countActiveEchoes());

		config.setCrowdDensity(CrowdDensity.FULL);
		scene.onSettingsChanged(PLAYER, view);

		assertEquals("the echoes go away on the click", 0, scene.countActiveEchoes());
		assertEquals("and the citizens stay", 4, scene.countActiveAuthored());
		assertEquals("with their wrappers still cached, ready to come back",
			1, scene.getCachedRegionCount());
	}

