	/**
	 * <b>Unticking a city takes its echoes with it even when an echo has stepped over
	 * a border into a region no city claims.</b>
	 *
	 * <p>{@link City#isEnabled} answers {@code true} for an unclaimed region on purpose
	 * — that is what lets a region file ship one commit before its checkbox — so an
	 * echo judged by its own tile went through that door: three of Piscatoris's echoes
	 * used to stand in region 9271, which no city claimed and which shipped no file,
	 * and unticking Piscatoris left them standing in the empty fields south of the
	 * village. They are judged by their source's city now, so they go when it goes and
	 * come back when it comes back.
	 *
	 * <p><b>This used to run against the real dataset and no longer can.</b> The
	 * nine-city cut on 2026-08-24 removed Piscatoris, and with it the only place in the
	 * shipped data where an echo crossed into a region no city claims: all 184 echoes
	 * the surviving 27 regions seed now stand in a region their own city claims. That
	 * is a real reduction in what this test proves — a hand-built fixture rather than a
	 * live case — and it is stated here rather than absorbed, because the instruction
	 * this file used to carry ("if the dataset moved, find the new case rather than
	 * deleting this test") assumed a new case existed, and none does.
	 *
	 * <p>The geometry stays as close to the real thing as it can. The source is filed
	 * under 13109, a region {@link City#VARROCK} genuinely claims; the echo lands in
	 * 13110, which is genuinely unclaimed and genuinely ships no file — because the
	 * same cut deleted it. So the hole being exercised is one the cut actually opened,
	 * directly north of a surviving city, rather than an invented square.
	 */
	@Test
	public void untickingACityAlsoRemovesTheEchoesStandingInARegionNoCityClaims()
	{
		// The north edge of Varrock's east-gate road, and the unclaimed region
		// immediately north of it. Both have to be in the scene: scope membership is
		// keyed on the entity's own tile, so an echo standing in 13110 is only in
		// scope while 13110 is loaded.
		WorldPoint spot = new WorldPoint(3290, 3454, 0);
		regions.file(VARROCK_EAST_GATE_ROAD,
			regions.recoloured(VARROCK_EAST_GATE_ROAD, spot.getX(), spot.getY(), 6));
		config.setCrowdDensity(CrowdDensity.CROWDED);

		FakeWorldView view = FakeWorldView.around(
			spot, VARROCK_EAST_GATE_ROAD, UNCLAIMED_NORTH_OF_THE_EAST_GATE);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, spot, view);

		int strays = countActiveEchoesInUnclaimedRegions(scene);
		assertTrue("the fixture depends on an echo crossing into region "
				+ UNCLAIMED_NORTH_OF_THE_EAST_GATE + " — if the echo ring or the separation "
				+ "distance moves, re-site the source rather than deleting this test", strays > 0);
		assertTrue("and on its authored source being on screen too",
			scene.countActiveAuthored() > 0);
		assertNull("the region it stands in really is unclaimed",
			City.of(UNCLAIMED_NORTH_OF_THE_EAST_GATE));
		assertEquals("and the region its source is filed under really is claimed",
			City.VARROCK, City.of(VARROCK_EAST_GATE_ROAD));

		config.disableOnly(City.VARROCK);
		scene.onSettingsChanged(spot, view);

		assertEquals("unticking Varrock has to take everything derived from Varrock "
				+ "with it, wherever it ended up standing", 0, client.registeredCount());

		config.enable(City.VARROCK);
		scene.onSettingsChanged(spot, view);

		assertEquals("and ticking it again brings the same strays back",
			strays, countActiveEchoesInUnclaimedRegions(scene));
	}

	/**
	 * <b>The census credits a border-crossing echo to the card that governs it.</b>
	 *
	 * <p><b>This test exists because of a mutation.</b> Changing
	 * {@code EntityScene.census()} to key its per-city breakdown on
	 * {@link EntityDefinition#getTileRegionId()} instead of
	 * {@link EntityDefinition#getCityRegionId()} left all 565 tests green. The two
	 * differ for exactly one population — an echo standing over a region border — and
	 * every census fixture until now used authored citizens, for whom they are equal by
	 * construction. So "the panel's numbers are keyed on the checkbox" was a claim no
	 * test could tell from "the panel's numbers are keyed on the tile".
	 *
	 * <p>It matters because the two answers are visibly different on the card. Under the
	 * mutation this echo is credited to <i>no</i> city — 13110 is unclaimed — so Varrock's
	 * card would say fewer figures are up than are up, while unticking Varrock's checkbox
	 * would still take the figure away. A card whose number disagrees with what its own
	 * checkbox controls is worse than no number.
	 *
	 * <p>The fixture is the one two tests down, for the reason its javadoc gives: the
	 * nine-city cut left region 13110 unclaimed and file-less directly north of a
	 * surviving city, so this is a hole the dataset actually has rather than an invented
	 * square.
	 */
	@Test
	public void theCensusCreditsAnEchoAcrossABorderToTheCityThatGovernsIt()
	{
		WorldPoint spot = new WorldPoint(3290, 3454, 0);
		regions.file(VARROCK_EAST_GATE_ROAD,
			regions.recoloured(VARROCK_EAST_GATE_ROAD, spot.getX(), spot.getY(), 6));
		config.setCrowdDensity(CrowdDensity.CROWDED);

		FakeWorldView view = FakeWorldView.around(
			spot, VARROCK_EAST_GATE_ROAD, UNCLAIMED_NORTH_OF_THE_EAST_GATE);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, spot, view);

		int strays = countActiveEchoesInUnclaimedRegions(scene);
		assertTrue("the fixture depends on an echo crossing into region "
				+ UNCLAIMED_NORTH_OF_THE_EAST_GATE + " — if the echo ring or the separation "
				+ "distance moves, re-site the source rather than deleting this test", strays > 0);
		assertNull("and on that region genuinely being unclaimed, or the mutation this "
			+ "test was written for would be invisible", City.of(UNCLAIMED_NORTH_OF_THE_EAST_GATE));

		SceneCensus census = scene.census();
		assertTrue("something has to be on screen", census.getActive() > 0);
		assertEquals("every figure up — the stray echo included — is credited to the card "
				+ "whose checkbox switches it off",
			census.getActive(), census.activeIn(City.VARROCK));

		// And the two really are the same figures: unticking Varrock takes all of them,
		// which is what makes "credited to the card that governs it" a statement about
		// the same set rather than a coincidence of counts.
		config.disableOnly(City.VARROCK);
		scene.onSettingsChanged(spot, view);
		assertEquals(0, scene.census().getActive());
	}

	/**
	 * The other half of that rule, which is <b>not</b> being changed: an
	 * <i>authored</i> entity in a region no city claims still fails open.
	 *
	 * <p>{@code CityTest.aRegionNoCityClaimsIsStillShown} asserts it of the lookup;
	 * this asserts it of the scene, with every checkbox in the plugin unticked, because
	 * the fix above works by asking a different question of an echo and it would have
	 * been just as easy to answer it wrongly for everybody.
	 */
	@Test
	public void anAuthoredCitizenInARegionNoCityClaimsIsStillShownWithEveryCheckboxOff()
	{
		// Keldagrim: no region file, no City constant, and no plans for either.
		int unclaimed = 11422;
		assertNull("the fixture has to be genuinely unmapped", City.of(unclaimed));

		WorldPoint tile = new WorldPoint(2860, 10150, 0);
		assertEquals(unclaimed, RenderPolicy.regionIdOf(tile.getX(), tile.getY()));

		regions.file(unclaimed, regions.recoloured(unclaimed, tile.getX(), tile.getY(), 6));
		config.setCrowdDensity(CrowdDensity.CROWDED).disable(City.values());

		FakeWorldView view = FakeWorldView.around(tile, unclaimed);
		scene.syncRegions(view);
		scene.onGameTick(tile, view);

		assertEquals("an unmapped region fails open for the citizen a human placed there",
			1, scene.countActiveAuthored());
		assertEquals("and for the echoes it seeds, which answer to the same nothing",
			2, scene.countActiveEchoes());
	}

	/** The cull radius is the echo's own, measured from where the echo stands. */
	@Test
	public void anEchoBeyondTheCullRadiusIsDeactivatedLikeAnythingElse()
	{
		regions.file(VARROCK_SOUTH, regions.recoloured(VARROCK_SOUTH, 3225, 3355, 6));
		config.setCrowdDensity(CrowdDensity.CROWDED);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		assertEquals(2, scene.countActiveEchoes());

		WorldPoint away = new WorldPoint(3225, 3355 - RenderPolicy.DEFAULT_CULL_RADIUS - 5, 0);
		scene.updateVisibility(away, view);
		assertEquals(0, client.registeredCount());
	}

	/**
	 * How many echoes are on screen whose <i>own</i> tile is in a region no city
	 * claims — the population that used to be unswitchable-off.
	 */
	private static int countActiveEchoesInUnclaimedRegions(EntityScene scene)
	{
		int n = 0;
		for (LivelyEntity entity : scene.inScopeEntities())
		{
			EntityDefinition definition = entity.getDefinition();
			if (definition.isEcho()
				&& entity.isActive()
				&& City.of(definition.getTileRegionId()) == null)
			{
				n++;
			}
		}
		return n;
	}

	private static List<EntityDefinition> echoesInScope(EntityScene scene)
	{
		List<EntityDefinition> out = new ArrayList<>();
		for (LivelyEntity entity : scene.inScopeEntities())
		{
			if (entity.getDefinition().isEcho())
			{
				out.add(entity.getDefinition());
			}
		}
		return out;
	}

	/**
	 * Everything about an echo that a rebuild could plausibly change, as one string
	 * per uuid — so a diff names the field rather than saying "not equal".
	 */
	private static Map<UUID, String> fingerprint(List<EntityDefinition> echoes)
	{
		Map<UUID, String> out = new HashMap<>();
		for (EntityDefinition echo : echoes)
		{
			StringBuilder key = new StringBuilder();
			key.append("tile=").append(echo.getWorldLocation())
				.append(" facing=").append(echo.getOrientation())
				.append(" region=").append(echo.getTileRegionId())
				.append(" source=").append(echo.getEchoSourceUuid())
				.append(" authoredGround=").append(echo.isEchoOnAuthoredGround())
				.append(" find=");
			for (short colour : echo.getRecolorFind())
			{
				key.append(colour).append(',');
			}
			key.append(" replace=");
			for (short colour : echo.getRecolorReplace())
			{
				key.append(colour).append(',');
			}
			out.put(echo.getUuid(), key.toString());
		}
		return out;
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

/**
 * The developer-mode gate on {@link LivelyCitiesDevReportsPlugin#runCacheAudit()}
 * — <b>not</b> the audit's own logic, which {@code CacheIdAuditTest} covers
 * directly against {@link FakeClient} without needing a plugin at all.
 *
 * <p>Was {@code LivelyCitiesPluginCacheAuditTest}. The gate did not change; the class it
 * guards did. The trigger and the file both moved out of {@code src/main} and into the
 * test source set, so the shipped jar has no filesystem I/O in it — see
 * {@link LivelyCitiesDevReportsPlugin}'s javadoc for why. The gate is still checked, and
 * still checked as an AND, even though nothing a hub user runs can load this class:
 * {@code ./gradlew run} loads it too, and an ordinary dev session must not pay for a
 * full cache walk.
 *
 * <p>{@code ./gradlew test} must never run a real cache walk, so both halves —
 * {@code developerMode} and
 * {@link LivelyCitiesDevReportsPlugin#CACHE_AUDIT_SYSTEM_PROPERTY} — are proven
 * independently: either one missing has to mean nothing runs.
 *
 * <p>The game state is pinned away from {@code LOGGED_IN} throughout, matching the
 * client this plugin starts in; nothing in {@code startUp()} depends on it any more,
 * but a fixture that quietly stopped resembling the real thing is not worth the two
 * lines saved.
 */
public class DevReportsCacheAuditTest
{
	private FakeClient client;
	private InlineClientThread clientThread;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		client.setGameState(GameState.LOGIN_SCREEN);
		clientThread = new InlineClientThread();

		// Belt and braces: a leftover from a crashed prior run must not leak
		// into a test that asserts the gate is closed.
		System.clearProperty(LivelyCitiesDevReportsPlugin.CACHE_AUDIT_SYSTEM_PROPERTY);
	}

	@After
	public void tearDown()
	{
		System.clearProperty(LivelyCitiesDevReportsPlugin.CACHE_AUDIT_SYSTEM_PROPERTY);
	}

	@Test
	public void theAuditDoesNotRunWhenDeveloperModeIsOff()
	{
		System.setProperty(LivelyCitiesDevReportsPlugin.CACHE_AUDIT_SYSTEM_PROPERTY, "true");
		CountingPlugin plugin = plugin();
		plugin.developerMode = false;

		plugin.startUp();

		assertEquals("the system property alone must not be enough", 0, plugin.auditRuns);
	}

	@Test
	public void theAuditDoesNotRunWhenTheSystemPropertyIsUnset()
	{
		CountingPlugin plugin = plugin();
		plugin.developerMode = true;

		plugin.startUp();

		assertEquals("developerMode alone is true on every `./gradlew run` — "
				+ "this is what stops an ordinary dev session from paying for a full cache walk",
			0, plugin.auditRuns);
	}

	@Test
	public void theAuditRunsExactlyOnceWhenBothFlagsAreSet()
	{
		System.setProperty(LivelyCitiesDevReportsPlugin.CACHE_AUDIT_SYSTEM_PROPERTY, "true");
		CountingPlugin plugin = plugin();
		plugin.developerMode = true;

		plugin.startUp();

		assertEquals(1, plugin.auditRuns);
	}

	/**
	 * A default-constructed plugin — nobody has set {@code developerMode} — must
	 * behave exactly like the "off" case above. This is the scenario every other
	 * test in this project's suite is already in, since none of them wire the
	 * field: if this ever regressed to defaulting {@code true}, every other test
	 * would still pass and only a real client run would ever notice.
	 */
	@Test
	public void aPluginNobodyConfiguredNeverRunsTheAudit()
	{
		System.setProperty(LivelyCitiesDevReportsPlugin.CACHE_AUDIT_SYSTEM_PROPERTY, "true");
		CountingPlugin plugin = plugin();

		plugin.startUp();

		assertEquals(0, plugin.auditRuns);
	}

	/**
	 * The audit's report goes in {@code model-id-audit.txt}, and never in the frame
	 * report's file.
	 *
	 * <p>The mirror of {@code FrameTimingsTest}'s
	 * {@code theFrameReportIsWrittenUnderItsOwnNameAndNeverTheAudits}, and it exists for
	 * the same reason: {@link ReportWriter} takes the file name as an argument, so each
	 * of its two callers names its own constant and nothing else checks which one. This
	 * is the cheaper direction of the two failures — a frame report is one dev session
	 * away from being regenerated, while the audit needs a live cache — but an unasserted
	 * constant is an unasserted constant, and the two call sites are in one class now.
	 *
	 * <p>The audit itself runs for real here, against an empty {@link FakeRegions} and
	 * {@link FakeClient}: no cache is touched, the report comes out empty, and what is
	 * under test is the envelope rather than the contents.
	 */
	@Test
	public void theCacheAuditIsWrittenUnderItsOwnNameAndNeverTheFrameReports()
	{
		RecordingPlugin plugin = new RecordingPlugin();
		plugin.client = client;
		plugin.clientThread = clientThread;
		plugin.regionDataLoader = new FakeRegions();

		plugin.runCacheAudit();

		assertEquals("one report, written once",
			Collections.singletonList(LivelyCitiesDevReportsPlugin.CACHE_AUDIT_REPORT_FILE_NAME),
			plugin.fileNames);
		assertNotEquals("the cache id audit must never be written over the frame report's file",
			LivelyCitiesDevReportsPlugin.FRAME_REPORT_FILE_NAME, plugin.fileNames.get(0));
	}

	/**
	 * The plugin with the disk taken out but the audit left in — see the identically
	 * shaped {@code RecordingReporter} in {@code FrameTimingsTest}.
	 */
	private static final class RecordingPlugin extends LivelyCitiesDevReportsPlugin
	{
		private final List<String> fileNames = new ArrayList<>();

		@Override
		CompletableFuture<Void> writeReportAsync(
			File outputDir, String fileName, String text, String what)
		{
			fileNames.add(fileName);
			return CompletableFuture.completedFuture(null);
		}
	}

	private CountingPlugin plugin()
	{
		CountingPlugin plugin = new CountingPlugin();
		plugin.client = client;
		plugin.clientThread = clientThread;

		// startUp() also asks the stopwatch whether it is on, so that it can say so in
		// the log. A reporter with no plugin behind it would NPE there and fail every
		// test in this file for a reason that is not the gate under test.
		LivelyCitiesPlugin owner = new LivelyCitiesPlugin();
		owner.frameTimings = FrameTimings.off();
		plugin.livelyCities = owner;
		return plugin;
	}

	private static final class CountingPlugin extends LivelyCitiesDevReportsPlugin
	{
		int auditRuns;

		@Override
		void runCacheAudit()
		{
			auditRuns++;
		}
	}

	/**
	 * The real {@link ClientThread}, minus the thread — see the identical class
	 * in {@code LivelyCitiesPluginLifecycleTest} for why {@code invoke} running
	 * inline is faithful to every path the plugin uses it for.
	 */
	private static final class InlineClientThread extends ClientThread
	{
		@Override
		public void invoke(Runnable runnable)
		{
			runnable.run();
		}
	}
}

package com.matthewmariner.livelycities;

import com.matthewmariner.livelycities.data.EntityRecord;
import com.matthewmariner.livelycities.data.MergedObjectRecord;
import com.matthewmariner.livelycities.data.PointRecord;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Validation is exercised directly here, rather than only through JSON, so each
 * rule has its own named case and a failure points at one rule.
 */
public class EntityDefinitionTest
{
	private static final int REGION = 12853;

	/**
	 * Shared with {@link RenderPolicyTest}: builds a minimal valid definition.
	 */
	static EntityDefinition definition(String type, int x, int y, int plane, int[] modelIds)
	{
		EntityRecord record = record(type);
		record.worldLocation = point(x, y, plane);
		record.modelIds = modelIds;
		return EntityDefinition.fromRecord(record, REGION);
	}

	private static EntityRecord record(String type)
	{
		EntityRecord record = new EntityRecord();
		record.entityType = type;
		record.uuid = "44444444-4444-4444-8444-444444444444";
		record.name = "Test subject";
		record.worldLocation = point(3238, 3425, 0);
		record.modelIds = new int[]{235, 248};
		return record;
	}

	private static PointRecord point(Integer x, Integer y, Integer plane)
	{
		PointRecord p = new PointRecord();
		p.x = x;
		p.y = y;
		p.plane = plane;
		return p;
	}

	@Test
	public void nullRecordIsSkipped()
	{
		assertNull(EntityDefinition.fromRecord(null, REGION));
	}

	@Test
	public void unknownOrMissingEntityTypeIsSkipped()
	{
		assertNull(EntityDefinition.fromRecord(record("MaintenanceRobot"), REGION));
		assertNull(EntityDefinition.fromRecord(record(null), REGION));
		assertNull(EntityDefinition.fromRecord(record(""), REGION));
		// The dataset's four types all survive.
		assertNotNull(EntityDefinition.fromRecord(record("StationaryCitizen"), REGION));
		assertNotNull(EntityDefinition.fromRecord(record("WanderingCitizen"), REGION));
		assertNotNull(EntityDefinition.fromRecord(record("ScriptedCitizen"), REGION));
		assertNotNull(EntityDefinition.fromRecord(record("Scenery"), REGION));
	}

	@Test
	public void scriptedCitizensAreParsedAndKeepTheirType()
	{
		// L1 spawns them stationary, but the type must survive for L3.
		EntityDefinition scripted = EntityDefinition.fromRecord(record("ScriptedCitizen"), REGION);
		assertNotNull(scripted);
		assertEquals(EntityType.ScriptedCitizen, scripted.getType());
		assertTrue(scripted.getType().isCitizen());
	}

	@Test
	public void locationsThatCannotBePlacedAreSkipped()
	{
		EntityRecord noLocation = record("StationaryCitizen");
		noLocation.worldLocation = null;
		assertNull(EntityDefinition.fromRecord(noLocation, REGION));

		EntityRecord noPlane = record("StationaryCitizen");
		noPlane.worldLocation = point(3238, 3425, null);
		assertNull(EntityDefinition.fromRecord(noPlane, REGION));

		EntityRecord noX = record("StationaryCitizen");
		noX.worldLocation = point(null, 3425, 0);
		assertNull(EntityDefinition.fromRecord(noX, REGION));

		// A zero coordinate is the world origin, i.e. certainly not authored.
		EntityRecord originX = record("StationaryCitizen");
		originX.worldLocation = point(0, 3425, 0);
		assertNull(EntityDefinition.fromRecord(originX, REGION));

		EntityRecord highPlane = record("StationaryCitizen");
		highPlane.worldLocation = point(3238, 3425, 7);
		assertNull(EntityDefinition.fromRecord(highPlane, REGION));

		EntityRecord negativePlane = record("StationaryCitizen");
		negativePlane.worldLocation = point(3238, 3425, -1);
		assertNull(EntityDefinition.fromRecord(negativePlane, REGION));

		// Plane 3 is the top legal storey and must survive.
		EntityRecord topPlane = record("StationaryCitizen");
		topPlane.worldLocation = point(3238, 3425, 3);
		assertNotNull(EntityDefinition.fromRecord(topPlane, REGION));
	}

	@Test
	public void recordsWithNothingToRenderAreSkipped()
	{
		EntityRecord noModels = record("Scenery");
		noModels.modelIds = null;
		assertNull(EntityDefinition.fromRecord(noModels, REGION));

		EntityRecord emptyModels = record("Scenery");
		emptyModels.modelIds = new int[0];
		assertNull(EntityDefinition.fromRecord(emptyModels, REGION));

		EntityRecord unusableModels = record("Scenery");
		unusableModels.modelIds = new int[]{0, -12};
		assertNull(EntityDefinition.fromRecord(unusableModels, REGION));
	}

	@Test
	public void unusableModelIdsAreDroppedIndividually()
	{
		EntityRecord mixed = record("Scenery");
		mixed.modelIds = new int[]{0, 235, -1, 248};

		EntityDefinition definition = EntityDefinition.fromRecord(mixed, REGION);
		assertNotNull(definition);
		assertEquals(2, definition.getModelIds().length);
		assertEquals(235, definition.getModelIds()[0]);
		assertEquals(248, definition.getModelIds()[1]);
	}

	@Test
	public void recolourArraysAreTruncatedToMatchedPairs()
	{
		EntityRecord lopsided = record("StationaryCitizen");
		lopsided.modelRecolorFind = new int[]{11, 22, 33};
		lopsided.modelRecolorReplace = new int[]{99, 88};

		EntityDefinition definition = EntityDefinition.fromRecord(lopsided, REGION);
		assertNotNull(definition);
		assertEquals(2, definition.getRecolorFind().length);
		assertEquals(2, definition.getRecolorReplace().length);
		assertEquals((short) 11, definition.getRecolorFind()[0]);
		assertEquals((short) 22, definition.getRecolorFind()[1]);
		assertEquals((short) 99, definition.getRecolorReplace()[0]);
		assertEquals((short) 88, definition.getRecolorReplace()[1]);
	}

	@Test
	public void oneSidedRecolourArraysYieldNoPairs()
	{
		EntityRecord findOnly = record("StationaryCitizen");
		findOnly.modelRecolorFind = new int[]{11, 22};
		findOnly.modelRecolorReplace = null;

		EntityDefinition definition = EntityDefinition.fromRecord(findOnly, REGION);
		assertNotNull(definition);
		assertEquals(0, definition.getRecolorFind().length);
		assertEquals(0, definition.getRecolorReplace().length);
	}

	@Test
	public void colourValuesWrapIntoSignedShorts()
	{
		EntityRecord record = record("StationaryCitizen");
		// Both are real values from the shipped dataset, whose recolour range
		// runs 0..65313 — i.e. past what a signed short holds.
		record.modelRecolorFind = new int[]{43030, 25238};
		record.modelRecolorReplace = new int[]{59437, 10520};

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		// 43030 overflows a signed short; the client's recolor() takes exactly
		// the wrapped 16-bit value, so the negative must be preserved, not
		// clamped and not rejected.
		assertEquals((short) 43030, definition.getRecolorFind()[0]);
		assertEquals(-22506, definition.getRecolorFind()[0]);
		assertTrue(definition.getRecolorFind()[0] < 0);
		assertEquals((short) 59437, definition.getRecolorReplace()[0]);
		assertTrue(definition.getRecolorReplace()[0] < 0);
		// And a value that does fit is left alone.
		assertEquals(25238, definition.getRecolorFind()[1]);
		assertEquals(10520, definition.getRecolorReplace()[1]);
	}

	@Test
	public void orientationIsWrappedIntoOneRotation()
	{
		assertEquals(0, orientationOf(null));
		assertEquals(0, orientationOf(0));
		assertEquals(512, orientationOf(512));
		assertEquals(2047, orientationOf(2047));
		assertEquals(0, orientationOf(2048));
		assertEquals(512, orientationOf(2560));
		assertEquals(1792, orientationOf(-256));
		// A non-cardinal value is legal and must pass through untouched:
		// region 12338 ships a baseOrientation of 500.
		assertEquals(500, orientationOf(500));
	}

	@Test
	public void unknownAnimationNamesDegradeInsteadOfSkipping()
	{
		EntityRecord record = record("StationaryCitizen");
		record.idleAnimation = "PolishingTheBrasswork";
		record.moveAnimation = "HumanWalk";

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull("an unknown animation must not cost the entity", definition);
		assertNull(definition.getIdleAnimation());
		assertEquals(LivelyAnimation.HumanWalk, definition.getMoveAnimation());
	}

	@Test
	public void malformedScaleAndTranslateAreIgnoredWholesale()
	{
		EntityRecord shortVector = record("Scenery");
		shortVector.scale = new float[]{0.5f, 0.5f};
		shortVector.translate = new float[]{0.1f, 0.2f, 0.3f, 0.4f};

		EntityDefinition definition = EntityDefinition.fromRecord(shortVector, REGION);
		assertNotNull(definition);
		assertNull(definition.getScale());
		assertNull(definition.getTranslate());

		EntityRecord good = record("Scenery");
		good.scale = new float[]{-0.8f, -0.7f, -0.6f};
		EntityDefinition scaled = EntityDefinition.fromRecord(good, REGION);
		assertNotNull(scaled);
		assertNotNull(scaled.getScale());
		assertEquals(-0.7f, scaled.getScale()[1], 0.0001f);
	}

	@Test
	public void mergedObjectsAreFilteredAndRotationsNormalised()
	{
		EntityRecord record = record("StationaryCitizen");
		List<MergedObjectRecord> merged = new ArrayList<>();
		merged.add(mergedObject(7719, 2));
		merged.add(mergedObject(null, 1));      // no id -> dropped
		merged.add(mergedObject(0, 1));         // unusable id -> dropped
		merged.add(mergedObject(1234, null));   // missing rotation -> 0
		merged.add(mergedObject(5678, 6));      // 6 quarter-turns -> 2
		merged.add(mergedObject(9012, -3));     // negative -> 0
		merged.add(null);                       // null entry -> dropped
		record.mergedObjects = merged;

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		assertEquals(4, definition.getMergedObjects().size());
		assertEquals(7719, definition.getMergedObjects().get(0).getObjectId());
		assertEquals(2, definition.getMergedObjects().get(0).getRotations());
		assertEquals(1234, definition.getMergedObjects().get(1).getObjectId());
		assertEquals(0, definition.getMergedObjects().get(1).getRotations());
		assertEquals(5678, definition.getMergedObjects().get(2).getObjectId());
		assertEquals(2, definition.getMergedObjects().get(2).getRotations());
		assertEquals(9012, definition.getMergedObjects().get(3).getObjectId());
		assertEquals(0, definition.getMergedObjects().get(3).getRotations());
	}

	@Test
	public void missingMergedObjectsListIsEmptyNotNull()
	{
		EntityDefinition definition = EntityDefinition.fromRecord(record("Scenery"), REGION);
		assertNotNull(definition);
		assertEquals(Collections.emptyList(), definition.getMergedObjects());
	}

	@Test
	public void fileRegionIdWinsOverTheRecordsClaim()
	{
		EntityRecord record = record("StationaryCitizen");
		record.regionId = 99999;

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		assertEquals(REGION, definition.getRegionId());
	}

	/**
	 * The file name says how the entity was found; the tile says where it is.
	 * Those are different questions and the shipped data answers them
	 * differently, so both have to survive validation.
	 */
	@Test
	public void theTileDecidesWhichRegionTheEntityStandsIn()
	{
		// The shipped case: "Dark wizard" is authored in 12853.json and stands
		// at (3261, 3386), six tiles inside region 12852.
		EntityRecord misfiled = record("WanderingCitizen");
		misfiled.worldLocation = point(3261, 3386, 0);

		EntityDefinition definition = EntityDefinition.fromRecord(misfiled, REGION);
		assertNotNull("a misfiled entity is still an entity", definition);
		assertEquals(REGION, definition.getRegionId());
		assertEquals(12852, definition.getTileRegionId());

		// And they agree for a record filed where it stands.
		EntityDefinition home = EntityDefinition.fromRecord(record("StationaryCitizen"), REGION);
		assertNotNull(home);
		assertEquals(REGION, home.getRegionId());
		assertEquals(REGION, home.getTileRegionId());
	}

	@Test
	public void aWanderingCitizenKeepsItsBoxNormalisedAndInclusive()
	{
		EntityRecord record = record("WanderingCitizen");
		record.worldLocation = point(3238, 3425, 0);
		// Corners the wrong way round: the field names say bottom-left and
		// top-right, but nothing in the schema enforces it.
		record.wanderBoxBL = point(3242, 3429, 0);
		record.wanderBoxTR = point(3234, 3421, 0);

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		EntityDefinition.WanderBox box = definition.getWanderBox();
		assertNotNull(box);
		assertEquals(3234, box.getMinX());
		assertEquals(3242, box.getMaxX());
		assertEquals(3421, box.getMinY());
		assertEquals(3429, box.getMaxY());
		assertEquals("inclusive, so a 3234..3242 span is nine tiles", 9, box.getWidth());
		assertEquals(9, box.getHeight());
		assertEquals(0, box.getPlane());
		assertTrue(box.contains(3238, 3425));
		assertTrue("the corners are inside it", box.contains(3234, 3421) && box.contains(3242, 3429));
		assertFalse(box.contains(3233, 3425));
		assertFalse(box.contains(3238, 3430));
	}

	/**
	 * The one piece of geometry this class invents, and the reason it does.
	 *
	 * <p>The cull check measures from the citizen's authored tile, so a box that
	 * reaches further than {@link RenderPolicy#DATASET_OVERHANG_ALLOWANCE} would
	 * let a citizen walk past the edge of the loaded scene, where
	 * {@code LocalPoint.fromWorld} returns null and it simply stops being drawn.
	 * Clamping here makes that impossible for any dataset rather than merely
	 * untrue of this one — no shipped box needs it, which is what
	 * {@code RenderPolicyTest} asserts.
	 */
	@Test
	public void aWanderBoxReachingOutOfTheLoadedSceneIsClampedNotHonoured()
	{
		int allowance = RenderPolicy.DATASET_OVERHANG_ALLOWANCE;

		EntityRecord record = record("WanderingCitizen");
		record.worldLocation = point(3238, 3425, 0);
		record.wanderBoxBL = point(3238 - 100, 3425 - 100, 0);
		record.wanderBoxTR = point(3238 + 100, 3425 + 100, 0);

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		EntityDefinition.WanderBox box = definition.getWanderBox();
		assertNotNull("clamped, not dropped", box);

		assertEquals(3238 - allowance, box.getMinX());
		assertEquals(3238 + allowance, box.getMaxX());
		assertEquals(3425 - allowance, box.getMinY());
		assertEquals(3425 + allowance, box.getMaxY());
		assertFalse("the far corner must be out of reach",
			box.contains(3238 - allowance - 1, 3425));

		// And a box already inside the allowance is left exactly alone.
		EntityRecord modest = record("WanderingCitizen");
		modest.worldLocation = point(3238, 3425, 0);
		modest.wanderBoxBL = point(3236, 3423, 0);
		modest.wanderBoxTR = point(3240, 3427, 0);
		EntityDefinition untouched = EntityDefinition.fromRecord(modest, REGION);
		assertNotNull(untouched);
		assertNotNull(untouched.getWanderBox());
		assertEquals(3236, untouched.getWanderBox().getMinX());
		assertEquals(3240, untouched.getWanderBox().getMaxX());
	}

	/**
	 * Every way a box can be unusable degrades to a citizen standing still —
	 * never to a skipped record, and never to invented geometry.
	 */
	@Test
	public void anUnusableWanderBoxLeavesTheCitizenStationary()
	{
		// No box at all.
		EntityRecord noBox = record("WanderingCitizen");
		noBox.worldLocation = point(3238, 3425, 0);
		assertStationary(noBox);

		// Only one corner.
		EntityRecord halfBox = record("WanderingCitizen");
		halfBox.worldLocation = point(3238, 3425, 0);
		halfBox.wanderBoxBL = point(3236, 3423, 0);
		assertStationary(halfBox);

		// A corner with no coordinates.
		EntityRecord emptyCorner = record("WanderingCitizen");
		emptyCorner.worldLocation = point(3238, 3425, 0);
		emptyCorner.wanderBoxBL = point(null, 3423, 0);
		emptyCorner.wanderBoxTR = point(3240, 3427, 0);
		assertStationary(emptyCorner);

		// A box on another storey: that is not a walk, it is a fall.
		EntityRecord wrongPlane = record("WanderingCitizen");
		wrongPlane.worldLocation = point(3238, 3425, 0);
		wrongPlane.wanderBoxBL = point(3236, 3423, 1);
		wrongPlane.wanderBoxTR = point(3240, 3427, 1);
		assertStationary(wrongPlane);

		// The citizen standing outside its own box.
		EntityRecord outside = record("WanderingCitizen");
		outside.worldLocation = point(3238, 3425, 0);
		outside.wanderBoxBL = point(3200, 3400, 0);
		outside.wanderBoxTR = point(3210, 3410, 0);
		assertStationary(outside);

		// A single-tile box, which is a walk with nowhere to go.
		EntityRecord oneTile = record("WanderingCitizen");
		oneTile.worldLocation = point(3238, 3425, 0);
		oneTile.wanderBoxBL = point(3238, 3425, 0);
		oneTile.wanderBoxTR = point(3238, 3425, 0);
		assertStationary(oneTile);
	}

	/**
	 * Only wandering citizens get a box, however the record is decorated.
	 * ScriptedCitizens are stationary until a later phase runs their scripts, and
	 * a scripted citizen wandering at random would be worse than one standing
	 * still.
	 */
	@Test
	public void nothingButAWanderingCitizenGetsAWanderBox()
	{
		for (String type : new String[]{"StationaryCitizen", "ScriptedCitizen", "Scenery"})
		{
			EntityRecord record = record(type);
			record.worldLocation = point(3238, 3425, 0);
			record.wanderBoxBL = point(3236, 3423, 0);
			record.wanderBoxTR = point(3240, 3427, 0);

			EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
			assertNotNull(definition);
			assertNull(type + " must not wander", definition.getWanderBox());
		}
	}

	private static void assertStationary(EntityRecord record)
	{
		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull("an unusable wanderBox must not cost the record", definition);
		assertNull("and must not produce a box", definition.getWanderBox());
	}

	// --- npcAppearanceId and the cameo flag ----------------------------------

	/**
	 * A record with no {@code modelIds} but a plausible {@code npcAppearanceId}
	 * survives the gate, which used to skip anything with no models.
	 */
	@Test
	public void anNpcAppearanceIdIsEnoughOnItsOwnWithNoModelIds()
	{
		EntityRecord record = record("StationaryCitizen");
		record.modelIds = null;
		record.npcAppearanceId = 1798;

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);

		assertNotNull("an NPC appearance is a body", definition);
		assertEquals(1798, definition.getNpcAppearanceId());
		assertEquals("and it carries no raw model ids", 0, definition.getModelIds().length);
	}

	/**
	 * Neither is still a skip — and this is the case the old
	 * "no entity has an empty modelIds array" rule could not distinguish from the one
	 * above.
	 */
	@Test
	public void neitherModelIdsNorAnNpcAppearanceIdIsStillASkip()
	{
		EntityRecord empty = record("StationaryCitizen");
		empty.modelIds = new int[0];
		assertNull(EntityDefinition.fromRecord(empty, REGION));

		EntityRecord nulled = record("StationaryCitizen");
		nulled.modelIds = null;
		assertNull(EntityDefinition.fromRecord(nulled, REGION));

		// Non-positive ids are dropped first, so this is "no usable models" too.
		EntityRecord sentinels = record("StationaryCitizen");
		sentinels.modelIds = new int[]{0, -1};
		assertNull(EntityDefinition.fromRecord(sentinels, REGION));
	}

	/**
	 * An implausible {@code npcAppearanceId} is dropped rather than trusted — a
	 * pasted hashcode in that field must not reach {@code client.getNpcDefinition}.
	 *
	 * <p>Dropping it <i>degrades</i> rather than skipping, so a record that also has
	 * models still spawns from them; a record with nothing else left is skipped by the
	 * gate above, which is the same outcome as a record with no models at all.
	 */
	@Test
	public void anImplausibleNpcAppearanceIdIsDroppedAndTheModelIdsSurvive()
	{
		EntityRecord withModels = record("StationaryCitizen");
		withModels.npcAppearanceId = CacheIdPlausibility.MAX_PLAUSIBLE_ID + 1;
		EntityDefinition degraded = EntityDefinition.fromRecord(withModels, REGION);
		assertNotNull("a junk NPC id must not cost the record its models", degraded);
		assertEquals(0, degraded.getNpcAppearanceId());
		assertEquals(2, degraded.getModelIds().length);

		EntityRecord negative = record("StationaryCitizen");
		negative.npcAppearanceId = -1798;
		EntityDefinition alsoDegraded = EntityDefinition.fromRecord(negative, REGION);
		assertNotNull(alsoDegraded);
		assertEquals(0, alsoDegraded.getNpcAppearanceId());

		// Nothing left to build from, so it is skipped.
		EntityRecord only = record("StationaryCitizen");
		only.modelIds = null;
		only.npcAppearanceId = 0;
		assertNull(EntityDefinition.fromRecord(only, REGION));
	}

	/**
	 * When a record carries both, the NPC appearance wins — models and palette alike.
	 *
	 * <p>Documented on {@code EntityRecord.npcAppearanceId} and pinned here. The
	 * {@code modelIds} survive on the definition (nothing gains from erasing them)
	 * but {@code LivelyEntity} never builds them; {@code LivelyEntityTest} asserts
	 * that half, because "which field wins" is only observable at render time.
	 */
	@Test
	public void bothPresentMeansTheNpcAppearanceWinsAndTheRecordKeepsItsModelIds()
	{
		EntityRecord record = record("StationaryCitizen");
		record.modelIds = new int[]{235, 248};
		record.npcAppearanceId = 1798;
		record.modelRecolorFind = new int[]{1};
		record.modelRecolorReplace = new int[]{2};

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);

		assertNotNull(definition);
		assertEquals("the NPC id is what the renderer will use", 1798, definition.getNpcAppearanceId());
		assertEquals("the ignored modelIds are still readable, for the log line",
			2, definition.getModelIds().length);
	}

	@Test
	public void anAbsentCameoFlagMeansNotACameo()
	{
		EntityRecord absent = record("StationaryCitizen");
		assertFalse(EntityDefinition.fromRecord(absent, REGION).isCameo());

		EntityRecord explicitlyFalse = record("StationaryCitizen");
		explicitlyFalse.cameo = Boolean.FALSE;
		assertFalse(EntityDefinition.fromRecord(explicitlyFalse, REGION).isCameo());

		EntityRecord flagged = record("StationaryCitizen");
		flagged.cameo = Boolean.TRUE;
		assertTrue(EntityDefinition.fromRecord(flagged, REGION).isCameo());
	}

	/**
	 * Scenery cannot be a cameo. The flag's job is to keep player-shaped named
	 * likenesses behind an opt-in, and a crate is neither — a crate carrying it would
	 * be a crate that a checkbox nobody expects switches off. Same rule, and the same
	 * place, as a talking crate being silenced.
	 */
	@Test
	public void sceneryCannotBeACameoHoweverItIsFlagged()
	{
		EntityRecord crate = record("Scenery");
		crate.cameo = Boolean.TRUE;

		EntityDefinition definition = EntityDefinition.fromRecord(crate, REGION);

		assertNotNull("the flag is ignored, not fatal", definition);
		assertFalse(definition.isCameo());

		// All three citizen flavours may be.
		for (String type : new String[]{"StationaryCitizen", "WanderingCitizen", "ScriptedCitizen"})
		{
			EntityRecord citizen = record(type);
			citizen.cameo = Boolean.TRUE;
			assertTrue(type + " may be a cameo", EntityDefinition.fromRecord(citizen, REGION).isCameo());
		}
	}

	@Test
	public void aMissingOrBrokenUuidGetsOneGeneratedRatherThanSkipping()
	{
		EntityRecord noUuid = record("StationaryCitizen");
		noUuid.uuid = null;
		EntityDefinition generated = EntityDefinition.fromRecord(noUuid, REGION);
		assertNotNull(generated);
		assertNotNull(generated.getUuid());

		EntityRecord badUuid = record("StationaryCitizen");
		badUuid.uuid = "not-a-uuid";
		EntityDefinition recovered = EntityDefinition.fromRecord(badUuid, REGION);
		assertNotNull(recovered);
		assertNotNull(recovered.getUuid());
	}

	private static MergedObjectRecord mergedObject(Integer objectId, Integer rotations)
	{
		MergedObjectRecord m = new MergedObjectRecord();
		m.objectId = objectId;
		m.count90CCWRotations = rotations;
		return m;
	}

	private static int orientationOf(Integer raw)
	{
		EntityRecord record = record("StationaryCitizen");
		record.baseOrientation = raw;
		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		return definition.getOrientation();
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The teardown contract, asserted against a client that actually keeps its
 * registered-object list.
 *
 * <p>This file exists because of a mutation test: gutting {@code despawn()},
 * {@code deactivateAll()} and {@code shutdown()} to no-ops — a total
 * {@code RuneLiteObject} leak on every despawn, scene change and plugin
 * shutdown — left all 37 of the earlier tests green. Nothing in the suite
 * looked at whether anything was ever deactivated.
 *
 * <p>Region 12852 spans x 3200-3263, y 3328-3391; region 12853 is the square
 * directly above it, y 3392-3455. Those two are Varrock, and they are where the
 * shipped dataset is densest, so the fixtures use them rather than invented ids.
 */
public class EntitySceneTest
{
	private static final int VARROCK_SOUTH = 12852;
	private static final int VARROCK_NORTH = 12853;

	/**
	 * A second city, for the one claim a single-city fixture cannot make: that the
	 * census's per-city breakdown is a breakdown rather than the total under one
	 * heading.
	 */
	private static final int GRAND_EXCHANGE = 12598;

	/**
	 * Region 12851: directly south of {@link #VARROCK_SOUTH}, in no {@link City}'s list,
	 * and shipping no file. The fixture for "an unclaimed region fails open" — see
	 * {@code City}'s class javadoc for why that grace period exists.
	 */
	private static final int UNCLAIMED = 12851;

	/** In 12852, comfortably inside the cull radius of the crowds below. */
	private static final WorldPoint PLAYER = new WorldPoint(3225, 3360, 0);

	private FakeClient client;
	private FakeRegions regions;
	private FakeConfig config;
	private EntityScene scene;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		regions = new FakeRegions();
		config = new FakeConfig();
		scene = new EntityScene(client, regions, config, config.overrides());
	}

	@Test
	public void changingSceneDeactivatesEverythingItActivated()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 5));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals("the fixture should have spawned", 5, client.registeredCount());

		// Walk far enough that the scene covers a different region entirely.
		WorldPoint elsewhere = new WorldPoint(3600, 3200, 0);
		FakeWorldView moved = FakeWorldView.around(elsewhere, RenderPolicy.regionIdOf(3600, 3200));
		scene.syncRegions(moved);

		assertEquals("a scene change must leave nothing registered", 0, client.registeredCount());
	}

	@Test
	public void shutdownDeactivatesEverythingAndForgetsIt()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 4));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals(4, client.registeredCount());

		assertEquals("shutdown reports what it deactivated", 4, scene.shutdown());
		assertEquals("shutdown must leave nothing registered", 0, client.registeredCount());
		assertEquals("and must drop every wrapper", 0, scene.getCachedRegionCount());
		assertEquals("with nothing held back, because nothing needed holding",
			0, scene.getRetainedCount());
	}

	/**
	 * <b>The leak that lives in the gap between "we tried" and "it worked".</b>
	 * {@code LivelyEntity.despawn()} catches its own {@code RuntimeException}, marks the
	 * entity broken and returns {@code false} — so a client that threw out of
	 * {@code removeRuneLiteObject} leaves the object registered, and a teardown that then
	 * cleared {@code built} unconditionally dropped the last reference to it. The object
	 * goes on rendering, re-enabling the plugin cannot reach it, and nothing short of a
	 * client restart removes it.
	 *
	 * <p>That is the one artefact this plugin's teardown contract exists to make
	 * impossible, and the version of {@code shutdown()} this test replaced was worse than
	 * no check at all: it counted the leak, logged an error about it, and then discarded
	 * the only handle that could ever have undone it.
	 *
	 * <p>No realistic in-client trigger for the throw is known. That makes it latent, not
	 * acceptable — the promise is unconditional, so it has to hold against a client that
	 * misbehaves.
	 */
	@Test
	public void anEntityThatCouldNotBeDeactivatedIsKeptRatherThanLeaked()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 4));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals("the state has to be there before the teardown means anything",
			4, client.registeredCount());

		client.refusingDeactivation();
		assertEquals("nothing came off the screen", 0, scene.shutdown());

		assertEquals("the client still has them", 4, client.registeredCount());
		assertEquals("so something still holds the references to them",
			4, scene.getRetainedCount());
	}

	/** And a client that will not even say is treated as one that still has it. */
	@Test
	public void anEntityTheClientWillNotAnswerAboutIsKeptToo()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 3));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals(3, client.registeredCount());

		client.withThrowingRegistrationChecks();
		scene.shutdown();

		assertEquals("keeping them costs three pointers; dropping them costs three figures "
			+ "nobody can remove", 3, scene.getRetainedCount());
	}

	/**
	 * The other half of the bargain: a held wrapper is held so it can be <i>asked
	 * again</i>, and the ask has to actually happen. A list that only ever grows is its
	 * own kind of leak.
	 */
	@Test
	public void aHeldEntityIsDeactivatedAndReleasedOnceTheClientRecovers()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 2));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);

		client.refusingDeactivation();
		scene.shutdown();
		assertEquals(2, scene.getRetainedCount());
		assertEquals(2, client.registeredCount());

		// The plugin is toggled off a second time — or the client comes to its senses
		// while it is still off. Either way the held wrappers are the only route back.
		client.acceptingDeactivation();
		assertEquals("the second teardown gets them off the screen", 2, scene.shutdown());

		assertEquals("and the client is empty", 0, client.registeredCount());
		assertEquals("and nothing is held any more", 0, scene.getRetainedCount());
	}

	/**
	 * What must <i>not</i> survive a teardown that held something back: the region cache.
	 *
	 * <p>{@code ensureBuilt} returns early for a region id it already holds, so a held
	 * wrapper left filed under region 12852 would mean the next walk into Varrock rebuilds
	 * nothing there — one broken citizen where a hundred should be, for the rest of the
	 * session. The held wrappers come out of {@code built} for exactly that reason.
	 */
	@Test
	public void aTeardownThatHeldSomethingBackStillRebuildsTheRegionAfterwards()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 4));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);

		client.refusingDeactivation();
		scene.shutdown();
		assertEquals(4, scene.getRetainedCount());
		assertEquals("the region cache is empty whatever was held", 0, scene.getCachedRegionCount());

		// Enabled again, walked back into Varrock.
		client.acceptingDeactivation();
		FakeWorldView back = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(back);
		VisibilityPasses.settle(scene, PLAYER, back);

		assertEquals("every citizen the region file names is built again",
			4, scene.getInScopeCount());
		assertEquals("four fresh ones on screen, and the four the client would not release "
			+ "still on it — which is the situation rather than a regression: what the "
			+ "teardown bought is that those four can still be reached", 8, client.registeredCount());
		assertEquals("and they are still held", 4, scene.getRetainedCount());
	}

	@Test
	public void invalidateDeactivatesEverythingWithoutDroppingTheWrappers()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 3));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		assertEquals(3, client.registeredCount());

		assertEquals(3, scene.invalidate("LOADING"));
		assertEquals("LOADING must leave nothing registered", 0, client.registeredCount());
		assertEquals("but the models stay cached", 1, scene.getCachedRegionCount());
	}

	@Test
	public void aRegionLeavingScopeDeactivatesOnlyItsOwnEntities()
	{
		// One entity in each region, both within the cull radius of a player
		// standing near the border.
		WorldPoint border = new WorldPoint(3225, 3390, 0);
		regions.file(VARROCK_SOUTH, regions.citizen(VARROCK_SOUTH, 3225, 3385, 0));
		regions.file(VARROCK_NORTH, regions.citizen(VARROCK_NORTH, 3225, 3395, 0));

		FakeWorldView view = FakeWorldView.around(border, VARROCK_SOUTH, VARROCK_NORTH);
		scene.syncRegions(view);
		scene.updateVisibility(border, view);
		assertEquals(2, client.registeredCount());

		// The northern region drops out of the scene; the player has not moved
		// far enough for the southern one to.
		view.setMapRegions(VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(border, view);

		assertEquals("only the region still in scope may stay registered", 1, client.registeredCount());
		assertEquals(1, scene.getInScopeCount());
	}

	@Test
	public void theActiveCapIsNeverExceeded()
	{
		// A crowd half again as big as the cap, in 6-wide rows running north.
		int cap = RenderPolicy.MAX_ACTIVE_OBJECTS;
		List<EntityDefinition> crowd = regions.crowd(VARROCK_SOUTH, 3210, 3350, cap + 40);
		regions.file(VARROCK_SOUTH, crowd);

		// Standing at the north end: the cap keeps the northern rows.
		WorldPoint north = new WorldPoint(3212, 3372, 0);
		FakeWorldView view = FakeWorldView.around(north, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, north, view);

		assertEquals("the crowd is bigger than the cap", cap + 40, scene.getInScopeCount());
		assertEquals(cap, client.registeredCount());

		// Now walk to the south end. Every entity is still inside the cull
		// radius, so this swaps which of them the cap keeps — and it swaps them
		// against the iteration order, so the newly wanted entities come up
		// before the ones being dropped. That is exactly where a single fused
		// deactivate/activate loop transiently holds far more than the cap.
		//
		// It also takes more than one pass now: the southern rows have no models yet,
		// and RenderPolicy.MAX_MODEL_BUILDS_PER_PASS builds three of them per pass. That
		// does not weaken this test — the peak is sampled on every pass by FakeClient,
		// so a fused loop would be caught on whichever pass it over-registered on, and
		// there are now twenty-eight chances instead of one.
		WorldPoint south = new WorldPoint(3212, 3348, 0);
		VisibilityPasses.settle(scene, south, view);

		assertEquals(cap, client.registeredCount());
		assertTrue("the two positions must actually want different entities",
			client.peakRegistered() >= cap);
		assertEquals("the client must never hold more than the cap, mid-pass included",
			cap, client.peakRegistered());
	}

	// --- The build budget -----------------------------------------------------
	//
	// Measured, not supposed: 300 game ticks in Varrock put the visibility pass's p99
	// in the histogram's overflow bucket at >=11ms and its worst pass at 53.73ms,
	// against a pre-registered "a problem" line of 8ms. Individual builds were fine
	// (p99 1.50ms) — 371 of them simply landed across 331 passes, so walking into
	// Varrock square built dozens inside one game tick. These four tests are the fix:
	// a pass builds at most RenderPolicy.MAX_MODEL_BUILDS_PER_PASS models, nearest
	// first, and the rest arrive on later passes.

	@Test
	public void aPassBuildsNoMoreThanItsBudgetAndTheRestArriveOnLaterPasses()
	{
		int budget = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS;

		// Three full passes and a fourth with a single citizen left in it, so the last
		// pass is one where the budget is deliberately not spent — a version that built
		// exactly `budget` every pass regardless would overshoot the crowd there.
		int crowd = budget * 3 + 1;
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, crowd));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);

		for (int pass = 1; pass <= 4; pass++)
		{
			client.resetCounters();
			scene.updateVisibility(PLAYER, view);

			int outstanding = crowd - (pass - 1) * budget;
			int expected = Math.max(0, Math.min(budget, outstanding));

			assertEquals("pass " + pass + " may build " + expected + " model(s)",
				expected, client.mergeCalls());
			assertEquals("and a citizen whose build was held over must not have asked the "
					+ "client for its parts either — the whole point is that the work does "
					+ "not happen on this pass",
				expected, client.loadModelDataCalls());
			assertEquals("pass " + pass + ": everything built so far is on screen",
				Math.min(crowd, pass * budget), client.registeredCount());
		}

		// And once the crowd has arrived the budget costs nothing at all: a settled
		// scene builds nothing, so this is a brake on the burst rather than a
		// permanent tax on every pass.
		client.resetCounters();
		scene.updateVisibility(PLAYER, view);
		assertEquals(0, client.mergeCalls());
		assertEquals(crowd, client.registeredCount());
	}

	/**
	 * What waits is the far end of the crowd, never the citizen the player is standing
	 * next to.
	 *
	 * <p><b>The fixture files them furthest first</b>, so scope order and distance order
	 * disagree. That is the whole test: the budget is spent walking the sorted candidate
	 * list, and a version that spent it in the order the region file happens to list its
	 * records would build the three citizens eight tiles away and leave the one on the
	 * next tile waiting — which is the same "nearest first" property
	 * {@link RenderPolicy#MAX_ACTIVE_OBJECTS} has always had, and it has to survive.
	 */
	@Test
	public void theBudgetHoldsBackTheFarCitizensAndNeverTheNearOnes()
	{
		// Longer than the budget, or the assertion below is satisfied by a version with
		// no budget in it at all — every citizen would be near enough to build and
		// "distance <= budget" would be true for all of them. Sized off the constant so
		// a re-measurement that moves the cap cannot quietly hollow this out.
		List<EntityDefinition> line = new ArrayList<>();
		for (int distance = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS + 3; distance >= 1; distance--)
		{
			line.add(regions.citizen(
				VARROCK_SOUTH, PLAYER.getX(), PLAYER.getY() + distance, 0));
		}
		regions.file(VARROCK_SOUTH, line);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);

		assertEquals(RenderPolicy.MAX_MODEL_BUILDS_PER_PASS, client.registeredCount());

		for (EntityDefinition definition : line)
		{
			LivelyEntity wrapper = scene.wrapperFor(definition);
			assertNotNull(wrapper);

			int distance = RenderPolicy.tileDistance(PLAYER, definition.getWorldLocation());
			assertEquals("the citizen " + distance + " tile(s) away, filed at position "
					+ line.indexOf(definition) + " of " + line.size(),
				distance <= RenderPolicy.MAX_MODEL_BUILDS_PER_PASS, wrapper.isActive());
		}

		// The far ones are not lost, refused or broken — they simply have not arrived.
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals("every one of them gets there", line.size(), client.registeredCount());
		assertEquals("and none of them is latched out on the way", 0, scene.countBroken());
	}

	/**
	 * A build held over by the budget is not an attempt, and must not spend one.
	 *
	 * <p>The bug this exists to make impossible: {@link LivelyEntity#MAX_MODEL_ATTEMPTS}
	 * is three per scene load, spaced by {@link LivelyEntity#RETRY_BACKOFF_PASSES}, and
	 * it is there to stop a genuinely missing model producing a per-tick storm of cache
	 * calls. If waiting for the budget counted against it, a crowd four passes deep
	 * would leave its last citizens having "attempted" three times without the client
	 * ever being asked anything — and then unbuildable for the next twenty-five passes,
	 * on a warm cache, for no reason at all.
	 *
	 * <p>The fixture is sized so that only that failure mode can show up here: one more
	 * pass' worth of crowd than the retry budget has attempts in it.
	 */
	@Test
	public void aBuildHeldOverByTheBudgetIsNotOneOfTheEntitysModelAttempts()
	{
		int budget = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS;
		int passes = LivelyEntity.MAX_MODEL_ATTEMPTS + 1;
		int crowd = budget * passes;
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3218, 3352, crowd));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);

		for (int pass = 0; pass < passes; pass++)
		{
			scene.updateVisibility(PLAYER, view);
		}

		assertEquals("every citizen arrives inside " + passes + " passes, and none of them "
				+ "burns a retry attempt waiting its turn",
			crowd, client.registeredCount());
		assertEquals("the client is asked for each citizen's parts exactly once", crowd,
			client.loadModelDataCalls());
		assertEquals(0, scene.countBroken());
	}

	/**
	 * A cold model cache does not spend the build budget, because it did not build
	 * anything.
	 *
	 * <p>This is the reason the budget is charged when a build <i>completes</i> rather
	 * than when one is planned, and it is the difference between a fix and a regression.
	 * Charged on intent, the three nearest citizens on a cold login would hold the whole
	 * budget shut while doing no work, and — since a miss puts them into
	 * {@link LivelyEntity#RETRY_BACKOFF_PASSES} — would keep holding it for
	 * twenty-five passes with everybody behind them never asked at all. Charged on
	 * completion, a cold pass costs exactly what it always cost.
	 */
	@Test
	public void aColdModelCacheDoesNotSpendTheBuildBudget()
	{
		int crowd = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS * 3;
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, crowd));
		client.setCacheCold(true);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);

		assertEquals("a cold cache spawns nobody", 0, client.registeredCount());
		assertEquals("but every one of them is asked for, on the one pass: a build that "
				+ "did not happen must not spend a budget that bounds the cost of building",
			crowd, client.loadModelDataCalls());
		assertEquals("and nothing was built, so nothing was merged", 0, client.mergeCalls());

		// And when the cache warms, they all arrive — through the retry backoff and then
		// through the budget, which is the two mechanisms cooperating rather than one
		// starving the other.
		client.setCacheCold(false);
		for (int pass = 0; pass < LivelyEntity.RETRY_BACKOFF_PASSES; pass++)
		{
			scene.updateVisibility(PLAYER, view);
		}
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals("a warm cache must spawn what the cold one could not",
			crowd, client.registeredCount());
	}

	/**
	 * The crowd cap still counts objects and the build budget still counts builds, in
	 * the one fixture where both bind.
	 */
	@Test
	public void theCrowdCapBoundsWhatIsActiveAndTheBudgetOnlyBoundsHowFastItGetsThere()
	{
		int cap = RenderPolicy.MAX_ACTIVE_OBJECTS;
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3210, 3350, cap + 20));

