	/**
	 * The border-crossing wanderers, counted and named from the shipped files.
	 *
	 * <p>The claim below — and the one in {@link EntityScene}'s own javadoc — is the
	 * reason scope membership is decided from the authored tile rather than from where
	 * a citizen currently is. It was written as "six of the 63" and stayed that way
	 * through a dataset cut that took the roster to 39 wanderers, three of which still
	 * cross a border. Counted here so the next cut cannot leave it stale.
	 *
	 * <p>The box read is {@link EntityDefinition}'s validated one, i.e. the box the
	 * walk actually uses, clamp included — the question is where a citizen can end up
	 * standing, not what the file asked for.
	 */
	@Test
	public void exactlyThreeShippedWanderersPaceAcrossARegionBorder()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		int wanderers = 0;
		List<String> crossing = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);

			for (EntityDefinition entity : region.getEntities())
			{
				EntityDefinition.WanderBox box = entity.getWanderBox();
				if (box == null)
				{
					continue;
				}

				wanderers++;
				int home = RenderPolicy.regionIdOf(box.getMinX(), box.getMinY());
				if (home != RenderPolicy.regionIdOf(box.getMaxX(), box.getMinY())
					|| home != RenderPolicy.regionIdOf(box.getMinX(), box.getMaxY())
					|| home != RenderPolicy.regionIdOf(box.getMaxX(), box.getMaxY()))
				{
					crossing.add(entity.getName());
				}
			}
		}

		assertEquals("the shipped wander boxes", 63, wanderers);
		assertEquals("wanderers pacing across a region border", 3, crossing.size());
		assertTrue("and they are the three the comments name: " + crossing,
			crossing.contains("Ava") && crossing.contains("Dark wizard")
				&& crossing.contains("Zethrus"));
	}

	/**
	 * Three of the 63 shipped wanderers have boxes that straddle a region border.
	 * Membership is pinned to the authored tile and does not follow the walk, so
	 * neither of the two failure modes is reachable: the citizen cannot be listed
	 * twice, and it cannot be left registered once its home region goes.
	 *
	 * <p>The fixture is the real one: "Dark wizard" is filed under 12853, stands
	 * in 12852 and paces a box that spans both. Which three, and that there are
	 * three, is counted from the shipped files by
	 * {@link #exactlyThreeShippedWanderersPaceAcrossARegionBorder()}.
	 */
	@Test
	public void aWandererWhoseBoxCrossesARegionBorderIsNeitherDoubledNorOrphaned()
	{
		EntityDefinition darkWizard = regions.wanderer(
			VARROCK_NORTH,
			new WorldPoint(3261, 3386, 0),
			new WorldPoint(3258, 3382, 0),
			new WorldPoint(3261, 3395, 0),
			500);
		assertEquals("filed under the northern region", VARROCK_NORTH, darkWizard.getRegionId());
		assertEquals("but standing in the southern one", VARROCK_SOUTH, darkWizard.getTileRegionId());
		regions.file(VARROCK_NORTH, darkWizard);

		WorldPoint nearby = new WorldPoint(3255, 3388, 0);
		FakeWorldView view = FakeWorldView.around(nearby, VARROCK_NORTH, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(nearby, view);
		assertEquals(1, scene.getInScopeCount());
		assertEquals(1, client.registeredCount());
		assertEquals(1, scene.getWalkerCount());

		CitizenWalk walk = walkOf(scene, darkWizard);

		// Walk it for long enough to cross the border and come back several times.
		boolean visitedNorth = false;
		boolean visitedSouth = false;
		for (int tick = 0; tick < 600; tick++)
		{
			scene.onGameTick(nearby, view);
			scene.onFrame(view, 0.5f);

			assertEquals("one wrapper means one object, wherever it has walked to",
				1, client.registeredCount());
			assertEquals("and one entry in the frame list", 1, scene.getWalkerCount());
			assertEquals("and one entry in scope", 1, scene.getInScopeCount());

			WorldPoint tile = walk.currentTile();
			assertTrue("a wanderer must never leave its box", darkWizard.getWanderBox()
				.contains(tile.getX(), tile.getY()));

			int region = RenderPolicy.regionIdOf(tile.getX(), tile.getY());
			visitedNorth |= region == VARROCK_NORTH;
			visitedSouth |= region == VARROCK_SOUTH;
		}

		assertTrue("the fixture has to actually cross the border to prove anything",
			visitedNorth && visitedSouth);

		// Now the region it is filed under leaves the scene while the region it
		// stands in stays loaded. That is the one case where the region keeping
		// the wrapper alive and the region making it visible come and go
		// independently, and a walk across a border does not change it: the
		// wrapper survives its grace period and is then dropped, deactivated on
		// the way out, because eviction walks the cache rather than the in-scope
		// list.
		for (int change = 0; change <= EntityScene.EVICTION_GRACE_SCOPE_CHANGES; change++)
		{
			view.setMapRegions(VARROCK_SOUTH, 10000 + change);
			scene.syncRegions(view);
			scene.onGameTick(nearby, view);
			scene.onFrame(view, 0.5f);

			assertTrue("there is one wrapper, so there can never be two objects",
				client.registeredCount() <= 1);
			assertTrue(scene.getWalkerCount() <= 1);
			assertTrue(scene.getInScopeCount() <= 1);

			if (change == 0)
			{
				assertEquals("inside the grace period it is still the same one object",
					1, client.registeredCount());
			}
		}

		assertEquals("past the grace period the wrapper is gone", 0, scene.getCachedRegionCount());
		assertEquals("an evicted wanderer must not still be in scope", 0, scene.getInScopeCount());
		assertEquals("nor still registered", 0, client.registeredCount());
		assertEquals("nor still in the per-frame list", 0, scene.getWalkerCount());

		assertEquals("and shutdown finds nothing left over", 0, scene.shutdown());
		assertEquals(0, client.registeredCount());
	}

	/**
	 * The two clocks, told apart.
	 *
	 * <p>A frame must never move the logical tile, and a game tick must never do
	 * the visual interpolation. Asserting only that "something moved" would pass
	 * with both jobs in either handler — and the version with stepping in the
	 * frame handler is a citizen sprinting at the frame rate.
	 */
	@Test
	public void movementIsSteppedPerGameTickAndInterpolatedPerFrame()
	{
		EntityDefinition walker = regions.wanderer(
			VARROCK_SOUTH,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3220, 3350, 0),
			new WorldPoint(3230, 3360, 0),
			500);
		regions.file(VARROCK_SOUTH, walker);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);
		assertEquals(1, scene.getWalkerCount());

		// Tick until it is actually mid-step; the first destination is its own tile
		// so it stands still for the first interval.
		CitizenWalk walk = walkOf(scene, walker);
		for (int tick = 0; tick < 200 && !walk.isMoving(); tick++)
		{
			scene.onGameTick(PLAYER, view);
		}
		assertTrue("the fixture must get the citizen walking", walk.isMoving());

		WorldPoint tileBefore = walk.currentTile();
		FakeRuneLiteObject object = client.lastObject();

		scene.onFrame(view, 0f);
		int xAtStart = object.getX();
		int yAtStart = object.getY();

		// A hundred frames, no game tick.
		for (int frame = 1; frame <= 100; frame++)
		{
			scene.onFrame(view, frame / 100f);
		}

		assertEquals("frames must not step the logical tile", tileBefore, walk.currentTile());
		assertTrue("but they must move the drawn position",
			object.getX() != xAtStart || object.getY() != yAtStart);

		// Game ticks, no frames: only these may move the tile, and one of the next
		// few has to. The bound is the idle interval plus slack, so a step handler
		// that quietly did nothing could not hide inside it.
		int ticksToMove = 0;
		while (walk.currentTile().equals(tileBefore))
		{
			ticksToMove++;
			assertTrue("a game tick must be what steps the tile",
				ticksToMove <= CitizenWalk.IDLE_TICKS_BEFORE_NEW_DESTINATION + 2);
			scene.onGameTick(PLAYER, view);
		}

		// And the animation is never advanced by us — the client does that, once
		// per frame, for every registered object.
		assertEquals("advancing the animation is the client's job, not ours",
			0, object.tickCalls());
	}

	/**
	 * Interpolating a position must not churn the client's registered-object list.
	 *
	 * <p>{@code RuneLiteObject.setLocation} quietly deactivates and reactivates the
	 * object whenever the point's world view differs from the one the object
	 * already has. A hand-built {@code LocalPoint} carrying the wrong world view
	 * would therefore unregister and re-register every walking citizen on every
	 * frame — invisible in the active count, and expensive.
	 */
	@Test
	public void interpolatingAPositionDoesNotReRegisterTheObject()
	{
		EntityDefinition walker = regions.wanderer(
			VARROCK_SOUTH,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3221, 3351, 0),
			new WorldPoint(3229, 3359, 0),
			500);
		regions.file(VARROCK_SOUTH, walker);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);

		CitizenWalk walk = walkOf(scene, walker);
		for (int tick = 0; tick < 200 && !walk.isMoving(); tick++)
		{
			scene.onGameTick(PLAYER, view);
		}
		assertTrue("the fixture must get the citizen walking", walk.isMoving());

		client.resetCounters();
		for (int frame = 0; frame < 1000; frame++)
		{
			scene.onFrame(view, (frame % 30) / 30f);
		}

		assertEquals("a thousand frames of interpolation, no re-registration",
			0, client.registerCalls());
		assertEquals(0, client.removeCalls());
		assertEquals("and the citizen is still there", 1, client.registeredCount());
	}

	@Test
	public void aStationaryCrowdNeedsNoPerFrameWork()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3220, 3355, 6));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		scene.onGameTick(PLAYER, view);

		assertEquals(6, client.registeredCount());
		assertEquals("nothing here wanders, so the frame pass has an empty list",
			0, scene.getWalkerCount());
	}

	@Test
	public void aDeactivatedWandererStopsWalkingAndComesBackWhereItLeftOff()
	{
		EntityDefinition walker = regions.wanderer(
			VARROCK_SOUTH,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3221, 3351, 0),
			new WorldPoint(3229, 3359, 0),
			500);
		regions.file(VARROCK_SOUTH, walker);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		for (int tick = 0; tick < 40; tick++)
		{
			scene.onGameTick(PLAYER, view);
		}
		assertEquals(1, client.registeredCount());

		CitizenWalk walk = walkOf(scene, walker);
		WorldPoint whereItStopped = walk.currentTile();

		// Player walks out of range; the citizen is deactivated.
		WorldPoint away = new WorldPoint(3225, 3355 - RenderPolicy.DEFAULT_CULL_RADIUS - 5, 0);
		for (int tick = 0; tick < 40; tick++)
		{
			scene.onGameTick(away, view);
			scene.onFrame(view, 0.5f);
		}
		assertEquals(0, client.registeredCount());
		assertEquals("a citizen nobody can see does not walk", whereItStopped, walk.currentTile());
		assertEquals("and does not cost the frame pass anything either",
			0, scene.getWalkerCount());

		// Back in range: it picks up from the tile it was on, not from its
		// authored one.
		scene.onGameTick(PLAYER, view);
		assertEquals(1, client.registeredCount());
		assertEquals(1, scene.getWalkerCount());
	}

	@Test
	public void anInstancedSceneAlsoEmptiesThePerFrameList()
	{
		EntityDefinition walker = regions.wanderer(
			VARROCK_SOUTH,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3221, 3351, 0),
			new WorldPoint(3229, 3359, 0),
			500);
		regions.file(VARROCK_SOUTH, walker);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);
		assertEquals(1, scene.getWalkerCount());

		view.setInstance(true);
		scene.onGameTick(PLAYER, view);
		assertEquals("an instance must leave nothing registered", 0, client.registeredCount());
		assertEquals("and nothing for the frame pass to interpolate inside a raid",
			0, scene.getWalkerCount());

		// A frame in an instance must therefore be a no-op.
		scene.onFrame(view, 0.5f);
		assertEquals(0, client.registeredCount());
	}

	/**
	 * The per-frame list must be empty the moment the scope changes, not merely by
	 * the time the next visibility pass has rebuilt it.
	 *
	 * <p>It holds wrapper references, and a scope change is where wrappers get
	 * evicted. Leaving stale entries in it between the scope change and the next
	 * pass is how a frame handler ends up holding the only reference to something
	 * the cache has let go of.
	 */
	@Test
	public void aSceneChangeAndAnInvalidateBothEmptyThePerFrameListImmediately()
	{
		EntityDefinition walker = regions.wanderer(
			VARROCK_SOUTH,
			new WorldPoint(3225, 3355, 0),
			new WorldPoint(3221, 3351, 0),
			new WorldPoint(3229, 3359, 0),
			500);
		regions.file(VARROCK_SOUTH, walker);

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);
		assertEquals(1, scene.getWalkerCount());

		// An invalidate on its own — no visibility pass afterwards.
		scene.invalidate("LOADING");
		assertEquals("invalidate must empty it", 0, scene.getWalkerCount());

		// Back, then a scene change on its own.
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);
		assertEquals(1, scene.getWalkerCount());

		view.setMapRegions(9999);
		scene.syncRegions(view);
		assertEquals("a scope change must empty it there and then", 0, scene.getWalkerCount());

		// And a frame landing in that window is a no-op rather than a resurrection.
		scene.onFrame(view, 0.5f);
		assertEquals(0, client.registeredCount());

		// Same again for teardown, which has to leave nothing pointing at anything.
		view.setMapRegions(VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);
		assertEquals(1, scene.getWalkerCount());

		scene.shutdown();
		assertEquals("shutdown must empty it too", 0, scene.getWalkerCount());
		assertEquals(0, client.registeredCount());
	}

	/**
	 * The walk the scene is actually driving — not a fresh one built from the same
	 * definition, which would be a copy nothing has ever ticked.
	 */
	private static CitizenWalk walkOf(EntityScene scene, EntityDefinition definition)
	{
		LivelyEntity wrapper = scene.wrapperFor(definition);
		assertNotNull("the scene should be holding a wrapper for this definition", wrapper);
		CitizenWalk walk = wrapper.getWalk();
		assertNotNull("and that wrapper should have a walk", walk);
		return walk;
	}

	/**
	 * The visibility pass is what re-asks for an animation that missed a cold
	 * cache, for everything that stands still.
	 *
	 * <p>{@link LivelyEntity} not caching a dead controller is only half the fix:
	 * something has to ask again. A wanderer gets that for free — {@code
	 * advanceTick} re-selects its controller every game tick — but a
	 * {@code StationaryCitizen} has no other clock, and most of the dataset stands
	 * still. Without the call in {@code updateVisibility} the animation would never
	 * arrive, which is the same session-long freeze one level up.
	 */
	@Test
	public void theVisibilityPassPicksUpAnAnimationThatMissedAColdCache()
	{
		EntityDefinition citizen = regions.animatedCitizen(VARROCK_SOUTH, 3225, 3355, "Fletching");
		regions.file(VARROCK_SOUTH, citizen);
		client.setUnloadableAnimations(LivelyAnimation.Fletching.getId());

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.onGameTick(PLAYER, view);

		LivelyEntity wrapper = scene.wrapperFor(citizen);
		assertNotNull("the scene should be holding a wrapper", wrapper);
		assertNull("this citizen has no walk, so nothing else could ever re-ask",
			wrapper.getWalk());
		assertEquals("it still spawns — standing in the right place beats not being there",
			1, client.registeredCount());
		assertNull("and nothing may be installed while the animation is missing",
			wrapper.getInstalledController());

		client.clearUnloadableAnimations();
		for (int pass = 0; pass < LivelyEntity.RETRY_BACKOFF_PASSES; pass++)
		{
			scene.onGameTick(PLAYER, view);
		}

		assertNotNull("the visibility pass has to be what asks again",
			wrapper.getInstalledController());
		assertEquals("and it must not have cost the entity its place in the scene",
			1, client.registeredCount());
	}

	@Test
	public void anEntityBeyondTheCullRadiusIsDeactivatedNotJustHidden()
	{
		regions.file(VARROCK_SOUTH, regions.citizen(VARROCK_SOUTH, 3225, 3355, 0));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);
		assertEquals(1, client.registeredCount());

		// Same scene, same scope — only the player has walked out of range.
		// One tile past the cull radius, measured from the entity, not from
		// where the player started.
		WorldPoint away = new WorldPoint(3225, 3355 - RenderPolicy.DEFAULT_CULL_RADIUS - 1, 0);
		scene.updateVisibility(away, view);
		assertEquals("out of range means deactivated", 0, client.registeredCount());
		assertEquals("and the wrapper is still cached, ready to come back", 1, scene.getCachedRegionCount());
	}

	// --- the census the side panel is drawn from ------------------------------

	/**
	 * The census agrees with every count it replaces.
	 *
	 * <p>{@link EntityScene#census()} exists so the panel takes one reading instead of
	 * four, which is a cost decision — so the thing worth pinning is that the cheaper
	 * route gives the same answers as the expensive one. Each of the four is compared
	 * against the method that was already trusted, and each of the four is non-zero in
	 * this fixture, because a census of an empty scene agrees with everything.
	 */
	@Test
	public void theCensusAgreesWithTheCountsItIsThereToReplace()
	{
		regions.file(VARROCK_SOUTH, regions.talkingCrowd(VARROCK_SOUTH, 3222, 3358, 6));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);

		// Ticks until somebody is actually talking, so the talking figure is not zero.
		for (int tick = 0; tick < 400 && scene.countTalking() == 0; tick++)
		{
			scene.onGameTick(PLAYER, view);
		}

		SceneCensus census = scene.census();
		assertEquals("the fixture has to have spawned", 6, census.getActive());
		assertEquals(scene.countActive(), census.getActive());
		assertEquals(scene.getInScopeCount(), census.getInScope());
		assertEquals(scene.getWalkerCount(), census.getWalking());
		assertEquals(scene.countTalking(), census.getTalking());
		assertTrue("the fixture has to get somebody talking, or one of the four is "
			+ "being compared at zero", census.getTalking() > 0);
	}

	/**
	 * The breakdown is a breakdown, and not the total under one heading.
	 *
	 * <p>A fixture with one city in it cannot tell those apart — a census that filed
	 * every figure under whichever city it saw first would agree with it exactly — which
	 * is the fixture-too-uniform trap this suite has been caught by before. Two cities do
	 * not fit in one 104x104 scene, because cities are a hundred tiles apart by
	 * construction, so the second population here is one in a region <b>no city
	 * claims</b>: region 12851, which is directly below Varrock's southern square and is
	 * in no {@link City}'s list.
	 *
	 * <p>That is also the behaviour worth pinning in its own right. An unclaimed region
	 * fails open — a region file may land one commit before its checkbox — so its figures
	 * really are on screen and really are governed by nothing. They count towards the
	 * total and towards no card, and the panel showing a total larger than its cards add
	 * up to is the honest way to render "these are the ones no checkbox can switch off".
	 */
	@Test
	public void theCensusFilesFiguresUnderTheirOwnCityAndLeavesUnclaimedOnesOut()
	{
		WorldPoint player = new WorldPoint(3225, 3332, 0);

		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3222, 3335, 4));
		regions.file(UNCLAIMED, regions.crowd(UNCLAIMED, 3222, 3320, 2));

		assertNull("the fixture is pointless if some city has since claimed 12851",
			City.of(UNCLAIMED));
		assertEquals(City.VARROCK, City.of(VARROCK_SOUTH));

		FakeWorldView view = FakeWorldView.around(player, VARROCK_SOUTH, UNCLAIMED);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, player, view);

		SceneCensus census = scene.census();
		assertEquals("all six are up", 6, census.getActive());
		assertEquals("four of them are Varrock's", 4, census.activeIn(City.VARROCK));

		int summed = 0;
		for (City city : City.values())
		{
			summed += census.activeIn(city);
		}
		assertEquals("and the two in a region no city claims are under no heading at all",
			4, summed);
	}

	/**
	 * A different city's figures land under that city, not under whichever one the
	 * fixture happened to use first.
	 *
	 * <p>The other half of the test above, and the half that needs a second scene: two
	 * cities are too far apart to be loaded at once, so this walks to the Grand Exchange
	 * instead. Varrock's figures are deactivated on the way out — that is what a scene
	 * change does — so the same census that read {@code VARROCK=4} has to read
	 * {@code VARROCK=0, GRAND_EXCHANGE=2} afterwards. A census keyed on anything but the
	 * entity's own city cannot produce both.
	 */
	@Test
	public void walkingToAnotherCityMovesTheFiguresToThatCitysHeading()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3222, 3358, 4));
		regions.file(GRAND_EXCHANGE, regions.crowd(GRAND_EXCHANGE, 3160, 3487, 2));

		FakeWorldView varrock = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(varrock);
		VisibilityPasses.settle(scene, PLAYER, varrock);
		assertEquals(4, scene.census().activeIn(City.VARROCK));
		assertEquals(0, scene.census().activeIn(City.GRAND_EXCHANGE));

		WorldPoint atTheGe = new WorldPoint(3161, 3488, 0);
		FakeWorldView exchange = FakeWorldView.around(atTheGe, GRAND_EXCHANGE);
		scene.syncRegions(exchange);
		VisibilityPasses.settle(scene, atTheGe, exchange);

		SceneCensus census = scene.census();
		assertEquals(2, census.activeIn(City.GRAND_EXCHANGE));
		assertEquals("and Varrock's crowd left with its scene", 0, census.activeIn(City.VARROCK));
		assertEquals(2, census.getActive());
	}

	/**
	 * An entity out of scope but still registered shows up in the census.
	 *
	 * <p>The census walks the whole wrapper cache rather than the in-scope list, for the
	 * same reason {@code countActive()} does: an object still registered but out of scope
	 * is the leak every count in this class exists to be able to see. A census that
	 * walked {@code inScope} would flatter the scene rather than describe it, and would
	 * be green through exactly the defect this file was written for.
	 */
	@Test
	public void theCensusCountsAnObjectTheSceneHasStoppedTrackingToo()
	{
		regions.file(VARROCK_SOUTH, regions.crowd(VARROCK_SOUTH, 3222, 3358, 3));

		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		scene.syncRegions(view);
		VisibilityPasses.settle(scene, PLAYER, view);
		assertEquals(3, scene.census().getActive());

		// Register an object behind the scene's back, the way a despawn that threw would
		// leave one, and confirm the count is of what the client holds rather than of
		// what the scene believes.
		assertEquals("the census reads the client, not a tally the scene keeps",
			client.registeredCount(), scene.census().getActive());
	}
}

package com.matthewmariner.livelycities;

import java.util.HashMap;
import java.util.Map;

/**
 * A hand-authored theme for the handful of shipped citizens whose name and
 * examine text carry an unambiguous, non-generic identity. Everything not
 * listed here is {@link Theme#GENERIC}.
 *
 * <p><b>Why a table and not an inference.</b> {@code EntityRecord} has no
 * theme field, and the three signals available — {@code name},
 * {@code examineText}, and {@code modelIds} — do not support a rule that
 * would not also misfire on the dataset's ordinary variety. A model-id-range
 * heuristic was considered and rejected outright: reading a raw OSRS cache id
 * and guessing "this range is desert-y" is exactly the kind of clever-looking,
 * unverifiable heuristic the dataset itself already warns against (see
 * {@code ShippedModelIds}'s javadoc on why the audits read raw ids rather than
 * interpret them). Text is at least human-checkable — every entry below is a
 * direct quote — so this table is keyed on {@code uuid} (stable, unique; see
 * {@code EntityDefinition.stableHash}) with the quote that justified it next
 * to it.
 *
 * <p><b>Confidence, entry by entry.</b> The three Al Kharid "Ali"s are certain —
 * the examine text names the character outright, or the name is the character.
 * The six cameos are certain the same way. "Ali" and "Afrah" in Varrock are
 * certain <i>as {@link Theme#DESERT}</i> — their own examine text says so — but
 * whether that is a bug is a separate question, answered by
 * {@code PlacementExceptions}, not by this table.
 *
 * <p>(Harry the monkey, Steven the werewolf and the six Barrow wights were listed
 * here on the same footing until the nine-city cut removed all three places from
 * the dataset. See the comment where their rows used to be.)
 *
 * <p><b>What was found and deliberately left out</b>, because the signal did
 * not clear the bar above: nine "a dwarf" citizens scattered across five
 * unrelated regions (see {@code Theme}'s javadoc); "Ak-Haranu", a name with a
 * desert-sounding ring but no examine text or shared model id in this dataset
 * to back it up (the three "Ali"s and the two Varrock desert transplants all
 * share exact {@code modelIds} arrays with each other or say "from Al-Kharid"
 * outright — Ak-Haranu does neither); "Ghost" (Draynor) and "Ghost of
 * Lumbridge", both generic haunting flavour rather than a named character, and
 * common enough across Gielinor that tagging bare "ghost" would flag two fine
 * placements and catch nothing. (When this was written the sharper catch was the
 * six Barrow wights, which are no longer in the dataset — see below. That removes
 * the comparison, not the conclusion: a bare "ghost" tag would still be two false
 * positives and no true one.)
 */
final class EntityTheme
{
	private static final Map<String, Theme> BY_UUID = build();

	private EntityTheme()
	{
	}

	static Theme themeOf(String uuid)
	{
		return BY_UUID.getOrDefault(uuid, Theme.GENERIC);
	}

	private static Map<String, Theme> build()
	{
		Map<String, Theme> byUuid = new HashMap<>();

		// --- Desert (Al Kharid) ------------------------------------------------
		// Correctly placed: all three ship inside the Al Kharid region group.
		byUuid.put("bc9a8714-c376-4ea6-b381-fa5c3127968b", Theme.DESERT); // "Ali the goat herder", 13105
		byUuid.put("7de72de4-8585-4756-8c6d-c87847115c65", Theme.DESERT); // "Ali the wanderer", 13106
		byUuid.put("576030cc-da28-4179-ac65-c88826e9fffc", Theme.DESERT); // "Ali the spy", 13361

		// Shipped in Varrock (12853) instead. Same modelIds array as "Ali the
		// wanderer"/"Ali the spy" above, and the examine text says outright
		// "He looks like he's from Al-Kharid." — a desert theme wearing a
		// Varrock address. Whether that address is a deliberate immigrant story
		// or a bug is PlacementExceptions's call, not this table's.
		byUuid.put("ee3c3e90-7fe5-4387-a976-74463163dab7", Theme.DESERT); // "Ali", 12853, "He looks like he's from Al-Kharid."
		byUuid.put("fc28fec2-c105-49ab-8040-e36dda874646", Theme.DESERT); // "Afrah", 12853, "She looks like she's from Al-Kharid."

		// --- Karamja / jungle, and Morytania / undead ------------------------------
		// Eight rows used to live here and no longer do, because the citizens they
		// named no longer ship: "Harry" the monkey (KARAMJA_JUNGLE, 11569 Musa
		// Point), "Steven" the werewolf (MORYTANIA_UNDEAD, 13878 Canifis) and the
		// six Barrow wights (MORYTANIA_UNDEAD, 14131) all went in the nine-city cut
		// on 2026-08-24, and both themes went with them — see Theme.
		//
		// The rows were deleted rather than left in place. A uuid in this table that
		// matches nothing in the dataset protects nothing while reading as though it
		// does, which is the same failure PlacementLintTest.everyExceptionNamesA
		// ShippedCitizen makes a red test for PlacementExceptions; this table has no
		// such guard, so the discipline has to be manual.

		// --- Cameos ---------------------------------------------------------------
		// The six named likenesses of the plugin author's friends, region 12598
		// (the Grand Exchange), behind the `cameos` config item which is off by
		// default. Certain, in the way the Barrows six were certain: the name *is*
		// the character, and there is no reading of these that is a generic
		// townsperson.
		//
		// Theme.CAMEO is compatible with the Grand Exchange and nowhere else, so
		// this table is what stops a future edit copying one into Varrock square —
		// which is exactly the "fake players at a classic bank spot" the project's
		// content rules forbid, and which tagging them GENERIC would allow silently.
		// CameoPlacementTest cross-checks this list against the dataset's own
		// `cameo: true` flag, so a seventh cameo that nobody tagged is a red test
		// rather than a cameo the lint cannot see.
		byUuid.put("0ca20001-9f4e-4b17-8d63-1e5a7c2b40d1", Theme.CAMEO); // "Cazh", 12598
		byUuid.put("0ca20002-3b8d-4f52-9a71-6c0e4d19b8f3", Theme.CAMEO); // "Gunnar", 12598
		byUuid.put("0ca20003-7d16-4a9c-8b45-2f80e6c31a97", Theme.CAMEO); // "Peter", 12598
		byUuid.put("0ca20004-5e2f-4c81-9d38-4a7b0916e5c2", Theme.CAMEO); // "Sludgellama", 12598
		byUuid.put("0ca20005-1a6b-4d73-8f92-b30c58e2417d", Theme.CAMEO); // "MrCream", 12598
		byUuid.put("0ca20006-8c47-4e29-9b05-7d16a4f9302e", Theme.CAMEO); // "Rob", 12598

		return byUuid;
	}
}

package com.matthewmariner.livelycities;

import net.runelite.api.Animation;

/**
 * A short looping animation, real enough for {@code AnimationController} to walk
 * frames through.
 *
 * <p>The render core's earlier tests only ever asked <i>which</i> animation ids
 * were requested, so {@link FakeClient} could return null and
 * {@code AnimationController.tick} would return immediately. That is no longer
 * enough: the whole animation-smoothing claim is that the frame counter advances
 * between game ticks and survives everything the plugin does in between, and a
 * null animation makes {@code tick} a no-op — a fixture too uniform to
 * distinguish a working switch from a broken one.
 *
 * <p>The numbers are chosen against {@code AnimationController}'s real
 * arithmetic (disassembled from 1.12.36): the non-Maya path accumulates
 * {@code elapsedTicks} and advances while {@code elapsedTicks > frameLengths[frame]},
 * and {@code loop()} rewinds by {@code getFrameStep()} and resets to 0 if that
 * leaves the frame outside {@code getDuration()}. So a frame length of 3 client
 * ticks means one {@code tick(4)} advances exactly one frame, and a frame step
 * equal to the frame count makes the loop land back on frame 0.
 *
 * <p>All ten {@link Animation} methods are implemented rather than inheriting a
 * throwing stub: at ten methods a stub layer would be more code than the honest
 * answers.
 */
final class FakeAnimation implements Animation
{
	static final int FRAMES = 8;
	static final int FRAME_LENGTH_CLIENT_TICKS = 3;

	/** Client ticks that advance the frame counter by exactly one. */
	static final int CLIENT_TICKS_PER_FRAME = FRAME_LENGTH_CLIENT_TICKS + 1;

	private final int id;
	private final int[] frameLengths;

	private int restartMode;

	FakeAnimation(int id)
	{
		this.id = id;
		this.frameLengths = new int[FRAMES];
		for (int i = 0; i < FRAMES; i++)
		{
			frameLengths[i] = FRAME_LENGTH_CLIENT_TICKS;
		}
	}

	@Override
	public int getId()
	{
		return id;
	}

	@Override
	public boolean isMayaAnim()
	{
		return false;
	}

	@Override
	public int getNumFrames()
	{
		return FRAMES;
	}

	@Override
	public int getRestartMode()
	{
		return restartMode;
	}

	@Override
	public void setRestartMode(int restartMode)
	{
		this.restartMode = restartMode;
	}

	@Override
	public int getDuration()
	{
		return FRAMES;
	}

	@Override
	public int getFrameStep()
	{
		return FRAMES;
	}

	@Override
	public int[] getFrameLengths()
	{
		return frameLengths;
	}

	@Override
	public int getLeftHandItem()
	{
		return -1;
	}

	@Override
	public int getRightHandItem()
	{
		return -1;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.Animation;
import net.runelite.api.GameState;
import net.runelite.api.ModelData;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;

/**
 * A client that keeps the registered-object list and the model cache in fields.
 *
 * <p>This is what makes the lifecycle testable without a game running. In
 * 1.12.36 (verified by disassembling the API jar) {@code RuneLiteObject} is not
 * a black box: {@code isActive()} is exactly
 * {@code client.isRuneLiteObjectRegistered(this)} and {@code setActive(b)} is
 * exactly {@code client.registerRuneLiteObject(this)} /
 * {@code removeRuneLiteObject(this)}. So a {@link Set} standing in for the
 * client's list turns "did teardown actually deactivate anything?" into an
 * assertion, and the objects under test are real {@code RuneLiteObject}s
 * running their real code.
 *
 * <p>{@link #peakRegistered()} is a high-water mark rather than a final count,
 * because "the cap is never exceeded" is a claim about the middle of a pass, not
 * about its end.
 *
 * <p>Everything the render core does not call is inherited from
 * {@link StubClient} and throws.
 *
 * <p>{@link #getNpcDefinition(int)} is modelled on the real one's <i>failure</i>
 * shape rather than on convenience — an unknown id throws. See that method.
 */
final class FakeClient extends StubClient
{
	/** Stands in for the client's registered-object list. */
	private final Set<RuneLiteObjectController> registered = new LinkedHashSet<>();

	/** Model ids that resolve to nothing, whatever the cache is doing. */
	private final Set<Integer> unloadable = new HashSet<>();

	/** Model ids whose load blows up rather than returning null. */
	private final Set<Integer> throwing = new HashSet<>();

	/** Animation ids the entities asked for, in order. */
	private final List<Integer> animationsLoaded = new ArrayList<>();

	/**
	 * Animation ids that resolve to nothing.
	 *
	 * <p>The real {@code loadAnimation} returns null when the sequence it finds
	 * has no frame lengths and is not a Maya animation — a cold cache, or an id
	 * with no frames at all. Both look the same from here, which is the point:
	 * the plugin cannot tell them apart either, and that is why it retries.
	 */
	private final Set<Integer> unloadableAnimations = new HashSet<>();

	/**
	 * NPC compositions this client knows about, keyed by NPC id.
	 *
	 * <p>Empty by default, and an id that is <b>not</b> in here <i>throws</i> rather
	 * than returning null — see {@link #getNpcDefinition(int)}. That is the real
	 * 1.12.36 behaviour and it is the whole reason this is a map with a default
	 * rather than a "return null unless told otherwise" field: a permissive fake
	 * would make {@code NpcAppearance}'s try/catch dead code that no test could tell
	 * from an empty method body.
	 */
	private final Map<Integer, net.runelite.api.NPCComposition> npcCompositions = new HashMap<>();

	/** NPC ids the composition lookup returns null for, rather than throwing. */
	private final Set<Integer> nullNpcCompositions = new HashSet<>();

	/** Every NPC id the composition lookup was asked about, in order. */
	private final List<Integer> npcDefinitionsRequested = new ArrayList<>();

	/** True while the model cache is pretending to be cold: everything misses. */
	private boolean cacheCold;

	/** Accepts the register call and does nothing with it. */
	private boolean refuseRegistration;

	/** Throws out of {@code removeRuneLiteObject}, leaving the object registered. */
	private boolean throwFromRemoval;

	/** Throws out of {@code isRuneLiteObjectRegistered}. */
	private boolean throwFromRegistrationCheck;

	private FakeRuneLiteObject lastObject;
	private int peakRegistered;
	private int registerCalls;
	private int removeCalls;
	private int loadModelDataCalls;
	private int createObjectCalls;
	private int mergeCalls;
	private int lastMergePartCount;
	private FakeModelData lastMerged;

	@Override
	public RuneLiteObject createRuneLiteObject()
	{
		createObjectCalls++;
		lastObject = new FakeRuneLiteObject(this);
		return lastObject;
	}

	/**
	 * @return the most recently created object, for the tests that need to ask it
	 * what was done to it. The scene tests deal in counts and never touch this.
	 */
	FakeRuneLiteObject lastObject()
	{
		return lastObject;
	}

	@Override
	public void registerRuneLiteObject(RuneLiteObjectController controller)
	{
		registerCalls++;

		if (refuseRegistration)
		{
			return;
		}

		registered.add(controller);
		peakRegistered = Math.max(peakRegistered, registered.size());
	}

	@Override
	public void removeRuneLiteObject(RuneLiteObjectController controller)
	{
		// Counted before the throw: the client really was asked, and the whole point of
		// this failure mode is that asking is not the same as it having worked.
		removeCalls++;

		if (throwFromRemoval)
		{
			throw new IllegalStateException("the client will not let go of this object");
		}

		registered.remove(controller);
	}

	@Override
	public boolean isRuneLiteObjectRegistered(RuneLiteObjectController controller)
	{
		if (throwFromRegistrationCheck)
		{
			throw new IllegalStateException("the client will not say whether it has this object");
		}

		return registered.contains(controller);
	}

	/**
	 * {@code setActive(false)} blows up and the object stays registered — the state in
	 * which forgetting a wrapper leaks the object it was holding.
	 *
	 * <p>No realistic in-client trigger for this is known; it is here because the teardown
	 * promise is unconditional, and a promise nothing can falsify is not one.
	 */
	FakeClient refusingDeactivation()
	{
		throwFromRemoval = true;
		return this;
	}

	/**
	 * The client comes to its senses and starts letting go of objects again — so a
	 * wrapper kept back by an earlier teardown can be asked a second time, which is the
	 * only reason keeping it is worth anything.
	 */
	FakeClient acceptingDeactivation()
	{
		throwFromRemoval = false;
		return this;
	}

	/** The client will not even say whether it still has an object. */
	FakeClient withThrowingRegistrationChecks()
	{
		throwFromRegistrationCheck = true;
		return this;
	}

	@Override
	public ModelData loadModelData(int id)
	{
		loadModelDataCalls++;

		if (throwing.contains(id))
		{
			throw new IllegalStateException("model " + id + " blew up on the way out of the cache");
		}

		if (cacheCold || unloadable.contains(id))
		{
			return null;
		}

		return new FakeModelData();
	}

	@Override
	public ModelData mergeModels(ModelData[] parts, int count)
	{
		mergeCalls++;
		lastMergePartCount = count;
		lastMerged = new FakeModelData();
		return lastMerged;
	}

	@Override
	public Animation loadAnimation(int id)
	{
		animationsLoaded.add(id);

		if (cacheCold || unloadableAnimations.contains(id))
		{
			return null;
		}

		// A real (if short) animation, not null: AnimationController.tick returns
		// immediately when its animation is null, so a null here would make every
		// assertion about frames advancing pass for the wrong reason.
		return new FakeAnimation(id);
	}

	/**
	 * {@code Client.getNpcDefinition(int)} as 1.12.36 actually behaves.
	 *
	 * <p>Three outcomes, and each is one the plugin has to cope with:
	 * <ul>
	 *   <li><b>Known id</b> — the composition that was registered.</li>
	 *   <li><b>Explicitly null</b> — see {@link #setNullNpcComposition}. The real
	 *       accessor is a cache read, so a null is possible even though it is not the
	 *       usual failure.</li>
	 *   <li><b>Anything else, including while the cache is cold</b> — throws. That is
	 *       the real path for an id whose archive entry is absent:
	 *       {@code client.kz(id)} → {@code oh.ae(id, ..)} loads the bytes with
	 *       {@code va.bb(9, id, ..)}, which returns null, and the {@code pl}
	 *       constructor then blows up inside {@code oh.ae}'s own
	 *       {@code catch (RuntimeException)} and is rethrown wrapped.</li>
	 * </ul>
	 */
	@Override
	public net.runelite.api.NPCComposition getNpcDefinition(int id)
	{
		npcDefinitionsRequested.add(id);

		if (nullNpcCompositions.contains(id))
		{
			return null;
		}

		net.runelite.api.NPCComposition composition = cacheCold ? null : npcCompositions.get(id);
		if (composition == null)
		{
			throw new IllegalStateException("no NPC composition for id " + id);
		}

		return composition;
	}

	FakeClient withNpc(int id, net.runelite.api.NPCComposition composition)
	{
		npcCompositions.put(id, composition);
		return this;
	}

	/**
	 * Registers a working composition for every {@code npcAppearanceId} the shipped
	 * dataset references — a warm NPC archive.
	 *
	 * <p>Needed by the tests that spawn the <b>real</b> {@code RegionData/*.json}
	 * rather than a {@link FakeRegions} fixture. {@link #getNpcDefinition(int)} throws
	 * for an id nobody registered, which is the real 1.12.36 behaviour, so without
	 * this those tests model a client whose NPC archive is missing every id the
	 * dataset names: "Rufus" in Varrock would silently fail to spawn and a crowd count
	 * would come out one short for a reason that has nothing to do with what was being
	 * measured. It cost an afternoon once; hence this method rather than a per-test
	 * {@code withNpc} call.
	 *
	 * <p>Reads the ids straight out of the dataset, so an eighth one added to the JSON
	 * is covered without touching this.
	 */
	FakeClient withShippedNpcAppearances()
	{
		for (int id : ShippedModelIds.distinctNpcAppearanceIds())
		{
			withNpc(id, FakeNpcComposition.of("shipped npc " + id, 900_000 + id));
		}
		return this;
	}

	/** The id resolves to a null composition instead of throwing. */
	FakeClient setNullNpcComposition(int id)
	{
		nullNpcCompositions.add(id);
		return this;
	}

	/** Every NPC id the composition lookup was asked about, in order. */
	List<Integer> npcDefinitionsRequested()
	{
		return npcDefinitionsRequested;
	}

	void setUnloadableAnimations(int... ids)
	{
		for (int id : ids)
		{
			unloadableAnimations.add(id);
		}
	}

	void clearUnloadableAnimations()
	{
		unloadableAnimations.clear();
	}

	/**
	 * {@code RuneLiteObject.setLocation} runs
	 * {@code Perspective.getTileHeight(client, ..)}, which asks the client for
	 * the world view by id and returns height 0 when there is none. Null is
	 * therefore the honest answer for a scene that only exists as numbers, and
	 * it keeps the real {@code setLocation} on its real code path.
	 */
	@Override
	public WorldView getWorldView(int id)
	{
		return null;
	}

	// --- The four the plugin's own event handlers read. -----------------------
	// The render core never touches these; LivelyCitiesPluginLifecycleTest drives
	// all four. They are fields rather than throwing stubs because every one of
	// them is a thing the plugin has to cope with changing under it: the game
	// cycle is the interpolation clock, and the other three are each null or
	// wrong at some point in a real login.

	/**
	 * The client's 20ms clock. An {@code int} on purpose — it is one in the API,
	 * and the plugin's fraction arithmetic has to survive it wrapping.
	 */
	private int gameCycle;

	private GameState gameState = GameState.LOGGED_IN;

	@Nullable
	private Player localPlayer;

	@Nullable
	private WorldView topLevelWorldView;

	@Override
	public int getGameCycle()
	{
		return gameCycle;
	}

	@Override
	public GameState getGameState()
	{
		return gameState;
	}

	@Override
	@Nullable
	public Player getLocalPlayer()
	{
		return localPlayer;
	}

	@Override
	@Nullable
	public WorldView getTopLevelWorldView()
	{
		return topLevelWorldView;
	}

	void setGameCycle(int gameCycle)
	{
		this.gameCycle = gameCycle;
	}

	/** @return the cycle after advancing it, so a test can read the clock it set */
	int advanceGameCycle(int clientTicks)
	{
		gameCycle += clientTicks;
		return gameCycle;
	}

	/**
	 * {@code Client.setGameState} is a real API method, so this implements it
	 * rather than shadowing it under another name. The plugin never calls it; the
	 * tests do, to move the client between states.
	 */
	@Override
	public void setGameState(GameState gameState)
	{
		this.gameState = gameState;
	}

	void setLocalPlayer(@Nullable Player localPlayer)
	{
		this.localPlayer = localPlayer;
	}

	void setTopLevelWorldView(@Nullable WorldView topLevelWorldView)
	{
		this.topLevelWorldView = topLevelWorldView;
	}

	int registeredCount()
	{
		return registered.size();
	}

	/**
	 * How many times the client was asked to register / unregister an object,
	 * rather than how many are registered now.
	 *
	 * <p>The difference matters for the per-frame path.
	 * {@code RuneLiteObject.setLocation} silently deactivates and reactivates the
	 * object whenever the point's world view differs from the object's, so a
	 * mismatched world view would churn the registered-object list once per frame
	 * per citizen while leaving the <i>count</i> looking perfectly stable.
	 */
	int registerCalls()
	{
		return registerCalls;
	}

	int removeCalls()
	{
		return removeCalls;
	}

	int peakRegistered()
	{
		return peakRegistered;
	}

	int loadModelDataCalls()
	{
		return loadModelDataCalls;
	}

	int createObjectCalls()
	{
		return createObjectCalls;
	}

	int mergeCalls()
	{
		return mergeCalls;
	}

	int lastMergePartCount()
	{
		return lastMergePartCount;
	}

	FakeModelData lastMerged()
	{
		return lastMerged;
	}

	List<Integer> animationsLoaded()
	{
		return animationsLoaded;
	}

	void setCacheCold(boolean cold)
	{
		cacheCold = cold;
	}

	void setUnloadable(int... ids)
	{
		for (int id : ids)
		{
			unloadable.add(id);
		}
	}

	void setThrowing(int... ids)
	{
		for (int id : ids)
		{
			throwing.add(id);
		}
	}

	void refuseRegistration()
	{
		refuseRegistration = true;
	}

	void resetCounters()
	{
		loadModelDataCalls = 0;
		createObjectCalls = 0;
		mergeCalls = 0;
		registerCalls = 0;
		removeCalls = 0;
	}

	// --- The interaction surface. --------------------------------------------
	//
	// Four methods, and the list is deliberately this short: every other way of
	// reaching the game — menuAction(..) above all — stays on StubClient and throws.
	// That is how CitizenMenuTest can assert "the click handler sends nothing to the
	// server" as a fact about the code rather than as an intention. A permissive
	// client would have made the claim unprovable.

	private final FakeMenu menu = new FakeMenu();

	private final List<String> chatMessages = new ArrayList<>();

	private boolean widgetSelected;

	@Nullable
	private net.runelite.api.Point mouseCanvasPosition;

	@Override
	public net.runelite.api.Menu getMenu()
	{
		return menu;
	}

	FakeMenu menu()
	{
		return menu;
	}

	/**
	 * The {@code MenuOpened} the client would post for the menu as it stands now.
	 *
	 * <p>A snapshot, exactly like the real event: {@code Menu.createMenuEntry}
	 * mutates the live menu, so entries added by a handler do not appear in the array
	 * the handler was given.
	 */
	net.runelite.api.events.MenuOpened menuOpened()
	{
		net.runelite.api.events.MenuOpened event = new net.runelite.api.events.MenuOpened();
		event.setMenuEntries(menu.getMenuEntries());
		return event;
	}

	/**
	 * "Is a widget in target mode?" — the client's own javadoc. True while an item
	 * or a spell is on the cursor, which is the state
	 * {@link CitizenMenu#onMenuOpened} must produce no clickbox in.
	 */
	@Override
	public boolean isWidgetSelected()
	{
		return widgetSelected;
	}

	/**
	 * {@code Client.setWidgetSelected} is a real API method, so this implements it
	 * rather than shadowing it under another name — the same treatment as
	 * {@code setGameState} above. This plugin never calls it; the tests do, to put
	 * an item on the cursor.
	 */
	@Override
	public void setWidgetSelected(boolean widgetSelected)
	{
		this.widgetSelected = widgetSelected;
	}

	@Override
	@Nullable
	public net.runelite.api.Point getMouseCanvasPosition()
	{
		return mouseCanvasPosition;
	}

	void setMouseCanvasPosition(@Nullable net.runelite.api.Point position)
	{
		this.mouseCanvasPosition = position;
	}

	// --- The interface layout, for the minimap guard. -------------------------
	//
	// Three methods, and they are the three RuneLite's own OverlayOrigin.MINIMAP
	// asks (verified in client-1.12.36's bytecode): is the client resized, which
	// toplevel interface is loaded, and what is at this component id.
	//
	// The widget map starts EMPTY and getWidget returns null for anything not in
	// it, which is the real behaviour for a component in an interface that is not
	// loaded — getWidget(group, child) returns null once either array index is out
	// of range. That default is what lets a test say "the layout the client is in
	// is not the one this id belongs to" by simply not registering it.

	private final Map<Integer, net.runelite.api.widgets.Widget> widgets = new HashMap<>();

	private boolean resized;

	private int topLevelInterfaceId = net.runelite.api.gameval.InterfaceID.TOPLEVEL;

	@Override
	public boolean isResized()
	{
		return resized;
	}

	@Override
	public int getTopLevelInterfaceId()
	{
		return topLevelInterfaceId;
	}

	@Override
	@Nullable
	public net.runelite.api.widgets.Widget getWidget(int componentId)
	{
		return widgets.get(componentId);
	}

	/** Puts one widget at one packed {@code gameval.InterfaceID} component id. */
	FakeClient withWidget(int componentId, net.runelite.api.widgets.Widget widget)
	{
		widgets.put(componentId, widget);
		return this;
	}

	/**
	 * Switches the client into one of the resizable layouts.
	 *
	 * @param topLevelInterfaceId {@code InterfaceID.TOPLEVEL_OSRS_STRETCH} or
	 *                            {@code InterfaceID.TOPLEVEL_PRE_EOC} — the two the
	 *                            resizable branch has to tell apart
	 */
	FakeClient resizedWith(int topLevelInterfaceId)
	{
		this.resized = true;
		this.topLevelInterfaceId = topLevelInterfaceId;
		return this;
	}

	/**
	 * The local chat buffer. Returns null rather than a {@code MessageNode} because
	 * nothing in this plugin reads the result — it prints a line and forgets it.
	 */
	@Override
	@Nullable
	public net.runelite.api.MessageNode addChatMessage(
		net.runelite.api.ChatMessageType type, String name, String message, String sender)
	{
		chatMessages.add(message);
		return null;
	}

	List<String> chatMessages()
	{
		return chatMessages;
	}
}

package com.matthewmariner.livelycities;

import net.runelite.api.CollisionData;

/**
 * One plane's collision map, as a plain {@code int[][]}.
 *
 * <p>{@link CollisionData} has exactly one method in 1.12.36 —
 * {@code int[][] getFlags()}, confirmed by {@code javap} — so this is the whole
 * interface and there is nothing to stub out.
 *
 * <p><b>Sized and indexed the way the client sizes and indexes it.</b> The injected
 * client allocates the flags array as
 * {@code new int[worldView.getSizeX()][worldView.getSizeY()]} and every writer in
 * it does {@code flags[x][y] |= ..}, so this is {@code [sceneX][sceneY]} and a test
 * that got the two the wrong way round would be asserting about the wrong tile.
 * {@code StandableGroundTest.theFlagsAreIndexedSceneXThenSceneY} is the test that
 * pins the order, and it deliberately uses an asymmetric fixture so a transposed
 * reader cannot pass it.
 *
 * <p><b>Zero means walkable.</b> That is the client's own convention — a flag is
 * something that blocks — so a freshly built map is open ground everywhere, and a
 * test only has to say what is blocked.
 */
final class FakeCollisionData implements CollisionData
{
	private final int[][] flags;

	FakeCollisionData(int sizeX, int sizeY)
	{
		this.flags = new int[sizeX][sizeY];
	}

	@Override
	public int[][] getFlags()
	{
		return flags;
	}

	/** ORs {@code mask} into one tile's flags. */
	void set(int sceneX, int sceneY, int mask)
	{
		flags[sceneX][sceneY] |= mask;
	}

	int at(int sceneX, int sceneY)
	{
		return flags[sceneX][sceneY];
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;

/**
 * A settable {@link LivelyCitiesConfig}.
 *
 * <p>No mocking framework needed and none available: a RuneLite config is an
 * interface of {@code default} methods, so the defaults come for free and only
 * the parts a test cares about have to be written.
 *
 * <p><b>All 9 city getters are overridden individually, on purpose.</b> The
 * cheap version of this class would return one field from all of them — and it
 * would then be a fixture too uniform to distinguish outcomes: every city would
 * answer the same, so {@code City.VARROCK.enabledIn(..)} calling
 * {@code cityLumbridge()} would be invisible. Wiring each getter to its own
 * {@link City} constant makes the composition of the two mappings an identity
 * that {@code CityTest} can assert, so a copy-paste in either direction is a red
 * test.
 *
 * <p><b>The two hidden uuid strings go through a real store.</b>
 * {@link #hiddenCitizens()} and {@link #mutedCitizens()} read the same map
 * {@link #writer()} writes, so "hide this citizen" in a test travels the whole
 * way a real one does: serialise to a string, store it under the key, read it
 * back, parse it. A pair of {@code Set<UUID>} fields would have tested
 * {@link UuidSetting}'s intent and skipped its only interesting failure mode.
 * The map also stands in for {@code ConfigManager}'s absence-versus-default
 * distinction: a key that was never written, or was unset, reads as the
 * interface default.
 */
final class FakeConfig implements LivelyCitiesConfig
{
	private final Set<City> disabled = EnumSet.noneOf(City.class);

	/** What {@link #writer()} has written, keyed on {@code keyName}. */
	private final Map<String, String> stored = new HashMap<>();

	/** Every write, in order — see {@link #writes()}. */
	private final List<String> writes = new ArrayList<>();

	private int cullRadius = RenderPolicy.DEFAULT_CULL_RADIUS;
	private CrowdDensity crowdDensity = CrowdDensity.FULL;

	/**
	 * Starts at the real default, which is <b>off</b>. Deliberately not flipped to
	 * true for convenience: a fixture that opted every test in would make "a fresh
	 * install shows no cameos" a claim no test could check.
	 */
	private boolean cameos = LivelyCitiesConfig.super.cameos();

	private boolean overheadText = true;
	private int remarkIntervalTicks = CitizenChatter.DEFAULT_ROLL_INTERVAL_TICKS;
	private int remarkDwellTicks = CitizenChatter.DEFAULT_DWELL_TICKS;
	private int chatterRadius = CitizenChatter.DEFAULT_RADIUS_TILES;
	private int maxConcurrentRemarks = CitizenChatter.DEFAULT_MAX_CONCURRENT;

	@Nullable
	private CitizenOverrides overrides;

	FakeConfig disable(City... cities)
	{
		for (City city : cities)
		{
			disabled.add(city);
		}
		return this;
	}

	FakeConfig enable(City... cities)
	{
		for (City city : cities)
		{
			disabled.remove(city);
		}
		return this;
	}

	FakeConfig disableOnly(City city)
	{
		disabled.clear();
		disabled.add(city);
		return this;
	}

	FakeConfig setCullRadius(int cullRadius)
	{
		this.cullRadius = cullRadius;
		return this;
	}

	FakeConfig setCrowdDensity(CrowdDensity crowdDensity)
	{
		this.crowdDensity = crowdDensity;
		return this;
	}

	FakeConfig setCameos(boolean cameos)
	{
		this.cameos = cameos;
		return this;
	}

	FakeConfig setOverheadText(boolean overheadText)
	{
		this.overheadText = overheadText;
		return this;
	}

	FakeConfig setRemarkIntervalTicks(int ticks)
	{
		this.remarkIntervalTicks = ticks;
		return this;
	}

	FakeConfig setRemarkDwellTicks(int ticks)
	{
		this.remarkDwellTicks = ticks;
		return this;
	}

	FakeConfig setChatterRadius(int tiles)
	{
		this.chatterRadius = tiles;
		return this;
	}

	FakeConfig setMaxConcurrentRemarks(int max)
	{
		this.maxConcurrentRemarks = max;
		return this;
	}

	/**
	 * The write half of the round trip.
	 *
	 * <p>{@code null} removes the key, which is what {@link ConfigWriter}'s contract
	 * says and what the real one does with {@code unsetConfiguration} — so a cleared
	 * list comes back as the interface default rather than as the empty string, and a
	 * test that asserted on the difference would see it.
	 */
	ConfigWriter writer()
	{
		return (key, value) ->
		{
			writes.add(key + "=" + value);
			if (value == null)
			{
				stored.remove(key);
			}
			else
			{
				stored.put(key, value);
			}
		};
	}

	/**
	 * Every write, in order, as {@code key=value}.
	 *
	 * <p>Counted as well as applied, because "this must not write twice" is a real
	 * requirement in two places: {@code ConfigManager} posts a {@code ConfigChanged}
	 * per write and this plugin answers each one with a full visibility pass, and a
	 * self-unticking button that rewrote itself on its own echo would never stop.
	 */
	List<String> writes()
	{
		return writes;
	}

	/** @return the raw stored value, or {@code null} if the key is not set */
	@Nullable
	String stored(String key)
	{
		return stored.get(key);
	}

	/**
	 * The {@link CitizenOverrides} that reads and writes this config — one instance,
	 * memoised.
	 *
	 * <p>Memoised because it has to be shared. {@link CitizenOverrides} caches its
	 * parse, and the scene and the menu must be looking at the same cache: a test
	 * where the menu hid somebody and the scene held a different {@code UuidSetting}
	 * would pass or fail on which copy happened to re-read the string first, which is
	 * exactly the kind of test that is green for the wrong reason.
	 */
	CitizenOverrides overrides()
	{
		if (overrides == null)
		{
			overrides = new CitizenOverrides(this, writer());
		}
		return overrides;
	}

	private boolean on(City city)
	{
		return !disabled.contains(city);
	}

	@Override
	public int cullRadius()
	{
		return cullRadius;
	}

	@Override
	public CrowdDensity crowdDensity()
	{
		return crowdDensity;
	}

	@Override
	public boolean cameos()
	{
		return cameos;
	}

	@Override
	public boolean overheadText()
	{
		return overheadText;
	}

	@Override
	public int remarkIntervalTicks()
	{
		return remarkIntervalTicks;
	}

	@Override
	public int remarkDwellTicks()
	{
		return remarkDwellTicks;
	}

	@Override
	public int chatterRadius()
	{
		return chatterRadius;
	}

	@Override
	public int maxConcurrentRemarks()
	{
		return maxConcurrentRemarks;
	}

	@Override
	public String hiddenCitizens()
	{
		return stored.getOrDefault(CitizenOverrides.HIDDEN_KEY,
			LivelyCitiesConfig.super.hiddenCitizens());
	}

	@Override
	public String mutedCitizens()
	{
		return stored.getOrDefault(CitizenOverrides.MUTED_KEY,
			LivelyCitiesConfig.super.mutedCitizens());
	}

	@Override
	public boolean unhideAll()
	{
		return Boolean.parseBoolean(stored.getOrDefault(CitizenOverrides.UNHIDE_ALL_KEY, "false"));
	}

	@Override
	public boolean unmuteAll()
	{
		return Boolean.parseBoolean(stored.getOrDefault(CitizenOverrides.UNMUTE_ALL_KEY, "false"));
	}

	// --- One override per checkbox, each pointing at exactly one City. --------

	@Override
	public boolean cityAlKharid()
	{
		return on(City.AL_KHARID);
	}

	@Override
	public boolean cityArdougne()
	{
		return on(City.ARDOUGNE);
	}

	@Override
	public boolean cityCatherby()
	{
		return on(City.CATHERBY);
	}

	@Override
	public boolean cityDraynor()
	{
		return on(City.DRAYNOR);
	}

	@Override
	public boolean cityEdgeville()
	{
		return on(City.EDGEVILLE);
	}

	@Override
	public boolean cityFalador()
	{
		return on(City.FALADOR);
	}

	@Override
	public boolean cityGrandExchange()
	{
		return on(City.GRAND_EXCHANGE);
	}

	@Override
	public boolean cityLumbridge()
	{
		return on(City.LUMBRIDGE);
	}

	@Override
	public boolean cityVarrock()
	{
		return on(City.VARROCK);
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

/**
 * The client minimenu, as an array a test can read.
 *
 * <p>{@link #createMenuEntry(int)} reproduces the real index arithmetic, verified
 * by disassembling 1.12.36: a negative index is folded to
 * {@code count + idx + 1} (so {@code -1} appends at the end) and a non-negative
 * one is used directly, shifting whatever is already there. That is the whole
 * point of this class rather than a list that only counts calls — "our entries go
 * in below every real option" is a claim about <i>where</i> in the array they
 * landed, and the array is rendered last-first
 * ({@code MenuOpened.getFirstEntry()} returns {@code menuEntries[length - 1]}), so
 * index 0 is the bottom row of the menu and index {@code count} is the top one.
 * A fake that appended regardless of the index would have made the two
 * indistinguishable.
 *
 * <p>{@link #seedWorldClick()} fills the menu with the entries the client itself
 * would have built for a right-click on the world, so that inserting at index 0 has
 * something real to be below — and so that {@link CitizenMenu}'s
 * world-click-versus-interface-click test has something to read.
 */
final class FakeMenu implements Menu
{
	private final List<MenuEntry> entries = new ArrayList<>();

	/** Only the ones {@link #createMenuEntry(int)} produced — see {@link #created()}. */
	private final List<MenuEntry> created = new ArrayList<>();

	/**
	 * One stand-in for a client entry, appended in array order — i.e. below
	 * everything seeded before it, because the array renders last-first.
	 *
	 * <p>The {@link MenuAction} is a required argument rather than a default,
	 * because {@link CitizenMenu} reads it: "was this a click on the world or on an
	 * interface" is answered by looking for a {@code WALK} entry, and a fixture
	 * whose seeds all carried the same type could not tell the two apart.
	 */
	FakeMenu seed(MenuAction action, String option)
	{
		entries.add(new FakeMenuEntry().setOption(option).setType(action));
		return this;
	}

	/**
	 * The menu the client builds for a right-click on the game world: Cancel, Walk
	 * here, and something real to click on.
	 */
	FakeMenu seedWorldClick()
	{
		return seed(MenuAction.CANCEL, "Cancel")
			.seed(MenuAction.WALK, "Walk here")
			.seed(MenuAction.NPC_FIRST_OPTION, "Talk-to");
	}

	/**
	 * The menu the client builds for a right-click on the <b>minimap</b>: Cancel and
	 * Walk here, and nothing that says where the click came from.
	 *
	 * <p>Deliberately a strict subset of {@link #seedWorldClick()} rather than
	 * something recognisable — that is the whole of GitHub issue #2. Disassembling the
	 * injected 1.12.36 client, every "Walk here" in the game comes out of one method
	 * with a literal identifier of {@code 0}, an empty target and mouse-relative
	 * params, so no field on the entry distinguishes a map click from a ground click.
	 * A fixture that made the two menus tell themselves apart would let a
	 * menu-reading fix pass a test the real client would fail.
	 */
	FakeMenu seedMinimapClick()
	{
		return seed(MenuAction.CANCEL, "Cancel")
			.seed(MenuAction.WALK, "Walk here");
	}

	/**
	 * The menu the client builds for a right-click on an interface: no "Walk here",
	 * because there is no tile under an inventory slot.
	 */
	FakeMenu seedInterfaceClick()
	{
		return seed(MenuAction.CANCEL, "Cancel")
			.seed(MenuAction.CC_OP, "Drop")
			.seed(MenuAction.CC_OP, "Wield");
	}

	@Override
	public MenuEntry createMenuEntry(int idx)
	{
		int at = idx;
		if (at < 0)
		{
			at = entries.size() + at + 1;
			if (at < 0)
			{
				throw new IllegalArgumentException("index " + idx + " is past the start of the menu");
			}
		}

		if (at > entries.size())
		{
			throw new IllegalStateException("index " + idx + " is past the end of a "
				+ entries.size() + "-entry menu");
		}

		MenuEntry entry = new FakeMenuEntry();
		entries.add(at, entry);
		created.add(entry);
		return entry;
	}

	@Override
	public MenuEntry[] getMenuEntries()
	{
		return entries.toArray(new MenuEntry[0]);
	}

	@Override
	public void setMenuEntries(MenuEntry[] menuEntries)
	{
		throw new UnsupportedOperationException(
			"FakeMenu.setMenuEntries — this plugin only ever adds entries, never replaces the array");
	}

	@Override
	public void removeMenuEntry(MenuEntry entry)
	{
		throw new UnsupportedOperationException(
			"FakeMenu.removeMenuEntry — this plugin never removes an entry; "
				+ "conditional removal of real entries is a hub-forbidden feature");
	}

	@Override
	public int getMenuX()
	{
		throw new UnsupportedOperationException("FakeMenu.getMenuX");
	}

	@Override
	public int getMenuY()
	{
		throw new UnsupportedOperationException("FakeMenu.getMenuY");
	}

	@Override
	public int getMenuWidth()
	{
		throw new UnsupportedOperationException("FakeMenu.getMenuWidth");
	}

	@Override
	public int getMenuHeight()
	{
		throw new UnsupportedOperationException("FakeMenu.getMenuHeight");
	}

	// --- what the tests ask ---------------------------------------------------

	/** @return the entries in array order, i.e. bottom row of the menu first */
	List<MenuEntry> entries()
	{
		return entries;
	}

	/**
	 * @return the entries {@link #createMenuEntry(int)} handed out, in the order it
	 * handed them out.
	 *
	 * <p>Tracked separately rather than filtered out of {@link #entries()} by type.
	 * Filtering on {@code getType() == RUNELITE} would make "every entry we add is
	 * RUNELITE" true by construction — the assertion would be checking the fake.
	 */
	List<MenuEntry> created()
	{
		return created;
	}

	/** @return how many rows the menu holds */
	int size()
	{
		return entries.size();
	}
}

package com.matthewmariner.livelycities;

