		this.type = type;
		return this;
	}

	@Override
	public int getIdentifier()
	{
		return identifier;
	}

	@Override
	public MenuEntry setIdentifier(int identifier)
	{
		this.identifier = identifier;
		return this;
	}

	@Override
	public boolean isDeprioritized()
