	@Override
	public MenuEntry setDeprioritized(boolean deprioritized)
	{
		this.deprioritized = deprioritized;
		return this;
	}

	@Override
	public String toString()
	{
		return "FakeMenuEntry{" + option + " " + target
			+ ", " + type + ", id " + identifier
			+ ", deprioritized " + deprioritized + '}';
	}
