	// --- helpers ----------------------------------------------------------------

	/**
	 * The frame meter is handed the number of walkers it actually interpolated.
	 *
	 * <p><b>Why this exists as a separate test</b>, when
	 * {@link #everyFrameIsASampleEvenWithNobodyWalking} already reads
	 * {@code countAtMax(INTERPOLATION)}: that one asserts the count is <b>0</b>, with a
	 * fixture of five stationary citizens — and 0 is also what a completely
	 * disconnected meter returns. Review proved it: replacing
	 * {@code recordFrame(startedAt, walkers.size())} with {@code recordFrame(startedAt,
	 * 99)} left the entire suite green. An expected value that coincides with the
	 * broken value is not a test, and this file had two of them.
	 *
	 * <p>So the fixture here has a walker count that is neither 0 nor any number a
	 * plausible mutation would pick, and the assertion is that <i>that</i> number comes
	 * back out.
	 */
	@Test
	public void theFrameMeterIsToldHowManyWalkersItActuallyInterpolated()
	{
		FrameTimings timings = new FrameTimings(true, true);
		EntityScene scene = sceneWithWanderers(timings, 3);

		scene.updateVisibility(PLAYER, view);
		assertEquals("the fixture has to actually walk, or this measures nothing",
			3, scene.getWalkerCount());

		scene.onFrame(view, 0.5f);

		assertEquals("the frame meter reports the walker count it was given",
			3, timings.countAtMax(FrameTimings.Pass.INTERPOLATION));
	}

	/**
	 * The model-build meter is handed the count the pass <b>planned</b>, which is not
	 * the same number as the count it considered.
	 *
	 * <p>The second mutation that survived the whole suite:
	 * {@code recordModelBuild(buildStartedAt, planned)} → {@code recordModelBuild(
	 * buildStartedAt, 0)}, green everywhere. {@code planned} is what the pass is about
	 * to have on screen — the same value for every build inside one pass.
	 *
	 * <p><b>Why the fixture is 90 citizens and not 5.</b> With five, {@code planned},
	 * {@code candidates.size()} and the fixture size are all 5, so the test passed
	 * against {@code recordModelBuild(buildStartedAt, candidates.size())} too — an
	 * expected value that coincides with a broken one, which is exactly the failure this
	 * file has already been caught by twice. The two are genuinely different in
	 * production: {@code planned} stops at {@link RenderPolicy#MAX_ACTIVE_OBJECTS} and
	 * {@code candidates} does not, so in the densest shipped neighbourhood at
	 * {@code CROWDED} the report would have claimed "at 120 objects active" for a pass
	 * that put 80 on screen — overstating the load the timing was measured under, in
	 * the one place the measurement matters. 90 candidates against a cap of 80 makes
	 * that gap real in the fixture.
	 *
	 * <p>Note this is only observable at all because {@code maxMicros} now starts at
	 * {@code -1}: every sample here truncates to 0µs, and under the old {@code
	 * micros > maxMicros} test against an initial 0, no sample ever won and the answer
	 * was 0 regardless.
	 */
	@Test
	public void theModelBuildMeterIsToldWhatThePassPlannedAndNotWhatItConsidered()
	{
		FrameTimings timings = new FrameTimings(true, true);
		EntityScene scene = packedSceneWith(timings, 90);

		// Eighty models no longer fit in one pass — that is what
		// RenderPolicy.MAX_MODEL_BUILDS_PER_PASS is for — so this is the same fixture
		// arriving over the twenty-seven passes it now takes. `planned` is unaffected by
		// the build budget and is 80 on every one of them, which is the point.
		VisibilityPasses.settle(scene, PLAYER, view);

		assertEquals("all ninety have to be candidates, or the cap is not what bound",
			90, scene.inScopeEntities().size());
		assertEquals("and the cap has to bind, or planned and candidates.size() are the "
				+ "same number again",
			RenderPolicy.MAX_ACTIVE_OBJECTS, scene.countActive());

		assertEquals("one build per object the pass planned for", (long) RenderPolicy.MAX_ACTIVE_OBJECTS,
			timings.sampleCount(FrameTimings.Pass.MODEL_BUILD));
		assertEquals("the model-build meter reports what the pass planned — 80 — and not the "
				+ "90 candidates it sorted through to get there, and not the three it was "
				+ "allowed to build on the pass the sample came from",
			RenderPolicy.MAX_ACTIVE_OBJECTS, timings.countAtMax(FrameTimings.Pass.MODEL_BUILD));
	}

	/**
	 * The visibility meter is handed everything the pass left the client holding, not
	 * just the objects it spawned this time round.
	 *
	 * <p>{@code runVisibilityPass} returns {@code planned - failed}, and the third
	 * mutation that survived the whole suite was {@code return spawned}. The two
	 * coincide on every first pass — an entity that was not already active either spawns
	 * or fails — so every fixture in this file agreed with the broken version. They come
	 * apart on the <b>second</b> pass over the same crowd, which is what a real client
	 * does every game tick: nothing new spawns, {@code spawned} is 0, and the client is
	 * still holding all five. A meter fed {@code spawned} would report a steady state as
	 * "0 objects active" and make the p99 of a busy scene look like the p99 of an empty
	 * one.
	 *
	 * <p>Read off the report's own min/mean/max line rather than {@code countAtMax},
	 * because {@code countAtMax} keeps the count from the <i>slowest</i> sample and both
	 * passes here truncate to 0µs, so the first one wins the tie and the second pass —
	 * the only one that can tell the two versions apart — never shows up in it.
	 *
	 * <p>The fixture is three rather than the five it used to be, because three is what
	 * {@link RenderPolicy#MAX_MODEL_BUILDS_PER_PASS} lets one pass build: with five, the
	 * first pass legitimately leaves three on screen and the min/mean/max line stops
	 * being one number. What this test needs is two passes that agree, and the
	 * held-over-builds arithmetic is guarded next door in
	 * {@link #everyVisibilityPassIsOneSampleCarryingTheActiveObjectCount}.
	 */
	@Test
	public void theVisibilityMeterCountsEverythingLeftActiveAndNotJustTheNewSpawns()
	{
		FrameTimings timings = new FrameTimings(true, true);
		EntityScene scene = sceneWith(timings, 3);

		scene.updateVisibility(PLAYER, view);
		assertEquals("the first pass has to actually spawn them", 3, scene.countActive());

		// The second pass: everybody is already on screen and stays there.
		scene.updateVisibility(PLAYER, view);
		assertEquals("and the second pass has to leave them there", 3, scene.countActive());

		assertEquals("two passes, two samples", 2L,
			timings.sampleCount(FrameTimings.Pass.VISIBILITY));

		// Deliberately the heading's *prefix*, not the whole thing. The full name gained
		// ", excluding model builds" when the meters were split on 2026-08-29 and this
		// assertion went red on the rename alone, having caught nothing. "visibility
		// pass (per game tick" already identifies exactly one meter — no other heading
		// begins with it, which theReportNamesEachMeterOnce pins — so matching on it
		// keeps the guard pointed at the right section without re-breaking every time
		// the parenthetical is reworded.
		String section = meterSection(timings.toReportText(), "visibility pass (per game tick");
		assertTrue("both passes left three objects with the client, so neither sample may "
				+ "read 0:\n" + section,
			section.contains("objects active: min 3, mean 3, max 3"));
	}

	/**
	 * Guice builds the scene through the constructor that takes the stopwatch.
	 *
	 * <p><b>The one thing in this file no hand-built fixture can see.</b> Every test
	 * here constructs {@link EntityScene} itself and passes a {@link FrameTimings} in,
	 * so moving {@code @Inject} onto the four-argument convenience constructor — the one
	 * that supplies {@link FrameTimings#off()} — leaves all of them green while the
	 * instrument is dead in every real client: the developer sets the system property,
	 * sees the "frame timings are on" line at startup, and gets a report of three empty
	 * meters.
	 *
	 * <p>So this asks the real injector, rather than reading the annotation. Guice is
	 * how RuneLite builds this plugin, the bindings below are the ones the client
	 * supplies, and the assertion is on the consequence — a meter this test owns either
	 * received a sample or did not. Not reflection and not a mocking framework: the
	 * production container, building the production object graph, out of the same
	 * hand-rolled fakes every other test here uses.
	 */
	@Test
	public void theSceneGuiceBuildsIsTheOneWiredToTheStopwatch()
	{
		FrameTimings timings = new FrameTimings(true, true);
		regions.file(VARROCK_NORTH, regions.citizen(VARROCK_NORTH, 3221, 3420, 0));

		Injector injector = Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(Client.class).toInstance(client);
				bind(RegionDataLoader.class).toInstance(regions);
				bind(LivelyCitiesConfig.class).toInstance(config);
				bind(CitizenOverrides.class).toInstance(config.overrides());
				bind(FrameTimings.class).toInstance(timings);
			}
		});

		EntityScene scene = injector.getInstance(EntityScene.class);
		scene.syncRegions(view);
		scene.updateVisibility(PLAYER, view);

		assertEquals("the scene has to have actually done a pass", 1, scene.countActive());
		assertEquals("the injected scene has to be holding the injected stopwatch — on the "
				+ "four-argument constructor it would build its own FrameTimings.off() and "
				+ "this meter would never hear from it again",
			1L, timings.sampleCount(FrameTimings.Pass.VISIBILITY));
	}

	/**
	 * A 0µs maximum still carries its companion count.
	 *
	 * <p>The regression test for the bug the two above were blind to, stated in the
	 * meter's own terms rather than through the scene: {@code maxMicros} initialised to
	 * 0 makes {@code micros > maxMicros} false for every 0µs sample, so {@code
	 * countAtMax} is never assigned. It matters because "too fast to measure" is the
	 * answer the interpolation meter is <i>expected</i> to give — the failure was
	 * invisible in the case anyone would look for and only bit in the healthy one.
	 */
	@Test
	public void aMaximumOfZeroStillReportsTheCountItHappenedAt()
	{
		FrameTimings timings = new FrameTimings(true, true);

		timings.recordElapsed(FrameTimings.Pass.INTERPOLATION, 900L, 42);
		timings.recordElapsed(FrameTimings.Pass.INTERPOLATION, 400L, 37);

		assertEquals("both samples truncate to 0us, so the first one is the max",
			0L, timings.maxMicros(FrameTimings.Pass.INTERPOLATION));
		assertEquals("and it has to remember there were 42 walkers, not 0",
			42, timings.countAtMax(FrameTimings.Pass.INTERPOLATION));
		assertTrue("the report must not claim 0 walkers when there were 42",
			timings.summaryLine().contains("at 42 walkers"));
	}

	private EntityScene sceneWithWanderers(FrameTimings timings, int citizens)
	{
		EntityDefinition[] roster = new EntityDefinition[citizens];
		for (int i = 0; i < citizens; i++)
		{
			roster[i] = regions.wanderer(
				VARROCK_NORTH,
				new WorldPoint(3221 + i, 3420, 0),
				new WorldPoint(3221 + i, 3418, 0),
				new WorldPoint(3223 + i, 3422, 0),
				512);
		}
		regions.file(VARROCK_NORTH, roster);

		EntityScene scene = new EntityScene(client, regions, config, config.overrides(), timings);
		scene.syncRegions(view);
		return scene;
	}

	/**
	 * A block of citizens packed tightly enough round the player that every one of them
	 * clears the cull radius — so the {@link RenderPolicy#MAX_ACTIVE_OBJECTS} cap is
	 * what decides how many are planned, and {@code planned} and {@code candidates}
	 * stop being the same number.
	 *
	 * <p>Ten to a row from (3212, 3412), which is a 10x9 block for 90 citizens: every
	 * tile is inside region {@code VARROCK_NORTH} and within eight tiles of the player,
	 * so nothing is culled and nothing is off-region.
	 */
	private EntityScene packedSceneWith(FrameTimings timings, int citizens)
	{
		EntityDefinition[] roster = new EntityDefinition[citizens];
		for (int i = 0; i < citizens; i++)
		{
			roster[i] = regions.citizen(VARROCK_NORTH, 3212 + (i % 10), 3412 + (i / 10), 0);
		}
		regions.file(VARROCK_NORTH, roster);

		EntityScene scene = new EntityScene(client, regions, config, config.overrides(), timings);
		scene.syncRegions(view);
		return scene;
	}

	/**
	 * One meter's block out of {@link FrameTimings#toReportText()}.
	 *
	 * <p>Needed rather than convenient: the visibility meter and the model-build meter
	 * both label their companion count "objects active", so a bare
	 * {@code report.contains(..)} on that line can be satisfied by the wrong meter — and
	 * in the two-pass fixture it is, which would make the assertion green against the
	 * exact mutation it exists to catch.
	 */
	/**
	 * Every meter heading is unique, and none is a prefix of another.
	 *
	 * <p>This is what makes {@link #meterSection} safe to call with a prefix, which
	 * several assertions do — the full headings carry parentheticals that get reworded
	 * (the visibility one gained ", excluding model builds" when the meters were split
	 * on 2026-08-29, and every test naming it in full went red on the rename alone,
	 * having caught nothing). A prefix is only a legitimate shorthand while it can name
	 * exactly one section, so that property is asserted rather than assumed.
	 *
	 * <p>The headings are discovered from the report rather than listed here, so adding
	 * a seventh meter is covered without editing this test — and a heading that
	 * accidentally extends another goes red the moment it is added.
	 */
	@Test
	public void theReportNamesEachMeterOnce()
	{
		FrameTimings timings = new FrameTimings(true, true);
		for (FrameTimings.Pass pass : FrameTimings.Pass.values())
		{
			timings.recordElapsed(pass, 500 * MICRO, 1);
		}

		String[] lines = timings.toReportText().split("\n", -1);
		List<String> headings = new ArrayList<>();
		for (int i = 0; i < lines.length - 1; i++)
		{
			// A meter heading is the only "# " line immediately followed by "samples:".
			if (lines[i].startsWith("# ") && lines[i + 1].startsWith("samples:"))
			{
				headings.add(lines[i].substring(2));
			}
		}

		assertEquals("one section per Pass, discovered from the report itself",
			FrameTimings.Pass.values().length, headings.size());
		assertEquals("and no heading may be written twice",
			headings.size(), new HashSet<>(headings).size());

		for (String one : headings)
		{
			for (String other : headings)
			{
				assertFalse("'" + other + "' begins with '" + one + "', so a prefix no"
						+ " longer names one section and meterSection() could silently"
						+ " return the wrong meter",
					!one.equals(other) && other.startsWith(one));
			}
		}
	}

	private static String meterSection(String report, String heading)
	{
		int start = report.indexOf("# " + heading);
		assertTrue("the report has no '" + heading + "' section:\n" + report, start >= 0);

		int end = report.indexOf("\n\n", start);
		return end < 0 ? report.substring(start) : report.substring(start, end);
	}

	private EntityScene sceneWith(FrameTimings timings, int citizens)
	{
		EntityDefinition[] roster = new EntityDefinition[citizens];
		for (int i = 0; i < citizens; i++)
		{
			roster[i] = regions.citizen(VARROCK_NORTH, 3221 + i, 3420, 0);
		}
		regions.file(VARROCK_NORTH, roster);

		EntityScene scene = new EntityScene(client, regions, config, config.overrides(), timings);
		scene.syncRegions(view);
		return scene;
	}

	private static CountingReporter reporter(FrameTimings timings)
	{
		return wireReporter(new CountingReporter(), timings);
	}

	private static RecordingReporter recordingReporter(FrameTimings timings)
	{
		return wireReporter(new RecordingReporter(), timings);
	}

	/**
	 * Everything {@link LivelyCitiesDevReportsPlugin} needs before its cadence and its
	 * shutdown can be called, which is one thing: the stopwatch.
	 *
	 * <p>It is handed over through a real {@link LivelyCitiesPlugin} rather than set on
	 * the reporter directly, because that is exactly how the reporter reaches it in a
	 * client — {@code @PluginDependency} binds the running plugin into the reporter's
	 * injector, and {@code stopwatch()} reads its field. Wiring it any other way here
	 * would leave that hop untested.
	 */
	private static <T extends LivelyCitiesDevReportsPlugin> T wireReporter(T plugin, FrameTimings timings)
	{
		return wireReporter(plugin, timings, true);
	}

	/**
	 * @param processingTicks what the owning plugin says it did with the tick. The
	 * reporter's cadence only counts ticks the plugin actually processed — see
	 * {@link LivelyCitiesDevReportsPlugin#onGameTick} — so a fixture that left this
	 * false would report nothing and every cadence assertion below would pass for the
	 * wrong reason.
	 */
	private static <T extends LivelyCitiesDevReportsPlugin> T wireReporter(
		T plugin, FrameTimings timings, boolean processingTicks)
	{
		LivelyCitiesPlugin owner = new LivelyCitiesPlugin()
		{
			@Override
			boolean processedGameTick()
			{
				return processingTicks;
			}
		};
		owner.frameTimings = timings;
		plugin.livelyCities = owner;
		return plugin;
	}

	/**
	 * The reporter with the report itself taken out — the same seam
	 * {@code DevReportsCacheAuditTest} uses for the cache audit, and for the same
	 * reason: what is under test is when the report runs, not that a file lands on a
	 * real user's disk.
	 */
	private static final class CountingReporter extends LivelyCitiesDevReportsPlugin
	{
		private int reports;

		@Override
		void reportFrameTimings()
		{
			reports++;
		}
	}

	/**
	 * The reporter with the <i>disk</i> taken out but the report left in — one level
	 * below {@link CountingReporter}, which replaces the whole method.
	 *
	 * <p>What that buys is the two things the counting seam is blind to: whether
	 * {@code reportFrameTimings()} decided to write anything at all, and what file name
	 * it chose. Both are decisions the method makes and neither leaves any other trace.
	 */
	private static final class RecordingReporter extends LivelyCitiesDevReportsPlugin
	{
		private final java.util.List<String> fileNames = new java.util.ArrayList<>();
		private final java.util.List<String> texts = new java.util.ArrayList<>();

		@Override
		java.util.concurrent.CompletableFuture<Void> writeReportAsync(
			File outputDir, String fileName, String text, String what)
		{
			fileNames.add(fileName);
			texts.add(text);
			return java.util.concurrent.CompletableFuture.completedFuture(null);
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class LivelyAnimationTest
{
	@Test
	public void resolvesNamesToTheirGameIds()
	{
		// Deliberately spread across the table rather than three neighbours, so
		// a truncated or reordered enum shows up.
		assertEquals(1248, LivelyAnimation.fromName("Fletching").getId());
		assertEquals(808, LivelyAnimation.fromName("HumanIdle").getId());
		assertEquals(10060, LivelyAnimation.fromName("SuzieIdle").getId());
		assertEquals(99, LivelyAnimation.fromName("DwarfMining").getId());
		assertEquals(6539, LivelyAnimation.fromName("WerewolfIdle").getId());
	}

	/**
	 * The one constant this project added rather than inheriting.
	 *
	 * <p>{@code HumanLeanReady} is 916, which
	 * {@code javap -p -constants net.runelite.api.gameval.AnimationID} on the 1.12.36
	 * jar names {@code HUMAN_LEAN_READY} — the pose rather than
	 * {@code HUMAN_LEAN = 915}, which is the transition into it. Pinned here because
	 * it is the only entry in the table with no upstream provenance (see
	 * {@code NOTICE}) and because a {@code _READY} id is the difference between a
	 * loopable idle and an animation that plays once and stops.
	 */
	@Test
	public void theOneLocallyAddedAnimationIsTheHumanLeanReadyPose()
	{
		assertNotNull(LivelyAnimation.fromName("HumanLeanReady"));
		assertEquals("gameval AnimationID.HUMAN_LEAN_READY",
			916, LivelyAnimation.fromName("HumanLeanReady").getId());
		assertNull("HUMAN_LEAN (915) is the transition, and is deliberately not in the table",
			byId(915));
	}

	private static LivelyAnimation byId(int id)
	{
		for (LivelyAnimation animation : LivelyAnimation.values())
		{
			if (animation.getId() == id)
			{
				return animation;
			}
		}
		return null;
	}

	@Test
	public void unknownAndEmptyNamesResolveToNullInsteadOfThrowing()
	{
		assertNull(LivelyAnimation.fromName(null));
		assertNull(LivelyAnimation.fromName(""));
		assertNull(LivelyAnimation.fromName("   "));
		assertNull(LivelyAnimation.fromName("PolishingTheBrasswork"));
		// Case matters: the dataset uses the exact constant names.
		assertNull(LivelyAnimation.fromName("fletching"));
	}

	@Test
	public void tolerateSurroundingWhitespace()
	{
		assertEquals(LivelyAnimation.Fletching, LivelyAnimation.fromName("  Fletching  "));
	}

	/**
	 * The load-bearing one. The dataset stores animations by name, so a name it
	 * uses that the enum does not carry means a citizen renders frozen — and
	 * nothing else in the build would notice.
	 */
	@Test
	public void everyAnimationNameInTheShippedDatasetResolves()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());

		List<String> missing = new ArrayList<>();
		TreeSet<String> seen = new TreeSet<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);

			for (EntityDefinition entity : region.getEntities())
			{
				// A definition only carries a resolved animation, so an
				// unresolved name would have shown up as null here. Cross-check
				// against the raw name via the enum directly.
				if (entity.getIdleAnimation() != null)
				{
					seen.add(entity.getIdleAnimation().name());
				}
				if (entity.getMoveAnimation() != null)
				{
					seen.add(entity.getMoveAnimation().name());
				}
			}
		}

		for (String name : ShippedAnimationNames.all())
		{
			if (LivelyAnimation.fromName(name) == null)
			{
				missing.add(name);
			}
		}

		assertTrue("animation names used by the dataset but absent from the enum: " + missing,
			missing.isEmpty());

		// Sanity: 54 distinct idleAnimation names and 19 distinct moveAnimation
		// names across the 27 files, overlapping on BeeIdle alone -> 72 distinct.
		// A drop here means definitions stopped resolving names.
		//
		// The history, because a number that only ever moves without explanation is
		// not evidence of anything. It was 81 before the six cameos, which brought in
		// Alching, Flex and HumanLeanReady as idle poses; the other three (Fishing,
		// Think, HumanIdle — and LectorIdle) were already in use elsewhere in the
		// dataset. It went 84 -> 89 when the video pass corrected the wrong gaits and
		// re-posed seven figures: the moves gained GoblinWalk, PenguinWalk and
		// KittenWalk (+3), the idles gained DrunkPlayerReady, VarrockTrampReady,
		// NervousIdle, SlapHead, MageReady, ArmsCrossedReady and HumanSmugIdle (+7)
		// and lost HalfLayingDown, CurledUp, Crying, Alching and Flex, which nothing
		// else used (-5). It stayed at 89 through the skeleton pass, which was
		// arithmetic rather than luck: the idles lost ChildIdle and gained
		// GnomeChildReady (0), the moves lost ChildWalk and gained GnomeChildWalk (0).
		//
		// 89 -> 72 is the nine-city cut on 2026-08-24, and it is the first move that
		// is subtraction rather than editing: seventeen names left because every
		// record using them left. They were the animal and monster vocabulary of the
		// fifteen removed places — DwarfMining, GoblinFishIdle/Walk, MoleIdle/Walk,
		// MonkeyIdle/Walk, PuffinIdle/Walk, SwanIdle/Walk, TanglerootIdle/Walk,
		// TrollIdle/Walk and WerewolfIdle/Walk. HumanIdle stopped being an overlap
		// because the one record that carried it as a *move* — "Ol' Tony" in 9273,
		// Piscatoris — went with them; it is still a widely-used idle.
		assertEquals("distinct animation names in the dataset", 72, ShippedAnimationNames.all().size());
		assertEquals("distinct animations resolved onto definitions", 72, seen.size());
	}

	/**
	 * The 23 animation ids RuneLite's core <b>Animation Smoothing</b> plugin
	 * refuses to interpolate, copied out of the 1.12.36 bytecode.
	 *
	 * <p>{@code AnimationSmoothingPlugin.isAnimationInterpolatable(int)} is a
	 * {@code lookupswitch} over exactly these, returning {@code false} for them and
	 * {@code true} for everything else — i.e. a <b>denylist</b>. That matters
	 * because it is the opposite of a whitelist, and the difference decides whether
	 * this plugin's citizens can be smoothed at all.
	 */
	private static final int[] SMOOTHING_DENYLIST = {
		244, 367, 1051, 3558, 4519, 4652, 5530, 5531, 5583, 5857, 6495, 6566,
		6818, 7898, 8266, 8267, 8270, 8271, 8499, 8977, 9450, 9493, 11291,
	};

	/**
	 * Whether the citizens can be smoothed at all — and the answer is yes, subject
	 * to the user having the plugin on.
	 *
	 * <p>The mechanism, disassembled from 1.12.36 rather than assumed:
	 * {@code AnimationController.getPackedFrame()} asks
	 * {@code client.getAnimationInterpolationFilter()}, and only packs the
	 * interpolation bits when that filter is non-null <i>and</i> returns true for
	 * the animation's id. The only thing in RuneLite that installs such a filter is
	 * the core Animation Smoothing plugin, which is {@code enabledByDefault =
	 * false}; the filter it installs is the denylist above. So:
	 *
	 * <ul>
	 *   <li>Animation Smoothing off — the filter is null, and nothing at all is
	 *       interpolated, ours included. Not something this plugin can change, and
	 *       not something it should: it is the same for every real NPC.</li>
	 *   <li>Animation Smoothing on — every id is interpolated unless it is on the
	 *       denylist, and this test is what says none of ours is.</li>
	 * </ul>
	 *
	 * <p>It is pinned as a test rather than written in a comment because the
	 * denylist is somebody else's file: an id added to it upstream that collides
	 * with one of ours would silently stop that citizen being smoothed, and this is
	 * the only place that would notice.
	 */
	@Test
	public void noShippedAnimationIsOnTheSmoothingDenylist()
	{
		List<String> clashes = new ArrayList<>();

		for (LivelyAnimation animation : LivelyAnimation.values())
		{
			for (int denied : SMOOTHING_DENYLIST)
			{
				if (animation.getId() == denied)
				{
					clashes.add(animation.name() + " (id " + denied + ")");
				}
			}
		}

		assertTrue("animation(s) RuneLite's Animation Smoothing plugin will not interpolate: "
			+ clashes, clashes.isEmpty());

		// The denylist itself, so a copy that lost entries cannot make this pass
		// by being empty.
		assertEquals("the 1.12.36 denylist has 23 entries", 23, SMOOTHING_DENYLIST.length);
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Named;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The developer-only half of this plugin's diagnostics: the two reports, and the disk
 * they are written to.
 *
 * <h2>Why it is a second plugin, in the test source set</h2>
 *
 * <p>Filesystem I/O in {@code src/main} costs a hub submission its automated review.
 * riktenx, on <a href="https://github.com/runelite/plugin-hub/pull/12366">plugin-hub#12366</a>:
 * "file i/o will make your plugin require manually review. if you can not use it your
 * plugin can be automatically reviewed." Neither of the two things that wrote a file
 * here is reachable by anybody who installs this plugin — {@code CacheIdAudit} and
 * {@link FrameTimings} are each gated behind {@code --developer-mode} <i>and</i> a JVM
 * system property — so the shipped jar was paying manual-review latency for capabilities
 * its users cannot invoke.
 *
 * <p>Deleting them was one option. The other, and the one riktenx names on
 * <a href="https://github.com/runelite/plugin-hub/pull/13208">plugin-hub#13208</a>, is
 * this: "you can either add a separate debug plugin in the test source set (which won't
 * ship with your plugin and won't get looked at but you can use it during development)
 * or just remove it". {@code src/test/java} is not packaged into the hub's jar, and both
 * {@code ./gradlew runWithTimings} and {@code ./gradlew auditCacheIds} already run on
 * {@code sourceSets.test.runtimeClasspath} — so this class is on the classpath of
 * exactly the two launches that want it and of nothing else. The dev capability is
 * unchanged; it simply stopped shipping.
 *
 * <h2>What stayed behind</h2>
 *
 * <p>The <i>measuring</i> and the <i>auditing</i>, because neither is file I/O.
 * {@link FrameTimings} still owns the histograms, the cadence and
 * {@link FrameTimings#toReportText()}; {@code CacheIdAudit} still owns the cache walk
 * and {@code CacheIdAudit.Report.toReportText()}. Both hand out a finished
 * {@code String}. Turning a {@code String} into a file is this class's job and
 * {@link ReportWriter}'s, and neither exists in the shipped jar.
 *
 * <p>That split is also why {@code src/main} has no {@code if} left over pretending a
 * file might be written. There is no sink to install, no nullable writer, no
 * "reporting enabled" branch: the plugin that reports is simply not loaded unless
 * somebody launched a developer client from this repo's test classpath.
 *
 * <h2>How it reaches the stopwatch</h2>
 *
 * <p>{@link PluginDependency} makes RuneLite build this plugin's injector as a
 * <i>child</i> of {@link LivelyCitiesPlugin}'s (see {@code PluginManager.instantiate}:
 * with one dependency the parent injector is {@code deps.get(0).getInjector()}), and
 * bind that plugin instance into it. So {@link #livelyCities} is the running plugin,
 * and {@link #stopwatch()} reads the very {@link FrameTimings} singleton
 * {@code EntityScene} is measuring into.
 *
 * <p><b>Deliberately not {@code @Inject FrameTimings}.</b> That would rely on Guice
 * hoisting the just-in-time binding into the root injector so both plugins share one
 * instance — which it does do, but a mistake there produces a report full of zeros
 * rather than an error, and a silently-wrong instrument is the one failure this whole
 * class of tooling exists to prevent. Going through the plugin instance cannot be
 * wrong: if the dependency were unmet, RuneLite throws
 * {@code PluginInstantiationException} at load and nothing starts.
 *
 * <p>{@link #regionDataLoader} <i>is</i> injected directly, and the asymmetry is the
 * explanation: it is a stateless reader of classpath resources, so a second instance
 * would give identical answers. The stopwatch is state, and there must be exactly one.
 */
@PluginDependency(LivelyCitiesPlugin.class)
@PluginDescriptor(
	name = "Lively Cities dev reports",
	description = "Developer-only: writes the Lively Cities frame-timing and cache-id reports",
	tags = {"developer", "lively", "cities"},
	developerPlugin = true,
	loadInSafeMode = false
)
public class LivelyCitiesDevReportsPlugin extends Plugin
{
	/**
	 * Set on {@code ./gradlew auditCacheIds} (never on {@code ./gradlew run} or
	 * {@code ./gradlew test}) to ask {@link #runCacheAudit()} to run once at startup.
	 * Read with {@link Boolean#getBoolean}, a plain JVM system property — no new
	 * argument parsing, no reflection.
	 *
	 * <p>Checked in addition to {@link #developerMode}, not instead of it, and both are
	 * still checked even though this class no longer ships: the audit is a real
	 * client-cache walk over every id the dataset references, and an ordinary
	 * {@code ./gradlew run} session must not pay for it.
	 */
	static final String CACHE_AUDIT_SYSTEM_PROPERTY = "livelycities.validateCacheIds";

	/** Under {@code ~/.runelite/lively-cities/} — see {@link ReportWriter}. */
	static final String CACHE_AUDIT_REPORT_FILE_NAME = "model-id-audit.txt";

	/** Under {@code ~/.runelite/lively-cities/} — see {@link ReportWriter}. */
	static final String FRAME_REPORT_FILE_NAME = "frame-timings.txt";

	/**
	 * Plain slf4j rather than Lombok's {@code @Slf4j}: Lombok is wired into this build
	 * for the main source set only ({@code compileOnly} / {@code annotationProcessor}),
	 * and adding {@code testAnnotationProcessor} purely for one logger would change the
	 * dependency block a hub reviewer reads for a class that never reaches them.
	 */
	private static final Logger log = LoggerFactory.getLogger(LivelyCitiesDevReportsPlugin.class);

	/**
	 * The running {@link LivelyCitiesPlugin}, bound into this plugin's parent injector
	 * by {@link PluginDependency}. Read only for {@link #stopwatch()}.
	 */
	@Inject
	LivelyCitiesPlugin livelyCities;

	@Inject
	Client client;

	@Inject
	ClientThread clientThread;

	@Inject
	RegionDataLoader regionDataLoader;

	/**
	 * True when the client was launched with {@code --developer-mode}. Bound by
	 * {@code RuneLiteModule} for every launch, so this is always resolvable and defaults
	 * to {@code false} when a test constructs this plugin directly instead of through
	 * Guice.
	 */
	@Inject
	@Named("developerMode")
	boolean developerMode;

	/**
	 * The one {@link FrameTimings} in the client — the instance {@code EntityScene}
	 * records into. See the class javadoc for why it is fetched this way.
	 *
	 * <p>Package-private and non-final so a test can hand over its own meter without
	 * standing up a {@link LivelyCitiesPlugin}.
	 */
	FrameTimings stopwatch()
	{
		return livelyCities.frameTimings;
	}

	@Override
	protected void startUp()
	{
		// Both flags, deliberately: developerMode alone is true for every ordinary
		// `./gradlew run`, and the cache id audit is a deliberate, on-demand action.
		if (developerMode && Boolean.getBoolean(CACHE_AUDIT_SYSTEM_PROPERTY))
		{
			clientThread.invoke(this::runCacheAudit);
		}

		if (stopwatch().isEnabled())
		{
			// Said out loud, because a measurement running silently is a measurement
			// somebody forgets is running — and because "is it actually on?" is the
			// first question when the report file turns out to be empty.
			log.info("Lively Cities: frame timings are on ({} is set) — a summary every {} game "
					+ "tick(s), and a report in ~/.runelite/lively-cities/{}",
				FrameTimings.SYSTEM_PROPERTY, FrameTimings.REPORT_INTERVAL_TICKS,
				FRAME_REPORT_FILE_NAME);
		}
	}

	/**
	 * The cache-backed half of the durability tooling: walks every distinct model id,
	 * merged-object id and animation id {@code RegionData/*.json} references and asks
	 * the live client whether each one still resolves — see {@code CacheIdAudit}'s
	 * javadoc for why this cannot run in the normal test suite.
	 *
	 * <p>Runs once, from the client thread (required — every model/animation load in
	 * this plugin goes through the client), and only ever on demand: see
	 * {@link #CACHE_AUDIT_SYSTEM_PROPERTY}.
	 *
	 * <p>Package-private and non-final so a test can override it and count the calls —
	 * the developer-mode gate above is what is under test there, not the audit's own
	 * logic, which {@code CacheIdAuditTest} covers directly against {@code FakeClient}.
	 */
	void runCacheAudit()
	{
		log.info("Lively Cities: {} is set, running the cache id audit", CACHE_AUDIT_SYSTEM_PROPERTY);

		CacheIdAudit.DatasetIds dataset = CacheIdAudit.collect(regionDataLoader);
		CacheIdAudit.Report report = CacheIdAudit.run(client, dataset);

		log.info("Lively Cities cache id audit: {} model id(s) checked ({} failing), "
				+ "{} merged-object id(s) checked ({} failing), {} animation id(s) checked "
				+ "({} failing, {} known permanently null)",
			dataset.modelIds.size(), report.failingModelIds.size(),
			dataset.mergedObjectIds.size(), report.failingMergedObjectIds.size(),
			dataset.animationIdsByName.size(), report.failingAnimations.size(),
			report.knownPermanentNullAnimations.size());

		// Disk I/O never happens on the client thread. The text is built here, where
		// the report was, so what crosses the thread boundary is a finished snapshot
		// rather than an object still holding collections.
		writeReportAsync(reportDir(), CACHE_AUDIT_REPORT_FILE_NAME, report.toReportText(),
			"cache id audit");
	}

	/**
	 * The frame-timing cadence: one info line and one file, every
	 * {@link FrameTimings#REPORT_INTERVAL_TICKS} game ticks.
	 *
	 * <p><b>Priority, not registration order.</b> RuneLite's {@code EventBus} sorts
	 * subscribers by {@code Subscribe.priority()}, highest first, so a negative priority
	 * puts this after {@link LivelyCitiesPlugin#onGameTick} — which is where the
	 * visibility pass this is measuring actually happens. The tick that triggers a
	 * report is therefore a tick the report already includes, exactly as it was when
	 * both halves lived in one class.
	 *
	 * <p><b>And only ticks the plugin actually processed count.</b> Before the split
	 * this call was the last statement of {@code LivelyCitiesPlugin.tick()}, <i>after</i>
	 * its "no player or no world view yet" early return, so a tick that did no work
	 * never advanced the cadence. Calling it unconditionally here would quietly change
	 * the population the report describes from "ticks the plugin processed" to "ticks
	 * that happened" — and with Lively Cities toggled off and this reporter left on, the
	 * 300-tick cadence would keep firing and rewriting the file out of stale samples.
	 * {@link LivelyCitiesPlugin#processedGameTick()} is the seam that keeps the old
	 * meaning, and the {@code -1f} priority above is what makes it readable: the plugin
	 * has already run and recorded its answer by the time this asks.
	 */
	@Subscribe(priority = -1f)
	public void onGameTick(GameTick event)
	{
		if (!livelyCities.processedGameTick())
		{
			return;
		}

		if (stopwatch().onGameTick())
		{
			reportFrameTimings();
		}
	}

	/**
	 * The tail of the session, on the way out.
	 *
	 * <p>Non-blocking, per {@code AGENTS.md} — the periodic report is the one to rely on
	 * if the client is killed rather than closed. Nothing here touches
	 * {@link LivelyCitiesPlugin}'s scene, so it does not matter which of the two plugins
	 * RuneLite shuts down first.
	 */
	@Override
	protected void shutDown()
	{
		reportFrameTimings();
	}

	/**
	 * Builds the frame report and hands it to a background thread.
	 *
	 * <p>The text is built here, on the client thread, and written on a background one:
	 * disk I/O never happens on the client thread, and a report handed over as finished
	 * text is a snapshot rather than a view of counters that are still moving.
	 *
	 * <p>Unreachable for an ordinary user twice over: this class is not in the shipped
	 * jar at all, and {@link FrameTimings#onGameTick()} returns false forever unless both
	 * halves of its gate are set.
	 *
	 * <p><b>Nothing is written when there is nothing to say.</b> {@link #shutDown()}
	 * calls this unconditionally, so without the {@code hasSamples()} guard a client
	 * that was started and closed without the stopwatch ever taking a sample would
	 * replace a real report with a file that says "no samples" three times over.
	 *
	 * <p>Package-private and non-final so a test can override it and count the calls.
	 * What needs asserting is <i>when</i> this runs, and under which file name
	 * ({@link #writeReportAsync}); that it can write a file is {@code ReportWriterTest}'s,
	 * against a temp directory rather than the real {@code ~/.runelite}.
	 */
	void reportFrameTimings()
	{
		FrameTimings frameTimings = stopwatch();
		if (!frameTimings.hasSamples())
		{
			return;
		}

		log.info(frameTimings.summaryLine());

		writeReportAsync(reportDir(), FRAME_REPORT_FILE_NAME, frameTimings.toReportText(),
			"frame timings");
	}

	/**
	 * Hands one finished report to a background thread.
	 *
	 * <p>Package-private and non-final so a test can run it inline and see what it was
	 * handed — the same seam, for the same reason, as {@link #reportFrameTimings()} and
	 * {@link #runCacheAudit()}, one level further down. It exists because the
	 * <b>file name</b> is the one argument at these call sites that nothing else could
	 * check. {@link ReportWriter} has been parameterised by file name since it grew a
	 * second caller, so each caller names its own constant — and passing
	 * {@link #CACHE_AUDIT_REPORT_FILE_NAME} from the frame-timing path compiles,
	 * type-checks, and silently makes the frame report overwrite the model id audit.
	 *
	 * @param what what to call it in the log line, so a failure names the report that
	 *             failed rather than "a report"
	 */
	CompletableFuture<Void> writeReportAsync(File outputDir, String fileName, String text, String what)
	{
		return CompletableFuture.runAsync(() -> writeReport(outputDir, fileName, text, what));
	}

	/**
	 * Writes one finished report. Background thread only — see {@link ReportWriter}.
	 */
	private static void writeReport(File outputDir, String fileName, String text, String what)
	{
		try
		{
			File file = ReportWriter.write(outputDir, fileName, text);
			log.info("Lively Cities {} report written to {}", what, file);
		}
		catch (IOException e)
		{
			log.warn("Lively Cities {}: could not write the report under {}", what, outputDir, e);
		}
	}

	/**
	 * The plugin's own subdirectory of {@code ~/.runelite}.
	 *
	 * <p>Resolved per call rather than held in a static, because
	 * {@code RuneLite.RUNELITE_DIR} is a static that a test never wants written to and
	 * that neither report is on a hot path for.
	 */
	private static File reportDir()
	{
		return new File(RuneLite.RUNELITE_DIR, "lively-cities");
	}
}

package com.matthewmariner.livelycities;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The one part of the panel that is Swing, exercised without a windowing system.
 *
 * <p>Every <em>decision</em> the panel draws is somewhere else and already under test —
 * {@link PanelModel} for the rows and the numbers, {@link CitizenDirectory} for the
 * names, {@code LivelyCitiesPluginLifecycleTest} for what a click writes. What is left
 * is wiring, and wiring is exactly the part that fails invisibly: a mouse listener on
 * the wrong component, a label that is built and never updated, a filter that hides the
 * row it was supposed to keep. None of that turns any other test red.
 *
 * <p>Headless throughout. {@code JPanel} and its children construct fine without a
 * display — it is {@code Frame} and {@code Window} that do not — so this runs on a build
 * machine, which is the only reason it is allowed to exist. Nothing here paints.
 *
 * <p><b>It walks the component tree rather than adding accessors to the panel.</b> A
 * {@code getCityCardFor(City)} written for a test is a seam that makes the test pass by
 * construction; reading the labels that are actually in the tree is asking the same
 * question a user's eyes ask.
 */
public class LivelyCitiesPanelTest
{
	private static final WorldPoint IN_VARROCK = new WorldPoint(3225, 3360, 0);

	private final FakeConfig config = new FakeConfig();
	private final CitizenDirectory directory =
		new CitizenDirectory(new RegionDataLoader(TestGson.injected()));

	// --- what it draws ---------------------------------------------------------

	/**
	 * The nine places are on it, with the dataset's counts, before anything has been
	 * pushed to it at all.
	 *
	 * <p>The cards are built in the constructor and repainted from each model, so the
	 * first draw happens with no model — and a panel that showed nothing until the first
	 * game tick would be blank for up to 600ms every time it is opened.
	 */
	@Test
	public void everyPlaceIsOnThePanel()
	{
		LivelyCitiesPanel panel = panel();
		panel.accept(loggedOut(config));
		drain();

		List<String> text = labels(panel);
		for (City city : City.values())
		{
			assertTrue(city.getLabel() + " has no card: " + text, text.contains(city.getLabel()));
		}

		assertTrue("Varrock's roster has to be on its card: " + text,
			text.contains("71 citizens"));
		assertTrue("and Edgeville's, which is a different number",
			text.contains("22 citizens"));
	}

	/**
	 * The live figures reach the labels, and the card for the city the player is in says
	 * so.
	 *
	 * <p>This is the whole claim of the panel: numbers a settings screen cannot show.
	 * Asserted on the rendered text rather than on the model, because the model already
	 * has its own test and the failure being guarded here is a card that was built and
	 * then never updated.
	 */
	@Test
	public void theLiveNumbersReachTheCards()
	{
		java.util.EnumMap<City, Integer> active = new java.util.EnumMap<>(City.class);
		active.put(City.VARROCK, 34);
		active.put(City.GRAND_EXCHANGE, 7);

		LivelyCitiesPanel panel = panel();
		panel.accept(PanelModel.of(IN_VARROCK, new SceneCensus(41, 190, 12, 2, active),
			config, Collections.emptySet(), Collections.emptySet(), directory));
		drain();

		List<String> text = labels(panel);
		assertTrue("Varrock's card has to carry both numbers and the marker: " + text,
			text.contains("71 citizens · 34 on screen · you are here"));
		assertTrue("and a city a region away still reports what is up there",
			text.contains("24 citizens · 7 on screen"));
		assertTrue("the header names where the player is", text.contains("Varrock"));
		assertTrue("and the total", text.contains("41"));
		assertTrue("with the breakdown under it",
			text.contains("12 walking · 2 talking · 190 loaded"));
	}

	/**
	 * A card follows its city's checkbox, and only its own.
	 *
	 * <p>The panel repaints nine cards from a nine-row list in a loop, which is the shape
	 * that makes an off-by-one plausible. Nine different labels is what would notice.
	 */
	@Test
	public void eachCardShowsItsOwnCitysState()
	{
		for (City target : City.values())
		{
			LivelyCitiesPanel panel = panel();
			panel.accept(PanelModel.of(IN_VARROCK, SceneCensus.EMPTY,
				new FakeConfig().disableOnly(target), Collections.emptySet(),
				Collections.emptySet(), directory));
			drain();

			assertEquals("exactly one card may read 'off' when one city is unticked",
				1, count(labels(panel), "off"));
			assertEquals("and eight read 'on'", City.values().length - 1,
				count(labels(panel), "on"));
		}
	}

	/**
	 * <b>Opening the panel at the login screen shows the panel, not nine empty outlines.</b>
	 *
	 * <p>Readings arrive through {@code accept}, {@code accept} is driven by
	 * {@code refreshPanel}, and {@code refreshPanel} is driven by {@code GameTick} — which
	 * the client does not post while there is no world. So the whole of this test is the
	 * thing that used to be missing: {@code onActivate} with nothing ever pushed. The panel
	 * shipped with {@code model} null in that case and {@link LivelyCitiesPanel}'s null
	 * branch drew nine bordered cards with no name, no on/off and no counts, no density
	 * chip selected, and an overrides section with no children in it at all — not even its
	 * empty-state sentence — until the player logged in.
	 *
	 * <p>Asserted through the labels rather than through the model, because the model was
	 * never the part that was missing: {@code PanelModel.loggedOut} was complete, correct
	 * and covered by six tests, with no caller anywhere in {@code src/main}.
	 */
	@Test
	public void thePanelHasContentBeforeTheFirstGameTick()
	{
		LivelyCitiesPanel panel = panel();

		// No accept(). This is the login screen: nothing has been pushed and nothing will
		// be until there is a world.
		panel.onActivate();

		List<String> text = labels(panel);
		for (City city : City.values())
		{
			assertTrue(city.getLabel() + " has no card: " + text, text.contains(city.getLabel()));
		}

		assertEquals("every card has to say whether its city is on",
			City.values().length, count(text, "on"));
		assertTrue("with the dataset's own count on it: " + text, text.contains("71 citizens"));
		assertTrue("and Edgeville's, which is a different number", text.contains("22 citizens"));
		assertTrue("the overrides section says something rather than nothing: " + text,
			text.contains("Nobody is hidden or muted."));
		assertTrue("and its header counts them",
			text.stream().anyMatch(line -> line.endsWith("Hidden and muted (0)")));
	}

	/**
	 * And the hidden list is the profile's, not an empty one.
	 *
	 * <p>Hiding and muting are stored in the config, so they are as true at the login
	 * screen as anywhere. A pre-tick reading that emptied them would put "Hidden and muted
	 * (0)" over "Nobody is hidden or muted." in front of somebody who had hidden three
	 * citizens — which is worse than the blank it replaces, because it is a confident
	 * answer rather than an absent one, and it would sit there until they logged in.
	 */
	@Test
	public void theLoginScreenPanelStillKnowsWhoIsHidden()
	{
		FakeRegions regions = new FakeRegions();
		FakeConfig config = new FakeConfig();
		config.overrides().hide(regions.citizen(12852, 3225, 3360, 0));
		config.overrides().mute(regions.talker(12852, 3226, 3360, "Busy today."));

		LivelyCitiesPanel panel = new LivelyCitiesPanel(plugin(config));
		panel.onActivate();

		List<String> text = labels(panel);
		assertTrue("the header has to carry the real count: " + text,
			text.stream().anyMatch(line -> line.endsWith("Hidden and muted (2)")));
		assertEquals("with the way back for the hidden one", 1, actionsLabelled(panel, "show").size());
		assertEquals("and for the muted one", 1, actionsLabelled(panel, "unmute").size());
	}

	// --- the search box --------------------------------------------------------

	/**
	 * Typing filters the cards, and clearing brings them all back.
	 *
	 * <p>Driven through the document, which is what a keystroke reaches — the panel
	 * listens on it rather than on key events, so this is the same path a typed
	 * character takes.
	 */
	@Test
	public void theSearchBoxFiltersTheCards() throws Exception
	{
		LivelyCitiesPanel panel = panel();
		panel.accept(loggedOut(config));
		drain();

		assertEquals("every card starts visible",
			City.values().length, visibleCards(panel));

		type(panel, "var");
		assertEquals("only Varrock matches 'var'", 1, visibleCards(panel));

		type(panel, "");
		assertEquals("and clearing brings them back",
			City.values().length, visibleCards(panel));

		type(panel, "zzzz");
		assertEquals("a query nothing matches hides them all", 0, visibleCards(panel));
	}

	/**
	 * A filtered-out card takes its spacer with it.
	 *
	 * <p>The cards are laid out as card, strut, card, strut. The filter hid the card and
	 * left the strut, and a strut's height is a fixed few pixels rather than something its
	 * neighbours decide — so filtering to one place left the matching card sitting on top
	 * of eight 4px voids. Cosmetic, and invisible to every other assertion in this file,
	 * because the panel really was showing exactly one city.
	 *
	 * <p>Counted out of the container the cards are in rather than by measuring pixels:
	 * nothing here is laid out, so a height would be zero whatever the truth was.
	 */
	@Test
	public void aFilteredOutCardTakesItsSpacerWithIt() throws Exception
	{
		LivelyCitiesPanel panel = panel();
		panel.accept(loggedOut(config));
		drain();

		Container cards = labelReading(panel, City.VARROCK.getLabel()).getParent().getParent();
		assertEquals("nine cards and nine struts to start with",
			City.values().length * 2, showingChildren(cards));

		type(panel, "var");
		assertEquals("one card and one strut, not one card and nine struts",
			2, showingChildren(cards));

		type(panel, "zzzz");
		assertEquals("and a query nothing matches leaves nothing at all",
			0, showingChildren(cards));

		type(panel, "");
		assertEquals("clearing brings the struts back with the cards",
			City.values().length * 2, showingChildren(cards));
	}

	// --- the hidden-and-muted list --------------------------------------------

	/**
	 * A restore lands on the right citizen.
	 *
	 * <p><b>The reason this file exists.</b> The rows are built in a loop and each one
	 * closes over its own uuid; a listener that closed over the loop variable, or over
	 * the last row's uuid, would restore the wrong person — and every other test in the
	 * suite would stay green, because the model, the overrides and the writer are all
	 * behaving correctly. Three rows rather than one, and the middle one clicked, so a
	 * listener that always fired for the first or the last is caught.
	 */
	@Test
	public void clickingRestoreOnARowRestoresThatRow()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition first = regions.citizen(12852, 3225, 3360, 0);
		EntityDefinition second = regions.citizen(12852, 3226, 3360, 0);
		EntityDefinition third = regions.citizen(12852, 3227, 3360, 0);

		FakeConfig config = new FakeConfig();
		LivelyCitiesPlugin plugin = plugin(config);
		config.overrides().hide(first);
		config.overrides().hide(second);
		config.overrides().hide(third);

		LivelyCitiesPanel panel = new LivelyCitiesPanel(plugin);
		panel.accept(model(config, uuids(first, second, third), Collections.emptySet()));
		drain();

		List<JLabel> actions = actionsLabelled(panel, "show");
		assertEquals("one restore per hidden citizen", 3, actions.size());

		// The rows are sorted, so which one is in the middle is a fact rather than a
		// guess — the three fixture uuids differ only in their last digit and all three
		// citizens are unplaceable by the real directory, so they sort by uuid.
		UUID middle = sortedUuids(first, second, third).get(1);
		click(actions.get(1));

		assertEquals("two still hidden", 2, config.overrides().hiddenUuids().size());
		assertFalse("and the one clicked is the one restored",
			config.overrides().hiddenUuids().contains(middle));
	}

	/**
	 * A citizen who is both hidden and muted gets one row with both restores on it.
	 *
	 * <p>Two rows would be two entries with the same name and no sign they are one
	 * person; one row with one restore would leave the other override with no way back
	 * at all, which is the defect this whole list exists to fix.
	 */
	@Test
	public void aCitizenWhoIsBothHiddenAndMutedGetsBothRestores()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition someone = regions.talker(12852, 3225, 3360, "Busy today.");

		FakeConfig config = new FakeConfig();
		LivelyCitiesPlugin plugin = plugin(config);
		config.overrides().hide(someone);
		config.overrides().mute(someone);

		LivelyCitiesPanel panel = new LivelyCitiesPanel(plugin);
		panel.accept(model(config, uuids(someone), uuids(someone)));
		drain();

		assertEquals("one row", 1, actionsLabelled(panel, "show").size());
		assertEquals("with both ways back on it", 1, actionsLabelled(panel, "unmute").size());
		assertTrue("and a subtitle that says so: " + labels(panel),
			labels(panel).stream().anyMatch(text -> text.endsWith("hidden and muted")));

		click(actionsLabelled(panel, "unmute").get(0));
