	// --- helpers -------------------------------------------------------------

	private LivelyCitiesPlugin plugin(EntityScene scene)
	{
		return plugin(scene, new FakeConfig());
	}

	/**
	 * The plugin with every injected collaborator wired to a fake.
	 *
	 * <p>{@code overlayRegistry} and {@code configWriter} exist as interfaces
	 * precisely so this method can exist: {@code OverlayManager} and
	 * {@code ConfigManager} both have private constructors in 1.12.36, so a plugin
	 * holding either directly is a plugin no test can construct — and this file
	 * exists because that is exactly what happened once already.
	 */
	private LivelyCitiesPlugin plugin(EntityScene scene, FakeConfig config)
	{
		LivelyCitiesPlugin plugin = new LivelyCitiesPlugin();
		plugin.client = client;
		plugin.clientThread = clientThread;
		plugin.scene = scene;
		plugin.overlayRegistry = overlays;
		plugin.chatterOverlay = new ChatterOverlay(plugin, client, scene, config);
		plugin.citizenMenu = new CitizenMenu(client, scene, config.overrides());
		plugin.overrides = config.overrides();
		plugin.configWriter = config.writer();
		plugin.config = config;
		plugin.sidePanel = sidebar;

		// A directory over a dataset with no files in it: every city reads zero citizens
		// and no uuid resolves. That is the right default for a lifecycle test — the
		// numbers are CitizenDirectoryTest's subject, and a fixture that loaded the real
		// 27 files would make every test in this class pay for a parse it never looks at.
		plugin.directory = new CitizenDirectory(new FakeRegions());

		// A stopwatch that measures nothing. Off is what a shipped client gets, so it
		// is what every test here should get; the measuring itself is FrameTimingsTest's.
		plugin.frameTimings = FrameTimings.off();
		return plugin;
	}

	/**
	 * Draws one frame at a given game cycle and hands back the fraction the plugin
	 * gave the scene.
	 *
	 * <p>{@code tickFraction()} is private, and deliberately: the fraction is not
	 * a fact about the plugin, it is the argument it passes. Asking for it through
	 * the frame handler is asking the question the citizens ask.
	 */
	private float fractionAt(LivelyCitiesPlugin plugin, RecordingScene scene, int gameCycle)
	{
		client.setGameCycle(gameCycle);
		int before = scene.fractions.size();
		plugin.onBeforeRender(new BeforeRender());
		assertEquals("the frame handler has to have run", before + 1, scene.fractions.size());
		return scene.fractions.get(scene.fractions.size() - 1);
	}

	private static ConfigChanged configChanged(String group, String key)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(group);
		event.setKey(key);
		return event;
	}

	private static ConfigChanged configChanged(String group, String key, @Nullable String newValue)
	{
		ConfigChanged event = configChanged(group, key);
		event.setNewValue(newValue);
		return event;
	}

	/**
	 * {@link CitizenMenu} with its three entry points counted and none of them doing
	 * anything.
	 *
	 * <p>Same shape as {@link RecordingScene}, and for the same reason: the question
	 * here is whether the plugin routes the events, not what the menu does with them
	 * — {@code CitizenMenuTest} answers that against the real one.
	 */
	private static final class CountingMenu extends CitizenMenu
	{
		private int opened;
		private int clicked;
		private int forgotten;

		private CountingMenu(net.runelite.api.Client client, EntityScene scene, CitizenOverrides overrides)
		{
			super(client, scene, overrides);
		}

		@Override
		void onMenuOpened(MenuOpened event)
		{
			assertNotNull(event);
			opened++;
		}

		@Override
		void onMenuOptionClicked(MenuOptionClicked event)
		{
			assertNotNull(event);
			clicked++;
		}

		@Override
		void forget()
		{
			forgotten++;
		}
	}

	/**
	 * The overlay manager, as two lists.
	 *
	 * <p>Registered rather than counted, so "shutDown removes the same overlay
	 * startUp added" is answerable — an overlay left registered draws forever, which
	 * is the overlay-shaped version of the leaked-active-object bug this plugin
	 * already guards against.
	 */
	private static final class RecordingOverlays implements OverlayRegistry
	{
		private final List<Overlay> added = new ArrayList<>();
		private final List<Overlay> removed = new ArrayList<>();

		@Override
		public void add(Overlay overlay)
		{
			assertNotNull("the plugin must never register a null overlay", overlay);
			added.add(overlay);
		}

		@Override
		public void remove(Overlay overlay)
		{
			removed.add(overlay);
		}

		/** @return what is registered now: everything added and not removed */
		List<Overlay> live()
		{
			List<Overlay> out = new ArrayList<>(added);
			out.removeAll(removed);
			return out;
		}
	}

	/**
	 * The real {@link ClientThread}, minus the thread. {@code invoke(Runnable)} runs
	 * inline on the real one whenever the caller is already on the client thread, which
	 * is every path this plugin uses it for.
	 *
	 * <p><b>The {@code BooleanSupplier} override is the guard, and it is here rather than
	 * beside any one call site because it covers all four at once.</b>
	 * {@code ClientThread} overloads {@code invoke} on {@link Runnable} and
	 * {@link BooleanSupplier}, and the two mean very different things: a
	 * {@code BooleanSupplier} is put on a queue and <b>re-run every tick until it returns
	 * true</b>. Which overload a call site binds to is decided by the return type of the
	 * method it wraps, so a signature change somewhere else entirely can move it —
	 * silently, because both overloads compile. JLS 15.12.2.5 makes the value-returning
	 * function type the more specific one, so a lambda that becomes value-compatible does
	 * not become ambiguous; {@code BooleanSupplier} simply wins.
	 *
	 * <p>This plugin has four {@code invoke} call sites — the first pass in
	 * {@code startUp}, the teardown in {@code shutDown}, the invalidate in
	 * {@code onGameStateChanged} and the visibility pass in {@code onConfigChanged} — and
	 * every one of them is driven by a test in this class. None may ever be a repeating
	 * task: a teardown that runs forever, or a scene invalidate that never finishes
	 * invalidating, is not a thing a user could diagnose. So reaching this overload at
	 * all fails the test that reached it.
	 */
	private static final class InlineClientThread extends ClientThread
	{
		private int invocations;

		@Override
		public void invoke(Runnable runnable)
		{
			invocations++;
			runnable.run();
		}

		@Override
		public void invoke(BooleanSupplier supplier)
		{
			fail("this plugin has no repeating client-thread task: invoke(BooleanSupplier) "
				+ "re-queues its argument every tick until it returns true. Reaching it means "
				+ "a call site bound to the wrong overload, which happens on its own when the "
				+ "method behind it grows a boolean return. Use a block lambda whose body is a "
				+ "bare statement — that has no value, so only Runnable fits.");
		}
	}

	/**
	 * The real {@link EntityScene} with every entry point counted and none of them
	 * doing anything. Nothing is stubbed out that the plugin does not call, so a
	 * new call from the plugin lands on the real implementation and fails on the
	 * null collaborators rather than being silently swallowed.
	 */
	private static final class RecordingScene extends EntityScene
	{
		private final List<Float> fractions = new ArrayList<>();
		private final List<String> invalidations = new ArrayList<>();

		private int syncRegions;
		private int gameTicks;
		private int settingsChanges;
		private int frames;
		private int shutdowns;

		RecordingScene()
		{
			super(null, null, null, null);
		}

		@Override
		boolean syncRegions(WorldView worldView)
		{
			assertNotNull("the plugin must never hand the scene a null world view", worldView);
			syncRegions++;
			return false;
		}

		@Override
		void onGameTick(@Nullable WorldPoint playerLocation, WorldView worldView)
		{
			assertNotNull("the plugin must never hand the scene a null player tile", playerLocation);
			gameTicks++;
		}

		@Override
		void onSettingsChanged(@Nullable WorldPoint playerLocation, WorldView worldView)
		{
			assertNotNull("the plugin must never hand the scene a null player tile", playerLocation);
			settingsChanges++;
		}

		@Override
		void onFrame(WorldView worldView, float fraction)
		{
			assertNotNull(worldView);
			frames++;
			fractions.add(fraction);
		}

		@Override
		int invalidate(String reason)
		{
			invalidations.add(reason);
			return 0;
		}

		@Override
		int shutdown()
		{
			shutdowns++;
			return 0;
		}
	}
}

package com.matthewmariner.livelycities;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.Plugin;

/**
 * The dev client's entry point — {@code ./gradlew run}, {@code runWithTimings} and
 * {@code auditCacheIds} all run this {@code main} on
 * {@code sourceSets.test.runtimeClasspath}.
 *
 * <p>{@link LivelyCitiesDevReportsPlugin} is loaded alongside the real plugin, and only
 * from here. It is the half of the diagnostics that writes files, kept out of
 * {@code src/main} so the shipped jar has no filesystem I/O in it at all — see its
 * javadoc for the maintainer guidance that shape comes from. It carries
 * {@code developerPlugin = true}, so {@code PluginManager.loadPlugins} skips it unless
 * the client was launched with {@code --developer-mode}, which all three tasks pass.
 */
public class LivelyCitiesPluginTest
{
	/**
	 * What the dev client loads, in one place so that {@code ShippedSourceTest} can
	 * assert on it.
	 *
	 * <p>Dropping the reporter from this list is silent in the worst way: the task
	 * launches, the client runs, the stopwatch measures, and the report file never
	 * appears — the same failure mode {@code FrameTimingsTest} guards the two Gradle
	 * tasks against, one step further along the same chain.
	 */
	static final List<Class<? extends Plugin>> BUILTIN_PLUGINS = Collections.unmodifiableList(
		Arrays.asList(LivelyCitiesPlugin.class, LivelyCitiesDevReportsPlugin.class));

	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(builtinPlugins());
		RuneLite.main(args);
	}

	/**
	 * {@link #BUILTIN_PLUGINS} as the varargs array {@code loadBuiltin} wants.
	 *
	 * <p>Its own method so the one unavoidable unchecked cast is suppressed on one
	 * line rather than warned about on every build — {@code toArray} cannot produce a
	 * generic array, and {@code Class<? extends Plugin>[]} is exactly that. Kept as the
	 * single path from the list to the client so {@code ShippedSourceTest} is asserting
	 * about what actually gets loaded: {@code main} reads the list only through here.
	 */
	@SuppressWarnings("unchecked")
	static Class<? extends Plugin>[] builtinPlugins()
	{
		return BUILTIN_PLUGINS.toArray(new Class[0]);
	}
}

package com.matthewmariner.livelycities;

import com.matthewmariner.livelycities.data.EntityRecord;
import com.matthewmariner.livelycities.data.PointRecord;
import java.util.List;
import net.runelite.api.AnimationController;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The wrapper's own rules: what gets cached, what gets latched, and what gets
 * retried. {@link EntitySceneTest} drives the same code through the scene; this
 * one asserts on a single entity so a failure names the rule.
 */
public class LivelyEntityTest
{
	private static final int REGION = 12852;
	private static final WorldPoint PLAYER = new WorldPoint(3225, 3360, 0);

	/** Not a multiple of 256, so it can never be mistaken for a travel facing. */
	private static final int BASE_ORIENTATION = 500;

	private FakeClient client;
	private FakeRegions definitions;
	private FakeWorldView view;

	@Before
	public void setUp()
	{
		client = new FakeClient();
		definitions = new FakeRegions();
		view = FakeWorldView.around(PLAYER, REGION);
	}

	private LivelyEntity entity(int... modelIds)
	{
		return new LivelyEntity(client, definitions.citizen(REGION, 3225, 3358, 0, modelIds));
	}

	@Test
	public void aCompleteModelSpawnsAndIsBuiltOnlyOnce()
	{
		LivelyEntity entity = entity(217, 218);

		assertTrue(entity.spawn(view));
		assertTrue(entity.isActive());
		assertEquals(1, client.registeredCount());
		assertEquals(2, client.loadModelDataCalls());
		assertEquals("both parts must reach the merge", 2, client.lastMergePartCount());

		// Out and back in: an activate, not a rebuild.
		assertTrue(entity.despawn());
		assertEquals(0, client.registeredCount());
		client.resetCounters();
		assertTrue(entity.spawn(view));
		assertEquals("the model is cached", 0, client.loadModelDataCalls());
		assertEquals(1, client.registeredCount());
	}

	@Test
	public void aPartialModelIsNotSpawnedAndNotCached()
	{
		LivelyEntity entity = entity(217, 218, 219);
		client.setUnloadable(219);

		assertFalse("two thirds of a citizen is not a citizen", entity.spawn(view));
		assertFalse(entity.isActive());
		assertEquals("nothing may be merged from a partial resolve", 0, client.mergeCalls());
		assertFalse("a missing part is transient, not structural", entity.isBroken());

		// The missing part turns up. Because nothing was cached, what gets built
		// is the whole model, not the two parts that happened to load first.
		FakeClient warm = new FakeClient();
		LivelyEntity healed = new LivelyEntity(warm, entity.getDefinition());
		assertTrue(healed.spawn(view));
		assertEquals(3, warm.lastMergePartCount());
	}

	@Test
	public void aColdCacheIsRetriedUpToTheBudgetAndThenLeftAlone()
	{
		LivelyEntity entity = entity(217);
		client.setCacheCold(true);

		// The first attempt is immediate.
		assertFalse(entity.spawn(view));
		assertEquals(1, client.loadModelDataCalls());

		// The retries are spaced out rather than fired on the next tick: the
		// cache being waited on warms up over seconds.
		for (int pass = 1; pass < LivelyEntity.RETRY_BACKOFF_PASSES; pass++)
		{
			assertFalse(entity.spawn(view));
		}
		assertEquals("a retry must not be spent on the very next pass", 1, client.loadModelDataCalls());

		for (int attempt = 2; attempt <= LivelyEntity.MAX_MODEL_ATTEMPTS; attempt++)
		{
			passesUntilRetry(entity);
			assertEquals("one client call per attempt", attempt, client.loadModelDataCalls());
		}

		// Budget spent: the client is not asked again however long we wait, and
		// the entity is still not broken — a cold cache is not a verdict on the
		// model id.
		passesUntilRetry(entity);
		passesUntilRetry(entity);
		assertEquals(LivelyEntity.MAX_MODEL_ATTEMPTS, client.loadModelDataCalls());
		assertFalse(entity.isBroken());

		// A scene load hands the budget back, and by then the cache is warm.
		client.setCacheCold(false);
		entity.onScopeEntered();
		assertTrue(entity.spawn(view));
		assertTrue(entity.isActive());
	}

	/** Drives exactly enough failed passes to spend the next spaced-out retry. */
	private void passesUntilRetry(LivelyEntity entity)
	{
		for (int pass = 0; pass < LivelyEntity.RETRY_BACKOFF_PASSES; pass++)
		{
			assertFalse(entity.spawn(view));
		}
	}

	// --- npcAppearanceId: the body comes from a composition -------------------

	private static final int WHITE_KNIGHT = 1798;

	private LivelyEntity npcDressed(int npcId)
	{
		return new LivelyEntity(client, definitions.npcDressed(REGION, 3225, 3358, npcId));
	}

	/**
	 * The whole mechanism, end to end: the composition's model ids are the ones
	 * loaded, and its palette is the one applied.
	 */
	@Test
	public void anNpcDressedEntityBuildsTheCompositionsModelsAndWearsItsPalette()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.recoloured(
			"White Knight",
			new int[]{217, 305, 246},
			new short[]{(short) 54397, 20},
			new short[]{(short) 33694, 21}));

		LivelyEntity entity = npcDressed(WHITE_KNIGHT);

		assertTrue(entity.spawn(view));
		assertEquals("one composition lookup", 1, client.npcDefinitionsRequested().size());
		assertEquals("three model parts, from the NPC", 3, client.loadModelDataCalls());
		assertEquals(3, client.lastMergePartCount());

		List<String> calls = client.lastMerged().calls();
		assertTrue("the NPC's palette has to be applied: " + calls,
			calls.contains("recolor " + (short) 54397 + "->" + (short) 33694));
		assertTrue("and the second pair too: " + calls, calls.contains("recolor 20->21"));
		assertTrue("cloneColors() must still come first, or the client's cached model is repainted",
			calls.indexOf("cloneColors") >= 0
				&& calls.indexOf("cloneColors") < calls.indexOf("recolor 20->21"));

		NpcAppearance appearance = entity.getAppearance();
		assertNotNull(appearance);
		assertEquals(WHITE_KNIGHT, appearance.getNpcId());
	}

	/**
	 * Precedence, at the only place it is observable.
	 *
	 * <p>{@code EntityDefinitionTest} asserts the record keeps both fields; this
	 * asserts which one is actually built. Written with a record rather than a
	 * {@link FakeRegions} fixture because the shipped data deliberately never carries
	 * both, so there is no fixture for it and there should not be.
	 */
	@Test
	public void whenARecordCarriesBothTheNpcAppearanceIsWhatGetsBuilt()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", 900, 901));

		EntityRecord record = new EntityRecord();
		record.entityType = "StationaryCitizen";
		record.uuid = "55555555-5555-4555-8555-555555555555";
		record.name = "Wearing both";
		PointRecord tile = new PointRecord();
		tile.x = 3225;
		tile.y = 3358;
		tile.plane = 0;
		record.worldLocation = tile;
		record.modelIds = new int[]{217, 305};
		record.modelRecolorFind = new int[]{1};
		record.modelRecolorReplace = new int[]{2};
		record.npcAppearanceId = WHITE_KNIGHT;

		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		LivelyEntity entity = new LivelyEntity(client, definition);

		assertTrue(entity.spawn(view));
		assertEquals("the NPC's two models, not the record's two", 2, client.loadModelDataCalls());
		assertFalse("the record's own palette must not be applied to somebody else's model: "
				+ client.lastMerged().calls(),
			client.lastMerged().calls().contains("recolor 1->2"));
		assertFalse("nor may the record's colours be cloned for nothing",
			client.lastMerged().calls().contains("cloneColors"));
	}

	/**
	 * An NPC id that will not resolve is transient, not structural — the same verdict
	 * a missing model gets, and for the same reason: the composition comes out of the
	 * same cache archives, so a cold-cache miss must not cost the entity the session.
	 *
	 * <p>The budget is shared with the model loads rather than being a second one, so
	 * the total number of client calls a broken entity can make per scene load stays
	 * bounded at {@link LivelyEntity#MAX_MODEL_ATTEMPTS} however it is broken.
	 */
	@Test
	public void anUnresolvableNpcIdIsRetriedOnTheModelBudgetAndNeverLatched()
	{
		// Nothing registered for this id, so FakeClient throws — the real 1.12.36
		// behaviour for an id whose archive entry is gone.
		LivelyEntity entity = npcDressed(4242);

		assertFalse(entity.spawn(view));
		assertFalse("a composition miss is not a verdict on the entity", entity.isBroken());
		assertEquals("the first attempt is immediate", 1, client.npcDefinitionsRequested().size());
		assertEquals("and nothing may be built from nothing", 0, client.loadModelDataCalls());
		assertEquals(0, client.mergeCalls());

		for (int pass = 1; pass < LivelyEntity.RETRY_BACKOFF_PASSES; pass++)
		{
			assertFalse(entity.spawn(view));
		}
		assertEquals("a retry must not be spent on the very next pass",
			1, client.npcDefinitionsRequested().size());

		for (int attempt = 2; attempt <= LivelyEntity.MAX_MODEL_ATTEMPTS; attempt++)
		{
			passesUntilRetry(entity);
			assertEquals("one composition lookup per attempt",
				attempt, client.npcDefinitionsRequested().size());
		}

		passesUntilRetry(entity);
		passesUntilRetry(entity);
		assertEquals("the budget bounds it",
			LivelyEntity.MAX_MODEL_ATTEMPTS, client.npcDefinitionsRequested().size());
		assertFalse(entity.isBroken());

		// A scene load hands the budget back, and by then the NPC is available.
		client.withNpc(4242, FakeNpcComposition.of("Late arrival", 217));
		entity.onScopeEntered();
		assertTrue(entity.spawn(view));
		assertNotNull(entity.getAppearance());
	}

	/**
	 * A composition that resolves to nothing drawable fails the same way, and it has
	 * to be tested separately from the throwing id: they are different branches in
	 * {@link NpcAppearance} and only one of them involves an exception.
	 */
	@Test
	public void aCompositionWithNoModelsDoesNotSpawnAndDoesNotHalfBuild()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.withoutModels("Bodyless", new int[0]));

		LivelyEntity entity = npcDressed(WHITE_KNIGHT);

		assertFalse(entity.spawn(view));
		assertFalse(entity.isActive());
		assertEquals("no part may be loaded from an empty composition", 0, client.loadModelDataCalls());
		assertEquals("and nothing may be merged", 0, client.mergeCalls());
		assertFalse(entity.isBroken());
		assertNull(entity.getAppearance());
	}

	/**
	 * The composition is asked for once and then kept.
	 *
	 * <p><b>Exercised through a partial model load, which is the only path that can
	 * see it.</b> Once the model is built, {@code trySpawn} never calls
	 * {@code loadParts()} again — so walking out of a region and back in cannot tell a
	 * cached appearance from an uncached one, and a test written that way is green
	 * whatever the cache does. (Mutation testing found exactly that: deleting the
	 * cache check left the whole suite green.) The reachable case is a composition that
	 * resolves while one of the models it names does not: the appearance is kept, the
	 * model is not, and the next retry has to re-ask the <i>model</i> cache without
	 * re-asking for the composition.
	 */
	@Test
	public void theCompositionIsResolvedOnceAndKeptAcrossAModelRetry()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", 217, 305, 246));
		client.setUnloadable(246);

		LivelyEntity entity = npcDressed(WHITE_KNIGHT);

		assertFalse("a part is missing, so nothing spawns", entity.spawn(view));
		assertEquals(1, client.npcDefinitionsRequested().size());
		assertNotNull("but the appearance resolved and must be kept", entity.getAppearance());
		assertEquals("all three ids came from the composition", 3, client.loadModelDataCalls());

		passesUntilRetry(entity);

		assertEquals("the composition must not be looked up again",
			1, client.npcDefinitionsRequested().size());
		assertEquals("while the model cache is asked again", 6, client.loadModelDataCalls());

		// And when the part turns up, it builds from the composition's full list.
		FakeClient warm = new FakeClient();
		warm.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", 217, 305, 246));
		LivelyEntity healed = new LivelyEntity(warm, entity.getDefinition());
		assertTrue(healed.spawn(view));
		assertEquals(3, warm.lastMergePartCount());
	}

	/**
	 * The built model is cached across a despawn/respawn, exactly as it is for an
	 * entity dressed from raw model ids — so an NPC-dressed citizen costs an activate
	 * rather than a rebuild when the player walks back.
	 */
	@Test
	public void anNpcDressedEntitysModelIsCachedAcrossADespawn()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", 217, 305));

		LivelyEntity entity = npcDressed(WHITE_KNIGHT);
		assertTrue(entity.spawn(view));

		assertTrue(entity.despawn());
		client.resetCounters();
		entity.onScopeEntered();
		assertTrue(entity.spawn(view));

		assertEquals("the model is cached", 0, client.loadModelDataCalls());
		assertEquals(0, client.mergeCalls());
	}

	/**
	 * A model part the composition names but the cache will not produce is still a
	 * partial build, and still refused.
	 *
	 * <p>Sourcing the ids from an NPC changes where the list came from, not what a
	 * missing part means — "no legs" is the failure that got the predecessor plugin
	 * disabled, and it must not come back through the new door.
	 */
	@Test
	public void aPartialBuildFromACompositionIsStillRefused()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", 217, 305, 246));
		client.setUnloadable(246);

		LivelyEntity entity = npcDressed(WHITE_KNIGHT);

		assertFalse("two thirds of a knight is not a knight", entity.spawn(view));
		assertEquals("nothing may be merged from a partial resolve", 0, client.mergeCalls());
		assertFalse(entity.isBroken());
	}

	@Test
	public void aStructuralFailureIsLatchedAndNeverRetried()
	{
		LivelyEntity entity = entity(217);
		client.setThrowing(217);

		assertFalse(entity.spawn(view));
		assertTrue("a throw is structural", entity.isBroken());
		assertFalse(entity.isWanted());

		client.resetCounters();
		assertFalse(entity.spawn(view));
		assertEquals("a broken entity must not touch the client again", 0, client.loadModelDataCalls());
	}

	@Test
	public void aRefusedActivationIsLatchedRatherThanWarnedEveryTick()
	{
		LivelyEntity entity = entity(217);
		client.refuseRegistration();

		assertFalse("setActive(true) did not take", entity.spawn(view));
		assertTrue("and that is not going to change next tick", entity.isBroken());
		assertFalse(entity.isWanted());

		client.resetCounters();
		assertFalse(entity.spawn(view));
		assertEquals("nothing may be rebuilt for a latched entity", 0, client.createObjectCalls());
		assertEquals(0, client.loadModelDataCalls());
	}

	@Test
	public void despawnIsIdempotentAndReportsWhetherItDidAnything()
	{
		LivelyEntity entity = entity(217);

		assertFalse("nothing to deactivate yet", entity.despawn());
		assertTrue(entity.spawn(view));
		assertTrue("this call deactivated something", entity.despawn());
		assertFalse("this one had nothing left to do", entity.despawn());
		assertEquals(0, client.registeredCount());
	}

	@Test
	public void recoloursCloneTheColoursBeforeTouchingThem()
	{
		// 54397 -> 33694 is a real pair from 12850.json; both wrap negative.
		LivelyEntity entity = new LivelyEntity(client, recoloured(54397, 33694));

		assertTrue(entity.spawn(view));

		List<String> calls = client.lastMerged().calls();
		assertNotNull(calls);
		int cloned = calls.indexOf("cloneColors");
		int recoloured = calls.indexOf("recolor " + (short) 54397 + "->" + (short) 33694);
		assertTrue("cloneColors() must happen: recolor() mutates the merge in place", cloned >= 0);
		assertTrue("the recolour must actually be applied", recoloured >= 0);
		assertTrue("cloneColors() must come first, or the client's cached model is repainted",
			cloned < recoloured);
	}

	@Test
	public void anEntityWithNoRecoloursDoesNotCloneColours()
	{
		LivelyEntity entity = entity(217);

		assertTrue(entity.spawn(view));
		assertFalse("no recolours, nothing to protect",
			client.lastMerged().calls().contains("cloneColors"));
	}

	@Test
	public void anEntityOutsideTheLoadedSceneIsNotAFailure()
	{
		// 200 tiles away: inside the region, outside the 104-tile scene.
		LivelyEntity entity = new LivelyEntity(client,
			definitions.citizen(REGION, 3225, 3560, 0, 217));

		assertFalse(entity.spawn(view));
		assertFalse("outside the scene is a wait, not a fault", entity.isBroken());
		assertEquals("and must not spend a model load", 0, client.loadModelDataCalls());
	}

	@Test
	public void theIdleAnimationIsAskedForByItsDatasetName()
	{
		LivelyEntity entity = new LivelyEntity(client, animated("Fletching"));

		assertTrue(entity.spawn(view));
		assertEquals(1, client.animationsLoaded().size());
		assertEquals(Integer.valueOf(LivelyAnimation.Fletching.getId()), client.animationsLoaded().get(0));
	}

	/**
	 * An animation the client will not give us must not be cached as a controller.
	 *
	 * <p>{@code new AnimationController(client, id)} calls
	 * {@code client.loadAnimation(id)} and hands the result — null or not —
	 * straight to {@code setAnimation}. A controller holding a null animation is
	 * inert forever: its {@code tick}, {@code loop} and {@code getPackedFrame} all
	 * return immediately. This class used to keep the first controller it built,
	 * so one cold-cache miss froze the citizen for the session.
	 *
	 * <p>The citizen still spawns while it waits. Standing in the right place
	 * holding still beats not being there, which is the same call the plugin makes
	 * for an animation name it does not recognise.
	 */
	@Test
	public void anAnimationThatWillNotLoadIsNotCachedAndIsRetried()
	{
		client.setUnloadableAnimations(LivelyAnimation.Fletching.getId());
		LivelyEntity entity = new LivelyEntity(client, animated("Fletching"));

		assertTrue("a citizen with no animation yet still belongs on its tile", entity.spawn(view));
		assertFalse("a missing animation is not a structural fault", entity.isBroken());
		assertNull("nothing may be installed while the animation is missing",
			entity.getInstalledController());
		assertEquals(1, client.animationsLoaded().size());

		// The cache warms up. The retry is spaced like the model one — a cold cache
		// warms over seconds, not ticks — so the next few passes are deliberately
		// silent, and then it asks again.
		client.clearUnloadableAnimations();
		for (int pass = 1; pass < LivelyEntity.RETRY_BACKOFF_PASSES; pass++)
		{
			entity.retryMissingAnimation();
		}
		assertEquals("the retry is spaced, not per pass", 1, client.animationsLoaded().size());
		assertNull(entity.getInstalledController());

		entity.retryMissingAnimation();
		assertEquals("and then it asks the client again", 2, client.animationsLoaded().size());
		AnimationController installed = entity.getInstalledController();
		assertNotNull("and install what it got", installed);
		assertNotNull("which has to be a controller with a real animation", installed.getAnimation());
		assertEquals(LivelyAnimation.Fletching.getId(), installed.getAnimation().getId());

		// And having resolved once, it is cached like any other: no more asking.
		entity.retryMissingAnimation();
		assertEquals("a resolved animation is never re-requested", 2, client.animationsLoaded().size());
		assertSame(installed, entity.getInstalledController());
	}

	/**
	 * The retry is bounded, exactly like the model-data retry it mirrors.
	 *
	 * <p>An id with no frames at all — {@code LivelyAnimation.BeeIdle} is id 0 —
	 * never resolves however long the cache warms. Without a budget that would be
	 * one {@code loadAnimation} call and one log line per game tick, forever, which
	 * is the noise the model path already exists to avoid.
	 */
	@Test
	public void aMissingAnimationIsRetriedAtMostThreeTimesPerScopeEntry()
	{
		client.setUnloadableAnimations(LivelyAnimation.Fletching.getId());
		LivelyEntity entity = new LivelyEntity(client, animated("Fletching"));

		assertTrue(entity.spawn(view));
		assertEquals("the spawn spends the first attempt", 1, client.animationsLoaded().size());

		// Hammer it. The backoff swallows everything until the spacing is met, and
		// the budget stops it after three attempts however long we keep asking.
		for (int pass = 0; pass < LivelyEntity.RETRY_BACKOFF_PASSES * 10; pass++)
		{
			entity.retryMissingAnimation();
		}

		assertEquals("three attempts per scope entry, no more",
			LivelyEntity.MAX_ANIMATION_ATTEMPTS, client.animationsLoaded().size());
		assertNull(entity.getInstalledController());
		assertFalse("an unresolvable animation is still not a structural fault", entity.isBroken());

		// A scene load is the granularity at which a cold cache is worth re-testing.
		entity.onScopeEntered();
		entity.retryMissingAnimation();
		assertEquals("entering scope hands the budget back",
			LivelyEntity.MAX_ANIMATION_ATTEMPTS + 1, client.animationsLoaded().size());
	}

	/**
	 * Scenery, and any citizen whose animation name this build does not know, are
	 * static by design. Neither is a cache miss, so neither may cost a client call
	 * on every visibility pass forever.
	 */
	@Test
	public void anEntityWithNoAnimationAtAllIsNeverRetried()
	{
		LivelyEntity scenery = entity(217);
		assertTrue(scenery.spawn(view));

		LivelyEntity unknownName = new LivelyEntity(client, animated("PolishingTheBrasswork"));
		assertTrue(unknownName.spawn(view));

		for (int pass = 0; pass < 50; pass++)
		{
			scenery.retryMissingAnimation();
			unknownName.retryMissingAnimation();
		}

		assertEquals("a model with no animation has nothing to wait for",
			0, client.animationsLoaded().size());
	}

	/**
	 * A stationary citizen never asks for its move animation, so the animation
	 * cache is not warmed for something that will never play.
	 */
	@Test
	public void aStationaryCitizenNeverLoadsAMoveAnimation()
	{
		EntityRecord record = record();
		record.idleAnimation = "HumanIdle";
		record.moveAnimation = "HumanWalk";
		LivelyEntity entity = new LivelyEntity(client, definition(record));

		assertTrue(entity.spawn(view));
		entity.advanceTick();
		entity.advanceFrame(view, 0.5f);

		assertEquals("only the idle animation is ever needed", 1, client.animationsLoaded().size());
		assertEquals(Integer.valueOf(LivelyAnimation.HumanIdle.getId()), client.animationsLoaded().get(0));
	}

	/**
	 * The animation switch, and the thing that made the predecessor look like it
	 * had no smoothing at all.
	 *
	 * <p>An {@code AnimationController} <i>is</i> the playback position: handing a
	 * fresh one to the object, or calling {@code setAnimation} on the one it has,
	 * resets the frame counter. So the count of installs has to be the count of
	 * idle↔move switches. If it were the count of game ticks, every animation
	 * would restart 1.6 times a second and no amount of per-frame advancing would
	 * show.
	 */
	@Test
	public void theControllerIsInstalledOncePerSwitchAndNotOncePerTick()
	{
		LivelyEntity entity = wanderer();
		assertTrue(entity.spawn(view));

		FakeRuneLiteObject object = client.lastObject();
		assertEquals("spawning installs the idle animation", 1, object.animationControllerInstalls());

		CitizenWalk walk = entity.getWalk();
		assertNotNull(walk);

		// Stand still through a whole idle interval. Nothing should be reinstalled.
		for (int tick = 1; tick < CitizenWalk.IDLE_TICKS_BEFORE_NEW_DESTINATION; tick++)
		{
			entity.advanceTick();
			assertFalse(walk.isMoving());
		}
		assertEquals("standing still must not reinstall anything",
			1, object.animationControllerInstalls());

		// Walk. That is one switch, however many ticks the walk lasts.
		int ticksWalking = 0;
		while (!walk.isMoving() && ticksWalking < 200)
		{
			entity.advanceTick();
			ticksWalking++;
		}
		assertTrue("the fixture must get the citizen walking", walk.isMoving());
		assertEquals("starting to walk is one switch", 2, object.animationControllerInstalls());

		int installsWhileWalking = object.animationControllerInstalls();
		int stepsTaken = 0;
		while (walk.isMoving() && stepsTaken < 200)
		{
			entity.advanceTick();
			stepsTaken++;
			if (walk.isMoving())
			{
				assertEquals("every further step must keep the same controller",
					installsWhileWalking, object.animationControllerInstalls());
			}
		}

		assertFalse("the fixture must get the citizen to stop again", walk.isMoving());
		assertEquals("stopping is the second switch", 3, object.animationControllerInstalls());

		// Both animations were asked for exactly once each.
		assertEquals(2, client.animationsLoaded().size());
		assertEquals(Integer.valueOf(LivelyAnimation.HumanIdle.getId()), client.animationsLoaded().get(0));
		assertEquals(Integer.valueOf(LivelyAnimation.HumanWalk.getId()), client.animationsLoaded().get(1));
	}

	/**
	 * The smoothing claim, asserted on the frame counter itself.
	 *
	 * <p>The client advances the animation once per frame by calling
	 * {@code RuneLiteObject.tick(ticksSinceLastFrame)} — that call is simulated
	 * here, because it is the client's and not ours. What is being tested is that
	 * the plugin's own per-tick and per-frame work does not throw that progress
	 * away.
	 */
	@Test
	public void theAnimationFrameSurvivesEverythingThePluginDoesToTheObject()
	{
		LivelyEntity entity = wanderer();
		assertTrue(entity.spawn(view));

		FakeRuneLiteObject object = client.lastObject();
		AnimationController controller = entity.getInstalledController();
		assertNotNull("the idle animation should be driving the model", controller);

		// The client, advancing the animation between game ticks.
		for (int frame = 0; frame < 3; frame++)
		{
			object.tick(FakeAnimation.CLIENT_TICKS_PER_FRAME);
		}
		int frameBefore = controller.getFrame();
		assertTrue("the fixture animation has to actually advance", frameBefore > 0);

		// A game tick's worth of the plugin's work, while the citizen is idle.
		entity.advanceTick();
		entity.advanceFrame(view, 0f);
		entity.advanceFrame(view, 0.5f);
		entity.advanceFrame(view, 1f);

		assertSame("the same controller must still be driving the model",
			controller, entity.getInstalledController());
		assertEquals("nothing the plugin does per tick or per frame may reset the animation",
			frameBefore, controller.getFrame());
		assertEquals("and the plugin must never advance it either — that is the client's job, "
			+ "once per frame, and a second caller doubles every animation's speed",
			3, object.tickCalls());
	}

	@Test
	public void aWanderingCitizenFacesItsTravelDirectionAndTurnsBackWhenItStops()
	{
		LivelyEntity entity = wanderer();
		assertTrue(entity.spawn(view));

		FakeRuneLiteObject object = client.lastObject();
		assertEquals("it spawns facing the way it was authored facing",
			BASE_ORIENTATION, object.getOrientation());

		CitizenWalk walk = entity.getWalk();
		assertNotNull(walk);

		boolean sawTravelFacing = false;
		boolean sawResetToBase = false;

		for (int tick = 0; tick < 400; tick++)
		{
			entity.advanceTick();

			assertEquals("the object's orientation must be the walk's",
				walk.getOrientation(), object.getOrientation());

			if (walk.isMoving())
			{
				assertNotEquals("a moving citizen must not still be facing its base orientation",
					BASE_ORIENTATION, object.getOrientation());
				sawTravelFacing = true;
			}
			else if (sawTravelFacing)
			{
				assertEquals("stopping must turn it back to its base orientation",
					BASE_ORIENTATION, object.getOrientation());
				sawResetToBase = true;
			}
		}

		assertTrue("the fixture must get the citizen walking", sawTravelFacing);
		assertTrue("and must get it to stop again", sawResetToBase);
	}

	@Test
	public void nothingThatStandsStillDoesAnyPerTickOrPerFrameWork()
	{
		// A base orientation of 500 rather than the default 0: an entity whose
		// authored facing is 0 cannot tell "left alone" from "reset to zero".
		EntityRecord record = record();
		record.baseOrientation = BASE_ORIENTATION;
		LivelyEntity entity = new LivelyEntity(client, definition(record));
		assertTrue(entity.spawn(view));
		assertEquals(BASE_ORIENTATION, client.lastObject().getOrientation());

		FakeRuneLiteObject object = client.lastObject();
		int x = object.getX();
		int y = object.getY();
		int orientation = object.getOrientation();
		int installs = object.animationControllerInstalls();

		for (int tick = 0; tick < 50; tick++)
		{
			entity.advanceTick();
			entity.advanceFrame(view, tick / 50f);
		}

		assertEquals(x, object.getX());
		assertEquals(y, object.getY());
		assertEquals(orientation, object.getOrientation());
		assertEquals(installs, object.animationControllerInstalls());
	}

	/**
	 * A wanderer whose move animation name is not one the plugin knows keeps
	 * whatever it idles as, rather than freezing into a static model mid-step.
	 */
	@Test
	public void anUnknownMoveAnimationFallsBackToTheIdleOneRatherThanNothing()
	{
		EntityRecord record = wandererRecord();
		record.moveAnimation = "PolishingTheBrasswork";
		LivelyEntity entity = new LivelyEntity(client, definition(record));

		assertTrue(entity.spawn(view));
		FakeRuneLiteObject object = client.lastObject();
		CitizenWalk walk = entity.getWalk();
		assertNotNull(walk);

		for (int tick = 0; tick < 200 && !walk.isMoving(); tick++)
		{
			entity.advanceTick();
		}
		assertTrue(walk.isMoving());

		assertEquals("only the idle animation resolved, so only it is ever loaded",
			1, client.animationsLoaded().size());
		assertEquals("and the object keeps the controller it already had",
			1, object.animationControllerInstalls());
		assertNotNull("it must not have been reduced to a static model",
			entity.getInstalledController());
	}

	/**
	 * A citizen standing still is placed once per game tick, not once per frame.
	 *
	 * <p>Not micro-optimisation for its own sake: {@code setLocation} runs
	 * {@code Perspective.getTileHeight} against the live scene, this is a frame
	 * handler, and most citizens are idle most of the time. A walking one is a
	 * different matter — that is the whole point of the frame pass — so both
	 * branches are asserted.
	 */
	@Test
	public void anIdleWandererIsPlacedOncePerTickAndAWalkingOneOncePerFrame()
	{
		LivelyEntity entity = wanderer();
		assertTrue(entity.spawn(view));

		FakeRuneLiteObject object = client.lastObject();
		CitizenWalk walk = entity.getWalk();
		assertNotNull(walk);
		assertFalse("it starts idle", walk.isMoving());

		int afterSpawn = object.setLocationCalls();
		for (int frame = 0; frame < 40; frame++)
		{
			entity.advanceFrame(view, frame / 40f);
		}
		assertEquals("forty frames of standing still cost one placement",
			afterSpawn + 1, object.setLocationCalls());

		// One more tick of standing still costs one more placement, not forty.
		entity.advanceTick();
		assertFalse(walk.isMoving());
		for (int frame = 0; frame < 40; frame++)
		{
			entity.advanceFrame(view, frame / 40f);
		}
		assertEquals(afterSpawn + 2, object.setLocationCalls());

		// Now get it walking: every frame has to count.
		for (int tick = 0; tick < 200 && !walk.isMoving(); tick++)
		{
			entity.advanceTick();
		}
		assertTrue("the fixture must get the citizen walking", walk.isMoving());

		int beforeWalkingFrames = object.setLocationCalls();
		for (int frame = 0; frame < 40; frame++)
		{
			entity.advanceFrame(view, frame / 40f);
		}
		assertEquals("a walking citizen is re-placed on every single frame",
			beforeWalkingFrames + 40, object.setLocationCalls());
	}

	@Test
	public void aDeactivatedWandererDoesNoWork()
	{
		LivelyEntity entity = wanderer();
		assertTrue(entity.spawn(view));
		assertTrue(entity.despawn());

		FakeRuneLiteObject object = client.lastObject();
		int installs = object.animationControllerInstalls();
		CitizenWalk walk = entity.getWalk();
		assertNotNull(walk);
		WorldPoint tile = walk.currentTile();

		for (int tick = 0; tick < 100; tick++)
		{
			entity.advanceTick();
			entity.advanceFrame(view, 0.5f);
		}

		assertEquals("a citizen nobody can see does not walk", tile, walk.currentTile());
		assertEquals(installs, object.animationControllerInstalls());
		assertEquals(0, client.registeredCount());
	}

	/**
	 * A wandering citizen with a small box around its start tile, and a base
	 * orientation of 500 — a real value from region 12338, and not one of the
	 * eight travel orientations, so "turned back to base" is distinguishable from
	 * "never turned".
	 */
	private LivelyEntity wanderer()
	{
		return new LivelyEntity(client, definition(wandererRecord()));
	}

	private static EntityRecord wandererRecord()
	{
		EntityRecord record = record();
		record.entityType = "WanderingCitizen";
		record.baseOrientation = BASE_ORIENTATION;
		record.idleAnimation = "HumanIdle";
		record.moveAnimation = "HumanWalk";
		record.wanderBoxBL = point(3221, 3354, 0);
		record.wanderBoxTR = point(3229, 3362, 0);
		return record;
	}

	private static EntityDefinition recoloured(int find, int replace)
	{
		EntityRecord record = record();
		record.modelRecolorFind = new int[]{find};
		record.modelRecolorReplace = new int[]{replace};
		return definition(record);
	}

	private static EntityDefinition animated(String idleAnimation)
	{
		EntityRecord record = record();
		record.idleAnimation = idleAnimation;
		return definition(record);
	}

	private static EntityDefinition definition(EntityRecord record)
	{
		EntityDefinition definition = EntityDefinition.fromRecord(record, REGION);
		assertNotNull(definition);
		return definition;
	}

	private static EntityRecord record()
	{
		EntityRecord record = new EntityRecord();
		record.entityType = "StationaryCitizen";
		record.name = "Test subject";
		record.uuid = "55555555-5555-4555-8555-555555555555";
		record.worldLocation = point(3225, 3358, 0);
		record.modelIds = new int[]{217};
		return record;
	}

	private static PointRecord point(int x, int y, int plane)
	{
		PointRecord p = new PointRecord();
		p.x = x;
		p.y = y;
		p.plane = plane;
		return p;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The offline half of the durability tooling: pure data invariants over the
 * shipped {@code RegionData/*.json}, no client and no cache. Whether an id
 * actually <i>resolves</i> is answered only by {@link CacheIdAudit}, which needs
 * a live client and is kept out of this run — see that class's javadoc.
 *
 * <p>What lives here instead is everything a JSON diff can catch before a
 * broken id ever reaches a player: an implausible number, an empty
 * {@code modelIds}, and a pinned count so a dataset change that adds or removes
 * ids shows up as a red assertion rather than a silent drift.
 */
public class ModelIdAuditTest
{
	/**
	 * Positive and not wrong by orders of magnitude. See
	 * {@link CacheIdPlausibility} for where the ceiling comes from and why it is
	 * deliberately loose — the precise question is the cache-backed check's job,
	 * not this one's.
	 */
	@Test
	public void everyModelIdIsPositiveAndWithinThePlausibleCacheRange()
	{
		List<String> violations = new ArrayList<>();

		for (ShippedModelIds.Entry entry : ShippedModelIds.perEntity())
		{
			for (int id : entry.modelIds)
			{
				if (!CacheIdPlausibility.isPlausible(id))
				{
					violations.add(entry + ": modelId " + id);
				}
			}
		}

		assertTrue("implausible model id(s) in the shipped dataset: " + violations, violations.isEmpty());
	}

	/**
	 * An entity with nothing to build cannot render anything — and there are now two
	 * ways to have something to build, so this is the qualified form of what used to
	 * be "no entity ships an empty {@code modelIds} array".
	 *
	 * <p>The six cameo records in {@code 12598.json} deliberately carry no
	 * {@code modelIds} at all: they are dressed from an {@code npcAppearanceId}
	 * instead (see {@code EntityRecord.npcAppearanceId}). So the invariant is
	 * <b>exactly one of the two</b> has to be present, which is a stronger statement
	 * than the old one rather than a relaxation of it — the old test could not have
	 * caught a record with neither, because a record with neither also has an empty
	 * {@code modelIds} array and would have been reported as the same violation.
	 *
	 * <p>{@code EntityDefinition} already skips a record with neither at load time
	 * (and {@code RegionDataLoaderTest.loadsTheWholeShippedDatasetWithoutSkippingAnything}
	 * asserts nothing in the shipped data is skipped at all), but this checks the raw
	 * JSON directly so the claim does not depend on that filtering staying in place,
	 * or on skip-counting logic that has other jobs too.
	 */
	@Test
	public void everyEntityHasEitherModelIdsOrAnNpcAppearanceIdAndNeverNeither()
	{
		List<String> violations = new ArrayList<>();
		int fromModelIds = 0;
		int fromNpcAppearance = 0;

		for (ShippedModelIds.Entry entry : ShippedModelIds.perEntity())
		{
			boolean hasModels = entry.modelIds.length > 0;
			boolean hasNpc = entry.npcAppearanceId != 0;

			if (!hasModels && !hasNpc)
			{
				violations.add(entry + ": neither modelIds nor npcAppearanceId");
			}
			else if (hasModels && hasNpc)
			{
				// Legal — the NPC appearance wins and EntityDefinition warns — but
				// nothing in the shipped data does it, and it is worth knowing if
				// that changes, because the ignored half is the half a human typed.
				violations.add(entry + ": carries both modelIds and npcAppearanceId "
					+ entry.npcAppearanceId + ", so the modelIds are dead weight");
			}

			if (hasNpc)
			{
				fromNpcAppearance++;
			}
			else
			{
				fromModelIds++;
			}
		}

		assertTrue("entities with nothing to build, or with two ways to build: " + violations,
			violations.isEmpty());

		// Both halves have to be non-empty or this test is only checking one rule.
		assertEquals("entities dressed from raw model ids", 304, fromModelIds);
		assertEquals("entities dressed from an NPC appearance", 7, fromNpcAppearance);
	}

	/**
	 * The {@code npcAppearanceId}s get the same offline bound as the model ids, and
	 * it bites harder here: {@code gameval.NpcID}'s highest constant in 1.12.36 is
	 * 16346, so a transposed digit or a pasted hashcode in this field is caught
	 * before a client is ever asked about it.
	 */
	@Test
	public void everyNpcAppearanceIdIsPositiveAndWithinThePlausibleCacheRange()
	{
		List<String> violations = new ArrayList<>();

		for (ShippedModelIds.Entry entry : ShippedModelIds.perEntity())
		{
			if (entry.npcAppearanceId != 0 && !CacheIdPlausibility.isPlausible(entry.npcAppearanceId))
			{
				violations.add(entry + ": npcAppearanceId " + entry.npcAppearanceId);
			}
		}

		assertTrue("implausible npcAppearanceId(s) in the shipped dataset: " + violations,
			violations.isEmpty());
		assertEquals("the dataset has to actually use the mechanism for this to mean anything",
			7, ShippedModelIds.distinctNpcAppearanceIds().size());
	}

	/**
	 * <b>GitHub issue #1: "Rufus renders without boots."</b>
	 *
	 * <p>Not a rendering bug — the client logged no model-load failure for him, and a
	 * partial build cannot spawn at all (see {@code LivelyEntity}). His record carried
	 * twelve model ids, the most of any entity in the corpus, and none of them was
	 * footwear. It sat unfixed because the only fix available was to guess a raw model
	 * id, and a wrong guess puts a hat where the boots should be.
	 *
	 * <p>{@code npcAppearanceId} removed the guess: he now wears a <i>named</i>
	 * constant. The id is asserted through {@link NpcID#FARMER1} rather than as 3114,
	 * and the second assertion is the one that makes the choice checkable rather than
	 * asserted — the 1.12.36 jar's other, independently generated id table names the
	 * same number {@code FARMER}, i.e. an NPC whose in-game name is literally "Farmer".
	 * That is the whole evidence for "the id maps to the thing we think it does".
	 *
	 * <p><b>That first line is a compile-time pin, not a runtime one</b>, and an earlier
	 * revision of this javadoc oversold it as "a mechanical check". Both names are
	 * {@code static final int}, so javac inlines them (JLS 4.12.4) and what actually
	 * executes is {@code assertEquals(3114, 3114)} — two literals that cannot disagree.
	 * It still earns its keep, because {@code runeLiteVersion = 'latest.release'} means
	 * a jar bump recompiles this file and a disagreement between the two tables would be
	 * baked in as two <i>different</i> literals and go red on the next run. But what it
	 * pins is the jar this file was compiled against, not the jar the suite is running
	 * on, and the only way to make it a genuine runtime read is reflection, which this
	 * project does not use.
	 *
	 * <p>The rest is the trade, written down: he is emphatically <b>not</b> a cameo — an
	 * ordinary townsperson must not become opt-in content by way of a bug fix, see
	 * {@code EntityRecord.cameo} — and he is the only non-cameo citizen dressed this
	 * way. He is looked up <b>by name across the whole roster</b> rather than taken out
	 * of the list filtered on {@code !cameo}, because an earlier revision did the
	 * latter and its {@code assertFalse(rufus.cameo)} was then a restatement of the
	 * filter that had selected him: it could not fail. Flip {@code cameo} to true on his
	 * record now and it does.
	 *
	 * <p>That his authored body is <b>replaced, not patched</b> — the appearance wins,
	 * so the twelve ids and their six recolour pairs left the record entirely — used to
	 * be a fourth loop here with no counter in it, which would have passed having
	 * asserted nothing if its {@code if} had stopped matching.
	 * {@link #everyEntityHasEitherModelIdsOrAnNpcAppearanceIdAndNeverNeither} already
	 * makes exactly that claim over every entity in the dataset, and reports carrying
	 * both as a violation, so the loop was deleted rather than decorated.
	 */
	@Test
	public void theCitizenWhoseAuthoredModelsHadNoBootsWearsANamedNpcInstead()
	{
		assertEquals("the two independently generated id tables in runelite-api-1.12.36 have to "
				+ "agree that this number is the NPC named \"Farmer\" — that agreement is the only "
				+ "evidence anybody has that the id means what the dataset says it means",
			net.runelite.api.NpcID.FARMER, NpcID.FARMER1);

		ShippedCitizens.Entry rufus = null;
		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if ("Rufus".equals(citizen.name))
			{
				assertNull("two citizens named Rufus would make every assertion below ambiguous",
					rufus);
				rufus = citizen;
			}
		}

		assertNotNull("the citizen this entire test is about is no longer in the dataset", rufus);
		assertEquals(NpcID.FARMER1, rufus.npcAppearanceId);
		assertFalse("a townsperson fixed by re-dressing him must not become opt-in content",
			rufus.cameo);

		List<ShippedCitizens.Entry> dressedFromAnNpc = new ArrayList<>();
		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (citizen.npcAppearanceId != 0 && !citizen.cameo)
			{
				dressedFromAnNpc.add(citizen);
			}
		}

		assertEquals("exactly one non-cameo citizen is dressed from a composition: " + dressedFromAnNpc,
			1, dressedFromAnNpc.size());
		assertEquals("and it is him", "Rufus", dressedFromAnNpc.get(0).name);
	}

	/**
	 * The load-bearing pin. The plan's L0 audit measured 384 — the exact input list
	 * the cache-backed validator had to check. It went to 376 when "Rufus" in Varrock
	 * was moved onto an {@code npcAppearanceId} (GitHub issue #1) and eight of his
	 * twelve model ids, used by nobody else, left the corpus with him. It is 324 now:
	 * the nine-city cut on 2026-08-24 removed eighteen region files, and 52 model ids
	 * went with them because nothing in the surviving nine places wears them. A dataset
	 * change that adds or removes model ids has to move this number, which is what makes
	 * the change visible in review rather than silently changing what the durability
	 * tooling covers.
	 */
	@Test
	public void theDistinctModelIdFigureIsPinned()
	{
		assertEquals("distinct model ids across the shipped dataset — see the L0 audit in "
				+ "plans/osrs-lively-cities.md; a change here means the durability tooling's "
				+ "input list changed and should be re-reviewed",
			324, ShippedModelIds.distinct().size());
	}

	/**
	 * A per-region summary, printed so a human reviewing a dataset change (or
	 * this test's own output) can see what moved without re-deriving it by hand.
	 * Backed by a real assertion — a summary nobody can break is documentation,
	 * not verification — so the printed total is cross-checked against the
	 * independently-computed dataset-wide distinct count.
	 */
	@Test
	public void printsAPerRegionModelIdSummaryForHumanReview()
	{
		TreeMap<Integer, java.util.TreeSet<Integer>> byRegion = new TreeMap<>();
		for (ShippedModelIds.Entry entry : ShippedModelIds.perEntity())
		{
			java.util.TreeSet<Integer> ids = byRegion.computeIfAbsent(entry.regionId, k -> new java.util.TreeSet<>());
			for (int id : entry.modelIds)
			{
				ids.add(id);
			}
		}

		java.util.TreeSet<Integer> unionAcrossRegions = new java.util.TreeSet<>();
		System.out.println("Lively Cities model id audit — per-region summary");
		System.out.println("region     distinct model ids");
		for (java.util.Map.Entry<Integer, java.util.TreeSet<Integer>> region : byRegion.entrySet())
		{
			unionAcrossRegions.addAll(region.getValue());
			System.out.println(String.format("%-10d %d", region.getKey(), region.getValue().size()));
		}
		System.out.println("TOTAL distinct model ids across " + byRegion.size() + " region(s): "
			+ unionAcrossRegions.size());

		assertEquals("every shipped region has a summary row", ShippedRegions.ids().size(), byRegion.size());
		assertEquals("the printed union has to equal the independently-computed distinct count "
				+ "or the summary is lying about what changed",
			ShippedModelIds.distinct(), unionAcrossRegions);
	}
}

package com.matthewmariner.livelycities;

import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Which framemap the <i>body</i> of a shipped record is rigged to — the other half of
 * the question {@link AnimationSkeletons} answers about animations.
 *
 * <h2>Why this exists</h2>
 *
 * <p>{@link AnimationSkeletonTest}'s first rule compares a citizen's two animations
 * against each other, which is a question the dataset can ask about itself. It has a
 * blind spot exactly one record wide: a figure with <i>one</i> animation has nothing to
 * disagree with, and every cameo is such a figure. Three records walked through that
 * gap — "Sludgellama" posed on the Braindeath Island rig while wearing a Rogue's body,
 * and "Child"/"Liam" playing human emotes on gnome-rigged child models. Comparing the
 * animation's framemap against the rig the record's <i>own models</i> imply is the check
 * that catches all three, and it needs this table.
 *
 * <h2>What a row actually claims, and how it was measured</h2>
 *
 * <p>A model id carries no rig of its own that can be read out of the cache in
 * isolation — rigging lives in the NPC definition that composes the model, not in the
 * model file. So the claim a row makes is the inference the evidence supports:
 *
 * <blockquote>every NPC definition in the 1.12.36 cache whose {@code models} list
 * contains this id has its own {@code stand} and {@code walk} on this framemap.</blockquote>
 *
 * <p>That inference is strong because the game itself almost never breaks it: of the
 * 13,533 NPC definitions whose {@code stand} and {@code walk} both resolve to a
 * framemap, 13,529 use exactly one — the four that do not are two fishing spots and the
 * two Nightmare bosses. Three shipped model ids are the exception on this side and are
 * recorded as such below rather than rounded off.
 *
 * <p>The numbers were produced by an independent read-only decoder run against the
 * 1.12.36 cache, walking {@code idx2/archive 9} (NPC definitions), {@code idx2/archive
 * 12} (sequences) and {@code idx0} (frames, whose first two bytes name the framemap).
 * They are transcribed here rather than read at test time for the same reason
 * {@link AnimationSkeletons}' numbers are: a test that reads the player's own game cache
 * passes or fails depending on whose machine it runs on.
 *
 * <h2>Coverage, and what it deliberately does not cover</h2>
 *
 * <p>This table holds 376 model ids: 340 that appear on at least one NPC, listed
 * below with the framemap that implies, and 36 that appear on no NPC at all — object
 * geometry (braziers, stalls, planters), which no amount of decoding turns into a
 * rig. Those are named in {@link #NO_NPC_EVIDENCE} so that "this record was skipped"
 * stays a counted, reviewable outcome rather than a silent one.
 *
 * <h2>Why 376 rows for a 324-id dataset</h2>
 *
 * <p>376 was the dataset's distinct-model-id count when these numbers were decoded.
 * The nine-city cut on 2026-08-24 took it to 324, leaving 52 rows here describing
 * model ids nothing ships any more. <b>They were deliberately kept.</b>
 *
 * <p>The count on each framemap comment below is therefore a count of <i>that row</i>,
 * not of what ships: framemap 0 lists 255 model ids and 218 of them are in the
 * dataset today, and eight of the smaller rows now describe nothing shipped at all.
 * They used to say "shipped model ids" and were left saying it through the cut, which
 * is the reason they say "model ids" now — a row is a reading of the cache, and the
 * dataset does not get a vote on whether it is true.
 *
 * <p>The reasoning is the difference between this table and something like
 * {@code EntityTheme}. A theme row is a <i>judgement about a citizen</i> — if the
 * citizen is gone the row asserts nothing and should go with it. A row here is a
 * <i>measurement of the game cache</i>: "every NPC built out of model 6640 stands and
 * walks on framemap 0" is true or false about the 1.12.36 cache and has nothing to do
 * with which regions this plugin happens to ship. Deleting those rows would discard
 * correct, expensively-obtained readings — the decoder run is not reproducible from
 * inside this repository — and the top-up pass that brings the thin cities back up
 * will want them.
 *
 * <p>What that decision costs is the property the old count quietly carried: that the
 * table and the dataset were the same set, so a shipped id with no row would have
 * shown up as a size mismatch. That is now stated as its own assertion instead —
 * {@code AnimationSkeletonTest.everyShippedModelIdIsEitherRiggedOrExplicitlyUnriggable}
 * — which is a stronger check than the size pin ever was, because it names the
 * uncovered id rather than reporting that two numbers differ.
 */
final class ModelSkeletons
{
	private static final Map<Integer, Set<Integer>> BY_MODEL = new TreeMap<>();

