	private ModelSkeletons()
	{
	}

	private static void rig(int framemap, int... modelIds)
	{
		for (int modelId : modelIds)
		{
			put(modelId, framemap);
		}
	}

	private static void sharedRig(int modelId, int... framemaps)
	{
		for (int framemap : framemaps)
		{
			put(modelId, framemap);
		}
	}

	private static void put(int modelId, int framemap)
	{
		Set<Integer> framemaps = BY_MODEL.get(modelId);
		if (framemaps == null)
		{
			framemaps = new TreeSet<>();
			BY_MODEL.put(modelId, framemaps);
		}
		if (!framemaps.add(framemap))
		{
			throw new IllegalStateException("duplicate framemap entry for model " + modelId);
		}
	}

	private static void body(int npcId, int framemap)
	{
		if (BY_BODY.put(npcId, framemap) != null)
		{
			throw new IllegalStateException("duplicate framemap entry for NPC body " + npcId);
		}
	}

	/**
	 * @return every framemap this model id was seen rigged to, or an empty set when no
	 * NPC in the cache uses it and nothing can be inferred
	 */
	static Set<Integer> framemapsOf(int modelId)
	{
		Set<Integer> framemaps = BY_MODEL.get(modelId);
		return framemaps == null ? Collections.<Integer>emptySet()
			: Collections.unmodifiableSet(framemaps);
	}

	/**
	 * @return the framemap the NPC whose whole appearance a record clones is rigged to,
	 * or {@code null} if this table has no row for it — which
	 * {@link AnimationSkeletonTest} treats as a failure rather than as a pass
	 */
	static Integer framemapOfBody(int npcAppearanceId)
	{
		return BY_BODY.get(npcAppearanceId);
	}

	/**
	 * The rig a record's own appearance implies: the NPC body it wears if it has one,
	 * otherwise every framemap its raw model ids were seen on.
	 *
	 * <p>The precedence is not a convenience — it mirrors the runtime.
	 * {@code LivelyEntity.loadParts()} sources the parts and the recolours from the
	 * {@code npcAppearanceId} <i>instead of</i> from the record when it is set, so an
	 * NPC-dressed figure's rig is that NPC's whether or not the record also carries
	 * model ids.
	 *
	 * @return the framemaps, or an empty set when the record's appearance carries no
	 * evidence either way
	 */
	static Set<Integer> impliedRig(EntityDefinition entity)
	{
		if (entity.getNpcAppearanceId() > 0)
		{
			Integer framemap = framemapOfBody(entity.getNpcAppearanceId());
			return framemap == null ? Collections.<Integer>emptySet()
				: Collections.singleton(framemap);
		}

		Set<Integer> framemaps = new TreeSet<>();
		for (int modelId : entity.getModelIds())
		{
			framemaps.addAll(framemapsOf(modelId));
		}
		return framemaps;
	}

	static Map<Integer, Set<Integer>> all()
	{
		return Collections.unmodifiableMap(BY_MODEL);
	}

	static Map<Integer, Integer> bodies()
	{
		return Collections.unmodifiableMap(BY_BODY);
	}
}

package com.matthewmariner.livelycities;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * {@link NpcAppearance}: given a client's answer about an NPC id, what does the
 * appearance come out as, and which answers are refused?
 *
 * <p>The four fixture shapes here exist because the real
 * {@code NPCComposition}'s three array accessors are each a bare {@code getfield}
 * in 1.12.36 (see {@link NpcAppearance}'s javadoc), so {@code null} is a value the
 * client really hands out and a fake that only ever produced arrays would leave
 * every null check untestable. {@link FakeNpcComposition} makes each one settable
 * separately for that reason.
 */
public class NpcAppearanceTest
{
	private static final int WHITE_KNIGHT = 1798;
	private static final String LABEL = "Rob@3158,3494,0";

	private FakeClient client;

	@Before
	public void setUp()
	{
		client = new FakeClient();
	}

	@Test
	public void aCompositionsModelsAndPaletteBothComeThrough()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.recoloured(
			"White Knight",
			new int[]{217, 305, 246},
			new short[]{10, 20},
			new short[]{11, 21}));

		NpcAppearance appearance = NpcAppearance.resolve(client, WHITE_KNIGHT, LABEL);

		assertNotNull(appearance);
		assertEquals(WHITE_KNIGHT, appearance.getNpcId());
		assertEquals("White Knight", appearance.getNpcName());
		assertArrayEquals(new int[]{217, 305, 246}, appearance.getModelIds());
		assertArrayEquals(new short[]{10, 20}, appearance.getRecolorFind());
		assertArrayEquals(new short[]{11, 21}, appearance.getRecolorReplace());
	}

	/**
	 * Most NPCs declare no recolours at all, and the client answers that with two
	 * {@code null}s rather than two empty arrays. An appearance with an empty palette
	 * has to be a working appearance, not a refused one — otherwise the mechanism
	 * would only work for NPCs that happen to be recoloured.
	 */
	@Test
	public void anNpcWithNoPaletteStillResolves()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", 217, 305));

		NpcAppearance appearance = NpcAppearance.resolve(client, WHITE_KNIGHT, LABEL);

		assertNotNull(appearance);
		assertEquals(0, appearance.getRecolorFind().length);
		assertEquals(0, appearance.getRecolorReplace().length);
		assertArrayEquals(new int[]{217, 305}, appearance.getModelIds());
	}

	/**
	 * Lopsided recolour arrays are truncated to the matched pairs, exactly as
	 * {@code EntityDefinition.recolorPairCount} does for an authored record — because
	 * the alternative is an {@code ArrayIndexOutOfBoundsException} inside the render
	 * loop, and the two halves are indexed together in {@code LivelyEntity.assemble}.
	 *
	 * <p>Asserted in both directions: a longer {@code find} and a longer
	 * {@code replace} are different array accesses, and a fixture that only tried one
	 * would leave the other's bound unchecked.
	 */
	@Test
	public void lopsidedRecolourArraysAreTruncatedToTheMatchedPairs()
	{
		client.withNpc(1, FakeNpcComposition.recoloured(
			"Longer find", new int[]{217}, new short[]{10, 20, 30}, new short[]{11}));
		client.withNpc(2, FakeNpcComposition.recoloured(
			"Longer replace", new int[]{217}, new short[]{10}, new short[]{11, 21, 31}));

		NpcAppearance longerFind = NpcAppearance.resolve(client, 1, LABEL);
		assertNotNull(longerFind);
		assertArrayEquals(new short[]{10}, longerFind.getRecolorFind());
		assertArrayEquals(new short[]{11}, longerFind.getRecolorReplace());

		NpcAppearance longerReplace = NpcAppearance.resolve(client, 2, LABEL);
		assertNotNull(longerReplace);
		assertArrayEquals(new short[]{10}, longerReplace.getRecolorFind());
		assertArrayEquals(new short[]{11}, longerReplace.getRecolorReplace());
	}

	/**
	 * One half of the palette present and the other {@code null} is the same
	 * lopsidedness with a harder edge — a {@code .length} on the null one would be an
	 * NPE inside a render pass.
	 */
	@Test
	public void oneHalfOfThePaletteBeingNullYieldsNoPaletteRatherThanAThrow()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.recoloured(
			"Half a palette", new int[]{217}, new short[]{10, 20}, null));

		NpcAppearance appearance = NpcAppearance.resolve(client, WHITE_KNIGHT, LABEL);

		assertNotNull(appearance);
		assertEquals(0, appearance.getRecolorFind().length);
		assertEquals(0, appearance.getRecolorReplace().length);
	}

	/**
	 * The ordinary "this id no longer exists" case, and the reason
	 * {@code NpcAppearance} has a try/catch at all: 1.12.36 throws rather than
	 * returning null for an id whose archive entry is missing. See
	 * {@code FakeClient.getNpcDefinition}.
	 */
	@Test
	public void anIdThatThrowsResolvesToNullRatherThanPropagating()
	{
		assertNull(NpcAppearance.resolve(client, 999999, LABEL));
		assertTrue("the client still has to have been asked, or this proves nothing",
			client.npcDefinitionsRequested().contains(999999));
	}

	/** The other way of not getting an answer: a null composition. */
	@Test
	public void anIdThatResolvesToNoCompositionResolvesToNull()
	{
		client.setNullNpcComposition(WHITE_KNIGHT);
		assertNull(NpcAppearance.resolve(client, WHITE_KNIGHT, LABEL));
	}

	/**
	 * A composition that resolves but has nothing to draw. Three shapes of it, all
	 * refused, because "the lookup worked" is not the same question as "there is a
	 * body" — and an audit that only checked the lookup would report a green id for
	 * an invisible citizen.
	 */
	@Test
	public void aCompositionWithNothingToDrawIsRefused()
	{
		client.withNpc(1, FakeNpcComposition.withoutModels("Null models", null));
		client.withNpc(2, FakeNpcComposition.withoutModels("Empty models", new int[0]));
		client.withNpc(3, FakeNpcComposition.withoutModels("Only empty slots", new int[]{-1, 0}));

		assertNull("a null getModels() is not an empty array", NpcAppearance.resolve(client, 1, LABEL));
		assertNull(NpcAppearance.resolve(client, 2, LABEL));
		assertNull("every slot empty is nothing to draw", NpcAppearance.resolve(client, 3, LABEL));
	}

	/**
	 * A composition with <i>some</i> empty slots keeps the rest. That is not the
	 * "partial model" this plugin refuses: a {@code -1} in a composition's array is
	 * the client's own "this equipment slot is empty", whereas a partial build is a
	 * part that failed to <i>load</i> — which {@code LivelyEntity.loadParts} still
	 * refuses wholesale.
	 */
	@Test
	public void emptySlotsAreDroppedAndTheRealModelsKept()
	{
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("Gappy", 217, -1, 305, 0, 246));

		NpcAppearance appearance = NpcAppearance.resolve(client, WHITE_KNIGHT, LABEL);

		assertNotNull(appearance);
		assertArrayEquals(new int[]{217, 305, 246}, appearance.getModelIds());
	}

	/**
	 * A non-positive id never reaches the client. Not reachable through
	 * {@code EntityDefinition}, which drops one at the validation gate — asserted
	 * here so the guard cannot be removed on the grounds that nothing exercises it.
	 */
	@Test
	public void aNonPositiveIdIsRefusedWithoutAskingTheClient()
	{
		assertNull(NpcAppearance.resolve(client, 0, LABEL));
		assertNull(NpcAppearance.resolve(client, -1798, LABEL));
		assertTrue("the client must not be asked about a sentinel",
			client.npcDefinitionsRequested().isEmpty());
	}

	/**
	 * The models array is not the composition's own. The client caches compositions
	 * ({@code pl.cy}), so handing out the live array would let a recolour or a future
	 * in-place edit reach every other user of that NPC — the same reasoning behind
	 * {@code LivelyEntity.assemble} always calling {@code mergeModels} before
	 * touching colours.
	 */
	@Test
	public void theModelsArrayIsACopyOfTheCompositionsOwn()
	{
		int[] compositionModels = {217, 305};
		client.withNpc(WHITE_KNIGHT, FakeNpcComposition.of("White Knight", compositionModels));

		NpcAppearance appearance = NpcAppearance.resolve(client, WHITE_KNIGHT, LABEL);

		assertNotNull(appearance);
		appearance.getModelIds()[0] = 999;
		assertEquals("the composition's own array must not have been written to",
			217, compositionModels[0]);
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Everything the side panel draws, decided here where there is no Swing and no client.
 *
 * <p>{@link LivelyCitiesPanel} is layout and mouse listeners; this is the part with
 * answers in it, and separating them is what makes the answers assertable on a build
 * machine with no display. So the rules that matter are all here: which checkbox a card
 * reads, where the live figures come from, what happens to a uuid nobody can place, and
 * the ordering the whole thing is unusable without.
 */
public class PanelModelTest
{
	/** Varrock square. Region 12852, which {@link City#VARROCK} claims. */
	private static final WorldPoint IN_VARROCK = new WorldPoint(3225, 3360, 0);

	/**
	 * A tile in region 11422 — Keldagrim, which no city claims and which ships no region
	 * file. The same region {@code CityTest.aRegionNoCityClaimsIsStillShown} uses, so the
	 * two tests are talking about the same "nowhere".
	 */
	private static final WorldPoint NOWHERE = new WorldPoint(2845, 10120, 0);

	private final FakeConfig config = new FakeConfig();

	// --- the city cards -------------------------------------------------------

	/**
	 * Each card reads its own city's checkbox, and no other's.
	 *
	 * <p>The same composition {@code CityTest} asserts for the render path, asserted
	 * again for the panel path, and it is not redundant: the panel walks
	 * {@code City.values()} building rows in a loop, which is exactly the shape that
	 * makes an off-by-one — every card showing the state of the city after it — a
	 * plausible defect. {@link FakeConfig} wires all nine getters to their own
	 * {@link City}, so switching off exactly one city and finding exactly one card off
	 * is the two mappings composing to the identity.
	 */
	@Test
	public void everyCardReadsItsOwnCityCheckbox()
	{
		for (City target : City.values())
		{
			PanelModel model = model(new FakeConfig().disableOnly(target), IN_VARROCK,
				SceneCensus.EMPTY, directory());

			assertEquals("one card per city", City.values().length, model.getCities().size());

			for (PanelModel.CityRow row : model.getCities())
			{
				if (row.getCity() == target)
				{
					assertFalse("unticking " + target + " has to switch its own card off",
						row.isEnabled());
				}
				else
				{
					assertTrue("unticking " + target + " must not switch off " + row.getCity(),
						row.isEnabled());
				}
			}
		}
	}

	/** The cards come out in {@link City} order, which is the order the checkboxes are in. */
	@Test
	public void theCardsAreInTheSameOrderAsTheCheckboxes()
	{
		PanelModel model = model(config, IN_VARROCK, SceneCensus.EMPTY, directory());

		City[] cities = City.values();
		for (int i = 0; i < cities.length; i++)
		{
			assertEquals("card " + i, cities[i], model.getCities().get(i).getCity());
		}
	}

	/**
	 * A card's citizen count is the dataset's, and its live count is the census's.
	 *
	 * <p>Two different numbers about the same city, and the reason to check them
	 * together is that they are trivially confusable: a card that showed the live count
	 * where the roster count belongs would read "Varrock, 0 citizens" from the login
	 * screen, which is the panel telling a first-time user the plugin has no data.
	 */
	@Test
	public void aCardShowsTheDatasetsCountAndTheScenesCountSeparately()
	{
		EnumMap<City, Integer> active = new EnumMap<>(City.class);
		active.put(City.VARROCK, 34);
		active.put(City.GRAND_EXCHANGE, 7);

		PanelModel model = model(config, IN_VARROCK,
			new SceneCensus(41, 190, 12, 2, active), directory());

		assertEquals("Varrock's roster", 71, row(model, City.VARROCK).getCitizens());
		assertEquals("and what is on screen of it", 34, row(model, City.VARROCK).getActive());

		// The Grand Exchange is a region away, so it is not where the player is and its
		// figures are still up. A card that only reported the live count for the city
		// the player stands in would lose this, and it is exactly the thing no config
		// screen can show.
		assertEquals(24, row(model, City.GRAND_EXCHANGE).getCitizens());
		assertEquals(7, row(model, City.GRAND_EXCHANGE).getActive());
		assertFalse(row(model, City.GRAND_EXCHANGE).isHere());

		assertEquals("a city with nothing up says so", 0, row(model, City.CATHERBY).getActive());
		assertEquals("but still knows its roster", 24, row(model, City.CATHERBY).getCitizens());
	}

	/**
	 * The nine cards survive being logged out. Only the live numbers go.
	 *
	 * <p>A panel that emptied itself at the login screen would be blank at the one
	 * moment somebody opens it to find out what the plugin does.
	 */
	@Test
	public void theCardsAreThereWithNoWorldAtAll()
	{
		PanelModel model = PanelModel.loggedOut(config,
			Collections.emptySet(), Collections.emptySet(), directory());

		assertFalse(model.isInWorld());
		assertNull("nowhere to be", model.getHere());
		assertEquals(0, model.getRegionId());
		assertEquals(City.values().length, model.getCities().size());
		assertEquals("the roster is a fact about the jar, not the session",
			71, row(model, City.VARROCK).getCitizens());
		assertEquals("what is on screen is a fact about the session",
			0, row(model, City.VARROCK).getActive());
		assertTrue("and nobody is overridden by default", model.getOverrides().isEmpty());
	}

	/**
	 * <b>And the overrides are not a live number.</b>
	 *
	 * <p>Hiding and muting live in the profile, so they survive having no world exactly
	 * the way the nine cards do. This method used to pass {@code Collections.emptySet()}
	 * for both, which put "Hidden and muted (0)" over "Nobody is hidden or muted." in
	 * front of anybody who had hidden somebody and then opened the panel at the login
	 * screen — a confident wrong answer where there had been an absent one.
	 */
	@Test
	public void beingLoggedOutUnhidesNobody()
	{
		FakeRegions regions = new FakeRegions();
		EntityDefinition someone = regions.citizen(12852, 3225, 3360, 0);

		PanelModel model = PanelModel.loggedOut(config,
			Collections.singleton(someone.getUuid()), Collections.emptySet(),
			new CitizenDirectory(regions));

		assertFalse("still nowhere to be", model.isInWorld());
		assertEquals("and still hidden", 1, model.getOverrides().size());
		assertTrue(model.getOverrides().get(0).isHidden());
	}

	// --- where the player is --------------------------------------------------

	@Test
	public void standingInACityNamesIt()
	{
		PanelModel model = model(config, IN_VARROCK, SceneCensus.EMPTY, directory());

		assertTrue(model.isInWorld());
		assertEquals(City.VARROCK, model.getHere());
		assertEquals(12852, model.getRegionId());

		PanelModel.CityRow varrock = row(model, City.VARROCK);
		assertTrue("and the card says so", varrock.isHere());
		for (PanelModel.CityRow other : model.getCities())
		{
			if (other.getCity() != City.VARROCK)
			{
				assertFalse(other.getCity() + " is not where the player is", other.isHere());
			}
		}
	}

	/**
	 * Standing somewhere the dataset does not cover is the ordinary case, not an error.
	 *
	 * <p>The plugin ships 27 of the game's regions. Almost everywhere a player stands is
	 * one of the others, so the panel has to have something true to say there — the
	 * region id — rather than a blank or a city it guessed.
	 */
	@Test
	public void standingOutsideEveryCityStillReportsARegion()
	{
		PanelModel model = model(config, NOWHERE, SceneCensus.EMPTY, directory());

		assertTrue(model.isInWorld());
		assertNull("no city claims Keldagrim", model.getHere());
		assertEquals(RenderPolicy.regionIdOf(NOWHERE.getX(), NOWHERE.getY()), model.getRegionId());
		for (PanelModel.CityRow row : model.getCities())
		{
			assertFalse(row.getCity() + " must not claim the player", row.isHere());
		}
	}

	// --- the density dial -----------------------------------------------------

	@Test
	public void theDensityShownIsTheOneConfigured()
	{
		for (CrowdDensity density : CrowdDensity.values())
		{
			PanelModel model = model(new FakeConfig().setCrowdDensity(density),
				IN_VARROCK, SceneCensus.EMPTY, directory());
			assertEquals(density, model.getDensity());
		}
	}

	/**
	 * A density this build does not know about deserialises to {@code null}, and the
	 * panel shows {@code FULL} rather than nothing selected.
	 *
	 * <p>The same case {@code EntityScene.runVisibilityPass} already handles, and the
	 * same answer. It matters more here than there: a panel with no chip lit has no
	 * chip to click back to, so a profile written by a future version would leave a user
	 * with a dial they cannot operate.
	 */
	@Test
	public void anUnknownDensityFallsBackToFullRatherThanToNothing()
	{
		// Implemented rather than subclassed: FakeConfig is final, and every other getter
		// here wants its interface default anyway — this fixture is about exactly one
		// method returning null.
		LivelyCitiesConfig fromTheFuture = new LivelyCitiesConfig()
		{
			@Override
			public CrowdDensity crowdDensity()
			{
				return null;
			}
		};

		assertNull("the fixture has to actually hand back null", fromTheFuture.crowdDensity());
		assertEquals(CrowdDensity.FULL,
			model(fromTheFuture, IN_VARROCK, SceneCensus.EMPTY, directory()).getDensity());
	}

	// --- the hidden-and-muted list -------------------------------------------

	/**
	 * A citizen who is both hidden and muted is one row carrying both flags, not two
	 * rows.
	 *
	 * <p>Two rows would be two entries with the same name and no indication that they
	 * are one person, and restoring one of them would leave the other looking unchanged.
	 */
	@Test
	public void oneCitizenIsOneRowHoweverManyWaysTheyAreOverridden()
	{
		FakeRegions regions = new FakeRegions();
		CitizenDirectory directory = new CitizenDirectory(regions);

		UUID both = UUID.fromString("00000000-0000-4000-8000-000000000001");
		UUID justHidden = UUID.fromString("00000000-0000-4000-8000-000000000002");
		UUID justMuted = UUID.fromString("00000000-0000-4000-8000-000000000003");

		PanelModel model = model(config, IN_VARROCK, SceneCensus.EMPTY, directory,
			uuids(both, justHidden), uuids(both, justMuted));

		assertEquals("three citizens, three rows", 3, model.getOverrides().size());

		assertTrue(find(model, both).isHidden());
		assertTrue(find(model, both).isMuted());
		assertTrue(find(model, justHidden).isHidden());
		assertFalse(find(model, justHidden).isMuted());
		assertFalse(find(model, justMuted).isHidden());
		assertTrue(find(model, justMuted).isMuted());
	}

	/**
	 * The rows carry the name and the city out of the directory.
	 *
	 * <p>This is the whole point of the feature. "Unhide all" needs no names; a list you
	 * restore one row from is only a repair if the row says who it is, and the citizen
	 * you hid is usually a city away by the time you regret it.
	 */
	@Test
	public void aRowNamesTheCitizenAndThePlaceTheyBelongTo()
	{
		CitizenDirectory directory = new CitizenDirectory(new RegionDataLoader(TestGson.injected()));

		// A real shipped uuid, taken from the dataset rather than typed, so this cannot
		// pass by naming a citizen the fixture invented.
		UUID someone = directory.authoredUuids().get(0);
		CitizenDirectory.Entry expected = directory.find(someone);
		assertNotNull("the directory has to be able to place its own uuid", expected);

		PanelModel model = model(config, IN_VARROCK, SceneCensus.EMPTY, directory,
			Collections.emptySet(), uuids(someone));

		PanelModel.OverrideRow row = find(model, someone);
		assertEquals(expected.getName(), row.getName());
		assertEquals(expected.getName(), row.getDisplayName());
		assertEquals(expected.getCity(), row.getCity());
	}

	/**
	 * A uuid nobody can place still gets a row, and the row does not invent a name.
	 *
	 * <p>Reachable in practice rather than hypothetically: fifteen places were dropped
	 * from the dataset on 2026-08-24, and a profile that hid somebody in Canifis before
	 * then still holds their uuid. The honest outcome is a row you can clear, labelled
	 * with something that is true.
	 */
	@Test
	public void aUuidTheDirectoryCannotPlaceIsStillARowYouCanClear()
	{
		UUID stranger = UUID.fromString("deadbeef-0000-4000-8000-000000000001");

		PanelModel model = model(config, IN_VARROCK, SceneCensus.EMPTY,
			new CitizenDirectory(new FakeRegions()), uuids(stranger), Collections.emptySet());

		PanelModel.OverrideRow row = find(model, stranger);
		assertNull("no name was invented", row.getName());
		assertNull("and no city", row.getCity());
		assertEquals("but the row still says something", "Citizen deadbeef", row.getDisplayName());
		assertTrue(row.isHidden());
	}

	/**
	 * The row order is the same every time, whatever order the two sets arrive in.
	 *
	 * <p><b>This is the guard that makes the list clickable at all.</b> A model is
	 * composed once a game tick while the panel is open, so an order that depended on
	 * set iteration would reshuffle the rows about a hundred times a minute — and the
	 * one thing anybody does with this list is click a specific row.
	 *
	 * <p>The two runs below are given the same uuids in opposite insertion orders, which
	 * is exactly what a user produces by hiding people in a different sequence. A
	 * {@code LinkedHashSet} — which is what {@link UuidSetting} hands out — preserves
	 * that sequence, so this is the real input rather than a contrived one.
	 */
	@Test
	public void theRowsComeOutInTheSameOrderHoweverTheyWentIn()
	{
		CitizenDirectory directory = new CitizenDirectory(new RegionDataLoader(TestGson.injected()));
		List<UUID> shipped = directory.authoredUuids();
		assertTrue("the dataset has to be on the classpath", shipped.size() > 20);

		List<UUID> forwards = shipped.subList(0, 12);
		List<UUID> backwards = new ArrayList<>(forwards);
		Collections.reverse(backwards);

		List<PanelModel.OverrideRow> first = model(config, IN_VARROCK, SceneCensus.EMPTY,
			directory, new LinkedHashSet<>(forwards), Collections.emptySet()).getOverrides();
		List<PanelModel.OverrideRow> second = model(config, IN_VARROCK, SceneCensus.EMPTY,
			directory, new LinkedHashSet<>(backwards), Collections.emptySet()).getOverrides();

		assertEquals(12, first.size());
		assertEquals(first.size(), second.size());
		for (int i = 0; i < first.size(); i++)
		{
			assertEquals("row " + i + " has to be the same citizen both times",
				first.get(i).getUuid(), second.get(i).getUuid());
		}

		// And the order is the one claimed: by city, then by name. Asserted rather than
		// assumed, because "stable" and "sorted the way the panel says" are two claims
		// and only the first survives a comparator that sorted on the uuid alone.
		for (int i = 1; i < first.size(); i++)
		{
			String previous = key(first.get(i - 1));
			String current = key(first.get(i));
			assertTrue("'" + previous + "' must not sort after '" + current + "'",
				previous.compareTo(current) <= 0);
		}
	}

	/** Nothing overridden is an empty list rather than a null one. */
	@Test
	public void aFreshProfileHasNoRows()
	{
		assertTrue(model(config, IN_VARROCK, SceneCensus.EMPTY, directory())
			.getOverrides().isEmpty());
	}

	// --- the census passes through untouched ---------------------------------

	@Test
	public void theLiveTotalsAreTheCensussOwn()
	{
		EnumMap<City, Integer> byCity = new EnumMap<>(City.class);
		byCity.put(City.LUMBRIDGE, 5);
		SceneCensus census = new SceneCensus(5, 61, 3, 1, byCity);

		PanelModel model = model(config, IN_VARROCK, census, directory());

		assertEquals(5, model.getCensus().getActive());
		assertEquals(61, model.getCensus().getInScope());
		assertEquals(3, model.getCensus().getWalking());
		assertEquals(1, model.getCensus().getTalking());
	}

	// --- helpers ---------------------------------------------------------------

	/** The real shipped dataset, which is what the card counts have to come from. */
	private static CitizenDirectory directory()
	{
		return new CitizenDirectory(new RegionDataLoader(TestGson.injected()));
	}

	private static PanelModel model(
		LivelyCitiesConfig config, WorldPoint at, SceneCensus census, CitizenDirectory directory)
	{
		return model(config, at, census, directory, Collections.emptySet(), Collections.emptySet());
	}

	private static PanelModel model(
		LivelyCitiesConfig config,
		WorldPoint at,
		SceneCensus census,
		CitizenDirectory directory,
		Set<UUID> hidden,
		Set<UUID> muted)
	{
		return PanelModel.of(at, census, config, hidden, muted, directory);
	}

	private static Set<UUID> uuids(UUID... uuids)
	{
		return new LinkedHashSet<>(Arrays.asList(uuids));
	}

	private static PanelModel.CityRow row(PanelModel model, City city)
	{
		for (PanelModel.CityRow row : model.getCities())
		{
			if (row.getCity() == city)
			{
				return row;
			}
		}
		throw new AssertionError("no card for " + city);
	}

	private static PanelModel.OverrideRow find(PanelModel model, UUID uuid)
	{
		for (PanelModel.OverrideRow row : model.getOverrides())
		{
			if (row.getUuid().equals(uuid))
			{
				return row;
			}
		}
		throw new AssertionError("no row for " + uuid);
	}

	private static String key(PanelModel.OverrideRow row)
	{
		return (row.getCity() == null ? "￿" : row.getCity().getLabel()) + '�'
			+ row.getDisplayName();
	}
}

package com.matthewmariner.livelycities;

/**
 * The one rule the placement lint is built on, pulled out on its own so it has
 * its own test ({@code PlacementCompatibilityTest}) against a hand-built
 * fixture rather than only ever being exercised indirectly through the real
 * 142-citizen dataset.
 */
final class PlacementCompatibility
{
	private PlacementCompatibility()
	{
	}

	/**
	 * @param entityTheme the theme a citizen carries
	 * @param regionTheme the theme its region expects ({@code CityTheme.of(..)})
	 * @return {@code true} if a citizen with {@code entityTheme} may stand in a
	 * region expecting {@code regionTheme}
	 */
	static boolean isCompatible(Theme entityTheme, Theme regionTheme)
	{
		// A plain Gielinor citizen needs no regional justification.
		if (entityTheme == Theme.GENERIC)
		{
			return true;
		}

		// Otherwise the two have to actually agree. Theme.UNIQUE_BOSS is never
		// the region theme CityTheme hands out for any city (see CityTheme), so
		// this equality can never hold for it in practice — it is compatible
		// with nothing, everywhere, by construction rather than by a special
		// case here.
		return entityTheme == regionTheme;
	}
}

package com.matthewmariner.livelycities;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The compatibility rule in isolation, against a fixture with more than one
 * theme in it on purpose — a fixture with only ever {@code GENERIC} vs
 * {@code GENERIC} could not tell a correct rule from one that always returns
 * {@code true}.
 */
public class PlacementCompatibilityTest
{
	@Test
	public void aGenericEntityFitsAnyRegion()
	{
		// Every theme there is, so a new constant that this rule happens to reject
		// cannot slip in unnoticed.
		for (Theme regionTheme : Theme.values())
		{
			assertTrue("a generic citizen must fit a " + regionTheme + " region",
				PlacementCompatibility.isCompatible(Theme.GENERIC, regionTheme));
		}
	}

	@Test
	public void aThemedEntityFitsItsOwnRegionTheme()
	{
		assertTrue(PlacementCompatibility.isCompatible(Theme.DESERT, Theme.DESERT));
		assertTrue(PlacementCompatibility.isCompatible(Theme.CAMEO, Theme.CAMEO));
	}

	/**
	 * The fixture deliberately uses <b>two different</b> non-generic themes on the
	 * region side. One would not be enough: a rule that returned {@code true}
	 * whenever the region theme was anything other than the one theme tested would
	 * pass, and the mismatch case is the whole point of the class.
	 */
	@Test
	public void aThemedEntityDoesNotFitAMismatchedRegionTheme()
	{
		assertFalse(PlacementCompatibility.isCompatible(Theme.DESERT, Theme.GENERIC));
		assertFalse(PlacementCompatibility.isCompatible(Theme.DESERT, Theme.CAMEO));
		assertFalse(PlacementCompatibility.isCompatible(Theme.CAMEO, Theme.DESERT));
		assertFalse(PlacementCompatibility.isCompatible(Theme.CAMEO, Theme.GENERIC));
	}

	/**
	 * {@link Theme#UNIQUE_BOSS} is never a region's theme (see {@link CityTheme}
	 * — no city maps to it), so this can never fire in practice. The rule
	 * itself, checked in isolation, is a plain equality: it is
	 * {@code CityTheme}'s job to keep the region side of that equality from
	 * ever being {@code UNIQUE_BOSS}, which {@code PlacementLintTest} guards
	 * separately, and both have to hold for a boss citizen to always be flagged.
	 */
	@Test
	public void aUniqueBossOnlyMatchesAUniqueBossRegionTheme()
	{
		assertTrue(PlacementCompatibility.isCompatible(Theme.UNIQUE_BOSS, Theme.UNIQUE_BOSS));
		assertFalse(PlacementCompatibility.isCompatible(Theme.UNIQUE_BOSS, Theme.GENERIC));
		assertFalse(PlacementCompatibility.isCompatible(Theme.UNIQUE_BOSS, Theme.DESERT));
		assertFalse(PlacementCompatibility.isCompatible(Theme.UNIQUE_BOSS, Theme.CAMEO));
	}
}

package com.matthewmariner.livelycities;

import java.util.HashMap;
import java.util.Map;

/**
 * Deliberate oddities the placement lint would otherwise flag, each carrying
 * the one-line reason it is fine as-is.
 *
 * <p><b>What does not belong here.</b> This list is for placements judged fine
 * on inspection — not a place to quietly launder a confirmed bug back to green.
 *
 * <p>The worked example is historical now, and is kept because the distinction it
 * draws is the reason this class is so short. Region 14131 (the Barrows) shipped
 * six citizens named after the Barrows Brothers, carrying "The ghost of
 * &lt;Brother&gt;." examine text, and tagged {@link Theme#UNIQUE_BOSS} — the
 * confirmed offender this lint exists to catch. They were deliberately
 * <b>never</b> added here. They were fixed in the data on 2026-08-23 instead:
 * renamed to generic "Barrow wight"s and retagged to the Morytania theme, which
 * the Barrows region did claim. The lint went green because the content changed,
 * not because the check was told to look away. (Region 14131 was then removed
 * outright in the nine-city cut on 2026-08-24, so neither the citizens nor that
 * theme ship any more.)
 *
 * <p>That is the distinction worth preserving. An exception here would have made
 * the build green while leaving the game exactly as wrong as it was.
 */
final class PlacementExceptions
{
	private static final Map<String, String> BY_UUID = build();

	private PlacementExceptions()
	{
	}

	static boolean isExcepted(String uuid)
	{
		return BY_UUID.containsKey(uuid);
	}

	static String reasonFor(String uuid)
	{
		return BY_UUID.get(uuid);
	}

	static Map<String, String> all()
	{
		return BY_UUID;
	}

	private static Map<String, String> build()
	{
		Map<String, String> byUuid = new HashMap<>();

		byUuid.put("ee3c3e90-7fe5-4387-a976-74463163dab7", // "Ali", Varrock (12853)
			"examine text ('He looks like he's from Al-Kharid.') frames him as a living "
				+ "transplant working in Varrock, not a copy of the Al Kharid citizen standing "
				+ "somewhere it doesn't belong — a capital city plausibly has a few immigrants");

		byUuid.put("fc28fec2-c105-49ab-8040-e36dda874646", // "Afrah", Varrock (12853)
			"same reasoning as 'Ali' above: her own examine text ('She looks like she's from "
				+ "Al-Kharid.') is the in-fiction explanation for why a desert-coded citizen is "
				+ "standing in Varrock");

		return byUuid;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.annotation.Nullable;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The placement lint: every shipped citizen's {@link Theme}
 * ({@link EntityTheme}) has to be compatible ({@link PlacementCompatibility})
 * with the theme its region expects ({@link CityTheme}, built on {@link City}),
 * or be named in {@link PlacementExceptions} with a reason.
 *
 * <p>This is the v1 backlog row for the predecessor plugin's 303-upvote
 * complaint — Barrows brothers wandering above their own crypts — and the
 * separate complaint about a Karamja NPC standing in Varrock square. Both were
 * silent until a player noticed; this makes the same shape of mistake a red
 * test instead.
 *
 * <p><b>It found one real offender, and that offender was fixed.</b> The
 * six citizens in region 14131 were named after the Barrows Brothers, with
 * "The ghost of &lt;Brother&gt;." examine text — the 303-upvote complaint about
 * the predecessor. {@link EntityTheme} tagged them {@link Theme#UNIQUE_BOSS},
 * which {@link CityTheme} maps to no region, so the lint went red. On
 * 2026-08-23 they were renamed in the dataset to generic "Barrow wight"s
 * (placements, models and animations untouched — only the identities) and
 * retagged to the Morytania theme, which the Barrows region did claim. The lint
 * went green because they were now honestly undead in Morytania, not because the
 * check was relaxed: {@link PlacementExceptions} was deliberately <b>not</b>
 * used, since that list is for placements judged fine on inspection and this one
 * was not.
 *
 * <p><b>Region 14131 was then removed outright</b> in the nine-city cut on
 * 2026-08-24, along with fourteen other thin places. That costs this file its
 * only historical example of the rule biting real content — the live coverage is
 * now the two Al Kharid transplants in Varrock, which violate and are excepted,
 * and {@link #everyExceptionWouldActuallyViolateWithoutIt} is what keeps that
 * exercised. It is a genuinely smaller sample than it was, and it is recorded
 * here rather than quietly absorbed.
 *
 * <p><b>The six cameos are reasoned about, not exempted.</b> They are the only
 * player-shaped named humans in the dataset and they stand in the Grand
 * Exchange, which is exactly the shape of content this lint exists for — so
 * they carry {@link Theme#CAMEO}, which {@link CityTheme} maps to the Grand
 * Exchange and to nothing else. The main test below therefore passes them
 * because they are at home, in the same way the Barrow wights pass because they
 * are honestly undead in Morytania; copy one into Varrock square and it goes
 * red. {@link PlacementExceptions} was deliberately not used, and
 * {@code CameoPlacementTest} owns the two guards this file cannot state —
 * that every cameo in the data is tagged, and that {@code CAMEO} is mapped to
 * exactly one city.
 *
 * <p><b>Standing limitation, worth knowing.</b> Nothing in the shipped data
 * carries {@link Theme#UNIQUE_BOSS} any more, so the rule that catches a
 * boss impersonator is live but currently unexercised by real content —
 * {@link PlacementCompatibilityTest} is the only thing keeping it honest.
 * A future dataset that reintroduces a named boss is caught only if someone
 * also adds its uuid to {@link EntityTheme}, which is a manual step. That is
 * the lint's weakest seam. It is narrower than it was for cameos specifically:
 * the dataset carries its own {@code cameo} flag, so a cameo that nobody
 * remembered to tag is a red test rather than an invisible one.
 */
public class PlacementLintTest
{
	@Test
	public void everyShippedCitizenThemeIsCompatibleWithItsRegion()
	{
		List<String> violations = new ArrayList<>();

		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (PlacementExceptions.isExcepted(citizen.uuid))
			{
				continue;
			}

			City city = City.of(citizen.fileRegionId);
			Theme regionTheme = CityTheme.of(city);
			Theme entityTheme = EntityTheme.themeOf(citizen.uuid);

			if (!PlacementCompatibility.isCompatible(entityTheme, regionTheme))
			{
				violations.add(citizen + ": " + entityTheme + " citizen in a "
					+ regionTheme + " region (" + cityLabel(city) + ")");
			}
		}

		assertTrue("placement violation(s) — theme incompatible with region, and not excepted: "
				+ violations,
			violations.isEmpty());
	}

	/**
	 * Guards the poison property {@link Theme#UNIQUE_BOSS} depends on: if a
	 * future edit ever gave some city that theme, every boss-tier citizen in
	 * it would silently stop being flagged. Walks {@link City#values()}
	 * directly rather than trusting {@link CityTheme} to grade its own claim.
	 */
	@Test
	public void noCityIsEverMappedToTheUniqueBossTheme()
	{
		List<String> offenders = new ArrayList<>();
		for (City city : City.values())
		{
			if (CityTheme.of(city) == Theme.UNIQUE_BOSS)
			{
				offenders.add(city.getLabel());
			}
		}

		assertTrue("Theme.UNIQUE_BOSS must map to no city, or it stops flagging boss-tier "
				+ "citizens wherever it is mapped: " + offenders,
			offenders.isEmpty());
	}

	/**
	 * An exception with no reason, or a copy-pasted placeholder, is exactly
	 * what the class javadoc on {@code PlacementExceptions} warns is "how a
	 * lint dies" — this makes a blank one a red test instead of a silent one.
	 */
	@Test
	public void everyExceptionCarriesAReason()
	{
		for (Map.Entry<String, String> exception : PlacementExceptions.all().entrySet())
		{
			String reason = exception.getValue();
			assertTrue("exception " + exception.getKey() + " has no usable reason: '" + reason + "'",
				reason != null && reason.trim().length() >= 10);
		}
	}

	/**
	 * Every excepted uuid has to name a citizen that actually shipped — an
	 * exception for a uuid that got typo'd, or that named an entity later
	 * removed from the dataset, would silently protect nothing while looking
	 * like it protects something.
	 */
	@Test
	public void everyExceptionNamesAShippedCitizen()
	{
		List<String> shippedUuids = new ArrayList<>();
		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			shippedUuids.add(citizen.uuid);
		}

		List<String> stale = new ArrayList<>();
		for (String uuid : PlacementExceptions.all().keySet())
		{
			if (!shippedUuids.contains(uuid))
			{
				stale.add(uuid);
			}
		}

		assertTrue("exception(s) naming a uuid that is not in the shipped dataset: " + stale,
			stale.isEmpty());
	}

	/**
	 * The inverse of the previous two: an exception for a citizen who was
	 * never actually going to violate anything is a dead exception — it reads
	 * as protecting something and protects nothing. Confirms each excepted
	 * uuid genuinely fails {@link PlacementCompatibility#isCompatible} before
	 * the exception is consulted, i.e. that removing the exception would turn
	 * {@link #everyShippedCitizenThemeIsCompatibleWithItsRegion} red for it.
	 */
	@Test
	public void everyExceptionWouldActuallyViolateWithoutIt()
	{
		List<String> dead = new ArrayList<>();

		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			if (!PlacementExceptions.isExcepted(citizen.uuid))
			{
				continue;
			}

			Theme regionTheme = CityTheme.of(City.of(citizen.fileRegionId));
			Theme entityTheme = EntityTheme.themeOf(citizen.uuid);

			if (PlacementCompatibility.isCompatible(entityTheme, regionTheme))
			{
				dead.add(citizen + " is excepted but was never going to violate "
					+ "(already " + entityTheme + " in a " + regionTheme + " region)");
			}
		}

		assertTrue("dead exception(s) — remove them, they are not doing anything: " + dead,
			dead.isEmpty());
	}

	/**
	 * An echo is judged by the same lint as the citizen it came from, and passes it
	 * for the same reason.
	 *
	 * <p>{@link EntityTheme} is keyed on uuid and an echo's uuid is its own, so an
	 * echo is {@link Theme#GENERIC} to the table — and {@code GENERIC} is compatible
	 * with everywhere. That would be a hole if an echo could carry its source's
	 * <i>identity</i>: a second "Ali" in Varrock would be a desert transplant the lint
	 * could not see. It cannot, and this is the test that says why it cannot: an echo
	 * has no name and no examine text of its source's, so it is a plain Gielinor
	 * passer-by — which needs no regional justification, exactly like the 96 shipped
	 * citizens the table does not list.
	 *
	 * <p>What still has to hold is geography. An echo stands within
	 * {@link RenderPolicy#DATASET_OVERHANG_ALLOWANCE} tiles of its source and is filed
	 * under the same region file, so it is judged against the same city's theme — it
	 * cannot wander into a region with a different flavour, because it cannot wander
	 * at all.
	 */
	@Test
	public void everyEchoIsJudgedAgainstItsSourcesOwnRegionAndPassesAsAGenericPasserBy()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<String> violations = new ArrayList<>();
		int echoes = 0;

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertTrue("region " + regionId + " failed to load", region != null);

			Theme regionTheme = CityTheme.of(City.of(regionId));

			Map<UUID, EntityDefinition> sources = new HashMap<>();
			for (EntityDefinition entity : region.getEntities())
			{
				sources.put(entity.getUuid(), entity);
			}

			// The whole roster, which is how the scene derives them — an echo's tile
			// depends on everything else standing in its region.
			for (EntityDefinition echo : CitizenEcho.echoesOfRegion(region.getEntities()))
			{
				echoes++;
				EntityDefinition source = sources.get(echo.getEchoSourceUuid());
				assertTrue("every echo names a source from its own region file", source != null);

				Theme echoTheme = EntityTheme.themeOf(echo.getUuid().toString());
				if (echoTheme != Theme.GENERIC)
				{
					violations.add(echo.label() + " carries " + echoTheme
						+ " — an echo has no authored identity to carry a theme with");
				}

				if (!PlacementCompatibility.isCompatible(echoTheme, regionTheme))
				{
					violations.add(echo.label() + ": " + echoTheme + " echo in a "
						+ regionTheme + " region (" + cityLabel(City.of(regionId)) + ")");
				}

				if (echo.getRegionId() != regionId)
				{
					violations.add(echo.label() + " left the file its source was filed under");
				}

				if (echo.getCityRegionId() != source.getTileRegionId())
				{
					violations.add(echo.label() + " is judged by region " + echo.getCityRegionId()
						+ " rather than by its source's " + source.getTileRegionId());
				}

				if (RenderPolicy.tileDistance(
					source.getWorldLocation(), echo.getWorldLocation())
					> RenderPolicy.DATASET_OVERHANG_ALLOWANCE)
				{
					violations.add(echo.label() + " stands further from its source than the "
						+ "overhang allowance, so it could be judged against another city");
				}
			}
		}

		assertTrue("the dataset has to actually produce echoes for this to mean anything",
			echoes > 0);
		assertTrue("echo placement violation(s): " + violations, violations.isEmpty());
	}

	/**
	 * A human-readable summary of every non-generic themed citizen and its
	 * status, printed for review. Backed by a real assertion — cross-checked
	 * against an independently-computed count — so the printout cannot drift
	 * from what the other tests here actually checked.
	 */
	@Test
	public void printsAPlacementSummaryForHumanReview()
	{
		int themedCount = 0;
		int compatibleCount = 0;
		int exceptedCount = 0;
		int violationCount = 0;

		System.out.println("Lively Cities placement lint — non-generic citizens");
		System.out.println("region     theme            status        citizen");

		for (ShippedCitizens.Entry citizen : ShippedCitizens.all())
		{
			Theme entityTheme = EntityTheme.themeOf(citizen.uuid);
			if (entityTheme == Theme.GENERIC)
			{
				continue;
			}
			themedCount++;

			Theme regionTheme = CityTheme.of(City.of(citizen.fileRegionId));
			boolean compatible = PlacementCompatibility.isCompatible(entityTheme, regionTheme);
			boolean excepted = PlacementExceptions.isExcepted(citizen.uuid);

			String status;
			if (compatible)
			{
				compatibleCount++;
				status = "ok";
			}
			else if (excepted)
			{
				exceptedCount++;
				status = "excepted";
			}
			else
			{
				violationCount++;
				status = "VIOLATION";
			}

			System.out.println(String.format("%-10d %-16s %-13s %s",
				citizen.fileRegionId, entityTheme, status, citizen));
		}

		System.out.println("total themed: " + themedCount + ", ok: " + compatibleCount
			+ ", excepted: " + exceptedCount + ", violation: " + violationCount);

		assertEqualsInt("themed citizen count must partition into ok/excepted/violation with nothing left over",
			themedCount, compatibleCount + exceptedCount + violationCount);
	}

	private static void assertEqualsInt(String message, int expected, int actual)
	{
		assertFalse(message + " (expected " + expected + ", got " + actual + ")", expected != actual);
	}

	private static String cityLabel(@Nullable City city)
	{
		return city == null ? "unmapped region" : city.getLabel();
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;

/**
 * A {@link SidePanel} that remembers whether it is in the sidebar and what it was last
 * told to draw.
 *
 * <p><b>This is the whole reason {@link SidePanel} is an interface.</b> The real
 * implementation ends in a {@code ClientToolbar} (private constructor, unmockable, no
 * mocking framework here) and a {@code PluginPanel} (Swing, which a lifecycle test must
 * not need). The promise being kept — {@code shutDown()} leaves nothing registered —
 * has to hold on a build machine with no display, which is exactly where it is checked.
 *
 * <p>{@link #shown} is a count and not a flag, because "added once" and "added, removed,
 * added" are different states and only one of them is what {@code startUp} does.
 */
final class RecordingSidePanel implements SidePanel
{
	private final List<PanelModel> models = new ArrayList<>();

	private int shown;
	private int hidden;
	private boolean open;

	@Override
	public void show()
	{
		shown++;
	}

	@Override
	public void hide()
	{
		hidden++;

		// The real one tells the panel it is no longer in the sidebar, or the game tick
		// would go on composing models for it. Mirrored here so a test can assert the
		// consequence — that nothing is refreshed after a teardown — rather than the
		// call.
		open = false;
	}

	@Override
	public boolean isOpen()
	{
		return open;
	}

	@Override
	public void refresh(PanelModel model)
	{
		models.add(model);
	}

	/** Pretends the user clicked the toolbar button. */
	RecordingSidePanel opened()
	{
		open = true;
		return this;
	}

	/** @return whether the button is in the sidebar now: shown at least once, and not since hidden */
	boolean inSidebar()
	{
		return shown > hidden;
	}

	int getShown()
	{
		return shown;
	}

	int getHidden()
	{
		return hidden;
	}

	/** @return every model handed over, in order */
	List<PanelModel> models()
	{
		return models;
	}

	/** @return the most recent model, or {@code null} if nothing was ever drawn */
	@Nullable
	PanelModel last()
	{
		return models.isEmpty() ? null : models.get(models.size() - 1);
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
