	@Test
	public void capacityStopsExactlyAtTheCap()
	{
		int cap = RenderPolicy.MAX_ACTIVE_OBJECTS;

		assertTrue(RenderPolicy.hasCapacity(0));
		assertTrue(RenderPolicy.hasCapacity(cap - 1));
		assertFalse(RenderPolicy.hasCapacity(cap));
		assertFalse(RenderPolicy.hasCapacity(cap + 1));
	}

	@Test
	public void theBuildBudgetStopsExactlyAtItsCap()
	{
		int budget = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS;

		assertTrue(RenderPolicy.hasBuildBudget(0));
		assertTrue(RenderPolicy.hasBuildBudget(budget - 1));
		assertFalse(RenderPolicy.hasBuildBudget(budget));
		assertFalse(RenderPolicy.hasBuildBudget(budget + 1));
	}

	/**
	 * The build budget is the arithmetic it says it is, and one more build would break
	 * the threshold it was derived from.
	 *
	 * <p><b>Both halves, because only the second one is a test.</b> Asserting the cap is
	 * nine restates the constant; what makes it a claim about the measurement is that ten
	 * does not fit. The figures are the ones from the 300-tick Varrock run on 2026-08-29:
	 * a visibility pass with no building in it took 151µs at the median, one model build
	 * inside a burst costs 1.40ms (the measured p95 — see the constant for why not the
	 * mean), the region files one scene load brings in cost 3.0ms, and a crossing tick's
	 * budget is one frame.
	 *
	 * <p><b>The third half, which is new and is the point of the 2026-08-29 pass.</b>
	 * The budget the cap is derived from has to be the <i>crossing tick</i> budget and
	 * not the visibility pass's own acceptable threshold. Those are different events —
	 * one is paid at a border, the other every 600ms forever — and the old derivation
	 * conflated them. Re-running the old formula on the new figures would have tightened
	 * the cap to two; the assertion below records that, so nobody re-derives it that way
	 * again without seeing what it costs.
	 *
	 * <p>Deliberately recomputed from {@code RenderPolicy}'s own constants rather than
	 * from literals, so a re-measurement moves the cap and this test with it — and a
	 * hand-typed cap that no longer follows from the figures beside it goes red.
	 */
	@Test
	public void theBuildBudgetIsTheLargestOneTheMeasuredCrossingTickAllows()
	{
		int budget = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS;
		int overhead = RenderPolicy.MEASURED_PASS_OVERHEAD_MICROS;
		int regionLoad = RenderPolicy.MEASURED_REGION_LOAD_MICROS;
		int perBuild = RenderPolicy.MEASURED_BURST_MODEL_BUILD_MICROS;
		int acceptable = RenderPolicy.CROSSING_TICK_BUDGET_MICROS;

		assertEquals("the measured figures the cap is derived from: 3.0ms of region load, "
				+ "151us of pass overhead and 1.40ms a build, against a one-frame crossing "
				+ "tick",
			9, budget);

		assertTrue("a crossing tick that spends the whole budget has to land inside the "
				+ "threshold: " + (regionLoad + overhead + budget * perBuild)
				+ "us against " + acceptable + "us",
			regionLoad + overhead + budget * perBuild <= acceptable);

		assertTrue("and one more build has to break it, or the cap is lower than the data "
				+ "allows and citizens are being made to wait for nothing: "
				+ (regionLoad + overhead + (budget + 1) * perBuild) + "us against "
				+ acceptable + "us",
			regionLoad + overhead + (budget + 1) * perBuild > acceptable);

		// The conflation that used to set this number. 2ms was registered for the
		// per-tick decision work, and charging a once-per-crossing burst to it is what
		// made the cap three when the pass overhead was 124us — and would make it two
		// now, for a spike the measurement has since attributed to first-execution cost
		// rather than to building at all.
		int visibilityAcceptableMicros = 2_000;
		assertTrue("deriving the burst cap from the visibility pass's own threshold has to "
				+ "give a strictly smaller number, or this guard is comparing the budget "
				+ "with itself",
			(visibilityAcceptableMicros - overhead) / perBuild < budget);
	}

	/**
	 * The cap is <b>computed</b> from the measured figures, not written down as a number
	 * that happens to match them.
	 *
	 * <p>Everything above checks that 9 is the right answer, and every one of those
	 * assertions passes against {@code MAX_MODEL_BUILDS_PER_PASS = 9} typed as a
	 * literal — I checked, by making exactly that change and watching the whole suite stay
	 * green. No assertion on a value can tell a computed 9 from a typed one, because
	 * both are 9.
	 *
	 * <p>That matters because {@code RenderPolicy}'s own javadoc and the README both
	 * promise that "a re-measurement moves the cap by editing the measured figures
	 * rather than by picking a new number". With a literal, re-measuring would move the
	 * figures and leave the cap where it was — the tests above would eventually catch
	 * the resulting inconsistency, but only on the next edit, and the documented
	 * property would already be false.
	 *
	 * <p>So this reads the source, the same way
	 * {@link #everyDensityFigureInTheSourceIsTheOneItsSentenceNames()} does for the
	 * density sentences: the initialiser has to mention all three measured constants and
	 * the threshold it divides into. A literal mentions none of them.
	 */
	@Test
	public void theBuildBudgetIsComputedFromTheMeasuredFiguresRatherThanTypedIn()
		throws IOException
	{
		Path source = Paths.get(
			"src/main/java/com/matthewmariner/livelycities/RenderPolicy.java");
		assertTrue("expected " + source.toAbsolutePath()
				+ " — if the source layout moved, this test has to move with it",
			Files.isRegularFile(source));

		String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);

		int at = text.indexOf("MAX_MODEL_BUILDS_PER_PASS =");
		assertNotEquals("no initialiser for MAX_MODEL_BUILDS_PER_PASS", -1, at);
		String initialiser = text.substring(at, text.indexOf(';', at));

		for (String required : new String[]{
			"CROSSING_TICK_BUDGET_MICROS",
			"MEASURED_REGION_LOAD_MICROS",
			"MEASURED_PASS_OVERHEAD_MICROS",
			"MEASURED_BURST_MODEL_BUILD_MICROS"})
		{
			assertTrue("the cap has to be derived from " + required + ", not typed in — "
					+ "its initialiser reads: " + initialiser.replaceAll("\\s+", " "),
				initialiser.contains(required));
		}
	}

	/**
	 * The two ceilings are not the same ceiling.
	 *
	 * <p>They are one word apart in English — "how many at once" — and they bound
	 * completely different things: {@link RenderPolicy#MAX_ACTIVE_OBJECTS} bounds objects
	 * the client has registered, which a pass spends and refunds as the player walks;
	 * {@link RenderPolicy#MAX_MODEL_BUILDS_PER_PASS} bounds work one pass may do. A
	 * change that fed one to the other's guard would compile and would be silently wrong
	 * in both directions at once — three citizens visible in Varrock, or eighty models
	 * built in a tick, depending which way round it went.
	 */
	@Test
	public void theCrowdCapAndTheBuildBudgetAreDifferentNumbersWithDifferentGuards()
	{
		assertTrue("if these ever coincide, every assertion that tells them apart starts "
				+ "passing for the wrong reason",
			RenderPolicy.MAX_ACTIVE_OBJECTS != RenderPolicy.MAX_MODEL_BUILDS_PER_PASS);

		// At a count between the two, one guard says yes and the other says no.
		int between = RenderPolicy.MAX_MODEL_BUILDS_PER_PASS + 1;
		assertTrue("there is still room for more objects at " + between,
			RenderPolicy.hasCapacity(between));
		assertFalse("but no budget for another build at " + between,
			RenderPolicy.hasBuildBudget(between));
	}

	/**
	 * If the cap drops below the densest neighbourhood the dataset actually
	 * contains, real content starts getting culled in Varrock — the busiest
	 * corner of the dataset, not Keldagrim, which is region 11422 and has no
	 * region file at all — and nobody would know why.
	 *
	 * <p>Measured at {@link RenderPolicy#MAX_CULL_RADIUS}, not at the default: the
	 * cap has to survive the widest setting the dial offers, not the one it ships
	 * with. (Wandering can still push a momentary count a little past the static
	 * figure, and the cap handles that by shedding the far edge of the crowd —
	 * that is what it is for.)
	 *
	 * <p>The density is computed from the shipped files rather than written down
	 * here, so it keeps guarding the invariant as the data grows.
	 */
	@Test
	public void capLeavesRoomForTheBusiestPlaceInTheDataset()
	{
		int radius = RenderPolicy.MAX_CULL_RADIUS;
		Neighbourhood densest = densestNeighbourhood(radius);

		assertTrue("the dataset has to be loaded for this to mean anything", densest.count > 0);
		assertTrue("cap " + RenderPolicy.MAX_ACTIVE_OBJECTS + " is below the busiest neighbourhood ("
				+ densest.count + " entities within " + radius + " tiles of "
				+ densest.x + "," + densest.y + " on plane " + densest.plane + ")",
			RenderPolicy.MAX_ACTIVE_OBJECTS >= densest.count);
	}

	/**
	 * Every density figure written down in the shipped source is the one its own
	 * sentence names.
	 *
	 * <p><b>Why the sentences and not just the arithmetic.</b> The test above asserts
	 * {@code cap >= densest}, which is true of <i>both</i> ways of measuring density
	 * and therefore blind to the difference between them. There are two:
	 *
	 * <ul>
	 *   <li><b>From an arbitrary tile</b> — the largest number of entities inside one
	 *       cull radius of <i>any</i> tile a player could stand on. This is the figure
	 *       that bounds the cap, because {@link RenderPolicy#isCandidate} measures from
	 *       the player's position and a player may stand anywhere.</li>
	 *   <li><b>Centred on an entity's own tile</b> — the largest number inside one cull
	 *       radius of a tile some citizen happens to occupy. Strictly smaller, useful to
	 *       a test that has to stand somewhere in particular, and it bounds
	 *       <b>nothing</b>.</li>
	 * </ul>
	 *
	 * <p>Both have been written in {@code MAX_ACTIVE_OBJECTS}'s javadoc at different
	 * times, and the second one halves the stated margin without changing a line of
	 * code. {@code CrowdedSceneTest} carries a comment warning about exactly that
	 * confusion; a comment cannot go red, so this does. Every claim is matched against
	 * the metric recomputed from the shipped files, so the way to move one of these
	 * numbers is to change the dataset.
	 */
	@Test
	public void everyDensityFigureInTheSourceIsTheOneItsSentenceNames() throws IOException
	{
		int wide = RenderPolicy.MAX_CULL_RADIUS;
		int fromAnyTile = densestNeighbourhood(wide).count;
		int centredOnAnEntity = densestEntityCentredNeighbourhood(wide);

		assertTrue("the dataset has to be loaded for any of this to mean anything",
			fromAnyTile > 0 && centredOnAnEntity > 0);
		assertTrue("an arbitrary tile can always do at least as well as an entity's own",
			fromAnyTile >= centredOnAnEntity);
		assertTrue("if the two metrics ever agree, every assertion below starts passing "
				+ "for the wrong reason and this guard is worth nothing — "
				+ fromAnyTile + " vs " + centredOnAnEntity,
			fromAnyTile != centredOnAnEntity);

		String shipped = flattenedShippedSource();
		int claims = 0;

		// "<n> entities at/inside <the widest radius>" — the sentence that bounds the
		// cap, wherever in src/main it is written.
		claims += pinned(shipped,
			"(\\d+) (?:authored )?entities (?:at|inside) "
				+ "(?:\\{@link (?:RenderPolicy)?#MAX_CULL_RADIUS\\}|the widest render distance)",
			fromAnyTile, 3, "the density at the widest cull radius");

		// The same claim in its other spelling, half a sentence later in
		// MAX_ACTIVE_OBJECTS's javadoc.
		claims += pinned(shipped,
			"(\\d+) inside a \\{@link #MAX_CULL_RADIUS\\}-tile one",
			fromAnyTile, 1, "the density at the widest cull radius");

		// And the same metric at the default radius, in the same sentence.
		Matcher atRadius = Pattern.compile("(\\d+) entities inside a (\\d+)-tile square")
			.matcher(shipped);
		int squares = 0;
		while (atRadius.find())
		{
			squares++;
			int radius = Integer.parseInt(atRadius.group(2));
			assertEquals("'" + atRadius.group() + "' has to be the density measured from an "
					+ "arbitrary tile at radius " + radius + ", not the one centred on an entity "
					+ "(" + densestEntityCentredNeighbourhood(radius) + ")",
				densestNeighbourhood(radius).count, Integer.parseInt(atRadius.group(1)));
		}
		assertEquals("the sentence naming a plain tile radius has to still be there", 1, squares);
		claims += squares;

		// The headroom, spelled out in words, in both places that spell it out.
		int spare = RenderPolicy.MAX_ACTIVE_OBJECTS - fromAnyTile;
		claims += pinnedWord(shipped,
			"holds (?:\\d+) entities at \\{@link #MAX_CULL_RADIUS\\}, (\\w+) short of this",
			spare, 1);
		claims += pinnedWord(shipped,
			"holds (?:\\d+) entities at the widest render distance, (\\w+) slots spare",
			spare, 1);

		// The build-budget cost sentence does arithmetic on the same figure.
		Matcher passes = Pattern.compile("\\{@code ceil\\((\\d+) / (\\d+)\\)\\} = (\\d+) passes")
			.matcher(shipped);
		int fills = 0;
		while (passes.find())
		{
			fills++;
			assertEquals("'" + passes.group() + "' fills the densest neighbourhood, so it is the "
					+ "arbitrary-tile figure", fromAnyTile, Integer.parseInt(passes.group(1)));
			assertEquals("and it fills it at the build budget",
				RenderPolicy.MAX_MODEL_BUILDS_PER_PASS, Integer.parseInt(passes.group(2)));
			int builds = Integer.parseInt(passes.group(2));
			assertEquals("and the division has to be the division it prints",
				(Integer.parseInt(passes.group(1)) + builds - 1) / builds,
				Integer.parseInt(passes.group(3)));
		}
		assertEquals("the cold-walk sentence has to still be there", 1, fills);
		claims += fills;

		assertTrue("a sweep that matched nothing would pass while checking nothing: "
				+ claims + " claims found", claims >= 8);

		// And the other metric, pinned where it is correctly named — the comment that
		// exists to stop this confusion recurring, which is itself a place the wrong
		// number could be typed.
		String warning = flatten(read(
			"src/test/java/com/matthewmariner/livelycities/CrowdedSceneTest.java"));
		pinned(warning, "(\\d+) is the densest window centred on an entity's own tile",
			centredOnAnEntity, 1, "the entity-centred density");
		pinned(warning, "the densest window from an arbitrary tile holds (\\d+)",
			fromAnyTile, 1, "the arbitrary-tile density");
	}

	/**
	 * Asserts every match of {@code regex} carries {@code expected} in group 1, and
	 * that there were {@code atLeast} of them.
	 *
	 * @return how many claims were checked
	 */
	private static int pinned(String text, String regex, int expected, int atLeast, String what)
	{
		Matcher matcher = Pattern.compile(regex).matcher(text);
		int found = 0;
		while (matcher.find())
		{
			found++;
			assertEquals("'" + matcher.group() + "' states " + what
					+ ", which is " + expected + " in the shipped dataset",
				expected, Integer.parseInt(matcher.group(1)));
		}

		assertTrue("expected at least " + atLeast + " sentence(s) matching /" + regex
				+ "/ and found " + found + " — if the wording moved, this guard has to move "
				+ "with it rather than quietly stop checking", found >= atLeast);
		return found;
	}

	/** {@link #pinned} for a figure written as an English word rather than digits. */
	private static int pinnedWord(String text, String regex, int expected, int atLeast)
	{
		Matcher matcher = Pattern.compile(regex).matcher(text);
		int found = 0;
		while (matcher.find())
		{
			found++;
			assertEquals("'" + matcher.group() + "' states the headroom between the cap and the "
					+ "densest neighbourhood a player can stand in",
				numberWord(expected), matcher.group(1));
		}

		assertTrue("expected at least " + atLeast + " sentence(s) matching /" + regex
				+ "/ and found " + found, found >= atLeast);
		return found;
	}

	private static String numberWord(int value)
	{
		String[] words = {
			"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
			"nine", "ten", "eleven", "twelve"};
		return value >= 0 && value < words.length ? words[value] : String.valueOf(value);
	}

	/**
	 * Every {@code .java} file under {@code src/main/java}, run together into one
	 * string with comment furniture and line wrapping flattened away.
	 *
	 * <p>Reading the source text rather than the compiled classes because what is
	 * being checked <i>is</i> prose — javadoc and {@code //} comments, which javac
	 * throws away. Same working-directory assumption as {@code ShippedSourceTest},
	 * and the same loud failure if it ever stops holding.
	 */
	private static String flattenedShippedSource() throws IOException
	{
		File root = new File("src/main/java");
		assertTrue("expected to find " + root.getAbsolutePath()
			+ " — if the test working directory moved, this test has to move with it",
			root.isDirectory());

		List<Path> sources;
		try (Stream<Path> paths = Files.walk(root.toPath()))
		{
			sources = paths
				.filter(path -> path.getFileName().toString().endsWith(".java"))
				.sorted()
				.collect(Collectors.toList());
		}

		assertFalse("no .java files under " + root.getAbsolutePath()
			+ " — a sweep of nothing would pass", sources.isEmpty());

		StringBuilder all = new StringBuilder();
		for (Path source : sources)
		{
			all.append(flatten(read(source.toString()))).append('\n');
		}
		return all.toString();
	}

	private static String read(String path) throws IOException
	{
		File file = new File(path);
		assertTrue("expected to find " + file.getAbsolutePath(), file.isFile());
		return new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
	}

	/**
	 * Strips the comment furniture — leading {@code *}, {@code //}, the javadoc
	 * delimiters and inline {@code <b>}/{@code <i>} — and collapses every run of
	 * whitespace to one space, so a sentence can be matched however it happens to be
	 * wrapped.
	 */
	private static String flatten(String source)
	{
		return source
			.replaceAll("(?m)^\\s*(?:\\*/|/\\*+|\\*|//)\\s?", " ")
			.replaceAll("</?[bi]>", "")
			.replaceAll("\\s+", " ");
	}

	/**
	 * The scene's geometry at the moment it is built, and the fact that it is only
	 * true at that moment.
	 *
	 * <p>The 104-tile scene sits on a chunk-aligned base with the player's chunk
	 * seventh of thirteen, so the player starts 48..55 tiles from every edge. The
	 * scene does not follow them: {@code FakeWorldView.around} reproduces the
	 * client's own base arithmetic, and this walks a player across a chunk to show
	 * the margin decaying step for step rather than staying at 48.
	 *
	 * <p>This test replaces one that asserted
	 * {@code DEFAULT_CULL_RADIUS <= GUARANTEED_SCENE_RADIUS} under the heading
	 * "an entity inside the cull radius must be inside the loaded scene". That was
	 * a false invariant dressed up as arithmetic, and it is the reason the pop-in
	 * was diagnosed as something other than what it is.
	 */
	@Test
	public void theSceneRadiusHoldsAtLoadAndDecaysAfterwards()
	{
		assertEquals(48, RenderPolicy.SCENE_RADIUS_AT_LOAD);
		assertEquals(Constants.SCENE_SIZE / 2 - Constants.CHUNK_SIZE / 2,
			RenderPolicy.SCENE_RADIUS_AT_LOAD);

		// At load: the closest edge is 48 tiles away at worst, 55 at best.
		for (int offsetInChunk = 0; offsetInChunk < Constants.CHUNK_SIZE; offsetInChunk++)
		{
			WorldPoint player = new WorldPoint(3200 + offsetInChunk, 3200 + offsetInChunk, 0);
			FakeWorldView freshScene = FakeWorldView.around(player, 12852);
			int margin = marginToNearestEdge(player, freshScene);
			assertTrue("at load the margin is 48..55, got " + margin,
				margin >= RenderPolicy.SCENE_RADIUS_AT_LOAD
					&& margin <= RenderPolicy.SCENE_RADIUS_AT_LOAD + Constants.CHUNK_SIZE - 1);
		}

		// Now hold the scene still and walk. Nothing recentres, so the margin
		// falls one tile per tile — which is the whole point.
		WorldPoint start = new WorldPoint(3200, 3200, 0);
		FakeWorldView stale = FakeWorldView.around(start, 12852);
		int atLoad = marginToNearestEdge(start, stale);
		int after32 = marginToNearestEdge(new WorldPoint(3200 - 32, 3200, 0), stale);

		assertEquals("walking 32 tiles costs 32 tiles of margin", atLoad - 32, after32);
		assertEquals("and lands exactly on the sustained floor",
			RenderPolicy.SUSTAINED_SCENE_RADIUS, after32);
	}

	/**
	 * The figure that actually holds, and the fact that the default cull radius is
	 * knowingly wider than it.
	 *
	 * <p>Sixteen is the game's map-rebuild margin: a new scene arrives once the
	 * player's position inside the current one leaves {@code [16, 104-16)}, so the
	 * player is never closer than 16 tiles to an edge and never guaranteed more.
	 * It is not in {@link Constants} and this test does not pretend it is; what it
	 * pins is the <i>consequence</i> — the default is above it, so pop-in is
	 * reachable at stock settings, and the config description has to keep saying
	 * so.
	 */
	@Test
	public void theSustainedSceneFloorIsBelowTheDefaultCullRadius()
	{
		assertEquals(16, RenderPolicy.SUSTAINED_SCENE_RADIUS);
		assertEquals("the floor is the at-load radius less four chunks of drift",
			RenderPolicy.SCENE_RADIUS_AT_LOAD - 4 * Constants.CHUNK_SIZE,
			RenderPolicy.SUSTAINED_SCENE_RADIUS);
		assertTrue("the sustained floor is well below what the scene offers at load",
			RenderPolicy.SUSTAINED_SCENE_RADIUS < RenderPolicy.SCENE_RADIUS_AT_LOAD);

		assertTrue("the default render distance is deliberately wider than the floor, "
				+ "so entities near its edge can be outside the loaded scene between "
				+ "scene loads — if this ever stops being true, the config description "
				+ "that warns about it has to change too",
			RenderPolicy.DEFAULT_CULL_RADIUS > RenderPolicy.SUSTAINED_SCENE_RADIUS);

		// And a wanderer can be outside the scene at any radius at all, because its
		// box reaches past the tile the cull check measured.
		assertTrue("no cull radius makes a wandering citizen always placeable",
			RenderPolicy.MIN_CULL_RADIUS + RenderPolicy.DATASET_OVERHANG_ALLOWANCE
				> RenderPolicy.SUSTAINED_SCENE_RADIUS);
	}

	/**
	 * The cull-radius dial's ceiling.
	 *
	 * <p>A choice with a bound behind it, not a derivation: an entity selected at
	 * radius R can be R + the dataset's worst overhang away by the time it is
	 * drawn, and past {@code SCENE_RADIUS_AT_LOAD} it is outside the scene even in
	 * the best case — immediately after a load — so it could never be drawn at any
	 * point in the walk cycle. Offering a setting like that would be offering
	 * nothing. Inside the ceiling, coverage is partial rather than guaranteed, and
	 * {@link #theSustainedSceneFloorIsBelowTheDefaultCullRadius} is where that is
	 * pinned.
	 *
	 * <p>The clamp has to hold whatever arrives from a hand-edited settings file,
	 * not just what the slider allows.
	 */
	@Test
	public void theCullRadiusDialStopsWhereEntitiesStopBeingDrawableAtAll()
	{
		assertEquals("the ceiling is the at-load radius less the dataset's overhang",
			RenderPolicy.SCENE_RADIUS_AT_LOAD - RenderPolicy.DATASET_OVERHANG_ALLOWANCE,
			RenderPolicy.MAX_CULL_RADIUS);
		assertTrue("the widest setting plus the overhang must at least fit the scene as loaded",
			RenderPolicy.MAX_CULL_RADIUS + RenderPolicy.DATASET_OVERHANG_ALLOWANCE
				<= RenderPolicy.SCENE_RADIUS_AT_LOAD);
		assertTrue("the default has to be a setting the dial can actually express",
			RenderPolicy.DEFAULT_CULL_RADIUS >= RenderPolicy.MIN_CULL_RADIUS
				&& RenderPolicy.DEFAULT_CULL_RADIUS <= RenderPolicy.MAX_CULL_RADIUS);

		// The clamp, which is the only thing every read goes through.
		assertEquals(RenderPolicy.MAX_CULL_RADIUS,
			RenderPolicy.clampCullRadius(RenderPolicy.MAX_CULL_RADIUS + 1));
		assertEquals(RenderPolicy.MAX_CULL_RADIUS, RenderPolicy.clampCullRadius(9999));
		assertEquals(RenderPolicy.MIN_CULL_RADIUS,
			RenderPolicy.clampCullRadius(RenderPolicy.MIN_CULL_RADIUS - 1));
		assertEquals(RenderPolicy.MIN_CULL_RADIUS, RenderPolicy.clampCullRadius(0));
		assertEquals(RenderPolicy.MIN_CULL_RADIUS, RenderPolicy.clampCullRadius(-40));
		// And a legal value is left exactly alone.
		assertEquals(RenderPolicy.DEFAULT_CULL_RADIUS,
			RenderPolicy.clampCullRadius(RenderPolicy.DEFAULT_CULL_RADIUS));
		assertEquals(RenderPolicy.MAX_CULL_RADIUS,
			RenderPolicy.clampCullRadius(RenderPolicy.MAX_CULL_RADIUS));
	}

	/**
	 * Both things that put a rendered entity further from the player than the cull
	 * check measured, computed from the shipped files.
	 *
	 * <ul>
	 *   <li><b>Misfiling.</b> Entities are found by region file name, and the
	 *       dataset misfiles one: "Dark wizard" is in {@code 12853.json} and
	 *       stands 6 tiles inside region 12852. It is still found, because the
	 *       file's region is in the scene whenever the entity is close enough to
	 *       render — but only while the cull radius plus the misfiling stays
	 *       inside the guaranteed scene.</li>
	 *   <li><b>Wandering.</b> A citizen paces its authored box while the cull
	 *       check keeps measuring from the tile it started on. The widest box in
	 *       the dataset reaches 18 tiles from that tile.</li>
	 * </ul>
	 *
	 * <p>Both have to fit inside {@link RenderPolicy#DATASET_OVERHANG_ALLOWANCE},
	 * which is the term {@link RenderPolicy#MAX_CULL_RADIUS} subtracts. Growing the
	 * dataset past it fails here rather than quietly widening the gap between the
	 * tile a cull decision was made about and the tile the citizen is drawn on.
	 *
	 * <p>The wander boxes are read from the JSON by {@link ShippedWanderBoxes},
	 * not from {@link EntityDefinition}, because that class clamps a box to the
	 * allowance: asking it would get the allowance back whatever the allowance
	 * was, and a mutation test caught exactly that tautology.
	 */
	@Test
	public void theWorstMisfilingAndTheWidestWanderBoxBothFitTheOverhangAllowance()
	{
		int allowance = RenderPolicy.DATASET_OVERHANG_ALLOWANCE;

		int worstMisfiling = 0;
		int misfiled = 0;
		String misfiledWhere = "nothing misfiled";

		for (EntityDefinition entity : shippedEntities())
		{
			if (entity.getTileRegionId() == entity.getRegionId())
			{
				continue;
			}

			misfiled++;
			int overhang = distanceToRegion(entity.getWorldLocation(), entity.getRegionId());
			if (overhang > worstMisfiling)
			{
				worstMisfiling = overhang;
				misfiledWhere = entity.label() + " filed under " + entity.getRegionId()
					+ ".json but standing in " + entity.getTileRegionId();
			}
		}

		int worstWander = 0;
		String wanderWhere = "nothing wanders";
		List<ShippedWanderBoxes.Authored> boxes = ShippedWanderBoxes.all();
		for (ShippedWanderBoxes.Authored box : boxes)
		{
			assertTrue("a WanderingCitizen with no wanderBox at all: " + box, box.hasBox());
			if (box.reach() > worstWander)
			{
				worstWander = box.reach();
				wanderWhere = box.toString();
			}
		}

		assertEquals("the shipped dataset has exactly one misfiled entity", 1, misfiled);
		assertEquals("the shipped dataset has 63 wandering citizens", 63, boxes.size());

		assertTrue("worst misfiling " + worstMisfiling + " (" + misfiledWhere
				+ ") exceeds the " + allowance + "-tile overhang allowance",
			worstMisfiling <= allowance);
		assertTrue("widest authored wander reach " + worstWander + " (" + wanderWhere
				+ ") exceeds the " + allowance + "-tile overhang allowance, so that box is being "
				+ "silently shortened",
			worstWander <= allowance);

		assertTrue("the widest cull radius plus the worst overhang ("
				+ Math.max(worstMisfiling, worstWander) + ") exceeds the "
				+ RenderPolicy.SCENE_RADIUS_AT_LOAD + " tiles the scene covers when it is "
				+ "built, so the far edge of the dial could never be drawn at all",
			RenderPolicy.MAX_CULL_RADIUS + Math.max(worstMisfiling, worstWander)
				<= RenderPolicy.SCENE_RADIUS_AT_LOAD);
	}

	/**
	 * Chebyshev distance from a tile to the nearest edge of a world view's loaded
	 * scene. Reads {@code getBaseX/getBaseY/getSizeX/getSizeY} — the same four
	 * numbers {@code LocalPoint.fromWorld} uses to decide whether a tile can be
	 * placed at all.
	 */
	private static int marginToNearestEdge(WorldPoint player, FakeWorldView view)
	{
		int minX = player.getX() - view.getBaseX();
		int minY = player.getY() - view.getBaseY();
		int maxX = view.getBaseX() + view.getSizeX() - 1 - player.getX();
		int maxY = view.getBaseY() + view.getSizeY() - 1 - player.getY();
		return Math.min(Math.min(minX, maxX), Math.min(minY, maxY));
	}

	/**
	 * Chebyshev distance from a tile to the nearest tile of a region, i.e. how
	 * far outside its own file's square an entity has been placed.
	 */
	private static int distanceToRegion(WorldPoint point, int regionId)
	{
		int x0 = (regionId >> 8) * Constants.REGION_SIZE;
		int y0 = (regionId & 0xFF) * Constants.REGION_SIZE;
		int dx = Math.max(0, Math.max(x0 - point.getX(), point.getX() - (x0 + Constants.REGION_SIZE - 1)));
		int dy = Math.max(0, Math.max(y0 - point.getY(), point.getY() - (y0 + Constants.REGION_SIZE - 1)));
		return Math.max(dx, dy);
	}

	/**
	 * The most entities that can be inside one cull radius at once, over every
	 * player position the shipped data allows.
	 *
	 * <p>A maximal window can always be slid until its low corner sits on an
	 * entity, so those corners are the only centres worth trying — checking the
	 * entities' own tiles as centres would undercount.
	 */
	private static Neighbourhood densestNeighbourhood(int radius)
	{
		List<WorldPoint> points = new ArrayList<>();
		for (EntityDefinition entity : shippedEntities())
		{
			points.add(entity.getWorldLocation());
		}

		Neighbourhood best = new Neighbourhood(0, 0, 0, 0);

		for (WorldPoint xSource : points)
		{
			for (WorldPoint ySource : points)
			{
				int cx = xSource.getX() + radius;
				int cy = ySource.getY() + radius;

				int[] perPlane = new int[Constants.MAX_Z];
				for (WorldPoint p : points)
				{
					if (Math.abs(p.getX() - cx) <= radius && Math.abs(p.getY() - cy) <= radius)
					{
						perPlane[p.getPlane()]++;
					}
				}

				for (int plane = 0; plane < perPlane.length; plane++)
				{
					if (perPlane[plane] > best.count)
					{
						best = new Neighbourhood(perPlane[plane], cx, cy, plane);
					}
				}
			}
		}

		return best;
	}

	/**
	 * The most entities that can be inside one cull radius of a tile <b>some entity
	 * already stands on</b>.
	 *
	 * <p>The other metric, and the one that bounds nothing: it is what a test can
	 * position itself on, not what the cull check measures. Kept here beside
	 * {@link #densestNeighbourhood} so the two are computed the same way and only
	 * differ in the one thing that differs.
	 */
	private static int densestEntityCentredNeighbourhood(int radius)
	{
		List<WorldPoint> points = new ArrayList<>();
		for (EntityDefinition entity : shippedEntities())
		{
			points.add(entity.getWorldLocation());
		}

		int best = 0;
		for (WorldPoint centre : points)
		{
			int count = 0;
			for (WorldPoint p : points)
			{
				if (p.getPlane() == centre.getPlane()
					&& Math.abs(p.getX() - centre.getX()) <= radius
					&& Math.abs(p.getY() - centre.getY()) <= radius)
				{
					count++;
				}
			}
			best = Math.max(best, count);
		}

		return best;
	}

	private static List<EntityDefinition> shippedEntities()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> entities = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			entities.addAll(region.getEntities());
		}

		return entities;
	}

	private static EntityDefinition definitionAt(int x, int y, int plane)
	{
		EntityDefinition definition = EntityDefinitionTest.definition(
			"StationaryCitizen", x, y, plane, new int[]{1});
		assertNotNull(definition);
		return definition;
	}

	/** The densest window found, and where it was. */
	private static final class Neighbourhood
	{
		private final int count;
		private final int x;
		private final int y;
		private final int plane;

		Neighbourhood(int count, int x, int y, int plane)
		{
			this.count = count;
			this.x = x;
			this.y = y;
			this.plane = plane;
		}
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

/**
 * Writes one of this plugin's developer reports to disk.
 *
 * <p><b>This class lives in the test source set, and that is the point.</b> It is the
 * only class in the project that touches a filesystem, and {@code src/test/java} is
 * not packaged into the jar the Plugin Hub builds — so the shipped plugin contains no
 * {@code java.io.File}, no {@code java.nio.file}, and nothing that can write anywhere.
 * A hub maintainer put the reason plainly on
 * <a href="https://github.com/runelite/plugin-hub/pull/12366">plugin-hub#12366</a>:
 * "file i/o will make your plugin require manually review. if you can not use it your
 * plugin can be automatically reviewed." The capability itself is not lost — both
 * {@code ./gradlew runWithTimings} and {@code ./gradlew auditCacheIds} run on
 * {@code sourceSets.test.runtimeClasspath}, so {@link LivelyCitiesDevReportsPlugin}
 * and this writer are on the classpath of exactly the two launches that want them, and
 * of nothing a hub user can ever start. That arrangement is the one riktenx suggested
 * on <a href="https://github.com/runelite/plugin-hub/pull/13208">plugin-hub#13208</a>:
 * "you can either add a separate debug plugin in the test source set (which won't ship
 * with your plugin and won't get looked at but you can use it during development) or
 * just remove it".
 *
 * <p>Two rules still apply here and are unchanged by the move: write only under the
 * caller-supplied directory — every caller passes a subdirectory of
 * {@code RuneLite.RUNELITE_DIR} — and never on the client thread, which
 * {@link LivelyCitiesDevReportsPlugin} guarantees by dispatching to a background thread
 * after the client-thread pass that produced the text has already finished.
 *
 * <p>It takes finished text rather than a report object so that the second caller
 * did not have to be a second writer. {@code CacheIdAudit} and {@link FrameTimings}
 * both produce a stable, sorted, diffable {@code String} on the client thread — both
 * still in {@code src/main}, because measuring and auditing are not file I/O — and hand
 * it here; adding a third is a file name and nothing else. It was called
 * {@code CacheAuditReportWriter} while it had one caller.
 */
final class ReportWriter
{
	/**
	 * The suffix a half-written report carries while it is being written. Named so a
	 * human who finds one after a crash can tell what it is, and so
	 * {@code ReportWriterTest} can assert none are left behind.
	 */
	static final String TEMP_SUFFIX = ".part";

	private ReportWriter()
	{
	}

	/**
	 * Writes {@code text} to {@code fileName}, replacing whatever was there.
	 *
	 * <p><b>Through a temporary file and a rename, rather than straight at the
	 * target.</b> {@code new FileOutputStream(file)} truncates in place, so the report
	 * spends the whole write as a partial file — and since {@link FrameTimings} arrived
	 * this method has two callers that can be in flight at once. The frame report is
	 * dispatched both from the 300-tick cadence in
	 * {@link LivelyCitiesDevReportsPlugin#onGameTick} and from that plugin's
	 * {@code shutDown}, each through {@code CompletableFuture.runAsync} on the common
	 * pool, so a client closed just as a periodic report begins puts two writers on one
	 * path with nothing between them. Truncating writers interleave into a file that is
	 * neither report. The cache audit ran once per session and never had this window;
	 * it inherits the fix anyway.
	 *
	 * <p>Writing somewhere else and renaming means the target is only ever replaced
	 * whole: a rename within one directory is atomic, so a concurrent writer or a
	 * concurrent reader sees the old report or the new one and never half of either.
	 * Serialising the two callers behind a lock would close the same window, but this
	 * also survives the process dying mid-write, which a lock does not.
	 *
	 * <p>The temporary file is created in {@code outputDir} rather than in the system
	 * temp directory, for two reasons: the rename has to stay inside one filesystem to
	 * be atomic at all, and {@code AGENTS.md}'s file-I/O rule says this plugin writes
	 * only under the caller-supplied directory.
	 *
	 * @param outputDir the plugin's own subdirectory, created if it does not
	 *                  exist yet
	 * @param fileName  the report's file name — see
	 *                  {@link LivelyCitiesDevReportsPlugin#CACHE_AUDIT_REPORT_FILE_NAME}
	 *                  and {@link LivelyCitiesDevReportsPlugin#FRAME_REPORT_FILE_NAME}.
	 *                  Both constants live with the writer rather than with the two
	 *                  classes that produce the text, because after the move
	 *                  {@code src/main} names no files at all.
	 * @param text      the finished report, already a snapshot
	 * @return the file written
	 */
	static File write(File outputDir, String fileName, String text) throws IOException
	{
		if (!outputDir.isDirectory() && !outputDir.mkdirs() && !outputDir.isDirectory())
		{
			throw new IOException("could not create " + outputDir);
		}

		File file = new File(outputDir, fileName);
		Path target = file.toPath();

		// A distinct name per call, so two writers in flight cannot scribble on each
		// other's draft either — the whole point would be lost if they shared one.
		Path draft = Files.createTempFile(outputDir.toPath(), fileName, TEMP_SUFFIX);
		try
		{
			try (Writer writer = new OutputStreamWriter(
				Files.newOutputStream(draft), StandardCharsets.UTF_8))
			{
				writer.write(text);
			}

			try
			{
				Files.move(draft, target,
					StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				// Not every filesystem promises it, and a report nobody can write is a
				// worse outcome than a narrower window. A plain replace still beats
				// truncating in place: the exposure shrinks from the length of the write
				// to the length of the rename.
				Files.move(draft, target, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A draft left behind would accumulate one file per failure in a directory
			// the user is expected to read.
			try
			{
				Files.deleteIfExists(draft);
			}
			catch (IOException cleanupFailed)
			{
				e.addSuppressed(cleanupFailed);
			}
			throw e;
		}

		return file;
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The one piece of this project that touches a filesystem — and, since the move, one
 * that lives in the test source set beside the class it tests rather than in the jar
 * the Plugin Hub builds. Points at a throwaway temp directory rather than the real
 * {@code ~/.runelite}, the same discipline this project already applies to region data
 * fixtures.
 *
 * <p>The fixtures are still cache-audit reports, because that is the report with a
 * fixture already built; what is under test is the writing, and the writer has not
 * known what a report <i>is</i> since {@link FrameTimings} became its second caller.
 */
public class ReportWriterTest
{
	/**
	 * Taken from the production constant rather than spelled out again, so a rename
	 * cannot leave this file asserting about a file name nobody writes.
	 */
	private static final String REPORT_FILE_NAME =
		LivelyCitiesDevReportsPlugin.CACHE_AUDIT_REPORT_FILE_NAME;

	private File tempRoot;

	@Before
	public void setUp() throws IOException
	{
		tempRoot = Files.createTempDirectory("lively-cities-audit-test").toFile();
	}

	@After
	public void tearDown()
	{
		deleteRecursively(tempRoot);
	}

	@Test
	public void writesTheReportTextVerbatimUnderTheGivenDirectory() throws IOException
	{
		File outputDir = new File(tempRoot, "lively-cities");
		CacheIdAudit.Report report = emptyReport();

		File written = ReportWriter.write(outputDir, REPORT_FILE_NAME, report.toReportText());

		assertEquals(new File(outputDir, REPORT_FILE_NAME), written);
		assertTrue(written.isFile());
		String contents = new String(Files.readAllBytes(written.toPath()), java.nio.charset.StandardCharsets.UTF_8);
		assertEquals(report.toReportText(), contents);
	}

	/**
	 * The plugin's real call site passes a subdirectory that does not exist yet
	 * — {@code RuneLite.RUNELITE_DIR}, not this plugin's own folder inside it.
	 */
	@Test
	public void createsTheOutputDirectoryWhenItDoesNotExistYet()
	{
		File outputDir = new File(tempRoot, "does-not-exist-yet/lively-cities");
		assertTrue(!outputDir.exists());

		File written = tryWrite(outputDir);

		assertTrue(outputDir.isDirectory());
		assertTrue(written.isFile());
	}

	@Test
	public void writingTwiceOverwritesRatherThanAppending() throws IOException
	{
		File outputDir = new File(tempRoot, "lively-cities");

		ReportWriter.write(outputDir, REPORT_FILE_NAME, emptyReport().toReportText());
		File secondReportFile = ReportWriter.write(
			outputDir, REPORT_FILE_NAME, reportWithOneFailure().toReportText());

		String contents = new String(Files.readAllBytes(secondReportFile.toPath()), java.nio.charset.StandardCharsets.UTF_8);
		assertEquals("a stale failing id from a fixed run must not linger in the file",
			reportWithOneFailure().toReportText(), contents);
	}

	/**
	 * The report is the only thing left in the directory afterwards.
	 *
	 * <p>The write goes through a draft file now (see {@link ReportWriter}'s javadoc),
	 * and a draft that survives the write is litter in a directory whose whole purpose
	 * is for a human to open it and read one file.
	 */
	@Test
	public void aWriteLeavesTheReportAndNothingElseBehind()
	{
		File outputDir = new File(tempRoot, "lively-cities");

		tryWrite(outputDir);
		tryWrite(outputDir);

		String[] left = outputDir.list();
		assertNotNull(left);
		assertEquals("only the report may survive the write: " + Arrays.toString(left),
			Collections.singletonList(REPORT_FILE_NAME),
			Arrays.asList(left));
	}

	/**
	 * Two writers on one path never produce a file that is neither report.
	 *
	 * <p><b>The window this closes is new.</b>
	 * {@code LivelyCitiesDevReportsPlugin.reportFrameTimings()} is reachable
	 * from two places — the 300-tick cadence and {@code shutDown} — and both dispatch
	 * through {@code CompletableFuture.runAsync}, so closing the client as a periodic
	 * report begins puts two writers on {@code frame-timings.txt} at once. The old
	 * implementation opened the target with {@code new FileOutputStream(file)}, which
	 * truncates in place: for the length of the write the report on disk is a prefix of
	 * itself, and two of them interleave into a file that is neither.
	 *
	 * <p>So a reader runs flat out against two writers alternating between two texts,
	 * and every single thing it manages to read has to be one of those two texts,
	 * whole. The texts are large enough that a truncating writer is caught within the
	 * first few rounds; with the rename it cannot be caught at all, because a reader
	 * either opens the old file or the new one and both are complete. That asymmetry is
	 * the point — this test cannot pass by being lucky, only by the window being shut.
	 */
	@Test
	public void aReaderRacingTwoWritersNeverSeesAHalfWrittenReport() throws Exception
	{
		File outputDir = new File(tempRoot, "lively-cities");
		String first = filler('a');
		String second = filler('b');

		// One complete report to start from, so "the file does not exist yet" is not
		// one of the states the reader has to tolerate.
		ReportWriter.write(outputDir, REPORT_FILE_NAME, first);
		File report = new File(outputDir, REPORT_FILE_NAME);

		AtomicBoolean writing = new AtomicBoolean(true);
		List<String> torn = Collections.synchronizedList(new ArrayList<>());
		AtomicInteger reads = new AtomicInteger();

		Thread reader = new Thread(() ->
		{
			while (writing.get())
			{
				String seen;
				try
				{
					seen = new String(Files.readAllBytes(report.toPath()), StandardCharsets.UTF_8);
				}
				catch (IOException e)
				{
					// The target disappearing is itself a failure of the contract: a
					// rename replaces it without ever unlinking it first.
					torn.add("unreadable: " + e);
					continue;
				}

				reads.incrementAndGet();
				if (!seen.equals(first) && !seen.equals(second))
				{
					torn.add("length " + seen.length());
				}
			}
		});

		reader.start();
		try
		{
			for (int round = 0; round < ROUNDS; round++)
			{
				ReportWriter.write(outputDir, REPORT_FILE_NAME,
					round % 2 == 0 ? second : first);
			}
		}
		finally
		{
			writing.set(false);
			reader.join();
		}

		assertTrue("the reader has to have actually read something", reads.get() > 0);
		assertEquals("every read must see one whole report or the other, never a prefix "
				+ "and never a mixture: " + torn,
			Collections.emptyList(), torn);

		String[] left = outputDir.list();
		assertNotNull(left);
		assertEquals("and no draft may survive the race: " + Arrays.toString(left),
			1, left.length);
	}

	/** Big enough that a truncating writer is caught, small enough to stay quick. */
	private static final int FILLER_CHARS = 400_000;

	private static final int ROUNDS = 60;

	private static String filler(char c)
	{
		char[] chars = new char[FILLER_CHARS];
		Arrays.fill(chars, c);
		return new String(chars);
	}

	private File tryWrite(File outputDir)
	{
		try
		{
			return ReportWriter.write(outputDir, REPORT_FILE_NAME, emptyReport().toReportText());
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static CacheIdAudit.Report emptyReport()
	{
		CacheIdAudit.DatasetIds dataset = new CacheIdAudit.DatasetIds(
			new TreeSet<>(), new TreeSet<>(), new TreeSet<>(), new TreeMap<>(),
			Collections.emptyList(), 0);
		return CacheIdAudit.run(new FakeClient(), dataset);
	}

	private static CacheIdAudit.Report reportWithOneFailure()
	{
		FakeClient client = new FakeClient();
		client.setUnloadable(42);
		TreeSet<Integer> modelIds = new TreeSet<>();
		modelIds.add(42);
		CacheIdAudit.DatasetIds dataset = new CacheIdAudit.DatasetIds(
			modelIds, new TreeSet<>(), new TreeSet<>(), new TreeMap<>(),
			Collections.emptyList(), 0);
		return CacheIdAudit.run(client, dataset);
	}

	private static void deleteRecursively(File file)
	{
		File[] children = file.listFiles();
		if (children != null)
		{
			for (File child : children)
			{
				deleteRecursively(child);
			}
		}
		file.delete();
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A scenery prop that is one model short of every other copy of itself.
 *
 * <h2>The defect this exists for</h2>
 *
 * <p>The brazier at the Grand Exchange ({@code 12598.json}, tile 3169,3488) shipped
 * as {@code modelIds: [2260]}. Every other placement of the same prop in the dataset
 * — two in 12594, one in 12595, one in 12853, all four on {@code FireIdle} — is
 * {@code [2260, 3818]}. On video the Grand Exchange one renders with a flat,
 * untextured green face where the missing half should be.
 *
 * <h2>Why the cache audit cannot see this</h2>
 *
 * <p>{@code CacheIdAudit} asks the live client whether each id resolves, and 2260
 * resolves perfectly. "The id is valid" and "the model is complete" are different
 * questions, and until this test only the first had ever been asked. Nothing about
 * a single valid id says a second one was meant to be beside it.
 *
 * <h2>The rule, and why it is scenery only</h2>
 *
 * <p>Call {@code B} <b>exclusive to</b> {@code A} when every record carrying B also
 * carries A, and B appears at least twice — i.e. the dataset only ever uses B as
 * half of the pair {@code (A, B)}. If A then turns up in exactly one further record
 * <i>without</i> B, that record is the odd one out and the pair has been split.
 *
 * <p><b>Citizens are deliberately excluded, and the exclusion is measured rather
 * than assumed.</b> Run the same rule over the citizen roster and it produces
 * thirteen findings, none of them defects: a citizen is six to twelve individually
 * chosen wardrobe models, so two citizens sharing five parts and differing in the
 * sixth is the authoring working, not failing. Scenery is the opposite — a prop is
 * a fixed set of models copied off the game's own object, so a partial copy is a
 * broken prop, and the same rule over the 42 scenery records produced exactly one
 * finding: the brazier above. A rule that fires thirteen times on correct data is
 * not a guard, it is noise somebody will delete; this one is narrow on purpose.
 */
public class SceneryModelPairTest
{
	/** Scenery records in the shipped dataset. Pinned; see {@code RegionDataLoaderTest}. */
	private static final int SHIPPED_SCENERY_RECORDS = 42;

	/**
	 * The one that would have caught the Grand Exchange brazier.
	 */
	@Test
	public void noSceneryPropCarriesOnlyHalfOfAPairEveryOtherCopyHasWhole()
	{
		List<ShippedModelIds.Entry> scenery = sceneryRecords();
		Map<Integer, TreeSet<Integer>> recordsById = recordsByModelId(scenery);

		List<String> violations = new ArrayList<>();

		for (Map.Entry<Integer, TreeSet<Integer>> whole : recordsById.entrySet())
		{
			int a = whole.getKey();
			TreeSet<Integer> carryingA = whole.getValue();
			if (carryingA.size() < 3)
			{
				// Two records cannot tell "a pair with one broken copy" from "two
				// different props that happen to share a model".
				continue;
			}

			for (Map.Entry<Integer, TreeSet<Integer>> part : recordsById.entrySet())
			{
				int b = part.getKey();
				TreeSet<Integer> carryingB = part.getValue();
				if (a == b || carryingB.size() < 2 || !carryingA.containsAll(carryingB))
				{
					continue;
				}

				TreeSet<Integer> missingB = new TreeSet<>(carryingA);
				missingB.removeAll(carryingB);
				if (missingB.size() != 1)
				{
					continue;
				}

				ShippedModelIds.Entry odd = scenery.get(missingB.first());
				violations.add("model " + b + " is only ever used beside " + a + " ("
					+ carryingB.size() + " record(s)), but " + odd + " carries " + a
					+ " alone — a prop one model short renders with the missing face open");
			}
		}

		assertEquals("shipped scenery records", SHIPPED_SCENERY_RECORDS, scenery.size());
		assertTrue("scenery prop(s) missing half of a fixed model pair: " + violations,
			violations.isEmpty());
	}

	/**
	 * The rule has something to be true about.
	 *
	 * <p>Without this the test above passes on a dataset with no pairs in it at all,
	 * including one where somebody deleted the second model from all five braziers
	 * instead of adding it to the sixth. So the pair itself is asserted: 3818 is used
	 * only ever beside 2260, and the two appear in the same five records.
	 */
	@Test
	public void theBrazierIsAFixedPairAndAllFiveCopiesAreWhole()
	{
		Map<Integer, TreeSet<Integer>> recordsById = recordsByModelId(sceneryRecords());

		TreeSet<Integer> withBrazierBase = recordsById.get(2260);
		TreeSet<Integer> withBrazierTop = recordsById.get(3818);

		assertEquals("the brazier base is in five scenery records", 5,
			withBrazierBase == null ? 0 : withBrazierBase.size());
		assertEquals("and its companion model is in exactly the same five, not four",
			withBrazierBase, withBrazierTop);
	}

	/**
	 * A printed inventory of every model a scenery prop is built from, so the
	 * pairings are reviewable by eye rather than only by assertion.
	 */
	@Test
	public void printsTheSceneryModelInventoryForHumanReview()
	{
		TreeMap<String, Integer> byShape = new TreeMap<>();
		for (ShippedModelIds.Entry entry : sceneryRecords())
		{
			TreeSet<Integer> ids = new TreeSet<>();
			for (int id : entry.modelIds)
			{
				ids.add(id);
			}
			byShape.merge(ids.toString(), 1, Integer::sum);
		}

		System.out.println("Lively Cities scenery model sets — models, placements");
		int total = 0;
		for (Map.Entry<String, Integer> row : byShape.entrySet())
		{
			System.out.println(String.format("%-24s %d", row.getKey(), row.getValue()));
			total += row.getValue();
		}

		assertEquals("every scenery record has to appear in the inventory",
			SHIPPED_SCENERY_RECORDS, total);
	}

	// --- fixtures ------------------------------------------------------------

	/**
	 * @return which record indices carry each model id, keyed by id. Indices are into
	 * the list {@link #sceneryRecords()} returned, so the same list has to be used for
	 * both or the reported record is the wrong one.
	 */
	private static Map<Integer, TreeSet<Integer>> recordsByModelId(List<ShippedModelIds.Entry> records)
	{
		Map<Integer, TreeSet<Integer>> out = new TreeMap<>();
		for (int i = 0; i < records.size(); i++)
		{
			for (int id : records.get(i).modelIds)
			{
				out.computeIfAbsent(id, k -> new TreeSet<>()).add(i);
			}
		}
		return out;
	}

	/**
	 * Scenery only, read raw out of the JSON — {@link ShippedModelIds} exists so this
	 * sees what was authored rather than what survived validation, and
	 * {@link EntityDefinition} would have dropped a non-positive id before this test
	 * could notice a prop was short one.
	 */
	private static List<ShippedModelIds.Entry> sceneryRecords()
	{
		List<ShippedModelIds.Entry> out = new ArrayList<>();
		for (ShippedModelIds.Entry entry : ShippedModelIds.perEntity())
		{
			if ("Scenery".equals(entry.label))
			{
				out.add(entry);
			}
		}
		return out;
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import java.util.TreeSet;

/**
 * Pulls the raw {@code idleAnimation} / {@code moveAnimation} strings straight
 * out of the shipped JSON.
 *
 * <p>Deliberately bypasses {@link EntityDefinition}: that class has already
 * resolved names to enum constants and dropped the ones it could not, so asking
 * it which names the dataset uses would only ever return names that resolve.
 */
final class ShippedAnimationNames
{
	private ShippedAnimationNames()
	{
	}

	static Set<String> all()
	{
		Set<String> names = new TreeSet<>();

		for (int regionId : ShippedRegions.ids())
		{
			String resource = RegionDataLoader.DEFAULT_RESOURCE_PREFIX + regionId + ".json";
			InputStream in = ShippedAnimationNames.class.getClassLoader().getResourceAsStream(resource);
			if (in == null)
			{
				throw new IllegalStateException("missing " + resource);
			}

			try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				JsonObject root = TestGson.injected().fromJson(reader, JsonObject.class);
				collect(root, "citizenRoster", names);
				collect(root, "sceneryRoster", names);
			}
			catch (IOException e)
			{
				throw new IllegalStateException("could not read " + resource, e);
			}
		}

		if (names.isEmpty())
		{
			throw new IllegalStateException("no animation names found in the shipped dataset");
		}

		return names;
	}

	private static void collect(JsonObject root, String rosterKey, Set<String> into)
	{
		JsonElement roster = root.get(rosterKey);
		if (roster == null || !roster.isJsonArray())
		{
			return;
		}

		JsonArray array = roster.getAsJsonArray();
		for (JsonElement element : array)
		{
			if (!element.isJsonObject())
			{
				continue;
			}

			JsonObject record = element.getAsJsonObject();
			addIfPresent(record, "idleAnimation", into);
			addIfPresent(record, "moveAnimation", into);
		}
	}

	private static void addIfPresent(JsonObject record, String key, Set<String> into)
	{
		JsonElement value = record.get(key);
		if (value != null && value.isJsonPrimitive())
		{
			into.add(value.getAsString());
		}
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Pulls {@code citizenRoster} entries straight out of the shipped JSON, one
 * per record, carrying exactly the fields the placement lint needs: which
 * file it shipped in (the id {@link City} and the checkbox key on), its uuid,
 * and its name/examine text.
 *
 * <p>Deliberately bypasses {@link EntityDefinition}, the same way
 * {@link ShippedAnimationNames}, {@link ShippedModelIds} and
 * {@link ShippedWanderBoxes} do and for the same reason: this is an offline
 * audit over the authored data, not over what already survived validation.
 *
 * <p><b>Scenery is out of scope.</b> A {@code sceneryRoster} record carries no
 * {@code name} or {@code examineText} — {@link EntityRecord}'s own javadoc
 * says as much — so there is no signal to hand-author a theme from and no
 * name to write a table entry against. All 42 shipped scenery records are
 * generic props (market stalls, planters — see the placement lint report),
 * and {@code PlacementLintTest} explains this rather than guessing a theme
 * from a bare {@code modelIds} array.
 *
 * <p><b>The file's own region id is authoritative</b>, not the {@code
 * regionId} field inside the record. {@link EntityDefinition} treats that
 * field as a claim that can disagree with where the file actually lives (see
 * its {@code fromRecord} javadoc — "Dark wizard" claims 12853 but stands in
 * 12852) and resolves visibility on the tile instead. This class does not need
 * that distinction: {@link City}'s checkbox, and therefore the theme a citizen
 * is judged against, is keyed on which <i>file</i> shipped the record, exactly
 * like {@link ShippedAnimationNames} and its siblings.
 */
final class ShippedCitizens
{
	private ShippedCitizens()
	{
	}

	static List<Entry> all()
	{
		List<Entry> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			String resource = RegionDataLoader.DEFAULT_RESOURCE_PREFIX + regionId + ".json";
			InputStream in = ShippedCitizens.class.getClassLoader().getResourceAsStream(resource);
			if (in == null)
			{
				throw new IllegalStateException("missing " + resource);
			}

			try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				JsonObject root = TestGson.injected().fromJson(reader, JsonObject.class);
				collect(root, regionId, out);
			}
			catch (IOException e)
			{
				throw new IllegalStateException("could not read " + resource, e);
			}
		}

		if (out.isEmpty())
		{
			throw new IllegalStateException("no citizens found in the shipped dataset");
		}

		return out;
	}

	private static void collect(JsonObject root, int fileRegionId, List<Entry> into)
	{
		JsonElement roster = root.get("citizenRoster");
		if (roster == null || !roster.isJsonArray())
		{
			return;
		}

		JsonArray array = roster.getAsJsonArray();
		for (JsonElement element : array)
		{
			if (!element.isJsonObject())
			{
				continue;
			}

			JsonObject record = element.getAsJsonObject();
			into.add(new Entry(
				fileRegionId,
				string(record, "uuid"),
				string(record, "name"),
				string(record, "examineText"),
				string(record, "entityType"),
				bool(record, "cameo"),
				integer(record, "npcAppearanceId"),
				authoredRemarks(record)));
		}
	}

	private static String string(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : null;
	}

	private static boolean bool(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		return value != null && value.isJsonPrimitive() && value.getAsBoolean();
	}

	/** @return the field's value, or {@code 0} if the record does not carry it */
	private static int integer(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		return value != null && value.isJsonPrimitive() ? value.getAsInt() : 0;
	}

	/**
	 * How many remarks the record authored, or {@code null} for a record with no
	 * {@code remarks} field at all.
	 *
	 * <p>The distinction is the whole reason this is read from the JSON rather than
	 * from {@link EntityDefinition}: the validation gate flattens "no field",
	 * "{@code []}", "all blank" and "scenery" into one empty array on purpose, so
	 * asking it how many records spelled silence which way gets one answer for all
	 * four.
	 */
	private static Integer authoredRemarks(JsonObject record)
	{
		JsonElement value = record.get("remarks");
		if (value == null || value.isJsonNull())
		{
			return null;
		}
		return value.isJsonArray() ? value.getAsJsonArray().size() : null;
	}

	/** One shipped {@code citizenRoster} record, exactly as authored. */
	static final class Entry
	{
		final int fileRegionId;
		final String uuid;
		final String name;
		final String examineText;
		final String entityType;

		/** The record's own {@code cameo} flag, absent-or-false flattened to false. */
		final boolean cameo;

		/** The record's own {@code npcAppearanceId}, or {@code 0} if it has none. */
		final int npcAppearanceId;

		/**
		 * How many remarks the record authored, or {@code null} for one carrying no
		 * {@code remarks} field at all — the difference {@link EntityDefinition}
		 * deliberately flattens away.
		 */
		final Integer authoredRemarks;

		Entry(
			int fileRegionId,
			String uuid,
			String name,
			String examineText,
			String entityType,
			boolean cameo,
			int npcAppearanceId,
			Integer authoredRemarks)
		{
			this.fileRegionId = fileRegionId;
			this.uuid = uuid;
			this.name = name;
			this.examineText = examineText;
			this.entityType = entityType;
			this.cameo = cameo;
			this.npcAppearanceId = npcAppearanceId;
			this.authoredRemarks = authoredRemarks;
		}

		@Override
		public String toString()
		{
			return "'" + name + "' (" + examineText + ") in " + fileRegionId + ".json, uuid=" + uuid;
		}
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

/**
 * Pulls the raw {@code modelIds} arrays straight out of the shipped JSON, one
 * entry per roster record.
 *
 * <p>Deliberately bypasses {@link EntityDefinition}, the same way
 * {@link ShippedAnimationNames} and {@link ShippedWanderBoxes} do and for the
 * same reason: {@code EntityDefinition.usableModelIds} already drops a
 * non-positive id and {@code EntityDefinition.fromRecord} already skips a
 * record whose {@code modelIds} came out empty. Asking the validated definitions
 * whether the dataset ever carries a bad id would only ever see the ids that
 * already survived that filtering — the offline audit's job is to catch the
 * mistake before it is quietly dropped, not to confirm the drop happened.
 */
final class ShippedModelIds
{
	private ShippedModelIds()
	{
	}

	/**
	 * @return one entry per roster record in the shipped dataset, carrying its
	 * raw (unfiltered) {@code modelIds} array exactly as authored
	 */
	static List<Entry> perEntity()
	{
		List<Entry> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			String resource = RegionDataLoader.DEFAULT_RESOURCE_PREFIX + regionId + ".json";
			InputStream in = ShippedModelIds.class.getClassLoader().getResourceAsStream(resource);
			if (in == null)
			{
				throw new IllegalStateException("missing " + resource);
			}

			try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				JsonObject root = TestGson.injected().fromJson(reader, JsonObject.class);
				collect(root, "citizenRoster", regionId, out);
				collect(root, "sceneryRoster", regionId, out);
			}
			catch (IOException e)
			{
				throw new IllegalStateException("could not read " + resource, e);
			}
		}

		if (out.isEmpty())
		{
			throw new IllegalStateException("no roster records found in the shipped dataset");
		}

		return out;
	}

	/**
	 * @return every distinct raw {@code modelIds} value across the whole shipped
	 * dataset — 324 of them. It was 384 at the L0 audit; 376 once Rufus traded his
	 * twelve authored ids for an {@code npcAppearanceId} and the eight of them nobody
	 * else used left with him; and 324 after the nine-city cut on 2026-08-24 took
	 * eighteen region files and the 52 ids only they wore.
	 * {@code ModelIdAuditTest.theDistinctModelIdFigureIsPinned} is where that figure
	 * is held.
	 */
	static TreeSet<Integer> distinct()
	{
		TreeSet<Integer> ids = new TreeSet<>();
		for (Entry entry : perEntity())
		{
			for (int id : entry.modelIds)
			{
				ids.add(id);
			}
		}
		return ids;
	}

	private static void collect(JsonObject root, String rosterKey, int regionId, List<Entry> into)
	{
		JsonElement roster = root.get(rosterKey);
		if (roster == null || !roster.isJsonArray())
		{
			return;
		}

		JsonArray array = roster.getAsJsonArray();
		for (JsonElement element : array)
		{
			if (!element.isJsonObject())
			{
				continue;
			}

			JsonObject record = element.getAsJsonObject();
			into.add(new Entry(regionId, label(record), modelIds(record), npcAppearanceId(record)));
		}
	}

	/** @return the record's {@code npcAppearanceId}, or {@code 0} if it has none */
	private static int npcAppearanceId(JsonObject record)
	{
		JsonElement value = record.get("npcAppearanceId");
		return value != null && value.isJsonPrimitive() ? value.getAsInt() : 0;
	}

	private static String label(JsonObject record)
	{
		JsonElement name = record.get("name");
		if (name != null && name.isJsonPrimitive())
		{
			return name.getAsString();
		}

		JsonElement type = record.get("entityType");
		return type != null && type.isJsonPrimitive() ? type.getAsString() : "entity";
	}

	private static int[] modelIds(JsonObject record)
	{
		JsonElement value = record.get("modelIds");
		if (value == null || !value.isJsonArray())
		{
			return new int[0];
		}

		JsonArray array = value.getAsJsonArray();
		int[] ids = new int[array.size()];
		for (int i = 0; i < array.size(); i++)
		{
			ids[i] = array.get(i).getAsInt();
		}
		return ids;
	}

	/**
	 * @return every distinct raw {@code npcAppearanceId} across the shipped dataset,
	 * the other half of the appearance surface the durability tooling has to cover
	 */
	static TreeSet<Integer> distinctNpcAppearanceIds()
	{
		TreeSet<Integer> ids = new TreeSet<>();
		for (Entry entry : perEntity())
		{
			if (entry.npcAppearanceId != 0)
			{
				ids.add(entry.npcAppearanceId);
			}
		}
		return ids;
	}

	/**
	 * One roster record's raw, unfiltered {@code modelIds} and {@code npcAppearanceId},
	 * as authored.
	 */
	static final class Entry
	{
		final int regionId;
		final String label;
		final int[] modelIds;

		/** The record's own {@code npcAppearanceId}, or {@code 0} if it has none. */
		final int npcAppearanceId;

		Entry(int regionId, String label, int[] modelIds, int npcAppearanceId)
		{
			this.regionId = regionId;
			this.label = label;
			this.modelIds = modelIds;
			this.npcAppearanceId = npcAppearanceId;
		}

		@Override
		public String toString()
		{
			return "region " + regionId + " '" + label + "'";
		}
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.net.URISyntaxException;
import java.net.URL;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Enumerates the region ids actually present in
 * {@code src/main/resources/RegionData/}.
 *
 * <p>Discovered from the classpath rather than hard-coded, so adding a region
 * file automatically brings it under test — including the check that every
 * animation name it uses resolves.
 */
final class ShippedRegions
{
	private ShippedRegions()
	{
	}

	static List<Integer> ids()
	{
		URL url = ShippedRegions.class.getClassLoader().getResource(RegionDataLoader.DEFAULT_RESOURCE_PREFIX);
		if (url == null)
		{
			throw new IllegalStateException(
				"RegionData/ is not on the test classpath — main resources are not being processed");
		}

		File directory;
		try
		{
			directory = new File(url.toURI());
		}
		catch (URISyntaxException e)
		{
			throw new IllegalStateException("could not resolve " + url, e);
		}

		File[] files = directory.listFiles((dir, name) -> name.endsWith(".json"));
		if (files == null || files.length == 0)
		{
			throw new IllegalStateException("no region files under " + directory);
		}

		List<Integer> ids = new ArrayList<>(files.length);
		for (File file : files)
		{
			String base = file.getName();
			ids.add(Integer.parseInt(base.substring(0, base.length() - ".json".length())));
		}

		Collections.sort(ids);
		return ids;
	}
}

package com.matthewmariner.livelycities;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.plugins.Plugin;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What may and may not appear in {@code src/main} — the half of this repo that becomes
 * the jar the Plugin Hub builds and serves.
 *
 * <p><b>Why a source scan rather than a note in a doc.</b> The hub's automated reviewer
 * refuses to look at a plugin that does file I/O. riktenx, on
 * <a href="https://github.com/runelite/plugin-hub/pull/12366">plugin-hub#12366</a>:
 * "file i/o will make your plugin require manually review. if you can not use it your
 * plugin can be automatically reviewed." Removing the file writing once is easy;
 * keeping it removed across every future milestone is what needs a guard, and there is
 * nothing else in this build that would notice a {@code new File(...)} reappearing in a
 * shipped class. Everything about the arrangement — {@link ReportWriter} in the test
 * source set, {@link LivelyCitiesDevReportsPlugin} loaded only by two Gradle tasks —
 * is undone by one import.
 *
 * <p><b>What this test does not claim.</b> Only that the shipped source names no
 * filesystem API. The reviewer's rule set is private — riktenx again: "i cannot share
 * that code" — so whether the classpath {@code InputStream} below trips it cannot be
 * checked from outside, and nothing here should be read as a promise that a submission
 * passes automated review.
 */
public class ShippedSourceTest
{
	/**
	 * Every filesystem entry point, spelled the ways a Java file can spell them.
	 *
	 * <p>Deliberately narrower than "no {@code java.io}": {@code java.io} is also how
	 * you read a classpath resource, which is not filesystem access and which this
	 * plugin cannot ship without — see
	 * {@link #theClasspathResourceReaderIsDeliberatelyStillAllowed()}. Banning the whole
	 * package would either break the dataset or teach the next person to weaken this
	 * list, and a guard that has to be weakened to get work done stops being a guard.
	 */
	private static final List<String> FORBIDDEN = Collections.unmodifiableList(Arrays.asList(
		// Internal form, with slashes: this is how a class file spells a type. The
		// java/io/File prefix covers File, FileWriter, FileReader, FileInputStream,
		// FileOutputStream, FileDescriptor and FilePermission in one entry — in the
		// constant pool they really are all one prefix, which they were not in source.
		"java/io/File",
		"java/io/RandomAccessFile",
		"java/io/PrintWriter",
		"java/nio/file/",
		"java/nio/channels/FileChannel",
		"javax/swing/JFileChooser",
		// Both take a String or File and write to it. Neither names a "File" anything,
		// which is how new Formatter("x.txt") walked past the source-text version.
		"java/util/Formatter",
		"java/util/Scanner",
		// Both take a String path and open it, and neither is caught by anything above.
		// This is the exact shape a leaked cache reader takes: the game cache is a
		// directory of files, and reaching it from the shipped jar is precisely what
		// this project keeps in a scratchpad instead. ZipFile is also how a plugin
		// would read a jar it was not shipped inside.
		"java/util/zip/ZipFile",
		"java/util/jar/JarFile"));

	/**
	 * The one exemption, named rather than pattern-matched.
	 *
	 * <p>{@code RegionDataLoader} opens {@code RegionData/<id>.json} with
	 * {@code getClassLoader().getResourceAsStream(...)}. That reads out of the jar the
	 * plugin is already running from — no path, no directory, no write — and it is how
	 * every hub plugin that ships a dataset gets at it. It is not on the list above and
	 * does not need to be; this constant exists so the next test can prove the list is a
	 * precise ban rather than an accidentally empty one.
	 */
	private static final String CLASSPATH_READER = "RegionDataLoader.java";

	/**
	 * {@code startScript} as it appears in a class file's constant pool: a
	 * {@code CONSTANT_Utf8} is {@code u2} length then the bytes, so the eleven-character
	 * name is {@code 00 0B} followed by the name itself. Read back through
	 * {@code ISO-8859-1}, which maps every byte to the char of the same value, that is
	 * this string.
	 *
	 * <p>The length prefix is the whole point: without it, a search for the name also
	 * matches {@code startScriptRunner} or the field renamed, and a rename is exactly
	 * what the sample guard in {@link #noShippedClassReadsTheStartScriptField()} exists
	 * to notice.
	 */
	private static final String START_SCRIPT_POOL_ENTRY = "\000\013startScript";

	/**
	 * The compiled classes, not the source text — and that difference is the test.
	 *
	 * <p>A source scan is an approximation of the program and it leaks. Review found
	 * three ordinary ways past the list below: {@code import java.io.PrintWriter; new
	 * PrintWriter("x.txt")} names nothing on it; {@code import java.io.*} defeats
	 * {@code "java.io.File"}, which was only ever catching {@code FileWriter} and
	 * {@code FileOutputStream} by being a <i>prefix</i> of their import lines; and
	 * {@code new Formatter("x.txt")} is in {@code java.util}. Lengthening the list
	 * would just move the leak.
	 *
	 * <p>By the time javac is done, every one of those — wildcard import,
	 * fully-qualified name, static import, even
	 * {@code Class.forName("java.io." + "FileWriter")} — has collapsed into the same
	 * UTF-8 entry in the class file's constant pool. So the scan reads
	 * {@code build/classes/java/main} instead. {@code test} depends on {@code classes},
	 * so those files exist whenever this runs, and {@link #shippedClasses()} fails
	 * loudly rather than scanning nothing if that ever stops being true.
	 *
	 * <p>Searching the whole file rather than parsing the pool properly means a string
	 * literal spelling {@code java/io/File} would also trip this. That is the right
	 * bias: a shipped class containing that text wants a human to look at it either way.
	 */
	@Test
	public void noShippedClassCanReachAFilesystem() throws IOException
	{
		List<String> offences = new ArrayList<>();

		for (Path classFile : shippedClasses())
		{
			String constants = new String(
				Files.readAllBytes(classFile), StandardCharsets.ISO_8859_1);
			for (String forbidden : FORBIDDEN)
			{
				if (constants.contains(forbidden))
				{
					offences.add(classFile.getFileName() + " references " + forbidden);
				}
			}
		}

		assertEquals("src/main ships to the Plugin Hub, and file I/O there costs the "
				+ "submission its automated review. Whatever wanted a file belongs in "
				+ "src/test/java beside ReportWriter and LivelyCitiesDevReportsPlugin, "
				+ "which the two Gradle dev tasks load and the hub's jar does not contain: "
				+ offences,
			Collections.emptyList(), offences);
	}

	/**
	 * The guard on the guard: a known-bad class really is caught.
	 *
	 * <p>Without this, {@link #noShippedClassCanReachAFilesystem()} passes when
	 * {@link #FORBIDDEN} is empty, when the scan reads the wrong directory, and when
	 * {@link #shippedClasses()} returns nothing — three ways to be green while checking
	 * nothing at all. Review proved the first of them: emptying the list left every
	 * test in this file passing, in a file whose own javadoc claimed that could not
	 * happen.
	 *
	 * <p>The positive control is this test class itself. It is compiled into
	 * {@code build/classes/java/test}, it genuinely uses {@code java.nio.file}, and it
	 * is therefore exactly the artifact the scan must reject — so pointing the same
	 * matcher at it and requiring an offence proves the matcher works without needing a
	 * deliberately broken file checked into {@code src/main}.
	 */
	@Test
	public void theScanActuallyCatchesAClassThatTouchesTheFilesystem() throws IOException
	{
		Path knownBad = Paths.get("build/classes/java/test",
			"com/matthewmariner/livelycities/ShippedSourceTest.class");
		assertTrue("expected the compiled form of this very test at " + knownBad.toAbsolutePath()
				+ " — without it there is no positive control and the scan could be"
				+ " matching nothing", Files.isRegularFile(knownBad));

		String constants = new String(
			Files.readAllBytes(knownBad), StandardCharsets.ISO_8859_1);

		List<String> hits = new ArrayList<>();
		for (String forbidden : FORBIDDEN)
		{
			if (constants.contains(forbidden))
			{
				hits.add(forbidden);
			}
		}

		assertFalse("this class uses java.nio.file, so the scan has to flag it. Zero hits"
				+ " means FORBIDDEN is empty or the matcher is broken, and"
				+ " noShippedClassCanReachAFilesystem is passing for no reason",
			hits.isEmpty());
	}

	/**
	 * And the scan is a ban on filesystems, not on {@code java.io} — proven by the file
	 * that still needs it.
	 *
	 * <p>Without this, the test above would keep passing if somebody "fixed" a future
	 * violation by deleting the dataset reader, and it would keep passing if the ban
	 * list were quietly emptied. Here the exemption is exercised: this file really does
	 * import {@code java.io}, really is in {@code src/main}, and really does ship.
	 */
	@Test
	public void theClasspathResourceReaderIsDeliberatelyStillAllowed() throws IOException
	{
		Path reader = shippedSources().stream()
			.filter(path -> CLASSPATH_READER.equals(path.getFileName().toString()))
			.findFirst()
			.orElseThrow(() -> new AssertionError(
				"expected to find " + CLASSPATH_READER + " under src/main/java"));

		String text = new String(Files.readAllBytes(reader), StandardCharsets.UTF_8);

		assertTrue(CLASSPATH_READER + " is the reason the ban above is a list of "
				+ "filesystem entry points rather than a blanket 'no java.io' — if it "
				+ "stopped importing java.io, that reasoning would be stale",
			text.contains("import java.io.InputStream;"));
		assertTrue("and what it does with it has to still be a classpath read: a path, a "
				+ "directory or a stream opened on a File would be filesystem access "
				+ "wearing the exemption's coat",
			text.contains("getClassLoader().getResourceAsStream("));
	}

	/**
	 * The dev client loads the plugin that writes the reports.
	 *
	 * <p>The last link in the chain the two Gradle tasks start:
	 * {@code sourceSets.test.runtimeClasspath} puts the reporter on the classpath, the
	 * system property opens its gate, and this list is what actually hands it to
	 * RuneLite. Drop it here and {@code ./gradlew runWithTimings} launches a client that
	 * measures perfectly and writes nothing.
	 *
	 * <p><b>It asserts on {@code builtinPlugins()}, not on the list</b>, and the
	 * difference is the whole test. An earlier version read {@code BUILTIN_PLUGINS}
	 * directly, which meant {@code main} could stop using the list altogether —
	 * hardcoding {@code loadBuiltin(LivelyCitiesPlugin.class)} and leaving the list
	 * sitting there intact and unread — and this stayed green while the reporter was
	 * never loaded. That is precisely the failure described above, reachable without
	 * turning anything red. {@code builtinPlugins()} is the only path from the list to
	 * {@code loadBuiltin}, so asserting on it asserts on the hand-off.
	 */
	@Test
	public void theDevClientLoadsTheReporterThatWritesTheReports() throws IOException
	{
		List<Class<? extends Plugin>> loaded =
			Arrays.asList(LivelyCitiesPluginTest.builtinPlugins());

		assertTrue("LivelyCitiesPluginTest.main has to load the reporter alongside the "
				+ "plugin: " + loaded,
			loaded.contains(LivelyCitiesDevReportsPlugin.class));
		assertTrue("and the plugin itself, obviously",
			loaded.contains(LivelyCitiesPlugin.class));

		// And main() has to actually hand that list over. Asserting only on the list
		// leaves the real failure reachable: hardcode loadBuiltin(LivelyCitiesPlugin
		// .class), leave BUILTIN_PLUGINS sitting there correct and unread, and every
		// assertion above still passes while the reporter is never loaded. Nothing
		// short of running main() can observe the call, and main() starts a client —
		// so the source text is the evidence, the same way this class reads src/main
		// and FrameTimingsTest reads build.gradle.
		String source = new String(Files.readAllBytes(
			new File("src/test/java/com/matthewmariner/livelycities/LivelyCitiesPluginTest.java")
				.toPath()), StandardCharsets.UTF_8);

		assertTrue("LivelyCitiesPluginTest.main has to pass builtinPlugins() to"
				+ " loadBuiltin — a hardcoded argument list would leave BUILTIN_PLUGINS"
				+ " correct, unread, and load nothing",
			source.contains("loadBuiltin(builtinPlugins())"));
	}

	/**
	 * Every {@code .class} compiled from {@code src/main/java} — the jar's actual
	 * contents, nested and synthetic classes included.
	 *
	 * <p>Fails loudly rather than scanning an empty list: a scan of nothing passes, and
	 * "passed" is the answer this test must never give by accident.
	 */
	/**
	 * <b>Nothing in the shipped jar reads {@code startScript}.</b>
	 *
	 * <p>A different rule from the one above, sharing its mechanism because the
	 * mechanism is the point. The vendored format has a {@code startScript} field
	 * naming a behaviour, five shipped records carry one, and this plugin has no
	 * script engine: {@link EntityRecord} parses the field so the redistributed files
	 * stay a faithful copy of the format they came from, and the render core ignores
	 * it entirely. Those five {@code ScriptedCitizen}s stand exactly where they were
	 * placed and are indistinguishable in behaviour from a {@code StationaryCitizen}.
	 *
	 * <p>That is a limitation the README states in as many words, and a limitation
	 * stated in prose is one refactor away from being wrong in prose. It is checkable
	 * exactly: reading {@code record.startScript} from anywhere puts a {@code Fieldref}
	 * in the <i>reading</i> class's constant pool, and with it the UTF-8 entry
	 * {@code startScript}. So the name may appear in {@code EntityRecord.class}, which
	 * declares it, and in no other shipped class. Javadoc mentioning the field is
	 * invisible here, which is the right way round — a comment about a field is not a
	 * use of it.
	 *
	 * <p>If a script engine is ever built, this test is the thing that says so, and
	 * deleting it is part of shipping one. It is not a rule against the feature; it is
	 * a rule against the README quietly ceasing to be true.
	 *
	 * <p><b>The search is for the exact constant-pool entry, not the substring.</b> A
	 * {@code contains("startScript")} is also satisfied by {@code startScriptRunner},
	 * {@code startScriptName} and the field simply renamed — which is how the sample
	 * guard at the bottom first passed a mutation that renamed the field out from under
	 * it. A pool {@code CONSTANT_Utf8} is length-prefixed, so the eleven-character name
	 * is the bytes {@code 00 0B} followed by {@code startScript} and nothing longer
	 * matches. See {@link #START_SCRIPT_POOL_ENTRY}.
	 */
	@Test
	public void noShippedClassReadsTheStartScriptField() throws IOException
	{
		List<String> readers = new ArrayList<>();
		boolean declared = false;

		for (Path classFile : shippedClasses())
		{
			String constants = new String(
				Files.readAllBytes(classFile), StandardCharsets.ISO_8859_1);
			if (!constants.contains(START_SCRIPT_POOL_ENTRY))
			{
				continue;
			}

			String name = classFile.getFileName().toString();
			if ("EntityRecord.class".equals(name))
			{
				declared = true;
			}
			else
			{
				readers.add(name);
			}
		}

		assertTrue("classes naming startScript other than the DTO that declares it — if a"
				+ " script engine has landed, the README's \"and no script runs\" limitation"
				+ " has to go with this test: " + readers,
			readers.isEmpty());

		// The sample guard: the rule above is a search for absence, and a scan that
		// found the name nowhere at all would pass while proving nothing about whether
		// the field still exists to be read.
		assertTrue("EntityRecord has to still declare a field named exactly startScript,"
			+ " or this test is checking that nobody reads a field nobody has", declared);
	}

	private static List<Path> shippedClasses() throws IOException
	{
		Path root = Paths.get("build/classes/java/main");
		assertTrue("expected compiled classes at " + root.toAbsolutePath()
				+ " — the test task depends on the main classes, so if these are missing"
				+ " the build layout changed and this test has to change with it",
			Files.isDirectory(root));

		try (Stream<Path> walk = Files.walk(root))
		{
			List<Path> classes = walk
				.filter(path -> path.getFileName().toString().endsWith(".class"))
				.sorted()
				.collect(Collectors.toList());

			assertTrue("no .class files under " + root.toAbsolutePath()
					+ " — a scan of nothing would pass", !classes.isEmpty());
			return classes;
		}
	}

	/**
	 * Every {@code .java} file under {@code src/main/java}.
	 *
	 * <p>Gradle runs tests with the project directory as the working directory — the
	 * same assumption {@code FrameTimingsTest} makes when it reads {@code build.gradle}
	 * — and this fails loudly rather than scanning an empty list if that ever changes.
	 */
	private static List<Path> shippedSources() throws IOException
	{
		File root = new File("src/main/java");
		assertTrue("expected to find " + root.getAbsolutePath()
				+ " — if the test working directory moved, this test needs to move with it",
			root.isDirectory());

		try (Stream<Path> paths = Files.walk(root.toPath()))
		{
			List<Path> sources = paths
				.filter(path -> path.getFileName().toString().endsWith(".java"))
				.sorted()
				.collect(Collectors.toList());

			assertTrue("a scan that found no source files proves nothing",
				sources.size() > 20);
			return sources;
		}
	}
}

package com.matthewmariner.livelycities;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Pulls the {@code wanderBox} corners straight out of the shipped JSON, as
 * authored.
 *
 * <p><b>Deliberately bypasses {@link EntityDefinition}</b>, the same way
 * {@link ShippedAnimationNames} does and for the same reason — and here the
 * reason has teeth. {@code EntityDefinition} <i>clamps</i> a wander box to
 * {@link RenderPolicy#DATASET_OVERHANG_ALLOWANCE} tiles around the citizen's
 * start tile. Asking it how far the dataset's boxes reach would therefore always
 * get the allowance back, whatever the allowance was set to: the guard on that
 * number would be measuring its own output and could never go red.
 *
 * <p>A mutation test found exactly that. This class is the fix.
 */
final class ShippedWanderBoxes
{
	private ShippedWanderBoxes()
	{
	}

	/**
	 * @return one entry per {@code WanderingCitizen} in the shipped dataset, with
	 * the box exactly as the file states it
	 */
	static List<Authored> all()
	{
		List<Authored> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			String resource = RegionDataLoader.DEFAULT_RESOURCE_PREFIX + regionId + ".json";
			InputStream in = ShippedWanderBoxes.class.getClassLoader().getResourceAsStream(resource);
			if (in == null)
			{
				throw new IllegalStateException("missing " + resource);
			}

			try (Reader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				JsonObject root = TestGson.injected().fromJson(reader, JsonObject.class);
				collect(root, regionId, out);
			}
			catch (IOException e)
			{
				throw new IllegalStateException("could not read " + resource, e);
			}
		}

		if (out.isEmpty())
		{
			throw new IllegalStateException("no wander boxes found in the shipped dataset");
		}

		return out;
	}

	private static void collect(JsonObject root, int regionId, List<Authored> into)
	{
		JsonElement roster = root.get("citizenRoster");
		if (roster == null || !roster.isJsonArray())
		{
			return;
		}

		JsonArray array = roster.getAsJsonArray();
		for (JsonElement element : array)
		{
			if (!element.isJsonObject())
			{
				continue;
			}

			JsonObject record = element.getAsJsonObject();
			if (!"WanderingCitizen".equals(string(record, "entityType")))
			{
				continue;
			}

			JsonObject base = object(record, "worldLocation");
			JsonObject bl = object(record, "wanderBoxBL");
			JsonObject tr = object(record, "wanderBoxTR");
			if (base == null || bl == null || tr == null)
			{
				// Reported as-is: a wanderer with no box is a finding, not
				// something to quietly drop.
				into.add(new Authored(regionId, string(record, "name"), 0, 0, 0, 0, 0, 0, false));
				continue;
			}

			into.add(new Authored(
				regionId,
				string(record, "name"),
				base.get("x").getAsInt(),
				base.get("y").getAsInt(),
				bl.get("x").getAsInt(),
				bl.get("y").getAsInt(),
				tr.get("x").getAsInt(),
				tr.get("y").getAsInt(),
				true));
		}
	}

	private static String string(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : null;
	}

	private static JsonObject object(JsonObject record, String key)
	{
		JsonElement value = record.get(key);
		return value != null && value.isJsonObject() ? value.getAsJsonObject() : null;
	}

	/** One wandering citizen's box, exactly as the file states it. */
	static final class Authored
	{
		private final int regionId;
		private final String name;
		private final int baseX;
		private final int baseY;
		private final int blX;
		private final int blY;
		private final int trX;
		private final int trY;
		private final boolean hasBox;

		Authored(int regionId, String name, int baseX, int baseY,
			int blX, int blY, int trX, int trY, boolean hasBox)
		{
			this.regionId = regionId;
			this.name = name;
			this.baseX = baseX;
			this.baseY = baseY;
			this.blX = blX;
			this.blY = blY;
			this.trX = trX;
			this.trY = trY;
			this.hasBox = hasBox;
		}

		boolean hasBox()
		{
			return hasBox;
		}

		/**
		 * @return Chebyshev distance from the citizen's start tile to the furthest
		 * corner of its authored box — i.e. how far from the tile its cull check is
		 * measured against the walk can take it
		 */
		int reach()
		{
			int dx = Math.max(Math.abs(blX - baseX), Math.abs(trX - baseX));
			int dy = Math.max(Math.abs(blY - baseY), Math.abs(trY - baseY));
			return Math.max(dx, dy);
		}

		@Override
		public String toString()
		{
			return "'" + name + "' in " + regionId + ".json at " + baseX + "," + baseY
				+ " pacing " + blX + "," + blY + ".." + trX + "," + trY;
		}
	}
}

package com.matthewmariner.livelycities;

import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

/**
 * The collision-map read, and the meaning of the flags it reads.
 *
 * <p>This is the class the whole {@link CrowdDensity#CROWDED} feature rests on: if
 * it answers "standable" for a tile that is a wall, the feature puts people inside
 * buildings, and no amount of determinism elsewhere helps. So every branch has a
 * test, including the four separate ways of having no answer at all — because
 * {@link StandableGround.Verdict#UNKNOWN} being silently treated as a yes is the
 * failure that would look fine in a unit test and wrong in Varrock.
 *
 * <p>The scene here is the one {@link FakeWorldView#around} builds, which places
 * the 104x104 square the way the client does, so the scene-coordinate arithmetic
 * under test is the arithmetic the game exercises.
 */
public class StandableGroundTest
{
	private static final int VARROCK_SOUTH = 12852;

	/** Inside region 12852, comfortably inside the scene the fake builds. */
	private static final WorldPoint PLAYER = new WorldPoint(3225, 3360, 0);

	@Test
	public void aTileWithNoBlockingFlagsIsStandable()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);

		assertSame(StandableGround.Verdict.STANDABLE,
			StandableGround.verdict(view, new WorldPoint(3230, 3362, 0)));
	}

	/**
	 * The three bits that mean "the tile itself cannot be occupied", one at a time.
	 *
	 * <p>Separately rather than only through {@code BLOCK_MOVEMENT_FULL}, because a
	 * mask narrowed to any two of the three would still pass a test that only ever
	 * sets all three at once — and each of the three is a real, common piece of
	 * geometry: a wall or counter fills the tile ({@code OBJECT}), a floor decoration
	 * fills it ({@code FLOOR_DECORATION}), or there is no walkable floor there at all
	 * ({@code FLOOR}, which is what open water and a building's footprint look like).
	 */
	@Test
	public void eachOfTheThreeFullBlockBitsOnItsOwnBlocksStanding()
	{
		int[] bits = {
			CollisionDataFlag.BLOCK_MOVEMENT_OBJECT,
			CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION,
			CollisionDataFlag.BLOCK_MOVEMENT_FLOOR,
		};

		for (int bit : bits)
		{
			FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
			WorldPoint tile = new WorldPoint(3230, 3362, 0);
			view.setFlags(tile, bit);

			assertSame("flag " + bit + " must block standing",
				StandableGround.Verdict.BLOCKED, StandableGround.verdict(view, tile));
		}
	}

	/**
	 * A wall along one edge of a tile does not stop a person standing on it.
	 *
	 * <p>This is the guard on the other side of the mask, and it is the one that
	 * matters for the crowd: almost every tile of pavement next to a building in
	 * Varrock carries one or more directional bits, so a check that refused them
	 * would refuse most of the ground a citizen could actually be standing on and
	 * quietly shrink the feature to nothing. Line-of-sight bits are in here too —
	 * they are about projectiles and sight, not about standing.
	 */
	@Test
	public void directionalAndLineOfSightBitsDoNotStopSomebodyStandingOnTheTile()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		WorldPoint tile = new WorldPoint(3230, 3362, 0);

		view.setFlags(tile, CollisionDataFlag.BLOCK_MOVEMENT_NORTH
			| CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST
			| CollisionDataFlag.BLOCK_MOVEMENT_EAST
			| CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST
			| CollisionDataFlag.BLOCK_MOVEMENT_SOUTH
			| CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST
			| CollisionDataFlag.BLOCK_MOVEMENT_WEST
			| CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST
			| CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL);

		assertSame("a tile boxed in by walls is still a tile somebody is standing on",
			StandableGround.Verdict.STANDABLE, StandableGround.verdict(view, tile));
	}

	/**
	 * {@code BLOCK_MOVEMENT_FULL} is exactly the three non-directional bits.
	 *
	 * <p>Pinned as arithmetic on the API's own constants, because the entire
	 * justification for using that one aggregate is that it is those three and
	 * nothing else. If a client update folded a directional bit into it, this goes
	 * red and the reasoning in {@link StandableGround}'s javadoc gets revisited
	 * instead of silently becoming untrue.
	 */
	@Test
	public void blockMovementFullIsExactlyTheThreeNonDirectionalBits()
	{
		assertEquals(
			CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
				| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION
				| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR,
			CollisionDataFlag.BLOCK_MOVEMENT_FULL);

		assertEquals("and that aggregate is what this class turns on",
			CollisionDataFlag.BLOCK_MOVEMENT_FULL, StandableGround.BLOCKS_STANDING);
	}

	/**
	 * The flags array is {@code [sceneX][sceneY]}, not the transpose.
	 *
	 * <p>An asymmetric fixture on purpose: blocking (dx=+5, dy=+1) and then asking
	 * about (dx=+1, dy=+5) is a question a transposed reader gets exactly backwards,
	 * while a square offset like (+3,+3) would let both readers pass. This is the
	 * order the injected client writes with — {@code gc.cv(x,y)} does
	 * {@code bb[x - originX][y - originY] |= 2097152} — and the order RuneLite's own
	 * DevTools collision overlay reads with.
	 */
	@Test
	public void theFlagsAreIndexedSceneXThenSceneY()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		WorldPoint blocked = new WorldPoint(PLAYER.getX() + 5, PLAYER.getY() + 1, 0);
		WorldPoint transposed = new WorldPoint(PLAYER.getX() + 1, PLAYER.getY() + 5, 0);
		view.block(blocked);

		assertSame(StandableGround.Verdict.BLOCKED, StandableGround.verdict(view, blocked));
		assertSame("the transposed tile must be untouched, or the indices are the wrong way round",
			StandableGround.Verdict.STANDABLE, StandableGround.verdict(view, transposed));
	}

	/** Each plane has its own map, so blocking one storey must not block another. */
	@Test
	public void theMapIsSelectedByTheTilesOwnPlane()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);
		WorldPoint ground = new WorldPoint(3230, 3362, 0);
		WorldPoint upstairs = new WorldPoint(3230, 3362, 1);
		view.block(ground);

		assertSame(StandableGround.Verdict.BLOCKED, StandableGround.verdict(view, ground));
		assertSame("blocking the ground floor must not block the storey above it",
			StandableGround.Verdict.STANDABLE, StandableGround.verdict(view, upstairs));
	}

	// --- The four ways of having no answer ------------------------------------

	@Test
	public void noCollisionDataAtAllIsUnknownRatherThanStandable()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH).withoutCollisionData();

		assertSame(StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(view, new WorldPoint(3230, 3362, 0)));
	}

	@Test
	public void aPlaneWithNoMapYetIsUnknown()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH).withoutCollisionMapFor(0);

		assertSame(StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(view, new WorldPoint(3230, 3362, 0)));
		assertSame("and the planes that do have a map still answer",
			StandableGround.Verdict.STANDABLE,
			StandableGround.verdict(view, new WorldPoint(3230, 3362, 1)));
	}

	/**
	 * A plane outside the four the client allocates.
	 *
	 * <p>{@code EntityDefinition} already refuses a record whose plane is outside
	 * 0..3, so this is unreachable from the dataset — and it is tested anyway,
	 * because the alternative to a bounds check is an
	 * {@code ArrayIndexOutOfBoundsException} thrown once per game tick out of a
	 * visibility pass.
	 */
	@Test
	public void aPlaneOutsideTheFourTheClientAllocatesIsUnknown()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);

		assertSame(StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(view, new WorldPoint(3230, 3362, 9)));
	}

	@Test
	public void aTileOutsideTheLoadedSceneIsUnknown()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH);

		assertSame("far to the west of the scene",
			StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(view, new WorldPoint(PLAYER.getX() - 500, PLAYER.getY(), 0)));
		assertSame("far to the north of it",
			StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(view, new WorldPoint(PLAYER.getX(), PLAYER.getY() + 500, 0)));
	}

	/**
	 * A {@code WorldEntity}'s view answers nothing.
	 *
	 * <p>Not caution: the injected client builds a non-top-level collision map with
	 * its origin one tile to the south-west and its size six tiles larger in each
	 * axis ({@code gc.<init>} takes a boolean for exactly this, and the world view
	 * passes {@code getId() != 0}). Reading it with scene coordinates would answer
	 * about the tile diagonally behind the one asked about — off by one, silently,
	 * which is how a citizen ends up half inside a wall. This plugin only ever hands
	 * over {@code client.getTopLevelWorldView()}; the check is so a later caller
	 * cannot.
	 */
	@Test
	public void aNonTopLevelWorldViewIsUnknownBecauseItsFlagsAreOriginShifted()
	{
		FakeWorldView view = FakeWorldView.around(PLAYER, VARROCK_SOUTH).asWorldEntityView();

		assertSame(StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(view, new WorldPoint(3230, 3362, 0)));
	}

	@Test
	public void nullsAreUnknownRatherThanAThrow()
	{
		assertSame(StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(null, new WorldPoint(3230, 3362, 0)));
		assertSame(StandableGround.Verdict.UNKNOWN,
			StandableGround.verdict(FakeWorldView.around(PLAYER, VARROCK_SOUTH), null));
	}
}

