/**
 * Hands the tests the exact {@link Gson} instance RuneLite binds in Guice.
 *
 * <p>{@code RuneLiteModule} does {@code bind(Gson.class).toInstance(RuneLiteAPI.GSON)},
 * so this is not an approximation of the injected Gson — it is the same object.
 * That matters: a locally-built Gson could differ in naming policy or leniency
 * and the loader tests would then be verifying a parser the plugin never uses.
 * It also keeps {@code new Gson(} — a Plugin Hub disallowed API — out of the
 * repository entirely, test sources included.
 */
final class TestGson
{
	private TestGson()
	{
	}

	static Gson injected()
	{
		return RuneLiteAPI.GSON;
	}
}

package com.matthewmariner.livelycities;

import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

/**
 * Stands in for {@link LivelyCitiesPlugin}'s game-tick handler on a real
 * {@code EventBus}: runs the visibility pass at the default priority and nothing else.
 *
 * <p><b>Its name is the fixture.</b> {@code EventBus} orders subscribers by
 * {@code comparingDouble(Subscriber::getPriority).reversed().thenComparing(s ->
 * s.object.getClass().getName())} — verified in the 1.12.36 bytecode — so equal
 * priorities fall back to <i>alphabetical order of the subscriber's class name</i>.
 *
 * <p>That tiebreak is why this is a named top-level class instead of an anonymous one
 * inside the test. An anonymous subscriber is {@code …livelycities.FrameTimingsTest$3},
 * and {@code F} sorts before {@code L}, so it would run before
 * {@link LivelyCitiesDevReportsPlugin} whatever the priority said — making the
 * ordering test pass on alphabetical luck rather than on the annotation under test.
 *
 * <p>Production sorts the other way, and that is the whole point:
 * {@code LivelyCitiesDevReportsPlugin} sorts <i>before</i> {@code LivelyCitiesPlugin}
 * ({@code D} before {@code P}), so at equal priority the reporter would run before the
 * pass it measures and every report would omit the tick that triggered it.
 * {@code TickPassRunner} reproduces that relationship — {@code T} after {@code L} — so
 * only the reporter's negative priority can put it last, and deleting that priority
 * turns the test red the way it should.
 */
public final class TickPassRunner
{
	private final EntityScene scene;
	private final net.runelite.api.coords.WorldPoint player;
	private final net.runelite.api.WorldView view;

	TickPassRunner(EntityScene scene, net.runelite.api.coords.WorldPoint player,
		net.runelite.api.WorldView view)
	{
		this.scene = scene;
		this.player = player;
		this.view = view;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		scene.updateVisibility(player, view);
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Nobody in this plugin lies collapsed in a public street.
 *
 * <h2>Why this is a rule and not a preference</h2>
 *
 * <p>Four vendored citizens rendered <i>exactly as authored</i> — nothing was broken
 * about them. What they depicted was the problem: a peasant lying flat in the road
 * in Varrock, a tramp curled up on the ground in Draynor market beside child NPCs,
 * a man weeping in the street, and a man face-down outside Edgeville. The brief for
 * this plugin is ambient city life; on video those four read as bugs, and one of
 * them reads worse than a bug.
 *
 * <p>They were re-posed rather than deleted, because the characters are good — a
 * drunk, a tramp, a man having a bad day, someone who came back from the Wilderness
 * the hard way all belong in a city. Only the pose changed; examine text and
 * remarks are untouched, and {@code NOTICE} records the change against the vendored
 * data as the licence requires.
 *
 * <p>This test is what stops the change being undone by accident, and — more
 * usefully — what stops the next authoring pass reaching for the same animations. A
 * dataset that is going to grow needs the rule written down where it executes.
 */
public class UprightPoseTest
{
	/**
	 * Poses that put a person on the ground or visibly in distress.
	 *
	 * <p>Named individually rather than inferred, because there is no property of an
	 * animation that says "this is undignified" — it is an editorial judgement and it
	 * belongs in a list a human can argue with. Every one of these is still in
	 * {@link LivelyAnimation}: the ids remain correct and a future authored scene —
	 * a hospital, a battlefield, the aftermath of something — may well want them. It
	 * is a <i>street</i> they may not be used in.
	 */
	private static final Set<LivelyAnimation> NOT_FOR_A_PUBLIC_STREET = EnumSet.of(
		LivelyAnimation.HalfLayingDown,  // WOUNDED_SITTING (1147)
		LivelyAnimation.LayingDown,      // HUMAN_UNCONSCIOUS (838)
		LivelyAnimation.CurledUp,        // MYQ3_CITIZEN_HUDDLED (4712)
		LivelyAnimation.FallenManDead,   // DREAM_CYRISUS_UNCONSCIOUS (6280)
		LivelyAnimation.FallenManIdle,   // DREAM_CYRISUS_BARELY_CONSCIOUS (6282)
		LivelyAnimation.Crying           // EMOTE_CRY (860)
	);

	/**
	 * The rule, over every citizen in the dataset.
	 */
	@Test
	public void noCitizenIsPosedCollapsedOrDistressed()
	{
		List<String> violations = new ArrayList<>();

		for (EntityDefinition entity : shipped())
		{
			if (entity.getType() == null || !entity.getType().isCitizen())
			{
				continue;
			}

			LivelyAnimation pose = entity.getIdleAnimation();
			if (pose != null && NOT_FOR_A_PUBLIC_STREET.contains(pose))
			{
				violations.add(entity.label() + " in " + entity.getRegionId() + ".json is posed "
					+ pose + " — \"" + entity.getExamineText() + "\"");
			}
		}

		assertTrue("citizen(s) depicted on the ground or in distress in a public street: "
			+ violations, violations.isEmpty());

		assertEquals("the list has to keep its teeth — six poses, not an empty set",
			6, NOT_FOR_A_PUBLIC_STREET.size());
	}

	/**
	 * The four, by name and by pose.
	 *
	 * <p>The sweep above stays green if somebody "fixes" a prone citizen by deleting
	 * it, or by giving all four the same blank {@code HumanIdle}. This says what each
	 * one was actually given and why it is that one, so a regression names the person.
	 */
	@Test
	public void theFourRePosedCitizensAreStandingAndStillThemselves()
	{
		// DRUNK_PLAYER_READY (2770) — the standing animation the game gives its own
		// "Drunken man", NpcID.FALADOR_MAN1. He sways instead of lying in the road.
		assertPose(12597, "Drunken peasant", LivelyAnimation.DrunkPlayerReady, "He had a long night.");

		// VARROCK_TRAMP_READY (6480) — the game's own idea of how a Varrock tramp
		// stands, and Joe is Varrock's tramp. Hunched, but on his feet.
		assertPose(12853, "Joe the tramp", LivelyAnimation.VarrockTrampReady, "He's had better days.");

		// EMOTE_SLAP_HEAD (4275) — upright, legible from across a street, and exactly
		// what the examine text already said about him. Replaces EMOTE_CRY.
		assertPose(12853, "Pryce", LivelyAnimation.SlapHead, "He's not having a good day.");

		// NERVOUS_IDLE (10680) — the standing animation of NPC 12667 "Bandit". A man
		// who came back from the Wilderness, still checking over his shoulder,
		// rather than a body on the ground outside the bank.
		assertPose(12342, "Damien", LivelyAnimation.NervousIdle, "A victim of the wilderness.");

		for (LivelyAnimation replaced : EnumSet.of(LivelyAnimation.HalfLayingDown,
			LivelyAnimation.CurledUp, LivelyAnimation.Crying, LivelyAnimation.FallenManIdle))
		{
			assertTrue(replaced + " was one of the four replaced poses and has to stay on the list",
				NOT_FOR_A_PUBLIC_STREET.contains(replaced));
		}
	}

	/**
	 * The one exemption, stated out loud.
	 *
	 * <p>The rule above is scoped to citizens, and that is not an oversight: a scenery
	 * record in {@code 12342.json} at 3090,3499 — the tile beside Damien — carries
	 * {@code FallenManIdle} on a single-model prop. It is not a person, it has no
	 * examine text, and nothing offline can say what model 2384 depicts. Rather than
	 * quietly excluding scenery, the exemption is pinned at exactly one record, so a
	 * second one cannot appear without somebody deciding it should.
	 */
	@Test
	public void exactlyOneSceneryRecordUsesOneOfThesePosesAndItIsTheKnownOne()
	{
		List<String> sceneryUsing = new ArrayList<>();

		for (EntityDefinition entity : shipped())
		{
			if (entity.getType() != EntityType.Scenery)
			{
				continue;
			}
			LivelyAnimation pose = entity.getIdleAnimation();
			if (pose != null && NOT_FOR_A_PUBLIC_STREET.contains(pose))
			{
				sceneryUsing.add(entity.getRegionId() + " " + entity.label() + " " + pose);
			}
		}

		assertEquals("scenery records using a ground pose: " + sceneryUsing, 1, sceneryUsing.size());
		assertEquals("12342 Scenery@3090,3499,0 FallenManIdle", sceneryUsing.get(0));
	}

	// --- fixtures ------------------------------------------------------------

	private static void assertPose(int regionId, String name, LivelyAnimation pose, String examine)
	{
		EntityDefinition citizen = null;
		for (EntityDefinition candidate : shipped())
		{
			if (candidate.getRegionId() == regionId && name.equals(candidate.getName()))
			{
				assertNull("two citizens named " + name + " in " + regionId + ".json", citizen);
				citizen = candidate;
			}
		}

		assertNotNull(name + " is no longer in " + regionId + ".json", citizen);
		assertEquals(name + " pose", pose, citizen.getIdleAnimation());
		assertEquals(name + " keeps the examine text it was authored with",
			examine, citizen.getExamineText());
	}

	private static List<EntityDefinition> shipped()
	{
		RegionDataLoader loader = new RegionDataLoader(TestGson.injected());
		List<EntityDefinition> out = new ArrayList<>();

		for (int regionId : ShippedRegions.ids())
		{
			RegionDefinition region = loader.loadRegion(regionId);
			assertNotNull("region " + regionId + " failed to load", region);
			out.addAll(region.getEntities());
		}

		return out;
	}
}

package com.matthewmariner.livelycities;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import javax.annotation.Nullable;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The hidden config string that stands in for the dynamic checkbox list RuneLite
 * does not have.
 *
 * <p>Its whole job is a round trip through a string, so that is what is tested:
 * write, read back, parse, and still hold the same uuids. Nothing here uses a
 * {@code Set<UUID>} field to short-circuit the serialisation, because the
 * serialisation is the only part that can be wrong.
 */
public class UuidSettingTest
{
	private static final String KEY = "hiddenCitizens";

	private static final UUID ONE = UUID.fromString("00000000-0000-4000-8000-000000000001");
	private static final UUID TWO = UUID.fromString("00000000-0000-4000-8000-000000000002");
	private static final UUID THREE = UUID.fromString("00000000-0000-4000-8000-000000000003");

	/**
	 * The store, and a record of every write.
	 *
	 * <p>The write log matters as much as the value: "a write that would produce the
	 * same string is skipped" is a real requirement — {@code ConfigManager} posts a
	 * {@code ConfigChanged} per write and this plugin answers each one with a full
	 * visibility pass — and it is invisible unless the writes are counted.
	 */
	private static final class Store
	{
		@Nullable
		private String value;

		private final List<String> writes = new ArrayList<>();

		private ConfigWriter writer()
		{
			return (key, newValue) ->
			{
				assertEquals("it must only ever write its own key", KEY, key);
				value = newValue;
				writes.add(String.valueOf(newValue));
			};
		}

		@Nullable
		private String read()
		{
			return value;
		}
	}

	@Test
	public void aUuidSurvivesTheRoundTripThroughTheString()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		assertTrue(setting.add(ONE));
		assertEquals("the stored form is the canonical uuid string",
			ONE.toString(), store.read());

		// A second instance reading the same string is the real test: it has never
		// seen the add, so everything it knows came out of the bytes.
		UuidSetting reloaded = new UuidSetting(KEY, store::read, store.writer());
		assertTrue("a fresh reader has to find it", reloaded.contains(ONE));
		assertEquals(1, reloaded.size());
	}

	@Test
	public void severalUuidsRoundTripAndKeepTheirOrder()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		setting.add(ONE);
		setting.add(TWO);
		setting.add(THREE);

		assertEquals(ONE + "," + TWO + "," + THREE, store.read());

		UuidSetting reloaded = new UuidSetting(KEY, store::read, store.writer());
		assertEquals(3, reloaded.size());
		assertTrue(reloaded.contains(TWO));
	}

	/**
	 * A profile can be hand-edited, synced from another install, or written by a
	 * later version. One bad character must not lose every hide the user ever set,
	 * and must certainly not throw inside a visibility pass that runs every tick.
	 */
	@Test
	public void junkBetweenTheCommasIsDroppedAndTheRestSurvives()
	{
		Store store = new Store();
		store.value = "  " + ONE + " ,not-a-uuid,, " + TWO + ",42,";

		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		assertEquals("both real uuids, neither of the three junk entries", 2, setting.size());
		assertTrue(setting.contains(ONE));
		assertTrue(setting.contains(TWO));
		assertTrue("reading must not rewrite the setting", store.writes.isEmpty());
	}

	@Test
	public void anAbsentOrEmptyStringIsAnEmptySet()
	{
		Store absent = new Store();
		assertEquals(0, new UuidSetting(KEY, absent::read, absent.writer()).size());

		Store blank = new Store();
		blank.value = "   ";
		assertEquals(0, new UuidSetting(KEY, blank::read, blank.writer()).size());
	}

	/**
	 * Clearing unsets the key rather than writing the empty string. A key left in
	 * the profile reads as a user override forever; "the user has no setting here"
	 * is the honest end state for a button.
	 */
	@Test
	public void clearingUnsetsTheKey()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());
		setting.add(ONE);
		setting.add(TWO);

		assertTrue(setting.clear());
		assertNull("cleared means unset, not the empty string", store.read());
		assertEquals(0, setting.size());
		assertFalse(setting.contains(ONE));

		assertFalse("clearing an empty set writes nothing", setting.clear());
		assertEquals("so there is exactly one write for the two adds' worth of state",
			3, store.writes.size());
	}

	/**
	 * Adding the same uuid twice must not write twice. Every write posts a
	 * {@code ConfigChanged}, and this plugin answers each one by re-running the
	 * visibility pass over every entity in scope.
	 */
	@Test
	public void addingAUuidTwiceWritesOnce()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		assertTrue(setting.add(ONE));
		assertFalse("the second add is a no-op", setting.add(ONE));
		assertEquals(1, store.writes.size());
		assertEquals(1, setting.size());
	}

	/**
	 * The parse is cached, and the cache has to notice the string changing
	 * underneath it — which is what happens when another instance writes, or when
	 * the user switches profile.
	 */
	@Test
	public void theCacheNoticesTheStringChangingUnderneathIt()
	{
		Store store = new Store();
		UuidSetting reader = new UuidSetting(KEY, store::read, store.writer());
		assertEquals(0, reader.size());

		// Somebody else writes. The reader has already parsed once, so this is the
		// case a naive "parse on first use" cache gets wrong.
		store.value = ONE + "," + TWO;
		assertEquals("the cache must re-parse when the value changes", 2, reader.size());

		store.value = null;
		assertEquals("including all the way back to nothing", 0, reader.size());
	}

	// --- taking one back out -------------------------------------------------

	/**
	 * Removing one uuid keeps the others, and keeps them through the string.
	 *
	 * <p>The whole reason {@code remove} exists: until the side panel there was only
	 * {@link UuidSetting#clear()}, so taking back one decision meant losing every other
	 * one. The assertion that matters is the second one — that the two who were not
	 * named are still there <b>after a re-parse</b>, which is where a remove that
	 * rewrote the string wrongly would show up. A fresh {@code UuidSetting} over the
	 * same store is what forces that re-parse; asking the same instance would be asking
	 * its primed cache.
	 */
	@Test
	public void removingOneKeepsTheRestThroughTheString()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		setting.add(ONE);
		setting.add(TWO);
		setting.add(THREE);

		assertTrue("TWO was in the set", setting.remove(TWO));
		assertEquals(2, setting.size());

		UuidSetting reread = new UuidSetting(KEY, store::read, store.writer());
		assertEquals("and the string it wrote holds the other two", 2, reread.size());
		assertTrue(reread.contains(ONE));
		assertFalse(reread.contains(TWO));
		assertTrue(reread.contains(THREE));
	}

	/**
	 * Removing a uuid that is not there writes nothing.
	 *
	 * <p>The same rule {@code add} keeps in the other direction, and for the same
	 * reason: {@code ConfigManager} posts a {@code ConfigChanged} per write and this
	 * plugin answers each one with a full visibility pass over every entity in scope, so
	 * a write that changes no bytes is a pass over a hundred citizens for nothing.
	 */
	@Test
	public void removingSomebodyWhoIsNotThereWritesNothing()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		setting.add(ONE);
		int writesBefore = store.writes.size();

		assertFalse(setting.remove(TWO));
		assertEquals("no write", writesBefore, store.writes.size());
		assertEquals(1, setting.size());

		assertFalse("nor on an empty set",
			new UuidSetting("mutedCitizens", () -> null, (key, value) ->
			{
				throw new AssertionError("an empty set must not be written to");
			}).remove(ONE));
	}

	/**
	 * Removing the last one unsets the key rather than storing an empty string.
	 *
	 * <p>{@link ConfigWriter}'s contract: a key left in the profile reads as a user
	 * override forever, and "the user has no setting here" is the honest end state.
	 * {@code clear()} already did this; {@code remove()} reaching the same state by a
	 * different route has to leave the profile in the same place, or a user who
	 * restored their citizens one at a time would end up with a profile subtly unlike
	 * one who pressed the button.
	 */
	@Test
	public void removingTheLastOneUnsetsTheKey()
	{
		Store store = new Store();
		UuidSetting setting = new UuidSetting(KEY, store::read, store.writer());

		setting.add(ONE);
		assertEquals(String.valueOf(ONE), store.read());

		assertTrue(setting.remove(ONE));
		assertNull("an empty set is stored as no setting at all", store.read());
		assertEquals("null", store.writes.get(store.writes.size() - 1));
		assertEquals(0, setting.size());
	}
}

package com.matthewmariner.livelycities;

import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * Runs enough visibility passes for a fixture's crowd to finish arriving.
 *
 * <p><b>Why this exists.</b> {@link RenderPolicy#MAX_MODEL_BUILDS_PER_PASS} caps a
 * single pass at three model builds, so "spawn five citizens and look at them" is no
 * longer one pass — it is two. That is the point of the cap and not an inconvenience:
 * the measured 53.73ms visibility spike was forty models built inside one game tick.
 * Twenty-four tests in this suite were written against the old behaviour, and every one
 * of them is about something else — teardown, eviction, city checkboxes, the crowd cap,
 * clickboxes. This is how they say "a few game ticks pass" without each one growing its
 * own loop.
 *
 * <p><b>What it is not.</b> It is not a way to make the budget invisible. It changes
 * <i>when</i> a citizen appears and never <i>whether</i> — so a test that used it to
 * paper over an entity that never spawns would still be red, because the assertion
 * after it is unchanged. Any test that is <i>about</i> the budget must not call this:
 * it has to drive the passes itself and count them, or it is asserting about the helper
 * instead of about the cap. {@code EntitySceneTest}'s budget block and
 * {@code FrameTimingsTest}'s do exactly that.
 *
 * <p><b>A fixed count rather than "until it stops changing."</b> Converging on a stable
 * active count sounds tidier and is a trap: a pass whose three builds all failed leaves
 * the count unchanged too, so a convergence loop would stop early on precisely the
 * fixture where stopping early is wrong, and would report a half-built crowd as a
 * settled one. The count below is derived from the two constants that bound the wait,
 * so it cannot rot if either moves.
 */
final class VisibilityPasses
{
	/**
	 * How many passes a full cap's worth of models needs: {@code ceil(80 / 3) + 1} = 28.
	 *
	 * <p>The ceiling covers the crowd, and the extra pass is the one that has nothing
	 * left to build — so a fixture that is genuinely finished is finished with a pass to
	 * spare, and this never depends on the division coming out even.
	 */
	static final int PASSES_TO_SETTLE =
		1 + (RenderPolicy.MAX_ACTIVE_OBJECTS + RenderPolicy.MAX_MODEL_BUILDS_PER_PASS - 1)
			/ RenderPolicy.MAX_MODEL_BUILDS_PER_PASS;

	private VisibilityPasses()
	{
	}

	/**
	 * Runs {@link #PASSES_TO_SETTLE} visibility passes, which is enough for every model
	 * a full crowd needs to have been built.
	 *
	 * <p>{@code updateVisibility} rather than {@code onGameTick}: this stands in for the
	 * passage of ticks as far as <i>spawning</i> is concerned, and a caller that also
	 * wanted its wanderers to have walked twenty-eight tiles would be asking for
	 * something else.
	 */
	static void settle(EntityScene scene, WorldPoint player, WorldView view)
	{
		for (int i = 0; i < PASSES_TO_SETTLE; i++)
		{
			scene.updateVisibility(player, view);
		}
	}

	/**
	 * The same wait, driven through whatever a caller uses to advance a tick — the
	 * plugin's own {@code GameTick} handler, for the tests that go through the plugin
	 * rather than straight at the scene.
	 */
	static void settle(Runnable oneTick)
	{
		for (int i = 0; i < PASSES_TO_SETTLE; i++)
		{
			oneTick.run();
		}
	}
}
